// Hyperrealistic Watercolour & Pencil: Staffordshire Porcelain Spaniel in Bubble Wrap
// p5.js 2.x + p5.brush (WEBGL)

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42891);
  noiseSeed(19403);

  // Custom brushes for watercolour glazing, sharp pencil fluting, matte tape, and opaque white pen dots
  brush.add("glaze_soft", {
    type: "default",
    weight: 4.5,
    scatter: 0.35,
    sharpness: 0.15,
    grain: 6,
    opacity: 38,
    spacing: 0.25,
    pressure: [0.3, 1.0, 0.3],
    rotate: "natural",
    noise: 0.3
  });

  brush.add("lens_stroke", {
    type: "default",
    weight: 2.2,
    scatter: 0.12,
    sharpness: 0.45,
    grain: 8,
    opacity: 85,
    spacing: 0.18,
    pressure: [0.2, 1.15, 0.2],
    rotate: "natural",
    noise: 0.2
  });

  brush.add("graphite_sharp", {
    type: "default",
    weight: 0.55,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 18,
    opacity: 185,
    spacing: 0.12,
    pressure: [0.6, 1.0, 0.5],
    rotate: "natural",
    noise: 0.45
  });

  brush.add("white_pen", {
    type: " custom" === "custom" ? "default" : "default",
    weight: 1.6,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 2,
    opacity: 250,
    spacing: 0.08,
    pressure: [0.95, 1.0, 0.85],
    rotate: "none",
    noise: 0.05
  });

  brush.add("matte_scuff", {
    type: "default",
    weight: 3.0,
    scatter: 0.6,
    sharpness: 0.25,
    grain: 14,
    opacity: 42,
    spacing: 0.3,
    pressure: [0.2, 0.9, 0.2],
    rotate: "random",
    noise: 0.5
  });
}

// ---------------------------------------------------------------------------
// SCENE GEOMETRY & UNDERLYING STAFFORDSHIRE SPANIEL OPTICAL MAP
// ---------------------------------------------------------------------------

// Helper: smoothstep
function sstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

// Helper: distance from point to segment
function distToSeg(px, py, x1, y1, x2, y2) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let l2 = dx * dx + dy * dy;
  if (l2 === 0) return dist(px, py, x1, y1);
  let t = constrain(((px - x1) * dx + (py - y1) * dy) / l2, 0, 1);
  return dist(px, py, x1 + t * dx, y1 + t * dy);
}

// Helper: point in polygon
function ptInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / (yj - yi + 0.00001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

// Tape polygons (taped seams that stay matte)
const TAPE_SEAM_1 = [
  [210, 745], [965, 515], [990, 595], [235, 825]
];
const TAPE_SEAM_2 = [
  [795, 295], [1145, 675], [1082, 732], [735, 348]
];

function isUnderTape(x, y) {
  return ptInPoly(x, y, TAPE_SEAM_1) || ptInPoly(x, y, TAPE_SEAM_2);
}

// Bubble wrap boundary across the spaniel's cheek & ear
function getWrapTopY(x) {
  // Sweeps from left cardboard across muzzle, middle of glazed cheek, dipped at gilt collar peek, up over right ear
  let base = 515 - 0.08 * (x - 200);
  // Rise over the glazed cheek (x: 380..540) so cheek is half-swaddled
  let cheekBump = -42 * exp(-pow((x - 455) / 85, 2));
  // Slight dip around x=575 where a glimpse of gilt collar and ear tip shows, then rises over right flap
  let collarDip = 36 * exp(-pow((x - 585) / 55, 2));
  let rightRise = -65 * sstep(620, 920, x);
  let wave = 10 * sin(x * 1.4) + 6 * cos(x * 2.7);
  return base + cheekBump + collarDip + rightRise + wave;
}

// Sample the underlying Staffordshire Spaniel & Box for optical lens refraction
// Returns an object describing the exact colour, feature type, and contrast at (x, y)
function sampleUnderlyingScene(x, y) {
  // Check if inside the spaniel body silhouette
  // Head & ears region + chest & torso region
  let inHead = dist(x, y, 470, 415) < 185;
  let inSnout = dist(x, y, 375, 455) < 98;
  let inLeftEar = dist(x, y, 305, 495) < 105;
  let inRightEar = dist(x, y, 605, 410) < 125;
  let inNeck = dist(x, y, 495, 565) < 165;
  let inChest = dist(x, y, 585, 740) < 235;
  let inFlank = dist(x, y, 790, 810) < 220;
  let inPaws = dist(x, y, 490, 910) < 155;

  let onDog = inHead || inSnout || inLeftEar || inRightEar || inNeck || inChest || inFlank || inPaws;

  if (!onDog) {
    // Kraft cardboard or packing paper background
    let dFold = distToSeg(x, y, 140, 620, 420, 1080);
    if (dFold < 45) {
      return {
        type: "cardboard_shadow",
        col1: "#7a532e",
        col2: "#593b1f",
        accent: "#b5834a",
        angle: -35,
        contrast: 0.65
      };
    }
    return {
      type: "cardboard",
      col1: "#be8a4f",
      col2: "#9e6b34",
      accent: "#d8ad78",
      angle: -14,
      contrast: 0.45
    };
  }

  // 1. GILT COLLAR (sweeping curve across neck from (345,545) through (485,568) to (640,505))
  let collarY = 552 + 24 * sin((x - 340) * 0.65) - 0.16 * (x - 450);
  let dCollar = abs(y - collarY);
  if (x > 335 && x < 648 && dCollar < 26) {
    return {
      type: "gilt_collar",
      col1: "#e3ab2b", // gleaming gold
      col2: "#9e5c11", // deep raw sienna / burnished gold shadow
      accent: "#fff5c0", // bright gilt specular
      darkRim: "#4d2c08",
      angle: -18,
      contrast: 1.0
    };
  }

  // 2. GILT PADLOCK / LOCKET & CHAIN (hanging from collar at (485, 608) and draping to (700, 685))
  let dLocket = dist(x, y, 485, 612);
  let dChain1 = distToSeg(x, y, 485, 612, 585, 685);
  let dChain2 = distToSeg(x, y, 585, 685, 725, 650);
  let dChain3 = distToSeg(x, y, 445, 575, 430, 720);
  if (dLocket < 30 || dChain1 < 16 || dChain2 < 16 || dChain3 < 14) {
    return {
      type: "gilt_chain",
      col1: "#d89c22",
      col2: "#7d450d",
      accent: "#ffefb0",
      darkRim: "#3e2206",
      angle: dChain1 < 16 ? 32 : -15,
      contrast: 0.98
    };
  }

  // 3. GLAZED CHEEK & WARM ROSY-SIENNA BLUSH (around (455, 468))
  let dCheek = dist(x, y, 462, 468);
  if (dCheek < 72) {
    return {
      type: "glazed_cheek",
      col1: "#d97848", // warm glazed terracotta-sienna blush
      col2: "#f5efe2", // glossy bone-white porcelain
      accent: "#b85527", // deeper raw/burnt sienna glaze
      darkRim: "#7d8c96", // cool porcelain turn shadow
      angle: -22,
      contrast: 0.88
    };
  }

  // 4. MUZZLE & NOSE / LIP LINE (around (375, 455))
  let dMuzzle = dist(x, y, 375, 465);
  if (dMuzzle < 68) {
    return {
      type: "muzzle",
      col1: "#c96638",
      col2: "#f2ead9",
      accent: "#5e2a18",
      darkRim: "#854224",
      angle: 15,
      contrast: 0.82
    };
  }

  // 5. RUFOUS / RAW SIENNA & COPPER-LUSTRE PATCHES (ears, shoulder, flank spots)
  let dLeftEarPatch = dist(x, y, 305, 505);
  let dRightEarPatch = dist(x, y, 608, 425);
  let dShoulderPatch = dist(x, y, 695, 585);
  let dFlankPatch = dist(x, y, 815, 760);
  let dChestSpot = dist(x, y, 540, 775);

  if (
    dLeftEarPatch < 88 ||
    dRightEarPatch < 98 ||
    dShoulderPatch < 82 ||
    dFlankPatch < 92 ||
    dChestSpot < 48
  ) {
    return {
      type: "sienna_patch",
      col1: "#b85620", // rich burnt/raw sienna glaze
      col2: "#cf7b32", // glowing raw sienna
      accent: "#782b0d", // deep iron-red curl trough
      darkRim: "#f2ecde", // adjacent bone-white porcelain
      angle: -30,
      contrast: 0.85
    };
  }

  // 6. BONE-WHITE GLAZED PORCELAIN WITH MOLDED CHEST CURLS & COOL POLYTHENE SHADOWS
  let curlWave = sin(x * 0.09 + y * 0.07) * cos(x * 0.05 - y * 0.08);
  return {
    type: "bone_porcelain",
    col1: "#f4efe2", // bone white
    col2: curlWave > 0 ? "#8a99a4" : "#c79252", // cool polythene grey or warm raw sienna reflection
    accent: "#ffffff",
    darkRim: "#6c7b86",
    angle: -12 + curlWave * 35,
    contrast: 0.65
  };
}

// ---------------------------------------------------------------------------
// MAIN DRAW FUNCTION
// ---------------------------------------------------------------------------

function draw() {
  translate(-width / 2, -height / 2);

  // Warm heavy cotton watercolour paper ground
  background("#f6f1e5");

  // 1. First Transparent Watercolour Washes (Cardboard Box & Background Tone)
  drawBackgroundWashes();

  // 2. Crumpled Kraft Paper & Inner Box Flaps
  drawBoxInteriorDetails();

  // 3. The Staffordshire Porcelain Spaniel (Unwrapped Upper Head, Eye, Ear Curls & Under-painting)
  drawPorcelainSpaniel();

  // 4. Translucent Polythene Base Washes over the Bubble-Wrap Swaddle
  drawBubbleWrapBaseGlazes();

  // 5. Generate & Render the Optical Air Domes (Magnifying, Splitting & Doubling Lens Cells)
  let domes = generateBubbleDomes();
  drawOpticalBubbleDomes(domes);

  // 6. Matte Taped Seams (Translucent Buff Packing Tape Muting the Domes Underneath)
  drawMatteTapedSeams();

  // 7. Corrugated Cardboard Box Edges in Sharp Pencil (Fluted Sinusoidal Wave + Liners)
  drawCorrugatedCardboardEdges();

  // 8. Crisp Opaque White Pen Dots on Every Un-taped Air Dome & Porcelain Speculars
  drawOpaqueWhiteHighlights(domes);

  noLoop();
}

// ---------------------------------------------------------------------------
// PHASE 1: TRANSPARENT WATERCOLOUR GROUND & KRAFT CARDBOARD WASHES
// ---------------------------------------------------------------------------

function drawBackgroundWashes() {
  brush.noStroke();

  // Batch 1: Pale warm raw sienna & bone wash across the whole sheet
  brush.fill("#e8d5b5", 52);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.3);
  brush.rect(30, 30, 1140, 1140, "corner");

  // Batch 2: Kraft-brown cardboard walls (tilted off-axis moving box)
  let kraftPolys = [
    // Upper left cardboard wall
    [[-20, 260], [685, 65], [650, 380], [180, 560], [-20, 490]],
    // Right cardboard wall
    [[685, 65], [1180, 860], [920, 980], [610, 360]],
    // Lower left box floor & inner flap
    [[-20, 480], [360, 490], [540, 1220], [-20, 1220]],
    // Lower right box floor
    [[620, 780], [1180, 760], [1220, 1220], [480, 1220]]
  ];

  brush.fill("#c58b4e", 82);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.42);
  for (let poly of kraftPolys) {
    drawFilledPoly(poly);
  }

  // Batch 3: Deeper raw sienna & warm umber shadow glazes in the box corners
  let shadowPolys = [
    // Deep corner behind dog's head
    [[540, 110], [685, 65], [760, 290], [510, 310]],
    // Deep shadow pocket to the left of the dog's ear
    [[110, 340], [325, 295], [310, 640], [95, 590]],
    // Shadow under the bubble wrap on the bottom left
    [[140, 680], [420, 740], [490, 1150], [160, 1080]],
    // Shadow under the right side of the dog
    [[740, 430], [960, 520], [890, 890], [680, 790]]
  ];

  brush.fill("#8c5828", 78);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.7, 0.48);
  for (let poly of shadowPolys) {
    drawFilledPoly(poly);
  }

  // Batch 4: Cool polythene grey-blue ambient shadow wash in the deep folds
  let coolShadowPolys = [
    [[155, 420], [295, 380], [275, 595], [140, 560]],
    [[640, 130], [720, 115], [710, 320], [605, 285]],
    [[310, 850], [560, 890], [520, 1160], [260, 1090]]
  ];

  brush.fill("#667580", 62);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.6, 0.35);
  for (let poly of coolShadowPolys) {
    drawFilledPoly(poly);
  }

  brush.noFill();
}

function drawFilledPoly(pts, curvature = 0.08) {
  brush.beginShape(curvature);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

// ---------------------------------------------------------------------------
// PHASE 2: BOX INTERIOR CREASES & CRUMPLED KRAFT PACKING PAPER
// ---------------------------------------------------------------------------

function drawBoxInteriorDetails() {
  // Subtle ribbed kraft liner texture in the cardboard background
  brush.hatchStyle("2H", "#8f6334", 0.55);
  brush.hatch(9, -14, { rand: 0.08 });
  brush.noStroke();
  drawFilledPoly([[60, 240], [670, 80], [620, 290], [110, 430]], 0.02);
  brush.noHatch();

  brush.hatchStyle("2H", "#82582c", 0.55);
  brush.hatch(9, 76, { rand: 0.08 });
  brush.noStroke();
  drawFilledPoly([[690, 85], [1080, 710], [910, 760], [640, 290]], 0.02);
  brush.noHatch();

  // Box corner fold line descending from (682, 75) into the box behind the spaniel
  brush.set("HB", "#54381c", 1.1);
  brush.line(682, 75, 588, 315);
  brush.set("2B", "#3d2711", 0.8);
  brush.line(685, 75, 592, 315);

  // Crumpled kraft paper facets around the top-left and bottom-left of the dog
  let paperFacets = [
    { pts: [[160, 360], [310, 300], [335, 430], [195, 470]], col: "#d6a972", op: 75 },
    { pts: [[125, 475], [275, 445], [260, 610], [115, 585]], col: "#a8733b", op: 80 },
    { pts: [[310, 240], [495, 195], [460, 295], [295, 315]], col: "#cfa068", op: 70 },
    { pts: [[510, 185], [640, 210], [595, 315], [465, 285]], col: "#9e6a35", op: 78 }
  ];

  brush.noStroke();
  for (let f of paperFacets) {
    brush.fill(f.col, f.op);
    brush.fillBleed(0.15, "out");
    brush.fillTexture(0.5, 0.4);
    drawFilledPoly(f.pts, 0.05);
  }
  brush.noFill();

  // Crisp angular crease lines on the packing paper
  brush.set("HB", "#6b441e", 0.75);
  brush.spline([[160, 360], [265, 410], [335, 430]], 0.2);
  brush.spline([[275, 445], [220, 520], [260, 610]], 0.25);
  brush.spline([[310, 240], [415, 275], [595, 315]], 0.2);
}

// ---------------------------------------------------------------------------
// PHASE 3: THE STAFFORDSHIRE PORCELAIN SPANIEL
// ---------------------------------------------------------------------------

function drawPorcelainSpaniel() {
  brush.noStroke();

  // 1. Bone-white porcelain reserve wash for the spaniel's head, snout, ears & chest
  let porcelainBody = [
    [335, 275], [455, 235], [575, 255], [675, 345],
    [710, 485], [885, 620], [915, 845], [745, 965],
    [455, 955], [345, 760], [265, 555], [285, 385]
  ];
  brush.wash("#fbf8f0", 225);
  drawFilledPoly(porcelainBody, 0.25);
  brush.noWash();

  // Soft warm bone-white watercolour glaze over the porcelain form
  brush.fill("#f2ead9", 95);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.42, 0.25);
  drawFilledPoly(porcelainBody, 0.25);

  // 2. Sculptural porcelain shading on the unwrapped head, snout & cheek (cool polythene grey + raw sienna)
  let headShadows = [
    // Eye socket & bridge of snout turn
    [[375, 360], [455, 355], [440, 435], [355, 425]],
    // Under the brow ridge & temple
    [[475, 285], [555, 305], [545, 415], [485, 395]],
    // Lower cheek turn (passing under the bubble wrap)
    [[415, 465], [545, 455], [565, 545], [395, 545]],
    // Sculpted chest ruff hollows (under wrap)
    [[425, 615], [615, 595], [645, 755], [410, 765]]
  ];
  brush.fill("#8c9aa4", 68);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.5, 0.3);
  for (let s of headShadows) {
    drawFilledPoly(s, 0.3);
  }

  // 3. Classic Staffordshire Raw Sienna & Burnt Sienna / Copper-Lustre Markings
  // (Both unwrapped upper ear/crown/cheek AND under-painted body patches that will refract through domes)
  let siennaPatches = [
    // Crown spot on top of forehead
    [[405, 255], [475, 245], [485, 305], [395, 310]],
    // Left Ear (cascading curls on viewer's left)
    [[285, 345], [355, 330], [358, 565], [265, 550]],
    // Right Ear (grand cascading curls on viewer's right)
    [[530, 265], [645, 295], [690, 485], [555, 505]],
    // Shoulder patch (under bubble wrap)
    [[635, 520], [775, 535], [785, 665], [625, 645]],
    // Flank patch (under bubble wrap)
    [[735, 705], [895, 725], [885, 865], [725, 845]],
    // Chest spot (under bubble wrap)
    [[495, 730], [585, 735], [575, 825], [485, 815]]
  ];

  // First glaze: Luminous Raw Sienna
  brush.fill("#cf7e2e", 115);
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.62, 0.45);
  for (let p of siennaPatches) {
    drawFilledPoly(p, 0.32);
  }

  // Second glaze: Rich Iron-Red / Burnt Sienna core in the ear curls and patches
  let deepSiennaCores = [
    [[420, 262], [465, 258], [468, 295], [412, 298]],
    [[292, 375], [345, 365], [342, 535], [278, 520]],
    [[550, 290], [635, 315], [668, 465], [568, 475]],
    [[655, 540], [755, 555], [758, 640], [645, 625]],
    [[755, 725], [865, 745], [855, 840], [745, 820]]
  ];
  brush.fill("#9e3914", 110);
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.68, 0.52);
  for (let p of deepSiennaCores) {
    drawFilledPoly(p, 0.35);
  }

  // 4. Glazed Cheek Blush & Muzzle Warmth (Crucial: Half-swaddled by the bubble wrap!)
  let cheekBlush = [
    [418, 428], [505, 425], [522, 502], [412, 505]
  ];
  brush.fill("#d97448", 95);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.45, 0.25);
  drawFilledPoly(cheekBlush, 0.4);

  // Muzzle blush
  let muzzleBlush = [
    [335, 415], [405, 412], [412, 488], [330, 480]
  ];
  brush.fill("#cf6e42", 85);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.45, 0.25);
  drawFilledPoly(muzzleBlush, 0.4);

  // 5. The Gilt Collar, Padlock Locket & Chain (Under-painted + Peek Zone)
  let giltCollarPoly = [
    [340, 532], [485, 548], [642, 488],
    [650, 518], [488, 582], [335, 562]
  ];
  brush.fill("#e0a624", 150);
  brush.fillBleed(0.1, "in");
  brush.fillTexture(0.55, 0.5);
  drawFilledPoly(giltCollarPoly, 0.2);

  // Gilt padlock & chain under-painting
  let locketPoly = [
    [462, 585], [508, 588], [512, 642], [485, 658], [458, 638]
  ];
  drawFilledPoly(locketPoly, 0.25);

  brush.noFill();

  // 6. Sculpted Baroque Ear Curls (Unwrapped upper parts of Left & Right Ears)
  drawUnwrappedEarCurls();

  // 7. Hand-Painted Staffordshire Spaniel Face (Eyes, Nose, Mouth, Cheek Glaze & Crazing)
  drawSpanielFacialFeatures();

  // 8. Detailed Gilt Collar Segment Peeking Out at the Wrap Fold (x: 545..635)
  drawUnwrappedGiltCollarPeek();
}

function drawUnwrappedEarCurls() {
  // Deep umber & burnt sienna curl troughs on the unwrapped right ear (y < 455)
  let rightCurls = [
    [[542, 285], [585, 275], [612, 308], [582, 335], [548, 322]],
    [[585, 312], [632, 308], [652, 348], [615, 372], [578, 355]],
    [[552, 348], [598, 345], [618, 385], [582, 412], [548, 392]],
    [[598, 378], [648, 372], [668, 415], [632, 442], [595, 422]],
    [[558, 412], [605, 408], [622, 445], [588, 468], [555, 448]]
  ];

  for (let c of rightCurls) {
    brush.set("glaze_soft", "#6e2209", 1.1);
    brush.spline(c, 0.55);
    // Warm raw sienna highlight rim next to trough
    brush.set("glaze_soft", "#e39b4b", 0.8);
    brush.spline([c[0], c[1], c[2]], 0.5);
  }

  // Left ear upper curls (y < 495)
  let leftCurls = [
    [[295, 355], [335, 345], [348, 382], [315, 405], [285, 390]],
    [[285, 402], [328, 395], [342, 435], [308, 458], [278, 442]],
    [[282, 452], [325, 448], [338, 485], [302, 502], [275, 488]]
  ];
  for (let c of leftCurls) {
    brush.set("glaze_soft", "#631e07", 1.05);
    brush.spline(c, 0.55);
    brush.set("glaze_soft", "#dc9041", 0.75);
    brush.spline([c[0], c[1], c[2]], 0.5);
  }
}

function drawSpanielFacialFeatures() {
  // --- RIGHT EYE (Prominent, around (478, 382)) ---
  // White scleral porcelain mound
  brush.noStroke();
  brush.wash("#fcfaf2", 220);
  brush.circle(478, 382, 22, 0.15);
  brush.noWash();

  // Golden-amber iris painted rim
  brush.fill("#c47520", 165);
  brush.fillBleed(0.08, "in");
  brush.circle(476, 383, 14, 0.1);
  brush.noFill();

  // Dark sepia-black pupil
  brush.wash("#1e1512", 240);
  brush.circle(475, 383, 9.5, 0.08);
  brush.noWash();

  // Characteristic Staffordshire feathered upper eyelid & brow lash line
  brush.set("pen", "#241712", 1.35);
  brush.spline([[446, 382], [462, 366], [484, 365], [504, 379], [512, 388]], 0.45);
  // Lower lid line
  brush.set("pen", "#5c3824", 0.85);
  brush.spline([[450, 385], [475, 397], [502, 386]], 0.4);

  // Molded upper eyelid crease
  brush.set("HB", "#75604e", 0.8);
  brush.spline([[444, 370], [472, 353], [506, 368]], 0.45);

  // Expressive painted Staffordshire brow arch
  brush.set("glaze_soft", "#943b18", 0.85);
  brush.spline([[448, 345], [478, 334], [512, 348]], 0.45);

