// ---------------------------------------------------------------------------
// PHASE 5: OPTICAL AIR DOMES (EVERY DOME ITS OWN SMALL LENS)
// ---------------------------------------------------------------------------

function generateBubbleDomes() {
  let domes = [];
  let spacingX = 52;
  let spacingY = 45;

  // Hexagonal grid warped over the 3D contour of the swaddled spaniel and box folds
  for (let row = 0; row < 16; row++) {
    for (let col = 0; col < 18; col++) {
      let gx = 125 + col * spacingX + (row % 2) * (spacingX * 0.5);
      let gy = 410 + row * spacingY;

      // Apply 3D surface drape & fold warp
      let dogDist = dist(gx, gy, 535, 650);
      let bulge = 18 * exp(-pow(dogDist / 260, 2));
      let foldWaveX = 9 * sin(gy * 0.85 + gx * 0.35);
      let foldWaveY = 11 * cos(gx * 0.75 - gy * 0.45);

      let cx = gx + foldWaveX - bulge * 0.3;
      let cy = gy + foldWaveY - bulge * 0.6;

      // Keep inside the bubble-wrap region and inside the box walls
      let topBound = getWrapTopY(cx) + 24;
      if (cy < topBound) continue;

      // Clip against cardboard box boundaries
      // Left inner flap edge: line from (-30, 720) to (490, 1230) -> y > 720 + (x+30)*0.98
      if (cy > 695 + (cx + 10) * 0.96) continue;
      // Right cardboard wall edge: line from (685, 75) to (1160, 880) -> x > 685 + (y-75)*0.59
      if (cx > 665 + (cy - 75) * 0.56) continue;
      // Bottom frame margin
      if (cy > 1095 || cx < 115) continue;

      // Calculate local dome radius and foreshortening near folds
      let baseR = 21.5 + 2.5 * sin(row * 37 + col * 19);
      let nearTopEdge = constrain((cy - topBound) / 45, 0.55, 1.0);
      let r = baseR * (0.88 + 0.14 * nearTopEdge);

      let underTape = isUnderTape(cx, cy);
      let sceneSample = sampleUnderlyingScene(cx, cy);

      // Also sample slightly offset points to detect high-contrast boundaries (cheek edge, collar edge)
      let sampleA = sampleUnderlyingScene(cx - 14, cy - 12);
      let sampleB = sampleUnderlyingScene(cx + 14, cy + 12);

      domes.push({
        cx,
        cy,
        r,
        row,
        col,
        underTape,
        scene: sceneSample,
        sampleA,
        sampleB,
        nearTopEdge: (cy - topBound) < 38
      });
    }
  }

  // Add a row of profile/blister domes rising right along the top edge of the wrap
  for (let x = 165; x <= 915; x += 48) {
    let wy = getWrapTopY(x);
    if (x > 660 + (wy - 75) * 0.55) continue;
    let sceneSample = sampleUnderlyingScene(x, wy + 6);
    domes.push({
      cx: x,
      cy: wy + 8,
      r: 19,
      isEdgeDome: true,
      underTape: isUnderTape(x, wy + 8),
      scene: sceneSample,
      sampleA: sampleUnderlyingScene(x - 10, wy),
      sampleB: sampleUnderlyingScene(x + 10, wy + 14)
    });
  }

  return domes;
}

function drawOpticalBubbleDomes(domes) {
  // PASS 1: Base lens interior washes (grouped/drawn cleanly with wash & soft strokes)
  for (let d of domes) {
    let { cx, cy, r, scene, sampleA, sampleB, underTape } = d;

    // 1. Subtle inter-bubble polythene shadow ring (bottom-right cast shadow of air cell)
    brush.noStroke();
    brush.wash("#6d7e8a", underTape ? 32 : 55);
    brush.circle(cx + 3.5, cy + 4.0, r * 1.02, 0.12);

    // 2. Interior base tint of the dome (bone white, warm sienna, or cool polythene grey)
    let baseWashCol = scene.col2;
    let baseAlpha = underTape ? 65 : 105;
    if (scene.type === "gilt_collar" || scene.type === "gilt_chain") {
      baseWashCol = "#f3d88d";
      baseAlpha = underTape ? 85 : 135;
    } else if (scene.type === "glazed_cheek") {
      baseWashCol = "#f5e6d8";
      baseAlpha = underTape ? 80 : 125;
    } else if (scene.type === "sienna_patch") {
      baseWashCol = "#e3a668";
      baseAlpha = underTape ? 75 : 115;
    }
    brush.wash(baseWashCol, baseAlpha);
    brush.circle(cx, cy, r * 0.92, 0.1);
    brush.noWash();

    // 3. OPTICAL LENS MAGNIFICATION, SPLITTING & DOUBLING INSIDE EACH DOME!
    // Every air dome acts as a small spherical/cylindrical lens:
    // It splits the underlying feature into two curved meniscus crescents on opposite sides
    // of the cell and magnifies a shifted central fragment.

    let contrastMult = underTape ? 0.55 : 1.0;

    // (a) Magnified & shifted central lens blob
    brush.noStroke();
    brush.wash(scene.col1, floor(145 * contrastMult));
    brush.circle(cx - r * 0.14, cy - r * 0.1, r * 0.52, 0.18);
    brush.noWash();

    // (b) Split & Doubled Meniscus Arcs (Primary Feature Color: Gilt, Glazed Cheek Blush, or Sienna)
    brush.set("lens_stroke", scene.col1, 1.35 * contrastMult);
    // Upper-left refracted image arc
    brush.arc(cx, cy, r * 0.72, 195, 315);
    // Lower-right doubled/inverted image arc
    brush.set("lens_stroke", sampleB.col1, 1.25 * contrastMult);
    brush.arc(cx, cy, r * 0.78, 15, 135);

    // (c) High-contrast doubled detail for Gilt Collar, Locket, Chain & Glazed Cheek!
    if (
      scene.type === "gilt_collar" ||
      scene.type === "gilt_chain" ||
      sampleA.type === "gilt_collar" ||
      sampleB.type === "gilt_collar"
    ) {
      // Split gleaming gold band + dark burnished bronze edge doubled inside the dome
      brush.set("lens_stroke", "#4f2c06", 1.15 * contrastMult);
      brush.arc(cx - 2, cy - 1, r * 0.56, 175, 295);
      brush.arc(cx + 2, cy + 2, r * 0.84, 350, 110);

      brush.set("lens_stroke", "#f0b929", 1.65 * contrastMult);
      brush.arc(cx - 1, cy - 1, r * 0.44, 180, 305);
      brush.arc(cx + 1, cy + 1, r * 0.68, 5, 125);

      // Tiny split gold chain link / collar boss inside the lens
      if (!underTape) {
        brush.set("pen", "#fff3b8", 1.1);
        brush.arc(cx - 2, cy - 2, r * 0.38, 210, 275);
      }
    } else if (
      scene.type === "glazed_cheek" ||
      sampleA.type === "glazed_cheek" ||
      sampleB.type === "glazed_cheek" ||
      scene.type === "muzzle"
    ) {
      // Split rosy-sienna cheek glaze and glossy bone-white porcelain rim
      brush.set("lens_stroke", "#c95b2e", 1.4 * contrastMult);
      brush.arc(cx - 2, cy + 1, r * 0.58, 160, 285);
      brush.set("lens_stroke", "#e08558", 1.2 * contrastMult);
      brush.arc(cx + 2, cy - 1, r * 0.76, 340, 95);

      // Doubled bone-white porcelain curve inside cell
      brush.set("lens_stroke", "#fbf7ec", 1.3 * contrastMult);
      brush.arc(cx + 1, cy + 1, r * 0.45, 20, 155);
    } else if (scene.type === "sienna_patch" || sampleA.type === "sienna_patch") {
      // Split iron-red ear/body curl inside the dome
      brush.set("lens_stroke", "#7d280b", 1.3 * contrastMult);
      brush.arc(cx - 1, cy, r * 0.55, 185, 310);
      brush.set("lens_stroke", "#d47c2c", 1.25 * contrastMult);
      brush.arc(cx + 1, cy, r * 0.75, 10, 140);
    }

    // 4. Cool Polythene Grey Dome Sidewall Rim & Optical Ring
    brush.set("HB", "#5e707d", underTape ? 0.45 : 0.75);
    brush.arc(cx, cy, r * 0.96, 25, 165);
    brush.set("2H", "#8c9ca8", underTape ? 0.35 : 0.6);
    brush.arc(cx, cy, r * 0.96, 200, 340);
  }
}

// ---------------------------------------------------------------------------
// PHASE 6: MATTE TAPED SEAMS
// ---------------------------------------------------------------------------

function drawMatteTapedSeams() {
  // Directive: "Taped seams stay matte."
  // Render the two wide strips of translucent buff/raw-sienna packing tape over the bubble wrap.
  brush.noStroke();

  let tapeStrips = [TAPE_SEAM_1, TAPE_SEAM_2];

  for (let strip of tapeStrips) {
    // 1. Opaque-ish matte warm buff wash to flatten and mute the glossy domes underneath
    brush.wash("#e3cfa8", 145);
    drawFilledPoly(strip, 0.02);
    brush.noWash();

    // 2. Watercolour raw sienna / warm grey matte glaze with zero bleed
    brush.fill("#cbb082", 68);
    brush.fillBleed(0.02, "in");
    brush.fillTexture(0.35, 0.45);
    drawFilledPoly(strip, 0.02);
    brush.noFill();
  }

  // 3. Matte surface scuffing & transverse adhesive tension wrinkles in dry pencil
  // Seam 1: from (210, 745) to (965, 515)
  brush.set("2H", "#9e845c", 0.55);
  brush.line(210, 745, 965, 515);
  brush.line(235, 825, 990, 595);

  // Serrated tape dispenser cut edges at both ends of Seam 1
  drawSerratedTapeEnd(210, 745, 235, 825, 9);
  drawSerratedTapeEnd(965, 515, 990, 595, 9);

  // Transverse matte tension creases across Seam 1
  for (let t = 0.08; t < 0.94; t += 0.09) {
    let x1 = lerp(210, 965, t);
    let y1 = lerp(745, 515, t);
    let x2 = lerp(235, 990, t + 0.015);
    let y2 = lerp(825, 595, t + 0.015);
    brush.set("2H", "#b0966e", 0.5);
    brush.line(x1, y1, x2, y2);
    brush.set("matte_scuff", "#efe4ce", 0.65);
    brush.line(x1 + 3, y1 + 1, x2 + 3, y2 + 1);
  }

  // Seam 2: from (795, 295) to (1145, 675)
  brush.set("2H", "#967b53", 0.55);
  brush.line(795, 295, 1145, 675);
  brush.line(735, 348, 1082, 732);
  drawSerratedTapeEnd(795, 295, 735, 348, 8);

  for (let t = 0.1; t < 0.9; t += 0.11) {
    let x1 = lerp(795, 1145, t);
    let y1 = lerp(295, 675, t);
    let x2 = lerp(735, 1082, t + 0.02);
    let y2 = lerp(348, 732, t + 0.02);
    brush.set("2H", "#a88d64", 0.5);
    brush.line(x1, y1, x2, y2);
  }
}

function drawSerratedTapeEnd(x1, y1, x2, y2, teeth) {
  brush.set("HB", "#7d643e", 0.65);
  let pts = [];
  for (let i = 0; i <= teeth * 2; i++) {
    let t = i / (teeth * 2);
    let bx = lerp(x1, x2, t);
    let by = lerp(y1, y2, t);
    let jag = (i % 2 === 0) ? -4 : 4;
    pts.push([bx + jag, by + jag * 0.5]);
  }
  brush.spline(pts, 0.05);
}

// ---------------------------------------------------------------------------
// PHASE 7: CORRUGATED CARDBOARD EDGES IN SHARP PENCIL
// ---------------------------------------------------------------------------

function drawCorrugatedCardboardEdges() {
  // Directive: "Corrugated cardboard edges are drawn in sharp pencil.
  // The frame is cropped tight and slightly off-axis, like a phone snapshot taken mid-unpacking."

  // Define the exposed corrugated cut edges framing the off-axis moving box:
  let edges = [
    // 1. Upper-left main box wall cut edge (running diagonally up to the top corner at (682, 72))
    { x1: -30, y1: 285, x2: 682, y2: 72, thick: 27, waveLen: 20 },
    // 2. Right main box wall cut edge (running from (682, 72) down-right to (1175, 885))
    { x1: 682, y1: 72, x2: 1175, y2: 885, thick: 28, waveLen: 20 },
    // 3. Bottom-left overlapping inner flap cut edge (running across foreground corner)
    { x1: -25, y1: 685, x2: 525, y2: 1225, thick: 29, waveLen: 21 },
    // 4. Left-side inner cardboard packing divider edge (tucked beside the dog's ear)
    { x1: 88, y1: 268, x2: 152, y2: 755, thick: 22, waveLen: 17 },
    // 5. Bottom-right folded flap edge cutting the lower corner
    { x1: 585, y1: 1145, x2: 1225, y2: 865, thick: 26, waveLen: 20 }
  ];

  // Outer frame margin outside the open box (dark table / shadow surround)
  brush.noStroke();
  brush.fill("#4a331e", 110);
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.6, 0.4);
  drawFilledPoly([[-30, -30], [1230, -30], [1230, 885], [682, 72], [-30, 285]], 0.02);
  drawFilledPoly([[-30, 685], [525, 1225], [-30, 1225]], 0.02);
  drawFilledPoly([[585, 1145], [1225, 865], [1225, 1225], [525, 1225]], 0.02);
  brush.noFill();

  // Render each corrugated cardboard cut edge with watercolour kraft base + razor-sharp pencil fluting
  for (let e of edges) {
    drawSingleCorrugatedEdge(e.x1, e.y1, e.x2, e.y2, e.thick, e.waveLen);
  }
}

function drawSingleCorrugatedEdge(x1, y1, x2, y2, thick, waveLen) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  let ux = dx / len;
  let uy = dy / len;
  // Perpendicular normal vector
  let nx = -uy;
  let ny = ux;

  // 1. Base kraft-brown watercolour strip for the cut edge
  let stripPoly = [
    [x1, y1],
    [x2, y2],
    [x2 + nx * thick, y2 + ny * thick],
    [x1 + nx * thick, y1 + ny * thick]
  ];
  brush.noStroke();
  brush.wash("#d6ab74", 210);
  drawFilledPoly(stripPoly, 0.01);
  brush.noWash();

  brush.fill("#b88042", 85);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.55, 0.45);
  drawFilledPoly(stripPoly, 0.01);
  brush.noFill();

  // 2. Outer and Inner Kraft Liner Sheets (double-lined in sharp HB & 2H graphite pencil)
  let linerT = 2.8;
  brush.set("graphite_sharp", "#2b2118", 0.95);
  brush.line(x1, y1, x2, y2);
  brush.line(x1 + nx * linerT, y1 + ny * linerT, x2 + nx * linerT, y2 + ny * linerT);

  brush.line(x1 + nx * (thick - linerT), y1 + ny * (thick - linerT), x2 + nx * (thick - linerT), y2 + ny * (thick - linerT));
  brush.line(x1 + nx * thick, y1 + ny * thick, x2 + nx * thick, y2 + ny * thick);

  // 3. Sinusoidal Corrugated Fluting Wave sandwiched between the two liners
  let wavePts = [];
  let steps = floor(len / (waveLen * 0.25));
  let innerAmp = (thick - linerT * 2.4) * 0.5;
  let midOff = thick * 0.5;

  for (let i = 0; i <= steps; i++) {
    let distAlong = (i / steps) * len;
    let phase = (distAlong / waveLen) * 360;
    let wOff = midOff + sin(phase) * innerAmp;

    let px = x1 + ux * distAlong + nx * wOff;
    let py = y1 + uy * distAlong + ny * wOff;
    wavePts.push([px, py]);

    // In every flute hollow (crest and trough), add sharp 2B pencil shadow shading!
    if (i % 2 === 1 && i < steps) {
      let isPeak = sin(phase) > 0;
      let pocketCenterOff = isPeak ? midOff + innerAmp * 0.55 : midOff - innerAmp * 0.55;
      let cx = x1 + ux * distAlong + nx * pocketCenterOff;
      let cy = y1 + uy * distAlong + ny * pocketCenterOff;

      // Dark shadow pocket inside the flute hole
      brush.set("2B", "#332417", 0.85);
      brush.line(
        cx - ux * (waveLen * 0.14),
        cy - uy * (waveLen * 0.14),
        cx + ux * (waveLen * 0.14),
        cy + uy * (waveLen * 0.14)
      );
      brush.set("HB", "#543b24", 0.65);
      brush.line(
        cx - nx * (innerAmp * 0.3),
        cy - ny * (innerAmp * 0.3),
        cx + nx * (innerAmp * 0.3),
        cy + ny * (innerAmp * 0.3)
      );
    }
  }

  // Draw the continuous sinusoidal corrugated wave in crisp graphite pencil
  brush.set("graphite_sharp", "#1f1710", 1.05);
  brush.spline(wavePts, 0.45);

  // Second subtle pencil pass for paper thickness of the flute medium
  let wavePts2 = wavePts.map(p => [p[0] + ux * 1.4, p[1] + uy * 1.4]);
  brush.set("2H", "#4d3926", 0.7);
  brush.spline(wavePts2, 0.45);
}

// ---------------------------------------------------------------------------
// PHASE 8: CRISP OPAQUE WHITE PEN DOTS ON EVERY DOME & PORCELAIN SPECULARS
// ---------------------------------------------------------------------------

function drawOpaqueWhiteHighlights(domes) {
  // Directive: "Crisp opaque white pen dots catch the highlight on every dome. Taped seams stay matte."

  for (let d of domes) {
    // Taped seams stay strictly matte — skip white pen dots on domes under the packing tape!
    if (d.underTape) continue;

    let { cx, cy, r } = d;

    // Light comes from upper-left: place crisp opaque white pen dot on the upper-left quadrant of every dome
    let hx = cx - r * 0.34;
    let hy = cy - r * 0.36;

    // Primary crisp opaque white pen dot
    brush.noStroke();
    brush.wash("#ffffff", 252);
    brush.circle(hx, hy, 3.1, 0.04);

    // Secondary tiny pin-dot catchlight just adjacent to the main dot
    brush.circle(hx + 5.2, hy - 1.8, 1.5, 0.02);
    brush.noWash();

    // Crisp white pen micro-stroke reinforcing the brightest specular bead
    brush.set("white_pen", "#ffffff", 1.35);
    brush.line(hx - 1.2, hy + 0.8, hx + 1.4, hy - 0.9);

    // Subtle secondary rim reflection on the opposite (bottom-right) curved wall of the air dome
    brush.set("white_pen", "#f7fbff", 0.65);
    brush.arc(cx, cy, r * 0.82, 28, 72);
  }

  // --- HIGH-FIRED PORCELAIN & GILT SPECULAR HIGHLIGHTS ON THE UNWRAPPED SPANIEL ---
