// Hyperrealism in p5.brush:
// Dawn Hoarfrost on a Vintage Bicycle Leaning Against an Iron Railing

const SADDLE_TOP = [
  [126, 355], [138, 306], [198, 284], [295, 302],
  [420, 333], [548, 337], [672, 329], [748, 336], [778, 366]
];

const SADDLE_BOT = [
