// Catmull-Rom / piecewise smooth curve evaluator
function evalCurve(pts, t) {
  t = constrain(t, 0, 1);
  let n = pts.length - 1;
  let f = t * n;
  let i = Math.min(Math.floor(f), n - 1);
  let u = f - i;
  let p0 = pts[Math.max(0, i - 1)];
  let p1 = pts[i];
  let p2 = pts[i + 1];
  let p3 = pts[Math.min(n, i + 2)];

  let u2 = u * u;
  let u3 = u2 * u;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * u +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * u +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3
  );
  return [x, y];
}

function curveNormal(pts, t, flip = 1) {
  let eps = 0.004;
  let a = evalCurve(pts, Math.max(0, t - eps));
  let b = evalCurve(pts, Math.min(1, t + eps));
  let dx = b[0] - a[0];
  let dy = b[1] - a[1];
  let ang = atan2(dy, dx) + flip * 90;
  return ang;
}

// Compute sunlight factor (0 = cold twilight shadow, 1 = apricot sunrise edge)
function getApricotFactor(x, y, nx = 1, ny = -0.3) {
  let posFactor = constrain(map(x * 0.82 - y * 0.35, 220, 720, 0, 1), 0, 1);
  let normFactor = constrain(nx * 0.85 - ny * 0.52, -0.2, 1);
  return constrain(posFactor * (0.35 + 0.65 * Math.max(0, normFactor)), 0, 1);
}

// Draw a single feathery hoarfrost needle with crystalline side barbs
function drawFrostNeedle(x, y, angleDeg, len, density, apricotAmt) {
  let rad = angleDeg * Math.PI / 180;
  let wobble = random(-7, 7);
  let a = (angleDeg + wobble) * Math.PI / 180;
  let ex = x + Math.cos(a) * len;
  let ey = y + Math.sin(a) * len;

  // 1. Subtle ice-blue base needle
  if (len > 9 && random() < 0.75) {
    let baseCol = apricotAmt > 0.45
      ? (random() < 0.5 ? "#c9b8b8" : "#d8c4bc")
      : (random() < 0.5 ? "#7e95ab" : "#9ab1c7");
    brush.set("cpencil", baseCol, random(0.18, 0.32));
    brush.line(x, y, x + Math.cos(a) * (len * 0.85), y + Math.sin(a) * (len * 0.85));
  }

  // 2. Primary crystalline white / pale apricot-white shaft
  let mainCol;
  if (apricotAmt > 0.55 && random() < 0.6) {
    mainCol = random() < 0.5 ? "#ffead9" : "#fff6ee";
  } else if (apricotAmt > 0.25 && random() < 0.4) {
    mainCol = "#eef4f8";
  } else {
    mainCol = random() < 0.65 ? "#f4f9fc" : "#ffffff";
  }

  let usePen = len > 14 ? (random() < 0.55) : (random() < 0.35);
  brush.set(usePen ? "rotring" : "2H", mainCol, random(0.14, 0.30) * (0.7 + 0.3 * density));
  brush.line(x, y, ex, ey);

  // 3. Dendritic 55-60 deg side feathers
  let numBarbs = Math.floor(map(len, 6, 42, 1, 6) * density);
  for (let b = 0; b < numBarbs; b++) {
    let frac = random(0.28, 0.88);
    let bx = lerp(x, ex, frac);
    let by = lerp(y, ey, frac);
    let side = b % 2 === 0 ? 1 : -1;
    let barbAng = (angleDeg + wobble + side * random(42, 62)) * Math.PI / 180;
    let barbLen = len * (1 - frac * 0.72) * random(0.32, 0.62);
    let bex = bx + Math.cos(barbAng) * barbLen;
    let bey = by + Math.sin(barbAng) * barbLen;

    brush.set(random() < 0.5 ? "2H" : "rotring", random() < 0.7 ? "#ffffff" : "#dde9f4", random(0.10, 0.22));
    brush.line(bx, by, bex, bey);

    // Secondary micro-barb on large feathers
    if (barbLen > 7 && random() < 0.45) {
      let sbx = lerp(bx, bex, 0.55);
      let sby = lerp(by, bey, 0.55);
      let sbAng = barbAng + side * 0.85;
      let sbLen = barbLen * 0.48;
      brush.line(sbx, sby, sbx + Math.cos(sbAng) * sbLen, sby + Math.sin(sbAng) * sbLen);
    }
  }

  // 4. Glistening dawn droplet on apricot-lit needles
  if (apricotAmt > 0.42 && len > 11 && random() < 0.22 * apricotAmt) {
    let gx = lerp(x, ex, random(0.72, 1.0));
    let gy = lerp(y, ey, random(0.72, 1.0));
    brush.set("cpencil", "#f29d6b", random(0.45, 0.75));
    brush.line(gx - 1, gy - 1, gx + 1.5, gy + 1.5);
    brush.set("rotring", "#ffd8b8", random(0.35, 0.55));
    brush.line(gx - 0.8, gy, gx + 0.8, gy);
    brush.set("rotring", "#ffffff", random(0.28, 0.48));
    brush.line(gx - 0.4, gy - 0.4, gx + 0.4, gy + 0.4);
  }
}

// Populate a path with tufted clusters of hoarfrost needles
function frostAlongPath(ptsFn, count, baseSpread, minLen, maxLen, flipNormal = -1, clusterBoost = 1.0) {
  for (let i = 0; i <= count; i++) {
    let t = i / count + random(-0.35 / count, 0.35 / count);
    t = constrain(t, 0.005, 0.995);
    let p = ptsFn(t);
    let eps = 0.005;
    let pA = ptsFn(Math.max(0, t - eps));
    let pB = ptsFn(Math.min(1, t + eps));
    let tang = atan2(pB[1] - pA[1], pB[0] - pA[0]);
    let normAng = tang + flipNormal * 90;

    // Clumping modulation so frost grows in natural crystalline tufts
    let clump = 0.45 + 0.85 * pow(noise(p[0] * 0.025, p[1] * 0.025), 1.4);
    let nx = cos(normAng);
    let ny = sin(normAng);
    let apricot = getApricotFactor(p[0], p[1], nx, ny);

    let ox = p[0] + random(-baseSpread, baseSpread);
    let oy = p[1] + random(-baseSpread, baseSpread);
    let len = random(minLen, maxLen) * clump * clusterBoost;
    let fan = random(-32, 32);

    drawFrostNeedle(ox, oy, normAng + fan, len, constrain(clump * clusterBoost, 0.6, 1.6), apricot);

    // Extra crossing needles at tuft peaks
    if (clump > 0.75 && random() < 0.65 * clusterBoost) {
      let fan2 = random(-52, 52);
      drawFrostNeedle(
        ox + random(-2, 2),
        oy + random(-2, 2),
        normAng + fan2,
        len * random(0.55, 0.92),
        0.9,
        apricot
      );
    }
  }
}

