function drawIronRailing() {
  // Railing geometry:
  // Top horizontal rail: (0, 508) -> (1200, 438), height 42
  // Lower horizontal rail: (0, 606) -> (1200, 536), height 18
  // Vertical balusters: x = 185, x = 648 (leaning contact point), x = 1072
  const railY = (x) => 508 - (70 * x) / 1200;
  const subRailY = (x) => 606 - (70 * x) / 1200;
  const bars = [185, 648, 1072];

  // Base washes for iron structure
  brush.noStroke();
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.4, 0.3);

  // Horizontal rails wash
  brush.fill("#1d252e", 210);
  brush.beginShape(0);
  brush.vertex(-10, railY(-10));
  brush.vertex(1210, railY(1210));
  brush.vertex(1210, railY(1210) + 42);
  brush.vertex(-10, railY(-10) + 42);
  brush.endShape(true);

  brush.fill("#222b35", 195);
  brush.beginShape(0);
  brush.vertex(-10, subRailY(-10));
  brush.vertex(1210, subRailY(1210));
  brush.vertex(1210, subRailY(1210) + 18);
  brush.vertex(-10, subRailY(-10) + 18);
  brush.endShape(true);

  // Vertical bars + spear finials wash
  for (let bx of bars) {
    let topY = railY(bx) - 185;
    brush.fill("#1a222b", 215);
    brush.rect(bx - 14, topY + 70, 28, 1220 - (topY + 70));

    // Finial spearhead
    brush.beginShape(0.15);
    brush.vertex(bx, topY);
    brush.vertex(bx + 19, topY + 52);
    brush.vertex(bx + 9, topY + 74);
    brush.vertex(bx - 9, topY + 74);
    brush.vertex(bx - 19, topY + 52);
    brush.endShape(true);
  }
  brush.noFill();

  // Colored pencil & graphite shading on the horizontal iron rails
  for (let s = 0; s < 160; s++) {
    let x1 = random(-10, 1120);
    let x2 = x1 + random(60, 190);
    let ry = random(0, 42);
    let y1 = railY(x1) + ry;
    let y2 = railY(x2) + ry;
    let apr = getApricotFactor((x1 + x2) * 0.5, y1, 0.3, -0.9);

    let col;
    if (ry < 7) {
      col = apr > 0.35 ? "#b89c8e" : "#5a6c7e"; // Top bevel catching dawn/sky
    } else if (ry > 32) {
      col = "#10151b"; // Deep underside shadow
    } else {
      col = random() < 0.3 ? "#3b2f2d" : "#252f3a"; // Oxidized iron & rust hint
    }
    brush.set("cpencil", col, random(0.22, 0.45));
    brush.line(x1, y1, x2, y2);
  }

  // Lower secondary rail shading
  for (let s = 0; s < 75; s++) {
    let x1 = random(-10, 1140);
    let x2 = x1 + random(50, 140);
    let ry = random(0, 18);
    let y1 = subRailY(x1) + ry;
    let y2 = subRailY(x2) + ry;
    let col = ry < 4 ? "#566778" : (ry > 13 ? "#12171d" : "#27313d");
    brush.set("cpencil", col, random(0.20, 0.38));
    brush.line(x1, y1, x2, y2);
  }

  // Vertical bars & finials detailed shading
  for (let bx of bars) {
    let topY = railY(bx) - 185;
    let apr = getApricotFactor(bx, 500, 1, 0);

    // Vertical iron grain & cylindrical modeling
    for (let i = 0; i < 120; i++) {
      let ox = random(-14, 14);
      let y1 = random(topY + 68, 1180);
      let y2 = Math.min(1200, y1 + random(40, 160));
      let col;
      if (ox > 7) {
        col = apr > 0.3 ? "#c79e85" : "#526375"; // Right edge catching dawn
      } else if (ox < -6) {
        col = "#11161c";
      } else {
        col = random() < 0.22 ? "#47332d" : "#232c37";
      }
      brush.set("cpencil", col, random(0.20, 0.42));
      brush.line(bx + ox, y1, bx + ox + random(-1, 1), y2);
    }

    // Finial spear facets
    for (let k = 0; k < 42; k++) {
      let t = k / 42;
      let fy = lerp(topY + 4, topY + 72, t);
      let halfW = t < 0.68 ? lerp(1, 19, t / 0.68) : lerp(19, 9, (t - 0.68) / 0.32);
      // Left dark facet
      brush.set("cpencil", "#161d24", 0.28);
      brush.line(bx - halfW, fy, bx, fy - 3);
      // Right lit facet
      let rCol = apr > 0.28 ? "#cfa186" : "#5e7082";
      brush.set("cpencil", rCol, 0.28);
      brush.line(bx, fy - 3, bx + halfW, fy);
    }

    // Cast-iron decorative knuckle/collar at rail intersections
    for (let cy of [railY(bx), subRailY(bx), topY + 74]) {
      brush.set("2B", "#12171d", 0.45);
      brush.rect(bx - 19, cy - 6, 38, 12);
      brush.set("cpencil", apr > 0.25 ? "#d9ad93" : "#6b7e91", 0.32);
      brush.line(bx - 18, cy - 5, bx + 18, cy - 5);
    }
  }
}

