function drawCylinderTube(x1, y1, x2, y2, r, isLuggedEnd) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  let ang = atan2(dy, dx);
  let nx = -sin(ang);
  let ny = cos(ang);
  if (ny > 0) {
    nx = -nx;
    ny = -ny;
  }

  // Base watercolor wash in deep British Racing Green
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.45, 0.3);
  brush.fill("#103022", 230);
  brush.beginShape(0);
  brush.vertex(x1 + nx * r, y1 + ny * r);
  brush.vertex(x2 + nx * r, y2 + ny * r);
  brush.vertex(x2 - nx * r, y2 - ny * r);
  brush.vertex(x1 - nx * r, y1 - ny * r);
  brush.endShape(true);
  brush.noFill();

  // Longitudinal colored-pencil strokes modeling cylindrical metal sheen
  let steps = Math.floor(r * 7.5);
  for (let i = 0; i < steps; i++) {
    let v = random(-1, 1); // -1 = bottom shadow, +1 = top/right dawn highlight
    let offX = nx * v * r;
    let offY = ny * v * r;
    let s1 = random(0, 0.85);
    let s2 = Math.min(1, s1 + random(0.12, 0.42));
    let px1 = lerp(x1, x2, s1) + offX;
    let py1 = lerp(y1, y2, s1) + offY;
    let px2 = lerp(x1, x2, s2) + offX;
    let py2 = lerp(y1, y2, s2) + offY;

    let apr = getApricotFactor((px1 + px2) * 0.5, (py1 + py2) * 0.5, nx * v, ny * v);
    let col;
    if (v > 0.55 && v < 0.84) {
      // Specular cylinder ridge catching dawn apricot & cold sky
      col = apr > 0.35
        ? (random() < 0.55 ? "#cfa78c" : "#8fa899")
        : (random() < 0.5 ? "#5c8576" : "#789e90");
    } else if (v >= 0.84) {
      // Extreme upper edge reflected sky/frost tone
      col = apr > 0.4 ? "#e3bca2" : "#496e60";
    } else if (v > -0.15) {
      // Rich midtone British Racing Green in muted colored pencil
      let p = random();
      col = p < 0.35 ? "#16422f" : (p < 0.7 ? "#1f543d" : "#286349");
    } else if (v > -0.68) {
      // Deep emerald-slate shadow
      col = random() < 0.5 ? "#0c261b" : "#152c29";
    } else {
      // Core shadow & reflected cold iron bounce
      col = random() < 0.6 ? "#081711" : "#1d2933";
    }

    brush.set("cpencil", col, random(0.22, 0.46));
    brush.line(px1, py1, px2, py2);
  }

  // Curved cross-contour colored pencil strokes for metallic roundness
  let ringCount = Math.floor(len / 14);
  for (let k = 0; k < ringCount; k++) {
    let t = (k + random(0.1, 0.9)) / ringCount;
    let cx = lerp(x1, x2, t);
    let cy = lerp(y1, y2, t);
    let v1 = random(-0.9, 0.4);
    let v2 = Math.min(0.95, v1 + random(0.3, 0.65));
    let curvePts = [
      [cx + nx * v1 * r, cy + ny * v1 * r],
      [cx + nx * ((v1 + v2) * 0.5) * r + cos(ang) * 5, cy + ny * ((v1 + v2) * 0.5) * r + sin(ang) * 5],
      [cx + nx * v2 * r, cy + ny * v2 * r]
    ];
    let col = v2 > 0.45 ? "#386e58" : "#0d291d";
    brush.set("cpencil", col, random(0.15, 0.28));
    brush.spline(curvePts, 0.4);
  }
}

function drawPaintChip(cx, cy, w, h, angDeg) {
  let pts = [];
  let n = 9;
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let radX = (w * 0.5) * random(0.65, 1.25);
    let radY = (h * 0.5) * random(0.65, 1.25);
    let lx = cos(a) * radX;
    let ly = sin(a) * radY;
    let rx = lx * cos(angDeg) - ly * sin(angDeg);
    let ry = lx * sin(angDeg) + ly * cos(angDeg);
    pts.push([cx + rx, cy + ry]);
  }

  // Dark chipped enamel shadow edge
  brush.set("2B", "#07140e", 0.35);
  for (let i = 0; i < n; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % n];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Exposed weathered bare steel & oxidized red-oxide primer inside chip
  for (let s = 0; s < 18; s++) {
    let pA = pts[ floor(random(n)) ];
    let pB = pts[ floor(random(n)) ];
    let mx1 = lerp(cx, pA[0], random(0.2, 0.9));
    let my1 = lerp(cy, pA[1], random(0.2, 0.9));
    let mx2 = lerp(cx, pB[0], random(0.2, 0.9));
    let my2 = lerp(cy, pB[1], random(0.2, 0.9));
    let col = random() < 0.45 ? "#6e4639" : (random() < 0.6 ? "#6b7885" : "#8e9ba8");
    brush.set("cpencil", col, random(0.18, 0.34));
    brush.line(mx1, my1, mx2, my2);
  }

  // Crisp light-catching rim on lower/right edge of chipped paint
  let apr = getApricotFactor(cx, cy, 1, -0.5);
  brush.set("2H", apr > 0.35 ? "#e8bfa5" : "#89a89c", 0.22);
  for (let i = 0; i < 4; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % n];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

