// ---------------------------------------------------------------------------
// SEATPOST, CLAMP & SADDLE RAILS
// ---------------------------------------------------------------------------
function drawSeatpostAndRails() {
  // Fluted alloy seatpost rising from (380, 665) to (334, 522)
  let x1 = 376, y1 = 665;
  let x2 = 334, y2 = 522;
  let r = 20;
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);

  brush.noStroke();
  brush.fill("#485461", 215);
  brush.beginShape(0);
  brush.vertex(x1 - nx * r, y1 - ny * r);
  brush.vertex(x2 - nx * r, y2 - ny * r);
  brush.vertex(x2 + nx * r, y2 + ny * r);
  brush.vertex(x1 + nx * r, y1 + ny * r);
  brush.endShape(true);
  brush.noFill();

  // Metallic shading & machined flutes on seatpost
  for (let i = 0; i < 95; i++) {
    let v = random(-1, 1);
    let s1 = random(0, 0.7);
    let s2 = Math.min(1, s1 + random(0.2, 0.5));
    let px1 = lerp(x1, x2, s1) + nx * v * r;
    let py1 = lerp(y1, y2, s1) + ny * v * r;
    let px2 = lerp(x1, x2, s2) + nx * v * r;
    let py2 = lerp(y1, y2, s2) + ny * v * r;
    let col = v > 0.35 ? "#b8c4cf" : (v < -0.35 ? "#1f262e" : "#677585");
    brush.set("cpencil", col, random(0.20, 0.36));
    brush.line(px1, py1, px2, py2);
  }
  // 4 dark machined flute grooves
  for (let f of [-0.55, -0.18, 0.18, 0.55]) {
    let fx1 = lerp(x1, x2, 0.12) + nx * f * r;
    let fy1 = lerp(y1, y2, 0.12) + ny * f * r;
    let fx2 = lerp(x1, x2, 0.82) + nx * f * r;
    let fy2 = lerp(y1, y2, 0.82) + ny * f * r;
    brush.set("2B", "#1a2129", 0.38);
    brush.line(fx1, fy1, fx2, fy2);
    brush.set("2H", "#cfdbe6", 0.20);
    brush.line(fx1 + 2, fy1, fx2 + 2, fy2);
  }

  // Saddle Rails (tubular chrome steel sweeping from rear cantle through clamp to nose)
  const railFar = [[185, 458], [250, 526], [335, 536], [442, 538], [585, 462], [728, 398]];
  const railNear = [[172, 448], [242, 514], [335, 524], [438, 526], [580, 450], [722, 390]];

  for (let rPts of [railFar, railNear]) {
    for (let o = -5; o <= 5; o += 1.5) {
      let shifted = rPts.map(p => [p[0], p[1] + o]);
      let col = o < -1.5 ? "#c8d4e0" : (o > 2 ? "#182029" : "#566473");
      brush.set("cpencil", col, 0.32);
      brush.spline(shifted, 0.45);
    }
  }

  // Seatpost Clamp & Nut at (335, 525)
  brush.noStroke();
  brush.fill("#28323c", 235);
  brush.circle(336, 524, 24, 0.2);
  brush.noFill();
  for (let k = 0; k < 35; k++) {
    let a = random(0, 360);
    let rad = random(4, 24);
    brush.set("cpencil", random() < 0.4 ? "#99a8b8" : "#1c242b", 0.32);
    brush.line(336 + cos(a) * rad, 524 + sin(a) * rad, 336 + cos(a + 25) * rad, 524 + sin(a + 25) * rad);
  }
  brush.set("2H", "#e6eef5", 0.28);
  brush.circle(336, 524, 11, 0.15);

  // Nose Tension Bolt & Shackle under saddle nose (705..758, 392..406)
  brush.set("2B", "#1d242b", 0.45);
  brush.line(702, 404, 756, 390);
  brush.set("cpencil", "#d4b098", 0.36);
  brush.line(702, 401, 756, 387);
}

// ---------------------------------------------------------------------------
// BRAKE CABLE, RIBBED HOUSING & TOP-TUBE CLIPS
// ---------------------------------------------------------------------------
const HOUSING_LEFT = [
  [-20, 616], [95, 624], [215, 640], [312, 656], [362, 664]
];
const BARE_CABLE = [
  [362, 664], [500, 682], [639, 706], [798, 739], [958, 772], [1072, 796]
];
const HOUSING_RIGHT = [
  [1072, 796], [1148, 812], [1225, 828]
];

function drawBrakeCableSystem() {
  // 1. Two Chrome Top-Tube Cable Clips wrapping the top tube at t=0.31 and t=0.69
  const clipPositions = [
    { cx: 632, cy: 742, topX: 639, topY: 706 },
    { cx: 951, cy: 809, topX: 958, topY: 772 }
  ];

  for (let cl of clipPositions) {
    let apr = getApricotFactor(cl.cx, cl.cy, 0.5, -0.8);
    // Band strap across the 64px top tube diameter
    for (let dx = -7; dx <= 7; dx += 1.4) {
      let col;
      if (dx > 2.5) col = apr > 0.35 ? "#f0c9ad" : "#c4d2de";
      else if (dx < -3) col = "#151d24";
      else col = "#637282";
      brush.set("cpencil", col, 0.30);
      brush.line(cl.cx + dx + 6, cl.cy - 32, cl.cx + dx - 6, cl.cy + 32);
    }
    // Pinched ear & miniature bolt at top of clip holding the brake cable
    brush.set("2B", "#182028", 0.38);
    brush.circle(cl.topX, cl.topY + 3, 9, 0.15);
    brush.set("2H", apr > 0.35 ? "#ffe3cc" : "#dce8f2", 0.26);
    brush.arc(cl.topX, cl.topY + 3, 8, -90, 60);
  }

  // 2. Left & Right Coiled/Ribbed Brake Cable Housing
  for (let hPts of [HOUSING_LEFT, HOUSING_RIGHT]) {
    for (let o = -5.5; o <= 5.5; o += 1.4) {
      let sPts = hPts.map(p => [p[0], p[1] + o]);
      let col = o < -2 ? "#7d8e9e" : (o > 2 ? "#10161c" : "#27323d");
      brush.set("cpencil", col, 0.34);
      brush.spline(sPts, 0.4);
    }
    // Coiled spiral ribs inside housing
    let steps = hPts === HOUSING_LEFT ? 75 : 32;
    for (let i = 0; i < steps; i++) {
      let t = i / steps;
      let p = evalCurve(hPts, t);
      let apr = getApricotFactor(p[0], p[1], 0.3, -0.9);
      brush.set("2B", "#0d1217", 0.25);
      brush.line(p[0] - 1, p[1] - 5, p[0] + 1, p[1] + 5);
      brush.set("2H", apr > 0.4 ? "#ebbda0" : "#8ba0b2", 0.18);
      brush.line(p[0] + 1, p[1] - 5, p[0] + 2, p[1] + 1);
    }
  }

  // Chrome Ferrules at (362, 664) and (1072, 796)
  for (let fp of [[362, 664], [1072, 796]]) {
    brush.set("2B", "#1b242c", 0.42);
    brush.rect(fp[0] - 8, fp[1] - 6, 16, 12, "center");
    brush.set("2H", "#e3edf5", 0.28);
    brush.line(fp[0] - 7, fp[1] - 4, fp[0] + 7, fp[1] - 2);
  }

  // 3. Taut Exposed Braided Steel Brake Wire (from (362, 664) to (1072, 796))
  // Core steel cable + helical wire strand texture
  brush.set("2B", "#1d262f", 0.45);
  brush.spline(BARE_CABLE, 0.35);
  let upperWire = BARE_CABLE.map(p => [p[0], p[1] - 2.2]);
  brush.set("cpencil", "#95a8b8", 0.32);
  brush.spline(upperWire, 0.35);

  for (let i = 0; i < 140; i++) {
    let t = i / 140;
    let p = evalCurve(BARE_CABLE, t);
    let apr = getApricotFactor(p[0], p[1], 0.4, -0.9);
    let col = apr > 0.4 ? "#f5cbb0" : "#cad8e6";
    brush.set("2H", col, 0.20);
    brush.line(p[0] - 2, p[1] - 2.5, p[0] + 2, p[1] + 2.2);
  }
}

// ---------------------------------------------------------------------------
// CRACKED LEATHER SADDLE, COPPER RIVETS & HEAVY STITCHING
// ---------------------------------------------------------------------------
function drawLeatherSaddle() {
  // 1. Base watercolor underpainting of the worn leather saddle
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.55, 0.35);
  brush.fill("#3b221b", 235);
  brush.beginShape(0.15);
  for (let p of SADDLE_TOP) brush.vertex(p[0], p[1]);
  for (let i = SADDLE_BOT.length - 2; i >= 1; i--) {
    brush.vertex(SADDLE_BOT[i][0], SADDLE_BOT[i][1]);
  }
  brush.endShape(true);

  // Warm apricot wash over the right nose and upper crown of the saddle
  brush.fillBleed(0.25, "out");
  brush.fill("#b86e4c", 90);
  brush.circle(695, 360, 120, 0.25);
  brush.fill("#e8a47e", 75);
  brush.circle(748, 362, 68, 0.2);
  brush.noFill();

  // 2. Dense Colored-Pencil Modeling of the 3D Leather Volume
  // Crown & seated hollow (between SADDLE_TOP and SADDLE_RIDGE)
  for (let i = 0; i < 650; i++) {
    let t = random(0.02, 0.98);
    let t2 = constrain(t + random(-0.08, 0.08), 0.01, 0.99);
    let v = random(0, 1);
    let pTop1 = evalCurve(SADDLE_TOP, t);
    let pRid1 = evalCurve(SADDLE_RIDGE, t);
    let pTop2 = evalCurve(SADDLE_TOP, t2);
    let pRid2 = evalCurve(SADDLE_RIDGE, t2);

    let x1 = lerp(pTop1[0], pRid1[0], v);
    let y1 = lerp(pTop1[1], pRid1[1], v);
    let x2 = lerp(pTop2[0], pRid2[0], v);
    let y2 = lerp(pTop2[1], pRid2[1], v);

    let apr = getApricotFactor(x1, y1, 0.5, -0.8);
    let inHollow = exp(-pow((t - 0.46) / 0.18, 2)); // Concave seat dip

    let col;
    if (v < 0.28) {
      // Upper crown catching cold dawn sky & warm apricot sunrise on the right
      if (apr > 0.48) {
        col = random() < 0.5 ? "#d99b78" : "#b87454";
      } else if (inHollow > 0.5) {
        col = random() < 0.5 ? "#5e545e" : "#705958"; // Cool dusk slate-violet reflection in worn hollow
      } else {
        col = random() < 0.5 ? "#7d4f3e" : "#6b483d";
      }
    } else {
      // Rounded shoulder transitioning to side flank
      if (apr > 0.42) {
        col = random() < 0.5 ? "#a65f43" : "#8c4a32";
      } else {
        col = random() < 0.5 ? "#573226" : "#45261d";
      }
    }
    brush.set("cpencil", col, random(0.22, 0.45));
    brush.line(x1, y1, x2, y2);
  }

  // Side Flank & Skirt (between SADDLE_RIDGE and SADDLE_BOT)
  for (let i = 0; i < 950; i++) {
    let t = random(0.02, 0.98);
    let t2 = constrain(t + random(-0.06, 0.06), 0.01, 0.99);
    let v = random(0, 1);
    let pRid1 = evalCurve(SADDLE_RIDGE, t);
    let pBot1 = evalCurve(SADDLE_BOT, t);
    let pRid2 = evalCurve(SADDLE_RIDGE, t2);
    let pBot2 = evalCurve(SADDLE_BOT, t2);

    let x1 = lerp(pRid1[0], pBot1[0], v);
    let y1 = lerp(pRid1[1], pBot1[1], v);
    let x2 = lerp(pRid2[0], pBot2[0], v);
    let y2 = lerp(pRid2[1], pBot2[1], v);

    let apr = getApricotFactor(x1, y1, 0.4, 0.3);
    // Molded relief depression in the middle flank (around t=0.25..0.62, v=0.35..0.78)
    let inDepression = (t > 0.22 && t < 0.64 && v > 0.32 && v < 0.78);

    let col;
    if (v > 0.84) {
      // Thick cut leather bottom edge & deep shadow
      col = random() < 0.65 ? "#1c0f0c" : "#2e1a15";
    } else if (inDepression) {
      col = random() < 0.5 ? "#2b1813" : "#3d241d";
    } else if (v < 0.22) {
      // Highlight along the main saddle ridge
      col = apr > 0.4 ? "#c98564" : (random() < 0.5 ? "#875442" : "#6e4334");
    } else {
      // Rich oxblood / aged walnut leather flank
      if (apr > 0.45) {
        col = random() < 0.5 ? "#96543b" : "#783f2b";
      } else {
        let r = random();
        col = r < 0.33 ? "#4d2b21" : (r < 0.66 ? "#3b2018" : "#5e382b");
      }
    }
    brush.set("cpencil", col, random(0.22, 0.48));
    brush.line(x1, y1, x2, y2);
  }

  // 3. Extensive Network of Hyper-Detailed Cracked Leather Creases
  // Primary tension cracks radiating across the crown, waist, and skirt
  for (let c = 0; c < 135; c++) {
    let tStart = random(0.06, 0.93);
    let isCrown = random() < 0.48;
    let vStart = random(0.05, 0.88);

    let pts = [];
    let curT = tStart;
    let curV = vStart;
    let segs = floor(random(4, 9));

    for (let s = 0; s <= segs; s++) {
      let pA = evalCurve(isCrown ? SADDLE_TOP : SADDLE_RIDGE, curT);
      let pB = evalCurve(isCrown ? SADDLE_RIDGE : SADDLE_BOT, curT);
      let px = lerp(pA[0], pB[0], curV);
      let py = lerp(pA[1], pB[1], curV);
      pts.push([px, py]);

      // Cracks follow stress lines (mostly transverse on crown/waist, diagonal on flank)
      curT += random(-0.028, 0.028);
      curV += isCrown ? random(0.08, 0.22) : random(-0.14, 0.18);
      curT = constrain(curT, 0.03, 0.96);
      curV = constrain(curV, 0.04, 0.94);
    }

    // Dark fissure line
    brush.set(random() < 0.5 ? "rotring" : "2B", "#170b08", random(0.16, 0.32));
    brush.spline(pts, 0.35);

    // Scuffed pale leather lip catching dawn light alongside the crack
    let lipPts = pts.map(p => [p[0] + 1.4, p[1] - 1.1]);
    let apr = getApricotFactor(pts[0][0], pts[0][1], 0.6, -0.5);
    let lipCol = apr > 0.4 ? "#d49a79" : "#8c6556";
    brush.set("2H", lipCol, random(0.14, 0.24));
    brush.spline(lipPts, 0.35);

    // Branching micro-crack
    if (pts.length >= 4 && random() < 0.65) {
      let mid = pts[2];
      let bEnd = [mid[0] + random(-18, 18), mid[1] + random(-16, 16)];
      brush.set("rotring", "#1a0d0a", 0.16);
      brush.line(mid[0], mid[1], bEnd[0], bEnd[1]);
    }
  }

  // 4. Hammered Copper Rivets (Rear Cantle & Nose)
  const rivets = [
    { x: 145, y: 332, r: 7.5 },
    { x: 138, y: 366, r: 8.0 },
    { x: 138, y: 400, r: 8.0 },
    { x: 158, y: 432, r: 7.8 },
    { x: 192, y: 458, r: 7.5 },
    { x: 728, y: 354, r: 6.8 },
    { x: 736, y: 380, r: 6.8 }
  ];

  for (let rv of rivets) {
    let apr = getApricotFactor(rv.x, rv.y, 0.7, -0.4);
    // Sunken leather dimple around rivet
    brush.set("2B", "#140a07", 0.42);
    brush.circle(rv.x, rv.y, rv.r + 2.2, 0.18);

    // Copper dome fill & facets
    for (let k = 0; k < 18; k++) {
      let a = random(0, 360);
      let d = random(1, rv.r);
      let col = (cos(a) > 0 && sin(a) < 0.3)
        ? (apr > 0.4 ? "#ffd3b0" : "#d99b78")
        : "#6e3d28";
      brush.set("cpencil", col, 0.30);
      brush.line(rv.x, rv.y, rv.x + cos(a) * d, rv.y + sin(a) * d);
    }
    // Specular copper glint
    brush.set("rotring", "#fff2e6", 0.26);
    brush.arc(rv.x, rv.y, rv.r * 0.65, -75, 35);
  }

  // 5. Heavy Wax-Thread Saddle Stitching Along Lower Skirt & Inner Welt
  // Primary lower skirt stitch seam (offset 13px inside SADDLE_BOT)
  let stitchCount = 58;
  for (let i = 0; i < stitchCount; i++) {
    let t1 = map(i, 0, stitchCount, 0.07, 0.95);
    let t2 = map(i + 0.68, 0, stitchCount, 0.07, 0.95);
    let p1 = evalCurve(SADDLE_BOT, t1);
    let p2 = evalCurve(SADDLE_BOT, t2);
    let nAng = curveNormal(SADDLE_BOT, t1, -1);
    let ox = cos(nAng) * 13;
    let oy = sin(nAng) * 13;

    let sx1 = p1[0] + ox, sy1 = p1[1] + oy;
    let sx2 = p2[0] + ox, sy2 = p2[1] + oy;

    // Stitch hole shadow
    brush.set("rotring", "#120906", 0.32);
    brush.line(sx1 - 1, sy1 + 1.5, sx2 + 1, sy2 + 1.5);

    // Raised wax thread segment
    let apr = getApricotFactor(sx1, sy1, 0.5, 0.5);
    let threadCol = apr > 0.4 ? "#e8c5ab" : "#b5a395";
    brush.set("cpencil", threadCol, 0.42);
    brush.line(sx1, sy1, sx2, sy2);
  }

  // Secondary inner flank stitch seam (framing the side cutout depression)
  const FLANK_STITCH = [
    [235, 424], [305, 448], [385, 452], [465, 428], [548, 398]
  ];
  let flankStitches = 32;
  for (let i = 0; i < flankStitches; i++) {
    let t1 = i / flankStitches;
    let t2 = (i + 0.68) / flankStitches;
    let p1 = evalCurve(FLANK_STITCH, t1);
    let p2 = evalCurve(FLANK_STITCH, t2);
    brush.set("rotring", "#140a08", 0.28);
    brush.line(p1[0], p1[1] + 1.5, p2[0], p2[1] + 1.5);
    brush.set("cpencil", "#c2b0a2", 0.36);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// ---------------------------------------------------------------------------
// MASTER HOARFROST LAYER: COUNTLESS WHITE PENCIL & PEN SPIKES
// ---------------------------------------------------------------------------
function drawHoarfrostMasterLayer() {
  // 1. Soft icy colored-pencil bloom along the heaviest frost nucleation zones
  // (Saddle stitching & brake cable) so the dense spikes emerge from a furry crystal bed
  const FLANK_STITCH = [
    [235, 424], [305, 448], [385, 452], [465, 428], [548, 398]
  ];

  for (let i = 0; i < 220; i++) {
    let t = random(0.06, 0.96);
    let p = evalCurve(SADDLE_BOT, t);
    let nAng = curveNormal(SADDLE_BOT, t, -1);
    let sx = p[0] + cos(nAng) * 13 + random(-4, 4);
    let sy = p[1] + sin(nAng) * 13 + random(-4, 4);
    let apr = getApricotFactor(sx, sy, 0.4, 0.5);
