// Lightweight 2D affine matrix stack so all Polygon/spline/line coordinates
// map directly to canvas space after the initial translate(-width/2, -height/2)
let matStack = [];
let curMat = { a: 1, b: 0, c: 0, d: 1, tx: 0, ty: 0, rot: 0, scale: 1 };

function resetMat() {
  matStack = [];
  curMat = { a: 1, b: 0, c: 0, d: 1, tx: 0, ty: 0, rot: 0, scale: 1 };
}

function pushM() {
  matStack.push({ ...curMat });
}

function popM() {
  if (matStack.length > 0) curMat = matStack.pop();
}

function transM(x, y) {
  curMat.tx += curMat.a * x + curMat.c * y;
  curMat.ty += curMat.b * x + curMat.d * y;
}

function rotM(deg) {
  let r = (deg * Math.PI) / 180;
  let cs = Math.cos(r);
  let sn = Math.sin(r);
  let a = curMat.a * cs + curMat.c * sn;
  let b = curMat.b * cs + curMat.d * sn;
  let c = curMat.a * -sn + curMat.c * cs;
  let d = curMat.b * -sn + curMat.d * cs;
  curMat.a = a;
  curMat.b = b;
  curMat.c = c;
  curMat.d = d;
  curMat.rot += deg;
}

function scaleM(s) {
  curMat.a *= s;
  curMat.b *= s;
  curMat.c *= s;
  curMat.d *= s;
  curMat.scale *= s;
}

function xf(x, y, pressure) {
  let nx = curMat.a * x + curMat.c * y + curMat.tx;
  let ny = curMat.b * x + curMat.d * y + curMat.ty;
  if (pressure !== undefined) return [nx, ny, pressure];
  return [nx, ny];
}

function xfPts(pts) {
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    out.push(xf(p[0], p[1], p[2]));
  }
  return out;
}

function cleanPts(pts, closeLoop = false) {
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (out.length === 0) {
      out.push(p);
    } else {
      let prev = out[out.length - 1];
      if (Math.hypot(p[0] - prev[0], p[1] - prev[1]) > 0.65) {
        out.push(p);
      }
    }
  }
  if (closeLoop && out.length >= 3) {
    let first = out[0];
    let last = out[out.length - 1];
    if (Math.hypot(first[0] - last[0], first[1] - last[1]) > 0.65) {
      out.push([first[0], first[1], first[2]]);
    }
  }
  return out;
}

// Safe p5.brush drawing primitives
function polyWash(localPts, col, alpha = 255) {
  let pts = cleanPts(xfPts(localPts), false);
  if (pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.wash(col, alpha);
}

function polyHatch(localPts, brushName, col, weight, dist, localAngleDeg, opts = { rand: 0.02 }) {
  let pts = cleanPts(xfPts(localPts), false);
  if (pts.length < 3) return;
  let p = new brush.Polygon(pts);
  brush.hatchStyle(brushName, col, weight);
  p.hatch(dist * curMat.scale, localAngleDeg + curMat.rot, opts);
  brush.noHatch();
}

function strokePath(localPts, brushName, col, weight, closed = false, curvature = 0.25) {
  let pts = cleanPts(xfPts(localPts), closed);
  if (pts.length < 2) return;
  brush.set(brushName, col, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, curvature);
  }
}

function strokeSeg(x1, y1, x2, y2, brushName, col, weight) {
  let p1 = xf(x1, y1);
  let p2 = xf(x2, y2);
  if (Math.hypot(p2[0] - p1[0], p2[1] - p1[1]) < 0.4) return;
  brush.set(brushName, col, weight);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
}

// Geometry generators in local coordinates
function makeEllipsePts(cx, cy, rx, ry, steps = 28, startRad = 0, endRad = Math.PI * 2) {
  let pts = [];
  let count = Math.max(4, steps);
  let full = Math.abs(endRad - startRad - Math.PI * 2) < 0.001;
  let limit = full ? count : count + 1;
  for (let i = 0; i < limit; i++) {
    let t = startRad + ((endRad - startRad) * i) / count;
    pts.push([cx + Math.cos(t) * rx, cy + Math.sin(t) * ry]);
  }
  return pts;
}

// 3D Spherical Coordinate Projection onto tilted 2D capsule plane
// phi: latitude (-PI/2 south pole .. 0 equator .. +PI/2 north pole)
// theta: longitude (0..PI front hemisphere, PI..2PI back hemisphere)
function spherePt(phi, theta, rad, tilt, yShift = 0) {
  let cPhi = Math.cos(phi);
  let sPhi = Math.sin(phi);
  let x = rad * cPhi * Math.cos(theta);
  let y = -rad * sPhi * Math.cos(tilt) + rad * cPhi * Math.sin(theta) * Math.sin(tilt) + yShift;
  return [x, y];
}

// Project a small circle on the sphere (for vent holes & mould sprue marks)
function sphereCirclePts(phi0, theta0, angRad, rad, tilt, steps = 16, yShift = 0) {
  let pts = [];
  let cPhi0 = Math.max(0.2, Math.cos(phi0));
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let phi = phi0 + angRad * Math.sin(a);
    let theta = theta0 + (angRad * Math.cos(a)) / cPhi0;
    pts.push(spherePt(phi, theta, rad, tilt, yShift));
  }
  return pts;
}

// Project a spherical patch [phi1..phi2] x [theta1..theta2]
function spherePatchPts(phi1, phi2, theta1, theta2, rad, tilt, stepsT = 16, stepsP = 6, yShift = 0) {
  let pts = [];
  for (let i = 0; i <= stepsT; i++) {
    let th = theta1 + ((theta2 - theta1) * i) / stepsT;
    pts.push(spherePt(phi1, th, rad, tilt, yShift));
  }
  for (let i = 1; i <= stepsP; i++) {
    let ph = phi1 + ((phi2 - phi1) * i) / stepsP;
    pts.push(spherePt(ph, theta2, rad, tilt, yShift));
  }
  for (let i = stepsT - 1; i >= 0; i--) {
    let th = theta1 + ((theta2 - theta1) * i) / stepsT;
    pts.push(spherePt(phi2, th, rad, tilt, yShift));
  }
  for (let i = stepsP - 1; i >= 1; i--) {
    let ph = phi1 + ((phi2 - phi1) * i) / stepsP;
    pts.push(spherePt(ph, theta1, rad, tilt, yShift));
  }
  return pts;
}

