    { x: 295, y: 930, r: 128, rot: 22, tilt: 0.35, color: "mint", toy: "bunny", variant: 2, open: 9, leaflet: true },
    { x: 915, y: 930, r: 130, rot: -26, tilt: 0.33, color: "yellow", toy: "bunny", variant: 0, open: 0, leaflet: true },

    // Hero foreground triad (Baby Blue Cat, Butter Yellow Dumpling, Mint Bunny)
    { x: 710, y: 810, r: 140, rot: 17, tilt: 0.36, color: "blue", toy: "cat", variant: 2, open: 0, leaflet: true },
    { x: 455, y: 780, r: 142, rot: -20, tilt: 0.36, color: "yellow", toy: "dumpling", variant: 0, open: 8, leaflet: false },
    { x: 585, y: 555, r: 148, rot: -9, tilt: 0.38, color: "mint", toy: "bunny", variant: 1, open: 11, leaflet: true }
  ];

  for (let i = 0; i < capsules.length; i++) {
    drawGachaCapsule(capsules[i]);
  }

  noLoop();
}

// ============================================================================
// HYPERREAL GACHA CAPSULE RENDERER
// ============================================================================
function drawGachaCapsule(cap) {
  pushM();
  transM(cap.x, cap.y);
  rotM(cap.rot);

  let R = cap.r;
  let tilt = cap.tilt;
  let openY = -cap.open; // slight upward separation of clear dome when ajar
  let pal = PALETTE[cap.color];

  // --- STEP 1: Clear Upper Dome Back Wall & Plastic Refraction over Pink ---
  let upperDomePts = [];
  for (let i = 0; i <= 32; i++) {
    let a = Math.PI + (Math.PI * i) / 32; // PI to 2PI (top semicircle in local coords)
    upperDomePts.push([Math.cos(a) * R, Math.sin(a) * R + openY]);
  }
  for (let i = 16; i >= 0; i--) {
    let th = (Math.PI * i) / 16;
    upperDomePts.push(spherePt(0, th, R, tilt, openY));
  }
  polyWash(upperDomePts, PALETTE.clear.pinkRefract, 235);
  polyWash(upperDomePts, PALETTE.clear.lilacTint, 95);
  polyHatch(upperDomePts, "blend_marker", PALETTE.clear.iceBlue, 1.0, 9, -38, { rand: 0.02 });

  // Inner clear wall thickness refraction crescent along top dome rim
  let topRimBand = [];
  for (let i = 2; i <= 30; i++) {
    let a = Math.PI + (Math.PI * i) / 32;
    topRimBand.push([Math.cos(a) * R * 0.99, Math.sin(a) * R * 0.99 + openY]);
  }
  for (let i = 30; i >= 2; i--) {
    let a = Math.PI + (Math.PI * i) / 32;
    topRimBand.push([Math.cos(a) * R * 0.91, Math.sin(a) * R * 0.91 + openY]);
  }
  polyWash(topRimBand, PALETTE.clear.iceBlue, 145);
  polyWash(topRimBand, PALETTE.white, 110);

  // --- STEP 2: Colored Lower Half-Domed Shell (Back Wall / Inside Bowl) ---
  let lowerBowlPts = [];
  // Back equator arc (theta from PI to 2PI)
  for (let i = 0; i <= 24; i++) {
    let th = Math.PI + (Math.PI * i) / 24;
    lowerBowlPts.push(spherePt(0, th, R, tilt, 0));
  }
  // Bottom outer semicircle (angle from 0 to PI)
  for (let i = 0; i <= 32; i++) {
    let a = (Math.PI * i) / 32;
    lowerBowlPts.push([Math.cos(a) * R, Math.sin(a) * R]);
  }
  polyWash(lowerBowlPts, pal.mid, 248);
  polyHatch(lowerBowlPts, "chisel_marker", pal.deep, 1.0, 7, 22, { rand: 0.02 });

  // Deep concave interior shadow inside the colored bowl (where the figurine sits)
  let innerWellPts = spherePatchPts(-0.75, -0.02, Math.PI * 1.06, Math.PI * 1.94, R * 0.95, tilt, 18, 5, 0);
  polyWash(innerWellPts, pal.deep, 175);
  polyHatch(innerWellPts, "chisel_marker", pal.deep, 1.1, 6, -15, { rand: 0.02 });

  // Bright internal bounce glow near bottom of colored cup
  let lowerBouncePts = spherePatchPts(-1.35, -0.65, Math.PI * 0.15, Math.PI * 0.85, R * 0.92, tilt, 16, 4, 0);
  polyWash(lowerBouncePts, pal.bright, 190);

  // South Pole injection mould sprue mark (at bottom of colored shell)
  let southGateOuter = sphereCirclePts(-Math.PI / 2, Math.PI * 0.5, 0.068, R * 0.96, tilt, 14, 0);
  let southGateInner = sphereCirclePts(-Math.PI / 2, Math.PI * 0.5, 0.032, R * 0.96, tilt, 10, 0);
  polyWash(southGateOuter, pal.light, 170);
  strokePath(southGateOuter, "micro_ink", pal.line, 0.65, true, 0.25);
  strokePath(southGateInner, "micro_ink", pal.line, 0.55, true, 0.25);

  // Back-wall vent holes on clear dome (2 rear holes visible behind figurine)
  const rearHoleThetas = [Math.PI * 1.25, Math.PI * 1.75];
  for (let k = 0; k < rearHoleThetas.length; k++) {
    let hPts = sphereCirclePts(1.06, rearHoleThetas[k], 0.072, R * 0.97, tilt, 14, openY);
    polyWash(hPts, PALETTE.clear.iceBlue, 165);
    strokePath(hPts, "micro_ink", PALETTE.inkSoft, 0.55, true, 0.25);
  }

  // --- STEP 3: Folded Gashapon Mini-Booklet (Paper Checklist Insert) ---
  if (cap.leaflet) {
    drawGachaLeaflet(R, tilt, cap.color);
  }

  // --- STEP 4: Back Half of the Equatorial Locking Seam ---
  let backRingUpper = spherePatchPts(0.0, 0.055, Math.PI * 1.02, Math.PI * 1.98, R * 1.02, tilt, 20, 2, openY);
  let backRingLower = spherePatchPts(-0.055, 0.0, Math.PI * 1.02, Math.PI * 1.98, R * 1.02, tilt, 20, 2, 0);
  polyWash(backRingUpper, PALETTE.clear.iceBlue, 160);
  polyWash(backRingLower, pal.bright, 195);

  // Back locking snap-tabs
  const backTabThetas = [Math.PI * 1.22, Math.PI * 1.78];
  for (let t = 0; t < backTabThetas.length; t++) {
    let tabPts = spherePatchPts(-0.06, 0.06, backTabThetas[t] - 0.08, backTabThetas[t] + 0.08, R * 1.01, tilt, 5, 2, 0);
    polyWash(tabPts, PALETTE.white, 175);
    strokePath(tabPts, "micro_ink", PALETTE.inkSoft, 0.55, true, 0.1);
  }

  // Crisp back equator line
  let backEqLine = [];
  for (let i = 0; i <= 22; i++) {
    let th = Math.PI + (Math.PI * i) / 22;
    backEqLine.push(spherePt(0, th, R * 1.01, tilt, 0));
  }
  strokePath(backEqLine, "micro_ink", PALETTE.inkSoft, 0.7, false, 0.2);

  // --- STEP 5: The Tiny Glossy Figurine Inside! ---
  pushM();
  transM(0, R * 0.06);
  rotM(cap.variant === 1 ? 6 : cap.variant === 2 ? -6 : 3);
  let figScale = R / 136;
  if (cap.toy === "cat") {
    drawCatFigurine(figScale, cap.variant, cap.color);
  } else if (cap.toy === "dumpling") {
    drawDumplingFigurine(figScale, cap.variant, cap.color);
  } else {
    drawBunnyFigurine(figScale, cap.variant, cap.color);
  }
  popM();

  // --- STEP 6: Translucent Front Wall of the Colored Half-Domed Shell ---
  // Wraps in front of the lower base of the figurine!
  let frontCupPts = [];
  for (let i = 0; i <= 24; i++) {
    let th = (Math.PI * i) / 24; // Front equator (0 to PI)
    frontCupPts.push(spherePt(0, th, R, tilt, 0));
  }
  for (let i = 24; i >= 0; i--) {
    let a = (Math.PI * i) / 24; // Bottom silhouette (PI to 0)
    frontCupPts.push([Math.cos(a) * R, Math.sin(a) * R]);
  }
  polyWash(frontCupPts, pal.mid, 145);
  polyHatch(frontCupPts, "blend_marker", pal.bright, 1.0, 8, 12, { rand: 0.02 });

  // Deep saturated rim refraction along the bottom outer edge of the colored shell
  let bottomRimShade = [];
  for (let i = 2; i <= 22; i++) {
    let a = (Math.PI * i) / 24;
    bottomRimShade.push([Math.cos(a) * R * 0.99, Math.sin(a) * R * 0.99]);
  }
  for (let i = 22; i >= 2; i--) {
    let a = (Math.PI * i) / 24;
    bottomRimShade.push([Math.cos(a) * R * 0.89, Math.sin(a) * R * 0.89]);
  }
  polyWash(bottomRimShade, pal.deep, 155);

  // Colored shell front meridian mould seam line
  let lowerSeamPts = [];
  for (let i = 0; i <= 10; i++) {
    let ph = (-Math.PI / 2) * (i / 10);
    lowerSeamPts.push(spherePt(ph, Math.PI * 0.36, R * 0.99, tilt, 0));
  }
  strokePath(lowerSeamPts, "micro_ink", pal.line, 0.5, false, 0.2);

  // Glossy white reflection band across the front of the colored lower cup
  let cupGlossPts = spherePatchPts(-0.48, -0.22, Math.PI * 0.56, Math.PI * 0.86, R * 0.96, tilt, 12, 3, 0);
  polyWash(cupGlossPts, pal.light, 210);
  polyWash(cupGlossPts, PALETTE.white, 175);
  strokePath(cupGlossPts, "white_posca", PALETTE.white, 0.85, true, 0.25);

  // --- STEP 7: Front Equatorial Locking Seam, Flange Steps & Snap Tabs ---
  // If slightly popped open (openY < 0), draw the gap and both exposed lips!
  if (cap.open > 0) {
    let gapBand = [];
    for (let i = 0; i <= 22; i++) {
      let th = (Math.PI * i) / 22;
      gapBand.push(spherePt(0, th, R * 1.01, tilt, openY));
    }
    for (let i = 22; i >= 0; i--) {
      let th = (Math.PI * i) / 22;
      gapBand.push(spherePt(0, th, R * 1.01, tilt, 0));
    }
    polyWash(gapBand, PALETTE.clear.iceBlue, 110);
  }

  // Lower colored flange lip (front)
  let frontLowerFlange = spherePatchPts(-0.068, 0.0, 0.0, Math.PI, R * 1.034, tilt, 24, 3, 0);
  polyWash(frontLowerFlange, pal.mid, 230);
  polyWash(frontLowerFlange, pal.bright, 140);

  // Upper clear dome flange lip (front)
  let frontUpperFlange = spherePatchPts(0.0, 0.068, 0.0, Math.PI, R * 1.034, tilt, 24, 3, openY);
  polyWash(frontUpperFlange, PALETTE.clear.iceBlue, 185);
  polyWash(frontUpperFlange, PALETTE.white, 165);

  // Internal twist-lock snap tabs on front equator
  const frontTabThetas = [Math.PI * 0.22, Math.PI * 0.78];
  for (let t = 0; t < frontTabThetas.length; t++) {
    let th0 = frontTabThetas[t];
    let tabBox = spherePatchPts(-0.095, 0.085, th0 - 0.09, th0 + 0.09, R * 1.036, tilt, 6, 2, openY * 0.5);
    polyWash(tabBox, PALETTE.clear.iceMint, 195);
    polyWash(tabBox, PALETTE.white, 180);
    strokePath(tabBox, "micro_ink", PALETTE.ink, 0.7, true, 0.1);

    // Vertical mould ribs inside the locking tab
    for (let r = -1; r <= 1; r++) {
      let pTop = spherePt(0.075, th0 + r * 0.035, R * 1.036, tilt, openY * 0.5);
      let pBot = spherePt(-0.085, th0 + r * 0.035, R * 1.036, tilt, openY * 0.5);
      strokeSeg(pTop[0], pTop[1], pBot[0], pBot[1], "micro_ink", PALETTE.inkSoft, 0.5);
    }
    // Pinprick white glint on tab edge
    let g1 = spherePt(0.065, th0 - 0.07, R * 1.038, tilt, openY * 0.5);
    let g2 = spherePt(0.065, th0 + 0.07, R * 1.038, tilt, openY * 0.5);
    strokeSeg(g1[0], g1[1], g2[0], g2[1], "white_posca", PALETTE.white, 1.1);
  }

  // Crisp ink lines along the front equatorial flange lips & parting seam
  let eqTopRim = [];
  let eqCenterUse = [];
  let eqBotRim = [];
  for (let i = 0; i <= 26; i++) {
    let th = (Math.PI * i) / 26;
    eqTopRim.push(spherePt(0.068, th, R * 1.034, tilt, openY));
    eqCenterUse.push(spherePt(0.0, th, R * 1.036, tilt, openY));
    eqBotRim.push(spherePt(-0.068, th, R * 1.034, tilt, 0));
  }
  strokePath(eqTopRim, "micro_ink", PALETTE.ink, 0.7, false, 0.2);
  strokePath(eqCenterUse, "liner_ink", PALETTE.ink, 0.95, false, 0.2);
  strokePath(eqBotRim, "micro_ink", PALETTE.ink, 0.75, false, 0.2);

  if (cap.open > 0) {
    let eqLowerLip = [];
    for (let i = 0; i <= 26; i++) {
      let th = (Math.PI * i) / 26;
      eqLowerLip.push(spherePt(0.0, th, R * 1.036, tilt, 0));
    }
    strokePath(eqLowerLip, "liner_ink", PALETTE.ink, 0.9, false, 0.2);
  }

  // Specular highlight streaks right along the protruding equatorial ring
  let eqGlintLeft = [];
  for (let i = 3; i <= 11; i++) {
    let th = Math.PI * (0.52 + (i / 14) * 0.38);
    eqGlintLeft.push(spherePt(0.032, th, R * 1.038, tilt, openY));
  }
  strokePath(eqGlintLeft, "white_posca", PALETTE.white, 1.4, false, 0.2);

  let eqGlintRight = [];
  for (let i = 0; i <= 6; i++) {
    let th = Math.PI * (0.12 + (i / 6) * 0.18);
    eqGlintRight.push(spherePt(-0.025, th, R * 1.038, tilt, 0));
  }
  strokePath(eqGlintRight, "white_posca", PALETTE.white, 1.15, false, 0.2);

  // --- STEP 8: Front Clear Dome Mould Marks, Sprue Gate & 4 Air Vent Holes ---
  // Clear dome meridian mould parting line + parallel white refraction hairline
  let upperSeamInk = [];
  let upperSeamWhite = [];
  for (let i = 0; i <= 12; i++) {
    let ph = 0.07 + ((Math.PI / 2 - 0.14) * i) / 12;
    upperSeamInk.push(spherePt(ph, Math.PI * 0.36, R * 0.995, tilt, openY));
    upperSeamWhite.push(spherePt(ph, Math.PI * 0.36 + 0.02, R * 0.995, tilt, openY));
  }
  strokePath(upperSeamInk, "micro_ink", PALETTE.inkSoft, 0.5, false, 0.2);
  strokePath(upperSeamWhite, "white_posca", PALETTE.white, 0.65, false, 0.2);

  // North Pole circular injection sprue gate (apex mould mark)
  let northSprueOuter = sphereCirclePts(Math.PI / 2, Math.PI * 0.5, 0.068, R * 0.99, tilt, 14, openY);
  let northSprueInner = sphereCirclePts(Math.PI / 2, Math.PI * 0.5, 0.028, R * 0.98, tilt, 10, openY);
  polyWash(northSprueOuter, PALETTE.clear.iceBlue, 155);
  polyWash(northSprueInner, PALETTE.white, 220);
  strokePath(northSprueOuter, "micro_ink", PALETTE.ink, 0.65, true, 0.25);
  strokePath(northSprueInner, "micro_ink", PALETTE.ink, 0.55, true, 0.25);

  // Front Air Vent Holes (2 prominent front holes with 3D plastic wall thickness!)
  const frontHoleThetas = [Math.PI * 0.25, Math.PI * 0.75];
  for (let k = 0; k < frontHoleThetas.length; k++) {
    let th0 = frontHoleThetas[k];
    let outerHole = sphereCirclePts(1.02, th0, 0.082, R * 0.995, tilt, 16, openY);
    let innerHole = sphereCirclePts(1.02, th0, 0.082, R * 0.955, tilt, 16, openY);
    polyWash(outerHole, PALETTE.clear.iceBlue, 195);
    polyWash(innerHole, PALETTE.bgPink, 175);
    strokePath(innerHole, "micro_ink", PALETTE.inkSoft, 0.55, true, 0.25);
    strokePath(outerHole, "liner_ink", PALETTE.ink, 0.8, true, 0.25);

    // Bright white specular rim glint on bottom lip of each vent hole
    let lipGlint = [];
    for (let s = 2; s <= 7; s++) {
      let a = (s / 16) * Math.PI * 2;
      let ph = 1.02 + 0.082 * Math.sin(a);
      let th = th0 + (0.082 * Math.cos(a)) / Math.cos(1.02);
      lipGlint.push(spherePt(ph, th, R * 0.998, tilt, openY));
    }
    strokePath(lipGlint, "white_posca", PALETTE.white, 1.15, false, 0.25);
  }

  // --- STEP 9: Obsessive Studio Specular Glints on Clear Dome ---
  // 1. Primary Split Curved Softbox Window Reflection (upper-left quadrant)
  let specWindow1 = spherePatchPts(0.24, 0.66, Math.PI * 0.62, Math.PI * 0.86, R * 0.96, tilt, 10, 4, openY);
  let specWindow2 = spherePatchPts(0.72, 1.02, Math.PI * 0.60, Math.PI * 0.84, R * 0.96, tilt, 10, 4, openY);

  // Cyan/Mint chromatic refraction halo just underneath the studio reflection
  let specHalo1 = spherePatchPts(0.21, 0.64, Math.PI * 0.60, Math.PI * 0.84, R * 0.96, tilt, 10, 3, openY);
  polyWash(specHalo1, PALETTE.clear.seamCyan, 150);

  polyWash(specWindow1, PALETTE.white, 245);
  polyHatch(specWindow1, "white_posca", PALETTE.white, 1.2, 3.5, -45, { rand: 0.01 });
  strokePath(specWindow1, "white_posca", PALETTE.white, 1.1, true, 0.2);

  polyWash(specWindow2, PALETTE.white, 240);
  polyHatch(specWindow2, "white_posca", PALETTE.white, 1.1, 3.5, -45, { rand: 0.01 });
  strokePath(specWindow2, "white_posca", PALETTE.white, 1.0, true, 0.2);

  // 2. Opposite Side Rim Reflection Ribbon (cool baby-blue & butter-yellow bounce)
  let rightRimGlow = spherePatchPts(0.18, 0.88, Math.PI * 0.07, Math.PI * 0.19, R * 0.95, tilt, 8, 5, openY);
  polyWash(rightRimGlow, PALETTE.yellow.light, 175);
  polyWash(rightRimGlow, PALETTE.white, 195);
  strokePath(rightRimGlow, "white_posca", PALETTE.white, 0.95, true, 0.25);

  // 3. Sharp Pill Catchlights & Star Glints
  let pillPts = makeEllipsePts(-R * 0.22, -R * 0.72 + openY, R * 0.065, R * 0.032, 12);
  polyWash(pillPts, PALETTE.white, 250);
  strokePath(pillPts, "white_posca", PALETTE.white, 1.0, true, 0.25);

  let dotPts = makeEllipsePts(-R * 0.08, -R * 0.78 + openY, R * 0.025, R * 0.02, 10);
  polyWash(dotPts, PALETTE.white, 250);

  // --- STEP 10: Deadpan Sticker-Like Outer Outline in Thin Black Ink ---
  // Includes the signature protruding equatorial flange steps at left & right!
  let outerContour = [];
  let flangeW = R * 1.038;
  let flangeTopY = -R * 0.068 * Math.cos(tilt) + openY;
  let flangeMidY = openY * 0.5;
  let flangeBotY = R * 0.068 * Math.cos(tilt);

  // Top clear dome outer arc (from right flange top up and around to left flange top)
  for (let i = 0; i <= 36; i++) {
    let a = -0.06 - ((Math.PI - 0.12) * i) / 36;
    outerContour.push([Math.cos(a) * R, Math.sin(a) * R + openY]);
  }
  // Left equatorial flange step
  outerContour.push([-flangeW, flangeTopY]);
  outerContour.push([-flangeW, flangeMidY]);
  outerContour.push([-flangeW, flangeBotY]);

  // Bottom colored shell outer arc (from left flange bottom down and around to right flange bottom)
  for (let i = 0; i <= 36; i++) {
    let a = Math.PI - 0.06 - ((Math.PI - 0.12) * i) / 36;
    outerContour.push([Math.cos(a) * R, Math.sin(a) * R]);
  }
  // Right equatorial flange step
  outerContour.push([flangeW, flangeBotY]);
  outerContour.push([flangeW, flangeMidY]);
  outerContour.push([flangeW, flangeTopY]);

  // Double-pass crisp black rotring/liner ink for even sticker-like outline
  strokePath(outerContour, "liner_ink", PALETTE.ink, 1.35, true, 0.12);

  popM();
}

// ============================================================================
// FOLDED GASHAPON PAPER LEAFLET INSERT (MINI-CATALOG SLIP)
// ============================================================================
function drawGachaLeaflet(R, tilt, shellColor) {
  let rad = R * 0.9;
  // Two accordion-folded panels hugging the back-left or back-right interior wall
  let panel1 = spherePatchPts(-0.32, 0.42, Math.PI * 1.12, Math.PI * 1.48, rad, tilt, 8, 4, 0);
  let panel2 = spherePatchPts(-0.32, 0.42, Math.PI * 1.48, Math.PI * 1.84, rad * 0.96, tilt, 8, 4, 0);

  polyWash(panel1, PALETTE.cream, 240);
  polyWash(panel2, PALETTE.leafletShadow, 235);

  // Vivid graphic header stripe on leaflet
  let bannerCol = shellColor === "mint" ? PALETTE.coral.mid : shellColor === "yellow" ? PALETTE.blue.mid : PALETTE.mint.mid;
  let banner1 = spherePatchPts(0.24, 0.38, Math.PI * 1.15, Math.PI * 1.46, rad, tilt, 6, 2, 0);
  let banner2 = spherePatchPts(0.24, 0.38, Math.PI * 1.50, Math.PI * 1.81, rad * 0.96, tilt, 6, 2, 0);
  polyWash(banner1, bannerCol, 230);
  polyWash(banner2, PALETTE.yellow.mid, 230);

  // Tiny thumbnail color squares on the leaflet
  let thumbCols = [PALETTE.mint.mid, PALETTE.yellow.mid, PALETTE.blue.mid];
  for (let i = 0; i < 3; i++) {
    let thA = Math.PI * (1.17 + i * 0.095);
    let box = spherePatchPts(-0.05, 0.14, thA, thA + 0.07, rad, tilt, 3, 2, 0);
    polyWash(box, thumbCols[i], 225);
    strokePath(box, "micro_ink", PALETTE.inkSoft, 0.45, true, 0.05);
  }

  // Tiny faux-print lines on panel 2
  for (let i = 0; i < 3; i++) {
    let ph = -0.18 + i * 0.14;
    let pA = spherePt(ph, Math.PI * 1.53, rad * 0.96, tilt, 0);
    let pB = spherePt(ph, Math.PI * 1.78, rad * 0.96, tilt, 0);
    strokeSeg(pA[0], pA[1], pB[0], pB[1], "micro_ink", PALETTE.inkSoft, 0.45);
  }

  // Crease line & outer paper border
  let cTop = spherePt(0.42, Math.PI * 1.48, rad, tilt, 0);
  let cBot = spherePt(-0.32, Math.PI * 1.48, rad, tilt, 0);
  strokeSeg(cTop[0], cTop[1], cBot[0], cBot[1], "micro_ink", PALETTE.inkSoft, 0.55);
  strokePath(panel1, "micro_ink", PALETTE.ink, 0.65, true, 0.1);
  strokePath(panel2, "micro_ink", PALETTE.ink, 0.65, true, 0.1);
}

// ============================================================================
// FIGURINE 1: GLOSSY CHIBI CAT (MANEKI-NEKO CAPSULE TOY)
// ============================================================================
function drawCatFigurine(s, variant, shellColor) {
  // Pick contrasting triad accents for ear patches & collar
  let patch1 = shellColor === "mint" ? PALETTE.yellow : PALETTE.mint;
  let patch2 = shellColor === "blue" ? PALETTE.coral : PALETTE.blue;
  let collarCol = variant === 0 ? PALETTE.coral.mid : variant === 1 ? PALETTE.blue.deep : PALETTE.mint.deep;

  // 1. Curled Tail on right hip
  let tailPts = [
    [28 * s, 38 * s],
