// ============================================================================
// FIGURINE 2: GLOSSY PLEATED DUMPLING (XIAO LONG BAO MASCOT ON SAUCER)
// ============================================================================
function drawDumplingFigurine(s, variant, shellColor) {
  let saucerPal = shellColor === "mint" ? PALETTE.blue : shellColor === "blue" ? PALETTE.mint : PALETTE.blue;

  // 1. Scalloped Porcelain Steamer Dish / Leaf Saucer at Base
  let saucerOuter = makeEllipsePts(0, 42 * s, 54 * s, 20 * s, 24);
  let saucerInner = makeEllipsePts(0, 39 * s, 44 * s, 14 * s, 20);
  polyWash(saucerOuter, saucerPal.mid, 250);
  polyHatch(saucerOuter, "chisel_marker", saucerPal.deep, 1.0, 5.5, 0);
  polyWash(saucerInner, saucerPal.deep, 215);
  strokePath(saucerOuter, "liner_ink", PALETTE.ink, 0.95, true, 0.25);
  strokePath(saucerInner, "micro_ink", saucerPal.line, 0.65, true, 0.25);

  // Saucer rim white specular streak
  let saucerGlint = [];
  for (let i = 2; i <= 9; i++) {
    let a = (Math.PI * i) / 14;
    saucerGlint.push([Math.cos(a) * 50 * s, 42 * s + Math.sin(a) * 17 * s]);
  }
  strokePath(saucerGlint, "white_posca", PALETTE.white, 1.15, false, 0.25);

  // 2. Plump Squishy Steamed Bao Body (Butter-Cream & Golden Glaze)
  let baoPts = [
    [0 * s, -54 * s], // Top twisted crown knot
    [16 * s, -48 * s],
    [38 * s, -34 * s],
    [52 * s, -8 * s],
    [50 * s, 22 * s],
    [34 * s, 40 * s],
    [0 * s, 44 * s],
    [-34 * s, 40 * s],
    [-50 * s, 22 * s],
    [-52 * s, -8 * s],
    [-38 * s, -34 * s],
    [-16 * s, -48 * s]
  ];
  polyWash(baoPts, PALETTE.yellow.light, 255);

  // Warm butter-yellow & honey-gold glaze shading on lower half & sides
  let baoMidShade = [
    [-50 * s, -6 * s],
    [-25 * s, 14 * s],
    [25 * s, 14 * s],
    [50 * s, -6 * s],
    [48 * s, 22 * s],
    [34 * s, 40 * s],
    [0 * s, 44 * s],
    [-34 * s, 40 * s],
    [-48 * s, 22 * s]
  ];
  polyWash(baoMidShade, PALETTE.yellow.bright, 225);
  polyHatch(baoMidShade, "chisel_marker", PALETTE.yellow.mid, 1.0, 5.5, 18);

  let baoDeepBase = [
    [-44 * s, 18 * s],
    [0 * s, 28 * s],
    [44 * s, 18 * s],
    [34 * s, 40 * s],
    [0 * s, 44 * s],
    [-34 * s, 40 * s]
  ];
  polyWash(baoDeepBase, PALETTE.yellow.mid, 210);
  polyHatch(baoDeepBase, "chisel_marker", PALETTE.yellow.deep, 0.9, 5, -12);

  // Cool mint/sky bounce reflection on far left & right edges of the dough
  let leftBounce = makeEllipsePts(-43 * s, 4 * s, 6 * s, 18 * s, 12);
  let rightBounce = makeEllipsePts(43 * s, 4 * s, 6 * s, 18 * s, 12);
  polyWash(leftBounce, PALETTE.mint.light, 195);
  polyWash(rightBounce, PALETTE.blue.light, 195);

  // 3. Sculpted Radial Dough Pleats (9 radial folds converging to top knot!)
  const pleatAngles = [-1.22, -0.92, -0.62, -0.31, 0.0, 0.31, 0.62, 0.92, 1.22];
  for (let i = 0; i < pleatAngles.length; i++) {
    let a = pleatAngles[i];
    let xTop = Math.sin(a) * 6 * s;
    let yTop = -48 * s + Math.cos(a) * 3 * s;
    let xMid = Math.sin(a) * 24 * s;
    let yMid = -32 * s + (1 - Math.cos(a)) * 10 * s;
    let xBot = Math.sin(a) * 39 * s;
    let yBot = -14 * s + (1 - Math.cos(a)) * 14 * s;

    // Golden shadow valley in each pleat
    let valleyPts = [
      [xTop, yTop],
      [xMid + 3.5 * s, yMid],
      [xBot, yBot],
      [xMid - 1.5 * s, yMid]
    ];
    polyWash(valleyPts, PALETTE.yellow.mid, 210);

    // Crisp crease line + parallel white vinyl ridge highlight
    strokePath([[xTop, yTop], [xMid, yMid], [xBot, yBot]], "micro_ink", PALETTE.yellow.line, 0.65, false, 0.3);
    strokePath(
      [
        [xTop + 2.2 * s, yTop + 1 * s],
        [xMid + 2.8 * s, yMid + 1 * s],
        [xBot + 2.2 * s, yBot + 1 * s]
      ],
      "white_posca",
      PALETTE.white,
      0.95,
      false,
      0.3
    );
  }

  // Top spiral knot dimple
  let knotDimple = makeEllipsePts(0, -49 * s, 8 * s, 4.5 * s, 12);
  polyWash(knotDimple, PALETTE.yellow.deep, 210);
  strokePath(knotDimple, "micro_ink", PALETTE.ink, 0.65, true, 0.25);

  // Outer silhouette ink contour of the dumpling
  strokePath(baoPts, "liner_ink", PALETTE.ink, 1.0, true, 0.28);

  // 4. Stubby Little Dough Hands Pressed to Tummy
  let lHand = makeEllipsePts(-32 * s, 20 * s, 9 * s, 7 * s, 12);
  let rHand = makeEllipsePts(32 * s, 20 * s, 9 * s, 7 * s, 12);
  polyWash(lHand, PALETTE.yellow.light, 250);
  polyWash(rHand, PALETTE.yellow.light, 250);
  strokePath(lHand, "liner_ink", PALETTE.ink, 0.8, true, 0.25);
  strokePath(rHand, "liner_ink", PALETTE.ink, 0.8, true, 0.25);

  // 5. Kawaii Glossy Face (Big Rosy Cheeks, Bead Eyes, Joyful Mouth)
  let lCheek = makeEllipsePts(-27 * s, 5 * s, 10 * s, 6.5 * s, 14);
  let rCheek = makeEllipsePts(27 * s, 5 * s, 10 * s, 6.5 * s, 14);
  polyWash(lCheek, PALETTE.coral.mid, 230);
  polyWash(rCheek, PALETTE.coral.mid, 230);
  // White gloss slash on cheeks
  strokeSeg(-30 * s, 3 * s, -25 * s, 3 * s, "white_posca", PALETTE.white, 0.9);
  strokeSeg(25 * s, 3 * s, 30 * s, 3 * s, "white_posca", PALETTE.white, 0.9);

  // Glossy Dark Bead Eyes
  const eyeX = [-16 * s, 16 * s];
  for (let i = 0; i < 2; i++) {
    let ex = eyeX[i];
    let ey = -1 * s;
    let ePts = makeEllipsePts(ex, ey, 6.2 * s, 6.8 * s, 14);
    polyWash(ePts, PALETTE.ink, 255);
    let c1 = makeEllipsePts(ex - 2 * s, ey - 2.2 * s, 2.5 * s, 2.5 * s, 10);
    let c2 = makeEllipsePts(ex + 1.8 * s, ey + 2 * s, 1.3 * s, 1.3 * s, 8);
    polyWash(c1, PALETTE.white, 255);
    polyWash(c2, PALETTE.white, 255);
  }

  // Happy open bean mouth with glossy pink tongue
  let mouthPts = [
    [-7 * s, 3 * s],
    [7 * s, 3 * s],
    [6 * s, 12 * s],
    [0 * s, 15 * s],
    [-6 * s, 12 * s]
  ];
  polyWash(mouthPts, PALETTE.coral.deep, 250);
  let tonguePts = makeEllipsePts(0, 11 * s, 4.8 * s, 3.2 * s, 10);
  polyWash(tonguePts, PALETTE.coral.bright, 245);
  strokePath(mouthPts, "micro_ink", PALETTE.ink, 0.75, true, 0.25);

  // 6. Fat Ceramic-Vinyl Studio Specular Glints on Cheek Bulges
  let cheekGlintL = makeEllipsePts(-35 * s, -14 * s, 8 * s, 4.2 * s, 12);
  polyWash(cheekGlintL, PALETTE.white, 252);
  strokePath(cheekGlintL, "white_posca", PALETTE.white, 0.95, true, 0.25);

  let cheekGlintR = makeEllipsePts(32 * s, -16 * s, 5 * s, 2.8 * s, 10);
  polyWash(cheekGlintR, PALETTE.white, 245);
}

// ============================================================================
// FIGURINE 3: GLOSSY CHUBBY BUNNY (USAGI HOLDING STAR/HEART CHARM)
// ============================================================================
function drawBunnyFigurine(s, variant, shellColor) {
  // Body color contrasts with capsule shell color
  let bodyPal =
    shellColor === "mint"
      ? variant === 0
        ? PALETTE.yellow
        : { light: PALETTE.cream, bright: "#FFF6FA", mid: "#DCE6F5", deep: "#B8CAE8", line: PALETTE.ink }
      : shellColor === "yellow"
        ? PALETTE.blue
        : PALETTE.mint;

  let charmPal = shellColor === "yellow" ? PALETTE.mint : PALETTE.yellow;

  // 1. Round Cotton Puff Tail peeking on right side
  let tailPts = makeEllipsePts(36 * s, 38 * s, 11 * s, 11 * s, 14);
  polyWash(tailPts, PALETTE.white, 250);
  strokePath(tailPts, "liner_ink", PALETTE.ink, 0.85, true, 0.25);

  // 2. Plump Pear-Shaped Vinyl Body
  let bodyPts = [
    [-28 * s, -2 * s],
    [28 * s, -2 * s],
    [40 * s, 26 * s],
    [34 * s, 50 * s],
    [0 * s, 55 * s],
    [-34 * s, 50 * s],
    [-40 * s, 26 * s]
  ];
  polyWash(bodyPts, bodyPal.light, 252);
  let bodyShade = [
    [-38 * s, 20 * s],
    [-18 * s, 36 * s],
    [18 * s, 36 * s],
    [38 * s, 20 * s],
    [34 * s, 50 * s],
    [0 * s, 55 * s],
    [-34 * s, 50 * s]
  ];
  polyWash(bodyShade, bodyPal.mid, 210);
  polyHatch(bodyShade, "chisel_marker", bodyPal.deep, 0.9, 5.5, 20);
  strokePath(bodyPts, "liner_ink", PALETTE.ink, 0.95, true, 0.28);

  // Out-turned Bunny Feet with Pink Sole Pads
  const footX = [-26 * s, 26 * s];
  for (let i = 0; i < 2; i++) {
    let fx = footX[i];
    let fPts = makeEllipsePts(fx, 48 * s, 13 * s, 10 * s, 14);
    polyWash(fPts, bodyPal.light, 252);
    strokePath(fPts, "liner_ink", PALETTE.ink, 0.9, true, 0.25);
    let padPts = makeEllipsePts(fx, 49 * s, 6 * s, 4.5 * s, 10);
    polyWash(padPts, PALETTE.coral.mid, 235);
  }

  // 3. Tall Sculpted Bunny Ears (Left upright, Right playfully curved)
  let lEarPts = [
    [-26 * s, -36 * s],
    [-34 * s, -68 * s],
    [-26 * s, -90 * s],
    [-14 * s, -88 * s],
    [-8 * s, -64 * s],
    [-10 * s, -36 * s]
  ];
  let rEarPts = [
    [10 * s, -36 * s],
    [12 * s, -64 * s],
    [24 * s, -86 * s],
    [38 * s, -80 * s],
    [38 * s, -56 * s],
    [26 * s, -36 * s]
  ];
  polyWash(lEarPts, bodyPal.light, 252);
  polyWash(rEarPts, bodyPal.light, 252);
  polyHatch(lEarPts, "blend_marker", bodyPal.mid, 0.85, 5, -75);
  polyHatch(rEarPts, "blend_marker", bodyPal.mid, 0.85, 5, 65);

  // Scooped Pink Inner Ears
  let lInner = [
    [-22 * s, -42 * s],
    [-27 * s, -66 * s],
    [-21 * s, -80 * s],
    [-14 * s, -64 * s],
    [-14 * s, -42 * s]
  ];
  let rInner = [
    [15 * s, -42 * s],
    [17 * s, -62 * s],
    [26 * s, -76 * s],
    [31 * s, -58 * s],
    [22 * s, -42 * s]
  ];
  polyWash(lInner, PALETTE.coral.mid, 235);
  polyWash(rInner, PALETTE.coral.mid, 235);
  strokePath(lInner, "micro_ink", PALETTE.coral.deep, 0.55, true, 0.25);
  strokePath(rInner, "micro_ink", PALETTE.coral.deep, 0.55, true, 0.25);

  // Long white vinyl specular streaks down both ears
  strokePath([[-24 * s, -82 * s], [-28 * s, -64 * s], [-24 * s, -48 * s]], "white_posca", PALETTE.white, 1.15, false, 0.25);
  strokePath([[26 * s, -78 * s], [32 * s, -62 * s], [26 * s, -46 * s]], "white_posca", PALETTE.white, 1.15, false, 0.25);

  strokePath(lEarPts, "liner_ink", PALETTE.ink, 0.95, true, 0.28);
  strokePath(rEarPts, "liner_ink", PALETTE.ink, 0.95, true, 0.28);

  // 4. Chubby Cheeked Bunny Head
  let headPts = makeEllipsePts(0, -18 * s, 44 * s, 30 * s, 24);
