    [-20 * s, 2 * s],
    [20 * s, 2 * s],
    [42 * s, -12 * s],
    [32 * s, 6 * s],
    [0 * s, 12 * s],
    [-32 * s, 6 * s]
  ];
  polyWash(headShade, bodyPal.mid, 195);
  strokePath(headPts, "liner_ink", PALETTE.ink, 1.0, true, 0.25);

  // 5. Miniature Glossy Star Charm Held in Clasped Paws
  let starPts = [];
  for (let i = 0; i < 10; i++) {
    let a = -Math.PI / 2 + (i * Math.PI) / 5;
    let rad = i % 2 === 0 ? 16 * s : 8 * s;
    starPts.push([Math.cos(a) * rad, 22 * s + Math.sin(a) * rad]);
  }
  polyWash(starPts, charmPal.mid, 252);
  polyHatch(starPts, "chisel_marker", charmPal.deep, 0.85, 4, 30);
  strokePath(starPts, "liner_ink", PALETTE.ink, 0.85, true, 0.15);
  let starGlint = makeEllipsePts(-4 * s, 17 * s, 4 * s, 2.5 * s, 10);
  polyWash(starGlint, PALETTE.white, 255);

  // Clasped Bunny Paws holding the Star
  let lPaw = makeEllipsePts(-17 * s, 20 * s, 10 * s, 8 * s, 12);
  let rPaw = makeEllipsePts(17 * s, 20 * s, 10 * s, 8 * s, 12);
  polyWash(lPaw, bodyPal.light, 252);
  polyWash(rPaw, bodyPal.light, 252);
  strokePath(lPaw, "liner_ink", PALETTE.ink, 0.85, true, 0.25);
  strokePath(rPaw, "liner_ink", PALETTE.ink, 0.85, true, 0.25);

  // 6. Face & Vinyl Specular Highlights
  let lBlush = makeEllipsePts(-26 * s, -10 * s, 8 * s, 4.8 * s, 12);
  let rBlush = makeEllipsePts(26 * s, -10 * s, 8 * s, 4.8 * s, 12);
  polyWash(lBlush, PALETTE.coral.mid, 225);
  polyWash(rBlush, PALETTE.coral.mid, 225);

  // Big Glossy Oval Eyes
  const eyeX = [-17 * s, 17 * s];
  for (let i = 0; i < 2; i++) {
    let ex = eyeX[i];
    let ey = -17 * s;
    let ePts = makeEllipsePts(ex, ey, 6.5 * s, 7.8 * s, 14);
    polyWash(ePts, PALETTE.ink, 255);
    let c1 = makeEllipsePts(ex - 2 * s, ey - 2.5 * s, 2.6 * s, 2.6 * s, 10);
    let c2 = makeEllipsePts(ex + 2 * s, ey + 2.2 * s, 1.4 * s, 1.4 * s, 8);
    polyWash(c1, PALETTE.white, 255);
    polyWash(c2, PALETTE.white, 255);
  }

  // Cute pink 'Y' nose & mouth
  let noseDot = makeEllipsePts(0, -12 * s, 3.2 * s, 2.4 * s, 8);
  polyWash(noseDot, PALETTE.coral.deep, 245);
  strokeSeg(0, -10 * s, 0, -5 * s, "micro_ink", PALETTE.ink, 0.7);
  strokeSeg(0, -5 * s, -5 * s, -3 * s, "micro_ink", PALETTE.ink, 0.7);
  strokeSeg(0, -5 * s, 5 * s, -3 * s, "micro_ink", PALETTE.ink, 0.7);

  // Forehead & Cheek Vinyl Specular Glint
  let headGlint = makeEllipsePts(-14 * s, -36 * s, 11 * s, 4.5 * s, 12);
  polyWash(headGlint, PALETTE.white, 252);
  strokePath(headGlint, "white_posca", PALETTE.white, 0.95, true, 0.25);
}

// Hyperreal Stereoscope Card: Two Views of a Fried Egg in a Cast-Iron Skillet
// Rendered in graphite, charcoal, sepia wash, vivid amber-saffron tones, and white gouache

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1898);
  noiseSeed(1898);

  // Crisp opaque gouache brush for wet highlights on yolk and blistered albumen
  brush.add("gouache", {
    type: "default",
    weight: 3.2,
    scatter: 0.06,
    sharpness: 0.88,
    grain: 0.12,
    opacity: 250,
    spacing: 0.15,
    pressure: [0.6, 1.25, 0.35],
    noise: 0.18
  });

  // Ultra-fine etching needle / 4H graphite pencil for seasoned iron & typography
  brush.add("needle", {
    type: "default",
    weight: 0.55,
    scatter: 0.04,
    sharpness: 0.92,
    grain: 0.3,
    opacity: 200,
    spacing: 0.18,
    pressure: [0.5, 1.0, 0.5],
    noise: 0.25
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#14100d");

  // 1. Dark Collector's Tabletop Background
  drawTabletopBackground();

  // Stereocard dimensions
  const cardX = 56;
  const cardY = 196;
  const cardW = 1088;
  const cardH = 808;
  const cardR = 26;

  // Arched window dimensions
  const wxL = 142;
  const wxR = 606;
  const wy = 244;
  const ww = 452;
  const wh = 632;
  const archH = 76;

  // 2. Trompe-l'oeil Drop Shadow beneath the Stereocard
  drawCardDropShadow(cardX, cardY, cardW, cardH, cardR);

  // 3. Buff Stereoscope Mount Base
  drawBuffCardMount(cardX, cardY, cardW, cardH, cardR);

  // 4. Left & Right Stereoscopic Views (eye = -1 for Left, eye = +1 for Right)
  drawStereoView(wxL, wy, ww, wh, archH, -1);
  drawStereoView(wxR, wy, ww, wh, archH, 1);

  // 5. Restore Crisp Arched Window Spandrels & Recessed Photo Borders
  drawArchSpandrelsAndBorders(wxL, wy, ww, wh, archH);
  drawArchSpandrelsAndBorders(wxR, wy, ww, wh, archH);

  // 6. Printed Stereocard Captions, Margin Titles & Ornaments
  drawStereocardTypography(cardX, cardY, cardW, cardH, wxL, wxR, wy, ww, wh);

  // 7. Vintage Foxing Spots & Age Staining
  drawFoxingAndPatina(cardX, cardY, cardW, cardH, wxL, wxR, wy, ww, wh);

  // 8. Creased Top-Right Corner & Card Edge Bevels
  drawCreasedCornerAndEdges(cardX, cardY, cardW, cardH, cardR);

  noLoop();
}

// ============================================================================
// 1. TABLETOP BACKGROUND
// ============================================================================
function drawTabletopBackground() {
  brush.noStroke();
  brush.wash("#17120e", 255);
  brush.rect(0, 0, 1200, 1200);

  // Warm ambient vignette around center
  brush.wash("#241b14", 120);
  brush.circle(600, 600, 520, 0.05);
  brush.noWash();

  // Subtle horizontal walnut woodgrain lines
  for (let i = 0; i < 220; i++) {
    let y = map(i, 0, 219, 8, 1192) + random(-3, 3);
    if (y > 205 && y < 995) continue; // skip under card center for speed
    let col = i % 3 === 0 ? "#0d0907" : (i % 2 === 0 ? "#211812" : "#2c2018");
    brush.set("2H", col, random(0.6, 1.4));
    let x1 = 0;
    let x2 = 1200;
    let ym = y + sin(i * 7) * 6;
    brush.spline([[x1, y, 0.5], [400, ym, 0.9], [800, y - (ym - y), 0.9], [x2, y, 0.5]], 0.3);
  }

  // Side woodgrain strips left & right of card
  for (let i = 0; i < 65; i++) {
    let y = random(200, 1000);
    let col = i % 2 === 0 ? "#0c0907" : "#261c15";
    brush.set("2H", col, random(0.6, 1.2));
    brush.line(0, y, 65, y + random(-2, 2));
    brush.line(1135, y, 1200, y + random(-2, 2));
  }
}

// ============================================================================
// 2. DROP SHADOW & BUFF CARD MOUNT
// ============================================================================
function traceRoundedRect(x, y, w, h, r, curvature = 0) {
  brush.beginShape(curvature);
  const steps = 6;
  const corners = [
    { cx: x + w - r, cy: y + r, a0: -90, a1: 0 },
    { cx: x + w - r, cy: y + h - r, a0: 0, a1: 90 },
    { cx: x + r, cy: y + h - r, a0: 90, a1: 180 },
    { cx: x + r, cy: y + r, a0: 180, a1: 270 }
  ];
  for (let c of corners) {
    for (let i = 0; i <= steps; i++) {
      let a = map(i, 0, steps, c.a0, c.a1);
      brush.vertex(c.cx + cos(a) * r, c.cy + sin(a) * r);
    }
  }
  brush.endShape(true);
}

function drawCardDropShadow(x, y, w, h, r) {
  brush.noStroke();
  for (let i = 5; i >= 1; i--) {
    let offX = i * 3.2;
    let offY = i * 4.2;
    let alpha = map(i, 1, 5, 165, 38);
    brush.wash("#050302", alpha);
    traceRoundedRect(x + offX - i, y + offY - i, w + i * 2, h + i * 2, r + i);
  }
  // Extra lifted shadow beneath the creased top-right corner
  brush.wash("#040201", 190);
  brush.beginShape(0.2);
  brush.vertex(x + w - 130, y + 6);
  brush.vertex(x + w + 24, y + 18);
  brush.vertex(x + w + 22, y + 155);
  brush.vertex(x + w - 10, y + 140);
  brush.endShape(true);
  brush.noWash();
}

function drawBuffCardMount(x, y, w, h, r) {
  // Solid warm buff base wash
  brush.noStroke();
  brush.wash("#e6ce9c", 255);
  traceRoundedRect(x, y, w, h, r);
  brush.noWash();

  // Watercolor buff texture pass for organic antique cardboard grain
  brush.fill("#dbb876", 95);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.68, 0.42);
  traceRoundedRect(x + 3, y + 3, w - 6, h - 6, r - 2);
  brush.noFill();

  // Subtle warm golden-ochre age darkening around outer margins
  brush.fill("#c79b52", 52);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.55, 0.5);
  traceRoundedRect(x + 2, y + 2, w - 4, h - 4, r - 2);
  brush.noFill();

  // Fine cardboard fiber cross-grain across the margins
  randomSeed(2201);
  for (let i = 0; i < 380; i++) {
    let px = random(x + 10, x + w - 10);
    let py = random(y + 10, y + h - 10);
    // Focus mostly on margins and bottom strip
    if (px > 148 && px < 1052 && py > 250 && py < 870) continue;
    let len = random(8, 28);
    let ang = random(-8, 8) + (random() < 0.25 ? 90 : 0);
    let col = random() < 0.5 ? "#cfa968" : (random() < 0.5 ? "#f2e1bc" : "#bfa67a");
    brush.set("2H", col, random(0.4, 0.9));
    brush.line(px, py, px + cos(ang) * len, py + sin(ang) * len);
  }
}

// ============================================================================
// 3. STEREOSCOPIC HYPERREAL VIEW (FRIED EGG IN CAST-IRON SKILLET)
// ============================================================================
function drawStereoView(wx, wy, ww, wh, archH, eye) {
  // Deterministic seed so both views depict the EXACT same physical egg & skillet
  // displaced solely by true 3D stereoscopic parallax (`eye` = -1 or +1)
  randomSeed(7777);
  noiseSeed(7777);

  push();
  brush.clip([wx, wy, wx + ww, wy + wh]);

  const cx = wx + ww * 0.5;
  const cy = wy + wh * 0.535;
  const aspectY = 0.875; // Perspective tilt of circular skillet

  // Stereoscopic 3D projection: maps local skillet coords (lx, ly, lz) to canvas (sx, sy)
  // Higher lz pops forward (shifts inward toward center bridge in stereo pair)
  function proj(lx, ly, lz) {
    const rot = -eye * 0.017; // ~1 degree horizontal viewing angle difference
    const rx = lx * cos(rot) - ly * sin(rot);
    const ry = (lx * sin(rot) + ly * cos(rot)) * aspectY;
    const scaleZ = 1 + lz * 0.0014;
    const parallaxX = -eye * (lz - 14) * 0.25;
    return [
      cx + rx * scaleZ + parallaxX,
      cy + ry * scaleZ - lz * 0.19
    ];
  }

  // Skillet radius with two classic side pouring spouts at 5° and 175°
  function getSkilletRimR(ang, baseR) {
    let d1 = ((ang - 5 + 540) % 360) - 180;
    let d2 = ((ang - 175 + 540) % 360) - 180;
    let spout1 = 23 * exp(-pow(d1 / 13.5, 2));
    let spout2 = 23 * exp(-pow(d2 / 13.5, 2));
    return baseR + spout1 + spout2;
  }

  // Egg white outer lacy perimeter radius at angle a
  function getEggWhiteR(ang) {
    let r = 126
      + 11 * sin(ang * 2 + 25)
      + 7.5 * cos(ang * 3 - 40)
      + 5.5 * sin(ang * 5 + 110)
      + 4.0 * cos(ang * 7 - 15)
      + 2.8 * sin(ang * 11 + 60)
      + 2.2 * cos(ang * 17);
    return r;
  }

  // Thick inner albumen collar radius around the yolk
  function getInnerCollarR(ang) {
    return 71
      + 6.5 * sin(ang * 2 - 20)
      + 4.2 * cos(ang * 3 + 55)
      + 2.5 * sin(ang * 5 - 30);
  }

  // --- STEP A: Albumen Photograph Base & Dark Sepia Stove Backdrop ---
  brush.noStroke();
  brush.wash("#e6d1ae", 255);
  brush.rect(wx, wy, ww, wh);

  // Dark sepia-graphite background surrounding the skillet
  brush.wash("#2a1e16", 235);
  brush.rect(wx, wy, ww, wh);
  brush.noWash();

  brush.fill("#1c130d", 130);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.65, 0.5);
  brush.rect(wx + 4, wy + 4, ww - 8, wh - 8);
  brush.noFill();

  // Background cross-hatching in sepia and dark graphite (stove grate texture)
  brush.hatchStyle("2B", "#140e0a", 1.0);
  brush.hatch(9, 35, { rand: 0.08 });
  brush.noStroke();
  brush.rect(wx + 2, wy + 2, ww - 4, wh - 4);
  brush.noHatch();

  brush.hatchStyle("HB", "#38281c", 0.85);
  brush.hatch(11, -45, { rand: 0.08 });
  brush.noStroke();
  brush.rect(wx + 2, wy + 2, ww - 4, wh - 4);
  brush.noHatch();

  // Subtle circular stove burner ring lines behind skillet in top/bottom corners
  for (let r = 225; r <= 315; r += 22) {
    brush.set("2B", r % 44 === 0 ? "#0e0a07" : "#423124", 1.2);
    brush.beginShape(0.3);
    for (let a = 0; a <= 360; a += 12) {
      let [px, py] = proj(cos(a) * r, sin(a) * r, -10);
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }

  // --- STEP B: Cast-Iron Skillet Handle (Bottom-Right) & Helper Tab (Top-Left) ---
  // Helper tab handle at angle 242° (upper-left)
  brush.noStroke();
  brush.wash("#1b1512", 250);
  brush.beginShape(0.25);
  for (let a = 226; a <= 258; a += 4) {
    let r = 198 + 26 * sin(map(a, 226, 258, 0, 180));
    let [px, py] = proj(cos(a) * r, sin(a) * r, 26);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // Main Skillet Handle extending down-right at angle 62°
  const hAng = 62;
  const hCos = cos(hAng), hSin = sin(hAng);
  const pCos = cos(hAng + 90), pSin = sin(hAng + 90);

  function handlePt(dist, across, z) {
    return proj(hCos * dist + pCos * across, hSin * dist + pSin * across, z);
  }

  // Handle shadow underneath
  brush.noStroke();
  brush.wash("#0b0806", 230);
  brush.beginShape(0.2);
  let hpShadow = [
    [185, -36], [235, -24], [320, -28], [355, -20],
    [355, 20], [320, 28], [235, 24], [185, 36]
  ];
  for (let pt of hpShadow) {
    let [px, py] = handlePt(pt[0], pt[1] + 8, 6);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // Handle solid iron body
  brush.wash("#211a16", 255);
  brush.beginShape(0.2);
  for (let pt of hpShadow) {
    let [px, py] = handlePt(pt[0], pt[1], 28);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noWash();

  // Teardrop hanging hole in handle
  brush.wash("#140e0a", 255);
  brush.beginShape(0.3);
  for (let a = 0; a < 360; a += 20) {
    let d = 285 + cos(a) * 28;
    let w = sin(a) * (a > 90 && a < 270 ? 6.5 : 10.5);
    let [px, py] = handlePt(d, w, 28);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noWash();

  // Handle graphite hatching & metallic bevel highlights
  for (let d = 192; d <= 340; d += 4.5) {
    let hw = d < 235 ? map(d, 192, 235, 32, 21) : map(d, 235, 340, 21, 25);
    let [x1, y1] = handlePt(d, -hw, 28);
    let [x2, y2] = handlePt(d, hw, 28);
    brush.set("2H", d % 9 === 0 ? "#4a3e35" : "#14100d", 0.75);
    brush.line(x1, y1, x2, y2);
  }
  // Bright seasoned graphite ridge along handle edges
  brush.set("HB", "#9e8f7e", 1.1);
  let [hx1, hy1] = handlePt(190, -28, 29);
  let [hx2, hy2] = handlePt(330, -21, 29);
  brush.line(hx1, hy1, hx2, hy2);
  brush.set("2H", "#d4c7b6", 0.7);
  brush.line(hx1, hy1, hx2, hy2);

  // --- STEP C: Cast-Iron Skillet Bowl, Wall & Rim ---
  // 1. Skillet outer shadow on stove
  brush.noStroke();
  brush.wash("#090605", 220);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 6) {
    let r = getSkilletRimR(a, 204);
    let [px, py] = proj(cos(a) * r + 10, sin(a) * r + 14, -4);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // 2. Skillet outer rim base (lz = 28)
  brush.wash("#2b231d", 255);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 5) {
    let r = getSkilletRimR(a, 198);
    let [px, py] = proj(cos(a) * r, sin(a) * r, 28);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // 3. Skillet inner wall cavity (connects inner rim at lz=28 to floor at lz=0)
  brush.wash("#17120f", 255);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 5) {
    let r = getSkilletRimR(a, 183);
    let [px, py] = proj(cos(a) * r, sin(a) * r, 28);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // 4. Skillet cooking floor (lz = 0, radius = 154)
  brush.wash("#1e1814", 255);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 6) {
    let [px, py] = proj(cos(a) * 154, sin(a) * 154, 0);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noWash();

  // Watercolor sepia & charcoal tonal washes on the seasoned iron floor
  brush.fill("#2e2219", 110);
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.7, 0.45);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 8) {
    let [px, py] = proj(cos(a) * 150, sin(a) * 150, 0);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noFill();

  // 5. Fine Pencil Hatching for the Seasoned Cast Iron
  // Concentric lathe/seasoning rings on the skillet floor (visible outside the egg)
  for (let r = 108; r <= 153; r += 3.2) {
    let col = r % 6.4 < 3.2 ? "#110d0b" : (r % 9.6 < 3.2 ? "#4a3d33" : "#2b221c");
    brush.set("needle", col, 0.75);
    brush.beginShape(0.25);
    for (let a = 0; a <= 360; a += 8) {
      let [px, py] = proj(cos(a) * r, sin(a) * r, 0);
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }

  // Dense graphite cross-hatching on the skillet floor perimeter
  for (let pass = 0; pass < 3; pass++) {
    let hAngle = pass === 0 ? -32 : (pass === 1 ? 28 : 78);
    let col = pass === 0 ? "#120e0b" : (pass === 1 ? "#362b23" : "#54453a");
    for (let i = -152; i <= 152; i += 4.5) {
      let halfChord = sqrt(max(0, 152 * 152 - i * i));
      if (halfChord < 10) continue;
      // Draw chords in local rotated space, skipping middle covered by egg
      let ca = cos(hAngle), sa = sin(hAngle);
      let xA = -halfChord * ca - i * sa;
      let yA = -halfChord * sa + i * ca;
      let xB = halfChord * ca - i * sa;
      let yB = halfChord * sa + i * ca;
      let [p1x, p1y] = proj(xA, yA, 0);
      let [p2x, p2y] = proj(xB, yB, 0);
      brush.set(pass === 2 ? "2H" : "HB", col, 0.65);
      brush.line(p1x, p1y, p2x, p2y);
    }
  }

  // 6. Steep Inner Cast-Iron Wall Contour Hatching & Metallic Sheen
  // Radial vertical wall strokes connecting floor (r=154, lz=0) to inner rim (r=183, lz=28)
  for (let a = 0; a < 360; a += 1.6) {
    let rFloor = 154;
    let rRim = getSkilletRimR(a, 183);
    let [x0, y0] = proj(cos(a) * rFloor, sin(a) * rFloor, 0);
    let [x1, y1] = proj(cos(a) * rRim, sin(a) * rRim, 28);

    // Light comes from upper-left (angle ~ 225°), reflecting off the curved inner wall
    // at angles 280°..360° and 0°..35° (far right/top-right curve) and 170°..215° (left spout)
    let sheen1 = exp(-pow(((a - 320 + 540) % 360 - 180) / 36, 2));
    let sheen2 = exp(-pow(((a - 185 + 540) % 360 - 180) / 22, 2));
    let sheen = max(sheen1, sheen2 * 0.8);

    let col = "#14100d";
    let w = 0.85;
    if (sheen > 0.72) {
      col = "#c7b9a6";
      w = 0.75;
    } else if (sheen > 0.45) {
      col = "#877868";
      w = 0.8;
    } else if (sheen > 0.22) {
      col = "#4f4339";
    } else if (int(a * 10) % 2 === 0) {
      col = "#29201a";
    }
    brush.set("2H", col, w);
    brush.line(x0, y0, x1, y1);
  }

  // Horizontal contour rings up the steep inner skillet wall
  for (let step = 1; step <= 6; step++) {
    let t = step / 7;
    let z = t * 28;
    brush.set("needle", step % 2 === 0 ? "#110d0b" : "#42362d", 0.7);
    brush.beginShape(0.25);
    for (let a = 170; a <= 375; a += 6) {
      let r = lerp(154, getSkilletRimR(a % 360, 183), t);
      let [px, py] = proj(cos(a) * r, sin(a) * r, z);
      brush.vertex(px, py);
    }
    brush.endShape(false);
  }

  // 7. Skillet Top Rim Bevel & Specular Seasoned-Iron Highlights
  for (let a = 0; a < 360; a += 2) {
    let rIn = getSkilletRimR(a, 183);
    let rOut = getSkilletRimR(a, 198);
    let [x0, y0] = proj(cos(a) * rIn, sin(a) * rIn, 28);
    let [x1, y1] = proj(cos(a) * rOut, sin(a) * rOut, 28);

    // Rim catches bright overhead/upper-left studio light
    let rimLight = exp(-pow(((a - 235 + 540) % 360 - 180) / 55, 2))
                 + 0.75 * exp(-pow(((a - 15 + 540) % 360 - 180) / 35, 2));
    let col = rimLight > 0.65 ? "#dfd3c3" : (rimLight > 0.35 ? "#8c7d6d" : (rimLight > 0.15 ? "#4d4137" : "#211b16"));
    brush.set("2H", col, 0.85);
    brush.line(x0, y0, x1, y1);
  }

  // Crisp inner and outer rim edges in pencil & white gouache glints
  brush.set("HB", "#120e0b", 1.1);
  brush.beginShape(0.25);
  for (let a = 0; a <= 360; a += 5) {
    let r = getSkilletRimR(a, 198.5);
    let [px, py] = proj(cos(a) * r, sin(a) * r, 28);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // Gleaming graphite/gouache highlight arcs on the inner lip and pouring spouts
  const rimGleams = [
    { a0: 162, a1: 192, rOff: 184, col: "#f2e8d8", w: 0.9 },
    { a0: 205, a1: 278, rOff: 184, col: "#d9ccb8", w: 0.8 },
    { a0: 348, a1: 382, rOff: 184, col: "#efe4d2", w: 0.9 },
    { a0: 95, a1: 150, rOff: 196, col: "#b5a692", w: 0.75 }
  ];
  for (let g of rimGleams) {
    brush.set("needle", g.col, g.w);
    brush.beginShape(0.3);
    for (let a = g.a0; a <= g.a1; a += 3) {
      let r = getSkilletRimR(a % 360, g.rOff);
      let [px, py] = proj(cos(a) * r, sin(a) * r, 28.5);
      brush.vertex(px, py);
    }
    brush.endShape(false);
  }

  // 8. Glistening Oil & Melted Butter Droplets on the Iron Floor Around the Egg
  for (let i = 0; i < 65; i++) {
    let a = random(360);
    let minR = getEggWhiteR(a) + 3;
    let maxR = 149;
    if (minR >= maxR - 2) continue;
    let r = random(minR, maxR);
    let br = random(1.2, 4.2);
    let [bx, by] = proj(cos(a) * r, sin(a) * r, 1);

    // Dark oil bead rim
    brush.set("needle", "#0d0907", 0.65);
    brush.circle(bx, by, br, 0.15);
    // Warm amber butter reflection on lower-right
    if (br > 2.0) {
      brush.set("needle", "#b86814", 0.65);
      brush.arc(bx, by, br * 0.75, 20, 120);
    }
    // Pinpoint white specular glint on upper-left
    brush.set("gouache", "#fffef5", 0.32);
    brush.line(bx - br * 0.45, by - br * 0.45, bx - br * 0.2, by - br * 0.35);
  }

  // --- STEP D: THE HYPERREAL FRIED EGG — LACY BROWNED WHITES (ALBUMEN) ---
  // 1. Dark Caramelized Shadow & Sizzling Butter Halo under the Crispy Skirt
  brush.noStroke();
  brush.wash("#0c0704", 230);
  brush.beginShape(0.3);
  for (let a = 0; a < 360; a += 4) {
    let r = getEggWhiteR(a) + 3.5;
    let [px, py] = proj(cos(a) * r + 2.5, sin(a) * r + 3.5, 1);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // 2. Saturated Burnt-Sienna & Golden-Sepia Crispy Browned Outer Skirt (lz = 5)
  const skirtLayers = [
    { dr: 2.0, col: "#4f1e04", alpha: 245 },
    { dr: 0.0, col: "#853808", alpha: 240 },
    { dr: -3.5, col: "#ba5b12", alpha: 235 },
    { dr: -7.5, col: "#de8324", alpha: 230 },
    { dr: -12.0, col: "#ebaa4b", alpha: 225 }
  ];
  for (let sl of skirtLayers) {
    brush.wash(sl.col, sl.alpha);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 4) {
      let jitter = sin(a * 13) * 1.8 + cos(a * 23) * 1.4;
      let r = getEggWhiteR(a) + sl.dr + jitter;
      let [px, py] = proj(cos(a) * r, sin(a) * r, 5);
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 3. Main Set Albumen Body (Creamy Warm Ivory to Parchment Sepia, lz = 9)
  brush.noStroke();
  brush.wash("#e3cfb0", 250);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 5) {
    let r = getEggWhiteR(a) - 13 + sin(a * 9) * 2.5;
    let [px, py] = proj(cos(a) * r, sin(a) * r, 9);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // Watercolor wash for organic albumen translucency & warm shadow on lower-right
  brush.fill("#c9ad82", 110);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.35);
  brush.beginShape(0.35);
  for (let a = -35; a <= 165; a += 8) {
    let r = getEggWhiteR((a + 360) % 360) - 14;
    let [px, py] = proj(cos(a) * r, sin(a) * r, 9);
    brush.vertex(px, py);
  }
  for (let a = 165; a >= -35; a -= 15) {
    let [px, py] = proj(cos(a) * 45, sin(a) * 45, 9);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noFill();

  // Luminous alabaster-ivory upper-left albumen slope
  brush.wash("#f5ecdc", 230);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 6) {
    let r = getEggWhiteR(a) - 18 + cos(a * 7) * 2;
    let [px, py] = proj(cos(a) * r - 4, sin(a) * r - 4, 10);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noWash();

  // 4. Lacy Perforations (Holes in the Outer Crispy Egg White Skirt Revealing Iron Below)
  for (let i = 0; i < 62; i++) {
    let a = map(i, 0, 62, 0, 360) + random(-2.5, 2.5);
    let edgeR = getEggWhiteR(a);
    let r = edgeR - random(3.5, 22);
    let holeR = map(r, edgeR - 22, edgeR - 3.5, 1.8, 5.2) * random(0.7, 1.25);
    let [hx, hy] = proj(cos(a) * r, sin(a) * r, 6);

    // Dark seasoned iron visible through the lacy perforation
    brush.noStroke();
    brush.wash("#1c140f", 245);
    brush.circle(hx, hy, holeR, 0.25);
    brush.noWash();

    // Crispy toasted amber-brown rim around the perforation
    brush.set("rotring", "#6e2c05", 0.85);
    brush.circle(hx, hy, holeR + 0.7, 0.25);
    brush.set("needle", "#c96512", 0.75);
    brush.arc(hx, hy, holeR + 1.3, 0, 210);

    // Wet pinpoint specular glint on the bottom-right rim of the hole (facing upper-left light)
    brush.set("gouache", "#fffdf2", 0.32);
    brush.arc(hx, hy, holeR + 0.5, 25, 85);
  }

  // 5. Crispy Frizzled Filaments & Browned Lace Detail Around the Entire Egg Perimeter
  for (let a = 0; a < 360; a += 1.4) {
    let rBase = getEggWhiteR(a);
    let rIn = rBase - random(6, 19);
    let rOut = rBase + random(-2, 4.5);
    let [x0, y0] = proj(cos(a) * rIn, sin(a) * rIn, 7);
    let [x1, y1] = proj(cos(a + random(-2, 2)) * rOut, sin(a + random(-2, 2)) * rOut, 5);

    let colChoice = random();
    let col = colChoice < 0.32 ? "#4a1c03" : (colChoice < 0.65 ? "#8a3b08" : (colChoice < 0.88 ? "#c96814" : "#f0a63a"));
    brush.set(colChoice < 0.5 ? "rotring" : "needle", col, random(0.55, 0.95));
    brush.line(x0, y0, x1, y1);

    // Tiny crispy browned lace loops along the very outer edge
    if (random() < 0.38) {
      let [lx, ly] = proj(cos(a) * (rBase + 1.5), sin(a) * (rBase + 1.5), 5.5);
      brush.set("rotring", "#592204", 0.65);
      brush.circle(lx, ly, random(1.2, 3.0), 0.3);
    }
  }

  // 6. Thick Inner Coagulated Albumen Collar (The Raised White Cushion Around the Yolk, lz = 21)
  // Soft cast shadow of the inner collar onto the outer thin white (shifted down-right)
  brush.noStroke();
  brush.wash("#b5966b", 150);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 6) {
    let r = getInnerCollarR(a) + 5;
    let [px, py] = proj(cos(a) * r + 7, sin(a) * r + 8, 12);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  brush.wash("#9c7b50", 115);
  brush.beginShape(0.35);
  for (let a = -25; a <= 145; a += 6) {
    let r = getInnerCollarR((a + 360) % 360) + 2;
    let [px, py] = proj(cos(a) * r + 5, sin(a) * r + 6, 13);
    brush.vertex(px, py);
  }
  for (let a = 145; a >= -25; a -= 12) {
    let [px, py] = proj(cos(a) * 45, sin(a) * 45, 13);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // Raised inner collar body in creamy ivory & warm alabaster
  brush.wash("#ede0c7", 245);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 6) {
    let r = getInnerCollarR(a);
    let [px, py] = proj(cos(a) * r, sin(a) * r, 20);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  brush.wash("#fbf6eb", 245);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 6) {
    let r = getInnerCollarR(a) - 4;
    let [px, py] = proj(cos(a) * r - 3, sin(a) * r - 3, 22);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noWash();

  // Delicate graphite & sepia contour shading along the undulating albumen ridges
  for (let ring = 0; ring < 14; ring++) {
    let rBase = map(ring, 0, 13, 56, 112);
    let zRing = rBase < 75 ? 21 : 10;
    let aStart = random(0, 180);
    let aSpan = random(55, 140);
    let isShadowSide = ((aStart + aSpan * 0.5) % 360) < 155;
    let col = isShadowSide ? "#a68960" : "#dfd0b4";
    brush.set("needle", col, 0.6);
    brush.beginShape(0.3);
    for (let a = aStart; a <= aStart + aSpan; a += 6) {
      let r = rBase + sin(a * 4 + ring * 20) * 4.5;
      let [px, py] = proj(cos(a) * r, sin(a) * r, zRing);
      brush.vertex(px, py);
    }
    brush.endShape(false);
  }

  // Smooth gouache highlight ridge along the upper-left shoulder of the inner albumen collar
  for (let pass = 0; pass < 3; pass++) {
    brush.set("gouache", "#ffffff", 0.85 - pass * 0.2);
    brush.beginShape(0.35);
    for (let a = 175; a <= 310; a += 6) {
      let r = getInnerCollarR(a) - 3 - pass * 3.5;
      let [px, py] = proj(cos(a) * r, sin(a) * r, 23);
      brush.vertex(px, py);
    }
    brush.endShape(false);
  }

  // 7. Blistered Air Bubbles Across the Egg White
  for (let i = 0; i < 48; i++) {
    let a = random(360);
    let r = random(54, getEggWhiteR(a) - 18);
    let zBub = r < 73 ? 22 : 11;
    let rad = random(1.8, 7.2);
    let [bx, by] = proj(cos(a) * r, sin(a) * r, zBub);

    // Bubble lower-right shadow crescent
    brush.set("needle", "#9e7f56", 0.7);
    brush.arc(bx + 0.8, by + 0.8, rad, -20, 135);

    // Subtle warm dome outline
    brush.set("needle", "#cbb38c", 0.55);
    brush.circle(bx, by, rad, 0.15);

    // Crisp white gouache gleam on upper-left of bubble dome
    brush.set("gouache", "#ffffff", rad > 4 ? 0.55 : 0.35);
    brush.arc(bx - 0.4, by - 0.4, rad * 0.72, 185, 290);
  }

  // --- STEP E: THE GLOSSY YOLK DOME (VIVID SATURATED AMBER-GOLD + SEPIA + WHITE GOUACHE) ---
  const yx0 = -7;
  const yy0 = -9;
  const yolkR = 48.5;
  const zYolkBase = 23;
  const zYolkTop = 58;

  // Helper for point on the 3D yolk hemisphere (u, v in [-1, 1], u^2 + v^2 <= 1)
  function projYolk(u, v) {
    let r2 = constrain(u * u + v * v, 0, 1);
    let h = sqrt(1 - r2);
    let lx = yx0 + u * yolkR;
    let ly = yy0 + v * yolkR;
    let lz = lerp(zYolkBase, zYolkTop, h);
    return proj(lx, ly, lz);
  }

  // 1. Subsurface-Scattered Luminous Amber Cast Shadow on the Albumen (Lower-Right of Yolk)
  // Because light passes through the golden yolk like a lens, its shadow glows warm amber-sepia!
  const yolkShadowLayers = [
    { offX: 11, offY: 13, rad: yolkR + 5, col: "#b5691c", alpha: 115 },
    { offX: 8, offY: 9.5, rad: yolkR + 2.5, col: "#9e4808", alpha: 145 },
    { offX: 4.5, offY: 5.5, rad: yolkR + 0.5, col: "#732904", alpha: 185 }
  ];
  brush.noStroke();
  for (let ys of yolkShadowLayers) {
    brush.wash(ys.col, ys.alpha);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 6) {
      let [px, py] = proj(yx0 + ys.offX + cos(a) * ys.rad, yy0 + ys.offY + sin(a) * ys.rad, zYolkBase - 1);
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }

  // 2. Volumetric Spherical Layers of the Yolk Dome (Saturated Sepia-Mahogany to Fiery Saffron-Gold)
  const domeRings = [
    { scale: 1.00, uOff: 0.00, vOff: 0.00, col: "#5e1c02", alpha: 255 },
    { scale: 0.97, uOff: 0.00, vOff: 0.00, col: "#822904", alpha: 250 },
    { scale: 0.93, uOff: -0.02, vOff: -0.02, col: "#a63806", alpha: 245 },
    { scale: 0.88, uOff: -0.04, vOff: -0.04, col: "#c74d08", alpha: 240 },
    { scale: 0.82, uOff: -0.06, vOff: -0.06, col: "#de630a", alpha: 235 },
    { scale: 0.75, uOff: -0.09, vOff: -0.09, col: "#f07c0e", alpha: 235 },
    { scale: 0.67, uOff: -0.12, vOff: -0.12, col: "#fa9616", alpha: 230 },
    { scale: 0.58, uOff: -0.15, vOff: -0.15, col: "#fcae22", alpha: 225 },
    { scale: 0.48, uOff: -0.19, vOff: -0.19, col: "#fec432", alpha: 225 },
    { scale: 0.37, uOff: -0.23, vOff: -0.23, col: "#ffd94d", alpha: 220 },
    { scale: 0.26, uOff: -0.27, vOff: -0.27, col: "#ffeb75", alpha: 215 }
  ];
  for (let dr of domeRings) {
    brush.wash(dr.col, dr.alpha);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 6) {
      let u = dr.uOff + cos(a) * dr.scale * (1 - abs(dr.uOff) * 0.45);
      let v = dr.vOff + sin(a) * dr.scale * (1 - abs(dr.vOff) * 0.45);
      let mag = sqrt(u * u + v * v);
      if (mag > 0.995) {
        u = (u / mag) * 0.995;
        v = (v / mag) * 0.995;
      }
      let [px, py] = projYolk(u, v);
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // Watercolor bleed pass on yolk for saturated luminous amber depth
  brush.fill("#e86808", 85);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.45, 0.3);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 10) {
    let [px, py] = projYolk(cos(a) * 0.92, sin(a) * 0.92);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noFill();

  // 3. Reflected Bounced Light Crescent on Lower-Right Rim of Yolk (from White Albumen Below)
  for (let pass = 0; pass < 4; pass++) {
    let rScale = map(pass, 0, 3, 0.94, 0.84);
    let col = pass < 2 ? "#f59b1d" : "#ffc238";
    brush.set("cpencil", col, 1.3 - pass * 0.2);
    brush.beginShape(0.35);
    for (let a = -15; a <= 115; a += 5) {
      let [px, py] = projYolk(cos(a) * rScale, sin(a) * rScale);
      brush.vertex(px, py);
    }
    brush.endShape(false);
  }

  // Deep core shadow terminator crescent just inside the reflected rim
  for (let pass = 0; pass < 5; pass++) {
    let rScale = map(pass, 0, 4, 0.79, 0.66);
    let col = pass % 2 === 0 ? "#8f2f04" : "#ad3f06";
    brush.set("cpencil", col, 1.15);
    brush.beginShape(0.35);
    for (let a = -25; a <= 125; a += 5) {
      let [px, py] = projYolk(cos(a) * rScale, sin(a) * rScale);
      brush.vertex(px, py);
    }
    brush.endShape(false);
  }

  // 4. Fine Spherical Contour Shading & Vitelline Membrane Tension Lines
  for (let i = 0; i < 55; i++) {
    let rScale = map(i, 0, 54, 0.18, 0.97);
    let a0 = random(360);
    let aSpan = random(35, 95);
    let midA = (a0 + aSpan * 0.5) % 360;
    // Choose warm sepia, fiery orange, or golden highlight based on hemisphere angle
    let distToHighlight = abs(((midA - 225 + 540) % 360) - 180);
    let col = distToHighlight < 55 ? "#ffe36e"
            : (distToHighlight < 105 ? "#f79416"
            : (rScale > 0.88 ? "#6e2103" : "#ba4407"));
    brush.set("needle", col, 0.65);
    brush.beginShape(0.35);
    for (let a = a0; a <= a0 + aSpan; a += 5) {
      let u = cos(a) * rScale;
      let v = sin(a) * rScale;
      let [px, py] = projYolk(u, v);
      brush.vertex(px, py);
    }
    brush.endShape(false);
  }

  // Faint germinal disc (blastodisc) visible beneath the glossy yolk membrane on the right slope
  let [gdx, gdy] = projYolk(0.42, -0.12);
  brush.noStroke();
  brush.wash("#ffd46b", 135);
  brush.circle(gdx, gdy, 4.8, 0.2);
  brush.wash("#", 0);
  brush.set("needle", "#fff0a8", 0.55);
  brush.circle(gdx, gdy, 3.2, 0.2);

  // Dark burnt-umber & sepia ambient-occlusion trough where yolk tucks into albumen
  brush.set("rotring", "#3d1201", 1.1);
  brush.beginShape(0.35);
  for (let a = 0; a <= 360; a += 5) {
    let [px, py] = projYolk(cos(a) * 0.995, sin(a) * 0.995);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // --- STEP F: CRISP WHITE GOUACHE-LIKE GLEAMS ON THE YOLK & ALBUMEN ---
  // 1. Primary Studio Skylight / Four-Pane Window Reflection on Upper-Left of Yolk Dome
  // Drawn on the curved 3D sphere surface (angles 196°..262°, radii 0.34..0.72)
  const panes = [
    { a0: 198, a1: 227, r0: 0.36, r1: 0.53 },
    { a0: 232, a1: 261, r0: 0.36, r1: 0.53 },
    { a0: 198, a1: 227, r0: 0.57, r1: 0.73 },
    { a0: 232, a1: 261, r0: 0.57, r1: 0.73 }
  ];

  // Warm lemon-cream halo around the window reflection
  brush.noStroke();
  brush.wash("#fff3a1", 180);
  brush.beginShape(0.3);
  for (let a = 192; a <= 267; a += 5) {
    let [px, py] = projYolk(cos(a) * 0.32, sin(a) * 0.32);
    brush.vertex(px, py);
  }
  for (let a = 267; a >= 192; a -= 5) {
    let [px, py] = projYolk(cos(a) * 0.77, sin(a) * 0.77);
    brush.vertex(px, py);
  }
  brush.endShape(true);

  // Four crisp white gouache window panes warped over the spherical yolk dome
  for (let p of panes) {
    brush.noStroke();
    brush.wash("#ffffff", 255);
    brush.beginShape(0.2);
    for (let a = p.a0; a <= p.a1; a += 4) {
      let [px, py] = projYolk(cos(a) * p.r0, sin(a) * p.r0);
      brush.vertex(px, py);
    }
    for (let a = p.a1; a >= p.a0; a -= 4) {
      let [px, py] = projYolk(cos(a) * p.r1, sin(a) * p.r1);
      brush.vertex(px, py);
    }
    brush.endShape(true);
    brush.noWash();

    // Thick impasto gouache brush strokes filling and edging each pane
    for (let r = p.r0 + 0.02; r <= p.r1 - 0.01; r += 0.045) {
      brush.set("gouache", "#ffffff", 0.78);
      brush.beginShape(0.25);
      for (let a = p.a0; a <= p.a1; a += 4) {
        let [px, py] = projYolk(cos(a) * r, sin(a) * r);
        brush.vertex(px, py);
      }
      brush.endShape(false);
    }
  }

  // Secondary smaller catchlight glint near the apex of the yolk
  let [gx1, gy1] = projYolk(-0.14, -0.18);
  let [gx2, gy2] = projYolk(-0.05, -0.22);
  brush.set("gouache", "#ffffff", 0.95);
  brush.line(gx1, gy1, gx2, gy2);
  brush.circle(gx1 - 2, gy1 + 1, 2.2, 0.1);

  // 2. Wet Meniscus Gouache Gleams Where Yolk Meets the Albumen Collar
  const meniscusArcs = [
    { a0: 150, a1: 215, r: 0.985, w: 0.85 },
    { a0: 235, a1: 295, r: 0.985, w: 0.95 },
    { a0: 25, a1: 78, r: 0.99, w: 0.7 }
  ];
  for (let ma of meniscusArcs) {
    brush.set("gouache", "#ffffff", ma.w);
    brush.beginShape(0.35);
    for (let a = ma.a0; a <= ma.a1; a += 3) {
      let [px, py] = projYolk(cos(a) * ma.r, sin(a) * ma.r);
      brush.vertex(px, py);
    }
    brush.endShape(false);
  }

  // Secondary curved wet reflection along the lower-right shoulder of the yolk
  brush.set("gouache", "#fff9d2", 0.55);
  brush.beginShape(0.35);
  for (let a = 18; a <= 72; a += 4) {
    let [px, py] = projYolk(cos(a) * 0.89, sin(a) * 0.89);
    brush.vertex(px, py);
  }
  brush.endShape(false);

  // 3. Pinpoint Gouache Glints on Crispy Lace & Wet Albumen Ridges
  for (let i = 0; i < 38; i++) {
    let a = random(360);
    let r = random(52, getEggWhiteR(a) - 2);
    let zG = r < 73 ? 22 : (r > getEggWhiteR(a) - 14 ? 6 : 10);
    let [px, py] = proj(cos(a) * r, sin(a) * r, zG);
    brush.set("gouache", "#ffffff", random(0.3, 0.65));
    let gl = random(1.5, 4.5);
    brush.line(px, py, px + cos(a + 90) * gl, py + sin(a + 90) * gl);
  }

  // --- STEP G: CRACKED BLACK PEPPER & FLAKY SEA SALT ---
  for (let i = 0; i < 28; i++) {
    let onYolk = i < 9;
    let px, py;
    if (onYolk) {
      let a = random(360);
      let rad = random(0.15, 0.88);
      [px, py] = projYolk(cos(a) * rad, sin(a) * rad);
    } else {
      let a = random(360);
      let r = random(52, getEggWhiteR(a) - 16);
      let zP = r < 73 ? 22 : 10;
      [px, py] = proj(cos(a) * r, sin(a) * r, zP);
    }
    let pSize = random(1.0, 2.4);
    brush.noStroke();
    brush.wash("#1a110b", 245);
    brush.circle(px, py, pSize, 0.35);
    brush.noWash();
    // Tiny warm crack highlight on peppercorn fragment
    brush.set("needle", "#c49e6c", 0.5);
    brush.line(px - 0.5, py - 0.5, px + 0.6, py + 0.2);
  }

  brush.noClip();
  pop();
}

// ============================================================================
// 4. ARCH SPANDREL MASKS & RECESSED PHOTOGRAPH BORDERS
// ============================================================================
function drawArchSpandrelsAndBorders(wx, wy, ww, wh, archH) {
  const cx = wx + ww * 0.5;
  const cyArch = wy + archH;
  const rx = ww * 0.5;
  const ry = archH;

  // Mask out the top-left and top-right spandrels outside the arch curve with the buff card color
  brush.noStroke();
  for (let side of [-1, 1]) {
    let cornerX = side < 0 ? wx - 3 : wx + ww + 3;
    let startA = side < 0 ? 180 : 0;
    let endA = side < 0 ? 270 : 270;

    brush.wash("#e6ce9c", 255);
    brush.beginShape(0);
    brush.vertex(cornerX, wy - 3);
    brush.vertex(cx, wy - 3);
    for (let i = 0; i <= 24; i++) {
      let a = side < 0 ? map(i, 0, 24, 270, 180) : map(i, 0, 24, 270, 360);
      brush.vertex(cx + cos(a) * rx, cyArch + sin(a) * ry);
    }
    brush.vertex(cornerX, cyArch);
    brush.endShape(true);
    brush.noWash();

    // Match the warm buff watercolor grain on the spandrels
    brush.fill("#d4ad68", 85);
    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.6, 0.4);
    brush.beginShape(0);
    brush.vertex(cornerX, wy - 2);
    brush.vertex(cx, wy - 2);
    for (let i = 0; i <= 16; i++) {
      let a = side < 0 ? map(i, 0, 16, 270, 180) : map(i, 0, 16, 270, 360);
      brush.vertex(cx + cos(a) * (rx + 1), cyArch + sin(a) * (ry + 1));
    }
    brush.vertex(cornerX, cyArch);
    brush.endShape(true);
    brush.noFill();
  }

  // Helper to trace the arched window perimeter with an inset/outset offset `off`
  function traceArchOutline(off) {
    brush.beginShape(0);
    brush.vertex(wx - off, wy + wh + off);
    brush.vertex(wx - off, cyArch);
    for (let a = 180; a <= 360; a += 4) {
      brush.vertex(cx + cos(a) * (rx + off), cyArch + sin(a) * (ry + off));
    }
    brush.vertex(wx + ww + off, cyArch);
    brush.vertex(wx + ww + off, wy + wh + off);
    brush.endShape(true);
  }

  // Inner warm albumen print edge vignette
  brush.set("2B", "#3d2917", 1.3);
  traceArchOutline(-1.5);

  // Crisp dark sepia mount cutout shadow along top & left of arch
  brush.set("rotring", "#2b1c0e", 1.15);
  traceArchOutline(0);

  // Cream highlight along bottom & right edge of window cutout
  brush.set("needle", "#fbf0d9", 0.9);
  brush.line(wx, wy + wh + 1.5, wx + ww + 1.5, wy + wh + 1.5);
  brush.line(wx + ww + 1.5, cyArch, wx + ww + 1.5, wy + wh + 1.5);

  // Decorative fine sepia rule border printed on the buff mount around the arch
  brush.set("needle", "#6e4f2c", 0.75);
  traceArchOutline(5.5);
}

