function drawPrintedText(text, cx, cy, size, tracking, angleDeg, col, weight) {
  push();
  translate(cx, cy);
  rotate(angleDeg);
  brush.set("needle", col, weight);

  // Measure total width for centering
  let totalW = 0;
  let charWidths = [];
  for (let i = 0; i < text.length; i++) {
    let ch = text[i];
    let isLower = ch >= 'a' && ch <= 'z';
    let up = ch.toUpperCase();
    let w = (ch === ' ') ? size * 0.55
          : ((ch === '.' || ch === ',' || ch === ':' || ch === '\'') ? size * 0.35
          : (isLower ? size * 0.56 : size * 0.72));
    charWidths.push(w);
    totalW += w + (i < text.length - 1 ? tracking : 0);
  }

  let curX = -totalW * 0.5;
  for (let i = 0; i < text.length; i++) {
    let ch = text[i];
    let isLower = ch >= 'a' && ch <= 'z';
    let up = ch.toUpperCase();
    let cw = charWidths[i];
    let chH = isLower ? size * 0.74 : size;
    let yOff = isLower ? -size * 0.5 + (size - chH) : -size * 0.5;

    let segs = GLYPHS[up];
    if (segs) {
      for (let s of segs) {
        brush.line(
          curX + s[0] * cw * 0.85,
          yOff + s[1] * chH,
          curX + s[2] * cw * 0.85,
          yOff + s[3] * chH
        );
      }
    }
    curX += cw + tracking;
  }
  pop();
}

