// ============================================================================
// 7. CREASED TOP-RIGHT CORNER & ANTIQUE CARDBOARD EDGE BEVELS
// ============================================================================
function drawCreasedCornerAndEdges(x, y, w, h, r) {
  // 1. Diagonal Crease Across the Top-Right Corner of the Mount
  // Fold runs from (x + w - 138, y) on top edge to (x + w, y + 132) on right edge
  const cx1 = x + w - 138;
  const cy1 = y;
  const cx2 = x + w;
  const cy2 = y + 132;

  // Bent corner plane has a slightly darker, angled warm-buff shading because it tilts away from the light
  brush.noStroke();
  brush.wash("#c9a362", 145);
  brush.beginShape(0.1);
  brush.vertex(cx1, cy1);
  brush.vertex(x + w - r, y);
  for (let i = 0; i <= 6; i++) {
    let a = map(i, 0, 6, -90, 0);
    brush.vertex(x + w - r + cos(a) * r, y + r + sin(a) * r);
  }
  brush.vertex(cx2, cy2);
  brush.endShape(true);

  // Soft shadow gradient immediately below/left of the crease ridge
  for (let s = 1; s <= 5; s++) {
    brush.wash("#8f6834", map(s, 1, 5, 85, 18));
    brush.beginShape(0.15);
    brush.vertex(cx1 - s * 3.5, cy1);
    brush.vertex(cx1 + 2, cy1);
    brush.vertex(cx2, cy2 + 2);
    brush.vertex(cx2, cy2 + s * 3.5);
    brush.endShape(true);
  }
  brush.noWash();

  // Jagged paper-fiber crease shadow line
  const steps = 22;
  let creasePts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let jx = (i === 0 || i === steps) ? 0 : sin(i * 47) * 1.8;
    let jy = (i === 0 || i === steps) ? 0 : cos(i * 31) * 1.8;
    creasePts.push([lerp(cx1, cx2, t) + jx, lerp(cy1, cy2, t) + jy]);
  }

  brush.set("2B", "#473014", 1.35);
  brush.spline(creasePts, 0.25);
  brush.set("rotring", "#2b1b09", 0.9);
  brush.spline(creasePts, 0.25);

  // Exposed pale cream cardboard core along the cracked fold ridge
  let ridgePts = creasePts.map(pt => [pt[0] + 1.8, pt[1] - 1.6]);
  brush.set("gouache", "#fbf1d8", 0.85);
  brush.spline(ridgePts, 0.25);
  brush.set("needle", "#ffffff", 0.7);
  brush.spline(ridgePts, 0.25);

  // Fine branching stress-cracks in the buff paper coating along the crease
  for (let i = 3; i < steps - 2; i += 2) {
    let [px, py] = creasePts[i];
    let ang = 42 + (i % 2 === 0 ? 28 : -32);
    let len = random(7, 18);
    brush.set("needle", "#593d1c", 0.65);
    brush.line(px, py, px + cos(ang) * len, py + sin(ang) * len);
    brush.set("needle", "#faefd4", 0.55);
    brush.line(px + 1, py - 1, px + 1 + cos(ang) * len * 0.8, py - 1 + sin(ang) * len * 0.8);
  }

  // 2. Multi-ply Cardboard Edge Bevel & Wear Around the Entire Stereocard
  // Inner decorative rule frame on the buff card
  brush.set("needle", "#8c693a", 0.75);
  traceRoundedRect(x + 12, y + 12, w - 24, h - 24, r - 6);

  // Bright cream-gold top & left cardboard bevel catchlight
  brush.set("HB", "#faf0d7", 1.25);
  brush.line(x + r, y + 1, x + w - r, y + 1);
  brush.line(x + 1, y + r, x + 1, y + h - r);

  // Dark multi-ply antique cardboard thickness along bottom & right edges
  for (let ply = 0; ply < 4; ply++) {
    let col = ply % 2 === 0 ? "#3d2914" : "#6e4e2a";
    brush.set("rotring", col, 1.0);
    brush.line(x + r, y + h + ply * 1.1, x + w - r, y + h + ply * 1.1);
    brush.line(x + w + ply * 1.1, y + r, x + w + ply * 1.1, y + h - r);
  }

  // Outer perimeter outline with subtle corner wear scuffing
  brush.set("2B", "#4a3319", 1.15);
  traceRoundedRect(x, y, w, h, r);
}

// Hyperreal Portrait in Ultramarine, Prussian Blue, Pale Cornflower, Muted Earth & Gold Pyrite
// Rendered purely through pigment density, watercolor washes, dry charcoal masses, and 3D cross-contour micro-strokes.

const HEAD_CX = 548;
const HEAD_CY = 522;
const HEAD_ANGLE = 23.5 * (Math.PI / 180);
const COS_A = Math.cos(HEAD_ANGLE);
const SIN_A = Math.sin(HEAD_ANGLE);
const HEAD_SCALE = 1.34;

// Profile spline landmarks: [v, u] along the anterior contour of the face
const PROFILE_PTS = [
  [-270, -10],
  [-230, 82],
  [-185, 148],
  [-135, 179],
  [-98, 182],
  [-78, 187],   // Brow ridge
  [-55, 174],   // Nasion (root of nose)
  [-26, 195],   // Nasal bridge
  [2, 214],     // Nasal dorsum
  [25, 231],    // Supratip
  [39, 237],    // Pronasale (tip of nose)
  [51, 228],    // Infratip lobule
  [61, 208],    // Columella
  [69, 195],    // Subnasale
  [90, 200],    // Philtrum
  [112, 210],   // Upper lip vermilion peak
  [129, 208],   // Upper lip cushion
  [141, 198],   // Upper lip lower roll
  [146, 186],   // Stomion (sleeping mouth cleft)
  [153, 198],   // Lower lip upper roll
  [164, 203],   // Lower lip fullest cushion
  [177, 190],   // Lower lip lower roll
  [191, 175],   // Labiomental sulcus (chin crease)
  [208, 181],   // Upper chin
  [225, 184],   // Pogonion (chin prominence)
  [244, 165],   // Gnathion (under-chin curve)
  [262, 118],   // Submental
  [290, 60]
];

// Foreground pillow crest landmarks: [u, v] pressing up into the lower cheek and cradling the chin
const PILLOW_PTS = [
  [-380, 235],
  [-250, 205],
  [-145, 174],
  [-65, 146],
  [-10, 131],   // Rising against jaw/cheek
  [42, 124],    // Peak compression into soft cheek
  [86, 138],    // Curving down before oral commissure
  [118, 172],   // Clearing the corner of the mouth
  [146, 222],   // Curving around labiomental fold
  [178, 247],   // Cradling the chin pad
  [225, 252],
  [310, 268],
  [420, 295]
];

function evalCatmullRom1D(pts, xVal) {
  if (xVal <= pts[0][0]) return pts[0][1];
  if (xVal >= pts[pts.length - 1][0]) return pts[pts.length - 1][1];
  let idx = 0;
  for (let i = 0; i < pts.length - 1; i++) {
    if (xVal >= pts[i][0] && xVal <= pts[i + 1][0]) {
      idx = i;
      break;
    }
  }
  let p0 = pts[Math.max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[idx + 1];
  let p3 = pts[Math.min(pts.length - 1, idx + 2)];
  let h = p2[0] - p1[0];
  if (h < 1e-5) return p1[1];
  let t = (xVal - p1[0]) / h;
  let m1 = (p2[1] - p0[1]) / Math.max(1e-5, p2[0] - p0[0]) * h;
  let m2 = (p3[1] - p1[1]) / Math.max(1e-5, p3[0] - p1[0]) * h;
  let t2 = t * t;
  let t3 = t2 * t;
  return (2 * t3 - 3 * t2 + 1) * p1[1] +
         (t3 - 2 * t2 + t) * m1 +
         (-2 * t3 + 3 * t2) * p2[1] +
         (t3 - t2) * m2;
}

function getProfileU(v) {
  return evalCatmullRom1D(PROFILE_PTS, v);
}

function getPillowV(u) {
  return evalCatmullRom1D(PILLOW_PTS, u);
}

function canvasToHead(x, y) {
  let dx = (x - HEAD_CX) / HEAD_SCALE;
  let dy = (y - HEAD_CY) / HEAD_SCALE;
  return {
    u: dx * COS_A + dy * SIN_A,
    v: -dx * SIN_A + dy * COS_A
  };
}

function headToCanvas(u, v) {
  let dx = u * COS_A - v * SIN_A;
  let dy = u * SIN_A + v * COS_A;
  return [HEAD_CX + dx * HEAD_SCALE, HEAD_CY + dy * HEAD_SCALE];
}

function gBump(u, v, u0, v0, su, sv, rot = 0) {
  let du = u - u0;
  let dv = v - v0;
  if (rot !== 0) {
    let c = Math.cos(rot), s = Math.sin(rot);
    let rdu = du * c + dv * s;
    let rdv = -du * s + dv * c;
    du = rdu;
    dv = rdv;
  }
  let q = (du * du) / (2 * su * su) + (dv * dv) / (2 * sv * sv);
  if (q > 12) return 0;
  return Math.exp(-q);
}

function distToSegment(px, py, x1, y1, x2, y2) {
  let vx = x2 - x1, vy = y2 - y1;
  let wx = px - x1, wy = py - y1;
  let c1 = vx * wx + vy * wy;
  let c2 = vx * vx + vy * vy;
  let t = c2 > 1e-6 ? Math.max(0, Math.min(1, c1 / c2)) : 0;
  let cx = x1 + t * vx, cy = y1 + t * vy;
  let dx = px - cx, dy = py - cy;
  return { d: Math.sqrt(dx * dx + dy * dy), t: t, cx: cx, cy: cy, side: (vx * wy - vy * wx) >= 0 ? 1 : -1 };
}

function distToCurve(u, v, pts) {
  let best = { d: 1e9, tGlobal: 0, side: 1, tanU: 1, tanV: 0 };
  let nSeg = pts.length - 1;
  for (let i = 0; i < nSeg; i++) {
    let res = distToSegment(u, v, pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    if (res.d < best.d) {
      let du = pts[i + 1][0] - pts[i][0];
      let dv = pts[i + 1][1] - pts[i][1];
      let len = Math.sqrt(du * du + dv * dv) || 1;
      best.d = res.d;
      best.tGlobal = (i + res.t) / nSeg;
      best.side = res.side;
      best.tanU = du / len;
      best.tanV = dv / len;
    }
  }
  return best;
}

// Anatomical curve definitions in (u, v) space
const BROW_CURVE = [[168, -68], [132, -85], [88, -90], [45, -78], [16, -60]];
const SUPRATARSAL_CURVE = [[144, -31], [116, -44], [84, -44], [50, -31]];
const LASH_CURVE = [[142, -14], [114, -8], [84, -9], [50, -19]];
const LOWER_LID_CURVE = [[138, -2], [110, 7], [80, 5], [54, -8]];
const ALAR_GROOVE_CURVE = [[164, 28], [157, 44], [165, 58], [178, 63]];
const NOSTRIL_CURVE = [[220, 54], [202, 57], [187, 61]];
const MOUTH_CLEFT_CURVE = [[192, 146], [168, 145], [144, 146], [124, 143]];
const UPPER_LIP_BORDER = [[210, 112], [182, 114], [152, 125], [124, 143]];
const LOWER_LIP_BORDER = [[191, 177], [166, 179], [142, 169], [124, 143]];
const LABIOMENTAL_CURVE = [[180, 191], [152, 193], [124, 202]];
const EAR_HELIX_CURVE = [[-114, -4], [-126, -32], [-148, -42], [-168, -20], [-170, 18], [-158, 52], [-138, 74]];
const EAR_ANTIHELIX_CURVE = [[-134, -22], [-146, 2], [-144, 30], [-126, 46]];

// Evaluate 3D height Z, occlusion AO, and anatomical mask at head coordinates (u, v)
function evaluateHead3D(u, v) {
  let uProf = getProfileU(v);
  let vPil = getPillowV(u);

  // Far brow and far cheek peeking slightly past the nasal root/bridge in 3/4 view
  let farCheekU = 165 + 32 * Math.exp(-Math.pow((v + 74) / 22, 2)) + 48 * Math.exp(-Math.pow((v - 6) / 38, 2));
  let uMaxFront = Math.max(uProf, farCheekU);

  // Posterior boundary of head/hair/neck
  let uBack = -208 - 18 * Math.exp(-Math.pow((v + 75) / 110, 2)) + 25 * Math.exp(-Math.pow((v - 180) / 90, 2));

  // Distance inside anterior profile
  let dFront = uProf - u;
  let dFar = farCheekU - u;
  let dBack = u - uBack;
  let dPillow = vPil - v; // Positive when above the foreground pillow crest

  // Smooth mask for whether point is on the near face/head vs pillow
  let inNearFace = dFront > -3.5 && dBack > -20 && v > -265 && dPillow > -4;
  let inFarCheek = dFront <= 0 && dFar > 0 && v > -100 && v < 55;

  // 1. Base cranial & facial 3D relief Z_face
  let zFace = 0;
  let ao = 0;
  let warmth = 0; // Muted earth warmth in midtones
  let isHair = 0;
  let isLip = 0;

  if (dFront > -15 && dBack > -40 && v > -275 && v < 275) {
    // Base ovoid dome of the skull and jaw
    let normFront = Math.max(0, dFront);
    let edgeRoll = Math.sqrt(normFront / (normFront + 24)) * (1 - Math.exp(-normFront / 3.5));
    let skullDome = 78 * Math.exp(-Math.pow((u - 15) / 195, 2) - Math.pow((v + 15) / 255, 2));
    zFace = (42 + skullDome) * edgeRoll;

    // Forehead & Glabella & Brow Ridge
    zFace += 22 * gBump(u, v, 145, -140, 65, 48);
    let browRes = distToCurve(u, v, BROW_CURVE);
    zFace += 16 * Math.exp(- (browRes.d * browRes.d) / (2 * 15 * 15));
    // Temple hollow
    zFace -= 12 * gBump(u, v, 18, -95, 42, 38, 0.3);

    // Eye socket concavity (orbit)
    let orbitDepth = 30 * gBump(u, v, 106, -34, 46, 28, -0.12) +
                     24 * gBump(u, v, 146, -42, 22, 20); // Deep medial orbit hollow
    zFace -= orbitDepth;
    ao += 0.58 * gBump(u, v, 144, -44, 24, 20) + 0.35 * gBump(u, v, 102, -40, 42, 22);

    // Eyeball & Closed Upper Eyelid sphere
    let eyeSphere = 26 * gBump(u, v, 98, -22, 34, 18, -0.08);
    zFace += eyeSphere;

    // Supratarsal eyelid crease
    let supraRes = distToCurve(u, v, SUPRATARSAL_CURVE);
    let supraCrease = Math.exp(-(supraRes.d * supraRes.d) / (2 * 3.2 * 3.2));
    zFace -= 7.5 * supraCrease;
    ao += 0.68 * supraCrease;

    // Resting Eyelash line (palpebral fissure) & cast shadow on upper cheek
    let lashRes = distToCurve(u, v, LASH_CURVE);
    let lashCrease = Math.exp(-(lashRes.d * lashRes.d) / (2 * 2.8 * 2.8));
    zFace -= 6.0 * lashCrease;
    ao += 0.85 * lashCrease;
    // Feathery eyelash fringe shadow extending slightly downward (+v)
    if (u > 46 && u < 145 && v > -14 && v < 12) {
      let lashFan = gBump(u, v, 96, -2, 36, 7, -0.06);
      ao += 0.48 * lashFan;
    }

    // Lower lid cushion & infraorbital tear trough
    let lowLidRes = distToCurve(u, v, LOWER_LID_CURVE);
    zFace += 4.5 * Math.exp(-(lowLidRes.d * lowLidRes.d) / (2 * 5.5 * 5.5));
    zFace -= 4.0 * gBump(u, v, 112, 12, 34, 8, -0.2);
    ao += 0.22 * gBump(u, v, 118, 12, 30, 8, -0.2);

    // Nose 3D wedge, bridge, tip, alar wing, and nostril
    if (v > -68 && v < 78 && u > 125) {
      let noseSpan = Math.max(1, uProf - 148);
      let noseFrac = Math.max(0, Math.min(1.15, (u - 148) / noseSpan));
      let vFade = Math.exp(-Math.pow((v - 8) / 48, 2));
      let ridgeLift = 34 * Math.pow(noseFrac, 1.35) * (1 - 0.35 * Math.pow(Math.max(0, dFront < 7 ? (7 - dFront) / 7 : 0), 2));
      zFace += ridgeLift * vFade;

      // Nose Tip sphere (Pronasale)
      zFace += 22 * gBump(u, v, 224, 38, 18, 16);
      // Alar Wing (Ala nasi)
      zFace += 15 * gBump(u, v, 180, 47, 15, 12, 0.2);
      // Alar facial groove
      let alarRes = distToCurve(u, v, ALAR_GROOVE_CURVE);
      let alarGroove = Math.exp(-(alarRes.d * alarRes.d) / (2 * 3.5 * 3.5));
      zFace -= 8.0 * alarGroove;
      ao += 0.72 * alarGroove;

      // Nostril cavity
      let nostRes = distToCurve(u, v, NOSTRIL_CURVE);
      let nostMask = Math.exp(-(nostRes.d * nostRes.d) / (2 * 4.2 * 4.2));
      zFace -= 14.0 * nostMask;
      ao += 0.96 * nostMask;

      // Shadow under nose tip & columella
      ao += 0.52 * gBump(u, v, 200, 64, 22, 8, 0.15);
    }

    // Cheekbone (Malar eminence) & Zygomatic arch
    zFace += 28 * gBump(u, v, 58, 36, 54, 40, 0.18);
    zFace += 14 * gBump(u, v, -22, 18, 52, 24, 0.15);
    warmth += 0.45 * gBump(u, v, 64, 42, 58, 46);

    // Sub-malar buccal contour & Nasolabial fold
    zFace -= 9 * gBump(u, v, 65, 92, 42, 26, 0.25);
    ao += 0.26 * gBump(u, v, 142, 82, 12, 28, -0.35);

    // Philtrum & Lips
    zFace -= 6.5 * gBump(u, v, 194, 92, 10, 14); // Philtrum dimple
    zFace += 5.5 * gBump(u, v, 184, 94, 5, 15);  // Philtrum ridge

    // Upper Lip (sloping downward into shadow)
    let upLipMask = gBump(u, v, 174, 129, 34, 14, 0.08);
    if (v > 108 && v < 147 && u > 120) {
      let vLip = (v - 112) / 34;
      zFace += 14 * Math.sin(Math.max(0, Math.min(1, vLip)) * Math.PI) * Math.exp(-Math.pow((u - 176) / 42, 2));
      // Downward tilt of upper lip surface normal
      zFace -= 9 * Math.max(0, (v - 115) / 30) * upLipMask;
      ao += 0.46 * upLipMask;
      isLip = Math.max(isLip, upLipMask);
    }

    // Mouth parting line (Stomion) & Oral commissure
    let mouthRes = distToCurve(u, v, MOUTH_CLEFT_CURVE);
    let mouthCleft = Math.exp(-(mouthRes.d * mouthRes.d) / (2 * 2.8 * 2.8));
    zFace -= 10.0 * mouthCleft;
    ao += 0.92 * mouthCleft;
    // Corner of mouth dimple
    ao += 0.65 * gBump(u, v, 124, 144, 10, 7);

    // Lower Lip cushion (full, rounded cylinder catching highlight above and rolling into shadow below)
    let lowLipMask = gBump(u, v, 168, 162, 30, 13, 0.05);
    zFace += 19 * lowLipMask;
    isLip = Math.max(isLip, lowLipMask);

    // Labiomental sulcus (deep shadow under lower lip)
    let labioRes = distToCurve(u, v, LABIOMENTAL_CURVE);
    let labioGroove = Math.exp(-(labioRes.d * labioRes.d) / (2 * 7.5 * 7.5));
    zFace -= 11.0 * labioGroove;
    ao += 0.68 * labioGroove;

    // Chin prominence (Mentum)
    zFace += 22 * gBump(u, v, 158, 222, 26, 20);

    // Cheek compression bulge just above the pillow contact line
    if (dPillow > 0 && dPillow < 42 && u > -45 && u < 120) {
      let pressBulge = Math.sin((dPillow / 42) * Math.PI) * Math.exp(-Math.pow((u - 38) / 58, 2));
      zFace += 15 * pressBulge;
    }

    // Ear sculpture (u in [-180, -85], v in [-50, 88])
    if (u < -75 && u > -188 && v > -55 && v < 92) {
      let earHelix = distToCurve(u, v, EAR_HELIX_CURVE);
      let earAnti = distToCurve(u, v, EAR_ANTIHELIX_CURVE);
      zFace += 14 * Math.exp(-(earHelix.d * earHelix.d) / (2 * 6.5 * 6.5));
      zFace += 11 * Math.exp(-(earAnti.d * earAnti.d) / (2 * 7.5 * 7.5));
      // Tragus & Antitragus
      zFace += 10 * gBump(u, v, -102, 16, 7, 9);
      zFace += 9 * gBump(u, v, -124, 52, 8, 7);
      // Earlobe
      zFace += 11 * gBump(u, v, -134, 70, 14, 12);
      // Deep Concha bowl & fossa shadows
      let concha = gBump(u, v, -122, 16, 14, 22, -0.15);
      zFace -= 18 * concha;
      ao += 0.92 * concha;
      // Under-helix curl crease
      let underHelix = gBump(u, v, -148, -12, 14, 24, -0.2);
      ao += 0.65 * underHelix;
      // Behind ear shadow
      ao += 0.55 * gBump(u, v, -176, 20, 14, 42);
    }

    // Hair volume & shadow mass (crown, temple, nape)
    let hairCrown = v < -145 - 0.35 * u ? 1 : 0;
    let hairBack = u < -75 - 0.35 * v && v < -15 ? 1 : 0;
    let sideburn = gBump(u, v, -74, -36, 24, 34, 0.2);
    if (hairCrown || hairBack || sideburn > 0.2) {
      let hStrength = Math.max(
         sideburn,
        gBump(u, v, -35, -195, 130, 65, -0.2),
        gBump(u, v, -145, -75, 65, 85, 0.25)
      );
      isHair = Math.min(1, hStrength * 1.4);
      ao += 0.68 * isHair;
      zFace += 12 * isHair;
    }

    // Soft transition at anterior profile edge
    if (dFront < 6) {
      let fEdge = Math.max(0, (dFront + 2.5) / 8.5);
      zFace *= fEdge;
    }
  }

  // Far cheek peeking out behind nasal bridge
  if (inFarCheek) {
    let fNorm = Math.max(0, dFar);
    zFace = 18 * Math.sqrt(fNorm / (fNorm + 12));
    ao = Math.max(ao, 0.42 + 0.32 * Math.exp(-Math.pow((v + 42) / 18, 2)));
  }

  // 2. Pillow 3D relief Z_pillow
  let zPillow = 0;
  let pillowAO = 0;
  // Foreground pillow rising up from bottom (dPillow < 0 means below vPil crest)
  if (dPillow < 18) {
    let intoPil = Math.max(0, -dPillow + 8);
    // Main pillow billow
    let crestRoll = 62 * Math.sqrt(intoPil / (intoPil + 35));
    // Radiating fabric folds from the weight of the head
    let fold1 = 14 * Math.exp(-Math.pow((v - (vPil + 28 + 0.28 * (u - 40))) / 26, 2)) * Math.exp(-Math.pow((u + 40) / 180, 2));
    let fold2 = 16 * Math.exp(-Math.pow((v - (vPil + 55 - 0.35 * (u - 130))) / 32, 2)) * Math.exp(-Math.pow((u - 160) / 170, 2));
    let foldCrease1 = Math.exp(-Math.pow((v - (vPil + 14 + 0.32 * (u - 20))) / 11, 2)) * Math.exp(-Math.pow((u - 10) / 120, 2));
    zPillow = crestRoll + fold1 + fold2 - 8 * foldCrease1;
    pillowAO += 0.42 * foldCrease1;
  }

  // Contact occlusion crease right where the cheek/jaw/chin presses into the foreground pillow
  let contactDist = Math.abs(dPillow);
  if (contactDist < 22 && u > -185 && u < 215) {
    let contactTightness = (u > -35 && u < 110) ? 7.5 : 11.5;
    let crease = Math.exp(-(contactDist * contactDist) / (2 * contactTightness * contactTightness));
    let strength = (u > -35 && u < 110) ? 0.88 : 0.72;
    ao = Math.max(ao, strength * crease);
    pillowAO = Math.max(pillowAO, strength * crease);
  }

  // Background / Upper-right pillow negative space behind the lit profile of the face
  let bgShadow = 0;
  if (!inNearFace && !inFarCheek && dPillow >= 0) {
    // Deep velvety Prussian/ultramarine negative-space halo right behind the brow, nose bridge, and lips
    // so the lit profile exists purely through pigment density contrast without any outline!
    let distOutsideProfile = -dFront;
    if (distOutsideProfile >= -2 && v > -190 && v < 255) {
      let profileHalo = Math.exp(-Math.max(0, distOutsideProfile) / 58);
      bgShadow = 0.62 * profileHalo + 0.18 * gBump(u, v, 265, 65, 95, 140);
    } else {
      bgShadow = 0.22 * gBump(u, v, -220, -140, 120, 140);
    }
    // Soft secondary pillow fold in upper right
    zPillow += 22 * gBump(u, v, 295, 55, 85, 130, -0.2);
  }

  let isFace = (inNearFace || inFarCheek) && (dPillow > -2);
  let zTotal = isFace ? zFace : zPillow;
  let totalAO = isFace ? Math.min(1, ao) : Math.min(1, pillowAO + bgShadow);

  return {
    z: zTotal,
    ao: totalAO,
    isFace: isFace,
    inNearFace: inNearFace,
    dFront: dFront,
    dPillow: dPillow,
    warmth: warmth,
    isHair: isHair,
    isLip: isLip,
    u: u,
    v: v
  };
}

// Compute complete lighting, pigment density, and 3D cross-contour tangent angle at canvas (x, y)
function evaluateScene(x, y) {
  let hc = canvasToHead(x, y);
  let u = hc.u, v = hc.v;
  let eps = 1.8;
  let c0 = evaluateHead3D(u, v);
  let cu = evaluateHead3D(u + eps, v);
  let cv = evaluateHead3D(u, v + eps);

  let dzdu = (cu.z - c0.z) / eps;
  let dzdv = (cv.z - c0.z) / eps;

  // 3D normal in head space
  let nx = -dzdu;
  let ny = -dzdv;
  let nz = 1.0;
  let nLen = Math.sqrt(nx * nx + ny * ny + nz * nz) || 1;
  nx /= nLen; ny /= nLen; nz /= nLen;

  // Key light from upper-right-anterior (soft directional studio/moonlight)
  let lx = 0.46, ly = -0.56, lz = 0.69;
  let ndotl = nx * lx + ny * ly + nz * lz;
  // Subsurface skin wrap lighting
  let wrappedLight = Math.max(0, (ndotl + 0.35) / 1.35);
  let shadeFromNormal = 1.0 - Math.pow(wrappedLight, 1.15);

  // Combine normal shading with anatomical ambient occlusion
  let darkness = 0;
  if (c0.isFace) {
    darkness = 0.52 * shadeFromNormal + 0.78 * c0.ao;
    // Highlight boost on forehead, bridge/tip of nose, closed upper eyelid sphere, cheekbone, lower lip, chin
    let specBoost = 0.25 * gBump(u, v, 228, 34, 14, 14) +     // Nose tip highlight
                    0.22 * gBump(u, v, 202, -8, 10, 28, -0.42) + // Nose bridge highlight
                    0.22 * gBump(u, v, 98, -24, 22, 10) +     // Closed eyelid highlight
                    0.20 * gBump(u, v, 64, 30, 42, 28) +      // Cheekbone highlight
                    0.24 * gBump(u, v, 174, 159, 20, 7) +     // Lower lip highlight
                    0.18 * gBump(u, v, 162, 218, 18, 14) +    // Chin highlight
                    0.18 * gBump(u, v, 152, -130, 38, 32);    // Forehead highlight
    darkness = Math.max(0, Math.min(1, darkness - specBoost * (1 - c0.ao)));
  } else {
    darkness = 0.38 * shadeFromNormal + 0.85 * c0.ao;
    darkness = Math.max(0, Math.min(1, darkness));
  }

  // Compute 3D cross-contour tangent angle in canvas degrees
  // Cross-contour runs perpendicular to gradient (dzdu, dzdv) in (u, v), converted to canvas angle
  let gradMag = Math.sqrt(dzdu * dzdu + dzdv * dzdv);
  let localAngle = Math.atan2(dzdu, -dzdv); // Tangent to isophotes/height contours
  if (gradMag < 0.08) {
    // Default gentle organic flow across cheek or pillow
    localAngle = c0.isFace ? 0.35 : -0.25;
  }
  let canvasAngleDeg = (localAngle + HEAD_ANGLE) * (180 / Math.PI);

  return {
    darkness: darkness,
    ao: c0.ao,
    isFace: c0.isFace,
    dFront: c0.dFront,
    dPillow: c0.dPillow,
    warmth: c0.warmth,
    isHair: c0.isHair,
    isLip: c0.isLip,
    angle: canvasAngleDeg,
    u: u,
    v: v
  };
}

// Helper to sample points along an anatomical curve in canvas coordinates
function headCurveToCanvasPoly(uvPts) {
  return uvPts.map(p => headToCanvas(p[0], p[1]));
}

function drawSmoothShape(pts, curvature = 0.5, closeShape = true) {
  if (pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7419);
  noiseSeed(7419);

  // Register custom hyperreal dry-pigment, mineral, and pyrite brushes
  brush.add("velvet_charcoal", {
    type: "default",
    weight: 1.8,
    scatter: 0.65,
    sharpness: 0.16,
    grain: 18,
    opacity: 36,
    spacing: 0.38,
    pressure: [0.15, 1.0, 0.15],
    noise: 0.65
  });

  brush.add("skin_whisper", {
    type: "default",
    weight: 1.25,
    scatter: 0.85,
    sharpness: 0.11,
    grain: 14,
    opacity: 22,
    spacing: 0.45,
    pressure: [0.1, 0.9, 0.1],
    noise: 0.35
  });

  brush.add("calcite_vein", {
    type: "default",
    weight: 0.75,
    scatter: 0.22,
    sharpness: 0.48,
    grain: 11,
    opacity: 68,
    spacing: 0.25,
    pressure: [0.1, 1.15, 0.1],
    noise: 0.85
  });

  brush.add("pyrite_mist", {
    type: "spray",
    weight: 1.5,
    scatter: 3.4,
    opacity: 135,
    spacing: 1.1,
    pressure: [0.4, 1.1, 0.4]
  });

  brush.add("pyrite_crystal", {
    type: "custom",
    weight: 1.6,
    scatter: 0.45,
    opacity: 195,
    spacing: 0.9,
    pressure: [0.6, 1.2, 0.6],
    tip: (_m) => {
      _m.rotate(35);
      _m.rect(-1.2, -0.9, 2.4, 1.8);
    },
    rotate: "random",
    markerTip: false
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm muted limestone / raw earth parchment ground
  background("#ded6c8");

  // =========================================================================
  // 1. LAYERED WATERCOLOR & EARTH/ULTRAMARINE MINERAL UNDERPAINTING (BATCHED)
  // =========================================================================
  brush.noStroke();

  // Batch A: Muted earth-umber & warm slate mineral ground washes
  brush.fill("#8c8070", 42);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.65, 0.22);
  drawSmoothShape([[60, 680], [520, 620], [920, 720], [1140, 1080], [80, 1140]]);
  drawSmoothShape([[80, 80], [640, 110], [480, 560], [90, 520]]);

  brush.fill("#6e6558", 48);
  brush.fillBleed(0.38, "out");
  drawSmoothShape(headCurveToCanvasPoly([
    [-210, -80], [-40, -60], [120, 60], [60, 175], [-160, 195]
  ]));

  // Batch B: Pale cornflower atmospheric & skin midtone washes
  brush.fill("#85a4d1", 52);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.55, 0.2);
  drawSmoothShape(headCurveToCanvasPoly([
    [-120, -180], [175, -155], [235, 35], [190, 225], [-40, 210], [-185, 40]
  ]));
  drawSmoothShape(headCurveToCanvasPoly([
    [-260, 165], [35, 118], [240, 235], [280, 340], [-240, 330]
  ]));

  brush.fill("#5b7fb8", 56);
  brush.fillBleed(0.35, "out");
  // Upper-right negative space pillow shadow behind the face profile
  drawSmoothShape(headCurveToCanvasPoly([
    [182, -145], [320, -120], [340, 120], [250, 255], [182, 240],
    [198, 160], [206, 112], [196, 68], [237, 38], [174, -55]
  ]));
  // Cheek & jaw shadow wash
  drawSmoothShape(headCurveToCanvasPoly([
    [-120, 30], [45, 72], [135, 105], [110, 175], [-15, 145], [-135, 160]
  ]));

  // Batch C: Rich French Ultramarine core shadow washes
  brush.fill("#1d3f80", 74);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.68, 0.3);
  // Eye socket & medial orbit wash
  drawSmoothShape(headCurveToCanvasPoly([
    [168, -68], [105, -82], [42, -55], [52, -10], [115, 4], [156, -24]
  ]));
  // Hair & crown ultramarine wash
  drawSmoothShape(headCurveToCanvasPoly([
    [-215, -60], [-155, -205], [10, -255], [115, -205], [-35, -120], [-85, -15], [-165, -20]
  ]));
  // Pillow contact crease & under-chin shadow wash
  drawSmoothShape(headCurveToCanvasPoly([
    [-160, 165], [-15, 126], [62, 124], [118, 168], [160, 242], [65, 255], [-120, 225]
  ]));
  // Behind nose bridge & mouth negative-space contrast wash
  drawSmoothShape(headCurveToCanvasPoly([
    [175, -56], [255, -45], [285, 95], [235, 215], [182, 192], [202, 162], [188, 146], [209, 112], [196, 68], [237, 38]
  ]));

  // Batch D: Deep Prussian Blue abyssal shadow washes
  brush.fill("#0b1b38", 86);
  brush.fillBleed(0.26, "out");
  // Medial orbit hollow
  drawSmoothShape(headCurveToCanvasPoly([
    [158, -58], [118, -62], [108, -32], [144, -18], [162, -36]
  ]));
  // Ear concha & helix shadow
  drawSmoothShape(headCurveToCanvasPoly([
    [-148, -28], [-112, -10], [-108, 34], [-135, 48], [-154, 15]
  ]));
  // Upper lip & labiomental shadow wash
  drawSmoothShape(headCurveToCanvasPoly([
    [208, 114], [152, 122], [122, 144], [165, 149], [202, 142]
  ]));
  drawSmoothShape(headCurveToCanvasPoly([
    [186, 182], [142, 184], [126, 205], [168, 206]
  ]));
  brush.noFill();

  // =========================================================================
  // 2. FAINT PALE-GREY CALCITE VEINS DRIFTING ACROSS THE BACKGROUND
  // =========================================================================
  const calcitePaths = [
    [[70, 210], [210, 265], [350, 240], [490, 170], [640, 105], [820, 65]],
    [[920, 80], [965, 230], [1030, 390], [990, 540], [1070, 710], [1145, 860]],
    [[65, 830], [195, 790], [330, 855], [440, 960], [580, 1070], [720, 1150]],
    [[840, 940], [940, 890], [1045, 955], [1135, 1040]],
    [[120, 440], [235, 495], [310, 595], [245, 710], [110, 760]]
  ];

  for (let vIdx = 0; vIdx < calcitePaths.length; vIdx++) {
    let basePts = calcitePaths[vIdx];
    let finePts = [];
    for (let i = 0; i < basePts.length - 1; i++) {
      let p1 = basePts[i], p2 = basePts[i + 1];
      let steps = 10;
      for (let s = 0; s < steps; s++) {
        let t = s / steps;
        let x = lerp(p1[0], p2[0], t);
        let y = lerp(p1[1], p2[1], t);
        let n = (noise(x * 0.008, y * 0.008, vIdx * 10) - 0.5) * 34;
        finePts.push([x + n, y - n * 0.7]);
      }
    }
    // Subtle mineral shadow alongside vein
    brush.set("calcite_vein", "#7a8599", 1.1);
    brush.spline(finePts.map(p => [p[0] + 2.5, p[1] + 2.5]), 0.35);
    // Main pale-grey calcite vein
    brush.set("calcite_vein", "#e3dfd7", 1.35);
    brush.spline(finePts, 0.35);
    brush.set("2H", "#f2efe9", 0.7);
    brush.spline(finePts.map(p => [p[0] - 1, p[1] - 1]), 0.35);

    // Secondary delicate offshoots
    for (let k = 6; k < finePts.length - 6; k += 11) {
      if (random() < 0.65) {
        let ox = finePts[k][0], oy = finePts[k][1];
        let branch = [[ox, oy]];
        let ang = random(-60, 60);
        for (let b = 1; b <= 4; b++) {
          ox += cos(ang + b * 12) * 24;
          oy += sin(ang + b * 12) * 24;
          branch.push([ox, oy]);
        }
        brush.set("calcite_vein", "#d8d5ce", 0.85);
        brush.spline(branch, 0.3);
      }
    }
  }

  // =========================================================================
  // 3. DEEP VELVETY CHARCOAL-LIKE MASSES (EYE SOCKET, LIP, EAR, PILLOW CREASE)
  // =========================================================================
  brush.noStroke();
  brush.noFill();

  // Ultramarine charcoal masses (outline: false -> zero outlines!)
  brush.mass("charcoal", "#122959", { precision: 0.5, strength: 0.75, gradient: 0.65, outline: false });
  // Eye socket outer shadow mass
  drawSmoothShape(headCurveToCanvasPoly([
    [164, -64], [116, -70], [72, -56], [62, -32], [112, -38], [156, -24]
  ]));
  // Ear antihelix & upper fold mass
  drawSmoothShape(headCurveToCanvasPoly([
    [-156, -26], [-132, -34], [-118, 4], [-134, 42], [-156, 22]
  ]));
  // Cheek-to-pillow compression shadow mass
  drawSmoothShape(headCurveToCanvasPoly([
    [-55, 144], [10, 126], [68, 124], [95, 144], [38, 142], [-25, 152]
  ]));
  // Hair crown & temple velvet mass
  drawSmoothShape(headCurveToCanvasPoly([
    [-175, -65], [-115, -165], [-15, -205], [25, -165], [-55, -95], [-92, -25]
  ]));

  // Deepest Prussian Blue charcoal masses
  brush.mass("charcoal", "#071329", { precision: 0.55, strength: 0.9, gradient: 0.55, outline: false });
  // Deep medial eye socket hollow
  drawSmoothShape(headCurveToCanvasPoly([
    [156, -54], [128, -56], [118, -34], [144, -24], [160, -38]
  ]));
  // Nostril & under-nose core shadow
  drawSmoothShape(headCurveToCanvasPoly([
    [222, 52], [198, 52], [182, 58], [194, 66], [218, 62]
  ]));
  // Upper lip & mouth cleft core shadow
  drawSmoothShape(headCurveToCanvasPoly([
    [206, 122], [168, 126], [124, 143], [164, 149], [198, 144]
  ]));
  // Labiomental shadow under lower lip
  drawSmoothShape(headCurveToCanvasPoly([
    [182, 184], [148, 186], [134, 198], [168, 198]
  ]));
  // Ear concha bowl abyssal shadow
  drawSmoothShape(headCurveToCanvasPoly([
    [-132, -4], [-114, 2], [-112, 30], [-128, 36], [-138, 16]
  ]));
  brush.noMass();

  // =========================================================================
  // 4. BREATHING-SOFT GRADATIONS & 3D FORM MODELING VIA PIGMENT DENSITY
  // =========================================================================
  const paletteDark = ["#061124", "#091833", "#0e2247", "#142d5e"];
  const paletteMid = ["#1b3b7a", "#244c99", "#345ea8", "#4f6d9e"];
  const paletteEarth = ["#54504a", "#696155", "#7a7164"];
  const paletteLight = ["#6b8ec2", "#8ba9d6", "#adc4e6", "#cfdef5"];
  const paletteHighlight = ["#d9e6f7", "#e8eef7", "#ede6da"];

  // Stratified organic sampling across the 1200x1200 canvas
  // Higher density on the face and pillow contact zone, lower on outer margins
  let samples = [];
  for (let y = 55; y < 1145; y += 7.5) {
    for (let x = 55; x < 1145; x += 7.5) {
      let jx = x + random(-3.5, 3.5);
      let jy = y + random(-3.5, 3.5);
      let sc = evaluateScene(jx, jy);

      // Determine local importance (face features & pillow creases get fine multi-layering)
      let inFeature = sc.isFace && (
        (sc.u > 25 && sc.u < 245 && sc.v > -95 && sc.v < 245) ||
        (sc.u > -180 && sc.u < -80 && sc.v > -55 && sc.v < 88)
      );

      if (inFeature || sc.darkness > 0.14 || random() < 0.45) {
        samples.push({ x: jx, y: jy, sc: sc, inFeature: inFeature });
      }
      // Extra dense sub-samples on high-detail anatomy (eye, nose, lips, ear, cheek-pillow crease)
      if (inFeature || Math.abs(sc.dPillow) < 28 || Math.abs(sc.dFront) < 22) {
        let sx = x + random(-3.5, 3.5);
        let sy = y + random(-3.5, 3.5);
        let ssc = evaluateScene(sx, sy);
        samples.push({ x: sx, y: sy, sc: ssc, inFeature: true });
      }
    }
  }

  // Sort samples from light/midtones to deepest shadows so velvety darks build on top naturally
  samples.sort((a, b) => a.sc.darkness - b.sc.darkness);

  for (let i = 0; i < samples.length; i++) {
    let pt = samples[i];
    let sc = pt.sc;
    let d = sc.darkness;
    let ang = sc.angle + random(-8, 8);
    let rad = ang * (Math.PI / 180);

    // Stroke length adapts to anatomical curvature: short & precise on features, long & breathing on cheek/pillow
    let baseLen = pt.inFeature ? map(d, 0, 1, 18, 9) : map(d, 0, 1, 38, 18);
    if (Math.abs(sc.dFront) < 14 && sc.u > 150) {
      // Align strokes cleanly along the anterior profile boundary (no outline, pure edge density!)
      let pTan = headToCanvas(sc.u, sc.v + 10);
      let pCur = [pt.x, pt.y];
      rad = Math.atan2(pTan[1] - pCur[1], pTan[0] - pCur[0]);
      baseLen = 13;
    }

    let dx = Math.cos(rad) * baseLen * 0.5;
    let dy = Math.sin(rad) * baseLen * 0.5;
    // Slight cross-contour curvature
    let perpX = -Math.sin(rad) * baseLen * random(-0.12, 0.12);
    let perpY = Math.cos(rad) * baseLen * random(-0.12, 0.12);

    if (d < 0.20) {
      // Luminous highlights on skin & pillow crests (pale cornflower & warm alabaster limestone)
      if (sc.isFace || sc.dPillow < 15) {
        let col = (d < 0.10) ? random(paletteHighlight) : random(paletteLight);
        let w = map(d, 0, 0.20, 1.35, 0.85);
        brush.set("skin_whisper", col, w);
        brush.spline([
          [pt.x - dx, pt.y - dy, 0.2],
          [pt.x + perpX, pt.y + perpY, 0.9],
          [pt.x + dx, pt.y + dy, 0.2]
        ], 0.4);
      }
    } else if (d < 0.44) {
      // Breathing-soft pale cornflower & muted earth skin transition gradations
      let useEarth = (sc.warmth > 0.15 && random() < 0.36) || (!sc.isFace && random() < 0.28);
      let col = useEarth ? random(paletteEarth) : (d < 0.32 ? random(paletteLight) : random(paletteMid));
      let w = map(d, 0.20, 0.44, 0.85, 1.25);
      brush.set("skin_whisper", col, w);
      brush.spline([
        [pt.x - dx, pt.y - dy, 0.2],
        [pt.x + perpX, pt.y + perpY, 0.85],
        [pt.x + dx, pt.y + dy, 0.2]
      ], 0.4);
    } else if (d < 0.70) {
      // Rich Ultramarine & slate-earth mid-shadows
      let col = (random() < 0.18) ? random(paletteEarth) : random(paletteMid);
      let w = map(d, 0.44, 0.70, 0.95, 1.45);
      brush.set(pt.inFeature ? "skin_whisper" : "velvet_charcoal", col, w);
      brush.spline([
        [pt.x - dx, pt.y - dy, 0.25],
        [pt.x + perpX, pt.y + perpY, 1.0],
        [pt.x + dx, pt.y + dy, 0.25]
      ], 0.45);
    } else {
      // Deep velvety Prussian Blue & dark Ultramarine shadow masses
      let col = (d > 0.82) ? paletteDark[0] : random(paletteDark);
      let w = map(d, 0.70, 1.0, 1.1, 1.75);
      brush.set("velvet_charcoal", col, w);
      brush.spline([
        [pt.x - dx, pt.y - dy, 0.3],
        [pt.x + perpX, pt.y + perpY, 1.1],
        [pt.x + dx, pt.y + dy, 0.3]
      ], 0.45);

      // Cross-grain velvet pass in deepest core shadows
      if (d > 0.80 && random() < 0.65) {
        let cRad = rad + 0.55;
        let cdx = Math.cos(cRad) * baseLen * 0.38;
        let cdy = Math.sin(cRad) * baseLen * 0.38;
        brush.set("skin_whisper", "#050e1f", 0.95);
        brush.line(pt.x - cdx, pt.y - cdy, pt.x + cdx, pt.y + cdy);
      }
    }
  }

  // =========================================================================
  // 5. ANATOMICAL MICRO-SCULPTING (EYELASHES, BROW, LIPS, NOSE, EAR, HAIR)
  //    All rendered as tonal pigment clusters & directional hairs—zero outlines
  // =========================================================================

  // A. Sleeping Eyelashes fanning downward from the closed upper lid & Supratarsal crease
  for (let i = 0; i <= 42; i++) {
    let t = i / 42;
    let uLash = lerp(140, 50, t);
    let vLash = -14 + 6.5 * Math.sin(t * Math.PI) - 4 * t;
    let pStart = headToCanvas(uLash, vLash);
    // Lashes curve downward (+v) and slightly forward (+u)
    let lashLen = (11 + 7 * Math.sin(t * Math.PI)) * random(0.85, 1.15);
    let uMid = uLash + (4 - 8 * t) * 0.45;
    let vMid = vLash + lashLen * 0.55;
    let uEnd = uLash + (6 - 13 * t) * 0.85;
    let vEnd = vLash + lashLen;
    let pMid = headToCanvas(uMid, vMid);
    let pEnd = headToCanvas(uEnd, vEnd);

    // Soft cast shadow on upper cheek beneath each lash cluster
    let pShadow = headToCanvas(uEnd - 2, vEnd + 6);
    brush.set("skin_whisper", "#1b3a75", 0.95);
    brush.line(pMid[0], pMid[1], pShadow[0], pShadow[1]);

    // Velvety Prussian blue eyelash hair
    brush.set("2B", i % 2 === 0 ? "#050e1f" : "#0b1d3d", random(0.65, 1.05));
    brush.spline([
      [pStart[0], pStart[1], 1.1],
      [pMid[0], pMid[1], 0.8],
      [pEnd[0], pEnd[1], 0.15]
    ], 0.45);
  }

  // Supratarsal eyelid fold tonal reinforcement (soft feathered strokes along the fold)
  for (let i = 0; i < 28; i++) {
    let t = i / 27;
    let uSup = lerp(144, 50, t);
    let vSup = -31 - 14 * Math.sin(t * Math.PI);
    let p1 = headToCanvas(uSup + 3, vSup + random(-1.5, 1.5));
    let p2 = headToCanvas(uSup - 4, vSup + random(-1.5, 1.5));
    brush.set("skin_whisper", "#091836", 0.95 * Math.sin(t * Math.PI));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // B. Feathered Eyebrow Hairs emerging naturally from the brow ridge shadow
  for (let i = 0; i < 68; i++) {
    let t = i / 67;
    let uBrow = lerp(166, 20, t) + random(-3, 3);
    let vBrow = -68 - 22 * Math.sin(t * Math.PI * 0.88) + 8 * t + random(-4, 4);
    let dirU = -14 - 8 * t;
    let dirV = -9 * (1 - 1.65 * t);
    let p1 = headToCanvas(uBrow, vBrow);
    let p2 = headToCanvas(uBrow + dirU * 0.5, vBrow + dirV * 0.5);
    let p3 = headToCanvas(uBrow + dirU, vBrow + dirV);
    let col = random() < 0.6 ? "#091936" : "#18346b";
    brush.set("2B", col, random(0.6, 0.95) * Math.sin(t * Math.PI));
    brush.spline([[p1[0], p1[1], 0.3], [p2[0], p2[1], 0.95], [p3[0], p3[1], 0.15]], 0.35);
  }

  // C. Lip Vermilion Striations & Parted Mouth Core Shadow
  // Upper lip downward tonal striations in deep ultramarine & Prussian blue
  for (let i = 0; i < 36; i++) {
    let t = i / 35;
    let uTop = lerp(208, 128, t);
    let vTop = lerp(113, 141, Math.pow(t, 1.25));
    let uBot = lerp(194, 125, t);
    let vBot = 145 - 2 * Math.sin(t * Math.PI);
    let p1 = headToCanvas(uTop, vTop);
    let pMid = headToCanvas((uTop + uBot) * 0.5 + 2, (vTop + vBot) * 0.5);
    let p2 = headToCanvas(uBot, vBot);
    brush.set("skin_whisper", t < 0.7 ? "#0b1e42" : "#16336b", 0.95);
    brush.spline([[p1[0], p1[1], 0.25], [pMid[0], pMid[1], 0.95], [p2[0], p2[1], 0.8]], 0.35);
  }

  // Lower lip luminous cross-contour striations (pale cornflower & warm limestone)
  for (let i = 0; i < 32; i++) {
    let t = i / 31;
    let uMid = lerp(198, 134, t);
    let pTop = headToCanvas(uMid - 2, 149);
    let pBulge = headToCanvas(uMid + 4 * Math.sin(t * Math.PI), 162);
    let pBot = headToCanvas(uMid - 4, 177);
    let col = (t > 0.12 && t < 0.72) ? (i % 2 === 0 ? "#c8dcf5" : "#e8e2d5") : "#6b8ec2";
    brush.set("skin_whisper", col, 0.85 * Math.sin(t * Math.PI));
    brush.spline([[pTop[0], pTop[1], 0.2], [pBulge[0], pBulge[1], 1.0], [pBot[0], pBot[1], 0.2]], 0.45);
  }

  // Deepest velvety parting cleft of the sleeping lips
  for (let i = 0; i < 24; i++) {
    let t = i / 23;
    let uM = lerp(192, 123, t);
    let vM = 146 - 2 * Math.sin(t * Math.PI);
    let p1 = headToCanvas(uM + 4, vM + random(-1, 1));
    let p2 = headToCanvas(uM - 4, vM + random(-1, 1));
    brush.set("velvet_charcoal", "#050d1c", 0.95);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // D. Nostril Cavity, Alar Crease, and Luminous Nose Highlight
  for (let i = 0; i < 22; i++) {
    let t = i / 21;
    let uN = lerp(221, 185, t);
    let vN = lerp(54, 61, t) + random(-2, 2);
    let p1 = headToCanvas(uN + 3, vN - 1);
    let p2 = headToCanvas(uN - 4, vN + 2);
    brush.set("velvet_charcoal", "#040b18", 1.05 * Math.sin(t * Math.PI));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Breathing-soft highlight along the nasal dorsum, tip, eyelid sphere, and cheekbone
  const glowZones = [
    { u: 230, v: 35, su: 8, sv: 8, n: 26, col: "#eef2f9" },   // Nose tip glow
    { u: 205, v: -6, su: 5, sv: 22, n: 28, col: "#dce9f8" },  // Nose bridge glow
    { u: 98, v: -25, su: 16, sv: 6, n: 26, col: "#d8e6f7" },  // Closed eyelid glow
    { u: 62, v: 32, su: 28, sv: 20, n: 36, col: "#cfe0f5" },  // Cheekbone glow
    { u: 38, v: 108, su: 26, sv: 9, n: 24, col: "#bfd4f0" },  // Cheek pillow-compression crest
    { u: 164, v: 218, su: 13, sv: 10, n: 20, col: "#d5e4f6" } // Chin cushion glow
  ];
  for (let gz of glowZones) {
    for (let k = 0; k < gz.n; k++) {
      let gu = gz.u + randomGaussian() * gz.su * 0.55;
      let gv = gz.v + randomGaussian() * gz.sv * 0.55;
      let pA = headToCanvas(gu - 5, gv - 3);
      let pB = headToCanvas(gu + 5, gv + 3);
      brush.set("skin_whisper", gz.col, random(0.65, 1.05));
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
  }

  // E. Flowing Tousled Hair Waves at Crown & Temple (dissolving into mineral stone)
  for (let h = 0; h < 85; h++) {
    let startU = random(-185, 85);
    let startV = random(-250, -85);
    if (startU > -35 && startV > -155) continue;
    let pts = [];
    let cu = startU, cv = startV;
    let baseAng = atan2(-cv - 60, -cu - 40) + random(-25, 25);
    for (let s = 0; s < 5; s++) {
      let cp = headToCanvas(cu, cv);
      pts.push([cp[0], cp[1], s === 2 ? 1.0 : 0.25]);
      let nAng = baseAng + (noise(cu * 0.015, cv * 0.015) - 0.5) * 55;
      cu += cos(nAng) * 18;
      cv += sin(nAng) * 18;
    }
    let hCol = random(["#061124", "#0b1d3d", "#153063", "#38465e"]);
    brush.set(random() < 0.5 ? "velvet_charcoal" : "skin_whisper", hCol, random(0.75, 1.35));
    brush.spline(pts, 0.45);
  }

  // =========================================================================
  // 6. METALLIC GOLD PYRITE SPRAY & MINERAL FLECKS ACROSS FACE & PILLOWCASE
  // =========================================================================
  const goldShades = ["#8f6f32", "#b38e42", "#d4af55", "#eccb74", "#fae49b", "#fff3c4"];

  // Three sweeping diagonal pyrite drift bands across cheek, bridge of nose, temple & pillowcase
  for (let i = 0; i < 680; i++) {
    // Concentrate along natural mineral vein/drift trajectories across face and pillow
    let band = i % 3;
    let t = random();
    let bx, by, spread;
    if (band === 0) {
      // Main drift across temple, cheekbone, cheek-pillow crease, and nose tip
      bx = lerp(220, 960, t);
      by = lerp(380, 790, t) + 48 * Math.sin(t * Math.PI * 2.2);
      spread = 75 * (0.4 + 0.6 * Math.sin(t * Math.PI));
    } else if (band === 1) {
      // Secondary drift across forehead, eye socket margin, and upper right pillow
      bx = lerp(420, 1060, t);
      by = lerp(240, 620, t) - 35 * Math.cos(t * Math.PI * 1.8);
      spread = 65;
    } else {
      // Lower pillowcase fold & chin/lip drift
      bx = lerp(160, 920, t);
      by = lerp(690, 1020, t) + 40 * Math.sin(t * Math.PI * 2.5);
      spread = 85;
    }

    let px = bx + randomGaussian() * spread;
    let py = by + randomGaussian() * spread;
    if (px < 50 || px > 1150 || py < 50 || py > 1150) continue;

    // Layer 1: Fine metallic ochre-gold spray mist
    if (i % 2 === 0) {
      let mistCol = goldShades[floor(random(0, 4))];
      brush.set("pyrite_mist", mistCol, random(0.65, 1.35));
      brush.line(px, py, px + random(-6, 6), py + random(-6, 6));
    }

    // Layer 2: Crisp pyrite crystal flecks in polished lapis stone
    let crystalCol = goldShades[floor(random(1, goldShades.length))];
    let w = random() < 0.16 ? random(1.15, 1.85) : random(0.45, 1.05);
    brush.set("pyrite_crystal", crystalCol, w);
    brush.line(px, py, px + random(-2.2, 2.2), py + random(-2.2, 2.2));

    // Tiny bright specular gold glints on larger pyrite clusters
    if (random() < 0.18) {
      brush.set("2H", "#fff5cc", random(0.55, 0.95));
      brush.line(px, py, px + 1.2, py + 0.8);
    }
  }

  noLoop();
}

