function draw() {
  translate(-width / 2, -height / 2);

  // 1. Cream laid paper background, aging washes, laid & chain lines
  drawAgedLaidPaper();

  // 2. Worn stamped-ink frame enclosing the primer page
  drawStampedFrame();

  // 3. Faded tomato-red letterpress capital 'Y' and lowercase 'y' at top-left
  drawTomatoRedLetters();

  // 4. Cast shadow and twirl air-whispers beneath the hanging yo-yo
  drawYoYoShadowAndTwirl(610, 652);

  // 5. Upper cotton string (finger loop, slip-knot, frayed tail, and upper cord)
  drawCottonStringAndFibres(610, 652);

  // 6. Hyperreal burnished colored-pencil wooden yo-yo (maple grain, varnish, chipped edge)
  drawWoodenYoYo(610, 652);

  // 7. Final foreground frayed string overlap entering the yo-yo cleft
  drawStringEntryOverlap(610, 652);

  // 8. Crisp schoolbook type caption "yo-yo" below
  drawSchoolbookCaption(600, 1018);

  // 9. Final subtle paper foxing and vintage primer dust
  drawFinalPaperPatina();

  noLoop();
}

// ============================================================================
// 1. AGED CREAM LAID PAPER
// ============================================================================
function drawAgedLaidPaper() {
  background("#f3ead8");

  brush.noStroke();
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.25);

  // Warm antique edge toning and subtle foxing clouds
  const washes = [
    { x: 600, y: 600, w: 1160, h: 1160, col: "#efe3cc", op: 45 },
    { x: 600, y: 42, w: 1200, h: 110, col: "#dfcba8", op: 65 },
    { x: 600, y: 1158, w: 1200, h: 110, col: "#dfcba8", op: 70 },
    { x: 42, y: 600, w: 110, h: 1200, col: "#dfcba8", op: 65 },
    { x: 1158, y: 600, w: 110, h: 1200, col: "#dfcba8", op: 70 },
    { x: 140, y: 140, w: 280, h: 260, col: "#e4d2b4", op: 50 },
    { x: 1060, y: 1050, w: 320, h: 300, col: "#dcc59e", op: 55 },
    { x: 1040, y: 160, w: 260, h: 240, col: "#e2cea9", op: 45 },
    { x: 150, y: 1040, w: 290, h: 260, col: "#dec8a2", op: 50 }
  ];

  for (let w of washes) {
    brush.fill(w.col, w.op);
    brush.rect(w.x, w.y, w.w, w.h, "center");
  }
  brush.noFill();

  // Horizontal laid paper screen lines (fine closely spaced ridges of handmade laid paper)
  for (let y = 12; y < height - 12; y += 4.5) {
    let n = noise(y * 0.05);
    let col = (Math.floor(y / 4.5) % 2 === 0) ? "#e4d7c0" : "#faf4e6";
    let wt = map(n, 0, 1, 0.16, 0.28);
    brush.set("2H", col, wt);
    // Draw in two segments with slight organic variation
    let midX = 580 + (n - 0.5) * 80;
    brush.line(18, y + (n - 0.5) * 0.8, midX, y);
    brush.line(midX - 10, y, width - 18, y + (noise(y * 0.05 + 99) - 0.5) * 0.8);
  }

  // Vertical chain lines characteristic of antique laid paper (every ~104 px)
  for (let x = 84; x < width - 60; x += 104) {
    brush.set("2H", "#d9c8ad", 0.24);
    for (let y = 20; y < height - 20; y += 190) {
      let y2 = min(height - 20, y + 182);
      brush.line(
        x + (noise(x, y * 0.01) - 0.5) * 1.2,
        y,
        x + (noise(x, y2 * 0.01) - 0.5) * 1.2,
        y2
      );
    }
  }
}

// ============================================================================
// 2. WORN STAMPED-INK FRAME
// ============================================================================
function drawStampedFrame() {
  const x1 = 94, y1 = 90, x2 = 1106, y2 = 1110;
  const ix1 = 107, iy1 = 103, ix2 = 1093, iy2 = 1097;

  // Helper to draw a stamped woodblock/metal rule with worn, broken corners
  function drawStampedRule(ax, ay, bx, by, thickness, cornerWearDist, seedOffset) {
    let totalLen = dist(ax, ay, bx, by);
    let dx = (bx - ax) / totalLen;
    let dy = (by - ay) / totalLen;
    let nx = -dy;
    let ny = dx;

    let step = 7;
    for (let d = 0; d < totalLen; d += step) {
      let distFromEnd = min(d, totalLen - d);
      // Corner wear envelope: heavy dropout & thinning near the corners
      let cornerFactor = constrain(distFromEnd / cornerWearDist, 0, 1);
      let wearNoise = noise((ax + dx * d) * 0.025 + seedOffset, (ay + dy * d) * 0.025 + seedOffset);

      // Skip fragments at worn corners
      if (cornerFactor < 0.22 && wearNoise < 0.72) continue;
      if (cornerFactor < 0.55 && wearNoise < 0.42 * (1 - cornerFactor)) continue;

      let localThick = thickness * pow(cornerFactor, 0.45) * map(wearNoise, 0, 1, 0.65, 1.15);
      let segLen = min(step + 2.5, totalLen - d);
      let sx = ax + dx * d;
      let sy = ay + dy * d;
      let ex = ax + dx * (d + segLen);
      let ey = ay + dy * (d + segLen);

      let strands = max(1, round(localThick * 1.3));
      for (let s = 0; s < strands; s++) {
        let off = (strands === 1) ? 0 : map(s, 0, strands - 1, -localThick * 0.5, localThick * 0.5);
        off += (random() - 0.5) * 0.6;
        let nInk = noise(sx * 0.04 + s * 7, sy * 0.04);
        if (nInk < 0.16) continue; // Tiny dry-ink voids over paper grain

        let col = (nInk > 0.62) ? "#2c2621" : (nInk > 0.35 ? "#3d352e" : "#544940");
        let wt = map(nInk, 0.16, 1, 0.26, 0.52) * constrain(cornerFactor + 0.2, 0.3, 1.0);
        brush.set("stamp_ink", col, wt);
        brush.line(sx + nx * off, sy + ny * off, ex + nx * off, ey + ny * off);
      }
    }
  }

  // Outer thick stamped rule (worn at all 4 corners)
  drawStampedRule(x1, y1, x2, y1, 5.2, 85, 11);
  drawStampedRule(x2, y1, x2, y2, 5.2, 85, 23);
  drawStampedRule(x2, y2, x1, y2, 5.2, 85, 37);
  drawStampedRule(x1, y2, x1, y1, 5.2, 85, 51);

  // Inner hairline rule (even more delicately worn at corners)
  drawStampedRule(ix1, iy1, ix2, iy1, 1.4, 95, 67);
  drawStampedRule(ix2, iy1, ix2, iy2, 1.4, 95, 79);
  drawStampedRule(ix2, iy2, ix1, iy2, 1.4, 95, 93);
  drawStampedRule(ix1, iy2, ix1, iy1, 1.4, 95, 109);

  // Subtle corner stamp ghost marks (tiny dry-ink speckles where corner blocks barely kissed paper)
  const corners = [[x1, y1], [x2, y1], [x2, y2], [x1, y2], [ix1, iy1], [ix2, iy1], [ix2, iy2], [ix1, iy2]];
  for (let c of corners) {
    for (let i = 0; i < 18; i++) {
      let rx = c[0] + random(-14, 14);
      let ry = c[1] + random(-14, 14);
      brush.set("2B", "#4a4138", random(0.18, 0.35));
      brush.line(rx, ry, rx + random(-2.5, 2.5), ry + random(-2.5, 2.5));
    }
  }
}

// ============================================================================
// 3. FADED TOMATO RED SERIF 'Y' AND 'y' (TOP LEFT)
// ============================================================================
function drawTomatoRedLetters() {
  // Construct high-resolution polygon outlines with smooth bracketed serifs
  const capYPoly = buildCapitalYPolygon();
  const lowYPoly = buildLowercaseYPolygon();

  // Soft faded vermilion / tomato-red ink base wash
  brush.noStroke();
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.45, 0.35);
  brush.fill("#d44a35", 108);

  drawBrushShapeFromPoly(capYPoly);
  drawBrushShapeFromPoly(lowYPoly);
  brush.noFill();

  // Render authentic letterpress ink scanlines, edge ink-squeeze, and laid-paper dropouts
  renderLetterpressGlyph(capYPoly, 152, 365, 156, 398, 101);
  renderLetterpressGlyph(lowYPoly, 362, 508, 244, 462, 202);
}

function buildCapitalYPolygon() {
  // Classic 19th-century bold serif Capital Y
  // Bounding area roughly x: 158..355, y: 158..395
  let pts = [];
  // Top-left serif bar & bracket into thick left arm
  pts.push([156, 158], [228, 158], [228, 165]);
  pts.push([215, 166], [208, 171], [210, 180]);
  // Inner V of the Y
  pts.push([264, 276]);
  // Up the thin right arm to top-right inner serif bracket
  pts.push([312, 180], [314, 171], [307, 166], [294, 165]);
  pts.push([294, 158], [352, 158], [352, 165]);
  // Top-right outer serif bracket down right side of thin arm
  pts.push([340, 166], [331, 172], [324, 184]);
  // Down to stem right side
  pts.push([273, 286], [273, 370]);
  // Bottom-right serif bracket
  pts.push([275, 381], [283, 386], [304, 388], [304, 395]);
  // Bottom serif base
  pts.push([214, 395], [214, 388]);
  // Bottom-left serif bracket up left side of stem
  pts.push([235, 386], [243, 381], [245, 370], [245, 290]);
  // Up outer left side of thick left arm to top-left outer bracket
  pts.push([180, 182], [172, 171], [165, 166], [156, 165]);
  return pts;
}

function buildLowercaseYPolygon() {
  // Classic serif lowercase y with curved tail and lachrymal ball terminal
  // Baseline y = 395, x-height y = 248, descender to y = 458
  let pts = [];
  // Top-left serif of thick left diagonal
  pts.push([366, 248], [426, 248], [426, 255]);
  pts.push([415, 256], [410, 261], [412, 270]);
  // Inner V junction
  pts.push([444, 364]);
  // Up thin right diagonal to top-right inner bracket
  pts.push([474, 270], [475, 261], [469, 256], [459, 255]);
  pts.push([459, 248], [505, 248], [505, 255]);
  // Top-right outer bracket & down right edge of descender sweep
  pts.push([495, 256], [488, 262], [482, 275]);
  pts.push([447, 388], [435, 418], [422, 439], [408, 452], [393, 458]);

  // Ball terminal at bottom-left of descender (centered around 384, 444, radius ~13)
  for (let a = 75; a <= 315; a += 30) {
    let bx = 384 + cos(a) * 13.5;
    let by = 445 + sin(a) * 13.5;
    pts.push([bx, by]);
  }

  // Inner curve of descender sweeping back up to base of V
  pts.push([399, 444], [412, 434], [424, 415], [434, 391]);
  // Up outer edge of thick left arm
  pts.push([386, 270], [380, 260], [374, 256], [366, 255]);
  return pts;
}

function drawBrushShapeFromPoly(poly) {
  brush.beginShape(0.05);
  for (let p of poly) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

function renderLetterpressGlyph(poly, minX, maxX, minY, maxY, seedVal) {
  // 1. Horizontal & slight diagonal ink texture pass inside polygon
  for (let y = minY; y <= maxY; y += 1.7) {
    let xs = getScanlineIntersections(poly, y);
    // Check if y aligns with a recessed groove in the laid paper (creates authentic faded stripes)
    let laidGroove = (abs((y % 4.5) - 2.2) < 0.75);

    for (let i = 0; i + 1 < xs.length; i += 2) {
      let xStart = xs[i];
      let xEnd = xs[i + 1];
      let span = xEnd - xStart;
      if (span < 1) continue;

      // Subdivide long spans so ink density fluctuates organically across the letterpress face
      let step = 9;
      for (let x = xStart; x < xEnd; x += step) {
        let sx = x;
        let ex = min(x + step + 1.2, xEnd);
        let midX = (sx + ex) * 0.5;
        let n = noise(midX * 0.035 + seedVal, y * 0.035 + seedVal);

        // Faded ink dropout in paper valleys
        if (laidGroove && n < 0.58) continue;
        if (n < 0.14) continue;

        // Edge squeeze: letterpress type pushes slightly darker tomato ink to the perimeter
        let distToEdge = min(midX - xStart, xEnd - midX);
        let isEdge = distToEdge < 4.0;

        let col;
        if (isEdge) {
          col = (n > 0.45) ? "#b3311e" : "#c93f2b";
        } else {
          col = (n > 0.68) ? "#c83e2b" : (n > 0.38 ? "#dc533e" : "#e86b56");
        }

        let wt = isEdge ? 0.38 : map(n, 0.14, 1, 0.22, 0.36);
        brush.set("cpencil", col, wt);
        brush.line(sx, y + (random() - 0.5) * 0.4, ex, y + (random() - 0.5) * 0.4);
      }
    }
  }

  // 2. Diagonal cross-grain burnish for solid tomato-red pigment body
  for (let y = minY; y <= maxY; y += 3.6) {
    let xs = getScanlineIntersections(poly, y);
    for (let i = 0; i + 1 < xs.length; i += 2) {
      let xStart = xs[i] + 1.5;
      let xEnd = xs[i + 1] - 1.5;
      if (xEnd <= xStart) continue;
      let n = noise(xStart * 0.02, y * 0.02 + seedVal);
      if (n < 0.25) continue;
      brush.set("burnish", n > 0.55 ? "#d14632" : "#e05a46", 0.32);
      brush.line(xStart, y, xEnd, y + (random() - 0.5) * 1.2);
    }
  }

  // 3. Crisp letterpress ink-squeeze outline with microscopic dry breaks
  for (let i = 0; i < poly.length; i++) {
    let a = poly[i];
    let b = poly[(i + 1) % poly.length];
    let len = dist(a[0], a[1], b[0], b[1]);
    let steps = max(1, ceil(len / 8));
    for (let s = 0; s < steps; s++) {
      let t0 = s / steps;
      let t1 = (s + 1) / steps;
      let px0 = lerp(a[0], b[0], t0);
      let py0 = lerp(a[1], b[1], t0);
      let px1 = lerp(a[0], b[0], t1);
      let py1 = lerp(a[1], b[1], t1);

      let n = noise(px0 * 0.05 + seedVal, py0 * 0.05);
      if (n < 0.12) continue; // Tiny worn break in edge

      brush.set("cpencil", n > 0.5 ? "#a62917" : "#c43b27", map(n, 0, 1, 0.28, 0.48));
      brush.line(px0, py0, px1, py1);
    }
  }

  // 4. Subtle laid-paper abrasion pass (light cream fibers crossing over faded ink)
  for (let y = minY + 4; y < maxY - 4; y += 9) {
    let xs = getScanlineIntersections(poly, y);
    for (let i = 0; i + 1 < xs.length; i += 2) {
      if (random() < 0.45) {
        let rx = random(xs[i] + 3, max(xs[i] + 4, xs[i + 1] - 12));
        let rw = random(4, 14);
        if (rx + rw < xs[i + 1]) {
          brush.set("2H", "#f3ead8", 0.22);
          brush.line(rx, y, rx + rw, y);
        }
      }
    }
  }
}

function getScanlineIntersections(poly, y) {
  let hits = [];
  for (let i = 0; i < poly.length; i++) {
    let p1 = poly[i];
    let p2 = poly[(i + 1) % poly.length];
    if ((p1[1] <= y && p2[1] > y) || (p2[1] <= y && p1[1] > y)) {
      let t = (y - p1[1]) / (p2[1] - p1[1]);
      hits.push(p1[0] + t * (p2[0] - p1[0]));
    }
  }
  hits.sort((a, b) => a - b);
  return hits;
}

// ============================================================================
// 4. YO-YO CAST SHADOW & TWIRLING MOTION CUES
// ============================================================================
function drawYoYoShadowAndTwirl(cx, cy) {
  // Soft layered cast shadow on the cream laid paper to the lower-right of the hanging yo-yo
  const sx = cx + 54;
  const sy = cy + 46;

  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.5, 0.2);

  const shadowLayers = [
    { dx: 12, dy: 10, r: 186, col: "#e3d5be", op: 55 },
    { dx: 4, dy: 4, r: 168, col: "#d2c2a8", op: 65 },
    { dx: -4, dy: -2, r: 146, col: "#bfb096", op: 65 },
    { dx: -12, dy: -8, r: 118, col: "#aba08c", op: 55 }
  ];

  for (let sl of shadowLayers) {
    brush.fill(sl.col, sl.op);
    brush.circle(sx + sl.dx, sy + sl.dy, sl.r, 0.08);
  }
  brush.noFill();

  // Fine graphite pencil-grey cross-hatching inside the paper shadow
  for (let y = sy - 165; y <= sy + 165; y += 3.2) {
    let dy = (y - sy) / 165;
    if (abs(dy) >= 1) continue;
    let halfW = sqrt(1 - dy * dy) * 162;
    let xStart = sx - halfW;
    let xEnd = sx + halfW;

    for (let x = xStart; x < xEnd; x += 14) {
      let ex = min(x + 15, xEnd);
      let mx = (x + ex) * 0.5;
      let dNorm = dist(mx, y, sx - 10, sy - 6) / 165;
      if (dNorm > 1.0) continue;

      let shade = pow(1 - dNorm, 1.4) * noise(mx * 0.02, y * 0.02);
      if (shade < 0.12) continue;

      let col = (shade > 0.45) ? "#787066" : (shade > 0.25 ? "#968d81" : "#b5ab9d");
      brush.set("HB", col, map(shade, 0.12, 0.8, 0.16, 0.32));
      // Slight diagonal pencil grain
      brush.line(x, y, ex, y - (ex - x) * 0.22);
    }
  }

  // Second finer cross-hatch pass in core shadow
  for (let y = sy - 115; y <= sy + 115; y += 4.5) {
    let dy = (y - (sy - 8)) / 115;
    if (abs(dy) >= 1) continue;
    let halfW = sqrt(1 - dy * dy) * 112;
    brush.set("2H", "#827a70", 0.2);
    brush.line(sx - 10 - halfW * 0.7, y - 6, sx - 10 + halfW * 0.7, y + 6);
  }

  // Delicate colored-pencil twirl whispers (subtle rotational motion arcs around the rim)
  const twirlArcs = [
    { r: 194, a1: -55, a2: -12, col: "#b5ac9f", wt: 0.22 },
    { r: 201, a1: -42, a2: -5, col: "#cfc5b6", wt: 0.18 },
    { r: 198, a1: 128, a2: 172, col: "#aba295", wt: 0.22 },
    { r: 206, a1: 138, a2: 182, col: "#c9bfb0", wt: 0.17 },
    { r: 191, a1: 205, a2: 238, col: "#c4b299", wt: 0.19 }
  ];

  for (let ta of twirlArcs) {
    let pts = [];
    for (let a = ta.a1; a <= ta.a2; a += 6) {
      let rad = ta.r + sin(a * 3) * 1.5;
      // Match the slightly tilted perspective of the twirling yo-yo
      let px = cx + cos(a) * rad * 0.96 - sin(a) * rad * 0.08;
      let py = cy + sin(a) * rad * 0.94 + cos(a) * rad * 0.06;
      let pr = sin(map(a, ta.a1, ta.a2, 0, 180));
      pts.push([px, py, pr]);
    }
    brush.set("2H", ta.col, ta.wt);
    brush.spline(pts, 0.3);
  }
}

// ============================================================================
// 5. FRAYED TWISTED COTTON STRING WITH EVERY FIBRE
// ============================================================================
function getMainStringPoint(t, cx, cy) {
  // Smooth S-curve descending from the slip-knot at (532, 206) into the yo-yo gap at (cx + 12, cy - 115)
  let x0 = 532, y0 = 206;
  let x1 = 548, y1 = 315;
  let x2 = 602, y2 = 435;
  let x3 = cx + 10, y3 = cy - 108;

  let u = 1 - t;
  let x = u * u * u * x0 + 3 * u * u * t * x1 + 3 * u * t * t * x2 + t * t * t * x3;
  let y = u * u * u * y0 + 3 * u * u * t * y1 + 3 * u * t * t * y2 + t * t * t * y3;

  // Add subtle high-tension rotational wave near the bottom from the twirling yo-yo
  let twirlWave = sin(t * 540) * pow(t, 1.8) * 2.2;
  return { x: x + twirlWave, y: y };
}

function drawCottonStringAndFibres(cx, cy) {
  // A. Draw the top finger-loop above the slip-knot (532, 206)
  let loopPts = [];
  for (let i = 0; i <= 48; i++) {
    let t = i / 48;
    let a = map(t, 0, 1, -15, 195);
    // Teardrop finger loop
    let pinch = sin(t * 180);
    let lx = 524 - cos(a) * 24 * pinch + (1 - pinch) * 8;
    let ly = 206 - sin(a) * 74 * pow(pinch, 0.75);
    loopPts.push({ x: lx, y: ly });
  }
  renderTwistedCordAlongPath(loopPts, 3.1, 0.42, 300);

  // B. Draw the main hanging string from the slip-knot down into the yo-yo gap
  let mainPts = [];
  let steps = 95;
  for (let i = 0; i <= steps; i++) {
    mainPts.push(getMainStringPoint(i / steps, cx, cy));
  }

  // Faint cast shadow of the cotton string on the cream paper
  for (let i = 0; i < mainPts.length - 1; i++) {
    let p0 = mainPts[i];
    let p1 = mainPts[i + 1];
    brush.set("2H", "#cfc2ae", 0.38);
    brush.line(p0.x + 14, p0.y + 10, p1.x + 14, p1.y + 10);
  }

  renderTwistedCordAlongPath(mainPts, 3.6, 0.55, 700);

  // C. Draw the slip-knot collar at (532, 206)
  drawSlipKnotAndFrayedTail(532, 206);
}

function renderTwistedCordAlongPath(pts, cordRadius, frayDensity, seedBase) {
  // Compute cumulative arc length and normals
  let arcLen = [0];
  for (let i = 1; i < pts.length; i++) {
    arcLen.push(arcLen[i - 1] + dist(pts[i - 1].x, pts[i - 1].y, pts[i].x, pts[i].y));
  }
  let totalL = arcLen[arcLen.length - 1];

  // Sample along arc length in small increments to draw the 2-ply helical twist
  let stepS = 2.0;
  for (let s = 0; s < totalL - stepS; s += stepS) {
    let pA = samplePathAtArc(pts, arcLen, s);
    let pB = samplePathAtArc(pts, arcLen, s + stepS);

    let dx = pB.x - pA.x;
    let dy = pB.y - pA.y;
    let segL = max(0.001, sqrt(dx * dx + dy * dy));
    let tx = dx / segL;
    let ty = dy / segL;
    let nx = -ty;
    let ny = tx;

    // Two plies wound around each other every ~11px
    let twistAngle = s * 32;
    let ply1Off = sin(twistAngle) * cordRadius * 0.52;
    let ply2Off = sin(twistAngle + 180) * cordRadius * 0.52;
    let ply1Front = cos(twistAngle) >= 0;

    // Draw back ply then front ply
    let order = ply1Front ? [
      { off: ply2Off, phase: twistAngle + 180, front: false },
      { off: ply1Off, phase: twistAngle, front: true }
    ] : [
      { off: ply1Off, phase: twistAngle, front: false },
      { off: ply2Off, phase: twistAngle + 180, front: true }
    ];

    for (let ply of order) {
      let cx0 = pA.x + nx * ply.off;
      let cy0 = pA.y + ny * ply.off;
      let cx1 = pB.x + nx * ply.off;
      let cy1 = pB.y + ny * ply.off;

      // Across the ply width, draw 5 individual spun cotton thread lines
      let plyRad = cordRadius * 0.56;
      for (let f = -2; f <= 2; f++) {
        let u = f / 2; // -1 to 1 across the ply
        let fOff0 = u * plyRad;
        // Helical slant of threads within the ply
        let fOff1 = fOff0 + (ply.front ? 0.85 : -0.85);

        let fx0 = cx0 + nx * fOff0;
        let fy0 = cy0 + ny * fOff0;
        let fx1 = cx1 + nx * fOff1;
        let fy1 = cy1 + ny * fOff1;

        // Lighting across the rounded cotton ply + crease shadow between plies
        let lightVal = -u * 0.55 + (ply.front ? 0.22 : -0.18);
        let col, wt;
        if (abs(u) > 0.85 && !ply.front) {
          // Crisp graphite-grey outline/crease
          col = "#59524a";
          wt = 0.72;
        } else if (lightVal > 0.25) {
          // Bleached cream cotton highlight
          col = "#fcf8ef";
          wt = 0.85;
        } else if (lightVal > -0.05) {
          // Warm raw cotton midtone (ochre-cream)
          col = "#e6d7be";
          wt = 0.8;
        } else if (lightVal > -0.35) {
          // Cool pencil-grey cotton shadow
          col = "#9e9487";
          wt = 0.75;
        } else {
          // Deep twist crevice
          col = "#696158";
          wt = 0.72;
        }

        brush.set("cotton_fibre", col, wt);
        brush.line(fx0, fy0, fx1, fy1);
      }
    }

    // Crisp pencil-grey twist notch where plies cross
    if (abs(cos(twistAngle)) < 0.28) {
      brush.set("cotton_fibre", "#4f4841", 0.78);
      brush.line(
        pA.x - nx * cordRadius * 0.45,
        pA.y - ny * cordRadius * 0.45,
        pB.x + nx * cordRadius * 0.45,
        pB.y + ny * cordRadius * 0.45
      );
    }

    // Spawn individual frayed cotton halo fibers along the cord ("with every fibre")
    let wearZone = (s > totalL * 0.62 && s < totalL * 0.88) ? 1.85 : 1.0;
    if (random() < frayDensity * wearZone) {
      let side = (random() < 0.5) ? -1 : 1;
      let startX = pA.x + nx * side * cordRadius * random(0.6, 1.05);
      let startY = pA.y + ny * side * cordRadius * random(0.6, 1.05);
      drawSingleCottonFibre(startX, startY, tx, ty, nx * side, ny * side, random(7, 26) * wearZone, seedBase + s);
    }
  }
}

function drawSingleCottonFibre(sx, sy, tx, ty, nx, ny, fLen, seed) {
  // Individual cotton fiber with natural microscopic crimp and curl
  let fPts = [];
  let cx = sx;
  let cy = sy;
  let baseAngle = atan2(ty, tx) + (atan2(ny, nx) - atan2(ty, tx)) * random(0.22, 0.78);
  if (random() < 0.35) baseAngle += 180; // Some fibers fray upward, some downward

  let segs = 5;
  let stepL = fLen / segs;
  for (let i = 0; i <= segs; i++) {
    let pr = map(i, 0, segs, 0.9, 0.15);
    fPts.push([cx, cy, pr]);
    let curl = (noise(seed + i * 0.7, cx * 0.05) - 0.48) * 58;
    baseAngle += curl;
    cx += cos(baseAngle) * stepL;
    cy += sin(baseAngle) * stepL;
  }

  // Draw subtle shadow/graphite fiber + bright cream backlit sister stroke so it pops against aged paper
  let isDarkFibre = random() < 0.68;
  let col = isDarkFibre ? (random() < 0.5 ? "#6e665d" : "#8c8378") : "#fdf9f0";
  let wt = isDarkFibre ? random(0.55, 0.85) : random(0.65, 0.95);
  brush.set("cotton_fibre", col, wt);
  brush.spline(fPts, 0.45);
}

function drawSlipKnotAndFrayedTail(kx, ky) {
  // Tightly wrapped slip-knot loops at (kx, ky)
  for (let i = -4; i <= 4; i++) {
    let yOff = i * 1.4;
    let w = 6.2 - abs(i) * 0.45;
    brush.set("cotton_fibre", i < 0 ? "#fcf7ed" : "#b8ab98", 0.9);
    brush.line(kx - w, ky + yOff - 1.2, kx + w, ky + yOff + 1.2);
    brush.set("cotton_fibre", "#5e574f", 0.72);
    brush.line(kx - w, ky + yOff + 0.5, kx + w, ky + yOff + 2.0);
  }

  // Short cut tail emerging from the knot to the upper-right, unraveling into 42 distinct crinkled cotton threads
  let tailBaseX = kx + 4;
  let tailBaseY = ky - 2;
  for (let f = 0; f < 42; f++) {
    let spread = map(f, 0, 41, -38, 44);
    let angle = -24 + spread + random(-6, 6);
    let len = random(18, 38);
    let pts = [];
    let px = tailBaseX;
    let py = tailBaseY + map(f, 0, 41, -3, 3);
    for (let s = 0; s <= 5; s++) {
      pts.push([px, py, map(s, 0, 5, 0.95, 0.15)]);
      angle += (noise(f * 3.1, s * 0.8) - 0.48) * 36;
      px += cos(angle) * (len / 5);
      py += sin(angle) * (len / 5);
    }
    // Alternate dark pencil-grey fibers and cream-ochre fibers for hyperreal volume
    let col = (f % 3 === 0) ? "#635b52" : (f % 3 === 1 ? "#fcf7eb" : "#cbb99d");
    brush.set("cotton_fibre", col, random(0.65, 0.95));
    brush.spline(pts, 0.4);
  }
}

function samplePathAtArc(pts, arcLen, s) {
  s = constrain(s, 0, arcLen[arcLen.length - 1]);
  for (let i = 0; i < arcLen.length - 1; i++) {
    if (s >= arcLen[i] && s <= arcLen[i + 1]) {
      let span = max(0.0001, arcLen[i + 1] - arcLen[i]);
      let t = (s - arcLen[i]) / span;
      return {
        x: lerp(pts[i].x, pts[i + 1].x, t),
        y: lerp(pts[i].y, pts[i + 1].y, t)
      };
    }
  }
  return pts[pts.length - 1];
}

// ============================================================================
// 6. HYPERREAL BURNISHED COLOURED PENCIL WOODEN YO-YO
// ============================================================================
// 3D Orthonormal Basis for the tilted, twirling wooden yo-yo:
// W points toward the front-left-upward viewer so the back disc shifts to (+x, +y)
const YOYO_BASIS = (() => {
  // Axle direction W
  let wx = -0.44, wy = -0.17, wz = 0.8818;
  let wLen = Math.hypot(wx, wy, wz);
  wx /= wLen; wy /= wLen; wz /= wLen;

  // Up vector tilted slightly for twirl
  let upx = -0.18, upy = 0.98, upz = 0.08;
  // U = normalize(up x W)
  let ux = upy * wz - upz * wy;
  let uy = upz * wx - upx * wz;
  let uz = upx * wy - upy * wx;
  let uLen = Math.hypot(ux, uy, uz);
  ux /= uLen; uy /= uLen; uz /= uLen;

  // V = W x U
  let vx = wy * uz - wz * uy;
  let vy = wz * ux - wx * uz;
  let vz = wx * uy - wy * ux;

  return {
    U: { x: ux, y: uy, z: uz },
    V: { x: vx, y: vy, z: vz },
    W: { x: wx, y: wy, z: wz }
  };
})();

// Parametric lathe profile for one wooden half of the yo-yo: s in [0, 1]
// s = 0: center of outer face; s = 0.56: outer crown bevel; s = 0.74: outer equator rim; s = 1.0: inner cleft wall
function getHalfProfile(s, isFrontHalf) {
  let r, zLocal, dr, dz;
  const R_MAX = 178;
  const R_CROWN = 144;
  const R_RIM_CURVE = R_MAX - R_CROWN; // 34

  if (s <= 0.54) {
    // Gently domed vintage tournament face with a subtle central lathe dimple
    let t = s / 0.54;
    r = t * R_CROWN;
    // Slight dome peaking around t = 0.45
    let dome = Math.sin(t * Math.PI) * 5.5 - Math.pow(t, 2.2) * 8.0;
    zLocal = 46 + dome;
    dr = R_CROWN / 0.54;
    dz = (Math.cos(t * Math.PI) * Math.PI * 5.5 - 2.2 * Math.pow(t, 1.2) * 8.0) / 0.54;
  } else if (s <= 0.90) {
    // Generously rounded outer maple rim (torus profile sweeping 180 degrees)
    let t = (s - 0.54) / 0.36;
    let ang = t * Math.PI; // 0 to PI
    r = R_CROWN + Math.sin(ang) * R_RIM_CURVE;
    zLocal = 21 + Math.cos(ang) * 17.0;
    dr = Math.cos(ang) * R_RIM_CURVE * (Math.PI / 0.36);
    dz = -Math.sin(ang) * 17.0 * (Math.PI / 0.36);
  } else {
    // Inner face tapering toward the central axle cleft
    let t = (s - 0.90) / 0.10;
    r = R_CROWN - t * 64;
    zLocal = 4.0 - t * 2.0;
    dr = -64 / 0.10;
    dz = -2.0 / 0.10;
  }

  if (isFrontHalf) {
    return { r, z: zLocal + 6, dr, dz };
  } else {
    // Back half is mirrored across z = -10 (leaving a 20px central cleft between halves)
    return { r, z: -26 - zLocal, dr, dz: -dz };
  }
}

// Evaluate chip geometry on the front half's upper-right rim bevel
// Returns chip depth (0 = intact varnished surface, >0 = raw chipped wood cavity)
function getChipInfo(s, thetaDeg, isFrontHalf) {
  if (!isFrontHalf) return { isChipped: false, depth: 0, edgeType: "none" };

  // Normalize theta around the chip center at theta = 32 degrees
  let dTheta = ((thetaDeg - 32 + 540) % 360) - 180;
  let sCenter = 0.61;
  let ds = (s - sCenter) / 0.145;

  // Irregular jagged fracture boundary modulated by angular wood-cleavage steps
  let jag = (noise(thetaDeg * 0.18 + 50, s * 18) - 0.5) * 0.32
          + Math.sin(thetaDeg * 0.45) * 0.12;
  let normDist = Math.hypot(dTheta / 15.5, ds) + jag;

  if (normDist >= 1.0) return { isChipped: false, depth: 0, edgeType: "none" };

  // Stepped wood-splinter cavity depth
  let rawDepth = constrain((1.0 - normDist) * 2.2, 0, 1);
  let terrace = Math.floor(rawDepth * 3.5) / 3.5 * 0.45 + rawDepth * 0.55;

  // Determine if we are on the upper/left shadow cliff of the chip or lower lit lip
  let edgeType = "interior";
  if (normDist > 0.76) {
    edgeType = (dTheta < 0 || ds < -0.15) ? "shadow_cliff" : "lit_lip";
  }

  return { isChipped: true, depth: terrace, edgeType: edgeType, dTheta: dTheta, ds: ds };
}

// Project a 3D lathe point (s, thetaDeg) onto 2D canvas and compute 3D normal & wood coordinates
function evalYoYoSurface(s, thetaDeg, isFrontHalf, cx, cy) {
  let prof = getHalfProfile(s, isFrontHalf);
  let chip = getChipInfo(s, thetaDeg, isFrontHalf);

  let r = prof.r;
  let z = prof.z;

  // Carve the chipped edge physically into the 3D surface silhouette!
  if (chip.isChipped) {
    r -= chip.depth * 11.5;
    z -= chip.depth * 8.5;
  }

  let rad = thetaDeg * Math.PI / 180;
  let cosT = Math.cos(rad);
  let sinT = Math.sin(rad);

  // Local 3D coordinates (xL, yL, zL)
  let xL = r * cosT;
  let yL = r * sinT;
  let zL = z;

  const { U, V, W } = YOYO_BASIS;
  let wx = xL * U.x + yL * V.x + zL * W.x;
  let wy = xL * U.y + yL * V.y + zL * W.y;
  let wz = xL * U.z + yL * V.z + zL * W.z;

  // Surface normal in local coordinates from profile tangent (dr, dz)
  // Outward normal in (r, z) plane is (dz, -dr) for front half, (-dz, dr) for back half
  let nrL = isFrontHalf ? prof.dz : -prof.dz;
  let nzL = isFrontHalf ? -prof.dr : prof.dr;
  let nLen = Math.hypot(nrL, nzL) || 1;
  nrL /= nLen;
  nzL /= nLen;

  let nxL = nrL * cosT;
  let nyL = nrL * sinT;

  // Perturb normal inside the raw chipped wood cavity
  if (chip.isChipped) {
    if (chip.edgeType === "shadow_cliff") {
      nxL -= 0.55; nyL += 0.45; nzL -= 0.35;
    } else {
      let splinterN = (noise(xL * 0.25, yL * 0.25) - 0.5) * 0.4;
      nxL += splinterN;
      nzL += 0.3;
    }
    let l2 = Math.hypot(nxL, nyL, nzL) || 1;
    nxL /= l2; nyL /= l2; nzL /= l2;
  }

  let nx = nxL * U.x + nyL * V.x + nzL * W.x;
  let ny = nxL * U.y + nyL * V.y + nzL * W.y;
  let nz = nxL * U.z + nyL * V.z + nzL * W.z;

  return {
    x: cx + wx,
    y: cy + wy,
    z: wz,
    xL, yL, zL,
    nx, ny, nz,
    chip
  };
}

// Procedural 3D Sugar Maple Grain + Varnish Specular + Faded Vermilion Ring Shader
function shadeMaplePoint(pt, s, thetaDeg, isFrontHalf) {
  const { xL, yL, zL, nx, ny, nz, chip } = pt;

  // 1. 3D Sugar Maple Growth Rings (tilted cylinder slicing through the turned wood dome)
  // Longitudinal wood fiber axis runs along (cos(22°), sin(22°), 0.18)
  let gx = xL * 0.927 + yL * 0.374;
  let gy = -xL * 0.374 + yL * 0.927;
  let gz = zL + gy * 0.26 + gx * 0.08;

  // Distance from pith center (offset so cathedral grain arches sweep across the face)
  let pithY = gy + 68;
  let pithZ = gz - 18;
  let warp = noise(gx * 0.012 + 10, gy * 0.012 + 20, zL * 0.02 + 30) * 18.0
           + noise(gx * 0.045, gy * 0.045) * 3.5;
  let ringDist = Math.hypot(pithY * 0.52, pithZ * 1.35) + warp;

  // Growth ring profile: broad golden-ochre earlywood with crisp dark amber latewood bands
  let ringPhase = (ringDist * 0.135) % 1.0;
  let latewood = Math.pow(Math.sin(ringPhase * Math.PI), 6.5); // Sharp dark grain line
  let subRing = Math.pow(Math.sin(ringPhase * Math.PI * 2.0), 4.0) * 0.35;

  // Fine maple medullary rays & wood pores streaky along gx
  let rayNoise = noise(gx * 0.03, gy * 0.22, zL * 0.15);
  let curlyFigure = Math.sin(gx * 0.09 + noise(gx * 0.02, gy * 0.02) * 4.0) * 0.5 + 0.5;

  // 2. 3D Lighting (Key light from upper-left, warm paper bounce from lower-right)
  // Key light L1 = normalize(-0.56, -0.60, 0.57)
  let diff1 = Math.max(0, nx * -0.56 + ny * -0.60 + nz * 0.57);
  // Warm bounce light L2 = normalize(0.52, 0.48, 0.35)
  let diff2 = Math.max(0, nx * 0.52 + ny * 0.48 + nz * 0.35);

  // Glossy varnish specular reflection (Blinn-Phong half-vector H)
  // Viewer V = (0, 0, 1), H = normalize(L1 + V) = normalize(-0.36, -0.39, 0.85)
  let ndoth = Math.max(0, nx * -0.36 + ny * -0.39 + nz * 0.85);
  let spec = Math.pow(ndoth, 26) * 0.92 + Math.pow(ndoth, 6) * 0.22;

  // Secondary rim reflection sheen along lower-right bevel
  let rimSheen = Math.pow(1.0 - Math.max(0, nz), 2.6) * diff2 * 0.55;

  // Ambient occlusion near the central cleft (s > 0.82 or back half inner wall)
  let cleftAO = (s > 0.80) ? map(s, 0.80, 1.0, 1.0, 0.28) : 1.0;
  if (!isFrontHalf) cleftAO *= 0.82;

  let totalLight = (0.22 + diff1 * 0.72 + diff2 * 0.22 * (1 - diff1) + curlyFigure * 0.08) * cleftAO;

  // 3. Handle Raw Chipped Edge Material vs Varnished Maple Material
  if (chip.isChipped) {
    if (chip.edgeType === "shadow_cliff") {
      return { col: "#2e1c10", weightMult: 1.15, isSpec: false, grainVal: 1.0 };
    }
    if (chip.edgeType === "lit_lip") {
      return { col: "#fbf0da", weightMult: 1.05, isSpec: true, grainVal: 0.1 };
    }
    // Raw unvarnished splintered maple interior (pale blonde wood with fibrous grain)
    let rawGrain = noise(gx * 0.08, gy * 0.35);
    if (rawGrain > 0.68) return { col: "#b58d5d", weightMult: 0.9, isSpec: false, grainVal: 0.8 };
    if (rawGrain > 0.42) return { col: "#dfc298", weightMult: 0.95, isSpec: false, grainVal: 0.4 };
    return { col: "#f5e5c9", weightMult: 1.0, isSpec: false, grainVal: 0.2 };
  }

  // 4. Optional Faded Vermilion Tournament Pin-Stripe on the Front Face (s in 0.35..0.41)
  // Worn away in spots so the maple grain shows through, and broken by the chip!
  let isRedStripe = isFrontHalf && (s >= 0.35 && s <= 0.405);
  if (isRedStripe) {
    let wear = noise(xL * 0.04 + 77, yL * 0.04 + 77);
    if (wear > 0.26) {
      if (spec > 0.55) return { col: "#fae6d4", weightMult: 0.95, isSpec: true, grainVal: latewood };
      if (totalLight > 0.68 && latewood < 0.45) return { col: "#d9503b", weightMult: 1.0, isSpec: false, grainVal: latewood };
      if (totalLight > 0.42) return { col: "#b83623", weightMult: 1.0, isSpec: false, grainVal: latewood };
      return { col: "#7d2215", weightMult: 1.0, isSpec: false, grainVal: latewood };
    }
  }

  // 5. Varnished Maple Palette (Ochre, Raw Sienna, Warm Amber, Pencil-Grey in Shadow, Cream Burnish)
  if (spec > 0.62 && latewood < 0.65) {
    return { col: "#fffbf0", weightMult: 1.15, isSpec: true, grainVal: latewood };
  }
  if (spec > 0.36 && latewood < 0.5) {
    return { col: "#fae4b4", weightMult: 1.05, isSpec: true, grainVal: latewood };
  }

  // Effective wood brightness combining 3D lighting and dark latewood cathedral rings
  let woodVal = totalLight - latewood * 0.34 - subRing * 0.14 + (rayNoise - 0.5) * 0.08 + rimSheen;

  let col;
  if (woodVal > 0.78) {
    col = "#f5cf87"; // Bright sunlit golden maple
  } else if (woodVal > 0.64) {
    col = "#e6b05c"; // Warm honey ochre
  } else if (woodVal > 0.50) {
    col = "#d18f3b"; // Rich yellow ochre
  } else if (woodVal > 0.38) {
    col = "#b86d25"; // Varnished amber / raw sienna
  } else if (woodVal > 0.27) {
    // Cool pencil-grey mixed with burnt sienna in the form terminator (classic colored-pencil realism)
    col = (diff2 > 0.25 && latewood < 0.4) ? "#7d6854" : "#8f4a1c";
  } else if (woodVal > 0.17) {
    col = (latewood > 0.5) ? "#592b11" : "#595149"; // Deep umber grain or graphite-grey core shadow
  } else {
    col = "#36271e"; // Deepest cleft & terminator shadow
  }

  return { col, weightMult: 1.0, isSpec: false, grainVal: latewood + subRing };
}

function drawWoodenYoYo(cx, cy) {
  // -------------------------------------------------------------------------
  // STEP 1: Base Watercolor Underpainting Glazes (Warm Golden Ochre & Sienna)
  // -------------------------------------------------------------------------
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.45, 0.3);

  // Back half crescent underpainting
  brush.fill("#b8732a", 125);
  brush.circle(cx + 22, cy + 9, 174, 0.03);

  // Deep central cleft shadow underpainting
  brush.fill("#3d291d", 160);
  brush.circle(cx + 8, cy + 3, 166, 0.03);

  // Front half warm maple underpainting
  brush.fill("#de9c45", 135);
  brush.circle(cx - 16, cy - 6, 172, 0.03);

  // Upper-left sunlit ochre-cream glow
  brush.fill("#f7d996", 95);
  brush.circle(cx - 56, cy - 48, 105, 0.05);

  brush.noFill();

  // -------------------------------------------------------------------------
  // STEP 2: Render Back (Far) Wooden Half Crescent
  // Visible mainly from theta = -85° to +135° around the right/lower-right
  // -------------------------------------------------------------------------
  for (let s = 0.50; s <= 0.96; s += 0.022) {
    let stepAng = 7;
    for (let th = -92; th < 142; th += stepAng) {
      let p0 = evalYoYoSurface(s, th, false, cx, cy);
      let p1 = evalYoYoSurface(s, th + stepAng + 1.2, false, cx, cy);
      let st = shadeMaplePoint(p0, s, th, false);

      brush.set("burnish", st.col, 0.38 * st.weightMult);
      brush.line(p0.x, p0.y, p1.x, p1.y);

      if (st.grainVal > 0.42) {
        brush.set("woodgrain", "#4a2711", 0.26);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }
  }

  // Cross-contour lathe turning strokes on the back half rim
  for (let th = -85; th <= 135; th += 3.5) {
    let p0 = evalYoYoSurface(0.55, th, false, cx, cy);
    let p1 = evalYoYoSurface(0.74, th, false, cx, cy);
    let p2 = evalYoYoSurface(0.92, th, false, cx, cy);
    let st = shadeMaplePoint(p1, 0.74, th, false);
    brush.set("cpencil", st.col, 0.28);
    brush.spline([[p0.x, p0.y, 0.5], [p1.x, p1.y, 1.0], [p2.x, p2.y, 0.5]], 0.35);
  }

  // -------------------------------------------------------------------------
  // STEP 3: Deep Central Gap (Cleft) & Wound Cotton Axle Bundle Inside
  // -------------------------------------------------------------------------
  for (let th = -95; th <= 145; th += 3.0) {
    let pFrontGap = evalYoYoSurface(0.95, th, true, cx, cy);
    let pBackGap = evalYoYoSurface(0.95, th, false, cx, cy);

    // Dark recessed shadow inside the cleft
    let isUpperGap = (th > -85 && th < -25);
    let gapCol = isUpperGap ? "#2b2019" : "#1f1712";
    brush.set("charcoal", gapCol, 0.34);
    brush.line(pFrontGap.x, pFrontGap.y, pBackGap.x, pBackGap.y);

    // Glimpse of the tightly wound cotton string bundle deep inside the gap
    if (th > -78 && th < 95 && Math.floor(th / 3) % 2 === 0) {
      let mx = lerp(pFrontGap.x, pBackGap.x, 0.48);
      let my = lerp(pFrontGap.y, pBackGap.y, 0.48);
      let sCol = (th < -15) ? "#d6c5ab" : (th < 35 ? "#9c8e7b" : "#665c50");
      brush.set("cotton_fibre", sCol, 0.78);
      brush.line(mx - 2.5, my - 2.5, mx + 2.5, my + 2.5);
    }
  }

  // -------------------------------------------------------------------------
  // STEP 4: Front Wooden Half — Layer 1: Dense Burnished Colored-Pencil Rings
  // -------------------------------------------------------------------------
  for (let s = 0.02; s <= 0.94; s += 0.015) {
    // Adjust angular step so arc length is uniform from center to outer rim
    let ringStep = (s < 0.15) ? 18 : (s < 0.35 ? 10 : 6);
    for (let th = 0; th < 360; th += ringStep) {
      let p0 = evalYoYoSurface(s, th, true, cx, cy);
      let p1 = evalYoYoSurface(s, th + ringStep + 1.2, true, cx, cy);
      let st = shadeMaplePoint(p0, s, th, true);

      brush.set("burnish", st.col, 0.42 * st.weightMult);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // -------------------------------------------------------------------------
  // STEP 5: Front Wooden Half — Layer 2: Radial & Wood-Fiber Grain Pass
  // Follows the 3D maple fiber direction across the domed face and curved rim
  // -------------------------------------------------------------------------
  for (let s = 0.04; s <= 0.90; s += 0.024) {
    let rStep = (s < 0.2) ? 14 : 5;
    for (let th = 0; th < 360; th += rStep) {
      let p0 = evalYoYoSurface(s, th, true, cx, cy);
      let p1 = evalYoYoSurface(min(0.95, s + 0.032), th + 2, true, cx, cy);
      let st = shadeMaplePoint(p0, s, th, true);

      // Draw crisp dark maple cathedral grain rings & fine pores
      if (st.grainVal > 0.38 && !p0.chip.isChipped) {
        let grainCol = (st.grainVal > 0.65) ? "#632f10" : "#8c4a1d";
        brush.set("woodgrain", grainCol, map(st.grainVal, 0.38, 1.0, 0.22, 0.38));
        brush.line(p0.x, p0.y, p1.x, p1.y);
      } else {
        brush.set("cpencil", st.col, 0.26);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }
  }

  // -------------------------------------------------------------------------
  // STEP 6: Continuous Longitudinal Maple Cathedral Grain Lines Across the Face
  // -------------------------------------------------------------------------
  const grainAngle = 22;
  const cosG = cos(grainAngle), sinG = sin(grainAngle);
  for (let v = -168; v <= 168; v += 3.2) {
    let segPts = [];
    for (let u = -168; u <= 168; u += 8) {
      let xL = u * cosG - v * sinG;
      let yL = u * sinG + v * cosG;
      let r = Math.hypot(xL, yL);
      if (r > 168) continue;

      // Map r back to profile parameter s in [0, 0.72]
      let s = (r <= 144) ? (r / 144) * 0.54 : 0.54 + ((r - 144) / 34) * 0.18;
      let th = atan2(yL, xL);
      let pt = evalYoYoSurface(s, th, true, cx, cy);
      let st = shadeMaplePoint(pt, s, th, true);

      if (st.grainVal > 0.32 && !pt.chip.isChipped) {
        segPts.push({ x: pt.x, y: pt.y, col: st.grainVal > 0.6 ? "#6e3512" : "#9e5724", wt: map(st.grainVal, 0.3, 1, 0.18, 0.34) });
      } else {
        if (segPts.length >= 2) flushGrainRun(segPts);
        segPts = [];
      }
    }
    if (segPts.length >= 2) flushGrainRun(segPts);
  }

  // -------------------------------------------------------------------------
  // STEP 7: Center Lathe Boss / Axle Dimple & Glossy Varnish Specular Burnish
  // -------------------------------------------------------------------------
  for (let th = 0; th < 360; th += 15) {
    let pIn = evalYoYoSurface(0.015, th, true, cx, cy);
    let pOut = evalYoYoSurface(0.045, th + 25, true, cx, cy);
    let col = (th > 130 && th < 310) ? "#f7dfb0" : "#6e3b19";
    brush.set("woodgrain", col, 0.25);
    brush.line(pIn.x, pIn.y, pOut.x, pOut.y);
  }

  // High-sheen white/cream colored-pencil burnish on the upper-left dome & rim ridge
  for (let s = 0.12; s <= 0.68; s += 0.018) {
    for (let th = 185; th <= 265; th += 4) {
      let pt = evalYoYoSurface(s, th, true, cx, cy);
      let st = shadeMaplePoint(pt, s, th, true);
      if (st.isSpec) {
        let pNext = evalYoYoSurface(s, th + 5, true, cx, cy);
        brush.set("burnish", st.col, 0.38);
        brush.line(pt.x, pt.y, pNext.x, pNext.y);
      }
    }
  }

  // -------------------------------------------------------------------------
  // STEP 8: Hyper-Detailed Chipped Edge on the Rim (Splinters, Varnish Ridge, Shadow)
  // -------------------------------------------------------------------------
  drawChippedEdgeDetail(cx, cy);

  // -------------------------------------------------------------------------
  // STEP 9: Crisp Graphite-Grey & Umber Form Contouring Around the Silhouette
  // -------------------------------------------------------------------------
  for (let th = 0; th < 360; th += 4) {
    let p0 = evalYoYoSurface(0.73, th, true, cx, cy);
    let p1 = evalYoYoSurface(0.73, th + 4.5, true, cx, cy);
    let isShadowSide = (th > -30 && th < 140);
    let col = p0.chip.isChipped ? "#4a3322" : (isShadowSide ? "#3b281c" : "#8c5828");
    let wt = isShadowSide ? 0.34 : 0.22;
    brush.set("woodgrain", col, wt);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }
}

function flushGrainRun(segPts) {
  for (let i = 0; i < segPts.length - 1; i++) {
    brush.set("woodgrain", segPts[i].col, segPts[i].wt);
    brush.line(segPts[i].x, segPts[i].y, segPts[i + 1].x, segPts[i + 1].y);
  }
}

function drawChippedEdgeDetail(cx, cy) {
  // Fine raw wood splinters, sharp varnish break-line, and fracture crevices around theta = 16°..48°, s = 0.46..0.76
  for (let s = 0.46; s <= 0.76; s += 0.01) {
    for (let th = 15; th <= 49; th += 1.4) {
      let pt = evalYoYoSurface(s, th, true, cx, cy);
      if (!pt.chip.isChipped) continue;

      // Align splinters with the maple wood fiber direction
      let pNext = evalYoYoSurface(min(0.78, s + 0.022), th + 1.8, true, cx, cy);

      if (pt.chip.edgeType === "shadow_cliff") {
        // Sharp dark crevice where the thick amber varnish broke off
        brush.set("cotton_fibre", "#24150b", 0.92);
        brush.line(pt.x, pt.y, pNext.x, pNext.y);
        // Tiny golden varnish thickness highlight just outside the break
        brush.set("cotton_fibre", "#f7d488", 0.75);
        brush.line(pt.x - 1.5, pt.y - 1.2, pt.x + 0.5, pt.y - 0.5);
      } else if (pt.chip.edgeType === "lit_lip") {
        // Crisp sunlit raw-wood bottom fracture edge
        brush.set("cotton_fibre", "#fff8e8", 0.95);
        brush.line(pt.x, pt.y, pNext.x, pNext.y);
      } else {
        // Fibrous splintered raw maple interior
        let n = noise(pt.xL * 0.35, pt.yL * 0.35);
        let col = (n > 0.66) ? "#6e4e2e" : (n > 0.38 ? "#d9ba8c" : "#f7e8ce");
        brush.set("cotton_fibre", col, map(n, 0, 1, 0.65, 0.95));
        brush.line(pt.x, pt.y, pNext.x, pNext.y);
      }
    }
  }

  // A few tiny protruding wood-splinter whiskers along the chipped rim silhouette
  for (let th = 22; th <= 43; th += 3.5) {
    let pt = evalYoYoSurface(0.68, th, true, cx, cy);
    if (pt.chip.isChipped) {
      brush.set("cotton_fibre", "#e8cfa6", 0.8);
      brush.line(pt.x, pt.y, pt.x + random(2, 5), pt.y - random(2, 6));
      brush.set("cotton_fibre", "#593e25", 0.65);
      brush.line(pt.x, pt.y + 1, pt.x + random(1, 4), pt.y - random(1, 4));
    }
  }
}

// ============================================================================
// 7. FOREGROUND FRAYED STRING OVERLAP AT THE YO-YO CLEFT ENTRY
// ============================================================================
function drawStringEntryOverlap(cx, cy) {
  // Draw the bottom segment of the cotton string (t = 0.78..1.0) right where it plunges
  // between the two wooden halves, with extra chafed cotton fibers catching the rim light
  let entryPts = [];
  for (let i = 0; i <= 24; i++) {
    let t = map(i, 0, 24, 0.78, 1.0);
    entryPts.push(getMainStringPoint(t, cx, cy));
  }
  renderTwistedCordAlongPath(entryPts, 3.5, 0.85, 950);
}

