// 8. CRISP SCHOOLBOOK TYPE CAPTION: "yo-yo"
// ============================================================================
function drawSchoolbookCaption(centerX, baseY) {
  // Authentic Century Schoolbook lowercase "yo-yo" centered at (centerX, baseY)
  // Character centers: 'y' (-94), 'o' (-46), '-' (0), 'y' (+46), 'o' (+94)
  drawSchoolbookLowerY(centerX - 94, baseY);
  drawSchoolbookLowerO(centerX - 44, baseY);
  drawSchoolbookHyphen(centerX, baseY);
  drawSchoolbookLowerY(centerX + 46, baseY);
  drawSchoolbookLowerO(centerX + 96, baseY);
}

function drawSchoolbookLowerY(cx, baseY) {
  // x-height = 36px (top at baseY - 36), descender to baseY + 20
  let topY = baseY - 36;
  let poly = [
    // Top-left serif
    [cx - 19, topY], [cx - 4, topY], [cx - 4, topY + 3],
    [cx - 7, topY + 3.5], [cx - 8, topY + 6],
    // Inner V junction
    [cx + 1, baseY - 6],
    // Up thin right arm to top-right serif
    [cx + 9, topY + 6], [cx + 8, topY + 3.5], [cx + 5, topY + 3],
    [cx + 5, topY], [cx + 18, topY], [cx + 18, topY + 3],
    [cx + 15, topY + 3.5], [cx + 13, topY + 7],
    // Down right edge of descender
    [cx + 2, baseY + 2], [cx - 3, baseY + 13], [cx - 8, baseY + 19], [cx - 13, baseY + 21],
    // Ball terminal at bottom-left
    [cx - 17, baseY + 20], [cx - 19, baseY + 16], [cx - 17, baseY + 12], [cx - 13, baseY + 12],
    [cx - 11, baseY + 15], [cx - 7, baseY + 15], [cx - 3, baseY + 9], [cx - 1, baseY + 1],
    // Up outer left thick arm
    [cx - 14, topY + 7], [cx - 16, topY + 3.5], [cx - 19, topY + 3]
  ];
  renderSchoolbookGlyphPoly(poly, topY, baseY + 22);
}

function drawSchoolbookLowerO(cx, baseY) {
  // Classic serif oval 'o' with vertical stress (thick left/right bowls, thin top/bottom hairlines)
  let cy = baseY - 18;
  let rxOut = 16.5, ryOut = 19.0;
  let rxIn = 8.8, ryIn = 15.2;

  for (let y = cy - ryOut; y <= cy + ryOut; y += 1.2) {
    let dyOut = (y - cy) / ryOut;
    if (abs(dyOut) > 1) continue;
    let xOut = sqrt(1 - dyOut * dyOut) * rxOut;

    let dyIn = (y - cy) / ryIn;
    if (abs(dyIn) >= 1) {
      // Top or bottom arch
      drawInkSpan(cx - xOut, cx + xOut, y);
    } else {
      let xIn = sqrt(1 - dyIn * dyIn) * rxIn;
      drawInkSpan(cx - xOut, cx - xIn, y);
      drawInkSpan(cx + xIn, cx + xOut, y);
    }
  }

  // Crisp outer & inner contour pass
  for (let a = 0; a < 360; a += 15) {
    let a2 = a + 15;
    brush.set("rotring", "#26211c", 0.35);
    brush.line(cx + cos(a) * rxOut, cy + sin(a) * ryOut, cx + cos(a2) * rxOut, cy + sin(a2) * ryOut);
    brush.line(cx + cos(a) * rxIn, cy + sin(a) * ryIn, cx + cos(a2) * rxIn, cy + sin(a2) * ryIn);
  }
}

function drawSchoolbookHyphen(cx, baseY) {
  let yMid = baseY - 16;
  let poly = [
    [cx - 9, yMid - 2.5],
    [cx + 9, yMid - 2.5],
    [cx + 9, yMid + 2.5],
    [cx - 9, yMid + 2.5]
  ];
  renderSchoolbookGlyphPoly(poly, yMid - 3, yMid + 3);
}

function renderSchoolbookGlyphPoly(poly, minY, maxY) {
  for (let y = minY; y <= maxY; y += 1.2) {
    let xs = getScanlineIntersections(poly, y);
    for (let i = 0; i + 1 < xs.length; i += 2) {
      drawInkSpan(xs[i], xs[i + 1], y);
    }
  }
  for (let i = 0; i < poly.length; i++) {
    let a = poly[i];
    let b = poly[(i + 1) % poly.length];
    brush.set("rotring", "#241f1a", 0.36);
    brush.line(a[0], a[1], b[0], b[1]);
  }
}

function drawInkSpan(x0, x1, y) {
  if (x1 <= x0) return;
  let n = noise(x0 * 0.08, y * 0.08);
  let col = (n > 0.35) ? "#241f1b" : "#3b332c";
  brush.set("rotring", col, 0.38);
  brush.line(x0, y, x1, y);
}

// ============================================================================
// 9. FINAL PAPER PATINA & VINTAGE PRIMER SPECKLES
// ============================================================================
function drawFinalPaperPatina() {
  // Subtle aged paper foxing flecks and microscopic fiber dust across the sheet
  for (let i = 0; i < 110; i++) {
    let x = random(28, width - 28);
    let y = random(28, height - 28);
    // Keep the very center of the yo-yo face clean
    if (dist(x, y, 600, 650) < 150 && random() < 0.75) continue;

    let col = (random() < 0.5) ? "#c9b391" : (random() < 0.5 ? "#b59872" : "#dfd0b6");
    brush.set("2H", col, random(0.14, 0.28));
    let ang = random(360);
    let len = random(1.5, 4.5);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

// Hyperrealism in p5.brush:
// Three uncapped felt-tip pens on buckled laboratory filter paper with chromatography rings

const DEG2RAD = Math.PI / 180;
function dCos(deg) { return Math.cos(deg * DEG2RAD); }
function dSin(deg) { return Math.sin(deg * DEG2RAD); }

// Filter paper center and radius
const PAPER_CX = 590;
const PAPER_CY = 595;
const PAPER_R = 472;
const TIDEMARK_R = 398;

// Three chromatography plume centers (slightly wicked ahead of each nib)
const PLUMES = [
  {
    // Plume 0: Black ink splitting into Cerulean, Rose Madder, and Lemon
    cx: 492, cy: 488,
    nibX: 500, nibY: 495,
    type: "black",
    maxR: 215,
    seed: 11.3
  },
