function draw() {
  translate(-width / 2, -height / 2);

  // 1. Cool fluorescent laboratory bench surface
  drawLabBench();

  // 2. Buckled filter paper cast shadow & 3D undulating paper surface
  drawFilterPaperShadow();
  drawBuckledFilterPaper();

  // 3. Damp solvent zone & hard pale outermost tidemark
  drawSolventFrontAndTidemark();

  // 4. Concentric chromatography rings, wet collision blooms & feathered capillary edges
  drawChromatographyPlumes();
  drawMeetingWetBlooms();
  drawCapillaryFeathering();

  // 5. Three uncapped felt-tip pens with barrels, cap clips, logos & plastic sheen
  drawAllPens();

  // 6. Final wet nib menisci and overhead cool fluorescent light veil
  drawNibContactMenisci();

  noLoop();
}

// ============================================================================
// GEOMETRY & TOPOGRAPHY HELPERS
// ============================================================================

function drawPoly(pts, curvature = 0.12) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Radial undulation of the damp buckled filter paper
function paperRimRadius(deg) {
  let n1 = noise(20 + dCos(deg) * 1.4, 20 + dSin(deg) * 1.4) - 0.5;
  let n2 = noise(50 + dCos(deg) * 4.5, 50 + dSin(deg) * 4.5) - 0.5;
  let n3 = noise(90 + dCos(deg) * 14.0, 90 + dSin(deg) * 14.0) - 0.5;
  // 8 gentle radial buckles around the perimeter
  let buckle = Math.sin(deg * 8 * DEG2RAD + 0.6) * 4.5 + Math.cos(deg * 5 * DEG2RAD - 0.4) * 3.2;
  return PAPER_R + n1 * 18 + n2 * 6 + n3 * 2.2 + buckle;
}

// Height of the paper buckle above the bench at angle deg (0 to 1)
function paperRimLift(deg) {
  let wave = 0.5 + 0.35 * Math.sin(deg * 8 * DEG2RAD + 0.6) + 0.15 * Math.cos(deg * 5 * DEG2RAD - 0.4);
  return constrain(wave, 0.08, 1.0);
}

// Outermost solvent front (hard pale tidemark) radius at angle deg
function tidemarkRadius(deg) {
  let px = PAPER_CX + TIDEMARK_R * dCos(deg);
  let py = PAPER_CY + TIDEMARK_R * dSin(deg);

  // Bulge outward slightly toward the three nib plumes
  let bulge = 0;
  for (let p of PLUMES) {
    let d = dist(px, py, p.cx, p.cy);
    bulge += Math.exp(-(d * d) / 65000) * 26;
  }

  let nLow = (noise(10 + dCos(deg) * 2.2, 10 + dSin(deg) * 2.2) - 0.5) * 24;
  let nMid = (noise(30 + dCos(deg) * 6.5, 30 + dSin(deg) * 6.5) - 0.5) * 11;
  let nHigh = (noise(70 + dCos(deg) * 18.0, 70 + dSin(deg) * 18.0) - 0.5) * 4.5;
  return TIDEMARK_R - 14 + bulge + nLow + nMid + nHigh;
}

// Deformed chromatography ring point that flattens & ruffles where plumes collide
function getPlumePoint(plumeIdx, baseFrac, deg, extraNoise = 1.0) {
  let p = PLUMES[plumeIdx];
  let r0 = baseFrac * p.maxR;

  // Multi-scale capillary boundary waviness
  let c = dCos(deg);
  let s = dSin(deg);
  let n1 = (noise(p.seed + c * 1.8, p.seed + s * 1.8 + baseFrac * 1.2) - 0.48) * 18 * baseFrac;
  let n2 = (noise(p.seed * 2 + c * 5.5, p.seed * 2 + s * 5.5 + baseFrac * 2.5) - 0.48) * 9 * baseFrac * extraNoise;
  let n3 = (noise(p.seed * 3 + c * 14.0, p.seed * 3 + s * 14.0 + baseFrac * 4.0) - 0.48) * 4.2 * baseFrac * extraNoise;

  let r = Math.max(2, r0 + n1 + n2 + n3);
  let x = p.cx + r * c;
  let y = p.cy + r * s;

  // Mutual fluid-front compression where neighboring plumes meet
  for (let j = 0; j < PLUMES.length; j++) {
    if (j === plumeIdx) continue;
    let o = PLUMES[j];
    let dx = x - o.cx;
    let dy = y - o.cy;
    let d = Math.sqrt(dx * dx + dy * dy);
    let influenceR = o.maxR * 0.92;
    if (d < influenceR && d > 1) {
      let overlap = (influenceR - d) / influenceR;
      let push = overlap * overlap * 36 * baseFrac;
      // Add cauliflower ruffle along the meeting boundary
      let ruffle = (noise(x * 0.045, y * 0.045) - 0.5) * 14 * overlap;
      x += (dx / d) * (push + ruffle);
      y += (dy / d) * (push + ruffle);
    }
  }

  return [x, y];
}

// Build an annular sector polygon for a chromatography ring between fracIn and fracOut
function buildRingSector(plumeIdx, fracIn, fracOut, degStart, degEnd, step = 4) {
  let pts = [];
  for (let a = degStart; a <= degEnd; a += step) {
    pts.push(getPlumePoint(plumeIdx, fracOut, a, 1.1));
  }
  for (let a = degEnd; a >= degStart; a -= step) {
    pts.push(getPlumePoint(plumeIdx, fracIn, a, 0.85));
  }
  return pts;
}

function buildFullPlumePoly(plumeIdx, frac, step = 4) {
  let pts = [];
  for (let a = 0; a < 360; a += step) {
    pts.push(getPlumePoint(plumeIdx, frac, a, 1.0));
  }
  return pts;
}

// ============================================================================
// 1. COOL FLUORESCENT LAB BENCH
// ============================================================================

function drawLabBench() {
  background("#5d6f80");
  brush.noField();

  // Deep cool slate corners (vignette away from overhead fluorescent fixture)
  let corners = [
    [[0, 0], [1200, 0], [1200, 260], [0, 340]],
    [[0, 880], [1200, 820], [1200, 1200], [0, 1200]],
    [[0, 0], [260, 0], [200, 1200], [0, 1200]],
    [[940, 0], [1200, 0], [1200, 1200], [980, 1200]]
  ];
  brush.noStroke();
  brush.fill("#435363", 85);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.45, 0.25);
  for (let c of corners) drawPoly(c, 0.05);

  // Cool overhead fluorescent reflection band across upper-mid benchtop
  brush.fill("#8599ad", 65);
  brush.fillBleed(0.5, "out");
  drawPoly([[60, 110], [1140, 85], [1170, 410], [40, 460]], 0.2);

  brush.fill("#a3b7ca", 45);
  drawPoly([[160, 165], [1040, 145], [1060, 310], [140, 340]], 0.2);

  brush.noFill();

  // Subtle epoxy lab counter seam lines and calibrated bench markings in corners
  brush.set("rotring", "#3a4856", 0.35);
  brush.line(0, 138, 1200, 112);
  brush.line(132, 0, 108, 1200);
  brush.set("2H", "#7c90a3", 0.28);
  brush.line(0, 140, 1200, 114);
  brush.line(134, 0, 110, 1200);

  // Faint millimeter scale ticks etched near top-left lab bench corner
  brush.set("microprint", "#8fa3b5", 0.35);
  for (let i = 0; i <= 25; i++) {
    let tx = 38 + i * 6;
    let ty = 137 - (tx / 1200) * 26;
    let len = (i % 5 === 0) ? 9 : 4.5;
    brush.line(tx, ty - len, tx, ty);
  }

  // Fine mineral grain on the lab bench
  brush.set("cellulose", "#3f4f5e", 0.7);
  for (let i = 0; i < 48; i++) {
    let y = random(20, 1180);
    let x1 = random(10, 300);
    let x2 = x1 + random(80, 260);
    if (dist((x1 + x2) * 0.5, y, PAPER_CX, PAPER_CY) > PAPER_R - 20) {
      brush.line(x1, y, x2, y + random(-8, 8));
    }
  }
}

// ============================================================================
// 2. BUCKLED FILTER PAPER & CAST SHADOW
// ============================================================================

function drawFilterPaperShadow() {
  brush.noStroke();

  // Outer soft penumbra cast by the buckled filter paper under fluorescent tubes
  let shadowOuter = [];
  let shadowInner = [];
  for (let a = 0; a < 360; a += 4) {
    let r = paperRimRadius(a);
    let lift = paperRimLift(a);
    let sx = PAPER_CX + 5 + lift * 10;
    let sy = PAPER_CY + 10 + lift * 18;
    shadowOuter.push([sx + (r + 6 * lift) * dCos(a), sy + (r + 6 * lift) * dSin(a)]);
    shadowInner.push([PAPER_CX + 3 + (r + 1) * dCos(a), PAPER_CY + 6 + (r + 1) * dSin(a)]);
  }

  brush.fill("#283440", 95);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.4, 0.3);
  drawPoly(shadowOuter, 0.15);

  brush.fill("#18222c", 135);
  brush.fillBleed(0.18, "out");
  drawPoly(shadowInner, 0.12);
  brush.noFill();
}

function drawBuckledFilterPaper() {
  let rimPts = [];
  for (let a = 0; a < 360; a += 3) {
    let r = paperRimRadius(a);
    rimPts.push([PAPER_CX + r * dCos(a), PAPER_CY + r * dSin(a)]);
  }

  // Opaque chalky cool-white base for the filter paper circle
  brush.noStroke();
  brush.wash("#f1f6fb", 252);
  drawPoly(rimPts, 0.1);
  brush.noWash();

  // Soft watercolor paper-tone layer
  brush.fill("#e8f0f8", 85);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.5, 0.35);
  drawPoly(rimPts, 0.1);

  // Radial buckling troughs (cool blue-grey shadow lobes where the damp paper warps)
  let troughAngles = [18, 63, 112, 158, 204, 248, 294, 338];
  brush.fill("#c5d4e3", 68);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.45, 0.25);

  for (let ta of troughAngles) {
    let lobe = [];
    let rIn = random(210, 275);
    let rOut = PAPER_R - 6;
    let halfSpan = random(11, 16);
    lobe.push([PAPER_CX + rIn * dCos(ta), PAPER_CY + rIn * dSin(ta)]);
    for (let a = ta - halfSpan; a <= ta + halfSpan; a += 4) {
      let rr = paperRimRadius(a) - 3;
      lobe.push([PAPER_CX + rr * dCos(a), PAPER_CY + rr * dSin(a)]);
    }
    drawPoly(lobe, 0.25);
  }

  // Deeper shadow pockets in the southern/lower troughs (facing away from top light)
  brush.fill("#b2c4d6", 62);
  brush.fillBleed(0.38, "out");
  for (let ta of [63, 112, 158, 248, 294]) {
    let pocket = [];
    let rMid = 340;
    for (let a = ta - 9; a <= ta + 9; a += 4) {
      let rr = paperRimRadius(a) - 8;
      pocket.push([PAPER_CX + rr * dCos(a), PAPER_CY + rr * dSin(a)]);
    }
    pocket.push([PAPER_CX + rMid * dCos(ta + 4), PAPER_CY + rMid * dSin(ta + 4)]);
    pocket.push([PAPER_CX + rMid * dCos(ta - 4), PAPER_CY + rMid * dSin(ta - 4)]);
    drawPoly(pocket, 0.25);
  }

  // Bright fluorescent highlights on the swollen ridges between troughs
  brush.fill("#ffffff", 95);
  brush.fillBleed(0.3, "out");
  for (let ta of troughAngles) {
    let ra = ta + 22;
    let ridge = [];
    ridge.push([PAPER_CX + 230 * dCos(ra), PAPER_CY + 230 * dSin(ra)]);
    for (let a = ra - 8; a <= ra + 8; a += 4) {
      let rr = paperRimRadius(a) - 10;
      ridge.push([PAPER_CX + rr * dCos(a), PAPER_CY + rr * dSin(a)]);
    }
    drawPoly(ridge, 0.25);
  }
  brush.noFill();

  // Delicate 2H graphite cross-contour shading on the paper buckles & deckle edge
  brush.set("2H", "#a7b9cc", 0.28);
  for (let ta of troughAngles) {
    for (let r = 310; r < PAPER_R - 8; r += 7) {
      let span = map(r, 310, PAPER_R, 4, 13);
      let x1 = PAPER_CX + r * dCos(ta - span);
      let y1 = PAPER_CY + r * dSin(ta - span);
      let xm = PAPER_CX + (r + 3) * dCos(ta);
      let ym = PAPER_CY + (r + 3) * dSin(ta);
      let x2 = PAPER_CX + r * dCos(ta + span);
      let y2 = PAPER_CY + r * dSin(ta + span);
      brush.spline([[x1, y1, 0.2], [xm, ym, 0.7], [x2, y2, 0.2]], 0.5);
    }
  }

  // Crisp fibrous edge of the circular filter paper
  brush.set("2H", "#8b9eb3", 0.38);
  drawPoly(rimPts, 0.1);

  // Subtle embossed "WHATMAN No. 1" / "185mm" blind-stamp arcs near top dry edge
  brush.set("2H", "#c4d2e0", 0.25);
  brush.arc(PAPER_CX, PAPER_CY, PAPER_R - 28, -112, -68);
  brush.arc(PAPER_CX, PAPER_CY, PAPER_R - 36, -108, -72);

  // Cellulose fiber texture across the paper
  brush.set("cellulose", "#cbd8e6", 0.65);
  for (let i = 0; i < 65; i++) {
    let ang = random(360);
    let rad = random(180, PAPER_R - 18);
    let x = PAPER_CX + rad * dCos(ang);
    let y = PAPER_CY + rad * dSin(ang);
    brush.line(x, y, x + random(-45, 45), y + random(-45, 45));
  }
}

// ============================================================================
// 3. DAMP SOLVENT ZONE & HARD PALE TIDEMARK
// ============================================================================

function drawSolventFrontAndTidemark() {
  let outerTide = [];
  let innerTide = [];
  let haloTide = [];

  for (let a = 0; a < 360; a += 3) {
    let r = tidemarkRadius(a);
    outerTide.push([PAPER_CX + r * dCos(a), PAPER_CY + r * dSin(a)]);
    innerTide.push([PAPER_CX + (r - 11) * dCos(a), PAPER_CY + (r - 11) * dSin(a)]);
    haloTide.push([PAPER_CX + (r + 5) * dCos(a), PAPER_CY + (r + 5) * dSin(a)]);
  }

  brush.noStroke();

  // Slightly cooler, translucent damp interior of the wet circle
  brush.fill("#dbe7f2", 52);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.65, 0.75);
  drawPoly(outerTide, 0.12);

  // Build annular sectors for the hard pale tidemark (mineral/cellulose sizing ring)
  brush.fill("#cfd4c4", 78);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.82, 0.92);
  for (let a = 0; a < 360; a += 30) {
    let sec = [];
    for (let t = a; t <= a + 30; t += 3) {
      let r = tidemarkRadius(t);
      sec.push([PAPER_CX + r * dCos(t), PAPER_CY + r * dSin(t)]);
    }
    for (let t = a + 30; t >= a; t -= 3) {
      let r = tidemarkRadius(t) - 9;
      sec.push([PAPER_CX + r * dCos(t), PAPER_CY + r * dSin(t)]);
    }
    drawPoly(sec, 0.1);
  }
  brush.noFill();

  // Bright dry refractive rim just outside the wet tidemark front
  brush.set("specular", "#ffffff", 0.55);
  drawPoly(haloTide, 0.12);

  // Hard pale tidemark double-capillary line (pale ochre-grey & cool mineral graphite)
  brush.set("cpencil", "#b8baa4", 0.52);
  drawPoly(outerTide, 0.12);

  brush.set("2H", "#94a3b0", 0.34);
  drawPoly(outerTide, 0.12);

  brush.set("rotring", "#a6b0a2", 0.22);
  drawPoly(innerTide, 0.12);

  // Tiny wet capillary micro-beads along the tidemark perimeter
  brush.set("capillary", "#9aa69b", 0.32);
  for (let a = 0; a < 360; a += 2) {
    let r = tidemarkRadius(a);
    let x1 = PAPER_CX + (r - 4) * dCos(a);
    let y1 = PAPER_CY + (r - 4) * dSin(a);
    let x2 = PAPER_CX + (r + random(1, 4)) * dCos(a);
    let y2 = PAPER_CY + (r + random(1, 4)) * dSin(a);
    brush.line(x1, y1, x2, y2);
  }
}

// ============================================================================
// 4. CHROMATOGRAPHY SEPARATIONS, WET BLOOMS & FEATHERED CAPILLARY EDGES
// ============================================================================

function drawChromatographyPlumes() {
  brush.noStroke();

  // --------------------------------------------------------------------------
  // PLUME 0: BLACK INK -> Concentric rings of Cerulean, Rose Madder, and Lemon
  // --------------------------------------------------------------------------
  // 1a. Outer Lemon Band (frac 0.70 to 1.00)
  brush.fill("#f2e436", 138);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.68, 0.78);
  for (let a = 0; a < 360; a += 45) {
    drawPoly(buildRingSector(0, 0.68, 1.00, a, a + 45, 5), 0.15);
  }
  // Luminous inner lemon-gold enrichment
  brush.fill("#e8d217", 95);
  brush.fillBleed(0.22, "out");
  for (let a = 0; a < 360; a += 60) {
    drawPoly(buildRingSector(0, 0.72, 0.90, a, a + 60, 5), 0.15);
  }

  // 1b. Middle Rose Madder Band (frac 0.42 to 0.73)
  brush.fill("#d93268", 145);
  brush.fillBleed(0.30, "out");
  brush.fillTexture(0.72, 0.82);
  for (let a = 0; a < 360; a += 45) {
    drawPoly(buildRingSector(0, 0.41, 0.73, a, a + 45, 5), 0.15);
  }
  // Deep quinacridone/rose madder concentration ridge
  brush.fill("#b51b50", 105);
  brush.fillBleed(0.20, "in");
  for (let a = 0; a < 360; a += 60) {
    drawPoly(buildRingSector(0, 0.48, 0.64, a, a + 60, 5), 0.15);
  }

  // 1c. Inner Cerulean Band (frac 0.16 to 0.46)
  brush.fill("#0b82c9", 158);
  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.74, 0.84);
  for (let a = 0; a < 360; a += 45) {
    drawPoly(buildRingSector(0, 0.15, 0.46, a, a + 45, 5), 0.15);
  }
  // Intense cerulean-cyan inner ring
  brush.fill("#065a94", 118);
  brush.fillBleed(0.18, "in");
  for (let a = 0; a < 360; a += 60) {
    drawPoly(buildRingSector(0, 0.18, 0.34, a, a + 60, 5), 0.15);
  }

  // 1d. Nib Origin Core: Carbon Violet-Black
  brush.fill("#161a29", 195);
  brush.fillBleed(0.22, "out");
  drawPoly(buildFullPlumePoly(0, 0.19, 8), 0.18);

  // --------------------------------------------------------------------------
  // PLUME 1: BROWN INK -> Concentric/fanned bands of Violet and Saffron
  // --------------------------------------------------------------------------
  // 2a. Outer Saffron Band (frac 0.62 to 1.00)
  brush.fill("#f59e19", 148);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.70, 0.82);
  for (let a = 0; a < 360; a += 45) {
    drawPoly(buildRingSector(1, 0.60, 1.00, a, a + 45, 5), 0.15);
  }
  // Deep warm saffron-amber fringe
  brush.fill("#de780d", 108);
  brush.fillBleed(0.24, "out");
  for (let a = 0; a < 360; a += 60) {
    drawPoly(buildRingSector(1, 0.64, 0.86, a, a + 60, 5), 0.15);
  }

  // 2b. Inner/Middle Violet Band (frac 0.18 to 0.65)
  brush.fill("#68298a", 155);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.75, 0.85);
  for (let a = 0; a < 360; a += 45) {
    drawPoly(buildRingSector(1, 0.17, 0.65, a, a + 45, 5), 0.15);
  }
  // Cool ultramarine-violet inner ring
  brush.fill("#461866", 122);
  brush.fillBleed(0.20, "in");
  for (let a = 0; a < 360; a += 60) {
    drawPoly(buildRingSector(1, 0.22, 0.48, a, a + 60, 5), 0.15);
  }

  // 2c. Nib Origin Core: Dark Espresso Umber
  brush.fill("#2e160e", 200);
  brush.fillBleed(0.22, "out");
  drawPoly(buildFullPlumePoly(1, 0.20, 8), 0.18);

  // --------------------------------------------------------------------------
  // PLUME 2: THIRD PEN (Cool Black-Sepia) -> Cerulean, Rose-Violet & Lemon-Saffron
  // --------------------------------------------------------------------------
  // 3a. Outer Lemon-Saffron Ring (frac 0.68 to 1.00)
  brush.fill("#ede034", 136);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.68, 0.78);
  for (let a = 0; a < 360; a += 45) {
    drawPoly(buildRingSector(2, 0.66, 1.00, a, a + 45, 5), 0.15);
  }

  // 3b. Middle Rose Madder & Violet Ring (frac 0.39 to 0.70)
  brush.fill("#c92c66", 142);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.74, 0.84);
  for (let a = 0; a < 360; a += 45) {
    drawPoly(buildRingSector(2, 0.38, 0.70, a, a + 45, 5), 0.15);
  }
  brush.fill("#742882", 105);
  brush.fillBleed(0.22, "in");
  for (let a = 0; a < 360; a += 60) {
    drawPoly(buildRingSector(2, 0.36, 0.54, a, a + 60, 5), 0.15);
  }

  // 3c. Inner Cerulean Ring (frac 0.15 to 0.42)
  brush.fill("#0d7bc2", 155);
  brush.fillBleed(0.24, "out");
  for (let a = 0; a < 360; a += 45) {
    drawPoly(buildRingSector(2, 0.14, 0.42, a, a + 45, 5), 0.15);
  }

  // 3d. Nib Origin Core: Deep Slate-Black
  brush.fill("#121824", 198);
  brush.fillBleed(0.22, "out");
  drawPoly(buildFullPlumePoly(2, 0.18, 8), 0.18);

  brush.noFill();
}

// Wet cauliflower blooms and backruns where the three expanding plumes collide
function drawMeetingWetBlooms() {
  // Collision zones between Plume 0 & 1, Plume 1 & 2, Plume 2 & 0, and triple junction
  let blooms = [
    { x: 590, y: 515, rx: 46, ry: 28, rot: -62, col: "#f2c829", rim: "#d45b3e", op: 95 },
    { x: 572, y: 465, rx: 36, ry: 22, rot: -55, col: "#f7ea52", rim: "#cf8d19", op: 88 },
    { x: 612, y: 558, rx: 40, ry: 32, rot: -35, col: "#b53678", rim: "#5b2075", op: 92 },
    { x: 632, y: 632, rx: 48, ry: 28, rot: 42,  col: "#f5ad24", rim: "#bd4a42", op: 95 },
    { x: 668, y: 668, rx: 38, ry: 22, rot: 48,  col: "#f7ca36", rim: "#d46f15", op: 85 },
    { x: 530, y: 595, rx: 44, ry: 26, rot: 18,  col: "#e34f7b", rim: "#0d74b8", op: 92 },
    { x: 472, y: 585, rx: 36, ry: 22, rot: 22,  col: "#f5ea47", rim: "#c93464", op: 88 },
    { x: 584, y: 584, rx: 32, ry: 30, rot: 10,  col: "#e8eff7", rim: "#8f3270", op: 110 } // Central pale water backrun
  ];

  for (let b of blooms) {
    let pts = [];
    for (let a = 0; a < 360; a += 10) {
      let n = 0.72 + 0.45 * noise(b.x * 0.03 + dCos(a) * 2.2, b.y * 0.03 + dSin(a) * 2.2);
      let lx = b.rx * n * dCos(a);
      let ly = b.ry * n * dSin(a);
      let wx = b.x + lx * dCos(b.rot) - ly * dSin(b.rot);
      let wy = b.y + lx * dSin(b.rot) + ly * dCos(b.rot);
      pts.push([wx, wy]);
    }

    // Watercolor cauliflower bloom with high border intensity (pigment pooling at edge)
    brush.noStroke();
    brush.fill(b.col, b.op);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.85, 0.95);
    drawPoly(pts, 0.22);
    brush.noFill();

    // Crisp dendritic capillary backrun rim
    brush.set("capillary", b.rim, 0.38);
    drawPoly(pts, 0.22);
  }
}

// Thousands of fine radial capillary fibers along every chromatographic ring transition
function drawCapillaryFeathering() {
  const ringConfigs = [
    // Plume 0 (Black: Cerulean -> Rose Madder -> Lemon)
    { idx: 0, frac: 1.00, col: "#d9c414", lenMin: 6,  lenMax: 22, step: 1.5, w: 0.34 },
    { idx: 0, frac: 0.85, col: "#f2e638", lenMin: 5,  lenMax: 16, step: 2.0, w: 0.30 },
    { idx: 0, frac: 0.71, col: "#d9366c", lenMin: 8,  lenMax: 26, step: 1.2, w: 0.38 },
    { idx: 0, frac: 0.56, col: "#b0194d", lenMin: 6,  lenMax: 18, step: 1.8, w: 0.32 },
    { idx: 0, frac: 0.44, col: "#0b7ec4", lenMin: 8,  lenMax: 24, step: 1.2, w: 0.38 },
    { idx: 0, frac: 0.28, col: "#065082", lenMin: 5,  lenMax: 16, step: 2.0, w: 0.34 },
    { idx: 0, frac: 0.17, col: "#181d2e", lenMin: 4,  lenMax: 13, step: 2.2, w: 0.36 },

    // Plume 1 (Brown: Violet -> Saffron)
    { idx: 1, frac: 1.00, col: "#d97a0d", lenMin: 7,  lenMax: 24, step: 1.5, w: 0.36 },
    { idx: 1, frac: 0.82, col: "#f5a51d", lenMin: 6,  lenMax: 18, step: 2.0, w: 0.32 },
    { idx: 1, frac: 0.63, col: "#6b288c", lenMin: 9,  lenMax: 28, step: 1.2, w: 0.40 },
    { idx: 1, frac: 0.45, col: "#481666", lenMin: 6,  lenMax: 20, step: 1.6, w: 0.35 },
    { idx: 1, frac: 0.28, col: "#36144f", lenMin: 5,  lenMax: 15, step: 2.0, w: 0.34 },
    { idx: 1, frac: 0.18, col: "#2b130c", lenMin: 4,  lenMax: 12, step: 2.2, w: 0.36 },

    // Plume 2 (Cool Black: Cerulean -> Rose/Violet -> Lemon)
    { idx: 2, frac: 1.00, col: "#dec618", lenMin: 6,  lenMax: 20, step: 1.6, w: 0.34 },
    { idx: 2, frac: 0.68, col: "#c72862", lenMin: 7,  lenMax: 24, step: 1.4, w: 0.36 },
    { idx: 2, frac: 0.50, col: "#6c247a", lenMin: 6,  lenMax: 18, step: 1.8, w: 0.34 },
    { idx: 2, frac: 0.40, col: "#0c78bd", lenMin: 7,  lenMax: 22, step: 1.4, w: 0.36 },
    { idx: 2, frac: 0.25, col: "#074d80", lenMin: 5,  lenMax: 15, step: 2.0, w: 0.32 },
    { idx: 2, frac: 0.16, col: "#121724", lenMin: 4,  lenMax: 11, step: 2.2, w: 0.36 }
  ];

  for (let rc of ringConfigs) {
    let p = PLUMES[rc.idx];
    brush.set("capillary", rc.col, rc.w);

    for (let a = 0; a < 360; a += rc.step) {
      let pt = getPlumePoint(rc.idx, rc.frac, a, 1.15);
      let dx = pt[0] - p.cx;
      let dy = pt[1] - p.cy;
      let d = Math.sqrt(dx * dx + dy * dy) || 1;
      let ux = dx / d;
      let uy = dy / d;

      // Tangential jitter for natural cellulose fiber orientation
      let jitterAng = random(-16, 16) * DEG2RAD;
      let fx = ux * Math.cos(jitterAng) - uy * Math.sin(jitterAng);
      let fy = ux * Math.sin(jitterAng) + uy * Math.cos(jitterAng);

      let lenIn = random(rc.lenMin * 0.4, rc.lenMax * 0.5);
      let lenOut = random(rc.lenMin, rc.lenMax) * (0.4 + 0.9 * noise(pt[0] * 0.04, pt[1] * 0.04));

      brush.line(
        pt[0] - fx * lenIn,
        pt[1] - fy * lenIn,
        pt[0] + fx * lenOut,
        pt[1] + fy * lenOut
      );
    }
  }

  // Fine colored-pencil cross-contour radial glazing inside the rings for hyperreal depth
  for (let idx = 0; idx < 3; idx++) {
    let ringTraces = (idx === 1)
      ? [{ f: 0.96, c: "#e07b10" }, { f: 0.62, c: "#5e227d" }, { f: 0.35, c: "#3c1257" }]
      : [{ f: 0.96, c: "#d9c216" }, { f: 0.70, c: "#bf2158" }, { f: 0.43, c: "#0866a3" }];

    for (let rt of ringTraces) {
      brush.set("cpencil", rt.c, 0.26);
      let tracePts = buildFullPlumePoly(idx, rt.f, 4);
      drawPoly(tracePts, 0.18);
    }
  }
}

