function createPenTransform(nibX, nibY, angleDeg) {
  let tx = dCos(angleDeg);
  let ty = dSin(angleDeg);
  // Choose perpendicular vector V so negative v is ALWAYS the upper (lit) side in screen space
  let nx = -ty;
  let ny = tx;
  if (ny < 0) {
    nx = -nx;
    ny = -ny;
  }
  return {
    nibX, nibY, angleDeg, tx, ty, nx, ny,
    pt(u, v) {
      return [nibX + u * tx + v * nx, nibY + u * ty + v * ny];
    }
  };
}

