function drawSingleHyperrealPen(cfg) {
  const pen = createPenTransform(cfg.nibX, cfg.nibY, cfg.angle);

  // Helper to build a quad/strip in (u, v) coordinates
  function uvPoly(u1, u2, v1, v2) {
    return [pen.pt(u1, v1), pen.pt(u2, v1), pen.pt(u2, v2), pen.pt(u1, v2)];
  }

  // --------------------------------------------------------------------------
  // A. CAST SHADOW ON DAMP PAPER & BENCH (Twin Fluorescent Tube Penumbra/Umbra)
  // --------------------------------------------------------------------------
  let profile = [
    [0, 2.2], [16, 3.0], [18, 4.8], [34, 6.2], [38, 8.8],
    [76, 14.5], [96, 16.2], [112, 18.8], [335, 19.2],
    [336, 22.2], [442, 22.2], [452, 18.5], [456, 11.0]
  ];

  let shadowOuter = [];
  let shadowInner = [];
  for (let i = 0; i < profile.length; i++) {
    let [u, r] = profile[i];
    // Shadow offset ramps from 0 right at the touching nib tip to full height along barrel
    let lift = constrain(u / 55, 0.05, 1.0);
    let ox = 4.5 * lift;
    let oy = 13.5 * lift;
    let pTop = pen.pt(u, -r * 0.7);
    shadowOuter.push([pTop[0] + ox, pTop[1] + oy - 2]);
    shadowInner.push([pTop[0] + ox * 0.7, pTop[1] + oy * 0.7]);
  }
  for (let i = profile.length - 1; i >= 0; i--) {
    let [u, r] = profile[i];
    let lift = constrain(u / 55, 0.05, 1.0);
    let ox = 4.5 * lift;
    let oy = 13.5 * lift;
    let pBot = pen.pt(u, r * 1.05);
    shadowOuter.push([pBot[0] + ox + 2, pBot[1] + oy + 5]);
    shadowInner.push([pBot[0] + ox * 0.85, pBot[1] + oy * 0.85 + 1]);
  }

  brush.noStroke();
  brush.fill("#23303d", 82);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.4, 0.25);
  drawPoly(shadowOuter, 0.08);

  brush.fill("#121a24", 125);
  brush.fillBleed(0.14, "out");
  drawPoly(shadowInner, 0.06);

  // Additional cast shadow for the protruding cap clip
  let cs = cfg.clipSide;
  let clipShadow = [
    pen.pt(344, cs * 21), pen.pt(352, cs * 33),
    pen.pt(436, cs * 34), pen.pt(442, cs * 21)
  ].map(p => [p[0] + 5, p[1] + 14]);
  brush.fill("#16202b", 105);
  brush.fillBleed(0.2, "out");
  drawPoly(clipShadow, 0.08);
  brush.noFill();

  // --------------------------------------------------------------------------
  // B. OPAQUE SILHOUETTE MASK (So underlying chromatography rings don't bleed through)
  // --------------------------------------------------------------------------
  let bodyHull = [];
  for (let i = 0; i < profile.length; i++) bodyHull.push(pen.pt(profile[i][0], -profile[i][1]));
  for (let i = profile.length - 1; i >= 0; i--) bodyHull.push(pen.pt(profile[i][0], profile[i][1]));

  brush.noStroke();
  brush.wash(cfg.barrelBase, 254);
  drawPoly(bodyHull, 0.04);
  brush.noWash();

  // --------------------------------------------------------------------------
  // C. ZONE 1: POROUS FELT NIB (u = 0 to 17)
  // --------------------------------------------------------------------------
  let nibPoly = [
    pen.pt(0, -1.5), pen.pt(3, -2.7), pen.pt(17, -3.1),
    pen.pt(17, 3.1), pen.pt(3, 2.7), pen.pt(0, 1.5)
  ];
  brush.wash(cfg.nibCol, 255);
  drawPoly(nibPoly, 0.15);
  brush.noWash();

  // Wet ink sheen along the top edge of the porous felt tip
  brush.set("rotring", "#07090d", 0.45);
  drawPoly(nibPoly, 0.15);
  brush.set("specular", "#b8cde0", 0.35);
  let nibHi1 = pen.pt(2.5, -1.4);
  let nibHi2 = pen.pt(15.5, -1.6);
  brush.line(nibHi1[0], nibHi1[1], nibHi2[0], nibHi2[1]);

  // --------------------------------------------------------------------------
  // D. ZONE 2: MACHINED STAINLESS STEEL COLLAR / FERRULE (u = 17 to 36)
  // --------------------------------------------------------------------------
  // Base steel grey
  brush.noStroke();
  brush.wash("#8a9ba8", 255);
  drawPoly(uvPoly(17, 25, -4.6, 4.6), 0.02);
  drawPoly(uvPoly(25, 36, -6.3, 6.3), 0.02);

  // High-contrast chrome reflection bands on the metal ferrule
  brush.wash("#eef6fc", 250);
  drawPoly(uvPoly(17, 25, -3.4, -1.1), 0.01);
  drawPoly(uvPoly(25, 36, -4.6, -1.6), 0.01);

  brush.wash("#242f38", 245);
  drawPoly(uvPoly(17, 25, -0.4, 2.1), 0.01);
  drawPoly(uvPoly(25, 36, -0.6, 3.0), 0.01);

  brush.wash("#9eb2c2", 235);
  drawPoly(uvPoly(25, 36, 3.2, 5.6), 0.01);
  brush.noWash();

  // Crisp machined step lines on metal collar
  brush.set("rotring", "#1b242c", 0.36);
  let f1a = pen.pt(17, -4.6), f1b = pen.pt(17, 4.6);
  let f2a = pen.pt(25, -6.3), f2b = pen.pt(25, 6.3);
  let f3a = pen.pt(36, -6.3), f3b = pen.pt(36, 6.3);
  brush.line(f1a[0], f1a[1], f1b[0], f1b[1]);
  brush.line(f2a[0], f2a[1], f2b[0], f2b[1]);
  brush.line(f3a[0], f3a[1], f3b[0], f3b[1]);

  // --------------------------------------------------------------------------
  // E. ZONE 3: STEPPED PLASTIC GRIP & CAP THREADS (u = 36 to 112)
  // --------------------------------------------------------------------------
  let gripHull = [
    pen.pt(36, -8.5), pen.pt(76, -14.5), pen.pt(112, -18.5),
    pen.pt(112, 18.5), pen.pt(76, 14.5), pen.pt(36, 8.5)
