  brush.wash(cfg.barrelDark, 235);
  drawPoly([
    pen.pt(36, 1.5), pen.pt(76, 2.8), pen.pt(112, 3.8),
    pen.pt(112, 13.5), pen.pt(76, 10.8), pen.pt(36, 6.2)
