    brush.line(g1[0], g1[1], g2[0], g2[1]);
  }

  // Three precision cap-retention thread rings (u = 80, 86, 92)
  for (let tu of [80, 86, 92]) {
    let tr = map(tu, 76, 112, 14.8, 18.2) + 1.1;
    let tDark1 = pen.pt(tu - 1.5, -tr), tDark2 = pen.pt(tu - 1.5, tr);
