  brush.noStroke();
  brush.wash("#c8d6e3", 252);
  drawPoly(uvPoly(112, 122, -19.0, 19.0), 0.02);
  brush.wash("#25303b", 240);
  drawPoly(uvPoly(112, 122, 1.5, 11.5), 0.02);
  brush.wash("#ffffff", 250);
  drawPoly(uvPoly(112, 122, -12.5, -5.5), 0.02);
  brush.noWash();

  // --------------------------------------------------------------------------
  // G. ZONE 5: MAIN PLASTIC BARREL (u = 122 to 336, radius = 19.2)
