  // 2. Upper mid-tone plastic sheen (-0.72R to -0.25R)
  brush.wash(cfg.barrelMid, 245);
  drawPoly(uvPoly(122, 336, -0.72 * R, -0.25 * R), 0.01);

  // 3. Central local color zone (-0.25R to +0.22R)
