  drawPoly(uvPoly(335, 444, -RC, RC), 0.02);

  brush.wash("#53677a", 230);
  drawPoly(uvPoly(335, 444, -RC, -0.72 * RC), 0.01);

  brush.wash(cfg.barrelMid, 240);
  drawPoly(uvPoly(335, 444, -0.72 * RC, -0.25 * RC), 0.01);

  brush.wash(cfg.barrelDark, 250);
  drawPoly(uvPoly(335, 444, 0.20 * RC, 0.74 * RC), 0.01);

  brush.wash(cfg.bounceCol, 200);
  drawPoly(uvPoly(335, 444, 0.74 * RC, RC), 0.01);

  // Stepped ventilated safety end-plug at rear of cap (u = 444 to 456)
  brush.wash(cfg.bandCol, 252);
  drawPoly([
    pen.pt(444, -18.5), pen.pt(454, -14.0),
    pen.pt(454, 14.0), pen.pt(444, 18.5)
  ], 0.08);
  brush.noWash();

  // Crisp step shadow at cap mouth (u = 335)
  brush.set("rotring", "#06080c", 0.55);
  let cm1 = pen.pt(335, -RC), cm2 = pen.pt(335, RC);
  brush.line(cm1[0], cm1[1], cm2[0], cm2[1]);
  brush.set("specular", "#dce8f5", 0.45);
  let cm3 = pen.pt(336.5, -RC * 0.75), cm4 = pen.pt(336.5, RC * 0.2);
  brush.line(cm3[0], cm3[1], cm4[0], cm4[1]);

  // Render the 3D Cap Clip
  drawCapClip(pen, cfg, RC);

  // --------------------------------------------------------------------------
  // J. HYPERREAL FLUORESCENT SPECULAR SHEEN ACROSS GRIP, BARREL & CAP
  // --------------------------------------------------------------------------
  // Soft cool-white specular halo
  brush.noStroke();
  brush.wash("#c8daeb", 165);
  drawPoly(uvPoly(38, 111, -0.60 * 14, -0.34 * 14), 0.02);
  drawPoly(uvPoly(123, 334, -0.62 * R, -0.34 * R), 0.01);
  drawPoly(uvPoly(337, 442, -0.62 * RC, -0.34 * RC), 0.01);

  // Twin razor-sharp white fluorescent tube bands (separated by fixture gap)
  brush.wash("#ffffff", 248);
  // Tube 1 reflection
  drawPoly(uvPoly(123, 334, -0.58 * R, -0.48 * R), 0.01);
  drawPoly(uvPoly(337, 442, -0.58 * RC, -0.48 * RC), 0.01);
  // Tube 2 reflection
  drawPoly(uvPoly(123, 334, -0.43 * R, -0.36 * R), 0.01);
  drawPoly(uvPoly(337, 442, -0.43 * RC, -0.36 * RC), 0.01);
  brush.noWash();

  // Crisp linear specular highlights with custom "specular" brush
  brush.set("specular", "#ffffff", 0.85);
  let spG1 = pen.pt(39, -5.2), spG2 = pen.pt(74, -7.8);
  brush.line(spG1[0], spG1[1], spG2[0], spG2[1]);

  let spB1 = pen.pt(123, -0.53 * R), spB2 = pen.pt(334, -0.53 * R);
  brush.line(spB1[0], spB1[1], spB2[0], spB2[1]);

  let spB3 = pen.pt(123, -0.39 * R), spB4 = pen.pt(334, -0.39 * R);
  brush.line(spB3[0], spB3[1], spB4[0], spB4[1]);

  let spC1 = pen.pt(338, -0.53 * RC), spC2 = pen.pt(441, -0.53 * RC);
  brush.line(spC1[0], spC1[1], spC2[0], spC2[1]);

  // Precision graphite & technical pen contour outlines around the entire pen
  brush.set("rotring", "#0c1117", 0.36);
  drawPoly(bodyHull, 0.03);
}

// Render the 3D molded/stamped cap clip with air gap, bevels, and cast shadow
function drawCapClip(pen, cfg, RC) {
  let cs = cfg.clipSide; // -1 = upper three-quarter edge, +1 = lower three-quarter edge

  if (cs < 0) {
    // Upper-edge clip projecting outward from v = -RC to v = -34.5
    // Dark air-gap slot between clip arm and cap surface
    brush.noStroke();
    brush.wash("#141c24", 245);
    drawPoly([
      pen.pt(352, -RC - 0.5), pen.pt(426, -RC - 0.5),
      pen.pt(426, -RC - 4.8), pen.pt(352, -RC - 3.8)
    ], 0.02);

    // Sculpted chrome/plastic clip arm + ball terminal + rear mounting collar
    let clipBody = [
      pen.pt(343, -RC + 1.5), // Rolled ball terminal touching cap
      pen.pt(345, -RC - 5.5),
      pen.pt(354, -RC - 9.8), // Clip outer bridge
      pen.pt(436, -RC - 11.2),
      pen.pt(442, -RC - 7.5),
      pen.pt(442, -RC + 4.0), // Rear mounting band on cap
      pen.pt(428, -RC + 4.0),
      pen.pt(426, -RC - 4.8), // Inner ceiling of clip bridge
      pen.pt(355, -RC - 4.2),
      pen.pt(349, -RC + 1.5)
