function drawBarrelText(pen, textStr, uStart, vTop, charW, charH, tracking, col, weight) {
  brush.set("microprint", col, weight);
  let u = uStart;
  for (let i = 0; i < textStr.length; i++) {
    let ch = textStr[i];
    let segs = FONT_STROKES[ch];
    if (segs) {
      for (let s of segs) {
        let p1 = pen.pt(u + s[0] * charW, vTop + s[1] * charH);
        let p2 = pen.pt(u + s[2] * charW, vTop + s[3] * charH);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
    u += charW + tracking;
  }
}

