// ============================================================================
// CLOTH GEOMETRY PRIMITIVES (Ridges, Troughs, Lapels, D-Cone Pinches)
// ============================================================================
function sampleCatmullRom(ctrlPts, numSamples) {
  let out = [];
  let n = ctrlPts.length;
  for (let i = 0; i < numSamples; i++) {
    let tGlobal = (i / (numSamples - 1)) * (n - 1);
    let idx = Math.min(Math.floor(tGlobal), n - 2);
    let t = tGlobal - idx;

    let p0 = ctrlPts[Math.max(0, idx - 1)];
    let p1 = ctrlPts[idx];
    let p2 = ctrlPts[idx + 1];
    let p3 = ctrlPts[Math.min(n - 1, idx + 2)];

    let t2 = t * t;
    let t3 = t2 * t;

    let x =
      0.5 *
      (2 * p1[0] +
        (-p0[0] + p2[0]) * t +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
    let y =
      0.5 *
      (2 * p1[1] +
        (-p0[1] + p2[1]) * t +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);

    out.push({ x, y, u: i / (numSamples - 1) });
  }

  let minX = Infinity,
    maxX = -Infinity,
    minY = Infinity,
    maxY = -Infinity;
  for (let i = 0; i < out.length; i++) {
    let p = out[i];
    let pPrev = out[Math.max(0, i - 1)];
    let pNext = out[Math.min(out.length - 1, i + 1)];
    let dx = pNext.x - pPrev.x;
    let dy = pNext.y - pPrev.y;
    let len = Math.hypot(dx, dy) || 1;
    p.nx = -dy / len;
    p.ny = dx / len;
    p.tx = dx / len;
    p.ty = dy / len;
    if (p.x < minX) minX = p.x;
    if (p.x > maxX) maxX = p.x;
    if (p.y < minY) minY = p.y;
    if (p.y > maxY) maxY = p.y;
  }
  return { pts: out, minX, maxX, minY, maxY };
}

function closestPointOnSampledCurve(curve, x, y, maxDist) {
  if (
    x < curve.minX - maxDist ||
    x > curve.maxX + maxDist ||
    y < curve.minY - maxDist ||
    y > curve.maxY + maxDist
  ) {
    return null;
  }
  let pts = curve.pts;
  let bestD2 = Infinity;
  let bestIdx = 0;
  for (let i = 0; i < pts.length; i++) {
    let dx = x - pts[i].x;
    let dy = y - pts[i].y;
    let d2 = dx * dx + dy * dy;
    if (d2 < bestD2) {
      bestD2 = d2;
      bestIdx = i;
    }
  }
  if (bestD2 > maxDist * maxDist) return null;

  // Refine projection onto adjacent segment
  let i0 = Math.max(0, bestIdx - 1);
  let i1 = Math.min(pts.length - 1, bestIdx + 1);
  let pA = pts[i0];
  let pB = pts[i1];
  let vx = pB.x - pA.x;
  let vy = pB.y - pA.y;
  let vLen2 = vx * vx + vy * vy || 1;
  let s = constrain(((x - pA.x) * vx + (y - pA.y) * vy) / vLen2, 0, 1);
  let cx = pA.x + s * vx;
  let cy = pA.y + s * vy;
  let nx = pA.nx + s * (pB.nx - pA.nx);
  let ny = pA.ny + s * (pB.ny - pA.ny);
  let u = pA.u + s * (pB.u - pA.u);
  let signedDist = (x - cx) * nx + (y - cy) * ny;
  return { d: signedDist, u: u, cx, cy, nx, ny };
}

