  { ang: -8, curv: 0.12, amp: 4.1, w: 0.048 },
  { ang: 18, curv: 0.20, amp: -5.2, w: 0.052 },
  { ang: 44, curv: -0.15, amp: 4.5, w: 0.056 },
  { ang: 72, curv: 0.10, amp: -4.9, w: 0.048 },
  { ang: 98, curv: -0.14, amp: 3.9, w: 0.052 },
  { ang: 126, curv: 0.16, amp: -5.5, w: 0.054 },
  { ang: 152, curv: -0.12, amp: 4.4, w: 0.050 },
  { ang: 176, curv: 0.14, amp: -4.6, w: 0.048 }
];

const RIGHT_PILLOW_CREASES = [
  { ang: -155, curv: 0.15, amp: -3.8, w: 0.060 },
  { ang: -110, curv: -0.12, amp: 3.5, w: 0.055 },
  { ang: -65, curv: 0.18, amp: -4.2, w: 0.052 },
  { ang: -20, curv: -0.14, amp: 3.6, w: 0.058 },
  { ang: 25, curv: 0.16, amp: -4.5, w: 0.052 },
  { ang: 75, curv: -0.15, amp: 3.8, w: 0.056 },
  { ang: 125, curv: 0.12, amp: -4.0, w: 0.054 },
  { ang: 168, curv: -0.16, amp: 3.4, w: 0.052 }
];

function evalPillow(
  x,
  y,
  cx,
  cy,
  halfW,
  halfH,
  rotDeg,
  puffHeight,
  hollowU,
  hollowV,
  hollowDepth,
  hollowRx,
  hollowRy,
  creases
) {
  let dx = x - cx;
  let dy = y - cy;
  let rad = (rotDeg * Math.PI) / 180;
  let cosA = Math.cos(rad);
  let sinA = Math.sin(rad);

  let u = (dx * cosA + dy * sinA) / halfW;
  let v = (-dx * sinA + dy * cosA) / halfH;

  if (Math.abs(u) > 1.35 || Math.abs(v) > 1.35) return 0;

  // Flared pillowcase corners ("ears"): width increases near v = +-1 and vice versa
  let uEar = u / (1 + 0.15 * v * v);
  let vEar = v / (1 + 0.17 * u * u);

  let q = Math.pow(Math.abs(uEar), 2.5) + Math.pow(Math.abs(vEar), 2.3);
  if (q >= 1.25) return 0;

  // Smooth pillow cushion dome with crisp seam edge
  let normQ = Math.min(1, q / 1.05);
  let seamStep = Math.pow(1 - normQ * normQ, 1.35);
  let z = puffHeight * seamStep;

  // Subtle corner ear pinch ridges
  let earFactor = Math.exp(-Math.pow((q - 0.78) / 0.22, 2)) * (u * u * v * v);
  z += puffHeight * 0.22 * earFactor;

  // Asymmetric Low-Pressure Pillow Hollow
  let hu = (u - hollowU) / hollowRx;
  let hv = (v - hollowV) / hollowRy;
  // Slightly steeper on the upper-left shaded wall, gentler on lower-right
  let asym = 1.0 - 0.16 * Math.tanh(hu * 0.9 + hv * 0.9);
  let hd = Math.hypot(hu, hv) * asym;

  // Deep central nest of rings + displaced down bolster rim
  let hollowCore =
    -hollowDepth * Math.exp(-Math.pow(hd / 0.72, 2.15)) -
    hollowDepth * 0.36 * Math.exp(-Math.pow(hd / 0.32, 2.0));
  let rimBolster =
    hollowDepth * 0.22 * Math.exp(-Math.pow((hd - 0.95) / 0.32, 2));

  z += (hollowCore + rimBolster) * Math.pow(seamStep, 0.35);

  // Radial d-cone compression creases radiating from the hollow rim to pillow edges
  let rawD = Math.hypot(u - hollowU, v - hollowV);
  if (rawD > 0.08 && q < 1.08) {
    let theta = Math.atan2(v - hollowV, u - hollowU);
    let radialEnv =
      Math.exp(-Math.pow((rawD - 0.52) / 0.38, 2)) *
      (1 - Math.exp(-Math.pow(rawD / 0.16, 2)));

    for (let i = 0; i < creases.length; i++) {
      let c = creases[i];
      let cRad = (c.ang * Math.PI) / 180 + c.curv * (rawD - 0.25);
      let dAng = Math.atan2(Math.sin(theta - cRad), Math.cos(theta - cRad));
      let w = c.w * (0.75 + 0.5 * rawD);
      let s = dAng / w;
      if (Math.abs(s) < 3.2) {
        // Sharp crease profile: V-valley paired with asymmetric side ridge
        let profile =
          (1 - Math.pow(Math.abs(s), 1.35) * 0.55) * Math.exp(-0.55 * s * s) -
          0.42 * s * Math.exp(-0.45 * s * s);
        z += c.amp * radialEnv * profile;
      }
    }
  }

  return z;
}

// ============================================================================
// BUILD FULL 3D BED HEIGHTFIELD Z(x, y), GRADIENT, AND SHADING METRIC
// ============================================================================
function buildBedHeightfield() {
  heightGrid = new Array(GRID_W + 1);
  gradMagGrid = new Array(GRID_W + 1);
  shadeGrid = new Array(GRID_W + 1);
  lightGrid = new Array(GRID_W + 1);

  for (let ix = 0; ix <= GRID_W; ix++) {
    heightGrid[ix] = new Float32Array(GRID_H + 1);
    gradMagGrid[ix] = new Float32Array(GRID_H + 1);
    shadeGrid[ix] = new Float32Array(GRID_H + 1);
    lightGrid[ix] = new Float32Array(GRID_H + 1);
  }

  for (let ix = 0; ix <= GRID_W; ix++) {
    let x = MARGIN + (ix / GRID_W) * CHART_W;
    for (let iy = 0; iy <= GRID_H; iy++) {
      let y = MARGIN + (iy / GRID_H) * CHART_H;
      heightGrid[ix][iy] = evaluateBedElevation(x, y);
    }
  }

  // Compute surface normals, morning light, curvature, and contour density field
  let cellW = CHART_W / GRID_W;
  let cellH = CHART_H / GRID_H;

  // Low-angle morning sunlight from the upper-right-southeast
  let lx = 0.68,
    ly = -0.42,
    lz = 0.60;

  for (let ix = 0; ix <= GRID_W; ix++) {
    let iPrev = Math.max(0, ix - 1);
    let iNext = Math.min(GRID_W, ix + 1);
    let dx = (iNext - iPrev) * cellW;

    for (let iy = 0; iy <= GRID_H; iy++) {
      let jPrev = Math.max(0, iy - 1);
      let jNext = Math.min(GRID_H, iy + 1);
      let dy = (jNext - jPrev) * cellH;

      let dzdx = (heightGrid[iNext][iy] - heightGrid[iPrev][iy]) / dx;
      let dzdy = (heightGrid[ix][jNext] - heightGrid[ix][jPrev]) / dy;
      let slope = Math.hypot(dzdx, dzdy);
      gradMagGrid[ix][iy] = slope;

      // Laplacian curvature (negative inside concave creases & troughs)
      let zC = heightGrid[ix][iy];
      let lap =
        heightGrid[iNext][iy] +
        heightGrid[iPrev][iy] +
        heightGrid[ix][jNext] +
        heightGrid[ix][jPrev] -
        4 * zC;

      // Surface normal N = (-dzdx * scale, -dzdy * scale, 1)
      let nScale = 2.8;
      let nx = -dzdx * nScale;
      let ny = -dzdy * nScale;
      let nz = 1.0;
      let nLen = Math.hypot(nx, ny, nz);
      nx /= nLen;
      ny /= nLen;
      nz /= nLen;

      let dotL = nx * lx + ny * ly + nz * lz;
      lightGrid[ix][iy] = dotL;

      // Shadow / Crease Density Metric D(x,y) in [0, 1]
      // High when facing away from morning light, or in concave creases, or deep in hollows
      let shadowTerm = constrain((0.68 - dotL) * 1.15, 0, 1);
      let creaseTerm = constrain(-lap * 1.85, 0, 1);
      let slopeTerm = constrain(slope * 1.6, 0, 1);
      let hollowTerm = zC < -4 ? constrain((-zC - 4) / 28, 0, 0.45) : 0;

      let dVal =
        0.48 * shadowTerm +
        0.30 * creaseTerm +
        0.22 * slopeTerm +
        hollowTerm;
      shadeGrid[ix][iy] = constrain(dVal, 0, 1);
    }
  }
}

function evaluateBedElevation(x, y) {
  let z = 0;

  // 1. Mattress base envelope (rounded perimeter drop-off at bed edges)
  let bx = (x - 600) / 515;
  let by = (y - 605) / 515;
  let bedEdge = Math.pow(Math.abs(bx), 12) + Math.pow(Math.abs(by), 12);
  z -= 16.0 * Math.min(1.4, bedEdge);

  // Headboard channel at very top of bed
  if (y < 145) {
    z -= 9.5 * Math.exp(-Math.pow((y - 72) / 34, 2));
  }

  // 2. Left Pillow (Sleeper's pillow with deep nest-of-rings head hollow)
  z += evalPillow(
    x,
    y,
    358,
    276,
    210,
    134,
    -5.5,
    25.5,
    0.04,
    0.06,
    39.5,
    0.46,
    0.50,
    LEFT_PILLOW_CREASES
  );

  // 3. Right Pillow (Tilted, puffed high-pressure crown + secondary shoulder hollow)
  z += evalPillow(
    x,
    y,
    826,
    264,
    204,
    130,
    9.5,
    27.0,
    -0.36,
    0.20,
    18.5,
    0.38,
    0.42,
    RIGHT_PILLOW_CREASES
  );
  // Extra high-pressure billow on right pillow crown
  let rpx = (x - 878) / 125;
  let rpy = (y - 236) / 88;
  z += 9.5 * Math.exp(-(rpx * rpx + rpy * rpy));

  // 4. Sleeper's Torso / Hip Impression on the flat exposed bottom sheet
  let sx = (x - 388) * Math.cos(0.2) + (y - 548) * Math.sin(0.2);
  let sy = -(x - 388) * Math.sin(0.2) + (y - 548) * Math.cos(0.2);
  let sDist2 = Math.pow(sx / 175, 2) + Math.pow(sy / 115, 2);
  z -= 9.8 * Math.exp(-Math.pow(sDist2, 1.15));

  // Subtle broad flat-sheet gentle gradient so wide contours drift gracefully
  z += 2.4 * Math.sin((x - 150) * 0.0045) * Math.cos((y - 400) * 0.005);

  // 5. Evaluate Spline Folds (Turn-back steps, lapel, and major duvet ridges/canyons)
  for (let i = 0; i < foldSplines.length; i++) {
    let f = foldSplines[i];
    let hit = closestPointOnSampledCurve(f.curve, x, y, f.maxDist);
    if (!hit) continue;

    let d = hit.d;
    let u = hit.u;
    let endTaper = Math.sin(Math.pow(constrain(u, 0, 1), 0.7) * Math.PI);
    // Keep step folds full strength all the way to the mattress edges
    if (f.type === "step") endTaper = 1.0;
    else endTaper = 0.25 + 0.75 * endTaper;

    if (f.type === "step") {
      // Sigmoid cliff + under-tuck crease + crest lapel roll
      let step = 0.5 * (1 + Math.tanh(d / f.steepWidth));
      let tuck =
        f.tuckDepth * Math.exp(-Math.pow((d + f.steepWidth * 0.7) / f.tuckWidth, 2));
      let crest =
        f.crestBump * Math.exp(-Math.pow((d - f.steepWidth * 1.3) / f.crestWidth, 2));
      // Decay step gently far into the foot of the bed so duvet sculptures dominate
      let farDecay = d > 0 ? Math.exp(-Math.pow(d / 520, 2)) : 1.0;
      z += (f.stepHeight * step * farDecay + tuck + crest) * endTaper;
    } else if (f.type === "ridge") {
      let w = d < 0 ? f.wLeft : f.wRight;
      let normD = Math.abs(d) / w;
      if (normD < 3.2) {
        let profile = Math.exp(-Math.pow(normD, f.sharp));
        let tuck =
          f.tuck *
          Math.exp(-Math.pow((d + f.wLeft * 0.85) / (f.wLeft * 0.55), 2));
        z += (f.amp * profile + tuck) * endTaper;
      }
    }
  }

  // 6. High-Pressure Billowing Duvet Dome on Lower Right & Foot Tangle Hollow on Lower Left
  let dxDome = (x - 835) / 185;
  let dyDome = (y - 835) / 155;
  z += 14.5 * Math.exp(-(dxDome * dxDome + dyDome * dyDome));

  // Deep foot-tangle low-pressure vortex at (328, 982)
  let vx = (x - 328) / 78;
  let vy = (y - 982) / 68;
  let vd2 = vx * vx + vy * vy;
  z -= 17.5 * Math.exp(-Math.pow(vd2, 1.1));

  // 7. D-Cone Pinch Buckles
  for (let i = 0; i < pinchCones.length; i++) {
    let c = pinchCones[i];
    let dx = x - c.x;
    let dy = y - c.y;
    let r = Math.hypot(dx, dy);
    if (r < 4 || r > c.len * 1.4) continue;
    let ang = Math.atan2(dy, dx);
    let cRad = (c.angle * Math.PI) / 180;
    let dAng = Math.atan2(Math.sin(ang - cRad), Math.cos(ang - cRad));
    let wAng = c.spread * (0.6 + (0.6 * r) / c.len);
    let s = dAng / wAng;
    if (Math.abs(s) < 2.8) {
      let rEnv =
        (r / (r + 18)) * Math.exp(-Math.pow(r / (c.len * 0.82), 2));
      let p = (1 - 0.6 * Math.abs(s)) * Math.exp(-0.6 * s * s);
      z += c.amp * rEnv * p;
    }
  }

  // 8. Fine organic linen weave micro-undulation (very low amplitude for authentic cloth contour wobble)
  let n1 = noise(x * 0.009, y * 0.009) - 0.5;
  let n2 = noise(x * 0.022 + 100, y * 0.022 + 100) - 0.5;
  z += n1 * 1.6 + n2 * 0.55;

  return z;
}

// ============================================================================
// MARCHING SQUARES + EXACT TOPOLOGICAL CHAINING + SMOOTHING
// ============================================================================
function extractContoursAtLevel(zLevel) {
  let H_STRIDE = GRID_W + 1;
  let V_OFFSET = (GRID_H + 1) * H_STRIDE;

  let segments = [];
  let edgeMap = new Map();

  function addEdgeRef(edgeId, segIdx) {
    let list = edgeMap.get(edgeId);
    if (!list) {
      edgeMap.set(edgeId, [segIdx]);
    } else {
      list.push(segIdx);
    }
  }

  let cellW = CHART_W / GRID_W;
  let cellH = CHART_H / GRID_H;

  for (let ix = 0; ix < GRID_W; ix++) {
    let x0 = MARGIN + ix * cellW;
    let x1 = x0 + cellW;

    for (let iy = 0; iy < GRID_H; iy++) {
      let z00 = heightGrid[ix][iy] - zLevel;
      let z10 = heightGrid[ix + 1][iy] - zLevel;
      let z11 = heightGrid[ix + 1][iy + 1] - zLevel;
      let z01 = heightGrid[ix][iy + 1] - zLevel;

      let mask = 0;
      if (z00 >= 0) mask |= 1;
      if (z10 >= 0) mask |= 2;
      if (z11 >= 0) mask |= 4;
      if (z01 >= 0) mask |= 8;
      if (mask === 0 || mask === 15) continue;

      let y0 = MARGIN + iy * cellH;
      let y1 = y0 + cellH;

      // Edge 0: top, Edge 1: right, Edge 2: bottom, Edge 3: left
      let ePts = [null, null, null, null];
      let eIds = [
        iy * H_STRIDE + ix,
        V_OFFSET + iy * H_STRIDE + (ix + 1),
        (iy + 1) * H_STRIDE + ix,
        V_OFFSET + iy * H_STRIDE + ix
      ];

      if ((mask & 1) !== ((mask >> 1) & 1)) {
        let t = z00 / (z00 - z10 || 1e-9);
        ePts[0] = [x0 + constrain(t, 0, 1) * cellW, y0];
      }
      if (((mask >> 1) & 1) !== ((mask >> 2) & 1)) {
        let t = z10 / (z10 - z11 || 1e-9);
        ePts[1] = [x1, y0 + constrain(t, 0, 1) * cellH];
      }
      if (((mask >> 3) & 1) !== ((mask >> 2) & 1)) {
        let t = z01 / (z01 - z11 || 1e-9);
        ePts[2] = [x0 + constrain(t, 0, 1) * cellW, y1];
      }
      if ((mask & 1) !== ((mask >> 3) & 1)) {
        let t = z00 / (z00 - z01 || 1e-9);
        ePts[3] = [x0, y0 + constrain(t, 0, 1) * cellH];
      }

      let pairs = [];
      switch (mask) {
        case 1:
        case 14:
          pairs.push([3, 0]);
          break;
        case 2:
        case 13:
          pairs.push([0, 1]);
          break;
        case 4:
        case 11:
          pairs.push([1, 2]);
          break;
        case 8:
        case 7:
          pairs.push([2, 3]);
          break;
        case 3:
        case 12:
          pairs.push([3, 1]);
          break;
        case 6:
        case 9:
          pairs.push([0, 2]);
          break;
        case 5: {
          let zCenter = 0.25 * (z00 + z10 + z11 + z01);
          if (zCenter >= 0) {
            pairs.push([3, 2], [0, 1]);
          } else {
            pairs.push([3, 0], [1, 2]);
          }
          break;
        }
        case 10: {
          let zCenter = 0.25 * (z00 + z10 + z11 + z01);
          if (zCenter >= 0) {
            pairs.push([3, 0], [1, 2]);
          } else {
            pairs.push([3, 2], [0, 1]);
          }
          break;
        }
      }

      for (let p of pairs) {
        let eA = eIds[p[0]];
        let eB = eIds[p[1]];
        let ptA = ePts[p[0]];
        let ptB = ePts[p[1]];
        let segIdx = segments.length;
        segments.push({ eA, eB, ptA, ptB, used: false });
        addEdgeRef(eA, segIdx);
        addEdgeRef(eB, segIdx);
      }
    }
  }

  // Chain segments into continuous polylines
  let polylines = [];
  for (let i = 0; i < segments.length; i++) {
    let seg = segments[i];
    if (seg.used) continue;
    seg.used = true;

    let pts = [seg.ptA, seg.ptB];
    let currEdge = seg.eB;

    // Extend forward
    while (true) {
      let neighbors = edgeMap.get(currEdge);
      if (!neighbors) break;
      let nextIdx = -1;
      for (let nIdx of neighbors) {
        if (!segments[nIdx].used) {
          nextIdx = nIdx;
          break;
        }
      }
      if (nextIdx === -1) break;
      let nextSeg = segments[nextIdx];
      nextSeg.used = true;
      if (nextSeg.eA === currEdge) {
        pts.push(nextSeg.ptB);
        currEdge = nextSeg.eB;
      } else {
        pts.push(nextSeg.ptA);
        currEdge = nextSeg.eA;
      }
    }

    // Extend backward
    currEdge = seg.eA;
    let backPts = [];
    while (true) {
      let neighbors = edgeMap.get(currEdge);
      if (!neighbors) break;
      let nextIdx = -1;
      for (let nIdx of neighbors) {
        if (!segments[nIdx].used) {
          nextIdx = nIdx;
          break;
        }
      }
      if (nextIdx === -1) break;
      let nextSeg = segments[nextIdx];
      nextSeg.used = true;
      if (nextSeg.eA === currEdge) {
        backPts.push(nextSeg.ptB);
        currEdge = nextSeg.eB;
      } else {
        backPts.push(nextSeg.ptA);
        currEdge = nextSeg.eA;
      }
    }

    if (backPts.length > 0) {
      backPts.reverse();
      pts = backPts.concat(pts);
    }

    if (pts.length >= 4) {
      polylines.push(pts);
    }
  }

  return polylines;
}

function smoothAndSubsamplePolyline(pts, stepDist) {
  let n = pts.length;
  if (n < 4) return pts;

  let isClosed =
    Math.hypot(pts[0][0] - pts[n - 1][0], pts[0][1] - pts[n - 1][1]) < 4.5;

  // 2 passes of Laplacian smoothing
  let curr = pts;
  for (let pass = 0; pass < 2; pass++) {
    let next = new Array(curr.length);
    for (let i = 0; i < curr.length; i++) {
      if (!isClosed && (i === 0 || i === curr.length - 1)) {
        next[i] = [curr[i][0], curr[i][1]];
      } else {
        let iPrev = i === 0 ? curr.length - 2 : i - 1;
        let iNext = i === curr.length - 1 ? 1 : i + 1;
        next[i] = [
          0.25 * curr[iPrev][0] + 0.5 * curr[i][0] + 0.25 * curr[iNext][0],
          0.25 * curr[iPrev][1] + 0.5 * curr[i][1] + 0.25 * curr[iNext][1]
        ];
      }
    }
    curr = next;
  }

  // Subsample by arc length
  let out = [curr[0]];
  let acc = 0;
  for (let i = 1; i < curr.length; i++) {
    let d = Math.hypot(
      curr[i][0] - curr[i - 1][0],
      curr[i][1] - curr[i - 1][1]
    );
    acc += d;
    if (acc >= stepDist || i === curr.length - 1) {
      out.push(curr[i]);
      acc = 0;
    }
  }
  if (isClosed && out.length >= 4) {
    out[out.length - 1] = [out[0][0], out[0][1]];
  }
  return out;
}

function sampleGridBilinear(grid, x, y) {
  let gx = constrain(((x - MARGIN) / CHART_W) * GRID_W, 0, GRID_W - 1.001);
  let gy = constrain(((y - MARGIN) / CHART_H) * GRID_H, 0, GRID_H - 1.001);
  let ix = Math.floor(gx);
  let iy = Math.floor(gy);
  let fx = gx - ix;
  let fy = gy - iy;

  let v00 = grid[ix][iy];
  let v10 = grid[ix + 1][iy];
  let v01 = grid[ix][iy + 1];
  let v11 = grid[ix + 1][iy + 1];

  return (
    v00 * (1 - fx) * (1 - fy) +
    v10 * fx * (1 - fy) +
    v01 * (1 - fx) * fy +
    v11 * fx * fy
  );
}

// ============================================================================
// RENDER ALL CONTOURS (Shading emerges strictly from contour line density)
// ============================================================================
let indexLabelCandidates = [];

function renderAllContours() {
  const dz = 0.65;
  const minIdx = Math.floor(-44 / dz);
  const maxIdx = Math.ceil(42 / dz);

  // Warm palette of sepia, umber, walnut, and warm taupe tones on pale grey-blue paper
  const warmDarkColors = [
    "#3a2921", // Deep espresso umber (tightest crease cores & deep hollow rings)
    "#4e382d", // Dark burnt umber
    "#63493b", // Warm walnut sepia
    "#785b4a", // Mid warm sepia
    "#8e705e", // Warm ochre-taupe
    "#a28573"  // Soft warm linen-taupe
  ];

  for (let k = minIdx; k <= maxIdx; k++) {
    let z = k * dz;
    let absK = Math.abs(k);

    // Determine hierarchical isobar tier:
    // Tier 0: Index contours (every 8*dz = 5.2 units) -> always drawn
    // Tier 1: Standard contours (odd multiples of 4*dz = 2.6) -> almost everywhere
    // Tier 2: Intermediate contours (odd multiples of 2*dz = 1.3) -> slopes & moderate shade
    // Tier 3: Fine crease/shadow contours (odd multiples of 1*dz = 0.65) -> deep folds & hollows
    let tier = 3;
    if (absK % 8 === 0) tier = 0;
    else if (absK % 4 === 0) tier = 1;
    else if (absK % 2 === 0) tier = 2;

    let shadeThreshold = 0.0;
    if (tier === 0) shadeThreshold = -1.0; // Always drawn across flat sheet & creases
    else if (tier === 1) shadeThreshold = 0.11;
    else if (tier === 2) shadeThreshold = 0.27;
    else shadeThreshold = 0.43;

    // Inside the deep pillow hollows and foot-tangle low, lower threshold so tight rings stay complete
    if (z < -6) {
      shadeThreshold -= 0.22;
    }

    let rawPolylines = extractContoursAtLevel(z);

    for (let poly of rawPolylines) {
      let smoothed = smoothAndSubsamplePolyline(poly, 6.5);
      if (smoothed.length < 3) continue;

      // Save long index contours for millibar label placement
      if (tier === 0 && smoothed.length > 26 && indexLabelCandidates.length < 28) {
        indexLabelCandidates.push({
          pts: smoothed,
          mb: Math.round(1008 + z * 0.45)
        });
      }

      // Compute smoothed shading density metric along the contour
      let dVals = new Float32Array(smoothed.length);
      let lVals = new Float32Array(smoothed.length);
      for (let i = 0; i < smoothed.length; i++) {
        dVals[i] = sampleGridBilinear(shadeGrid, smoothed[i][0], smoothed[i][1]);
        lVals[i] = sampleGridBilinear(lightGrid, smoothed[i][0], smoothed[i][1]);
      }

      // Smooth dVals along curve to avoid short fragments
      for (let pass = 0; pass < 2; pass++) {
        for (let i = 1; i < smoothed.length - 1; i++) {
          dVals[i] = 0.25 * dVals[i - 1] + 0.5 * dVals[i] + 0.25 * dVals[i + 1];
        }
      }

      // 1. Draw Warm Ivory / Cream Sunlit Contours on high morning-lit billows & crests
      if (tier <= 2 && z > -4) {
        extractAndDrawSegments(
          smoothed,
          (i) => lVals[i] > 0.72 && dVals[i] < 0.34,
          4,
          "iso_ivory",
          z > 14 ? "#fbf5e9" : "#f2e8d7",
          tier === 0 ? 0.95 : 0.78
        );
      }

      // 2. Draw Warm Sepia / Umber Contours (filtered by tier threshold for density shading)
      if (tier === 0) {
        // Index contours: split gently into darker shadow segments and softer sunlit segments
        extractAndDrawSegments(
          smoothed,
          (i) => dVals[i] >= 0.38,
          3,
          "iso_primary",
          warmDarkColors[1],
          0.95
        );
        extractAndDrawSegments(
          smoothed,
          (i) => dVals[i] < 0.42,
          3,
          "iso_primary",
          warmDarkColors[3],
          0.82
        );
      } else {
        let bName = tier === 1 ? "iso_secondary" : "iso_fine";
        let wMult = tier === 1 ? 0.88 : tier === 2 ? 0.82 : 0.75;

        extractAndDrawByShade(
          smoothed,
          dVals,
          shadeThreshold,
          4,
          bName,
          warmDarkColors,
          wMult
        );
      }
    }
  }

  // Extra half-interval micro-rings inside the deepest pillow hollow & sharp crease cores
  for (let z = -39.325; z <= -10.0; z += 0.65) {
    let rawPolylines = extractContoursAtLevel(z);
    for (let poly of rawPolylines) {
      let smoothed = smoothAndSubsamplePolyline(poly, 5.5);
      if (smoothed.length < 4) continue;
      brush.set("iso_fine", "#3a2921", 0.72);
      drawSmoothSpline(smoothed);
    }
  }
}

function extractAndDrawSegments(pts, predicate, minLen, brushName, col, weight) {
  let run = [];
  for (let i = 0; i < pts.length; i++) {
    if (predicate(i)) {
      run.push(pts[i]);
    } else {
      if (run.length >= minLen) {
        brush.set(brushName, col, weight);
        drawSmoothSpline(run);
      }
      run = [];
    }
  }
  if (run.length >= minLen) {
    brush.set(brushName, col, weight);
    drawSmoothSpline(run);
  }
}

function extractAndDrawByShade(
  pts,
  dVals,
  threshold,
  minLen,
  brushName,
  palette,
  weight
) {
  let run = [];
  let sumD = 0;

  function flushRun() {
    if (run.length >= minLen) {
      let avgD = sumD / run.length;
      let cIdx = constrain(
        Math.floor(map(avgD, 0.15, 0.75, palette.length - 1, 0)),
        0,
        palette.length - 1
      );
      brush.set(brushName, palette[cIdx], weight);
      drawSmoothSpline(run);
    }
    run = [];
    sumD = 0;
  }

  for (let i = 0; i < pts.length; i++) {
    if (dVals[i] >= threshold) {
      run.push(pts[i]);
      sumD += dVals[i];
    } else {
      flushRun();
    }
  }
  flushRun();
}

function drawSmoothSpline(pts) {
  if (pts.length < 2) return;
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
    return;
  }
  brush.spline(pts, 0.45);
}

