function drawWeatherFront(
  ctrlPts,
  frontType,
  sideSign,
  pipSpacing,
  pipSize,
  mainCol,
  softCol
) {
  let curve = sampleCatmullRom(ctrlPts, 140);
  let pts = curve.pts;

  // Draw double-pass colored pencil frontal line for soft cerulean / rose richness
  let lineCoords = pts.map((p) => [p.x, p.y]);
  brush.set("front_pencil", mainCol, 1.15);
  brush.spline(lineCoords, 0.45);
  brush.set("iso_primary", softCol, 0.85);
  brush.spline(lineCoords, 0.45);

  // Compute cumulative arc length and place meteorological pips
  let arcLens = [0];
  for (let i = 1; i < pts.length; i++) {
    let d = Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
    arcLens.push(arcLens[i - 1] + d);
  }
  let totalLen = arcLens[arcLens.length - 1];

  for (let s = pipSpacing * 0.65; s < totalLen - pipSpacing * 0.45; s += pipSpacing) {
    // Find point at arc length s
    let idx = 0;
    while (idx < arcLens.length - 2 && arcLens[idx + 1] < s) idx++;
    let p = pts[idx];
    let nx = p.nx * sideSign;
    let ny = p.ny * sideSign;
    let tx = p.tx;
    let ty = p.ty;

    if (frontType === "cold") {
      // Equilateral cold-front triangle pip filled with concentric pencil strokes
      let halfBase = pipSize * 0.68;
      let height = pipSize * 1.12;
      for (let scale = 1.0; scale >= 0.2; scale -= 0.26) {
        let hb = halfBase * scale;
        let h = height * scale;
        let ax = p.x - tx * hb;
        let ay = p.y - ty * hb;
        let bx = p.x + tx * hb;
        let by = p.y + ty * hb;
        let cx = p.x + nx * h;
        let cy = p.y + ny * h;

        brush.set(
          scale > 0.7 ? "front_pencil" : "iso_secondary",
          scale > 0.7 ? mainCol : softCol,
          0.88
        );
        brush.line(ax, ay, cx, cy);
        brush.line(cx, cy, bx, by);
        if (scale > 0.7) brush.line(bx, by, ax, ay);
      }
    } else if (frontType === "warm") {
      // Warm-front semicircle pip drawn with nested pencil dome arcs
      let rBase = pipSize * 0.68;
      for (let scale = 1.0; scale >= 0.22; scale -= 0.25) {
        let r = rBase * scale;
        let arcPts = [];
        for (let a = 0; a <= 180; a += 22.5) {
          let rad = (a * Math.PI) / 180;
          let ca = Math.cos(rad);
          let sa = Math.sin(rad);
          let px = p.x - tx * ca * r + nx * sa * r;
          let py = p.y - ty * ca * r + ny * sa * r;
          arcPts.push([px, py]);
        }
        brush.set(
          scale > 0.7 ? "front_pencil" : "iso_secondary",
          scale > 0.7 ? mainCol : softCol,
          0.88
        );
        brush.spline(arcPts, 0.45);
      }
    }
  }
}

