// METEOROLOGICAL ANNOTATIONS, TROUGH AXES, ISOBAR LABELS & CHART FRAME
// ============================================================================
function renderChartAnnotations() {
  // 1. Dashed Trough Axes along major pillow and sheet radial valleys
  const troughCurves = [
    [
      [365, 285],
      [275, 345],
      [175, 385]
    ],
    [
      [365, 285],
      [445, 215],
      [535, 165]
    ],
    [
      [388, 548],
      [265, 595],
      [135, 642]
    ],
    [
      [328, 982],
