    for (let i = 0; i < c.pts.length - 2; i += 3) {
      let p0 = c.pts[i];
      let p1 = c.pts[i + 1];
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // 2. Pressure Centers (L and H with millibar readings and crosshairs)
  const centers = [
    { x: 364, y: 284, type: "L", mb: "992", col: "#b5564e" }, // Deep left pillow hollow
    { x: 742, y: 294, type: "L", mb: "1001", col: "#b5564e" }, // Right pillow secondary hollow
    { x: 388, y: 548, type: "L", mb: "1004", col: "#8c5c4c" }, // Sleeper torso impression
    { x: 328, y: 982, type: "L", mb: "995", col: "#b5564e" }, // Foot-tangle hollow
    { x: 878, y: 232, type: "H", mb: "1022", col: "#477894" }, // Right pillow puffed crown
    { x: 838, y: 832, type: "H", mb: "1024", col: "#477894" }  // Lower-right duvet dome
  ];

  for (let c of centers) {
    // Tiny target crosshair
    brush.set("iso_fine", c.col, 0.75);
    brush.line(c.x - 4, c.y, c.x + 4, c.y);
    brush.line(c.x, c.y - 4, c.x, c.y + 4);

    // Vector-plotted L or H
    brush.set("iso_primary", c.col, 1.05);
    if (c.type === "L") {
      brush.line(c.x - 5, c.y - 17, c.x - 5, c.y - 7);
      brush.line(c.x - 5, c.y - 7, c.x + 3, c.y - 7);
    } else {
      brush.line(c.x - 5, c.y - 17, c.x - 5, c.y - 7);
      brush.line(c.x + 3, c.y - 17, c.x + 3, c.y - 7);
      brush.line(c.x - 5, c.y - 12, c.x + 3, c.y - 12);
    }

    // Millibar reading below crosshair
    drawVectorNumber(c.mb, c.x - 10, c.y + 7, 4.2, "#5c463a");
  }

  // 3. Inline Isobar Millibar Labels along selected index contours
  let placedLabels = [];
  for (let cand of indexLabelCandidates) {
    let midIdx = Math.floor(cand.pts.length * 0.5);
    let p = cand.pts[midIdx];
    if (p[0] < 130 || p[0] > 1070 || p[1] < 130 || p[1] > 1070) continue;

    // Avoid crowding other labels or pressure centers
    let tooClose = false;
    for (let pl of placedLabels) {
      if (Math.hypot(p[0] - pl[0], p[1] - pl[1]) < 145) {
        tooClose = true;
        break;
      }
    }
    for (let c of centers) {
      if (Math.hypot(p[0] - c.x, p[1] - c.y) < 95) {
        tooClose = true;
        break;
      }
    }
    if (tooClose) continue;

    placedLabels.push(p);
    drawVectorNumber(String(cand.mb), p[0] - 8, p[1] - 3, 3.6, "#664e40");
  }

  // 4. Crisp Analytical Chart Frame and Coordinate Tick Marks
  let x0 = MARGIN,
    y0 = MARGIN,
    x1 = 1200 - MARGIN,
    y1 = 1200 - MARGIN;

  // Outer double rule
  brush.set("iso_primary", "#5a473c", 0.85);
  brush.line(x0, y0, x1, y0);
  brush.line(x1, y0, x1, y1);
  brush.line(x1, y1, x0, y1);
  brush.line(x0, y1, x0, y0);

  let pad = 7;
  brush.set("iso_fine", "#786254", 0.7);
  brush.line(x0 - pad, y0 - pad, x1 + pad, y0 - pad);
  brush.line(x1 + pad, y0 - pad, x1 + pad, y1 + pad);
  brush.line(x1 + pad, y1 + pad, x0 - pad, y1 + pad);
  brush.line(x0 - pad, y1 + pad, x0 - pad, y0 - pad);

  // Subtle meteorological grid ticks along frame border
  for (let t = x0 + 60; t < x1; t += 60) {
    brush.line(t, y0 - pad, t, y0);
    brush.line(t, y1, t, y1 + pad);
    brush.line(x0 - pad, t, x0, t);
    brush.line(x1, t, x1 + pad, t);
  }
}

// Clean single-stroke vector digit plotter for crisp chart numbers using p5.brush
function drawVectorNumber(str, x, y, h, col) {
  let w = h * 0.62;
  let gap = h * 0.88;
  brush.set("iso_fine", col, 0.72);

  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    let ox = x + i * gap;
    let oy = y;
    let segs = getDigitSegments(ch, ox, oy, w, h);
    for (let s of segs) {
      brush.line(s[0], s[1], s[2], s[3]);
    }
  }
}

function getDigitSegments(ch, x, y, w, h) {
  let xm = x + w * 0.5;
  let x1 = x + w;
  let ym = y + h * 0.5;
  let y1 = y + h;

  switch (ch) {
    case "0":
      return [
        [x, y, x1, y],
        [x1, y, x1, y1],
        [x1, y1, x, y1],
        [x, y1, x, y]
      ];
    case "1":
      return [
        [xm, y, xm, y1],
        [x, y + h * 0.2, xm, y],
        [x, y1, x1, y1]
      ];
    case "2":
      return [
        [x, y, x1, y],
        [x1, y, x1, ym],
        [x1, ym, x, ym],
        [x, ym, x, y1],
        [x, y1, x1, y1]
      ];
    case "3":
      return [
        [x, y, x1, y],
        [x1, y, x1, y1],
        [x1, y1, x, y1],
        [x, ym, x1, ym]
      ];
    case "4":
      return [
        [x, y, x, ym],
        [x, ym, x1, ym],
        [x1, y, x1, y1]
      ];
    case "5":
      return [
        [x1, y, x, y],
        [x, y, x, ym],
        [x, ym, x1, ym],
        [x1, ym, x1, y1],
        [x1, y1, x, y1]
      ];
    case "6":
      return [
        [x1, y, x, y],
        [x, y, x, y1],
        [x, y1, x1, y1],
        [x1, y1, x1, ym],
        [x1, ym, x, ym]
      ];
    case "7":
      return [
        [x, y, x1, y],
        [x1, y, x + w * 0.25, y1]
      ];
    case "8":
      return [
        [x, y, x1, y],
        [x1, y, x1, y1],
        [x1, y1, x, y1],
        [x, y1, x, y],
        [x, ym, x1, ym]
      ];
    case "9":
      return [
        [x1, ym, x, ym],
        [x, ym, x, y],
        [x, y, x1, y],
        [x1, y, x1, y1],
        [x1, y1, x, y1]
      ];
    default:
      return [];
  }
}

// Hyperreal Early Colour Plate (Autochrome Lumière, c. 1910):
// Hand-knitted mustard cardigan on a striped canvas deckchair at a lawn edge.

const GRID_RES = 150;
let plateGrid = [];
let strokeBuckets = new Map();

// Autochrome starch & tonal palette
const PAL = {
  // Deep plum-brown & aubergine shadows (high contrast darks)
  shadow0: "#160a14",
  shadow1: "#23101e",
  shadow2: "#331829",
  shadow3: "#472335",
  shadowPlum: "#592c3f",

  // Autochrome primary starch grains (Orange-Red, Green, Violet)
  orDeep: "#8c241b",
  orMid: "#d93e22",
  orBright: "#eb5e28",
  orWarm: "#f58838",
  orPowder: "#fcaea0",

  grDeep: "#1b4028",
  grMid: "#2f6e3e",
  grBright: "#468f4c",
  grChartreuse: "#82ab3a",
  grPowder: "#bdd48a",

  viDeep: "#251138",
  viMid: "#3e2159",
  viBright: "#5e409c",
  viLuminous: "#8062bd",
