  wool0: "#2b1420",
  wool1: "#452129",
  wool2: "#693821",
  wool3: "#8f551d",
  wool4: "#b57921",
  wool5: "#d49b27",
  wool6: "#e8b838",
  wool7: "#f5cf5b",
  wool8: "#fce38d",
  wool9: "#fff5c8",

