async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4079);
  noiseSeed(4079);

  // Custom Autochrome multi-grain starch cluster brush (5 microscopic grains per stamp)
  brush.add("starch_cluster", {
    type: "custom",
    weight: 1.5,
    scatter: 2.2,
    opacity: 145,
    spacing: 0.55,
    pressure: [0.85, 1.15, 0.8],
    tip: (_m) => {
      _m.circle(-1.1, -0.7, 0.48);
      _m.circle(1.0, -0.5, 0.42);
      _m.circle(-0.2, 1.1, 0.46);
      _m.circle(0.85, 0.85, 0.38);
      _m.circle(0.0, 0.0, 0.54);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.4
  });

  // Finer starch stipple for delicate stitch & wood grain transitions
  brush.add("starch_fine", {
    type: "custom",
    weight: 1.0,
    scatter: 1.4,
    opacity: 165,
    spacing: 0.42,
    pressure: [0.9, 1.1, 0.9],
    tip: (_m) => {
      _m.circle(-0.65, -0.4, 0.36);
      _m.circle(0.65, -0.25, 0.32);
      _m.circle(0.0, 0.65, 0.35);
      _m.circle(0.1, -0.1, 0.40);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.3
  });

  // 2-ply twisted wool yarn brush for individual knit stitches
  brush.add("yarn_ply", {
    type: "default",
    weight: 0.85,
    scatter: 0.14,
    sharpness: 0.62,
    grain: 0.85,
    opacity: 195,
    spacing: 0.18,
    pressure: [0.65, 1.25, 0.65],
    noise: 0.5
  });

  // Fine wool halo & weathered wood splinter brush
  brush.add("fine_fiber", {
    type: "default",
    weight: 0.42,
    scatter: 0.08,
    sharpness: 0.82,
    grain: 0.78,
    opacity: 175,
    spacing: 0.15,
    pressure: [0.9, 0.6, 0.2],
    noise: 0.6
  });

  initPlateGrid();
}

function draw() {
  translate(-width / 2, -height / 2);

  // Deep plum-aubergine silver gelatin base
  background(PAL.shadow0);

  // 1. Base watercolor & tonal washes establishing high-contrast lighting
  renderUnderpaintingWashes();

  // 2. Lawn edge & warm stone/gravel border
  renderLawnAndGravelEdge();
  flushBuckets();

  // 3. Rear deckchair wooden struts & ground cast shadows
  renderRearDeckchairFrame();
  flushBuckets();

  // 4. Striped canvas sling (3D catenary surface with warp/weft & cast shadows)
  renderStripedCanvasSling();
  flushBuckets();

  // 5. Foreground main wooden side rails & brass pivot rivets
  renderMainDeckchairRails();
  flushBuckets();

  // 6. Cast shadows of the cardigan onto canvas & left rail
  renderCardiganCastShadows();

  // 7. Hand-knitted mustard cardigan (sculpted 3D folds, cable & rib stitches, buttons)
  renderKnittedCardigan();
  flushBuckets();

  // 8. The dangling loose thread against the deep plum-brown shadow
  renderDanglingLooseThread();
  flushBuckets();

  // 9. Unified Autochrome Lumière potato-starch optical screen & corner vignette
  renderAutochromeStarchScreen();
  flushBuckets();

  noLoop();
}

// ============================================================================
// PLATE GRID & BUCKETED STROKE ENGINE
// ============================================================================

function initPlateGrid() {
  plateGrid = new Array(GRID_RES);
  for (let gx = 0; gx < GRID_RES; gx++) {
    plateGrid[gx] = new Array(GRID_RES);
    for (let gy = 0; gy < GRID_RES; gy++) {
      plateGrid[gx][gy] = { r: 28, g: 14, b: 24, lum: 0.08, tag: "bg" };
    }
  }
}

function recordGrid(x, y, r, g, b, lum, tag = "scene", rad = 1) {
  let cx = floor((x / width) * GRID_RES);
  let cy = floor((y / height) * GRID_RES);
  for (let dx = -rad; dx <= rad; dx++) {
    for (let dy = -rad; dy <= rad; dy++) {
      let gx = cx + dx;
      let gy = cy + dy;
      if (gx >= 0 && gx < GRID_RES && gy >= 0 && gy < GRID_RES) {
        let cell = plateGrid[gx][gy];
        let a = dx === 0 && dy === 0 ? 0.75 : 0.35;
        cell.r = lerp(cell.r, r, a);
        cell.g = lerp(cell.g, g, a);
        cell.b = lerp(cell.b, b, a);
        cell.lum = lerp(cell.lum, lum, a);
        cell.tag = tag;
      }
    }
  }
}

function queueLine(brushName, colorHex, weight, x1, y1, x2, y2) {
  let wQuant = round(weight * 20) / 20;
  let key = brushName + "|" + colorHex + "|" + wQuant;
  let bucket = strokeBuckets.get(key);
  if (!bucket) {
    bucket = { brushName, colorHex, weight: wQuant, lines: [] };
    strokeBuckets.set(key, bucket);
  }
  bucket.lines.push(x1, y1, x2, y2);
}

function flushBuckets() {
  for (let bucket of strokeBuckets.values()) {
    brush.set(bucket.brushName, bucket.colorHex, bucket.weight);
    let arr = bucket.lines;
    for (let i = 0; i < arr.length; i += 4) {
      brush.line(arr[i], arr[i + 1], arr[i + 2], arr[i + 3]);
    }
  }
  strokeBuckets.clear();
}

function drawWashPoly(pts, col, opacity, bleed = 0.18, tex = 0.45) {
  brush.noStroke();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.25);
  brush.beginShape(0.25);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function drawSolidWashPoly(pts, col, opacity) {
  let poly = new brush.Polygon(pts);
  poly.wash(col, opacity);
}

// ============================================================================
// 1. UNDERPAINTING & HIGH-CONTRAST LUMINOSITY WASHES
// ============================================================================

