  );
  drawWashPoly(
    [[60, 60], [620, 60], [460, 460], [110, 660]],
    "#828938", 110, 0.32, 0.5
  );

  // Warm gravel/limestone path edge (lower-right)
  drawWashPoly(
    [[1200, 500], [1200, 1200], [320, 1200], [820, 770]],
    "#6e554c", 165, 0.22, 0.5
  );
  drawWashPoly(
    [[1180, 580], [1180, 1150], [520, 1180], [880, 810]],
    "#a88e76", 125, 0.25, 0.45
  );

  // Deep plum-brown shadow pool under the deckchair & sleeve
  drawWashPoly(
    [[180, 720], [730, 580], [1120, 980], [860, 1190], [200, 1140]],
