  );

  // Gentle early-plate corner vignette washes
  drawWashPoly([[0, 0], [360, 0], [180, 180], [0, 360]], PAL.shadow0, 175, 0.35, 0.5);
  drawWashPoly([[840, 0], [1200, 0], [1200, 380], [1000, 190]], PAL.shadow0, 185, 0.35, 0.5);
  drawWashPoly([[0, 820], [190, 1000], [380, 1200], [0, 1200]], PAL.shadow0, 195, 0.35, 0.5);
  drawWashPoly([[800, 1200], [1000, 990], [1200, 780], [1200, 1200]], PAL.shadow0, 205, 0.35, 0.5);
