function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawShapePts(pts, curvature = 0, closed = true) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 0.25) clean.push(pts[i]);
  }
  if (closed && clean.length > 2) {
    let dx = clean[0][0] - clean[clean.length - 1][0];
    let dy = clean[0][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy <= 0.25) clean.pop();
  }
  if (clean.length < 3) return;

  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(closed);
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-7) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function distToPolyEdge(x, y, poly) {
  let minD2 = 1e9;
  for (let i = 0; i < poly.length; i++) {
    let p1 = poly[i];
    let p2 = poly[(i + 1) % poly.length];
    let vx = p2[0] - p1[0], vy = p2[1] - p1[1];
    let wx = x - p1[0], wy = y - p1[1];
    let c1 = vx * wx + vy * wy;
    let c2 = vx * vx + vy * vy;
    let t = c2 > 1e-6 ? Math.max(0, Math.min(1, c1 / c2)) : 0;
    let px = p1[0] + t * vx, py = p1[1] + t * vy;
    let d2 = (x - px) * (x - px) + (y - py) * (y - py);
    if (d2 < minD2) minD2 = d2;
  }
  return Math.sqrt(minD2);
}

function lerpHex(c1, c2, t) {
  t = Math.max(0, Math.min(1, t));
  let r1 = parseInt(c1.slice(1, 3), 16), g1 = parseInt(c1.slice(3, 5), 16), b1 = parseInt(c1.slice(5, 7), 16);
  let r2 = parseInt(c2.slice(1, 3), 16), g2 = parseInt(c2.slice(3, 5), 16), b2 = parseInt(c2.slice(5, 7), 16);
  let r = Math.round(r1 + (r2 - r1) * t);
  let g = Math.round(g1 + (g2 - g1) * t);
  let b = Math.round(b1 + (b2 - b1) * t);
  return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

function makeEllipsePoly(cx, cy, rx, ry, rotRad, n = 40, wobble = 0) {
  let pts = [];
  let cr = Math.cos(rotRad), sr = Math.sin(rotRad);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let w = wobble > 0 ? 1 + wobble * Math.sin(a * 5 + 1.2) + wobble * 0.5 * Math.cos(a * 3 - 0.7) : 1;
    let lx = Math.cos(a) * rx * w;
    let ly = Math.sin(a) * ry * w;
    pts.push([cx + lx * cr - ly * sr, cy + lx * sr + ly * cr]);
  }
  return pts;
}

