function drawGoldCord(pts, isLitSide) {
  resetBrush();
  // Dark seam shadow under cord
  brush.set("charcoal", "#02050d", 2.4);
  brush.spline(pts.map(p => [p[0], p[1] + 5, 1]), 0.4);

  // Base antique bronze-gold cord
  brush.set("marker", isLitSide ? "#593e0e" : "#382607", 1.8);
  brush.spline(pts.map(p => [p[0], p[1], 1]), 0.4);

  // Twisted gold bullion segments along the spline
  let totalSteps = 58;
  for (let i = 0; i < totalSteps; i++) {
    let t = i / totalSteps;
    let idx = t * (pts.length - 1);
    let i0 = Math.floor(idx);
    let i1 = Math.min(pts.length - 1, i0 + 1);
    let f = idx - i0;
    let x = pts[i0][0] + (pts[i1][0] - pts[i0][0]) * f;
    let y = pts[i0][1] + (pts[i1][1] - pts[i0][1]) * f;
    let dx = pts[i1][0] - pts[i0][0];
    let dy = pts[i1][1] - pts[i0][1];
    let len = Math.hypot(dx, dy) || 1;
    let tx = dx / len, ty = dy / len;
    let nx = -ty, ny = tx;

    let shade = (isLitSide ? 0.85 : 0.45) * (1 - 0.35 * Math.abs(t - 0.4));
    let colMain = lerpHex("#4f3509", "#d4a238", shade);
    let colHigh = lerpHex("#7a5514", "#fae084", shade);

    brush.set("pen", colMain, 1.1);
    brush.line(x - nx * 4 - tx * 3, y - ny * 4 - ty * 3, x + nx * 4 + tx * 3, y + ny * 4 + ty * 3);
    brush.set("rotring", colHigh, 0.55);
    brush.line(x - nx * 2.5 - tx * 1.5, y - ny * 2.5 - ty * 1.5, x + nx * 1.5 + tx * 1.5, y + ny * 1.5 + ty * 1.5);
  }
}

// ============================================================================
// 3. CHASED GOLD CROWN (CALYX)
// ============================================================================
function renderChasedGoldCrown() {
  resetBrush();
  // Crown sits at the upper-right crest of the main pomegranate:
  // Neck center at (795, 385), axis tilted at -37 deg (pointing toward upper-right (925, 285))
  let cx = 795, cy = 385;
  let ang = -0.645; // -37 degrees in radians
  let ux = Math.cos(ang), uy = Math.sin(ang); // axis outward along crown
  let vx = -uy, vy = ux;                     // perpendicular across neck

  function crownPt(along, across) {
    return [cx + ux * along + vx * across, cy + uy * along + vy * across];
  }

  // 1) Back interior cavity of the calyx crown
  let backCavity = [
    crownPt(35, -52), crownPt(78, -68), crownPt(92, -32),
    crownPt(95, 0), crownPt(92, 34), crownPt(76, 66), crownPt(35, 52)
  ];
  resetBrush();
  brush.wash("#211202", 245);
  drawShapePts(backCavity, 0.25, true);

  // 2) Three Back Calyx Lobes (concave inner gold faces with warm ruby bounce light)
  let backLobes = [
    { a0: 42, w0: -52, aTip: 122, wTip: -76, a1: 48, w1: -16, shade: 0.62 },
    { a0: 48, w0: -20, aTip: 132, wTip: -8,  a1: 48, w1: 22,  shade: 0.52 },
    { a0: 48, w0: 18,  aTip: 118, wTip: 74,  a1: 38, w1: 54,  shade: 0.44 }
  ];

  for (let lb of backLobes) {
    let p0 = crownPt(lb.a0, lb.w0);
    let pMidL = crownPt((lb.a0 + lb.aTip) * 0.52, (lb.w0 + lb.wTip) * 0.56 - 6);
    let pTip = crownPt(lb.aTip, lb.wTip);
    let pMidR = crownPt((lb.a1 + lb.aTip) * 0.52, (lb.w1 + lb.wTip) * 0.56 + 6);
    let p1 = crownPt(lb.a1, lb.w1);
    let poly = [p0, pMidL, pTip, pMidR, p1];

    resetBrush();
    brush.wash(lerpHex("#2e1a03", "#8a5c11", lb.shade), 240);
    drawShapePts(poly, 0.2, true);

    // Subtle ruby reflection inside gold calyx
    resetBrush();
    brush.wash("#6b1418", 75);
    drawShapePts([p0, crownPt(lb.a0 + 28, (lb.w0 + lb.wTip) * 0.45), p1], 0.2, true);

    // Chased inner rib and rim lines
    resetBrush();
    brush.set("rotring", "#241302", 0.55);
    drawShapePts(poly, 0.2, true);
    let pBaseMid = crownPt((lb.a0 + lb.a1) * 0.5, (lb.w0 + lb.w1) * 0.5);
    brush.line(pBaseMid[0], pBaseMid[1], pTip[0], pTip[1]);

    brush.set("rotring", "#ebbd52", 0.45);
    brush.spline([p0, pMidL, pTip], 0.3);
  }

  // 3) Sculpted Chased Gold Neck / Chalice Body
  let neckPoly = [
    crownPt(-18, -66), crownPt(16, -54), crownPt(52, -58),
    crownPt(56, 0), crownPt(52, 58), crownPt(16, 54),
    crownPt(-18, 66), crownPt(-28, 0)
  ];
  resetBrush();
  brush.wash("#593a08", 250);
  drawShapePts(neckPoly, 0.3, true);

  // Shaded metallic gradient bands across the curved gold neck (bright upper-left, dark lower-right)
  let bands = 7;
  for (let b = 0; b < bands; b++) {
    let t0 = (b / bands) * 2 - 1;
    let t1 = ((b + 1) / bands) * 2 - 1;
    let bPoly = [
      crownPt(-20, t0 * 64),
      crownPt(16, t0 * 53),
      crownPt(52, t0 * 57),
      crownPt(52, t1 * 57),
      crownPt(16, t1 * 53),
      crownPt(-20, t1 * 64)
    ];
    // Upper side (t < 0) faces the upper-left spotlight
    let lightVal = Math.exp(-Math.pow((t0 + 0.42) * 1.45, 2));
    let bandCol = lerpHex("#331f03", "#e8b842", lightVal);
    resetBrush();
    brush.wash(bandCol, 210);
    drawShapePts(bPoly, 0.25, true);
  }

  // 4) Three Front Calyx Lobes (repoussé sculpted gold leaves with central ribs and scrollwork)
  let frontLobes = [
    { w0: -58, w1: -14, aBase: 42, aTip: 126, wTip: -54, light: 0.96 },
    { w0: -22, w1: 24,  aBase: 46, aTip: 138, wTip: 4,   light: 0.82 },
    { w0: 16,  w1: 58,  aBase: 42, aTip: 118, wTip: 60,  light: 0.48 }
  ];

  for (let lb of frontLobes) {
    let pL = crownPt(lb.aBase, lb.w0);
    let pR = crownPt(lb.aBase, lb.w1);
    let pMid = crownPt(lb.aBase - 6, (lb.w0 + lb.w1) * 0.5);
    let pTip = crownPt(lb.aTip, lb.wTip);
    let pCurveL = crownPt((lb.aBase + lb.aTip) * 0.54, lb.w0 * 0.62 + lb.wTip * 0.38 - 7);
    let pCurveR = crownPt((lb.aBase + lb.aTip) * 0.54, lb.w1 * 0.62 + lb.wTip * 0.38 + 7);

    // Left facet of the repoussé lobe (faces upper-left light)
    let leftHalf = [pL, pCurveL, pTip, pMid];
    // Right facet of the repoussé lobe (faces away from light)
    let rightHalf = [pMid, pTip, pCurveR, pR];

    let colLeft = lerpHex("#6e490b", "#f5cf62", lb.light);
    let colRight = lerpHex("#2b1a03", "#ad7b1d", lb.light * 0.72);

    resetBrush();
    brush.wash(colLeft, 240);
    drawShapePts(leftHalf, 0.22, true);

    resetBrush();
    brush.wash(colRight, 240);
    drawShapePts(rightHalf, 0.22, true);

    // Fine chased engraving & repoussé flute lines on each gold lobe
    resetBrush();
    for (let k = 1; k <= 5; k++) {
      let f = k / 6;
      let sL = [
        pL[0] + (pMid[0] - pL[0]) * f,
        pL[1] + (pMid[1] - pL[1]) * f
      ];
      let eL = [
        pCurveL[0] + (pTip[0] - pCurveL[0]) * f,
        pCurveL[1] + (pTip[1] - pCurveL[1]) * f
      ];
      brush.set("guilloche_burin", "#3b2404", 0.45);
      brush.line(sL[0], sL[1], eL[0], eL[1]);

      let sR = [
        pMid[0] + (pR[0] - pMid[0]) * f,
        pMid[1] + (pR[1] - pMid[1]) * f
      ];
      let eR = [
        pTip[0] + (pCurveR[0] - pTip[0]) * f,
        pTip[1] + (pCurveR[1] - pTip[1]) * f
      ];
      brush.set("guilloche_burin", "#211302", 0.45);
      brush.line(sR[0], sR[1], eR[0], eR[1]);
    }

    // Specular gold ridge along central repoussé spine and left edge
    brush.set("rotring", lb.light > 0.7 ? "#fff6c2" : "#e3b444", 0.65);
    brush.line(pMid[0], pMid[1], pTip[0], pTip[1]);
    brush.spline([pL, pCurveL, pTip], 0.3);

    // Crisp dark chased contour around lobe
    brush.set("rotring", "#261602", 0.5);
    brush.spline([pTip, pCurveR, pR], 0.3);
  }

  // 5) Chased Acanthus / Fluted Ornamentation on the Gold Neck
  let flutes = 9;
  for (let i = 0; i < flutes; i++) {
    let f = (i / (flutes - 1)) * 2 - 1;
    let wStart = f * 58;
    let wEnd = f * 48;
    let p0 = crownPt(-14, wStart);
    let p1 = crownPt(14, (wStart + wEnd) * 0.48);
    let p2 = crownPt(40, wEnd);

    let isLit = f < 0.15;
    resetBrush();
    brush.set("rotring", "#2b1902", 0.55);
    brush.spline([p0, p1, p2], 0.35);

    let p0H = crownPt(-14, wStart - 2.5);
    let p1H = crownPt(14, (wStart + wEnd) * 0.48 - 2.5);
    let p2H = crownPt(40, wEnd - 2.5);
    brush.set("rotring", isLit ? "#ffefb0" : "#b8841f", isLit ? 0.65 : 0.45);
    brush.spline([p0H, p1H, p2H], 0.35);
  }

  // 6) Beaded Gold Collar Ring at the junction with the Ruby Enamel Rind
  let numBeads = 19;
  for (let i = 0; i < numBeads; i++) {
    let f = (i / (numBeads - 1)) * 2 - 1;
    let curveAlong = -16 + Math.cos(f * Math.PI * 0.5) * 10;
    let bp = crownPt(curveAlong, f * 65);
    let r = 3.8 - Math.abs(f) * 0.8;
    let beadLit = Math.max(0.2, 1 - (f + 0.55) * 0.65);

    resetBrush();
    brush.wash("#241302", 230);
    brush.circle(bp[0] + 1, bp[1] + 1.2, r + 0.6, 0.1);

    resetBrush();
    brush.wash(lerpHex("#4a2f06", "#e8b944", beadLit), 245);
    brush.circle(bp[0], bp[1], r, 0.1);

    if (beadLit > 0.45) {
      resetBrush();
      brush.set("rotring", "#fff8d4", 0.65);
      brush.circle(bp[0] - r * 0.32, bp[1] - r * 0.32, r * 0.28, 0.05);
    }
  }
}

// ============================================================================
// 4. MAIN POMEGRANATE GEOMETRY & GUILLOCHÉ RUBY ENAMEL RIND
// ============================================================================
function buildMainPomegranateGeometry() {
  // Outer 3D sphere/ovoid of the pomegranate (slightly hexagonal-lobate botanical swell)
  let sphereCx = 638, sphereCy = 546;
  let sphereRx = 262, sphereRy = 250;
  let rot = -0.645; // aligned with crown axis (-37 deg)
  let cr = Math.cos(rot), sr = Math.sin(rot);

  let outerPoly = [];
  let nOuter = 96;
  for (let i = 0; i < nOuter; i++) {
    let a = (i / nOuter) * Math.PI * 2;
    // Slight hexagonal bossing + neck flare near angle 0 (crown direction)
    let boss = 1 + 0.022 * Math.cos(a * 6 - 0.3) + 0.015 * Math.sin(a * 3 + 0.8);
    let neckFlare = Math.exp(-Math.pow(Math.atan2(Math.sin(a), Math.cos(a)) * 2.6, 2)) * 0.045;
    let lx = Math.cos(a) * sphereRx * (boss + neckFlare);
    let ly = Math.sin(a) * sphereRy * boss;
    outerPoly.push([sphereCx + lx * cr - ly * sr, sphereCy + lx * sr + ly * cr]);
  }

  // Cut Face Rim (shifted toward lower-left viewer side so a wide 3D dome of ruby enamel rind shows on top/right/bottom-right)
  let cutCx = 568, cutCy = 582;
  let cutRx = 212, cutRy = 206;
  let outerRimPts = [];
  let innerCavityPts = [];
  let nRim = 84;

  for (let i = 0; i < nRim; i++) {
    let a = (i / nRim) * Math.PI * 2;
    // Organic undulating cut contour
    let undul = 1 + 0.032 * Math.sin(a * 5 + 0.4) + 0.018 * Math.cos(a * 3 - 1.1) + 0.012 * Math.sin(a * 8 + 2.0);
    let lx = Math.cos(a) * cutRx * undul;
    let ly = Math.sin(a) * cutRy * undul;
    let px = cutCx + lx * cr - ly * sr;
    let py = cutCy + lx * sr + ly * cr;
    outerRimPts.push([px, py]);

    // Inner boundary of the outer pale pearl membrane wall (thickness ~20-30 px, thicker at septum cusps)
    let cusp = 0.88 - 0.045 * Math.max(0, Math.cos(a * 5 + 0.35));
    let ilx = lx * cusp;
    let ily = ly * cusp;
    innerCavityPts.push([cutCx + ilx * cr - ily * sr, cutCy + ilx * sr + ily * cr]);
  }

  return {
    sphereCx, sphereCy, sphereRx, sphereRy, rot,
    cutCx, cutCy, cutRx, cutRy,
    outerPoly, outerRimPts, innerCavityPts
  };
}

function renderGuillocheRubyRind(geom) {
  resetBrush();
  let { sphereCx, sphereCy, sphereRx, sphereRy, rot, outerPoly, outerRimPts } = geom;
  let cr = Math.cos(rot), sr = Math.sin(rot);

  // 1) Underlayer of the Rind: Polished Rose-Gold / Crimson-Gilt Metallic Base
  // Deep claret-garnet base across the whole fruit silhouette
  resetBrush();
  brush.wash("#360208", 250);
  drawShapePts(outerPoly, 0.25, true);

  // Concentric metallic under-glow zones (shifted toward upper-left spotlight)
  let glowZones = [
    { dx: -15, dy: -22, sx: 0.92, sy: 0.90, col: "#5c0511", a: 210 },
    { dx: -35, dy: -45, sx: 0.78, sy: 0.75, col: "#8f091d", a: 195 },
    { dx: -55, dy: -68, sx: 0.62, sy: 0.58, col: "#c4122c", a: 185 },
    { dx: -72, dy: -85, sx: 0.45, sy: 0.42, col: "#eb3b52", a: 170 },
    { dx: -85, dy: -98, sx: 0.28, sy: 0.26, col: "#ff8593", a: 145 }
  ];

  for (let gz of glowZones) {
    let gPoly = makeEllipsePoly(
      sphereCx + gz.dx,
      sphereCy + gz.dy,
      sphereRx * gz.sx,
      sphereRy * gz.sy,
      rot,
      48
    );
    resetBrush();
    brush.wash(gz.col, gz.a);
    drawShapePts(gPoly, 0.3, true);
  }

  // 2) FINE GUILLOCHÉ PATTERN OF ENGRAVED WAVES
  // Helper: map 3D spherical coordinates (u = meridian angle from crown axis, v = azimuth around axis)
  // onto the visible front hemisphere of the pomegranate rind, clipped inside outerPoly and outside outerRimPts
  function rindSpherePt(u, v) {
    // u in [0.06, PI - 0.08] (0 is crown pole, PI is base pole)
    // v in [-PI/2, PI/2] (front hemisphere facing viewer)
    let boss = 1 + 0.02 * Math.cos(u * 5) * Math.sin(v * 3);
    let lx = Math.cos(u) * sphereRx * boss;
    let ly = Math.sin(u) * Math.sin(v) * sphereRy * boss;
    let lz = Math.sin(u) * Math.cos(v); // depth toward viewer in [0, 1]
    let x = sphereCx + lx * cr - ly * sr;
    let y = sphereCy + lx * sr + ly * cr;

    // Surface normal in screen space for jeweller's spotlight calculation
    let nx = (Math.cos(u) * cr - Math.sin(u) * Math.sin(v) * sr);
    let ny = (Math.cos(u) * sr + Math.sin(u) * Math.sin(v) * cr);
    let nz = lz;
    // Spotlight direction from upper-left (-0.58, -0.62, 0.52)
    let dotLight = Math.max(0, nx * -0.58 + ny * -0.62 + nz * 0.52);
    // Grazing blue velvet rim reflection on lower-right edge
    let dotRim = Math.max(0, nx * 0.65 + ny * 0.65) * (1 - nz * 0.7);
    return { x, y, dotLight, dotRim, nz };
  }

  function isVisibleRind(x, y) {
    return pointInPoly(x, y, outerPoly) && !pointInPoly(x, y, outerRimPts);
  }

  function drawClippedGuillocheWave(ptsWithLight) {
    let seg = [];
    for (let i = 0; i <= ptsWithLight.length; i++) {
      let p = i < ptsWithLight.length ? ptsWithLight[i] : null;
      if (p && p.inside) {
        seg.push(p);
      } else {
        if (seg.length >= 3) {
          let mid = seg[Math.floor(seg.length / 2)];
          // Shadow burin cut
          let cutCol = lerpHex("#1f0004", "#54030e", mid.dotLight);
          brush.set("guilloche_burin", cutCol, 0.46);
          brush.spline(seg.map(q => [q.x + 0.7, q.y + 0.7, 0.9]), 0.3);

          // Illuminated metallic guilloché ridge glowing from beneath the enamel
          let ridgeCol;
          if (mid.dotLight > 0.62) {
            ridgeCol = lerpHex("#ff4760", "#ffd1d9", (mid.dotLight - 0.62) / 0.38);
          } else if (mid.dotLight > 0.28) {
            ridgeCol = lerpHex("#8f071b", "#ff4760", (mid.dotLight - 0.28) / 0.34);
          } else {
            ridgeCol = lerpHex("#42020a", "#8f071b", mid.dotLight / 0.28);
          }
          if (mid.dotRim > 0.38 && mid.dotLight < 0.25) {
            ridgeCol = lerpHex(ridgeCol, "#5c7ec2", (mid.dotRim - 0.38) * 1.1);
          }
          brush.set("guilloche_burin", ridgeCol, mid.dotLight > 0.5 ? 0.52 : 0.4);
          brush.spline(seg.map(q => [q.x, q.y, 0.95]), 0.3);
        }
        seg = [];
      }
    }
  }

  // Family A: 58 Concentric Latitude Engine-Turned Wave Rings
  resetBrush();
  let nLat = 58;
  let stepsLat = 76;
  for (let i = 1; i < nLat; i++) {
    let uBase = 0.08 + (i / nLat) * (Math.PI - 0.16);
    let phase = (i % 2) * Math.PI; // Phased sine waves create classic Fabergé barleycorn/moiré cells
    let wavePts = [];
    for (let j = 0; j <= stepsLat; j++) {
      let v = -Math.PI * 0.49 + (j / stepsLat) * (Math.PI * 0.98);
      let uWave = uBase + 0.015 * Math.sin(v * 28 + phase) + 0.006 * Math.cos(v * 14 - phase);
      let pt = rindSpherePt(uWave, v);
      pt.inside = isVisibleRind(pt.x, pt.y);
      wavePts.push(pt);
    }
    drawClippedGuillocheWave(wavePts);
  }

  // Family B: 52 Meridional Harmonic Wave Ribbons radiating from Crown to Base
  let nMer = 52;
  let stepsMer = 76;
  for (let i = 0; i <= nMer; i++) {
    let vBase = -Math.PI * 0.48 + (i / nMer) * (Math.PI * 0.96);
    let phase = (i % 2) * Math.PI;
    let wavePts = [];
    for (let j = 0; j <= stepsMer; j++) {
      let u = 0.07 + (j / stepsMer) * (Math.PI - 0.14);
      let vWave = vBase + 0.018 * Math.sin(u * 26 + phase);
      let pt = rindSpherePt(u, vWave);
      pt.inside = isVisibleRind(pt.x, pt.y);
      wavePts.push(pt);
    }
    drawClippedGuillocheWave(wavePts);
  }

  // 3) LAYERED TRANSPARENT RUBY ENAMEL WASHES (glowing from beneath!)
  // Batch 1: Overall pigeon-blood ruby translucent vitreous glaze
  resetBrush();
  brush.fill("#99061c", 48);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.22, 0.12);
  drawShapePts(outerPoly, 0.25, true);

  // Batch 2: Rich carmine-ruby heart wash over the mid-dome
  let midRindCrescent = [];
  for (let i = 0; i <= 40; i++) {
    let v = -Math.PI * 0.46 + (i / 40) * Math.PI * 0.92;
    let p = rindSpherePt(0.12, v);
    midRindCrescent.push([p.x, p.y]);
  }
  for (let i = 40; i >= 0; i--) {
    let v = -Math.PI * 0.46 + (i / 40) * Math.PI * 0.92;
    let p = rindSpherePt(2.65, v);
    midRindCrescent.push([p.x, p.y]);
  }
  resetBrush();
  brush.fill("#bf0b26", 38);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.18, 0.1);
  drawShapePts(midRindCrescent, 0.25, true);

  // Batch 3: Deep pyrope-garnet shadow glaze on the lower-right & right hemisphere
  let shadowRindPoly = [];
  for (let i = 0; i <= 32; i++) {
    let u = 0.25 + (i / 32) * 2.65;
    let p = rindSpherePt(u, 0.05);
    shadowRindPoly.push([p.x, p.y]);
  }
  for (let i = 32; i >= 0; i--) {
    let u = 0.25 + (i / 32) * 2.65;
    let p = rindSpherePt(u, Math.PI * 0.48);
    shadowRindPoly.push([p.x, p.y]);
  }
  resetBrush();
  brush.fill("#2e0106", 62);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.25, 0.15);
  drawShapePts(shadowRindPoly, 0.25, true);

  // Batch 4: Incandescent ruby-orange inner glow on the upper-left spotlight shoulder
  let litShoulderPoly = [];
  for (let i = 0; i <= 24; i++) {
    let u = 0.22 + (i / 24) * 1.45;
    let p = rindSpherePt(u, -Math.PI * 0.45);
    litShoulderPoly.push([p.x, p.y]);
  }
  for (let i = 24; i >= 0; i--) {
    let u = 0.22 + (i / 24) * 1.45;
    let p = rindSpherePt(u, -0.05);
    litShoulderPoly.push([p.x, p.y]);
  }
  resetBrush();
  brush.wash("#ff2442", 34);
  drawShapePts(litShoulderPoly, 0.3, true);

  // 4) VITREOUS ENAMEL SPECULAR HIGHLIGHTS & IMPERIAL-BLUE VELVET RIM REFLECTION
  // High-gloss curved window reflections along the upper-top / upper-right dome
  let glossArcs = [
    { u0: 0.24, u1: 1.18, v: -0.56, w: 0.045, col: "#ff99aa", a: 95 },
    { u0: 0.30, u1: 0.98, v: -0.55, w: 0.022, col: "#ffe3e8", a: 155 },
    { u0: 0.36, u1: 0.78, v: -0.54, w: 0.010, col: "#ffffff", a: 215 },
    // Secondary narrow specular ribbon parallel to main window reflection
    { u0: 0.32, u1: 1.05, v: -0.36, w: 0.018, col: "#ffb3c0", a: 110 },
    { u0: 0.38, u1: 0.85, v: -0.36, w: 0.008, col: "#ffffff", a: 175 }
  ];

  for (let ga of glossArcs) {
    let arcPoly = [];
    let steps = 24;
    for (let i = 0; i <= steps; i++) {
      let u = ga.u0 + (i / steps) * (ga.u1 - ga.u0);
      let mod = 0.004 * Math.sin(u * 26); // subtle ripple from guilloché beneath
      let p = rindSpherePt(u, ga.v - ga.w + mod);
      if (isVisibleRind(p.x, p.y)) arcPoly.push([p.x, p.y]);
    }
    for (let i = steps; i >= 0; i--) {
      let u = ga.u0 + (i / steps) * (ga.u1 - ga.u0);
      let mod = 0.004 * Math.sin(u * 26);
      let p = rindSpherePt(u, ga.v + ga.w + mod);
      if (isVisibleRind(p.x, p.y)) arcPoly.push([p.x, p.y]);
    }
    if (arcPoly.length >= 4) {
      resetBrush();
      brush.wash(ga.col, ga.a);
      drawShapePts(arcPoly, 0.3, true);
    }
  }

  // Cool Imperial-Blue velvet bounce reflection along the lower-right glossy enamel edge
  resetBrush();
  for (let k = 0; k < 4; k++) {
    let vRim = Math.PI * 0.42 + k * 0.016;
    let rimCurve = [];
    for (let i = 0; i <= 28; i++) {
      let u = 0.55 + (i / 28) * 1.95;
      let p = rindSpherePt(u, vRim);
      if (isVisibleRind(p.x, p.y)) rimCurve.push([p.x, p.y, Math.sin((i / 28) * Math.PI)]);
    }
    if (rimCurve.length >= 3) {
      brush.set("enamel_gloss", k === 2 ? "#7aa4eb" : "#3a5a96", k === 2 ? 0.9 : 1.3);
      brush.spline(rimCurve, 0.35);
    }
  }

  // Crisp outer contour of the ruby enamel sphere
  resetBrush();
  brush.set("rotring", "#240105", 0.65);
  drawShapePts(outerPoly, 0.25, true);
}

// ============================================================================
// 5. PALE PEARL MEMBRANE, SEPTA, AND SEED PEARLS ALONG THE CUT EDGE
// ============================================================================
function buildMainChambersAndSepta(geom) {
  let { cutCx, cutCy, cutRx, cutRy, rot, outerRimPts, innerCavityPts } = geom;
  let cr = Math.cos(rot), sr = Math.sin(rot);

  // Botanical core (columella) slightly off-center inside the cut face
  let coreCx = cutCx - 12, coreCy = cutCy + 8;

  // 5 radial septa angles (in local cut-face radians) dividing the interior into 5 garnet chambers
  let septaAngles = [-2.55, -1.28, -0.12, 1.08, 2.22];
  let chambers = [];

  for (let c = 0; c < 5; c++) {
    let aStart = septaAngles[c];
    let aEnd = c < 4 ? septaAngles[c + 1] : septaAngles[0] + Math.PI * 2;
    let span = aEnd - aStart;

    // Leave angular margin for the pale pearl septum wall thickness (~0.095 rad on each side)
    let m0 = aStart + 0.092;
    let m1 = aEnd - 0.092;
    let chPoly = [];

    // 1) Inner core corner arc (around the pale pearl columella star)
    let coreSteps = 6;
    for (let i = 0; i <= coreSteps; i++) {
      let a = m0 + (i / coreSteps) * (m1 - m0);
      let rCore = 28 + 8 * Math.cos((i / coreSteps - 0.5) * Math.PI);
      let lx = Math.cos(a) * rCore;
      let ly = Math.sin(a) * rCore;
      chPoly.push([coreCx + lx * cr - ly * sr, coreCy + lx * sr + ly * cr]);
    }

    // 2) Right septum wall marching from core outward to innerCavityPts
    let wallSteps = 10;
    for (let i = 1; i < wallSteps; i++) {
      let t = i / wallSteps;
      let r = 32 + t * (cutRx * 0.84 - 32);
      // Natural organic wave in the thin pearl septum wall
      let wAng = m1 + 0.035 * Math.sin(t * Math.PI * 2 + c);
      let lx = Math.cos(wAng) * r;
      let ly = Math.sin(wAng) * r * (cutRy / cutRx);
      chPoly.push([
        coreCx * (1 - t) + cutCx * t + lx * cr - ly * sr,
        coreCy * (1 - t) + cutCy * t + lx * sr + ly * cr
      ]);
    }

    // 3) Outer chamber boundary hugging innerCavityPts
    let outerSteps = 18;
    for (let i = outerSteps; i >= 0; i--) {
      let a = m0 + (i / outerSteps) * (m1 - m0);
      let undul = 1 + 0.032 * Math.sin(a * 5 + 0.4) + 0.018 * Math.cos(a * 3 - 1.1);
      let cusp = 0.855 - 0.035 * Math.cos(((i / outerSteps) - 0.5) * Math.PI * 2);
      let lx = Math.cos(a) * cutRx * undul * cusp;
      let ly = Math.sin(a) * cutRy * undul * cusp;
      chPoly.push([cutCx + lx * cr - ly * sr, cutCy + lx * sr + ly * cr]);
    }

    // 4) Left septum wall marching from outer rim back to core
    for (let i = wallSteps - 1; i >= 1; i--) {
      let t = i / wallSteps;
      let r = 32 + t * (cutRx * 0.84 - 32);
      let wAng = m0 + 0.035 * Math.sin(t * Math.PI * 2 + c - 1);
      let lx = Math.cos(wAng) * r;
      let ly = Math.sin(wAng) * r * (cutRy / cutRx);
      chPoly.push([
        coreCx * (1 - t) + cutCx * t + lx * cr - ly * sr,
        coreCy * (1 - t) + cutCy * t + lx * sr + ly * cr
      ]);
    }

    // Compute chamber centroid
    let sumX = 0, sumY = 0;
    for (let p of chPoly) { sumX += p[0]; sumY += p[1]; }
    chambers.push({
      id: c,
      poly: chPoly,
      cx: sumX / chPoly.length,
      cy: sumY / chPoly.length,
      midAngle: (aStart + aEnd) * 0.5 + rot
    });
  }

  return { coreCx, coreCy, septaAngles, chambers };
}

function renderPalePearlMembraneBase(geom, septaData) {
  resetBrush();
  let { outerRimPts, innerCavityPts, cutCx, cutCy, cutRx, cutRy, rot } = geom;
  let { coreCx, coreCy, septaAngles } = septaData;

  // 1) Base shadow bevel where the ruby enamel rind meets the cut pearl membrane
  resetBrush();
  brush.wash("#2b040c", 220);
  drawShapePts(outerRimPts, 0.3, true);

  // 2) Pale Mother-of-Pearl Base across the entire cut face
  resetBrush();
  brush.wash("#d6deeb", 248);
  drawShapePts(outerRimPts, 0.3, true);

  // 3) Iridescent Nacre Washes (cool silver-blue shadow on lower-right, warm alabaster-cream in spotlight, blush-pink near chambers)
  resetBrush();
  brush.fill("#8b9bb8", 95);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.35, 0.2);
  drawShapePts(makeEllipsePoly(cutCx + 38, cutCy + 42, cutRx * 0.88, cutRy * 0.86, rot, 40), 0.3, true);

  resetBrush();
  brush.fill("#f5f7fc", 145);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.25, 0.15);
  drawShapePts(makeEllipsePoly(cutCx - 35, cutCy - 38, cutRx * 0.78, cutRy * 0.76, rot, 40), 0.3, true);

  // Rosy subsurface scatter along the inner membrane ring where the red garnet arils glow through the pearl pith
  resetBrush();
  brush.fill("#e39aa8", 110);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.3, 0.15);
  drawShapePts(innerCavityPts, 0.3, true);

  // 4) Delicate fibrous mother-of-pearl radial & contour texture along the outer pearl rim
  resetBrush();
  let nRim = outerRimPts.length;
  for (let i = 0; i < nRim; i++) {
    let pOut = outerRimPts[i];
    let pIn = innerCavityPts[i];
    let dx = pOut[0] - cutCx, dy = pOut[1] - cutCy;
    let isLit = (dx * -0.6 + dy * -0.6) > 0;

    brush.set("2H", isLit ? "#ffffff" : "#95a4bd", 0.55);
    brush.line(
      pOut[0] * 0.75 + pIn[0] * 0.25,
      pOut[1] * 0.75 + pIn[1] * 0.25,
      pOut[0] * 0.18 + pIn[0] * 0.82,
      pOut[1] * 0.18 + pIn[1] * 0.82
    );
  }

  // Iridescent aqua-pearl and blush-pearl sheen highlights on the nacreous septa & central columella
  let cr = Math.cos(rot), sr = Math.sin(rot);
  for (let c = 0; c < septaAngles.length; c++) {
    let a = septaAngles[c];
    let septumSpine = [];
    for (let s = 0; s <= 10; s++) {
      let t = s / 10;
      let r = 12 + t * (cutRx * 0.92 - 12);
      let wAng = a + 0.032 * Math.sin(t * Math.PI * 2 + c);
      let lx = Math.cos(wAng) * r;
      let ly = Math.sin(wAng) * r * (cutRy / cutRx);
      septumSpine.push([
        coreCx * (1 - t) + cutCx * t + lx * cr - ly * sr,
        coreCy * (1 - t) + cutCy * t + lx * sr + ly * cr,
        1.1 - t * 0.4
      ]);
    }
    resetBrush();
    brush.set("cpencil", "#e8b5c0", 1.8);
    brush.spline(septumSpine, 0.35);
    brush.set("2H", "#ffffff", 0.9);
    brush.spline(septumSpine, 0.35);
  }
}

// ============================================================================
// 6. FACETED CABOCHONS OF GARNET & PIGEON-BLOOD RED + STARBURST HIGHLIGHTS
// ============================================================================
function packChamberArils(chamberPoly, minDist = 27.5, seedOffset = 0) {
  // Compute bounding box of chamberPoly
  let minX = 1e9, minY = 1e9, maxX = -1e9, maxY = -1e9;
  for (let p of chamberPoly) {
    if (p[0] < minX) minX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] > maxY) maxY = p[1];
  }

  // Generate initial candidate seed centers inside chamberPoly
  let seeds = [];
  let step = minDist * 0.86;
  let row = 0;
  for (let y = minY + 11; y <= maxY - 11; y += step * 0.866) {
    let xShift = (row % 2) * (step * 0.5);
    for (let x = minX + 11 + xShift; x <= maxX - 11; x += step) {
      // Deterministic jitter
      let jx = Math.sin(x * 0.17 + y * 0.31 + seedOffset) * 4.2;
      let jy = Math.cos(x * 0.23 - y * 0.19 + seedOffset) * 4.2;
      let px = x + jx, py = y + jy;
      if (pointInPoly(px, py, chamberPoly) && distToPolyEdge(px, py, chamberPoly) > 9.5) {
        seeds.push({ x: px, y: py, rMax: 17.5 + 3.2 * Math.sin(row * 1.7 + x * 0.05) });
      }
    }
    row++;
  }

  // Relaxation passes so arils pack snugly and organically into every corner of the chamber
  for (let iter = 0; iter < 12; iter++) {
    for (let i = 0; i < seeds.length; i++) {
      let fx = 0, fy = 0;
      for (let j = 0; j < seeds.length; j++) {
        if (i === j) continue;
        let dx = seeds[i].x - seeds[j].x;
        let dy = seeds[i].y - seeds[j].y;
        let d = Math.hypot(dx, dy) || 0.01;
        let target = (seeds[i].rMax + seeds[j].rMax) * 0.82;
        if (d < target) {
          let push = (target - d) * 0.32;
          fx += (dx / d) * push;
          fy += (dy / d) * push;
        }
      }
      let nx = seeds[i].x + fx;
      let ny = seeds[i].y + fy;
      if (pointInPoly(nx, ny, chamberPoly) && distToPolyEdge(nx, ny, chamberPoly) > 8.5) {
        seeds[i].x = nx;
        seeds[i].y = ny;
      }
    }
  }

  // Build mutually compressed Voronoi/botanical cabochon polygon for each seed
  let arils = [];
  let nDirs = 10;
  for (let i = 0; i < seeds.length; i++) {
    let s = seeds[i];
    let poly = [];
    let rSum = 0;
    // Slight elongation axis pointing roughly toward chamber center
    let baseAng = Math.atan2(s.y - 580, s.x - 565);

    for (let k = 0; k < nDirs; k++) {
      let a = (k / nDirs) * Math.PI * 2;
      let dirX = Math.cos(a), dirY = Math.sin(a);
      let elong = 1 + 0.12 * Math.cos((a - baseAng) * 2);
      let maxR = s.rMax * elong;
      let bestR = 4;

      for (let r = 4; r <= maxR; r += 1.4) {
        let tx = s.x + dirX * r;
        let ty = s.y + dirY * r;
        if (!pointInPoly(tx, ty, chamberPoly) || distToPolyEdge(tx, ty, chamberPoly) < 1.8) {
          break;
        }
        // Check Voronoi half-plane against neighboring seeds
        let tooClose = false;
        for (let j = 0; j < seeds.length; j++) {
          if (i === j) continue;
          let dOther = Math.hypot(tx - seeds[j].x, ty - seeds[j].y);
          if (dOther < r + 0.85) {
            tooClose = true;
            break;
          }
        }
        if (tooClose) break;
        bestR = r;
      }
      rSum += bestR;
      poly.push([s.x + dirX * bestR, s.y + dirY * bestR]);
    }

    let edgeDist = distToPolyEdge(s.x, s.y, chamberPoly);
    arils.push({
      cx: s.x,
      cy: s.y,
      rAvg: rSum / nDirs,
      poly,
      edgeDist,
      toneSeed: Math.abs(Math.sin(i * 12.9898 + seedOffset * 78.233))
    });
  }

  // Sort so perimeter/recessed arils draw first and central crowning arils sit slightly proud
  arils.sort((a, b) => a.edgeDist - b.edgeDist);
  return arils;
}

function drawFacetedAril(aril, lightFactor = 1.0, isLoose = false) {
  let { cx, cy, rAvg, poly, toneSeed } = aril;
  let n = poly.length;
  if (n < 5 || rAvg < 4.5) return;

  // Determine gem variety: rich pyrope/almandine garnet vs electric pigeon-blood ruby
  let isPigeonBlood = toneSeed > 0.36;
  let colSocket  = "#1a0104";
  let colDark    = isPigeonBlood ? "#4a020b" : "#330107";
  let colMid     = isPigeonBlood ? "#99071d" : "#6e0413";
  let colVivid   = isPigeonBlood ? "#db0f2e" : "#ad0921";
  let colCaustic = isPigeonBlood ? "#ff3856" : "#eb1c3a";
  let colEmber   = isPigeonBlood ? "#ff8597" : "#ff5972";
  let colCrownHi = isPigeonBlood ? "#ff99aa" : "#ff758c";

  // Modulate by overall chamber lightFactor
  if (lightFactor < 0.85) {
    let dim = 1 - lightFactor;
    colMid     = lerpHex(colMid, "#2b0106", dim * 0.55);
    colVivid   = lerpHex(colVivid, "#4d030c", dim * 0.5);
    colCaustic = lerpHex(colCaustic, "#820718", dim * 0.45);
  }

  // 1) Deep socket / bezel shadow around the aril
  resetBrush();
  brush.wash(colSocket, 235);
  drawShapePts(poly, 0.25, true);

  // 2) Construct Crown Table Polygon (shifted slightly toward upper-left spotlight for 3D cabochon dome)
  let tableCx = cx - rAvg * 0.14;
  let tableCy = cy - rAvg * 0.14;
  let tablePoly = [];
  let girdlePoly = [];

  for (let i = 0; i < n; i++) {
    let gx = cx + (poly[i][0] - cx) * 0.92;
    let gy = cy + (poly[i][1] - cy) * 0.92;
    girdlePoly.push([gx, gy]);

    let tx = tableCx + (poly[i][0] - cx) * 0.44;
    let ty = tableCy + (poly[i][1] - cy) * 0.44;
    tablePoly.push([tx, ty]);
  }

  // 3) Draw each surrounding Crown / Pavilion Facet Quad individually based on its 3D facet normal!
  for (let i = 0; i < n; i++) {
    let iNext = (i + 1) % n;
    let g0 = girdlePoly[i], g1 = girdlePoly[iNext];
    let t0 = tablePoly[i],  t1 = tablePoly[iNext];
    let quad = [g0, g1, t1, t0];

    // Facet outward direction from aril center
    let mx = (g0[0] + g1[0]) * 0.5 - cx;
    let my = (g0[1] + g1[1]) * 0.5 - cy;
    let mLen = Math.hypot(mx, my) || 1;
    let nx = mx / mLen, ny = my / mLen;

    // Dot with upper-left jeweller's spotlight (-0.68, -0.73)
    let dotLight = nx * -0.68 + ny * -0.73;
    // Dot with lower-right internal subsurface caustic glow (+0.65, +0.76)
    let dotCaustic = nx * 0.65 + ny * 0.76;

    let facetCol;
    if (dotLight > 0.52) {
      // Upper-left crown facets catching direct specular sky/spotlight reflection
      facetCol = lerpHex(colVivid, colCrownHi, (dotLight - 0.52) * 1.6 * lightFactor);
    } else if (dotLight > 0.05) {
      // High-contrast rich ruby/garnet crown facets
      facetCol = (i % 2 === 0) ? colMid : colDark;
    } else if (dotCaustic > 0.42) {
      // Lower-right pavilion facets glowing with internal refracted pigeon-blood caustic!
      facetCol = lerpHex(colVivid, colCaustic, (dotCaustic - 0.42) * 1.5 * lightFactor);
    } else {
      // Deep velvety extinction facets on the sides
      facetCol = (i % 2 === 0) ? colDark : colMid;
    }

    resetBrush();
    brush.wash(facetCol, 240);
    drawShapePts(quad, 0, true);
  }

  // 4) Central Table Facet + Internal Translucent Seed Core (Sarcotesta) Ember Glow
  resetBrush();
  brush.wash(lerpHex(colMid, colVivid, 0.65 * lightFactor), 245);
  drawShapePts(tablePoly, 0, true);

  // Warm internal seed-kernel caustic glowing inside the lower-right half of the table & dome
  let emberPoly = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let ex = cx + rAvg * 0.12 + Math.cos(a) * rAvg * 0.34;
    let ey = cy + rAvg * 0.12 + Math.sin(a) * rAvg * 0.24;
    emberPoly.push([ex, ey]);
  }
  resetBrush();
  brush.wash(colCaustic, Math.round(165 * lightFactor));
  drawShapePts(emberPoly, 0.25, true);

  let seedCorePoly = makeEllipsePoly(cx + rAvg * 0.14, cy + rAvg * 0.15, rAvg * 0.19, rAvg * 0.12, 0.5, 12);
  resetBrush();
  brush.wash(colEmber, Math.round(145 * lightFactor));
  drawShapePts(seedCorePoly, 0.3, true);

  // 5) Crisp Geometric Facet Junction Ridges
  resetBrush();
  for (let i = 0; i < n; i++) {
    let iNext = (i + 1) % n;
    let g0 = girdlePoly[i], t0 = tablePoly[i], t1 = tablePoly[iNext];
    let dx = t0[0] - cx, dy = t0[1] - cy;
    let isUpperLeft = (dx * -0.7 + dy * -0.7) > 0;

    // Radial crown facet edge
    brush.set("facet_edge", isUpperLeft ? "#ffccd6" : "#380108", isUpperLeft ? 0.42 : 0.35);
    brush.line(g0[0], g0[1], t0[0], t0[1]);

    // Table polygon perimeter edge
    brush.set("facet_edge", isUpperLeft ? "#ffe3e8" : "#5e0411", isUpperLeft ? 0.46 : 0.35);
    brush.line(t0[0], t0[1], t1[0], t1[1]);
  }

  // 6) CRISP STARBURST HIGHLIGHT on the upper-left crown/table junction!
  // Every aril gets a crisp starburst; its scale and ray length respond to local illumination
  let starX = tableCx - rAvg * 0.16;
  let starY = tableCy - rAvg * 0.16;
  let starScale = rAvg * (0.42 + 0.38 * lightFactor) * (0.85 + 0.3 * toneSeed);

  drawStarburstHighlight(starX, starY, starScale, lightFactor, toneSeed > 0.62);
}

function drawStarburstHighlight(x, y, rayLen, lightFactor, isHero) {
  resetBrush();
  // Soft rose-white specular halo beneath the starburst center
  brush.wash("#ffccd5", Math.round(135 * lightFactor));
  brush.circle(x, y, Math.max(1.8, rayLen * 0.24), 0.1);

  brush.wash("#ffffff", Math.round(225 * lightFactor));
  brush.circle(x, y, Math.max(1.1, rayLen * 0.13), 0.05);

  if (rayLen < 3.2) return;

  // Primary 4-point cross rays (slightly tilted at -8 deg for jeweller's optics)
  let baseTilt = -0.14;
  let mainAngles = [baseTilt, baseTilt + Math.PI * 0.5];
  for (let a of mainAngles) {
    let ca = Math.cos(a), sa = Math.sin(a);
    let rL = rayLen * (a === baseTilt ? 0.92 : 1.08);
    // Outer pink-white diffraction flare
    brush.set("facet_edge", "#ffd6de", 0.52);
    brush.line(x - ca * rL, y - sa * rL, x + ca * rL, y + sa * rL);
    // Razor-sharp pure white needle core
    brush.set("facet_edge", "#ffffff", isHero ? 0.65 : 0.48);
    brush.line(x - ca * rL * 0.72, y - sa * rL * 0.72, x + ca * rL * 0.72, y + sa * rL * 0.72);
  }

  // Secondary 45-degree diagonal starburst rays on brighter / hero cabochons
  if (isHero || rayLen > 6.5) {
    let diagLen = rayLen * 0.48;
    let diagAngles = [baseTilt + Math.PI * 0.25, baseTilt + Math.PI * 0.75];
    for (let a of diagAngles) {
      let ca = Math.cos(a), sa = Math.sin(a);
      brush.set("facet_edge", "#ffffff", 0.42);
      brush.line(x - ca * diagLen, y - sa * diagLen, x + ca * diagLen, y + sa * diagLen);
    }
  }
}

function renderAllChambersArils(septaData) {
  let { chambers, coreCx, coreCy } = septaData;

  for (let ch of chambers) {
    // 1) Deep blood-garnet cavernous chamber floor wash
    resetBrush();
    brush.wash("#170003", 250);
    drawShapePts(ch.poly, 0.25, true);

    // 2) Recessed dark pyrope-garnet background cabochons visible in the deep interstices
    let bgPts = packChamberArils(ch.poly, 21.0, ch.id * 19 + 7);
    for (let bg of bgPts) {
      resetBrush();
      brush.wash("#380107", 230);
      brush.circle(bg.cx, bg.cy, bg.rAvg * 0.85, 0.15);
      resetBrush();
      brush.wash("#610410", 180);
      brush.circle(bg.cx - 2, bg.cy - 2, bg.rAvg * 0.45, 0.1);
    }

    // 3) Pack and render the primary Faceted Cabochons of Garnet & Pigeon-Blood Red
    let arils = packChamberArils(ch.poly, 27.5, ch.id * 31 + 3);
    for (let aril of arils) {
      // Compute local illumination from upper-left spotlight + proximity to chamber rim shadow
      let dx = (aril.cx - 480) / 360;
      let dy = (aril.cy - 460) / 360;
      let spot = Math.max(0.48, Math.min(1.0, 1.04 - (dx * 0.28 + dy * 0.28)));
      let rimShade = Math.min(1.0, 0.58 + aril.edgeDist * 0.022);
      let lightFactor = spot * rimShade;

      drawFacetedAril(aril, lightFactor, false);
    }

    // 4) Selective translucent ruby watercolor glaze over the shadowed rim of each chamber for depth
    resetBrush();
    brush.fill("#4a020b", 32);
    brush.fillBleed(0.06, "in");
    drawShapePts(ch.poly, 0.25, true);
  }
}

function renderPearlMembraneOverhangsAndSeedPearls(geom, septaData) {
  let { outerRimPts, innerCavityPts, cutCx, cutCy, cutRx, cutRy, rot } = geom;
  let { coreCx, coreCy, septaAngles, chambers } = septaData;
  let cr = Math.cos(rot), sr = Math.sin(rot);

  // 1) Crisp sculpted Pale Pearl Septa Ridges & Translucent Nacre Veils partially overlapping edge arils
  for (let c = 0; c < septaAngles.length; c++) {
    let a = septaAngles[c];
    let leftEdge = [], rightEdge = [], centerSpine = [];
    let steps = 12;

    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let r = 20 + t * (cutRx * 0.87 - 20);
      let wAng = a + 0.035 * Math.sin(t * Math.PI * 2 + c);
      // Septum is wider at the core and at the outer cusp, thinner in the middle
      let halfW = (11 * (1 - t * 0.65) + 14 * Math.pow(t, 2.5)) / r;

      let lxL = Math.cos(wAng - halfW) * r;
      let lyL = Math.sin(wAng - halfW) * r * (cutRy / cutRx);
      leftEdge.push([
        coreCx * (1 - t) + cutCx * t + lxL * cr - lyL * sr,
        coreCy * (1 - t) + cutCy * t + lxL * sr + lyL * cr
      ]);

      let lxR = Math.cos(wAng + halfW) * r;
      let lyR = Math.sin(wAng + halfW) * r * (cutRy / cutRx);
      rightEdge.push([
        coreCx * (1 - t) + cutCx * t + lxR * cr - lyR * sr,
        coreCy * (1 - t) + cutCy * t + lxR * sr + lyR * cr
      ]);

      let lxC = Math.cos(wAng) * r;
      let lyC = Math.sin(wAng) * r * (cutRy / cutRx);
      centerSpine.push([
        coreCx * (1 - t) + cutCx * t + lxC * cr - lyC * sr,
        coreCy * (1 - t) + cutCy * t + lxC * sr + lyC * cr,
        1.2 - t * 0.3
      ]);
    }

    let septumPoly = leftEdge.concat(rightEdge.reverse());

    // Semi-translucent rosy-pearl overhang where thin septum tissue veils the edges of adjacent arils
    resetBrush();
    brush.wash("#e3bac4", 130);
    drawShapePts(septumPoly, 0.3, true);

    // Opaque creamy mother-of-pearl septum crest
    resetBrush();
    brush.set("marker", "#e8edf5", 1.15);
    brush.spline(centerSpine, 0.35);

    brush.set("2H", "#ffffff", 0.85);
    brush.spline(centerSpine, 0.35);
  }

  // 2) Central Pale Pearl Columella Star-Core with tiny nestled seed pearls
  let coreStar = [];
  let nStar = 15;
  for (let i = 0; i < nStar; i++) {
    let a = (i / nStar) * Math.PI * 2 + rot;
    // Star points align with the 5 septa
    let r = 24 + 13 * Math.pow(Math.max(0, Math.cos((i / nStar) * Math.PI * 10)), 1.5);
    coreStar.push([coreCx + Math.cos(a) * r, coreCy + Math.sin(a) * r]);
  }
  resetBrush();
  brush.wash("#cdd7e8", 230);
  drawShapePts(coreStar, 0.35, true);

  resetBrush();
  brush.wash("#f2f5fa", 210);
  drawShapePts(makeEllipsePoly(coreCx - 4, coreCy - 4, 20, 18, 0, 18), 0.35, true);

  // Small cluster of 9 delicate seed pearls nestled in the central pearl columella
  for (let i = 0; i < 9; i++) {
    let a = (i / 9) * Math.PI * 2;
    let rad = i === 0 ? 0 : 10.5 + (i % 2) * 3.5;
    let px = coreCx + Math.cos(a) * rad;
    let py = coreCy + Math.sin(a) * rad;
    drawSeedPearl(px, py, i === 0 ? 5.2 : 3.8, a, 0.92);
  }

  // 3) CONTINUOUS NECKLACE OF SEED PEARLS DOTTED ALONG THE CUT EDGE
  // Compute arc length along outerRimPts and place graduated, touching/near-touching seed pearls
  let rimLen = outerRimPts.length;
  for (let i = 0; i < rimLen; i++) {
    let p = outerRimPts[i];
    let pIn = innerCavityPts[i];
    // Shift slightly inward onto the cut rim bezel
    let bx = p[0] * 0.86 + pIn[0] * 0.14;
    let by = p[1] * 0.86 + pIn[1] * 0.14;

    // Direction toward the interior garnet arils (for warm ruby bounce reflection on each pearl)
    let rubyAngle = Math.atan2(cutCy - by, cutCx - bx);

    // Illumination based on position around the rim (upper-left brightest, lower-right cooler)
    let dx = (bx - cutCx) / cutRx;
    let dy = (by - cutCy) / cutRy;
    let pearlLight = Math.max(0.38, Math.min(1.0, 0.78 - dx * 0.25 - dy * 0.25));

    // Graduated pearl radius (larger on the plush swells, slightly finer on the foreshortened left edge)
    let rPearl = 5.6 + 1.4 * Math.sin(i * 0.45) + (dx > -0.6 ? 0.8 : -0.6);
    drawSeedPearl(bx, by, rPearl, rubyAngle, pearlLight);
  }
}

function drawSeedPearl(x, y, r, rubyBounceAngle, lightFactor = 0.9) {
  resetBrush();
  // 1) Tiny dark setting shadow on the membrane / bezel
  brush.wash("#240812", 210);
  brush.circle(x + r * 0.22, y + r * 0.26, r * 1.04, 0.08);

  // 2) Spherical base in cool imperial-blue / silver-slate shadow
  let colShadow = lerpHex("#5e6d8a", "#8fa0bd", lightFactor);
  brush.wash(colShadow, 245);
  brush.circle(x, y, r, 0.06);

  // 3) Warm ruby-pink bounce reflection crescent on the side facing the garnet arils
  let rx = x + Math.cos(rubyBounceAngle) * r * 0.28;
  let ry = y + Math.sin(rubyBounceAngle) * r * 0.28;
  brush.wash("#e3788b", Math.round(165 * lightFactor));
  brush.circle(rx, ry, r * 0.68, 0.08);

  // 4) Creamy iridescent nacre body shifted toward upper-left spotlight
  let colNacre = lerpHex("#ced8e8", "#f2f5fa", lightFactor);
  brush.wash(colNacre, 240);
  brush.circle(x - r * 0.14, y - r * 0.14, r * 0.76, 0.06);

  // 5) Warm champagne-pearl orient halo around the upper-left dome
  brush.wash("#fff9eb", Math.round(210 * lightFactor));
  brush.circle(x - r * 0.24, y - r * 0.24, r * 0.46, 0.05);

  // 6) Crisp pinpoint specular highlight
  brush.set("rotring", "#ffffff", 0.65);
  brush.circle(x - r * 0.32, y - r * 0.32, Math.max(0.8, r * 0.18), 0.02);
}

