function drawKraftGround() {
  background("#9e9485");

  // Large subtle warm-grey kraft paper washes
  let patches = [
    [[0, 0], [1200, 0], [1200, 620], [0, 740]],
    [[0, 480], [1200, 380], [1200, 1200], [0, 1200]],
    [[120, 80], [980, 40], [1080, 780], [90, 860]]
  ];
  drawWorldPolyFill(patches[0], "#948979", 38, 0.25, 0.55);
  drawWorldPolyFill(patches[1], "#a69b8c", 32, 0.25, 0.5);
  drawWorldPolyFill(patches[2], "#8c8172", 28, 0.3, 0.6);

  // Horizontal kraft laid-lines and unbleached pulp grain
  for (let y = 6; y < 1200; y += 7.5) {
    let col = (y % 15 < 7.5) ? "#8d8273" : "#aba090";
    brush.set("2H", col, random(0.22, 0.38));
    let x = 0;
    while (x < 1200) {
      let segLen = random(90, 260);
      let x2 = Math.min(1200, x + segLen);
      let dy = random(-1.5, 1.5);
      brush.line(x, y + dy, x2, y - dy);
      x = x2 + random(8, 35);
    }
  }

  // Wood-pulp flecks & short raw kraft fibers across the sheet
  for (let i = 0; i < 420; i++) {
    let fx = random(15, 1185);
    let fy = random(15, 1185);
    let ang = random(360);
    let flen = random(3, 14);
    let fcol = random(["#6e6456", "#7a7062", "#b8ad9d", "#595044"]);
    brush.set("cpencil", fcol, random(0.2, 0.45));
    brush.line(fx, fy, fx + cos(ang) * flen, fy + sin(ang) * flen);
  }

  // Subtle physical kraft fold crease running horizontally at y ~ 835
  // (accentuating the stark empty bottom third of the top-heavy composition)
  brush.set("2H", "#7c7264", 0.38);
  brush.line(0, 842, 1200, 818);
  brush.set("cpencil", "#b5aa9a", 0.32);
  brush.line(0, 845, 1200, 821);

  // Raw studio registration / crop marks on the kraft ground
  let regMarks = [[82, 745], [1115, 685], [310, 960], [925, 1020]];
  for (let [rx, ry] of regMarks) {
    brush.set("2H", "#665d50", 0.32);
    brush.line(rx - 14, ry, rx + 14, ry);
    brush.line(rx, ry - 14, rx, ry + 14);
    brush.circle(rx, ry, 7, 0.15);
  }
}

// ============================================================================
// LAYER 2: THE FLAT VERMILION DISC SLAPPED ACROSS THE MIDDLE
// ============================================================================

function drawVermilionDisc(cx, cy, r) {
  let pts = [];
  let steps = 72;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let rad = r + (noise(410 + cos(a) * 1.8, 410 + sin(a) * 1.8) - 0.5) * 4.5;
    pts.push([cx + cos(a) * rad, cy + sin(a) * rad]);
  }

  // Subtle slight edge shadow under the pasted/slapped disc
  let shPts = pts.map(p => [p[0] + 4, p[1] + 5]);
  drawWorldPolyWash(shPts, "#332922", 65);

  // Flat, confrontational opaque vermilion disc
  drawWorldPolyWash(pts, "#de351c", 252);
  drawWorldPolyMass(pts, "marker", "#d93118", { precision: 0.92, strength: 0.85, outline: true });
  drawWorldPolyWash(pts, "#e3391f", 160);

  // Crisp flat gouache/matte-paper rim
  brush.set("marker", "#c92b14", 0.55);
  for (let i = 0; i < pts.length; i++) {
    let p1 = pts[i], p2 = pts[(i + 1) % pts.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

