// Stencil glyph helper: draws military/industrial stencil characters with stencil bridges
function drawStencilChar(frag, ch, x, y, w, h, col) {
  let rects = [];
  let g = h * 0.08; // Stencil bridge gap
  let t = w * 0.24; // Stroke thickness

  if (ch === "S") {
    rects.push([x, y, w, t], [x, y + t + g * 0.5, t, h * 0.42 - t],
               [x, y + h * 0.43, w, t],
               [x + w - t, y + h * 0.43 + t + g * 0.5, t, h * 0.57 - 2 * t],
               [x, y + h - t, w, t]);
  } else if (ch === "E") {
    rects.push([x, y, t, h],
               [x + t + g, y, w - t - g, t],
               [x + t + g, y + h * 0.44, (w - t - g) * 0.78, t],
               [x + t + g, y + h - t, w - t - g, t]);
  } else if (ch === "K") {
    rects.push([x, y, t, h]);
    // Diagonal upper and lower stencil arms
    let arm1 = [[x + t + g, y + h * 0.46], [x + w - t * 0.3, y], [x + w, y + t * 0.7], [x + t + g, y + h * 0.56]];
    let arm2 = [[x + t + g * 1.4, y + h * 0.52], [x + w, y + h - t * 0.3], [x + w - t * 0.85, y + h], [x + t + g, y + h * 0.62]];
    fillStencilPoly(frag, arm1, col);
    fillStencilPoly(frag, arm2, col);
  } else if (ch === "T") {
    rects.push([x, y, w * 0.44, t], [x + w * 0.56, y, w * 0.44, t],
               [x + (w - t) * 0.5, y + t + g * 0.6, t, h - t - g * 0.6]);
  } else if (ch === "N") {
    rects.push([x, y, t, h], [x + w - t, y, t, h]);
    let diag = [[x + t + g * 0.5, y + g], [x + t * 1.85, y + g],
                [x + w - t - g * 0.5, y + h - g], [x + w - t * 1.85, y + h - g]];
    fillStencilPoly(frag, diag, col);
  } else if (ch === "O" || ch === "0") {
    rects.push([x, y + g, t, h - 2 * g],
               [x + w - t, y + g, t, h - 2 * g],
               [x + t * 0.5, y, w - t, t],
               [x + t * 0.5, y + h - t, w - t, t]);
  } else if (ch === "9") {
    rects.push([x, y + g, t, h * 0.52 - g],
               [x + w - t, y + g, t, h - 2 * g],
               [x + t * 0.4, y, w - t * 0.8, t],
               [x + t * 0.4, y + h * 0.46, w - t * 1.4, t],
               [x + t * 0.4, y + h - t, w - t * 0.8, t]);
  } else if (ch === "4") {
    rects.push([x, y, t, h * 0.58],
               [x + t + g, y + h * 0.5, w - t - g, t],
               [x + w - t * 1.3, y + g, t, h - g]);
  } else if (ch === "2") {
    rects.push([x, y, w, t],
               [x + w - t, y + t + g * 0.5, t, h * 0.42 - t],
               [x, y + h * 0.44, w, t],
               [x, y + h * 0.44 + t + g * 0.5, t, h * 0.56 - 2 * t],
               [x + t + g, y + h - t, w - t - g, t]);
  } else if (ch === "R") {
    rects.push([x, y, t, h],
               [x + t + g, y, w - t - g, t],
               [x + w - t, y + t + g * 0.4, t, h * 0.44 - t],
               [x + t + g, y + h * 0.44, w - t - g, t]);
    let leg = [[x + t * 1.3 + g, y + h * 0.54], [x + t * 2.2 + g, y + h * 0.54],
               [x + w, y + h], [x + w - t * 1.05, y + h]];
    fillStencilPoly(frag, leg, col);
  } else if (ch === "A") {
    let L = [[x + w * 0.36, y], [x + w * 0.48, y], [x + t, y + h], [x, y + h]];
    let R = [[x + w * 0.54, y], [x + w * 0.66, y], [x + w, y + h], [x + w - t, y + h]];
    fillStencilPoly(frag, L, col);
    fillStencilPoly(frag, R, col);
    rects.push([x + w * 0.25, y + h * 0.58, w * 0.5, t]);
  } else if (ch === "F") {
    rects.push([x, y, t, h],
               [x + t + g, y, w - t - g, t],
               [x + t + g, y + h * 0.45, (w - t - g) * 0.78, t]);
  }

  for (let r of rects) {
    let rx = r[0], ry = r[1], rw = r[2], rh = r[3];
    let poly = [[rx, ry], [rx + rw, ry], [rx + rw, ry + rh], [rx, ry + rh]];
    fillStencilPoly(frag, poly, col);
  }
}

function fillStencilPoly(frag, poly, col) {
  frag.washPoly(poly, col, 235);
  frag.hatchRegion(poly, 2.6, 25, "marker", col, 0.42, 0.2);
  // Stencil stipple/bleed along perimeter
  for (let i = 0; i < poly.length; i++) {
    let p1 = poly[i], p2 = poly[(i + 1) % poly.length];
    frag.line(p1[0], p1[1], p2[0], p2[1], "rotring", col, 0.45);
  }
}

