// ============================================================================
// FRAGMENT 2: HALF A POCKET WATCH WITH MOVEMENT EXPOSED (Upper Right, +20 deg)
// ============================================================================

function drawHalfPocketWatch() {
  // Left tear edge rips vertically down lx ~ -18, slicing the pocket watch in half!
  let base = [
    [-18, -225],
    [215, -215],
    [225, 200],
    [-12, 215]
  ];
  let frag = new TornFragment(820, 255, 20, base, [15, 14, 15, 18], 702);
  frag.drawPaperBase("#e4ded2", 88, "#d1cabd");

  let wcx = -16, wcy = 20; // Center of the pocket watch sits right on the jagged left tear!
  let outerR = 178;

  // 1. Dark studio backdrop outside the watch case
  let bgCorners = [
    [[75, -220], [220, -220], [220, -40], [140, -110]],
    [[145, 115], [220, 50], [220, 210], [65, 210]]
  ];
  for (let c of bgCorners) {
    frag.washPoly(c, "#211d1a", 220);
    frag.hatchRegion(c, 3.5, 45, "2B", "#161311", 0.48, 0.25);
    frag.hatchRegion(c, 4.0, -45, "HB", "#1f1b18", 0.4, 0.25);
  }

  // 2. CROWN, PENDANT NECK & BOW RING AT TOP OF WATCH (y = -220..-155)
  // Elliptical watch bow sweeping out to the right
  for (let rOff = -7; rOff <= 7; rOff += 1.6) {
    let bowPts = [];
    for (let a = -95; a <= 105; a += 10) {
      let bx = wcx + 8 + cos(a) * (66 + rOff);
      let by = wcy - 196 + sin(a) * (36 + rOff * 0.75);
      bowPts.push([bx, by]);
    }
    let isSpec = Math.abs(rOff + 2.2) < 1.8;
    let isCore = Math.abs(rOff - 3.5) < 2.0;
    let col = isSpec ? "#ffffff" : (isCore ? "#12100e" : "#6e665c");
    let br = isSpec ? "cpencil" : (isCore ? "rotring" : "2H");
    frag.spline(bowPts, br, col, isSpec ? 0.5 : 0.38, 0.5);
  }

  // Ornate chalice pendant neck (y = -182..-156)
  let pendantPoly = [[wcx - 10, wcy - 184], [wcx + 28, wcy - 184], [wcx + 34, wcy - 156], [wcx - 10, wcy - 156]];
  frag.washPoly(pendantPoly, "#595147", 220);
  frag.washPoly([[wcx + 2, wcy - 184], [wcx + 14, wcy - 184], [wcx + 16, wcy - 156], [wcx + 2, wcy - 156]], "#f5f0e6", 220);
  frag.washPoly([[wcx + 18, wcy - 184], [wcx + 30, wcy - 184], [wcx + 32, wcy - 156], [wcx + 18, wcy - 156]], "#171412", 230);

  // Knurled Winding Crown (y = -212..-184)
  let crownBox = [[wcx - 12, wcy - 212], [wcx + 40, wcy - 212], [wcx + 36, wcy - 184], [wcx - 12, wcy - 184]];
  frag.washPoly(crownBox, "#3b352f", 235);
  for (let kx = wcx - 8; kx <= wcx + 38; kx += 4.2) {
    frag.line(kx, wcy - 211, kx - 1, wcy - 185, "rotring", "#12100e", 0.48);
    frag.line(kx + 1.8, wcy - 211, kx + 0.8, wcy - 185, "cpencil", "#faf6ed", 0.42);
  }

  // 3. STEPPED METALLIC WATCH CASE BEZEL (r = 146 to 178)
  // Base metallic ring
  let caseOuterPts = [];
  for (let a = -105; a <= 105; a += 5) {
    caseOuterPts.push([wcx + cos(a) * outerR, wcy + sin(a) * outerR]);
  }
  frag.washPoly([[wcx - 15, wcy - outerR], ...caseOuterPts, [wcx - 15, wcy + outerR]], "#6e675d", 220);

  // Concentric high-contrast metallic case grooves & specular bands
  let ringSpecs = [
    { r: 177, col: "#12100e", br: "rotring", w: 0.55 },
    { r: 173, col: "#f7f3e9", br: "cpencil", w: 0.52 },
    { r: 169, col: "#ffffff", br: "cpencil", w: 0.55 },
    { r: 164, col: "#26221e", br: "2B", w: 0.48 },
    { r: 159, col: "#8c8376", br: "2H", w: 0.42 },
    { r: 154, col: "#141210", br: "rotring", w: 0.52 },
    { r: 150, col: "#fffdf7", br: "cpencil", w: 0.5 },
    { r: 146, col: "#12100e", br: "rotring", w: 0.58 }
  ];
  for (let rs of ringSpecs) {
    let pts = [];
    for (let a = -102; a <= 102; a += 4) {
      pts.push([wcx + cos(a) * rs.r, wcy + sin(a) * rs.r]);
    }
    frag.spline(pts, rs.br, rs.col, rs.w, 0.5);
  }
  // Radial metallic reflection blocks on the bezel
  for (let a = -88; a <= 88; a += 2.2) {
    let isDarkBand = (a > -45 && a < -15) || (a > 35 && a < 68);
    let isBrightBand = (a >= -15 && a <= 12);
    if (isDarkBand || isBrightBand) {
      let col = isBrightBand ? "#ffffff" : "#181512";
      let br = isBrightBand ? "cpencil" : "2B";
      frag.line(wcx + cos(a) * 147, wcy + sin(a) * 147,
                wcx + cos(a) * 176, wcy + sin(a) * 176, br, col, 0.42);
    }
  }

  // 4. RECESSED MOVEMENT WELL & DAMASKEENED MAINPLATE (r < 145)
  let wellPts = [[wcx - 15, wcy - 145]];
  for (let a = -100; a <= 100; a += 5) {
    wellPts.push([wcx + cos(a) * 145, wcy + sin(a) * 145]);
  }
  wellPts.push([wcx - 15, wcy + 145]);
  frag.washPoly(wellPts, "#231f1b", 242);
  frag.hatchRegion(wellPts, 3.4, 30, "2B", "#161311", 0.45, 0.2);

  // Circular perlage / damaskeening arcs on the recessed mainplate
  for (let py = -125; py <= 125; py += 18) {
    for (let px = -5; px <= 125; px += 18) {
      if (Math.hypot(px - wcx, py - wcy) < 132) {
        let arcPts = [];
        for (let a = -70; a <= 110; a += 30) {
          arcPts.push([px + cos(a) * 9, py + sin(a) * 9]);
        }
        frag.spline(arcPts, "2H", "#453e37", 0.28, 0.5);
      }
    }
  }

  // 5. EXPOSED HOROLOGICAL MOVEMENT (Gears, Mainspring, Balance Wheel, Bridges)
  // Helper to draw a precision horological gear wheel in local space
  function drawGearWheel(gx, gy, r, numTeeth, numSpokes, rimCol, highlightCol) {
    // Drop shadow under gear
    let shPts = [];
    for (let a = 0; a < 360; a += 15) shPts.push([gx + 4 + cos(a) * (r + 3), gy + 5 + sin(a) * (r + 3)]);
    frag.washPoly(shPts, "#0d0b0a", 210);

    // Gear rim body
    let rimPts = [];
    for (let a = 0; a < 360; a += 10) rimPts.push([gx + cos(a) * r, gy + sin(a) * r]);
    frag.washPoly(rimPts, rimCol, 235);

    // Cut out windows between spokes (showing dark mainplate beneath)
    if (numSpokes > 0) {
      let innerR = r * 0.26;
      let outerRimR = r * 0.78;
      let sectorSpan = 360 / numSpokes;
      for (let s = 0; s < numSpokes; s++) {
        let a1 = s * sectorSpan + 11;
        let a2 = (s + 1) * sectorSpan - 11;
        let winPts = [
          [gx + cos(a1) * innerR, gy + sin(a1) * innerR],
          [gx + cos(a1) * outerRimR, gy + sin(a1) * outerRimR],
          [gx + cos(0.5 * (a1 + a2)) * outerRimR, gy + sin(0.5 * (a1 + a2)) * outerRimR],
          [gx + cos(a2) * outerRimR, gy + sin(a2) * outerRimR],
          [gx + cos(a2) * innerR, gy + sin(a2) * innerR]
        ];
        frag.washPoly(winPts, "#181512", 242);
        frag.hatchRegion(winPts, 2.5, 45, "2B", "#100e0c", 0.4, 0.1);
        // Chamfer highlight along spoke edges
        frag.line(gx + cos(a1) * innerR, gy + sin(a1) * innerR,
                  gx + cos(a1) * outerRimR, gy + sin(a1) * outerRimR, "cpencil", highlightCol, 0.38);
        frag.line(gx + cos(a2) * innerR, gy + sin(a2) * innerR,
                  gx + cos(a2) * outerRimR, gy + sin(a2) * outerRimR, "rotring", "#12100e", 0.4);
      }
    }

    // Precision Involute Gear Teeth around circumference
    let stepA = 360 / numTeeth;
    for (let i = 0; i < numTeeth; i++) {
      let a = i * stepA;
      let tx1 = gx + cos(a - stepA * 0.22) * r;
      let ty1 = gy + sin(a - stepA * 0.22) * r;
      let tx2 = gx + cos(a) * (r + 5.5);
      let ty2 = gy + sin(a) * (r + 5.5);
      let tx3 = gx + cos(a + stepA * 0.22) * r;
      let ty3 = gy + sin(a + stepA * 0.22) * r;
      frag.line(tx1, ty1, tx2, ty2, "cpencil", highlightCol, 0.36);
      frag.line(tx2, ty2, tx3, ty3, "rotring", "#12100e", 0.42);
    }

    // Concentric rim highlights & dark jewel/arbor pivot at center
    let cPts = [];
    for (let a = 0; a <= 360; a += 12) cPts.push([gx + cos(a) * (r * 0.88), gy + sin(a) * (r * 0.88)]);
    frag.spline(cPts, "cpencil", highlightCol, 0.44, 0.5);
    let hubPts = [];
    for (let a = 0; a < 360; a += 30) hubPts.push([gx + cos(a) * (r * 0.16), gy + sin(a) * (r * 0.16)]);
    frag.washPoly(hubPts, "#141210", 250);
    frag.line(gx - r * 0.14, gy - 2, gx + r * 0.14, gy + 2, "cpencil", "#ffffff", 0.45);
  }

  // A. Torn Mainspring Barrel at upper-left (lx = -6, ly = -52) showing coiled steel mainspring!
  drawGearWheel(wcx + 10, wcy - 68, 44, 42, 0, "#756d61", "#ded7c8");
  for (let sr = 8; sr <= 36; sr += 3.6) {
    let coilPts = [];
    for (let a = -95; a <= 115; a += 12) {
      coilPts.push([wcx + 10 + cos(a) * sr, wcy - 68 + sin(a) * sr]);
    }
    frag.spline(coilPts, "rotring", "#12100e", 0.48, 0.5);
    let hiPts = coilPts.map(p => [p[0] + 1.2, p[1] - 0.8]);
    frag.spline(hiPts, "cpencil", "#d8d0c2", 0.32, 0.5);
  }

  // B. Great / Center Wheel at (lx = 18, ly = 14)
  drawGearWheel(wcx + 34, wcy - 6, 52, 48, 5, "#9c9283", "#fffdf7");

  // C. Third & Fourth Wheels meshing on the right and lower-center
  drawGearWheel(wcx + 88, wcy + 26, 34, 36, 4, "#857c6e", "#f2ece0");
  drawGearWheel(wcx + 32, wcy + 78, 38, 40, 5, "#968c7d", "#faf6ed");

  // D. Balance Wheel with Timing Screws & Hairspring Spiral at (wcx + 76, wcy - 64)
  let bx = wcx + 76, by = wcy - 64, brR = 38;
  drawGearWheel(bx, by, brR, 24, 2, "#aba192", "#ffffff");
  // Delicate concentric hairspring spiral inside the balance wheel
  let spiralPts = [];
  for (let a = 0; a <= 360 * 4.5; a += 18) {
    let sr = 3 + (a / (360 * 4.5)) * 18;
    spiralPts.push([bx + cos(a) * sr, by + sin(a) * sr]);
  }
  frag.spline(spiralPts, "rotring", "#12100e", 0.34, 0.5);

  // E. Engraved Balance Cock & Train Bridge (with Geneva Stripes, bevels, and slotted screws)
  let bridgePoly = [
    [wcx + 2, wcy + 42], [wcx + 82, wcy + 34], [wcx + 112, wcy + 62],
    [wcx + 92, wcy + 108], [wcx + 22, wcy + 116], [wcx - 8, wcy + 88]
  ];
  let bridgeSh = bridgePoly.map(p => [p[0] + 4, p[1] + 6]);
  frag.washPoly(bridgeSh, "#0d0b0a", 220);
  frag.washPoly(bridgePoly, "#b8afa0", 238);
  // Côtes de Genève (parallel satin stripes across the bridge)
  frag.hatchRegion(bridgePoly, 3.2, -25, "2H", "#7d7468", 0.34, 0.1);
  frag.hatchRegion([[wcx + 15, wcy + 42], [wcx + 65, wcy + 38], [wcx + 55, wcy + 110], [wcx + 10, wcy + 110]],
                   2.8, -25, "cpencil", "#f7f3e8", 0.38, 0.1);
  // Crisp chamfered steel edge around bridge
  for (let i = 0; i < bridgePoly.length; i++) {
    let p1 = bridgePoly[i], p2 = bridgePoly[(i + 1) % bridgePoly.length];
    frag.line(p1[0], p1[1], p2[0], p2[1], "rotring", "#141210", 0.5);
    frag.line(p1[0] - 1.5, p1[1] - 1.5, p2[0] - 1.5, p2[1] - 1.5, "cpencil", "#ffffff", 0.45);
  }
  // Slotted steel screw heads & ruby jewel chatons on the bridge
  let screws = [[wcx + 18, wcy + 62, 9], [wcx + 84, wcy + 58, 9], [wcx + 48, wcy + 88, 7]];
  for (let [sx, sy, sr] of screws) {
    let sPts = [];
    for (let a = 0; a < 360; a += 24) sPts.push([sx + cos(a) * sr, sy + sin(a) * sr]);
    frag.washPoly(sPts, "#ded8ca", 245);
    frag.spline([...sPts, sPts[0]], "rotring", "#12100e", 0.45, 0.5);
    // Screw slot
    frag.line(sx - sr * 0.8, sy - sr * 0.4, sx + sr * 0.8, sy + sr * 0.4, "rotring", "#0d0b0a", 0.6);
    frag.line(sx - sr * 0.8, sy - sr * 0.4 + 1.5, sx + sr * 0.8, sy + sr * 0.4 + 1.5, "cpencil", "#ffffff", 0.42);
  }

  // 6. BROKEN PORCELAIN ENAMEL DIAL SHARD WITH ROMAN NUMERALS (r = 104 to 145, right rim)
  // Upper-right and lower-right surviving porcelain dial shard (jaggedly broken inward!)
  let dialPoly = [];
  for (let a = -68; a <= 76; a += 5) {
    dialPoly.push([wcx + cos(a) * 144, wcy + sin(a) * 144]);
  }
  let innerBreak = [
    [wcx + cos(76) * 102, wcy + sin(76) * 102],
    [wcx + 88, wcy + 72],
    [wcx + 108, wcy + 36],
    [wcx + 96, wcy + 2],
    [wcx + 112, wcy - 28],
    [wcx + 92, wcy - 62],
    [wcx + cos(-68) * 104, wcy + sin(-68) * 104]
  ];
  let fullDialShard = [...dialPoly, ...innerBreak];
  // Cast shadow of the broken porcelain dial shard onto the gears below
  let dialShadow = fullDialShard.map(p => [p[0] - 5, p[1] + 6]);
  frag.washPoly(dialShadow, "#0d0b0a", 215);

  // Porcelain white enamel surface
  frag.washPoly(fullDialShard, "#f5f1e6", 248);
  frag.hatchRegion(fullDialShard, 4.5, 15, "2H", "#dcd4c5", 0.26, 0.1);
  // Jagged broken porcelain inner edge & hairline cracks
  frag.spline(innerBreak, "rotring", "#24201c", 0.48, 0.15);
  frag.line(wcx + 96, wcy + 2, wcx + 138, wcy + 8, "2H", "#6e655a", 0.32);
  frag.line(wcx + 108, wcy + 36, wcx + 132, wcy + 52, "2H", "#6e655a", 0.3);

  // Outer Railway Minute Track on the porcelain dial
  for (let a = -64; a <= 72; a += 6) {
    let r1 = (a % 30 === 0) ? 131 : 134;
    let r2 = 141;
    let w = (a % 30 === 0) ? 0.55 : 0.35;
    frag.line(wcx + cos(a) * r1, wcy + sin(a) * r1,
              wcx + cos(a) * r2, wcy + sin(a) * r2, "rotring", "#141210", w);
  }
  // Bold Roman Numerals at II (-30 deg), III (0 deg), IV (+30 deg)
  let numerals = [
    { a: -30, strokes: [[-3, -8, -3, 8], [3, -8, 3, 8], [-5, -8, 5, -8], [-5, 8, 5, 8]] },
    { a: 0,   strokes: [[-5, -8, -5, 8], [0, -8, 0, 8], [5, -8, 5, 8], [-7, -8, 7, -8], [-7, 8, 7, 8]] },
    { a: 30,  strokes: [[-6, -8, -6, 8], [-1, -8, 3, 8], [3, 8, 7, -8], [-8, -8, 8, -8], [-8, 8, 8, 8]] }
  ];
  for (let num of numerals) {
    let ncx = wcx + cos(num.a) * 118;
    let ncy = wcy + sin(num.a) * 118;
    let ca = cos(num.a + 90), sa = sin(num.a + 90);
    for (let st of num.strokes) {
      let x1 = ncx + st[0] * ca - st[1] * sa;
      let y1 = ncy + st[0] * sa + st[1] * ca;
      let x2 = ncx + st[2] * ca - st[3] * sa;
      let y2 = ncy + st[2] * sa + st[3] * ca;
      frag.line(x1, y1, x2, y2, "rotring", "#141210", 0.52);
    }
  }

  // Torn Bent Blued-Steel Watch Hand pointing across the movement toward II
  let handPoly = [
    [wcx - 8, wcy - 2], [wcx + 52, wcy - 34], [wcx + 88, wcy - 48],
    [wcx + 54, wcy - 24], [wcx - 6, wcy + 5]
  ];
  frag.washPoly(handPoly.map(p => [p[0] + 3, p[1] + 5]), "#0a0908", 200);
  frag.washPoly(handPoly, "#141210", 248);
  frag.line(wcx - 6, wcy, wcx + 84, wcy - 46, "cpencil", "#e8e2d5", 0.38);
}

// ============================================================================
// FRAGMENT 3: THE GRINNING MOUTH WITH ONE GOLD CROWN (Center, +6 deg)
// ============================================================================

function drawGrinningMouth() {
  // Wide, confrontational cutout torn closely around a taut human grin
  let base = [
    [-218, -92],
    [-85, -142],
    [95, -142],
    [225, -88],
    [232, 78],
    [115, 138],
    [-110, 138],
    [-228, 72]
  ];
  let frag = new TornFragment(512, 505, 6, base, [13, 15, 14, 15, 14, 15, 14, 13], 803);
  frag.drawPaperBase("#e6dfd2", 92, "#cfc6b6");

  // 1. PERIORAL SKIN, PHILTRUM, NASOLABIAL FOLDS & CHIN CREASE
  // Deep shadow under the nose / nostrils at top center (y < -105)
  let noseShadow = [[-68, -145], [68, -145], [52, -108], [0, -98], [-52, -108]];
  frag.washPoly(noseShadow, "#2e2823", 210);
  frag.hatchRegion(noseShadow, 3.0, 25, "2B", "#1a1714", 0.45, 0.2);

  // Philtrum dimple (central vertical hollow above Cupid's bow, x = -18..+18, y = -108..-62)
  let philtrumHollow = [[-16, -108], [16, -108], [20, -64], [0, -58], [-20, -64]];
  frag.washPoly(philtrumHollow, "#7a7062", 165);
  frag.hatchRegion(philtrumHollow, 3.0, 88, "HB", "#4f473e", 0.36, 0.2);
  // Illuminated philtral columns flanking the dimple
  frag.washPoly([[-30, -106], [-15, -106], [-18, -60], [-34, -64]], "#f2ece0", 190);
  frag.washPoly([[15, -106], [30, -106], [34, -64], [18, -60]], "#f2ece0", 190);
  frag.line(-22, -104, -25, -62, "cpencil", "#ffffff", 0.48);
  frag.line(22, -104, 25, -62, "cpencil", "#ffffff", 0.48);

  // Deep Nasolabial Folds (laugh lines stretched wide on left & right)
  let leftFold = [[-125, -125], [-105, -125], [-168, -15], [-192, 68], [-155, 118],
                  [-182, 118], [-215, 62], [-195, -22]];
  let rightFold = [[105, -125], [125, -125], [195, -22], [215, 62], [182, 118],
                   [155, 118], [192, 68], [168, -15]];
  frag.washPoly(leftFold, "#4a4239", 185);
  frag.washPoly(rightFold, "#4a4239", 185);
  frag.hatchRegion(leftFold, 3.2, 62, "2B", "#26211c", 0.42, 0.25);
  frag.hatchRegion(rightFold, 3.2, -62, "2B", "#26211c", 0.42, 0.25);
  frag.spline([[-115, -122], [-178, -18], [-202, 58], [-168, 112]], "2B", "#1c1815", 0.48, 0.5);
  frag.spline([[115, -122], [178, -18], [202, 58], [168, 112]], "2B", "#1c1815", 0.48, 0.5);
  // Bright cheek pillows just outside the nasolabial folds
  frag.spline([[-122, -118], [-186, -16], [-210, 56]], "cpencil", "#f7f3e8", 0.45, 0.5);
  frag.spline([[122, -118], [186, -16], [210, 56]], "cpencil", "#f7f3e8", 0.45, 0.5);

  // Mentolabial Sulcus (deep shadow crease under the lower lip, y = 82..118)
  let chinCrease = [[-118, 76], [0, 88], [118, 76], [92, 116], [0, 122], [-92, 116]];
  frag.washPoly(chinCrease, "#453d35", 190);
  frag.hatchRegion(chinCrease, 3.2, 12, "2B", "#29241e", 0.4, 0.25);
  frag.hatchRegion(chinCrease, 3.6, -22, "HB", "#362f28", 0.36, 0.25);

  // Subtle stubble & skin pores across upper lip skin and chin
  for (let i = 0; i < 160; i++) {
    let sx = random(-175, 175);
    let sy = random() < 0.55 ? random(-105, -62) : random(82, 132);
    frag.line(sx, sy, sx + random(-1.5, 1.5), sy + random(2, 4.5), "2H", "#4a423a", 0.3);
  }

  // 2. DARK ORAL CAVITY & GUMS (Gingiva)
  let mouthInterior = [
    [-176, -2], [-135, -36], [-65, -48], [0, -48], [65, -48], [135, -36], [176, -2],
    [138, 38], [68, 52], [0, 54], [-68, 52], [-138, 38]
  ];
  frag.washPoly(mouthInterior, "#12100e", 252);
  frag.hatchRegion(mouthInterior, 2.5, 5, "charcoal", "#0a0908", 0.55, 0.15);

  // Upper Gingiva (gums & interdental papillae above upper teeth)
  let gumBand = [[-128, -42], [-65, -50], [0, -50], [65, -50], [128, -42],
                 [128, -24], [0, -28], [-128, -24]];
  frag.washPoly(gumBand, "#595046", 215);
  frag.hatchRegion(gumBand, 2.8, 15, "HB", "#38312b", 0.36, 0.15);

  // 3. LOWER DENTAL ARCH (partially shadowed beneath upper arch, y = +12..+48)
  let lowerTeeth = [
    { x1: -118, x2: -94, yTop: 10, yBot: 34 },
    { x1: -94,  x2: -70, yTop: 13, yBot: 40 },
    { x1: -70,  x2: -44, yTop: 14, yBot: 44 }, // Lower Right Canine
    { x1: -44,  x2: -22, yTop: 16, yBot: 46 }, // Lower Right Lateral
    { x1: -22,  x2: 0,   yTop: 17, yBot: 47 }, // Lower Right Central
    { x1: 0,    x2: 22,  yTop: 17, yBot: 47 }, // Lower Left Central
    { x1: 22,   x2: 44,  yTop: 16, yBot: 46 }, // Lower Left Lateral
    { x1: 44,   x2: 70,  yTop: 14, yBot: 44 }, // Lower Left Canine
    { x1: 70,   x2: 94,  yTop: 13, yBot: 40 },
    { x1: 94,   x2: 118, yTop: 10, yBot: 34 }
  ];
  for (let lt of lowerTeeth) {
    let xm = 0.5 * (lt.x1 + lt.x2);
    let tPoly = [
      [lt.x1 + 1.2, lt.yTop + 2], [xm, lt.yTop], [lt.x2 - 1.2, lt.yTop + 2],
      [lt.x2 - 2, lt.yBot - 3], [xm, lt.yBot], [lt.x1 + 2, lt.yBot - 3]
    ];
    let distFactor = Math.abs(xm) / 130;
    let baseCol = distFactor > 0.55 ? "#948b7d" : "#c7bfb0";
    frag.washPoly(tPoly, baseCol, 238);
    // Cast shadow from upper teeth across upper half of lower teeth
    let shSub = [[lt.x1 + 1, lt.yTop], [lt.x2 - 1, lt.yTop], [lt.x2 - 1, lt.yTop + 11], [lt.x1 + 1, lt.yTop + 11]];
    frag.washPoly(shSub, "#4d453c", 160);
    // Crisp bright incisal rim & vertical enamel highlight
    frag.line(lt.x1 + 2.5, lt.yTop + 1.5, lt.x2 - 2.5, lt.yTop + 1.5, "cpencil", "#f2ece0", 0.42);
    frag.line(xm, lt.yTop + 3, xm, lt.yBot - 4, "cpencil", "#e8e0d2", 0.36);
    // Dark interproximal separation
    frag.line(lt.x1, lt.yTop, lt.x1 + 1, lt.yBot, "rotring", "#141210", 0.45);
  }

  // 4. UPPER DENTAL ARCH + THE ONE GLEAMING GOLD CROWN!
  let upperTeeth = [
    { x1: -136, x2: -114, yGum: -26, yInc: -4,  isCanine: false, isGold: false }, // R 2nd Premolar
    { x1: -114, x2: -90,  yGum: -32, yInc: 0,   isCanine: false, isGold: false }, // R 1st Premolar
    { x1: -90,  x2: -62,  yGum: -39, yInc: 7,   isCanine: true,  isGold: false }, // R Canine
    { x1: -62,  x2: -34,  yGum: -37, yInc: 4,   isCanine: false, isGold: false }, // R Lateral Incisor
    { x1: -34,  x2: 0,    yGum: -41, yInc: 8,   isCanine: false, isGold: false }, // R Central Incisor
    { x1: 0,    x2: 34,   yGum: -41, yInc: 8,   isCanine: false, isGold: false }, // L Central Incisor
    { x1: 34,   x2: 64,   yGum: -38, yInc: 5,   isCanine: false, isGold: true  }, // L Lateral Incisor: GOLD CROWN!
    { x1: 64,   x2: 92,   yGum: -39, yInc: 7,   isCanine: true,  isGold: false }, // L Canine
    { x1: 92,   x2: 115,  yGum: -32, yInc: 0,   isCanine: false, isGold: false }, // L 1st Premolar
    { x1: 115,  x2: 136,  yGum: -26, yInc: -4,  isCanine: false, isGold: false }  // L 2nd Premolar
  ];

  for (let ut of upperTeeth) {
    let xm = 0.5 * (ut.x1 + ut.x2);
    let tw = ut.x2 - ut.x1;
    let tPoly = [
      [ut.x1 + 2.5, ut.yGum + 6],
      [xm - tw * 0.22, ut.yGum],
      [xm + tw * 0.22, ut.yGum],
      [ut.x2 - 2.5, ut.yGum + 6],
      [ut.x2 - 1.2, ut.yInc - (ut.isCanine ? 5 : 2)],
      [xm, ut.yInc + (ut.isCanine ? 2.5 : 0)],
      [ut.x1 + 1.2, ut.yInc - (ut.isCanine ? 5 : 2)]
    ];

    if (!ut.isGold) {
      // Natural hyperreal graphite tooth
      let edgeDarken = Math.abs(xm) / 145;
      let enamelCol = edgeDarken > 0.65 ? "#a89f90" : (edgeDarken > 0.38 ? "#cfc7b8" : "#ebe5d8");
      frag.washPoly(tPoly, enamelCol, 248);

      // Subtle cervical shading near gumline & lateral roll-off
      let cervPoly = [tPoly[0], tPoly[1], tPoly[2], tPoly[3],
                      [ut.x2 - 2, ut.yGum + 14], [ut.x1 + 2, ut.yGum + 14]];
      frag.washPoly(cervPoly, "#9c9283", 125);
      // Translucent grey-blue incisal edge zone
      let incPoly = [[ut.x1 + 2, ut.yInc - 7], [ut.x2 - 2, ut.yInc - 7], tPoly[4], tPoly[5], tPoly[6]];
      frag.washPoly(incPoly, "#b8afa0", 115);

      // Fine vertical enamel striations & labial lobe highlights
      for (let tx = ut.x1 + 3.5; tx <= ut.x2 - 3.5; tx += 3.2) {
        let isLobe = Math.abs(tx - (xm - tw * 0.16)) < 2.5 || Math.abs(tx - (xm + tw * 0.14)) < 2.2;
        frag.line(tx, ut.yGum + 5, tx, ut.yInc - 3,
                  isLobe ? "cpencil" : "2H",
                  isLobe ? "#ffffff" : "#968c7e",
                  isLobe ? 0.52 : 0.26);
      }
      // Wet horizontal specular bar across labial prominence
      frag.line(ut.x1 + 4, ut.yGum + (ut.yInc - ut.yGum) * 0.48,
                ut.x2 - 4, ut.yGum + (ut.yInc - ut.yGum) * 0.48, "cpencil", "#ffffff", 0.58);
    } else {
      // ======================================================================
      // THE GLEAMING HYPERREAL GOLD CROWN (x: 34..64)
      // ======================================================================
      // 1. Rich warm metallic gold base
      frag.washPoly(tPoly, "#d9a01b", 252);
      frag.washPoly(tPoly, "#e8b930", 190);

      // 2. Deep bronze-brown metallic core reflection (mirroring the dark mouth interior)
      let darkGoldCore = [
        [ut.x1 + 3, ut.yGum + 12], [xm + 4, ut.yGum + 9],
        [ut.x2 - 3, ut.yGum + 16], [ut.x2 - 4, ut.yInc - 7],
        [xm, ut.yInc - 5], [ut.x1 + 4, ut.yInc - 9]
      ];
      frag.washPoly(darkGoldCore, "#5e3e05", 225);
      frag.hatchRegion(darkGoldCore, 2.2, 85, "HB", "#422a02", 0.42, 0.1);

      // 3. Warm amber-gold transitional bevels at cervical & mesial/distal margins
      let cervicalGold = [tPoly[0], tPoly[1], tPoly[2], tPoly[3],
                          [ut.x2 - 3, ut.yGum + 13], [ut.x1 + 3, ut.yGum + 13]];
      frag.washPoly(cervicalGold, "#b87d0e", 215);
      let incisalGold = [[ut.x1 + 2, ut.yInc - 8], [ut.x2 - 2, ut.yInc - 8], tPoly[4], tPoly[5], tPoly[6]];
      frag.washPoly(incisalGold, "#f2c944", 235);

      // 4. Liquid-bright yellow-gold vertical reflection lobe & blinding white-gold hotspot!
      let brightGoldBand = [
        [xm - 7, ut.yGum + 4], [xm + 2, ut.yGum + 4],
        [xm + 3, ut.yInc - 2], [xm - 6, ut.yInc - 2]
      ];
      frag.washPoly(brightGoldBand, "#fae06b", 245);
      for (let gx = xm - 5; gx <= xm + 0.5; gx += 1.4) {
        frag.line(gx, ut.yGum + 5, gx + 0.5, ut.yInc - 3, "cpencil", "#fffce6", 0.52);
      }
      // Blinding pure white specular gleam right on the gold crown's labial ridge and incisal corner
      frag.line(xm - 3, ut.yGum + 8, xm - 2.5, ut.yInc - 5, "cpencil", "#ffffff", 0.68);
      frag.line(ut.x1 + 4.5, ut.yGum + 16, ut.x2 - 5, ut.yGum + 14, "cpencil", "#ffffff", 0.65);
      frag.line(ut.x1 + 4, ut.yInc - 2.5, ut.x2 - 4, ut.yInc - 2.5, "cpencil", "#fffef5", 0.58);

      // 5. Subtle warm golden bounce-light on adjacent Left Central Incisor & Left Canine
      frag.washPoly([[26, -34], [34, -34], [34, 4], [26, 4]], "#d9a01b", 65);
      frag.washPoly([[64, -34], [71, -34], [71, 4], [64, 4]], "#d9a01b", 60);
    }

    // Crisp scalloped dark gingival margin & interproximal shadow gaps around every tooth
    frag.spline([tPoly[0], tPoly[1], tPoly[2], tPoly[3]], "rotring", "#1a1613", 0.46, 0.4);
    frag.line(ut.x1, ut.yGum + 4, ut.x1 + 1.2, ut.yInc - 2, "rotring", "#12100e", 0.52);
    frag.line(ut.x2, ut.yGum + 4, ut.x2 - 1.2, ut.yInc - 2, "rotring", "#12100e", 0.52);
    frag.spline([tPoly[6], tPoly[5], tPoly[4]], "rotring", "#141210", 0.45, 0.3);
  }

  // 5. STRETCHED UPPER AND LOWER LIPS (with anatomical fissures & wet specular highlights)
  // A. Upper Lip (y = -68 to -36 at center, tapering to corners at (\pm 178, -2))
  let upperLipPoly = [
    [-180, -2], [-128, -48], [-64, -66], [-24, -72], [0, -64], [24, -72], [64, -66], [128, -48], [180, -2],
    [135, -34], [65, -45], [0, -42], [-65, -45], [-135, -34]
  ];
  frag.washPoly(upperLipPoly, "#594f45", 225);
  // Darker inward slope of upper lip right above the teeth
  let upperLipInner = [
    [-168, -6], [-125, -40], [-60, -54], [0, -50], [60, -54], [125, -40], [168, -6],
    [135, -34], [65, -45], [0, -42], [-65, -45], [-135, -34]
  ];
  frag.washPoly(upperLipInner, "#332c26", 215);

  // Curved radial contour strokes & lip creases across the upper lip
  for (let lx = -164; lx <= 164; lx += 3.4) {
    let t = Math.abs(lx) / 176;
    let cupidsDip = Math.exp(- (lx * lx) / 380) * 8;
    let yTop = -72 * (1 - t * t * 0.92) + cupidsDip;
    let yBot = -44 * (1 - t * t * 0.92) + cupidsDip * 0.35;
    let isCrease = (Math.round(lx / 3.4) % 4 === 0);
    let midX = lx * 0.985;
    let midY = 0.5 * (yTop + yBot) - 2;
    frag.spline([[lx, yTop], [midX, midY], [lx * 0.97, yBot]],
                isCrease ? "2B" : "HB",
                isCrease ? "#1c1815" : "#423a32",
                isCrease ? 0.44 : 0.34, 0.5);
    if (isCrease && Math.abs(lx) < 120) {
      frag.line(lx + 1.4, yTop + 3, midX + 1.4, midY + 2, "cpencil", "#dfd7c8", 0.35);
    }
  }
  // Bright White Roll highlight along Cupid's bow & upper vermilion border
  let cupidsBowRoll = [
    [-125, -49], [-64, -67], [-24, -74], [0, -65], [24, -74], [64, -67], [125, -49]
  ];
  frag.spline(cupidsBowRoll, "cpencil", "#ffffff", 0.56, 0.45);
  frag.spline(cupidsBowRoll.map(p => [p[0], p[1] - 2]), "cpencil", "#f5f0e5", 0.42, 0.45);

  // B. Lower Lip (full, taut, catching strong top light, y = +44..+88 at center)
  let lowerLipPoly = [
    [-180, -2], [-138, 36], [-68, 50], [0, 52], [68, 50], [138, 36], [180, -2],
    [136, 58], [72, 82], [0, 88], [-72, 82], [-136, 58]
  ];
  frag.washPoly(lowerLipPoly, "#8c8173", 220);

  // Shadowed lower roll of the lower lip (y = +70..+88)
  let lowerLipRoll = [
    [-145, 46], [-72, 68], [0, 72], [72, 68], [145, 46],
    [136, 58], [72, 82], [0, 88], [-72, 82], [-136, 58]
  ];
  frag.washPoly(lowerLipRoll, "#423a32", 210);

  // Bright illuminated pillow of the lower lip (y = +52..+70)
  let lowerLipPillow = [
    [-112, 44], [-58, 53], [0, 54], [58, 53], [112, 44],
    [98, 64], [48, 71], [0, 72], [-48, 71], [-98, 64]
  ];
  frag.washPoly(lowerLipPillow, "#dcd4c5", 195);

  // 3D curved vertical lip sulci (creases) & wet specular ridges across the lower lip
  for (let lx = -162; lx <= 162; lx += 3.6) {
    let t = Math.abs(lx) / 176;
    let yTop = 52 * (1 - t * t * 0.96);
    let yBot = 88 * (1 - t * t * 0.96);
    let bulgeX = lx * 1.03;
    let midY = yTop + (yBot - yTop) * 0.46;
    let isFissure = (Math.round(lx / 3.6) % 4 === 0);

    frag.spline([[lx, yTop], [bulgeX, midY], [lx * 0.99, yBot]],
                isFissure ? "rotring" : "HB",
                isFissure ? "#211d19" : "#6b6155",
                isFissure ? 0.44 : 0.32, 0.5);

    // Wet specular highlight pillows between the vertical lip fissures
    if (Math.abs(lx) < 115 && !isFissure) {
      frag.line(bulgeX, midY - 4, bulgeX, midY + 4, "cpencil", "#ffffff", 0.58);
    }
  }
  // Intense wet specular line across the crest of the lower lip
  for (let lx = -88; lx <= 88; lx += 14) {
    let t = Math.abs(lx) / 176;
    let cy = 62 * (1 - t * t * 0.9);
    frag.line(lx, cy, lx + 9, cy + 0.5, "cpencil", "#ffffff", 0.65);
  }

  // Deep shadow pits (oral commissures) at the far left & right corners of the grin
  frag.washPoly([[-186, -8], [-162, -12], [-156, 4], [-178, 10]], "#0f0d0b", 248);
  frag.washPoly([[162, -12], [186, -8], [178, 10], [156, 4]], "#0f0d0b", 248);
}

// ============================================================================
// FRAGMENT 4: A PAIR OF PLIERS (Mid-Right to Lower-Right, -35 deg)
// ============================================================================

function drawPliers() {
  // Elongated torn strip lunging diagonally upward-left toward the gold crown!
  let base = [
    [-238, -88],
    [-45, -102],
    [232, -98],
    [245, 95],
    [-42, 105],
    [-232, 92]
  ];
  let frag = new TornFragment(785, 748, -35, base, [14, 15, 13, 14, 15, 13], 904);
  frag.drawPaperBase("#e4ddd0", 90, "#cdc5b6");

  // 1. Moody dark studio photograph background & cast shadow beneath the pliers
  let studioBg = [[-232, -84], [228, -92], [238, 90], [-226, 86]];
  frag.washPoly(studioBg, "#3b352e", 185);
  frag.hatchRegion(studioBg, 4.0, 28, "HB", "#29241f", 0.38, 0.25);
  frag.hatchRegion(studioBg, 4.5, -52, "2H", "#332d27", 0.34, 0.25);

  // Heavy cast shadow of the pliers on the studio surface (offset (+8, +14))
  let shadowUpperJaw = [[-212, -38], [-125, -52], [-48, -14], [-52, 12], [-135, -18], [-208, -22]];
  let shadowLowerJaw = [[-206, 52], [-122, 68], [-48, 26], [-52, 4], [-132, 34], [-202, 36]];
  let shadowUpperHnd = [[-45, 2], [58, -48], [218, -34], [218, -12], [58, -24], [-45, 18]];
  let shadowLowerHnd = [[-45, 18], [58, 78], [214, 68], [214, 46], [58, 52], [-45, 4]];
  for (let sp of [shadowUpperJaw, shadowLowerJaw, shadowUpperHnd, shadowLowerHnd]) {
    frag.washPoly(sp, "#141210", 215);
  }

  // 2. FORGED STEEL HANDLES (Sweeping from pivot lx = -52 out to lx = +218)
  // Upper Handle
  let upperHandleC = [[-48, -6], [4, -38], [68, -56], [142, -52], [216, -40]];
  // Lower Handle
  let lowerHandleC = [[-48, 8], [4, 42], [68, 60], [142, 56], [212, 44]];

  function renderPlierHandle(centerCurve, halfW) {
    let topPts = [], botPts = [];
    for (let i = 0; i < centerCurve.length; i++) {
      let p = centerCurve[i];
      let pNext = centerCurve[Math.min(centerCurve.length - 1, i + 1)];
      let pPrev = centerCurve[Math.max(0, i - 1)];
      let dx = pNext[0] - pPrev[0], dy = pNext[1] - pPrev[1];
      let len = Math.hypot(dx, dy) || 1;
      let nx = dy / len, ny = -dx / len;
      topPts.push([p[0] + nx * halfW, p[1] + ny * halfW]);
      botPts.push([p[0] - nx * halfW, p[1] - ny * halfW]);
    }
    let handlePoly = [...topPts, ...botPts.slice().reverse()];
    frag.washPoly(handlePoly, "#665f56", 242);

    // Cylindrical steel banding along the handle
    for (let s = -halfW + 1.5; s <= halfW - 1.5; s += 1.8) {
      let cPts = [];
      for (let i = 0; i < centerCurve.length; i++) {
        let p = centerCurve[i];
        let pNext = centerCurve[Math.min(centerCurve.length - 1, i + 1)];
        let pPrev = centerCurve[Math.max(0, i - 1)];
        let dx = pNext[0] - pPrev[0], dy = pNext[1] - pPrev[1];
        let len = Math.hypot(dx, dy) || 1;
        let nx = dy / len, ny = -dx / len;
        cPts.push([p[0] + nx * s, p[1] + ny * s]);
      }
      let isSpec = (s > halfW * 0.22 && s < halfW * 0.58);
      let isCore = (s < -halfW * 0.15 && s > -halfW * 0.68);
      let col = isSpec ? "#ffffff" : (isCore ? "#141210" : "#8c8375");
      let br = isSpec ? "cpencil" : (isCore ? "2B" : "2H");
      frag.spline(cPts, br, col, isSpec ? 0.52 : 0.4, 0.5);
    }

    // Diamond Cross-Knurling Grip Texture along the handle (lx = +18 to +196)
    let knurlPoly = [
      topPts[1], topPts[2], topPts[3],
      [topPts[3][0] + 45, topPts[3][1] + 6],
      [botPts[3][0] + 45, botPts[3][1] + 6],
      botPts[3], botPts[2], botPts[1]
    ];
    frag.hatchRegion(knurlPoly, 4.2, 42, "rotring", "#171412", 0.38, 0.1);
    frag.hatchRegion(knurlPoly, 4.2, -42, "rotring", "#171412", 0.38, 0.1);
    frag.hatchRegion(knurlPoly, 8.4, 42, "cpencil", "#f2ece0", 0.32, 0.1);

    // Crisp forged steel outlines & rounded handle end cap
    frag.spline(topPts, "rotring", "#12100e", 0.5, 0.5);
    frag.spline(botPts, "rotring", "#12100e", 0.5, 0.5);
    let endT = topPts[topPts.length - 1], endB = botPts[botPts.length - 1];
    let endMid = [0.5 * (endT[0] + endB[0]) + 8, 0.5 * (endT[1] + endB[1])];
    frag.spline([endT, endMid, endB], "rotring", "#12100e", 0.52, 0.5);
    frag.spline([[endT[0] - 2, endT[1] + 2], [endMid[0] - 2, endMid[1]], [endB[0] - 2, endB[1] - 2]],
                "cpencil", "#ffffff", 0.48, 0.5);
  }

  renderPlierHandle(upperHandleC, 13.5);
  renderPlierHandle(lowerHandleC, 13.5);

  // 3. THE OPEN FORGED STEEL JAWS (lx = -212 to -52, menacingly parted!)
  // A. Upper Jaw
  let upperJawOuter = [[-52, -26], [-98, -58], [-156, -64], [-212, -52], [-212, -32]];
  let upperJawInner = [
    [-212, -32], [-158, -28], // Flat serrated nose
    [-144, -38], [-126, -38], [-114, -24], // Curved pipe-grip recess
    [-82, -16], [-56, -4] // Wire cutter bevel & throat
  ];
  let upperJawPoly = [...upperJawOuter, ...upperJawInner.slice(1)];
  frag.washPoly(upperJawPoly, "#82796c", 248);

  // Beveled top chamfer plane of the upper jaw (dark steel) & bright flat side face
  let upperChamfer = [[-52, -26], [-98, -58], [-156, -64], [-212, -52],
                      [-206, -44], [-152, -52], [-96, -44], [-54, -14]];
  frag.washPoly(upperChamfer, "#24201c", 235);
  frag.hatchRegion(upperChamfer, 2.8, -15, "2B", "#141210", 0.44, 0.15);

  let upperFlatFace = [[-206, -44], [-152, -52], [-96, -44], [-58, -14],
                       [-82, -16], [-114, -24], [-135, -36], [-158, -28], [-212, -32]];
  frag.washPoly(upperFlatFace, "#ded7c8", 235);
  // Brushed machined grinding lines across the flat steel face of the upper jaw
  frag.hatchRegion(upperFlatFace, 2.6, 68, "2H", "#8f8678", 0.32, 0.1);
  // Blinding specular reflection band along the upper jaw ridge
  frag.spline([[-206, -44], [-152, -51], [-96, -43], [-58, -14]], "cpencil", "#ffffff", 0.62, 0.4);
  frag.spline([[-204, -41], [-152, -48], [-96, -40], [-60, -12]], "cpencil", "#ffffff", 0.52, 0.4);

  // B. Lower Jaw
  let lowerJawOuter = [[-52, 26], [-98, 58], [-154, 64], [-208, 50], [-208, 30]];
  let lowerJawInner = [
    [-208, 30], [-156, 26], // Flat serrated nose
    [-142, 36], [-124, 36], [-112, 22], // Curved pipe-grip recess
    [-82, 14], [-56, 4] // Wire cutter bevel & throat
  ];
  let lowerJawPoly = [...lowerJawOuter, ...lowerJawInner.slice(1)];
  frag.washPoly(lowerJawPoly, "#70685c", 248);

  // Dark underside bevel of lower jaw & bright top/side planes
  let lowerBottomBevel = [[-52, 26], [-98, 58], [-154, 64], [-208, 50],
                          [-202, 41], [-150, 50], [-96, 42], [-56, 14]];
  frag.washPoly(lowerBottomBevel, "#1c1815", 240);
  frag.hatchRegion(lowerBottomBevel, 2.8, 18, "2B", "#110f0d", 0.45, 0.15);

  let lowerFlatFace = [[-202, 41], [-150, 50], [-96, 42], [-58, 14],
                       [-82, 14], [-112, 22], [-133, 34], [-156, 26], [-208, 30]];
  frag.washPoly(lowerFlatFace, "#c9c1b2", 235);
  frag.hatchRegion(lowerFlatFace, 2.6, 68, "2H", "#7a7164", 0.32, 0.1);
  // Blinding specular highlight along the inner top chamfer of the lower jaw
  frag.spline([[-208, 30], [-156, 26], [-142, 36], [-124, 36], [-112, 22], [-82, 14]],
              "cpencil", "#ffffff", 0.58, 0.25);

  // C. Razor-Sharp Serration Teeth along both inner jaw faces & pipe-grip cutouts!
  // Flat nose serrations (lx = -208 to -158)
  for (let tx = -206; tx <= -160; tx += 4.2) {
    // Upper jaw tooth pointing down-right
    frag.line(tx, -31, tx + 2.2, -25.5, "rotring", "#12100e", 0.48);
    frag.line(tx + 2.2, -25.5, tx + 4.2, -31, "cpencil", "#ffffff", 0.42);
    // Lower jaw tooth pointing up-left
    frag.line(tx, 29, tx + 2.2, 23.5, "cpencil", "#ffffff", 0.44);
    frag.line(tx + 2.2, 23.5, tx + 4.2, 29, "rotring", "#12100e", 0.48);
  }
  // Larger pipe-grip teeth inside the curved cutout (lx = -146 to -116)
  for (let tx = -144; tx <= -118; tx += 5.5) {
    frag.line(tx, -36, tx + 2.8, -29, "rotring", "#12100e", 0.52);
    frag.line(tx + 2.8, -29, tx + 5.2, -36, "cpencil", "#ffffff", 0.45);
    frag.line(tx, 34, tx + 2.8, 27, "cpencil", "#ffffff", 0.45);
    frag.line(tx + 2.8, 27, tx + 5.2, 34, "rotring", "#12100e", 0.52);
  }

  // Crisp outer silhouettes of both jaws
  frag.spline(upperJawOuter, "rotring", "#110f0d", 0.55, 0.2);
  frag.spline(lowerJawOuter, "rotring", "#110f0d", 0.55, 0.2);

  // 4. MACHINED SLIP-JOINT LAP PIVOT & CENTRAL BOLT (lx = -56, ly = 0, radius = 32)
  let px = -56, py = 0, pr = 31;
  let pivotDisc = [];
  for (let a = 0; a < 360; a += 12) pivotDisc.push([px + cos(a) * pr, py + sin(a) * pr]);
  // Dark machined step shadow around the lap joint
  frag.washPoly(pivotDisc.map(p => [p[0] + 2, p[1] + 3]), "#12100e", 235);
  frag.washPoly(pivotDisc, "#aba293", 245);

  // Concentric circular brushed-steel turnings & bow-tie specular gleams on pivot cheek
  for (let r = 14; r <= pr - 1; r += 2.6) {
    let ring = [];
    for (let a = 0; a <= 360; a += 15) ring.push([px + cos(a) * r, py + sin(a) * r]);
    frag.spline(ring, "2H", "#6e6559", 0.32, 0.5);
  }
  for (let a = -55; a <= -18; a += 3.5) {
    frag.line(px + cos(a) * 13, py + sin(a) * 13, px + cos(a) * (pr - 1), py + sin(a) * (pr - 1),
              "cpencil", "#ffffff", 0.48);
    frag.line(px + cos(a + 180) * 13, py + sin(a + 180) * 13,
              px + cos(a + 180) * (pr - 1), py + sin(a + 180) * (pr - 1),
              "cpencil", "#f5f0e4", 0.42);
  }
  for (let a = 35; a <= 72; a += 3.5) {
    frag.line(px + cos(a) * 13, py + sin(a) * 13, px + cos(a) * (pr - 1), py + sin(a) * (pr - 1),
              "2B", "#1c1815", 0.45);
    frag.line(px + cos(a + 180) * 13, py + sin(a + 180) * 13,
              px + cos(a + 180) * (pr - 1), py + sin(a + 180) * (pr - 1),
              "2B", "#1c1815", 0.45);
  }
  frag.spline([...pivotDisc, pivotDisc[0]], "rotring", "#12100e", 0.52, 0.5);

  // Figure-8 slip-joint slot & domed central steel pivot bolt with machined flat
  let slotPoly = [
    [px - 11, py - 8], [px + 11, py - 8], [px + 14, py],
    [px + 11, py + 8], [px - 11, py + 8], [px - 14, py]
  ];
  frag.washPoly(slotPoly, "#141210", 248);

  // Domed bolt head sitting at (px - 3, py)
  let boltR = 11.5;
  let boltPts = [];
  for (let a = 0; a < 360; a += 18) boltPts.push([px - 3 + cos(a) * boltR, py + sin(a) * boltR]);
  frag.washPoly(boltPts, "#d9d2c4", 248);
  frag.washPoly([[px - 11, py - 9], [px + 1, py - 9], [px - 1, py - 1], [px - 11, py - 1]], "#ffffff", 240);
  frag.washPoly([[px - 10, py + 2], [px + 5, py + 2], [px + 3, py + 10], [px - 8, py + 10]], "#2b251f", 225);
  frag.spline([...boltPts, boltPts[0]], "rotring", "#0f0d0b", 0.55, 0.5);
  frag.line(px - 10, py - 5, px + 3, py - 5, "cpencil", "#ffffff", 0.62);
}

