// 3D Axonometric Basis Vectors
// u: main explosion shaft axis (down-right at ~32.5 deg)
// v: cross horizontal depth axis (up-right at ~-26 deg, foreshortened)
// w: vertical axis (straight down)
const AX = {
  ox: 135,
  oy: 168,
  ux: 0.842, uy: 0.539,
  vx: 0.710, vy: -0.345,
  wx: 0.000, wy: 1.000
};

function iso(u, v, w) {
  return [
    AX.ox + u * AX.ux + v * AX.vx + w * AX.wx,
    AX.oy + u * AX.uy + v * AX.vy + w * AX.wy
  ];
}

// Point on a 3D circle in the (v, w) plane perpendicular to main axis u
function vwPoint(u, vc, wc, r, angDeg, aspectV = 1.0) {
  let c = cos(angDeg) * aspectV;
  let s = sin(angDeg);
  return iso(u, vc + r * c, wc + r * s);
}

// Point on a 3D circle in the (u, v) horizontal plane perpendicular to vertical axis w
function uvPoint(uc, vc, w, r, angDeg) {
  let c = cos(angDeg) * 0.82;
  let s = sin(angDeg);
  return iso(uc + r * c, vc + r * s, w);
}

// Exact silhouette angles for a cylinder aligned along the u-axis
// Normal to u-axis in 2D screen space is (-uy, ux)
const SIL_A = AX.vx * (-AX.uy) + AX.vy * AX.ux;
const SIL_B = AX.wx * (-AX.uy) + AX.wy * AX.ux;
const THETA_TOP = Math.atan2(SIL_B, SIL_A) * (180 / Math.PI); // ~ 127.5 deg
const THETA_BOT = THETA_TOP - 180;                            // ~ -52.5 deg

