  drawSelectorDialPlate(62, 0, 0);          // FIG. 1: Rotary Pencil Guide
  drawSpringRetainer(162, 0, 0);            // FIG. 2: Tension Clip
  drawTwinBurrAssembly(635, 0, 0);          // FIG. 4A, 4B, 5, 6: Helical Burr Cylinders & Carrier
  drawPedestalAndRingGear(915, 0, 0);       // FIG. 7: Main Frame & Internal Gear
  drawClampAssembly(915, 0, 205);           // FIG. 8, 9: Desk Clamp & Thumb Screw
  drawCrankAndHandle(1058, 0, 0);           // FIG. 10, 11: Crank Arm & Knob

  // 4. THE HYPERREAL BREAK: Shavings-Filled Receptacle (FIG. 3)
  // Positioned at u = 270..455, spilling curled cedar shavings & smeared lead dust
  drawHyperrealReceptacleAndShavings(275, 455, 0, 0);

  // 5. Foreground Axis Overlays, Leader Lines & Patent Lettering
  drawExplosionAxesFront();
  drawPatentAnnotations();

  noLoop();
}

