// 1. BRISTOL PAPER GROUND
// =============================================================================
function drawBristolGround() {
  background(PAL.bristol);

  // Subtle stiff bristol plate tone & very faint paper tooth
  brush.noStroke();
  brush.fill(PAL.bristolWarm, 28);
  brush.fillTexture(0.35, 0.08);
  brush.fillBleed(0.05);
  brush.rect(30, 30, 1140, 1140);
  brush.noFill();

  // Faint dry graphite/paper grain across the sheet
  brush.set("2H", "#dfd9cc", 0.35);
  for (let i = 0; i < 65; i++) {
    let y = random(20, 1180);
    let x1 = random(20, 900);
    let x2 = x1 + random(80, 280);
    brush.line(x1, y, x2, y + random(-2, 2));
  }

  // Crisp patent-sheet corner registration ticks (cold technical pen)
  brush.set("rotring", PAL.inkFaint, 0.32);
  const m = 42, tk = 18;
  // Top-left
  brush.line(m, m, m + tk, m);
  brush.line(m, m, m, m + tk);
  // Top-right
  brush.line(width - m - tk, m, width - m, m);
  brush.line(width - m, m, width - m, m + tk);
  // Bottom-left
  brush.line(m, height - m, m + tk, height - m);
  brush.line(m, height - m - tk, m, height - m);
  // Bottom-right
  brush.line(width - m - tk, height - m, width - m, height - m);
  brush.line(width - m, height - m - tk, width - m, height - m);
}

// =============================================================================
// 2. TECHNICAL PEN GEOMETRY HELPERS
// =============================================================================
function drawTechPolyline(pts, closeShape = false) {
  if (pts.length < 2) return;
  for (let i = 0; i < pts.length - 1; i++) {
    brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }
  if (closeShape) {
    brush.line(pts[pts.length - 1][0], pts[pts.length - 1][1], pts[0][0], pts[0][1]);
  }
}

function drawDashedLine(x1, y1, x2, y2, dashLen = 14, gapLen = 7, dotInGap = true) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let distTotal = sqrt(dx * dx + dy * dy);
  if (distTotal < 1) return;
  let ux = dx / distTotal;
  let uy = dy / distTotal;
  let cur = 0;
  while (cur < distTotal) {
    let seg = min(dashLen, distTotal - cur);
    brush.line(x1 + ux * cur, y1 + uy * cur, x1 + ux * (cur + seg), y1 + uy * (cur + seg));
    cur += seg;
    if (dotInGap && cur + gapLen * 0.5 < distTotal) {
      let mx = x1 + ux * (cur + gapLen * 0.5);
      let my = y1 + uy * (cur + gapLen * 0.5);
      brush.line(mx - ux * 1.2, my - uy * 1.2, mx + ux * 1.2, my + uy * 1.2);
    }
    cur += gapLen;
  }
}

function drawVWCircle(u, vc, wc, r, startAng = 0, endAng = 360, steps = 48, aspectV = 1.0) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(startAng, endAng, i / steps);
    pts.push(vwPoint(u, vc, wc, r, a, aspectV));
  }
  drawTechPolyline(pts, false);
}

function drawUVCircle(uc, vc, w, r, startAng = 0, endAng = 360, steps = 40) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(startAng, endAng, i / steps);
    pts.push(uvPoint(uc, vc, w, r, a));
  }
  drawTechPolyline(pts, false);
}

// Draws a 3D cylinder aligned along the u-axis with silhouette lines & optional shading lines
function drawTechCylinderU(u1, u2, vc, wc, r, opts = {}) {
  let steps = opts.steps || 48;
  let weight = opts.weight || 0.48;
  let shadeLines = opts.shadeLines !== undefined ? opts.shadeLines : true;
  let showBackFull = opts.showBackFull || false;

  // Paper knock-out wash if solid technical part
  if (opts.opaque !== false) {
    brush.noStroke();
    brush.wash(PAL.bristol, 235);
    brush.beginShape(0);
    for (let i = 0; i <= 24; i++) {
      let a = lerp(THETA_BOT, THETA_TOP, i / 24);
      let p = vwPoint(u2, vc, wc, r, a);
      brush.vertex(p[0], p[1]);
    }
    for (let i = 0; i <= 24; i++) {
      let a = lerp(THETA_TOP, THETA_BOT + 360, i / 24);
      let p = vwPoint(u1, vc, wc, r, a);
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(true);
    brush.noWash();
  }

  brush.set("rotring", PAL.ink, weight);

  // Front face full circle at u2
  drawVWCircle(u2, vc, wc, r, 0, 360, steps);

  // Back face visible arc at u1 (from THETA_TOP to THETA_BOT + 360)
  if (showBackFull) {
    drawVWCircle(u1, vc, wc, r, 0, 360, steps);
  } else {
    drawVWCircle(u1, vc, wc, r, THETA_TOP, THETA_BOT + 360, Math.round(steps * 0.6));
  }

  // Top & Bottom Silhouette Contour Lines
  let p1Top = vwPoint(u1, vc, wc, r, THETA_TOP);
  let p2Top = vwPoint(u2, vc, wc, r, THETA_TOP);
  let p1Bot = vwPoint(u1, vc, wc, r, THETA_BOT);
  let p2Bot = vwPoint(u2, vc, wc, r, THETA_BOT);
  brush.line(p1Top[0], p1Top[1], p2Top[0], p2Top[1]);
  brush.line(p1Bot[0], p1Bot[1], p2Bot[0], p2Bot[1]);

  // Patent-style curved/axial surface ruling lines on cylinder belly
  if (shadeLines && u2 - u1 > 6) {
    brush.set("rotring", PAL.inkMid, weight * 0.62);
    let shadeAngles = [-38, -28, -16, -2, 85, 102, 114, 121];
    for (let ang of shadeAngles) {
      let pa = vwPoint(u1, vc, wc, r, ang);
      let pb = vwPoint(u2, vc, wc, r, ang);
      brush.line(pa[0], pa[1], pb[0], pb[1]);
    }
  }
}

// Draws a 3D spur or bevel gear perpendicular to the u-axis
function drawTechGearU(u1, u2, vc, wc, rRoot, rTip, numTeeth, boreR = 8) {
  // Opaque paper mask
  brush.noStroke();
  brush.wash(PAL.bristol, 240);
  brush.beginShape(0);
  for (let i = 0; i <= 32; i++) {
    let p = vwPoint((u1 + u2) * 0.5, vc, wc, rTip, (i / 32) * 360);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  let frontPts = [];
  let backPts = [];
  let stepAng = 360 / numTeeth;

  for (let i = 0; i < numTeeth; i++) {
    let baseA = i * stepAng;
    let a0 = baseA;
    let a1 = baseA + stepAng * 0.22;
    let a2 = baseA + stepAng * 0.34;
    let a3 = baseA + stepAng * 0.62;
    let a4 = baseA + stepAng * 0.74;

    frontPts.push(vwPoint(u2, vc, wc, rRoot, a0));
    frontPts.push(vwPoint(u2, vc, wc, rRoot, a1));
    frontPts.push(vwPoint(u2, vc, wc, rTip, a2));
    frontPts.push(vwPoint(u2, vc, wc, rTip, a3));
    frontPts.push(vwPoint(u2, vc, wc, rRoot, a4));

    backPts.push(vwPoint(u1, vc, wc, rRoot, a0));
    backPts.push(vwPoint(u1, vc, wc, rRoot, a1));
    backPts.push(vwPoint(u1, vc, wc, rTip, a2));
    backPts.push(vwPoint(u1, vc, wc, rTip, a3));
    backPts.push(vwPoint(u1, vc, wc, rRoot, a4));
  }

  // Connect tooth tips from u1 to u2 on the visible outer hemisphere
  brush.set("rotring", PAL.inkMid, 0.36);
  for (let i = 0; i < numTeeth; i++) {
    let baseA = (i * stepAng + stepAng * 0.48) % 360;
    // Check if tooth is on visible upper/left/lower rim
    if (baseA > 110 || baseA < -40 || baseA > 290 || baseA < 60) {
      let idx = i * 5;
      brush.line(backPts[idx + 2][0], backPts[idx + 2][1], frontPts[idx + 2][0], frontPts[idx + 2][1]);
      brush.line(backPts[idx + 3][0], backPts[idx + 3][1], frontPts[idx + 3][0], frontPts[idx + 3][1]);
    }
  }

  // Back gear contour (visible portion)
  brush.set("rotring", PAL.ink, 0.42);
  for (let i = 0; i < backPts.length; i++) {
    let next = (i + 1) % backPts.length;
    let ang = (i / backPts.length) * 360;
    if (ang >= 115 && ang <= 315) {
      brush.line(backPts[i][0], backPts[i][1], backPts[next][0], backPts[next][1]);
    }
  }

  // Front gear contour
  brush.set("rotring", PAL.ink, 0.48);
  drawTechPolyline(frontPts, true);

  // Inner web & central bore
  brush.set("rotring", PAL.inkMid, 0.36);
  drawVWCircle(u2, vc, wc, rRoot * 0.76, 0, 360, 36);
  brush.set("rotring", PAL.ink, 0.46);
  drawVWCircle(u2, vc, wc, boreR, 0, 360, 28);
}

