// =============================================================================
// 4. COLD TECHNICAL PEN COMPONENTS
// =============================================================================

// FIG. 1: Rotary Pencil-Size Selector Dial Plate
function drawSelectorDialPlate(u, vc, wc) {
  // Stepped outer bezel disc
  drawTechCylinderU(u - 9, u, vc, wc, 58, { weight: 0.5, shadeLines: true });
  drawTechCylinderU(u, u + 5, vc, wc, 46, { weight: 0.45, shadeLines: false });

  // Knurling ticks around outer rim
  brush.set("rotring", PAL.inkMid, 0.32);
  for (let a = 125; a <= 310; a += 6) {
    let p1 = vwPoint(u - 9, vc, wc, 58, a);
    let p2 = vwPoint(u, vc, wc, 58, a);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 8 Graduated Pencil-Size Aperture Holes in a turret circle
  brush.set("rotring", PAL.ink, 0.45);
  let holeRadii = [4.5, 5.2, 6.0, 6.8, 7.6, 8.5, 9.2, 5.0];
  for (let i = 0; i < 8; i++) {
    let ang = i * 45 + 15;
    let hc = [vc + 28 * cos(ang), wc + 28 * sin(ang)];
    let hr = holeRadii[i];
    drawVWCircle(u + 5, hc[0], hc[1], hr, 0, 360, 24);
    // Inner thickness ring
    brush.set("rotring", PAL.inkMid, 0.30);
    drawVWCircle(u + 2, hc[0], hc[1], hr * 0.85, 110, 300, 14);
    brush.set("rotring", PAL.ink, 0.45);
  }

  // Central pivot boss & entry hole
  drawTechCylinderU(u + 5, u + 11, vc, wc, 13, { weight: 0.45, shadeLines: false });
  brush.set("rotring", PAL.ink, 0.48);
  drawVWCircle(u + 11, vc, wc, 7.5, 0, 360, 24);

  // Upper & lower finger-grip ears on selector dial
  for (let dir of [-1, 1]) {
    let earW = dir * 64;
    drawTechCylinderU(u - 7, u - 1, vc, wc + earW, 10, { weight: 0.42, shadeLines: false });
  }
}

// FIG. 2: Stamped Spring Tension Retainer Clip
function drawSpringRetainer(u, vc, wc) {
  drawTechCylinderU(u - 3, u + 3, vc, wc, 36, { weight: 0.44, shadeLines: false });
  brush.set("rotring", PAL.ink, 0.44);
  drawVWCircle(u + 3, vc, wc, 26, 0, 360, 36);

  // Three inward tension leaf prongs
  for (let i = 0; i < 3; i++) {
    let a = i * 120 + 30;
    let p1 = vwPoint(u + 3, vc, wc, 26, a - 12);
    let p2 = vwPoint(u + 8, vc, wc, 14, a - 5);
    let p3 = vwPoint(u + 8, vc, wc, 14, a + 5);
    let p4 = vwPoint(u + 3, vc, wc, 26, a + 12);
    drawTechPolyline([p1, p2, p3, p4], false);
  }
}

// FIG. 4A, 4B, 5, 6: Twin Helical Burr Cylinders, Pinion Gears & Carrier Yoke
function drawTwinBurrAssembly(uCenter, vc, wc) {
  let u1 = uCenter - 58;
  let u2 = uCenter + 54;

  // Draw Lower-Front Burr (4B) and Upper-Back Burr (4A)
  let burrs = [
    { dv: -40, dw: -26, label: "4A" }, // Upper-Back Burr Cylinder
    { dv: 40,  dw: 26,  label: "4B" }  // Lower-Front Burr Cylinder
  ];

  for (let b of burrs) {
    let bv = vc + b.dv;
    let bw = wc + b.dw;
    let rCore = 17;
    let rFlute = 23.5;

    // Front & rear steel journal shafts
    drawTechCylinderU(u1 - 26, u1, bv, bw, 5.5, { weight: 0.42, shadeLines: false });
    drawTechCylinderU(u2, u2 + 44, bv, bw, 6.0, { weight: 0.42, shadeLines: false });

    // Core cylinder body knock-out
    drawTechCylinderU(u1, u2, bv, bw, rCore, { weight: 0.42, shadeLines: false });

    // End collar disks
    drawTechCylinderU(u1 - 4, u1, bv, bw, rFlute * 0.9, { weight: 0.44, shadeLines: false });
    drawTechCylinderU(u2, u2 + 4, bv, bw, rFlute * 0.9, { weight: 0.44, shadeLines: false });

    // 12 Helical Spiral Cutting Flutes wrapping 200 degrees along u1..u2
    let nFlutes = 12;
    let twistDeg = 195;
    for (let f = 0; f < nFlutes; f++) {
      let startA = (f / nFlutes) * 360;
      let tipPts = [];
      let basePts = [];
      let segs = 28;
      for (let s = 0; s <= segs; s++) {
        let t = s / segs;
        let uu = lerp(u1, u2, t);
        let ang = (startA + t * twistDeg) % 360;
        // Check if this point on the helix is on the front-facing side of the cylinder
        // Visible angular window in vw-plane is roughly from -65 deg to +140 deg (plus front end)
        let normA = ((ang + 180) % 360) - 180;
        if (normA >= -62 && normA <= 138) {
          tipPts.push(vwPoint(uu, bv, bw, rFlute, ang));
          basePts.push(vwPoint(uu, bv, bw, rCore, ang + 7));
        } else {
          if (tipPts.length > 1) {
            brush.set("rotring", PAL.ink, 0.44);
            drawTechPolyline(tipPts, false);
            brush.set("rotring", PAL.inkMid, 0.30);
            drawTechPolyline(basePts, false);
          }
          tipPts = [];
          basePts = [];
        }
      }
      if (tipPts.length > 1) {
        brush.set("rotring", PAL.ink, 0.44);
        drawTechPolyline(tipPts, false);
        brush.set("rotring", PAL.inkMid, 0.30);
        drawTechPolyline(basePts, false);
      }
    }

    // Re-emphasize outer silhouette bounds of the fluted cylinder
    brush.set("rotring", PAL.ink, 0.50);
    let sTop1 = vwPoint(u1, bv, bw, rFlute, THETA_TOP);
    let sTop2 = vwPoint(u2, bv, bw, rFlute, THETA_TOP);
    let sBot1 = vwPoint(u1, bv, bw, rFlute, THETA_BOT);
    let sBot2 = vwPoint(u2, bv, bw, rFlute, THETA_BOT);
    brush.line(sTop1[0], sTop1[1], sTop2[0], sTop2[1]);
    brush.line(sBot1[0], sBot1[1], sBot2[0], sBot2[1]);

    // FIG. 5: Bevel Pinion Gear mounted at u2 + 12..u2 + 28
    drawTechGearU(u2 + 10, u2 + 25, bv, bw, 17, 25, 11, 6.5);
  }

  // FIG. 6: Cutter Carrier Yoke & Main Drive Spindle (at u = uCenter + 125)
  let uYoke = uCenter + 128;

  // Front triangular/lobed carrier plate (holds front journals)
  // Draw connecting bridge bars from front cheek to rear cheek
  brush.set("rotring", PAL.ink, 0.48);
  drawTechCylinderU(uYoke - 8, uYoke + 8, vc, wc, 26, { weight: 0.48, shadeLines: true });

  // Upper and lower bearing arms on the carrier yoke
  for (let b of burrs) {
    let bv = vc + b.dv;
    let bw = wc + b.dw;
    // Arm web connecting center hub (0,0) to bearing boss (bv, bw)
    let pHub1 = vwPoint(uYoke, vc, wc, 18, b.dw < 0 ? -110 : 70);
    let pHub2 = vwPoint(uYoke, vc, wc, 18, b.dw < 0 ? -40 : 140);
    let pBoss1 = vwPoint(uYoke, bv, bw, 14, b.dw < 0 ? -110 : 70);
    let pBoss2 = vwPoint(uYoke, bv, bw, 14, b.dw < 0 ? -40 : 140);
    brush.set("rotring", PAL.ink, 0.46);
    brush.line(pHub1[0], pHub1[1], pBoss1[0], pBoss1[1]);
    brush.line(pHub2[0], pHub2[1], pBoss2[0], pBoss2[1]);

    // Bearing boss cylinder
    drawTechCylinderU(uYoke - 10, uYoke + 10, bv, bw, 15, { weight: 0.46, shadeLines: true });
    brush.set("rotring", PAL.ink, 0.46);
    drawVWCircle(uYoke + 10, bv, bw, 6.5, 0, 360, 20);
  }

  // Main central drive shaft extending rightward from Carrier Yoke to Crank
  drawTechCylinderU(uYoke + 8, uYoke + 82, vc, wc, 9.5, { weight: 0.48, shadeLines: true });
  // Squared/threaded end on main shaft for crank retention
  drawTechCylinderU(uYoke + 82, uYoke + 98, vc, wc, 6.5, { weight: 0.44, shadeLines: false });
}

// FIG. 7: Main Cast-Iron Pedestal Stand & Internal Gear Ring Housing
function drawPedestalAndRingGear(u, vc, wc) {
  let rOuter = 82;
  let rInner = 64;
  let u1 = u - 22;
  let u2 = u + 22;

  // 1. Main upper cylindrical gear housing drum
  drawTechCylinderU(u1, u2, vc, wc, rOuter, { weight: 0.54, shadeLines: true });

  // Stepped rim flange on front face
  brush.set("rotring", PAL.ink, 0.48);
  drawVWCircle(u2, vc, wc, rOuter - 5, 0, 360, 48);

  // 2. Internal Gear Teeth (7a) around the inside rim of the housing
  let numTeeth = 32;
  let toothPts = [];
  let stepA = 360 / numTeeth;
  for (let i = 0; i < numTeeth; i++) {
    let a = i * stepA;
    toothPts.push(vwPoint(u2 - 3, vc, wc, rInner, a));
    toothPts.push(vwPoint(u2 - 3, vc, wc, rInner - 6.5, a + stepA * 0.25));
    toothPts.push(vwPoint(u2 - 3, vc, wc, rInner - 6.5, a + stepA * 0.65));
    toothPts.push(vwPoint(u2 - 3, vc, wc, rInner, a + stepA * 0.9));
  }
  brush.set("rotring", PAL.ink, 0.42);
  drawTechPolyline(toothPts, true);

  // Axial gear tooth lines inside the cavity
  brush.set("rotring", PAL.inkMid, 0.30);
  for (let i = 0; i < numTeeth; i += 2) {
    let a = i * stepA + stepA * 0.45;
    if (a > 120 && a < 310) {
      let pFront = vwPoint(u2 - 3, vc, wc, rInner - 6.5, a);
      let pBack = vwPoint(u1 + 8, vc, wc, rInner - 6.5, a);
      brush.line(pFront[0], pFront[1], pBack[0], pBack[1]);
    }
  }

  // Rear web wall inside housing & central shaft bearing boss
  brush.set("rotring", PAL.inkMid, 0.38);
  drawVWCircle(u1 + 8, vc, wc, rInner - 7, 100, 320, 36);
  drawTechCylinderU(u1 + 8, u2 + 18, vc, wc, 20, { weight: 0.48, shadeLines: true });
  brush.set("rotring", PAL.ink, 0.48);
  drawVWCircle(u2 + 18, vc, wc, 10.5, 0, 360, 28);

  // 3. Swept Cast-Iron Pedestal Neck Column (w = 72 down to w = 175)
  let wTop = 74;
  let wBase = 175;

  // Paper wash behind pedestal column
  brush.noStroke();
  brush.wash(PAL.bristol, 240);
  brush.beginShape(0);
  let colOutline = [
    iso(u - 18, vc - 24, wTop),
    iso(u + 18, vc - 24, wTop),
    iso(u + 34, vc + 26, wBase),
    iso(u - 34, vc + 26, wBase)
  ];
  for (let p of colOutline) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Curved S-profile edges of the pedestal column
  brush.set("rotring", PAL.ink, 0.50);
  let leftCol = [], rightCol = [], midRibL = [], midRibR = [];
  for (let i = 0; i <= 16; i++) {
    let t = i / 16;
    let ww = lerp(wTop, wBase, t);
    // Waist narrows in the middle and flares at top & bottom
    let flare = 18 + 16 * pow(t - 0.35, 2) * 2.2;
    leftCol.push(iso(u - flare * 0.7, vc - flare * 0.9, ww));
    rightCol.push(iso(u + flare * 0.85, vc + flare * 0.75, ww));
    midRibL.push(iso(u - flare * 0.25, vc - flare * 0.3, ww));
    midRibR.push(iso(u + flare * 0.35, vc + flare * 0.25, ww));
  }
  drawTechPolyline(leftCol, false);
  drawTechPolyline(rightCol, false);

  // Recessed I-beam web panel & cross-hatching on the cast-iron neck
  brush.set("rotring", PAL.inkMid, 0.36);
  drawTechPolyline(midRibL, false);
  drawTechPolyline(midRibR, false);
  for (let i = 2; i < 15; i++) {
    brush.line(midRibL[i][0], midRibL[i][1], midRibR[i][0], midRibR[i][1]);
  }

  // 4. Rectangular Slotted Footplate Base at w = 175..188
  let bw1 = 175, bw2 = 190;
  let bu = 44, bv = 48;
  let topCorners = [
    iso(u - bu, vc - bv, bw1),
    iso(u + bu, vc - bv, bw1),
    iso(u + bu, vc + bv, bw1),
    iso(u - bu, vc + bv, bw1)
  ];
  let botCorners = [
    iso(u - bu, vc - bv, bw2),
    iso(u + bu, vc - bv, bw2),
    iso(u + bu, vc + bv, bw2),
    iso(u - bu, vc + bv, bw2)
  ];

  brush.noStroke();
  brush.wash(PAL.bristol, 240);
  brush.beginShape(0);
  brush.vertex(topCorners[0][0], topCorners[0][1]);
  brush.vertex(topCorners[1][0], topCorners[1][1]);
  brush.vertex(botCorners[1][0], botCorners[1][1]);
  brush.vertex(botCorners[2][0], botCorners[2][1]);
  brush.vertex(botCorners[3][0], botCorners[3][1]);
  brush.vertex(topCorners[3][0], topCorners[3][1]);
  brush.endShape(true);
  brush.noWash();

  brush.set("rotring", PAL.ink, 0.50);
  drawTechPolyline(topCorners, true);
  // Visible lower base edges
  brush.line(botCorners[3][0], botCorners[3][1], botCorners[2][0], botCorners[2][1]);
  brush.line(botCorners[2][0], botCorners[2][1], botCorners[1][0], botCorners[1][1]);
  for (let i = 0; i < 4; i++) {
    brush.line(topCorners[i][0], topCorners[i][1], botCorners[i][0], botCorners[i][1]);
  }

  // Wood-screw mounting holes at corners of baseplate
  brush.set("rotring", PAL.ink, 0.40);
  drawUVCircle(u - 30, vc + 32, bw1, 6, 0, 360, 18);
  drawUVCircle(u + 30, vc - 32, bw1, 6, 0, 360, 18);
}

// FIG. 8 & 9: Forged C-Clamp Bracket & Acme Threaded Thumb Screw
function drawClampAssembly(u, vc, wStart) {
  // FIG. 8: Heavy C-Clamp Frame (wStart = 215 to 365)
  let wTop = wStart + 18;
  let wBot = wStart + 150;
  let throatV = -62; // spine of the C-clamp sits back along -v

  // Build C-Clamp 3D profile in (v, w) extruded along u (-14..+14)
  let cOuter = [
    [18, wTop],
    [throatV - 18, wTop],
    [throatV - 24, wTop + 18],
    [throatV - 24, wBot - 18],
    [throatV - 18, wBot],
    [14, wBot],
    [14, wBot - 22],
    [throatV + 4, wBot - 20],
    [throatV + 4, wTop + 20],
    [18, wTop + 18]
  ];

  let frontFace = cOuter.map(pt => iso(u + 13, vc + pt[0], pt[1]));
  let backFace = cOuter.map(pt => iso(u - 13, vc + pt[0], pt[1]));

  // Paper knockout
  brush.noStroke();
  brush.wash(PAL.bristol, 240);
  brush.beginShape(0);
  for (let p of frontFace) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Draw back face, connecting edges, and front face
  brush.set("rotring", PAL.inkMid, 0.38);
  drawTechPolyline(backFace, true);
  for (let i = 0; i < frontFace.length; i++) {
    brush.line(backFace[i][0], backFace[i][1], frontFace[i][0], frontFace[i][1]);
  }
  brush.set("rotring", PAL.ink, 0.52);
  drawTechPolyline(frontFace, true);

  // Structural webbing rib on C-clamp spine + diagonal technical hatching
  brush.set("rotring", PAL.inkMid, 0.32);
  for (let ww = wTop + 24; ww < wBot - 24; ww += 9) {
    let p1 = iso(u + 13, vc + throatV - 18, ww);
    let p2 = iso(u + 13, vc + throatV - 2, ww + 6);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Dovetail tongue on top of C-clamp (slides into Pedestal Base)
  let dtTop = wTop - 12;
  let dtPts = [
    iso(u - 10, vc - 18, dtTop),
    iso(u + 10, vc - 18, dtTop),
    iso(u + 10, vc + 16, dtTop),
    iso(u - 10, vc + 16, dtTop)
  ];
  brush.set("rotring", PAL.ink, 0.45);
  drawTechPolyline(dtPts, true);
  brush.line(dtPts[1][0], dtPts[1][1], iso(u + 10, vc - 18, wTop)[0], iso(u + 10, vc - 18, wTop)[1]);
  brush.line(dtPts[2][0], dtPts[2][1], iso(u + 10, vc + 16, wTop)[0], iso(u + 10, vc + 16, wTop)[1]);
  brush.line(dtPts[3][0], dtPts[3][1], iso(u - 10, vc + 16, wTop)[0], iso(u - 10, vc + 16, wTop)[1]);

  // Threaded boss collar at bottom jaw of C-clamp
  let wBoss = wBot + 8;
  brush.set("rotring", PAL.ink, 0.46);
  drawUVCircle(u, vc, wBoss, 15, 0, 360, 28);
  drawUVCircle(u, vc, wTop + 98, 22, 0, 360, 32); // Swivel pad floating inside throat!
  drawUVCircle(u, vc, wTop + 103, 22, 0, 180, 20);

  // FIG. 9: Vertical Acme Clamp Screw & Winged Thumb-Turn (w = wTop + 105 down to wBot + 95)
  let screwW1 = wTop + 105;
  let screwW2 = wBot + 78;
  let sr = 7.5;

  // Screw shaft silhouette
  let sLeft1 = uvPoint(u, vc, screwW1, sr, 180);
  let sLeft2 = uvPoint(u, vc, screwW2, sr, 180);
  let sRight1 = uvPoint(u, vc, screwW1, sr, 0);
  let sRight2 = uvPoint(u, vc, screwW2, sr, 0);

  brush.noStroke();
  brush.wash(PAL.bristol, 240);
  brush.beginShape(0);
  brush.vertex(sLeft1[0], sLeft1[1]);
  brush.vertex(sRight1[0], sRight1[1]);
  brush.vertex(sRight2[0], sRight2[1]);
  brush.vertex(sLeft2[0], sLeft2[1]);
  brush.endShape(true);
  brush.noWash();

  brush.set("rotring", PAL.ink, 0.45);
  brush.line(sLeft1[0], sLeft1[1], sLeft2[0], sLeft2[1]);
  brush.line(sRight1[0], sRight1[1], sRight2[0], sRight2[1]);

  // Helical Acme Screw Thread ridges along the vertical shaft
  brush.set("rotring", PAL.inkMid, 0.36);
  for (let ww = screwW1 + 4; ww < screwW2 - 4; ww += 5.5) {
    drawUVCircle(u, vc, ww, sr * 1.12, -20, 200, 14);
  }

  // Winged Thumb-Turn Handle at bottom (w = screwW2..screwW2 + 24)
  let wThumb = screwW2 + 10;
  drawUVCircle(u, vc, screwW2, 13, 0, 360, 24);
  // Left & Right flat thumb wings
  for (let side of [-1, 1]) {
    let wing = [
      iso(u + side * 11, vc, screwW2 + 2),
      iso(u + side * 36, vc - side * 8, screwW2 + 6),
      iso(u + side * 38, vc - side * 8, screwW2 + 22),
      iso(u + side * 12, vc, screwW2 + 20)
    ];
    brush.set("rotring", PAL.ink, 0.48);
    drawTechPolyline(wing, true);
    brush.set("rotring", PAL.inkMid, 0.32);
    drawUVCircle(u + side * 26, vc - side * 5, screwW2 + 13, 5, 0, 360, 14);
  }
}

// FIG. 10 & 11: Crank Lever Arm & Exploded Rotating Handle Knob
function drawCrankAndHandle(u, vc, wc) {
  // FIG. 10: Upper hub boss at main shaft axis (u, vc, wc)
  drawTechCylinderU(u - 8, u + 10, vc, wc, 19, { weight: 0.50, shadeLines: true });
  brush.set("rotring", PAL.ink, 0.46);
  // Square/slotted drive bore
  drawVWCircle(u + 10, vc, wc, 8, 0, 360, 24);

  // Lower handle boss at (u, vc - 28, wc + 148)
  let vBot = vc - 28;
  let wBot = wc + 148;

  // Swept S-curved Crank Arm connecting (vc, wc) to (vBot, wBot)
  let armLeftF = [], armRightF = [], armRightB = [];
  let slotL = [], slotR = [];
  for (let i = 0; i <= 20; i++) {
    let t = i / 20;
    // Smooth S-curve offset in v
    let sCurve = sin(t * 180) * 10;
    let vv = lerp(vc, vBot, t) + sCurve;
    let ww = lerp(wc + 15, wBot - 12, t);
    let halfW = lerp(13, 9.5, t);
    armLeftF.push(iso(u + 6, vv - halfW, ww));
    armRightF.push(iso(u + 6, vv + halfW, ww));
    armRightB.push(iso(u - 4, vv + halfW, ww));
    if (i >= 3 && i <= 17) {
      slotL.push(iso(u + 6, vv - halfW * 0.42, ww));
      slotR.push(iso(u + 6, vv + halfW * 0.42, ww));
    }
  }

  // Opaque mask for crank arm
  brush.noStroke();
  brush.wash(PAL.bristol, 240);
  brush.beginShape(0);
  for (let p of armLeftF) brush.vertex(p[0], p[1]);
  for (let i = armRightF.length - 1; i >= 0; i--) brush.vertex(armRightF[i][0], armRightF[i][1]);
  brush.endShape(true);
  brush.noWash();

  brush.set("rotring", PAL.ink, 0.50);
  drawTechPolyline(armLeftF, false);
  drawTechPolyline(armRightF, false);
  brush.set("rotring", PAL.inkMid, 0.38);
  drawTechPolyline(armRightB, false);
  for (let i = 0; i < armRightF.length; i += 4) {
    brush.line(armRightF[i][0], armRightF[i][1], armRightB[i][0], armRightB[i][1]);
  }
  // Recessed lightening slot on crank arm face
  drawTechPolyline(slotL, false);
  drawTechPolyline(slotR, false);
  brush.line(slotL[0][0], slotL[0][1], slotR[0][0], slotR[0][1]);
  brush.line(slotL[slotL.length - 1][0], slotL[slotL.length - 1][1], slotR[slotR.length - 1][0], slotR[slotR.length - 1][1]);

  // Lower crank hub
  drawTechCylinderU(u - 4, u + 8, vBot, wBot, 13, { weight: 0.48, shadeLines: false });
  brush.set("rotring", PAL.ink, 0.45);
  drawVWCircle(u + 8, vBot, wBot, 5.5, 0, 360, 18);

  // FIG. 11: Exploded Crank Pin Spindle & Turned Handle Knob (u = u + 32 to u + 125)
  let uPin = u + 32;
  // Steel rivet spindle pin
  drawTechCylinderU(uPin, uPin + 22, vBot, wBot, 5.0, { weight: 0.42, shadeLines: false });

  // Turned ergonomic wooden/celluloid handle sleeve (u = u + 66 to u + 124)
  let uKnob1 = u + 66;
  let uKnob2 = u + 124;
  // Contoured barrel-shaped knob built from stepped/curved rings
  let nRings = 16;
  let topSil = [], botSil = [];
  for (let i = 0; i <= nRings; i++) {
    let t = i / nRings;
    let uu = lerp(uKnob1, uKnob2, t);
    let r = 13 + 5.5 * sin(t * 180) - 1.5 * sin(t * 360);
    topSil.push(vwPoint(uu, vBot, wBot, r, THETA_TOP));
    botSil.push(vwPoint(uu, vBot, wBot, r, THETA_BOT));
  }

  brush.noStroke();
  brush.wash(PAL.bristol, 240);
  brush.beginShape(0);
  for (let p of topSil) brush.vertex(p[0], p[1]);
  for (let i = botSil.length - 1; i >= 0; i--) brush.vertex(botSil[i][0], botSil[i][1]);
  brush.endShape(true);
  brush.noWash();

  brush.set("rotring", PAL.ink, 0.50);
  drawTechPolyline(topSil, false);
  drawTechPolyline(botSil, false);
  drawVWCircle(uKnob1, vBot, wBot, 13, THETA_TOP, THETA_BOT + 360, 28);
  drawVWCircle(uKnob2, vBot, wBot, 13, 0, 360, 32);

  // Decorative turned grooves & shade lines on the knob
  brush.set("rotring", PAL.inkMid, 0.34);
  drawVWCircle(uKnob1 + 10, vBot, wBot, 16.2, THETA_TOP, THETA_BOT + 360, 24);
  drawVWCircle(uKnob2 - 10, vBot, wBot, 16.2, THETA_TOP, THETA_BOT + 360, 24);
  // Peened rivet head cap at end of knob
  drawTechCylinderU(uKnob2, uKnob2 + 5, vBot, wBot, 6.5, { weight: 0.44, shadeLines: false });
}

// =============================================================================
// 5. THE HYPERREAL BREAK: SHAVINGS-FILLED RECEPTACLE (FIG. 3)
// =============================================================================
function drawHyperrealReceptacleAndShavings(u1, u2, vc, wc) {
  let rBody = 86;

  // ---------------------------------------------------------------------------
  // A. CAST SHADOW ON THE BRISTOL SHEET & SMEARED LEAD DUST
  // ---------------------------------------------------------------------------
  drawLeadDustAndShadow(u1, u2, vc, wc, rBody);

  // ---------------------------------------------------------------------------
  // B. RECEPTACLE EXTERIOR SHELL IN HYPERREAL GRAPHITE
  // ---------------------------------------------------------------------------
  // First knock out the paper under the receptacle body so back axes don't bleed through
  brush.noStroke();
  brush.wash(PAL.bristol, 250);
  brush.beginShape(0);
  for (let i = 0; i <= 28; i++) {
    let a = lerp(THETA_BOT, THETA_TOP, i / 28);
    let p = vwPoint(u2, vc, wc, rBody, a);
    brush.vertex(p[0], p[1]);
  }
  for (let i = 0; i <= 28; i++) {
    let a = lerp(THETA_TOP, THETA_BOT + 360, i / 28);
    let p = vwPoint(u1, vc, wc, rBody * 0.94, a);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Render the 3D cylindrical/fluted receptacle shell using circumferential tonal strips
  // Visible outer flank spans from THETA_TOP (~127.5 deg) counter-clockwise/clockwise to THETA_BOT (~-52.5 deg, i.e. 307.5 deg)
  // Specifically, the visible outer surface is angles from -52.5 deg -> 0 -> 90 -> 127.5 deg!
  // Let's verify:
  // At angle -45 deg (upper-right): faces upper-right (light source is at -65 deg!)
  // At angle 0 deg (right-up): sunlit flank & bright specular highlight ridge!
  // At angle +55 deg (lower-right/down): core shadow along the belly of the drum!
  // At angle +110 deg (down-left): subtle reflected bounce light from the white bristol paper!
  let nStrips = 36;
  let angStart = THETA_BOT; // -52.5 deg
  let angEnd = THETA_TOP;   // +127.5 deg

  // 1. Soft Graphite Wash Underpainting (grouped into tonal bands)
  brush.noStroke();
  brush.fillBleed(0.06, "out");
  brush.fillTexture(0.45, 0.15);

  for (let i = 0; i < nStrips; i++) {
    let a1 = lerp(angStart, angEnd, i / nStrips);
    let a2 = lerp(angStart, angEnd, (i + 1.15) / nStrips);
    let aMid = (a1 + a2) * 0.5;

    // Compute realistic cylindrical lighting value:
    // Specular ridge around aMid = -18 deg; Core shadow around aMid = +68 deg; Bounce light around +115 deg
    let spec = exp(-pow((aMid - (-16)) / 14, 2));
    let core = exp(-pow((aMid - 68) / 38, 2));
    let topEdge = exp(-pow((aMid - (-48)) / 14, 2)) * 0.45;
    let botEdge = exp(-pow((aMid - 122) / 14, 2)) * 0.35;

    let darkness = constrain(0.18 + 0.68 * core + topEdge + botEdge - 0.75 * spec, 0.03, 0.92);

    if (darkness > 0.10) {
      let col = darkness > 0.62 ? PAL.leadDark : (darkness > 0.35 ? PAL.leadMid : PAL.leadSoft);
      let alpha = map(darkness, 0.10, 0.92, 18, 125);
      brush.fill(col, alpha);

      let p1 = vwPoint(u1 + 10, vc, wc, rBody * 0.96, a1);
      let p2 = vwPoint(u2 - 6, vc, wc, rBody, a1);
      let p3 = vwPoint(u2 - 6, vc, wc, rBody, a2);
      let p4 = vwPoint(u1 + 10, vc, wc, rBody * 0.96, a2);

      brush.beginShape(0);
      brush.vertex(p1[0], p1[1]);
      brush.vertex(p2[0], p2[1]);
      brush.vertex(p3[0], p3[1]);
      brush.vertex(p4[0], p4[1]);
      brush.endShape(true);
    }
  }
  brush.noFill();

  // 2. Dense Multi-Pass Graphite Shading (2H, HB, 2B, Charcoal) along the 3D form
  // Pass 1: Longitudinal form strokes along u1..u2
  for (let i = 0; i <= 140; i++) {
    let t = i / 140;
    let ang = lerp(angStart, angEnd, t) + random(-0.8, 0.8);
    let spec = exp(-pow((ang - (-16)) / 13, 2));
    let core = exp(-pow((ang - 68) / 36, 2));
    let edge = exp(-pow((ang - (-49)) / 10, 2)) * 0.5 + exp(-pow((ang - 124) / 10, 2)) * 0.45;
    let tone = constrain(0.20 + 0.72 * core + edge - 0.85 * spec, 0, 1);

    // Leave the bright metallic highlight strip nearly bare save for whisper-thin 2H lines
    if (tone < 0.12 && random() < 0.75) continue;

    if (tone > 0.68) {
      brush.set("2B", PAL.leadDark, random(0.42, 0.72));
    } else if (tone > 0.40) {
      brush.set("HB", PAL.leadMid, random(0.35, 0.58));
    } else {
      brush.set("2H", PAL.leadSoft, random(0.28, 0.45));
    }

    let r1 = rBody * 0.96;
    let r2 = rBody;
    let uStart = u1 + random(6, 18);
    let uStop = u2 - random(2, 10);
    let pA = vwPoint(uStart, vc, wc, r1, ang);
    let pB = vwPoint((uStart + uStop) * 0.5, vc, wc, (r1 + r2) * 0.5, ang + random(-1.2, 1.2));
    let pC = vwPoint(uStop, vc, wc, r2, ang);
    brush.spline([
      [pA[0], pA[1], random(0.4, 0.8)],
      [pB[0], pB[1], random(0.7, 1.1)],
      [pC[0], pC[1], random(0.4, 0.8)]
    ], 0.3);

    // Extra deep charcoal pass in the core shadow & lower rim
    if (tone > 0.74 && i % 2 === 0) {
      brush.set("charcoal", PAL.leadBlack, random(0.35, 0.55));
      let pD = vwPoint(uStart + random(5, 30), vc, wc, r1, ang + random(-2, 2));
      let pE = vwPoint(uStop - random(5, 25), vc, wc, r2, ang + random(-2, 2));
      brush.line(pD[0], pD[1], pE[0], pE[1]);
    }
  }

  // Pass 2: Circumferential Cross-Contour Graphite Strokes (wrapping around the barrel)
  for (let uRing = u1 + 12; uRing <= u2 - 6; uRing += 4.5) {
    let uRatio = (uRing - u1) / (u2 - u1);
    let rRing = lerp(rBody * 0.96, rBody, uRatio);

    // Draw curved cross-contour arcs in the midtones and core shadow
    let arcPts = [];
    for (let a = 8; a <= 125; a += 8) {
      let p = vwPoint(uRing + random(-1, 1), vc, wc, rRing, a);
      arcPts.push([p[0], p[1], map( sin((a - 8) / 117 * 180), 0, 1, 0.35, 0.95 )]);
    }
    brush.set(uRing % 9 < 4.5 ? "HB" : "2B", PAL.leadMid, random(0.30, 0.48));
    brush.spline(arcPts, 0.45);

    // Upper bevel cross-contour above the specular highlight
    let upperPts = [];
    for (let a = -52; a <= -24; a += 7) {
      let p = vwPoint(uRing, vc, wc, rRing, a);
      upperPts.push([p[0], p[1], 0.5]);
    }
    brush.set("2H", PAL.leadMid, 0.32);
    brush.spline(upperPts, 0.4);
  }

  // 3. Molded Flank Ribs & Recessed Oval Brand Medallion on the Receptacle Side
  drawReceptacleSurfaceDetails(u1, u2, vc, wc, rBody);

  // 4. Stepped Front Nose Cone (at u1..u1+12) & Rolled Metal Lip at Open Rear Mouth (u2)
  drawReceptacleNoseAndRim(u1, u2, vc, wc, rBody);

  // ---------------------------------------------------------------------------
  // C. DEEP VELVETY GRAPHITE CAVITY INSIDE THE OPEN MOUTH (at u2)
  // ---------------------------------------------------------------------------
  drawReceptacleDarkCavity(u2, vc, wc, rBody);

  // ---------------------------------------------------------------------------
  // D. CURLED CEDAR SHAVINGS, YELLOW LACQUER FLECKS & BROKEN LEAD TIPS
  // ---------------------------------------------------------------------------
  drawAllCedarShavingsAndDebris(u2, vc, wc, rBody);
}

function drawLeadDustAndShadow(u1, u2, vc, wc, rBody) {
  // 1. Soft Cast Shadow directly under the Receptacle (w = +75..+145)
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.12);

  let shadowCenter = iso((u1 + u2) * 0.52, vc - 10, wc + 96);
  for (let layer = 0; layer < 4; layer++) {
    let expand = layer * 14;
    let alpha = map(layer, 0, 3, 62, 16);
    brush.fill(layer < 2 ? PAL.leadDark : PAL.leadSoft, alpha);
    brush.beginShape(0.6);
    let shPts = [
      iso(u1 + 12 - expand * 0.4, vc - 35, wc + 74 + expand * 0.3),
      iso(u2 + 15 + expand * 0.7, vc - 25, wc + 78 + expand * 0.3),
      iso(u2 + 45 + expand * 1.1, vc + 38, wc + 125 + expand * 0.6),
      iso(u1 + 25 - expand * 0.3, vc + 20, wc + 118 + expand * 0.5)
    ];
    for (let p of shPts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
  }

  // 2. Dramatic Diagonal Smear of Crushed Lead Dust sweeping down-right across the sheet
  // Trails from the open mouth (u2 ~ 455) down toward (u ~ 650, w ~ 210)
  for (let s = 0; s < 5; s++) {
    let t1 = s * 0.15;
    let smPts = [
      iso(u2 - 15 + s * 12, vc - 10, wc + 55 + s * 8),
      iso(u2 + 55 + s * 18, vc + 25, wc + 65 + s * 10),
      iso(u2 + 185 - s * 14, vc + 12, wc + 185 - s * 12),
      iso(u2 + 95 - s * 10, vc - 32, wc + 195 - s * 10),
      iso(u2 + 5 + s * 6,   vc - 40, wc + 135 - s * 5)
    ];
    brush.fill(s < 2 ? PAL.leadMid : PAL.leadLight, map(s, 0, 4, 38, 14));
    brush.beginShape(0.65);
    for (let p of smPts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
  }
  brush.noFill();

  // 3. Dry-brush Charcoal Smudge Streaks & Finger-Wipe Marks in the Lead Dust
  let smearOrigin = iso(u2 + 10, vc, wc + 78);
  for (let i = 0; i < 95; i++) {
    let frac = random();
    let sx = smearOrigin[0] + random(-55, 85) + frac * 145;
    let sy = smearOrigin[1] + random(-35, 55) + frac * 115;
    let len = random(25, 95) * (1 - frac * 0.45);
    let ang = 36 + random(-14, 18);

    if (random() < 0.35) {
      brush.set("charcoal", frac < 0.4 ? PAL.leadDark : PAL.leadSoft, random(0.28, 0.55));
    } else {
      brush.set("2H", frac < 0.5 ? PAL.leadMid : PAL.leadLight, random(0.25, 0.48));
    }
    let ex = sx + cos(ang) * len;
    let ey = sy + sin(ang) * len;
    brush.line(sx, sy, ex, ey);
  }

  // 4. Fine Stippled Graphite Powder & Crushed Lead Granules (Spray + 2B micro-dots)
  brush.set("spray", PAL.leadDark, 0.55);
  for (let i = 0; i < 28; i++) {
    let t = pow(random(), 1.4);
    let gx = smearOrigin[0] + random(-45, 55) + t * 175;
    let gy = smearOrigin[1] + random(-30, 50) + t * 135;
    brush.line(gx, gy, gx + random(8, 28), gy + random(5, 20));
  }

  // Individual sharp crushed lead specks scattered on the white bristol
  for (let i = 0; i < 160; i++) {
    let t = pow(random(), 1.6);
    let gx = smearOrigin[0] + random(-65, 90) + t * 210 + random(-20, 20);
    let gy = smearOrigin[1] + random(-40, 75) + t * 165 + random(-15, 15);
    let sz = random(0.8, 3.2) * (1 - t * 0.5);
    brush.set(random() < 0.5 ? "2B" : "charcoal", t < 0.4 ? PAL.leadBlack : PAL.leadMid, random(0.35, 0.68));
    brush.line(gx, gy, gx + sz, gy + sz * 0.7);
  }

  // Subtle graphite thumbprint smudge below the receptacle (concentric whorl arcs)
  let tp = iso(u1 + 75, vc - 35, wc + 148);
  brush.set("2H", PAL.leadSoft, 0.26);
  for (let r = 3; r <= 18; r += 2.2) {
    brush.arc(tp[0] + r * 0.15, tp[1], r, -35, 145);
  }
}

function drawReceptacleSurfaceDetails(u1, u2, vc, wc, rBody) {
  // Three raised longitudinal grip ribs along the lower-mid flank (ang = 32, 42, 52 deg)
  let ribAngles = [28, 38, 48];
  for (let ra of ribAngles) {
    // Dark shadow under each rib
    let s1 = vwPoint(u1 + 22, vc, wc, rBody * 0.98, ra + 2.2);
    let s2 = vwPoint(u2 - 16, vc, wc, rBody * 1.00, ra + 2.2);
    brush.set("2B", PAL.leadBlack, 0.52);
    brush.line(s1[0], s1[1], s2[0], s2[1]);

    // Crisp graphite highlight along top edge of each rib
    let h1 = vwPoint(u1 + 22, vc, wc, rBody * 0.98, ra - 1.2);
    let h2 = vwPoint(u2 - 16, vc, wc, rBody * 1.00, ra - 1.2);
    brush.set("2H", PAL.bristol, 0.42);
    brush.line(h1[0], h1[1], h2[0], h2[1]);
  }

  // Recessed Oval Brand Boss / Escutcheon Plate centered at uMid, ang = +8 deg
  let uMid = (u1 + u2) * 0.48;
  let bossPts = [];
  let bossHi = [];
  for (let i = 0; i <= 24; i++) {
    let a = (i / 24) * 360;
    let du = 28 * cos(a);
    let da = 15 * sin(a);
    bossPts.push(vwPoint(uMid + du, vc, wc, rBody * 0.99, 6 + da));
    if (a >= 160 && a <= 350) {
      bossHi.push(vwPoint(uMid + du, vc, wc, rBody * 0.99, 6 + da));
    }
  }
  brush.set("HB", PAL.leadDark, 0.42);
  drawTechPolyline(bossPts, true);
  brush.set("2H", PAL.bristol, 0.45);
  drawTechPolyline(bossHi, false);
}

function drawReceptacleNoseAndRim(u1, u2, vc, wc, rBody) {
  // 1. Stepped Front Nose Bevel at u1..u1+12
  for (let a = THETA_BOT; a <= THETA_TOP; a += 3) {
    let pBack = vwPoint(u1, vc, wc, rBody * 0.86, a);
    let pFront = vwPoint(u1 + 11, vc, wc, rBody * 0.96, a);
    let isDark = a > 25;
    brush.set(isDark ? "2B" : "HB", isDark ? PAL.leadDark : PAL.leadMid, 0.42);
    brush.line(pBack[0], pBack[1], pFront[0], pFront[1]);
  }

  // Outer silhouette edges of the receptacle rendered in crisp, rich 2B/HB graphite
  let top1 = vwPoint(u1 + 10, vc, wc, rBody * 0.96, THETA_TOP);
  let top2 = vwPoint(u2, vc, wc, rBody, THETA_TOP);
  let bot1 = vwPoint(u1 + 10, vc, wc, rBody * 0.96, THETA_BOT);
  let bot2 = vwPoint(u2, vc, wc, rBody, THETA_BOT);

  brush.set("2B", PAL.leadBlack, 0.62);
  brush.line(top1[0], top1[1], top2[0], top2[1]);
  brush.set("HB", PAL.leadDark, 0.55);
  brush.line(bot1[0], bot1[1], bot2[0], bot2[1]);

  // 2. Rolled Metal Collar Rim at Open Mouth (u2 - 6 to u2 + 2)
  for (let a = THETA_BOT; a <= THETA_TOP; a += 2.5) {
    let p1 = vwPoint(u2 - 6, vc, wc, rBody * 1.025, a);
    let p2 = vwPoint(u2 + 1, vc, wc, rBody * 1.025, a);
    let rimSpec = exp(-pow((a - (-18)) / 15, 2));
    if (rimSpec > 0.55) {
      brush.set("2H", PAL.leadLight, 0.35);
    } else if (a > 35) {
      brush.set("2B", PAL.leadBlack, 0.55);
    } else {
      brush.set("HB", PAL.leadDark, 0.45);
    }
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function drawReceptacleDarkCavity(u2, vc, wc, rBody) {
  let rInner = rBody * 0.92;

  // 1. Deep dark charcoal/lead wash inside the open mouth of the receptacle
  brush.noStroke();
  brush.wash(PAL.leadDark, 235);
  brush.beginShape(0);
  for (let i = 0; i <= 36; i++) {
    let p = vwPoint(u2, vc, wc, rInner, (i / 36) * 360);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Deeper shadow core in the upper/left recess of the cavity
  brush.fillBleed(0.08, "in");
  brush.fill(PAL.leadBlack, 190);
  brush.beginShape(0);
  for (let i = 0; i <= 32; i++) {
    let a = (i / 32) * 360;
    let r = rInner * (0.85 + 0.12 * cos(a - 140));
    let p = vwPoint(u2 - 8, vc - 4, wc - 4, r, a);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noFill();

  // 2. Dense Cross-Hatched Charcoal & 2B Strokes inside the cavity for velvety depth
  for (let i = 0; i < 85; i++) {
    let a1 = random(0, 360);
    let a2 = a1 + random(110, 230);
    let p1 = vwPoint(u2 - random(0, 12), vc, wc, rInner * random(0.65, 0.98), a1);
    let p2 = vwPoint(u2 - random(0, 12), vc, wc, rInner * random(0.65, 0.98), a2);
    brush.set(i % 2 === 0 ? "charcoal" : "2B", PAL.leadBlack, random(0.45, 0.78));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 3. Burnished Metal Rim Face (between rInner and rBody * 1.025 at u2)
  // Bright metallic bevel highlight on the rim face
  for (let i = 0; i < 48; i++) {
    let a1 = (i / 48) * 360;
    let a2 = ((i + 1) / 48) * 360;
    let pOut1 = vwPoint(u2, vc, wc, rBody * 1.02, a1);
    let pOut2 = vwPoint(u2, vc, wc, rBody * 1.02, a2);
    let pIn1 = vwPoint(u2, vc, wc, rInner, a1);
    let pIn2 = vwPoint(u2, vc, wc, rInner, a2);

    // Highlight along the upper-left and lower-right bevel
    let gleam = abs(cos(a1 + 35));
    brush.set("HB", gleam > 0.65 ? PAL.leadLight : PAL.leadDark, 0.50);
    brush.line(pOut1[0], pOut1[1], pOut2[0], pOut2[1]);
    brush.set("2B", PAL.leadBlack, 0.55);
    brush.line(pIn1[0], pIn1[1], pIn2[0], pIn2[1]);

    if (gleam > 0.6) {
      brush.set("2H", PAL.bristol, 0.45);
      brush.line(
        (pOut1[0] + pIn1[0]) * 0.5, (pOut1[1] + pIn1[1]) * 0.5,
        (pOut2[0] + pIn2[0]) * 0.5, (pOut2[1] + pIn2[1]) * 0.5
      );
    }
  }
}

// =============================================================================
// 6. HYPERREAL CURLED CEDAR SHAVINGS, YELLOW LACQUER & LEAD TIPS
// =============================================================================
function drawSingleCedarShaving(cx, cy, radius, startAng, spanAng, tiltX, tiltY, woodVariant, hasYellow = true) {
  // 1. Cast shadow directly beneath the wood curl
  brush.noStroke();
  brush.fillBleed(0.06, "out");
  brush.fill(PAL.leadDark, 75);
  brush.beginShape(0.4);
  for (let i = 0; i <= 14; i++) {
    let a = lerp(startAng, startAng + spanAng, i / 14);
    let rOut = radius * (0.88 + 0.12 * sin(i * 55));
    brush.vertex(
      cx + 4 + cos(a) * rOut * tiltX,
      cy + 6 + sin(a) * rOut * tiltY
    );
  }
  for (let i = 14; i >= 0; i--) {
    let a = lerp(startAng, startAng + spanAng, i / 14);
    let rIn = radius * 0.22;
    brush.vertex(
      cx + 3 + cos(a) * rIn * tiltX,
      cy + 4 + sin(a) * rIn * tiltY
    );
  }
  brush.endShape(true);
  brush.noFill();

  // 2. Build the Scalloped Helical Wood Ribbon (5 to 7 hexagonal pencil facets)
  let nLobes = 6;
  let steps = 30;
  let outerPts = [];
  let innerPts = [];
  let lacquerStrips = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = lerp(startAng, startAng + spanAng, t);
    // Spiral expansion + hexagonal scalloped outer lobes
    let spiral = 0.76 + 0.28 * t;
    let scallop = 1.0 + 0.11 * abs(sin(t * nLobes * 180));
    let rOut = radius * spiral * scallop;
    let rIn = radius * (0.16 + 0.12 * t);

    // 3D conical lift offset
    let lift = sin(t * 180) * radius * 0.16;

    let ox = cx + cos(a) * rOut * tiltX;
    let oy = cy + sin(a) * rOut * tiltY - lift;
    let ix = cx + cos(a) * rIn * tiltX;
    let iy = cy + sin(a) * rIn * tiltY - lift * 0.3;

    outerPts.push([ox, oy, a, rOut]);
    innerPts.push([ix, iy, a, rIn]);
  }

  // Opaque base wash in warm/muted cedar earth tone
  let baseCol = woodVariant === 0 ? PAL.cedarWarm : (woodVariant === 1 ? PAL.cedarMid : PAL.cedarLight);
  let shadeCol = woodVariant === 0 ? PAL.cedarDark : (woodVariant === 1 ? PAL.cedarDeep : PAL.cedarMid);

  brush.noStroke();
  brush.wash(baseCol, 235);
  brush.beginShape(0);
  for (let p of outerPts) brush.vertex(p[0], p[1]);
  for (let i = innerPts.length - 1; i >= 0; i--) brush.vertex(innerPts[i][0], innerPts[i][1]);
  brush.endShape(true);
  brush.noWash();

  // Shaded half of the conical curl (watercolor bleed for 3D wood modeling)
  brush.fillBleed(0.05, "in");
  brush.fill(shadeCol, 115);
  brush.beginShape(0);
  let halfIdx = Math.floor(steps * 0.55);
  for (let i = 0; i <= halfIdx; i++) brush.vertex(outerPts[i][0], outerPts[i][1]);
  for (let i = halfIdx; i >= 0; i--) brush.vertex(innerPts[i][0], innerPts[i][1]);
  brush.endShape(true);
  brush.noFill();

  // 3. Radial Fibrous Cedar Wood Grain & Tiny V-Notch Splits between Scallops
  for (let i = 0; i <= steps; i++) {
    let op = outerPts[i];
    let ip = innerPts[i];
    let t = i / steps;
    let isSunlit = sin(op[2] + 40) > 0.15;

    // Fine wood grain fibers radiating from inner curl to scalloped outer edge
    if (i % 2 === 0) {
      brush.set("cpencil", isSunlit ? PAL.cedarPale : PAL.cedarDeep, random(0.28, 0.45));
    } else {
      brush.set("2H", isSunlit ? PAL.cedarMid : PAL.cedarDark, random(0.25, 0.38));
    }
    brush.line(
      lerp(ip[0], op[0], 0.12), lerp(ip[1], op[1], 0.12),
      lerp(ip[0], op[0], 0.94), lerp(ip[1], op[1], 0.94)
    );

    // Occasional radial split crack at scallop valleys
    if (i > 3 && i < steps - 3 && i % 6 === 0) {
      brush.set("rotring", PAL.leadDark, 0.32);
      brush.line(op[0], op[1], lerp(op[0], ip[0], 0.42), lerp(op[1], ip[1], 0.42));
    }
  }

  // 4. Yellow Lacquer Outer Rim along the Hexagonal Scalloped Edge!
  if (hasYellow) {
    for (let i = 0; i < steps; i++) {
      let p1 = outerPts[i];
      let p2 = outerPts[i + 1];
      let in1 = [lerp(p1[0], innerPts[i][0], 0.13), lerp(p1[1], innerPts[i][1], 0.13)];
      let in2 = [lerp(p2[0], innerPts[i + 1][0], 0.13), lerp(p2[1], innerPts[i + 1][1], 0.13)];

      let lit = sin(p1[2] + 45) > 0;
      let lacCol = lit ? PAL.lacquerBright : PAL.lacquerMid;

      brush.noStroke();
      brush.wash(lacCol, 240);
      brush.beginShape(0);
      brush.vertex(p1[0], p1[1]);
      brush.vertex(p2[0], p2[1]);
      brush.vertex(in2[0], in2[1]);
      brush.vertex(in1[0], in1[1]);
      brush.endShape(true);
      brush.noWash();

      // Bright yellow-gold highlight or dark edge on the lacquer facet
      brush.set("cpencil", lit ? PAL.lacquerLight : PAL.lacquerDark, 0.42);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Crisp outer contour & inner graphite-stained eye of the shaving
  brush.set("HB", PAL.cedarDeep, 0.38);
  drawTechPolyline(outerPts.map(p => [p[0], p[1]]), false);

  // 5. Dark Graphite Collar Ring & Lead Smudge at the tight inner eye of the curl
  for (let i = 0; i < steps; i++) {
    let ip1 = innerPts[i];
    let ip2 = innerPts[i + 1];
    let mid1 = [lerp(ip1[0], outerPts[i][0], 0.18), lerp(ip1[1], outerPts[i][1], 0.18)];
    brush.set("2B", PAL.leadBlack, 0.58);
    brush.line(ip1[0], ip1[1], ip2[0], ip2[1]);
    brush.set("HB", PAL.leadDark, 0.42);
    brush.line(ip1[0], ip1[1], mid1[0], mid1[1]);
  }
}

function drawAllCedarShavingsAndDebris(u2, vc, wc, rBody) {
  let mouthCenter = iso(u2, vc, wc);
  let mx = mouthCenter[0];
  let my = mouthCenter[1];

  // 1. Shavings Packed Inside the Open Cavity of the Receptacle (partially shadowed)
  let cavityShavings = [
    { dx: -18, dy: -28, r: 34, sa: 20,  sp: 255, tx: 0.85, ty: 0.92, wv: 1, y: true },
    { dx: 16,  dy: -34, r: 30, sa: 140, sp: 240, tx: 0.78, ty: 0.88, wv: 0, y: true },
    { dx: -26, dy: 8,   r: 36, sa: -40, sp: 270, tx: 0.82, ty: 0.90, wv: 1, y: true },
    { dx: 12,  dy: -4,  r: 38, sa: 75,  sp: 290, tx: 0.88, ty: 0.84, wv: 2, y: true },
    { dx: -8,  dy: 28,  r: 35, sa: 190, sp: 260, tx: 0.90, ty: 0.80, wv: 0, y: true },
    { dx: 24,  dy: 22,  r: 32, sa: -15, sp: 245, tx: 0.80, ty: 0.86, wv: 1, y: true }
  ];

  for (let s of cavityShavings) {
    drawSingleCedarShaving(mx + s.dx, my + s.dy, s.r, s.sa, s.sp, s.tx, s.ty, s.wv, s.y);
  }

  // Re-glaze top-left cavity edge shadow over recessed shavings so they feel tucked inside the drum
  brush.noStroke();
  brush.fillBleed(0.10, "out");
  brush.fill(PAL.leadBlack, 95);
  brush.beginShape(0.4);
  for (let a = 150; a <= 310; a += 20) {
    let p = vwPoint(u2 - 2, vc, wc, rBody * 0.90, a);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noFill();

  // 2. Hero Shavings Spilling Over the Rim and Tumbling Across the Bristol Sheet
  let spilledShavings = [
    // Perched right on the lower mouth lip
    { dx: 4,   dy: 46,  r: 42, sa: 30,  sp: 305, tx: 0.92, ty: 0.82, wv: 0, y: true },
    { dx: 34,  dy: 38,  r: 38, sa: 165, sp: 275, tx: 0.86, ty: 0.88, wv: 2, y: true },
    { dx: -24, dy: 58,  r: 34, sa: -55, sp: 240, tx: 0.88, ty: 0.78, wv: 1, y: true },

    // Mid-spill pile directly below & right of the receptacle
    { dx: 22,  dy: 84,  r: 44, sa: 110, sp: 315, tx: 0.95, ty: 0.78, wv: 0, y: true },
    { dx: 64,  dy: 74,  r: 39, sa: -25, sp: 285, tx: 0.88, ty: 0.84, wv: 2, y: true },
    { dx: -12, dy: 96,  r: 36, sa: 210, sp: 255, tx: 0.92, ty: 0.75, wv: 1, y: true },
    { dx: 48,  dy: 112, r: 41, sa: 45,  sp: 295, tx: 0.94, ty: 0.80, wv: 0, y: true },

    // Trailing shavings & half-curls further down-right in the graphite dust
    { dx: 96,  dy: 98,  r: 33, sa: 145, sp: 230, tx: 0.90, ty: 0.76, wv: 2, y: true },
    { dx: 82,  dy: 138, r: 37, sa: -70, sp: 265, tx: 0.92, ty: 0.74, wv: 1, y: true },
    { dx: 18,  dy: 134, r: 29, sa: 15,  sp: 205, tx: 0.88, ty: 0.72, wv: 0, y: true },
    { dx: 128, dy: 128, r: 28, sa: 85,  sp: 195, tx: 0.94, ty: 0.72, wv: 2, y: true },
    { dx: 56,  dy: 156, r: 25, sa: 200, sp: 180, tx: 0.90, ty: 0.70, wv: 1, y: false },
    { dx: 152, dy: 158, r: 22, sa: -30, sp: 165, tx: 0.86, ty: 0.70, wv: 0, y: true }
  ];

  for (let s of spilledShavings) {
    drawSingleCedarShaving(mx + s.dx, my + s.dy, s.r, s.sa, s.sp, s.tx, s.ty, s.wv, s.y);
  }

  // 3. Two Snapped Conical Graphite Pencil Lead Tips lying in the dust
  let tips = [
    { x: mx + 74,  y: my + 122, ang: 24,  len: 22, w: 4.8 },
    { x: mx + 116, y: my + 150, ang: -18, len: 17, w: 4.2 }
  ];
  for (let tp of tips) {
    let ca = cos(tp.ang), sa = sin(tp.ang);
    let nx = -sa, ny = ca;
    let tipApex = [tp.x + ca * tp.len, tp.y + sa * tp.len];
    let base1 = [tp.x + nx * tp.w, tp.y + ny * tp.w];
    let base2 = [tp.x - nx * tp.w, tp.y - ny * tp.w];

    // Cast shadow
    brush.set("2B", PAL.leadDark, 0.55);
    brush.line(base2[0] + 2, base2[1] + 3, tipApex[0] + 2, tipApex[1] + 3);

    // Solid black graphite cone
    brush.noStroke();
    brush.wash(PAL.leadBlack, 250);
    brush.beginShape(0);
    brush.vertex(base1[0], base1[1]);
    brush.vertex(tipApex[0], tipApex[1]);
    brush.vertex(base2[0], base2[1]);
    brush.endShape(true);
    brush.noWash();

    // Silvery specular graphite sheen line along the cone ridge
    brush.set("2H", PAL.leadGleam, 0.38);
    brush.line(
      lerp(base1[0], base2[0], 0.3), lerp(base1[1], base2[1], 0.3),
      tipApex[0], tipApex[1]
    );
  }

  // 4. Scattered Flecks of Yellow Pencil Lacquer & Tiny Cedar Wood Splinters
  for (let i = 0; i < 62; i++) {
    let t = pow(random(), 1.2);
    let fx = mx + random(-40, 65) + t * 145 + random(-18, 18);
    let fy = my + random(20, 85) + t * 115 + random(-15, 15);
    let flen = random(3.5, 9.5) * (1 - t * 0.35);
    let fang = random(0, 360);
    let fdx = cos(fang) * flen;
    let fdy = sin(fang) * flen;
    let fnx = -sin(fang) * random(1.5, 3.2);
    let fny = cos(fang) * random(1.5, 3.2);

    let isLacquer = random() < 0.68;
    let fCol = isLacquer
      ? (random() < 0.6 ? PAL.lacquerBright : (random() < 0.85 ? PAL.lacquerMid : PAL.lacquerLight))
      : (random() < 0.5 ? PAL.cedarWarm : PAL.cedarDark);

    // Tiny shadow under fleck
    brush.set("HB", PAL.leadMid, 0.30);
    brush.line(fx + 1.2, fy + 1.8, fx + fdx + 1.2, fy + fdy + 1.8);

    // Opaque fleck chip
    brush.noStroke();
    brush.wash(fCol, 245);
    brush.beginShape(0);
    brush.vertex(fx, fy);
    brush.vertex(fx + fdx, fy + fdy);
    brush.vertex(fx + fdx + fnx, fy + fdy + fny);
    brush.vertex(fx + fnx, fy + fny);
    brush.endShape(true);
    brush.noWash();

    // Crisp micro-edge
    brush.set("cpencil", isLacquer ? PAL.lacquerDark : PAL.cedarDeep, 0.28);
    brush.line(fx, fy, fx + fdx, fy + fdy);
  }
}

