function drawTechString(str, x, y, charH = 13, weight = 0.44, tracking = 0.82) {
  brush.set("rotring", PAL.ink, weight);
  let charW = charH * 0.66;
  let stepX = charW + charH * 0.28 * tracking;
  let curX = x;

  for (let ch of str.toUpperCase()) {
    if (ch === " ") {
      curX += stepX * 0.75;
      continue;
    }
    let g = GLYPHS[ch];
    if (g) {
      for (let strokePath of g) {
        for (let i = 0; i < strokePath.length - 1; i++) {
          let p1 = strokePath[i];
          let p2 = strokePath[i + 1];
          brush.line(
            curX + p1[0] * charW, y + p1[1] * charH,
            curX + p2[0] * charW, y + p2[1] * charH
          );
        }
      }
    }
    curX += (ch === "." || ch === "I" || ch === "1") ? stepX * 0.72 : stepX;
  }
}

function drawLeaderCallout(tx, ty, kx, ky, ex, ey, labelText, alignRight = false) {
  brush.set("rotring", PAL.ink, 0.38);

  // Leader line from target (tx, ty) to knee (kx, ky) to horizontal shelf (ex, ey)
  brush.line(tx, ty, kx, ky);
  brush.line(kx, ky, ex, ey);

  // Crisp technical arrowhead at (tx, ty)
  let ang = atan2(ky - ty, kx - tx);
  let aLen = 8.5;
  brush.line(tx, ty, tx + cos(ang + 18) * aLen, ty + sin(ang + 18) * aLen);
  brush.line(tx, ty, tx + cos(ang - 18) * aLen, ty + sin(ang - 18) * aLen);

  // Small datum point ring at target
  brush.circle(tx, ty, 1.8);

  // Draw the FIG. label text adjacent to the horizontal shelf
  let lx = alignRight ? ex + 8 : ex - labelText.length * 10.2 - 4;
  let ly = ey - 6.5;
  drawTechString(labelText, lx, ly, 12.5, 0.44);
}

