// ============================================================================
// GEOMETRY & POLYLINE HELPERS
// ============================================================================

function rotPt(x, y, cx, cy, angDeg) {
  let r = angDeg * Math.PI / 180;
  let c = Math.cos(r), s = Math.sin(r);
  let dx = x - cx, dy = y - cy;
  return [cx + dx * c - dy * s, cy + dx * s + dy * c];
}

function drawPolyShape(pts, closeShape = true, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape ? CLOSE : undefined);
}

function chaikinSmooth(pts, iterations = 1, closed = true) {
  let curr = pts;
  for (let it = 0; it < iterations; it++) {
    let next = [];
    let n = curr.length;
    let limit = closed ? n : n - 1;
    if (!closed) next.push(curr[0]);
    for (let i = 0; i < limit; i++) {
      let p0 = curr[i];
      let p1 = curr[(i + 1) % n];
      next.push([0.75 * p0[0] + 0.25 * p1[0], 0.75 * p0[1] + 0.25 * p1[1]]);
      next.push([0.25 * p0[0] + 0.75 * p1[0], 0.25 * p0[1] + 0.75 * p1[1]]);
    }
    if (!closed) next.push(curr[n - 1]);
    curr = next;
  }
  return curr;
}

// ============================================================================
// 1. COLD SLATE BOARD & STUDIO GROUND
// ============================================================================

function drawColdSlateBoard(cx, cy) {
  brush.noField();
  brush.noStroke();

  // Subtle icy studio wash at top-left and bottom-left outside the slate slab
  brush.fill(PAL.bgMid, 85);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.55, 0.35);
  drawPolyShape([[0, 0], [1200, 0], [1200, 220], [0, 340]], true);
  drawPolyShape([[0, 820], [1200, 1080], [1200, 1200], [0, 1200]], true);
  brush.noFill();

  // Main slate slab polygon (angled riven stone slab occupying most of canvas)
  const slateTop = [
    [-20, 275], [240, 235], [580, 185], [920, 142], [1220, 110]
  ];
  const slateBot = [
    [1220, 1085], [890, 1038], [560, 975], [270, 912], [65, 855], [-20, 810]
  ];
  const slatePoly = [...slateTop, ...slateBot];

  // Riven front thickness bevel of the slate slab (along the lower edge)
  const bevelBot = slateBot.map((p, idx) => [
    p[0] - 4,
    p[1] + 38 + 8 * Math.sin(idx * 1.7)
  ]).reverse();
  const slateSidePoly = [...slateBot, ...bevelBot];

  // Cast shadow of the slate slab itself onto the cold table
  const slabDropShadow = bevelBot.map(p => [p[0] - 12, p[1] + 22]);
  brush.wash(PAL.shadowDeep, 130);
  drawPolyShape([...bevelBot, ...slabDropShadow.slice().reverse()], true);

  // Dark riven front edge of slate
  brush.wash(PAL.slateDark, 245);
  drawPolyShape(slateSidePoly, true);

  // Base solid wash for the slate board
  brush.wash(PAL.slateBase, 242);
  drawPolyShape(slatePoly, true);

  // Layered watercolor mineral washes across the slate slab
  const washZones = [
    { x: 180, y: 460, rx: 320, ry: 170, col: PAL.slateMid, op: 85, bleed: 0.18 },
    { x: 460, y: 690, rx: 360, ry: 210, col: PAL.slateDark, op: 95, bleed: 0.15 },
    { x: 250, y: 640, rx: 240, ry: 140, col: PAL.slateLight, op: 55, bleed: 0.22 },
    { x: 760, y: 310, rx: 340, ry: 150, col: PAL.slateMid, op: 75, bleed: 0.16 },
    { x: 640, y: 860, rx: 310, ry: 140, col: PAL.slateDark, op: 110, bleed: 0.14 }
  ];

  for (let z of washZones) {
    let pts = [];
    for (let a = 0; a < 360; a += 18) {
      let rad = a * Math.PI / 180;
      let n = 0.8 + 0.35 * noise(z.x * 0.01 + Math.cos(rad), z.y * 0.01 + Math.sin(rad));
      pts.push([
        z.x + Math.cos(rad) * z.rx * n,
        z.y + Math.sin(rad) * z.ry * n
      ]);
    }
    brush.fill(z.col, z.op);
    brush.fillBleed(z.bleed, "out");
    brush.fillTexture(0.75, 0.65);
    drawPolyShape(pts, true);
  }
  brush.noFill();
  brush.noWash();

  // Fine directional slate foliation & cleavage lines (angled along ~ -8 deg)
  brush.hatchStyle("2H", PAL.slateDark, 0.45);
  brush.hatch(9, -8, { rand: 0.08, gradient: 0.3 });
  drawPolyShape(slatePoly, true);
  brush.noHatch();

  brush.hatchStyle("2H", PAL.slateLight, 0.35);
  brush.hatch(14, 15, { rand: 0.12, gradient: 0.4 });
  drawPolyShape(slatePoly, true);
  brush.noHatch();

  // Riven cleavage steps & stepped fractures along the lower slate edge
  for (let i = 0; i < slateBot.length - 1; i++) {
    let p0 = slateBot[i], p1 = slateBot[i + 1];
    // Chipped pale highlight along top of the riven edge
    brush.set("2H", PAL.slateQuartz, 0.55);
    brush.line(p0[0], p0[1], p1[0], p1[1]);

    // Stepped horizontal cleavage striation on the vertical slab face
    for (let s = 1; s <= 4; s++) {
      let f = s / 5;
      brush.set("rotring", s % 2 === 0 ? PAL.shadowDeep : PAL.slateHighlight, 0.4);
      brush.line(p0[0], p0[1] + f * 34, p1[0], p1[1] + f * 34);
    }
  }

  // Fine mineral quartz veins & wet knife score marks on the left slate surface
  const quartzVeins = [
    [[40, 410], [180, 435], [340, 448], [520, 472]],
    [[90, 585], [235, 560], [395, 548]],
    [[140, 745], [310, 780], [490, 825], [670, 880]],
    [[290, 320], [460, 355], [610, 378]]
  ];
  for (let v of quartzVeins) {
    brush.set("rotring", PAL.slateHighlight, 0.32);
    brush.spline(v, 0.35);
    let offsetV = v.map(p => [p[0] + 1.5, p[1] + 2.0]);
    brush.set("rotring", PAL.slateDark, 0.35);
    brush.spline(offsetV, 0.35);
  }

  // Subtle knife cut marks where the cabbage was just sliced
  for (let k = 0; k < 7; k++) {
    let x1 = 260 + k * 28 + random(-10, 10);
    let y1 = 620 + k * 22 + random(-8, 8);
    let len = random(85, 190);
    let ang = (-18 + random(-4, 4)) * Math.PI / 180;
    brush.set("rotring", PAL.slateQuartz, 0.28);
    brush.line(x1, y1, x1 + Math.cos(ang) * len, y1 + Math.sin(ang) * len);
    brush.set("rotring", PAL.shadowDeep, 0.32);
    brush.line(x1, y1 + 1.5, x1 + Math.cos(ang) * len, y1 + Math.sin(ang) * len + 1.5);
  }
}

// ============================================================================
// 2. CAST SHADOW & WET SLATE REFLECTION
// ============================================================================

function drawCabbageCastShadow(cx, cy) {
  brush.noStroke();

  // Multi-layered cold cast shadow stretching left from beneath the cabbage
  const shadowLayers = [
    { ox: -250, oy: 115, rx: 380, ry: 175, col: PAL.slateDark, op: 120, bleed: 0.22 },
    { ox: -190, oy: 105, rx: 310, ry: 145, col: PAL.shadowDeep, op: 155, bleed: 0.14 },
    { ox: -120, oy: 95, rx: 245, ry: 118, col: PAL.blackGreen, op: 190, bleed: 0.08 },
    { ox: -55, oy: 85, rx: 195, ry: 95, col: "#020709", op: 230, bleed: 0.03 }
  ];

  for (let sh of shadowLayers) {
    let pts = [];
    for (let a = 0; a < 360; a += 12) {
      let rad = a * Math.PI / 180;
      let sc = 0.92 + 0.14 * Math.sin(rad * 3) + 0.08 * noise(Math.cos(rad) * 2, Math.sin(rad) * 2);
      let px = cx + sh.ox + Math.cos(rad) * sh.rx * sc;
      let py = cy + sh.oy + Math.sin(rad) * sh.ry * sc;
      pts.push(rotPt(px, py, cx + sh.ox, cy + sh.oy, -10));
    }
    brush.fill(sh.col, sh.op);
    brush.fillBleed(sh.bleed, "out");
    brush.fillTexture(0.65, 0.45);
    drawPolyShape(pts, true);
  }

  // Subtle green wet reflection on the polished slate directly beneath the cut face
  let reflPts = [];
  for (let a = 0; a < 360; a += 15) {
    let rad = a * Math.PI / 180;
    reflPts.push([
      cx - 95 + Math.cos(rad) * 185,
      cy + 275 + Math.sin(rad) * 62
    ]);
  }
  brush.fill(PAL.bottleDark, 90);
  brush.fillBleed(0.2, "out");
  brush.fillTexture(0.5, 0.3);
  drawPolyShape(reflPts, true);

  brush.noFill();
}

// ============================================================================
// 3. OUTER CRINKLED SAVOY LEAVES (HYPERREAL BLISTERS & VEINING)
// ============================================================================

function drawOuterSavoyCrown(cx, cy, tilt) {
  // 9 overlapping outer wrapper leaves framing the cut face
  // Heavily developed on the left, top, and bottom; cropped on the right edge
  const leaves = [
    // Back-most broad dark leaves
    { ang: 152, dist: 230, len: 295, wid: 265, curl: -12, light: 0.72 },
    { ang: 198, dist: 235, len: 290, wid: 255, curl: 14, light: 0.85 },
    { ang: 112, dist: 225, len: 265, wid: 245, curl: -18, light: 0.62 },
    { ang: 245, dist: 225, len: 270, wid: 255, curl: 10, light: 0.95 },
    { ang: 65,  dist: 230, len: 240, wid: 230, curl: -8, light: 0.55 },
    { ang: 295, dist: 220, len: 250, wid: 240, curl: 16, light: 0.88 },
    // Prominent middle-left and upper-left wrapper leaves showing full bullate detail
    { ang: 174, dist: 195, len: 275, wid: 250, curl: 6,  light: 0.92 },
    { ang: 222, dist: 198, len: 260, wid: 240, curl: -8, light: 1.00 },
    { ang: 132, dist: 195, len: 245, wid: 235, curl: -14, light: 0.75 }
  ];

  for (let idx = 0; idx < leaves.length; idx++) {
    drawSingleSavoyLeaf(cx, cy, leaves[idx], idx);
  }
}

function drawSingleSavoyLeaf(cx, cy, spec, leafIdx) {
  const baseAng = spec.ang * Math.PI / 180;
  const dirX = Math.cos(baseAng);
  const dirY = Math.sin(baseAng);
  const perpX = -dirY;
  const perpY = dirX;

  const startX = cx + dirX * (spec.dist * 0.52);
  const startY = cy + dirY * (spec.dist * 0.52);
  const fullLen = spec.len + spec.dist * 0.48;

  // Helper to map local leaf coordinates (s along midrib [0..1], t across blade [-1..1]) to canvas
  function leafPoint(s, t) {
    let curveOffset = Math.sin(s * Math.PI * 0.85) * spec.curl * 1.4;
    // Broad fan shape of a cabbage leaf with ruffled scalloped margin
    let env = Math.pow(Math.sin(Math.min(1, s * 1.12) * Math.PI * 0.78), 0.65);
    let scallop = 1.0
      + 0.08 * Math.sin(t * 14 + leafIdx * 2.1)
      + 0.05 * Math.cos(s * 18 - t * 9);
    let w = spec.wid * env * scallop;
    let archDrop = (t * t) * 38 * s; // 3D cup curvature of leaf blade
    let x = startX + dirX * (s * fullLen - archDrop) + perpX * (t * w + curveOffset);
    let y = startY + dirY * (s * fullLen - archDrop) + perpY * (t * w + curveOffset);
    return [x, y];
  }

  // 1. Leaf silhouette polygon
  let boundary = [];
  const N_EDGE = 28;
  for (let i = 0; i <= N_EDGE; i++) {
    boundary.push(leafPoint(0.12 + 0.88 * (i / N_EDGE), -1.0));
  }
  for (let i = -N_EDGE; i <= N_EDGE; i++) {
    let t = i / N_EDGE;
    let r = 0.035 * Math.sin(t * 22 + leafIdx);
    boundary.push(leafPoint(1.0 + r, t));
  }
  for (let i = N_EDGE; i >= 0; i--) {
    boundary.push(leafPoint(0.12 + 0.88 * (i / N_EDGE), 1.0));
  }

  // Deep shadow under-wash for leaf separation
  let underBoundary = boundary.map(p => [p[0] - 5, p[1] + 7]);
  brush.noStroke();
  brush.wash(PAL.blackGreen, 210);
  drawPolyShape(underBoundary, true);

  // Dark bottle-green base fill of the leaf
  brush.wash(PAL.bottleDark, 248);
  drawPolyShape(boundary, true);

  // Watercolor viridian undertone
  brush.fill(PAL.viridianDeep, 135);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.7, 0.6);
  drawPolyShape(boundary, true);
  brush.noFill();

  // 2. Bullate Blisters (Savoy Crinkles) between Lateral Veins
  // Divide the leaf blade into ribs (s-bands) and lateral cells (t-bands)
  const S_BANDS = 7;
  const T_CELLS = 5;

  for (let side = -1; side <= 1; side += 2) {
    for (let i = 0; i < S_BANDS; i++) {
      let s0 = 0.22 + (i / S_BANDS) * 0.72;
      let s1 = 0.22 + ((i + 0.92) / S_BANDS) * 0.72;

      for (let j = 0; j < T_CELLS; j++) {
        let t0 = side * (0.09 + (j / T_CELLS) * 0.85);
        let t1 = side * (0.09 + ((j + 0.9) / T_CELLS) * 0.85);

        // Veins angle forward toward the leaf margin: shift s outward with |t|
        let slant0 = Math.abs(t0) * 0.16;
        let slant1 = Math.abs(t1) * 0.16;

        let sa0 = Math.min(0.98, s0 + slant0);
        let sa1 = Math.min(0.99, s1 + slant0);
        let sb0 = Math.min(0.98, s0 + slant1);
        let sb1 = Math.min(0.99, s1 + slant1);

        // Build rounded blister polygon inside this vein cell
        let sc = 0.5 * (sa0 + sb1);
        let tc = 0.5 * (t0 + t1);
        let ds = ( sa1 - sa0 ) * 0.48;
        let dt = Math.abs(t1 - t0) * 0.48;

        let blisterPts = [];
        let domeMidPts = [];
        let domeHighPts = [];

        // Light comes from upper-left (-0.7, -0.7)
        let centerCanvas = leafPoint(sc, tc);

        for (let a = 0; a < 360; a += 40) {
          let rad = a * Math.PI / 180;
          let wob = 0.88 + 0.22 * noise(leafIdx * 10 + i * 3 + Math.cos(rad), j * 3 + Math.sin(rad));
          let sp = sc + Math.cos(rad) * ds * wob + Math.sin(rad) * ds * 0.22 * side;
          let tp = tc + Math.sin(rad) * dt * wob;
          sp = Math.min(0.985, Math.max(0.15, sp));
          tp = Math.min(0.98, Math.max(-0.98, tp));

          let p = leafPoint(sp, tp);
          blisterPts.push(p);

          // Mid-dome shifted slightly toward top-left light
          domeMidPts.push([
            centerCanvas[0] + (p[0] - centerCanvas[0]) * 0.68 - 2.2,
            centerCanvas[1] + (p[1] - centerCanvas[1]) * 0.68 - 2.2
          ]);

          // Crown highlight of blister
          domeHighPts.push([
            centerCanvas[0] + (p[0] - centerCanvas[0]) * 0.36 - 3.5,
            centerCanvas[1] + (p[1] - centerCanvas[1]) * 0.36 - 3.5
          ]);
        }

        // a) Dark recessed crease around blister
        brush.set("rotring", PAL.blackGreen, 0.55);
        brush.wash(PAL.abyssGreen, 215);
        drawPolyShape(blisterPts, true);

        // b) Viridian blister body
        brush.noStroke();
        let midCol = (i + j) % 2 === 0 ? PAL.viridian : PAL.viridianDeep;
        brush.wash(midCol, 210);
        drawPolyShape(domeMidPts, true);

        // c) Mint / glaucous blister highlight crown (stronger on upper-left facing blisters)
        if (spec.light > 0.6) {
          let crownCol = (j < 3 && spec.light > 0.8) ? PAL.mint : PAL.emeraldCool;
          brush.wash(crownCol, Math.floor(155 * spec.light));
          drawPolyShape(domeHighPts, true);

          // Tiny crisp glaucous sheen on peak of prominent blisters
          if ((i + j + leafIdx) % 3 === 0 && spec.light > 0.78) {
            brush.set("2H", PAL.mintPale, 0.45);
            brush.circle(centerCanvas[0] - 3, centerCanvas[1] - 3, 3.2, 0.25);
          }
        }
        brush.noWash();

        // d) Fine curved cross-contour pen lines over the blister dome
        brush.set("rotring", PAL.bottleDark, 0.32);
        brush.arc(centerCanvas[0], centerCanvas[1], 7 + (T_CELLS - j) * 1.8, 290, 85);
      }
    }
  }

  // 3. Raised Branching Vein Network (Midrib + Lateral + Tertiary Veins)
  // Main central midrib tapering from thick pale mint base to fine tip
  let midLeft = [], midRight = [];
  for (let k = 0; k <= 14; k++) {
    let s = 0.14 + (k / 14) * 0.83;
    let halfT = 0.085 * Math.pow(1 - k / 14.5, 1.25) + 0.006;
    midLeft.push(leafPoint(s, -halfT));
    midRight.unshift(leafPoint(s, halfT));
  }
  let midribPoly = [...midLeft, ...midRight];

  // Shadow under midrib
  let midShadow = midribPoly.map(p => [p[0] + 2.5, p[1] + 2.5]);
  brush.noStroke();
  brush.wash(PAL.blackGreen, 190);
  drawPolyShape(midShadow, true);

  // Pale mint / celadon midrib body
  brush.wash(PAL.mintPale, 235);
  drawPolyShape(midribPoly, true);
  brush.noWash();

  // Fine longitudinal vascular striations along midrib
  for (let v = -1; v <= 1; v++) {
    let stripe = [];
    for (let k = 0; k <= 10; k++) {
      let s = 0.16 + (k / 10) * 0.75;
      let t = v * 0.032 * (1 - k / 11);
      stripe.push(leafPoint(s, t));
    }
    brush.set("rotring", v === 0 ? PAL.whiteSpec : PAL.mintDeep, 0.38);
    brush.spline(stripe, 0.3);
  }

  // Lateral Primary & Secondary Veins
  for (let side = -1; side <= 1; side += 2) {
    for (let i = 0; i <= S_BANDS; i++) {
      let sBase = 0.21 + (i / S_BANDS) * 0.70;
      let veinPts = [];
      let shadowPts = [];
      for (let m = 0; m <= 8; m++) {
        let frac = m / 8;
        let t = side * (0.04 + frac * 0.90);
        let s = Math.min(0.98, sBase + frac * 0.16 + 0.015 * Math.sin(frac * Math.PI * 2));
        let pt = leafPoint(s, t);
        veinPts.push(pt);
        shadowPts.push([pt[0] + 1.8, pt[1] + 2.0]);

        // Tertiary Forking Veinlets branching off the lateral vein
        if (m >= 2 && m <= 6 && m % 2 === 0) {
          let forkA = pt;
          let forkB = leafPoint(
            Math.min(0.985, s + 0.045),
            side * Math.min(0.96, Math.abs(t) + 0.08)
          );
          let forkC = leafPoint(
            Math.max(0.18, s - 0.04),
            side * Math.min(0.96, Math.abs(t) + 0.09)
          );
          brush.set("rotring", PAL.bottleDark, 0.35);
          brush.line(forkA[0] + 1.2, forkA[1] + 1.2, forkB[0] + 1.2, forkB[1] + 1.2);
          brush.set("rotring", PAL.mint, 0.36);
          brush.line(forkA[0], forkA[1], forkB[0], forkB[1]);

          brush.set("rotring", PAL.mintDeep, 0.30);
          brush.line(forkA[0], forkA[1], forkC[0], forkC[1]);
        }
      }

      // Draw lateral vein underside shadow
      brush.set("rotring", PAL.blackGreen, 0.55);
      brush.spline(shadowPts, 0.35);

      // Draw raised pale-mint lateral vein
      let wVein = 0.78 * (1 - i / (S_BANDS + 3));
      brush.set("rotring", PAL.mintPale, Math.max(0.35, wVein));
      brush.spline(veinPts, 0.35);
    }
  }

  // Crisp ruffled outer leaf margin highlight and fine dark contour
  brush.set("rotring", PAL.blackGreen, 0.52);
  drawPolyShape(boundary, true);

  let rimHighlight = boundary.slice(N_EDGE, N_EDGE * 3);
  brush.set("rotring", PAL.mint, 0.42);
  drawPolyShape(rimHighlight, false);
}

// ============================================================================
// 4. CUT RIND / OUTER MIDRIB COLLAR AROUND THE CUT SLAB
// ============================================================================

function drawCutCollarMidribs(cx, cy, tilt) {
  // Around the perimeter of the cut face, thick outer leaf stalks/midribs
  // are sliced in cross-section, showing lens-shaped celadon/mint crescents
  const RX = 328, RY = 345;

  // Dark outer wrapper shadow bed just behind the cut face
  let rimBed = [];
  for (let a = 0; a < 360; a += 6) {
    let rad = a * Math.PI / 180;
    let rMod = 1.03 + 0.03 * Math.sin(rad * 7) + 0.02 * Math.cos(rad * 13);
    let u = Math.cos(rad) * RX * rMod;
    let v = Math.sin(rad) * RY * rMod;
    rimBed.push(rotPt(cx + u, cy + v, cx, cy, tilt));
  }
  brush.noStroke();
  brush.wash(PAL.blackGreen, 252);
  drawPolyShape(rimBed, true);

  // Draw 18 crescent-shaped cut midrib cross-sections hugging the outer ring
  const numRibs = 18;
  for (let i = 0; i < numRibs; i++) {
    let aCenter = i * (360 / numRibs) + 8;
    let span = 14 + (i % 3) * 3;
    let rOuter = 1.015 + 0.018 * Math.sin(i * 2.3);
    let rInner = rOuter - (0.045 + 0.025 * Math.pow(Math.sin(aCenter * Math.PI / 180 * 0.5), 2));

    let outerArc = [], innerArc = [];
    for (let s = -span; s <= span; s += 3) {
      let a = (aCenter + s) * Math.PI / 180;
      let f = 1 - Math.pow(s / span, 2); // lens taper at ends
      let ro = rInner + (rOuter - rInner) * (0.5 + 0.5 * f);
      let ri = rInner + (rOuter - rInner) * (0.5 - 0.5 * f);

      outerArc.push(rotPt(cx + Math.cos(a) * RX * ro, cy + Math.sin(a) * RY * ro, cx, cy, tilt));
      innerArc.unshift(rotPt(cx + Math.cos(a) * RX * ri, cy + Math.sin(a) * RY * ri, cx, cy, tilt));
    }
    let crescent = [...outerArc, ...innerArc];

    brush.noStroke();
    brush.wash(i % 2 === 0 ? PAL.mintPale : PAL.mint, 235);
    drawPolyShape(crescent, true);

    brush.set("rotring", PAL.bottleDark, 0.42);
    drawPolyShape(crescent, true);

    // Tiny vascular bundle dots along the center of each cut midrib crescent
    for (let d = -span * 0.55; d <= span * 0.55; d += 4.5) {
      let a = (aCenter + d) * Math.PI / 180;
      let rm = 0.5 * (rOuter + rInner);
      let dp = rotPt(cx + Math.cos(a) * RX * rm, cy + Math.sin(a) * RY * rm, cx, cy, tilt);
      brush.set("rotring", PAL.viridianDeep, 0.48);
      brush.circle(dp[0], dp[1], 1.6, 0.1);
    }
  }
  brush.noWash();
}

// ============================================================================
// 5. MALACHITE-BANDED CUT FACE (ISO-CONTOUR ENGINE + WATERCOLOUR + PEN)
// ============================================================================

// Smooth minimum (log-sum-exp style / polynomial smin) for botryoidal malachite merging
function smin(a, b, k) {
  let h = Math.max(k - Math.abs(a - b), 0.0) / k;
  return Math.min(a, b) - h * h * k * 0.25;
}

// Evaluate the Savoy-Malachite scalar field in normalized cut-face coords (u, v)
// u in [-1.2, 1.2], v in [-1.2, 1.2], where +v is toward the bottom-left stalk base
function evalMalachiteCabbageField(u, v) {
  // 1. Savoy crinkle domain warping (concentric folded leaf waves)
  let r0 = Math.sqrt(u * u + v * v) + 1e-5;
  let ang0 = Math.atan2(v, u);

  // Tangential & radial savoy leaf buckling
  let crinkle1 = 0.036 * Math.sin(ang0 * 11 + r0 * 14) * Math.min(1, r0 * 1.4);
  let crinkle2 = 0.022 * Math.cos(ang0 * 19 - r0 * 22) * Math.min(1, r0 * 1.2);
  let nWarpX = (noise(u * 3.8 + 10, v * 3.8 + 10) - 0.5) * 0.085;
  let nWarpY = (noise(u * 3.8 + 30, v * 3.8 + 30) - 0.5) * 0.085;

  let uw = u + (u / r0) * (crinkle1 + crinkle2) + nWarpX;
  let vw = v + (v / r0) * (crinkle1 + crinkle2) + nWarpY;

  // 2. Outer cabbage head envelope (flattened apple/dome shape indented near stalk)
  let stalkIndent = 0.08 * Math.exp(-Math.pow((ang0 - Math.PI * 0.5) * 2.2, 2));
  let cheekSwell = 0.06 * Math.pow(Math.cos(ang0), 2);
  let headRad = Math.sqrt(uw * uw * 0.94 + vw * vw * 0.98) - cheekSwell + stalkIndent;

  // 3. Internal folded leaf whorls / Malachite "eyes" (7 botanical fold centers)
  const whorls = [
    // Left primary heart fold
    { x: -0.35, y: -0.04, sx: 1.15, sy: 0.95, w: 0.88, twist: 0.35 },
    // Right primary heart fold
    { x:  0.36, y: -0.02, sx: 1.12, sy: 0.95, w: 0.88, twist: -0.35 },
    // Upper central crown whorl
    { x:  0.01, y: -0.46, sx: 0.92, sy: 1.25, w: 0.90, twist: 0.15 },
    // Upper-left secondary fold
    { x: -0.48, y: -0.42, sx: 1.25, sy: 1.15, w: 0.94, twist: 0.40 },
    // Upper-right secondary fold
    { x:  0.48, y: -0.40, sx: 1.25, sy: 1.15, w: 0.94, twist: -0.40 },
    // Lower-left axillary fold beside stalk
    { x: -0.52, y:  0.38, sx: 1.20, sy: 1.10, w: 0.92, twist: -0.25 },
    // Lower-right axillary fold beside stalk
    { x:  0.52, y:  0.38, sx: 1.20, sy: 1.10, w: 0.92, twist: 0.25 }
  ];

  let dWhorls = 10.0;
  for (let i = 0; i < whorls.length; i++) {
    let c = whorls[i];
    let dx = uw - c.x;
    let dy = vw - c.y;
    let locR = Math.sqrt(dx * dx + dy * dy) + 1e-5;
    let locA = Math.atan2(dy, dx) + c.twist * Math.sin(locR * 12);
    // Tightly crinkled local leaf folds inside each malachite eye
    let foldWave = 1.0 + 0.085 * Math.sin(locA * 7 + i * 1.7) + 0.05 * Math.cos(locA * 13 - locR * 18);
    let dist = Math.sqrt(Math.pow(dx * c.sx, 2) + Math.pow(dy * c.sy, 2)) * foldWave * c.w;
    dWhorls = smin(dWhorls, dist, 0.26);
  }

  // 4. Central Stalk / Core Wedge (entering from bottom v = +0.85 up to v = +0.02)
  // Leaves arch around and originate from this central core
  let stalkY = Math.max(0.05, Math.min(0.78, vw));
  let stalkHalfW = 0.08 + 0.14 * ((stalkY - 0.05) / 0.73);
  let dStalk = Math.sqrt(Math.pow(uw / (1.0 + stalkHalfW * 1.8), 2) + Math.pow(vw - stalkY, 2));
  dWhorls = smin(dWhorls, dStalk * 0.95 + 0.08, 0.22);

  // Blend internal multi-whorl field with the overarching outer cabbage boundary
  // so outer layers wrap seamlessly around the entire head while inner layers loop around eyes
  let blend = Math.pow(Math.min(1.0, Math.max(0.0, headRad / 0.98)), 1.65);
  let fieldVal = (1.0 - blend) * (dWhorls * 1.45) + blend * headRad;

  return fieldVal;
}

// Directed Marching Squares contour extractor over a precomputed 2D grid
function extractIsoContours(grid, NX, NY, uMin, uMax, vMin, vMax, threshold, cx, cy, RX, RY, tilt) {
  const segMap = new Map(); // startEdgeKey -> { endKey, x1, y1, x2, y2 }

  function hEdgeKey(i, j) { return j * (NX + 1) + i; }
  function vEdgeKey(i, j) { return 200000 + j * (NX + 1) + i; }

  function gridToCanvas(gx, gy) {
    let u = uMin + (gx / NX) * (uMax - uMin);
    let v = vMin + (gy / NY) * (vMax - vMin);
    return rotPt(cx + u * RX, cy + v * RY, cx, cy, tilt);
  }

  for (let j = 0; j < NY; j++) {
    for (let i = 0; i < NX; i++) {
      let val0 = grid[j][i];
      let val1 = grid[j][i + 1];
      let val2 = grid[j + 1][i + 1];
      let val3 = grid[j + 1][i];

      let b0 = val0 < threshold ? 1 : 0;
      let b1 = val1 < threshold ? 1 : 0;
      let b2 = val2 < threshold ? 1 : 0;
      let b3 = val3 < threshold ? 1 : 0;
      let mask = b0 | (b1 << 1) | (b2 << 2) | (b3 << 3);

      if (mask === 0 || mask === 15) continue;

      // Interpolate edge crossing points
      let tTop = (threshold - val0) / ((val1 - val0) || 1e-7);
      let tRight = (threshold - val1) / ((val2 - val1) || 1e-7);
      let tBot = (threshold - val3) / ((val2 - val3) || 1e-7);
      let tLeft = (threshold - val0) / ((val3 - val0) || 1e-7);

      tTop = Math.max(0.001, Math.min(0.999, tTop));
      tRight = Math.max(0.001, Math.min(0.999, tRight));
      tBot = Math.max(0.001, Math.min(0.999, tBot));
      tLeft = Math.max(0.001, Math.min(0.999, tLeft));

      const E_T = { key: hEdgeKey(i, j),     pt: gridToCanvas(i + tTop, j) };
      const E_R = { key: vEdgeKey(i + 1, j), pt: gridToCanvas(i + 1, j + tRight) };
      const E_B = { key: hEdgeKey(i, j + 1), pt: gridToCanvas(i + tBot, j + 1) };
      const E_L = { key: vEdgeKey(i, j),     pt: gridToCanvas(i, j + tLeft) };

      let pairs = [];
      let avg = 0.25 * (val0 + val1 + val2 + val3);

      switch (mask) {
        case 1:  pairs.push([E_L, E_T]); break;
        case 2:  pairs.push([E_T, E_R]); break;
        case 3:  pairs.push([E_L, E_R]); break;
        case 4:  pairs.push([E_R, E_B]); break;
        case 5:
          if (avg < threshold) { pairs.push([E_L, E_B], [E_R, E_T]); }
          else { pairs.push([E_L, E_T], [E_R, E_B]); }
          break;
        case 6:  pairs.push([E_T, E_B]); break;
        case 7:  pairs.push([E_L, E_B]); break;
        case 8:  pairs.push([E_B, E_L]); break;
        case 9:  pairs.push([E_B, E_T]); break;
        case 10:
          if (avg < threshold) { pairs.push([E_T, E_L], [E_B, E_R]); }
          else { pairs.push([E_T, E_R], [E_B, E_L]); }
          break;
        case 11: pairs.push([E_B, E_R]); break;
        case 12: pairs.push([E_R, E_L]); break;
        case 13: pairs.push([E_R, E_T]); break;
        case 14: pairs.push([E_T, E_L]); break;
      }

      for (let p of pairs) {
        segMap.set(p[0].key, {
          endKey: p[1].key,
          p0: p[0].pt,
          p1: p[1].pt
        });
      }
    }
  }

  // Chain directed segments into closed polygons
  const visited = new Set();
  const loops = [];

  for (let [startKey, firstSeg] of segMap.entries()) {
    if (visited.has(startKey)) continue;
    let pts = [firstSeg.p0];
    let currKey = startKey;
    let safety = 0;

    while (!visited.has(currKey) && safety < 4000) {
      visited.add(currKey);
      let seg = segMap.get(currKey);
      if (!seg) break;
      pts.push(seg.p1);
      currKey = seg.endKey;
      safety++;
    }

    if (pts.length >= 6) {
      // Subsample every 2nd vertex & smooth slightly for crisp organic fluidity
      let decimated = [];
      for (let k = 0; k < pts.length - 1; k += 2) {
        decimated.push(pts[k]);
      }
      if (decimated.length >= 4) {
        loops.push(chaikinSmooth(decimated, 1, true));
      }
    }
  }

  return loops;
}

// Rhythmic Malachite + Savoy Cabbage Leaf Layer Transfer Palette
function getMalachiteBandStyle(idx, total) {
  // Repeating 9-step botanical/malachite cycle:
  // 0: Deep inter-leaf cleft (nearly black)
  // 1: Outer leaf wall (deep bottle green)
  // 2: Mesophyll (viridian deep)
  // 3: Bright viridian band
  // 4: Cool emerald transition
  // 5: Mint vein layer
  // 6: Pale icy mint midrib core
  // 7: Mint vein layer
  // 8: Viridian / bottle green return
  const cycle = [
    { fill: PAL.blackGreen,     pen: PAL.blackGreen,  w: 0.62, isWater: false, op: 248 },
    { fill: PAL.bottleDark,     pen: PAL.blackGreen,  w: 0.42, isWater: true,  op: 215 },
    { fill: PAL.viridianDeep,   pen: PAL.bottleDark,  w: 0.36, isWater: false, op: 235 },
    { fill: PAL.viridian,       pen: PAL.bottleMid,   w: 0.34, isWater: true,  op: 210 },
    { fill: PAL.emeraldCool,    pen: PAL.viridianDeep,w: 0.32, isWater: false, op: 235 },
    { fill: PAL.mint,           pen: PAL.viridian,    w: 0.35, isWater: false, op: 240 },
    { fill: PAL.mintIce,        pen: PAL.mintDeep,    w: 0.40, isWater: false, op: 245 },
    { fill: PAL.mintPale,       pen: PAL.viridian,    w: 0.35, isWater: true,  op: 220 },
    { fill: PAL.bottleMid,      pen: PAL.blackGreen,  w: 0.48, isWater: false, op: 242 }
  ];

  // Vary cycle rhythm slightly so banding has authentic mineral / organic irregularity
  let phase = (idx + Math.floor(idx / 9) * 2) % cycle.length;
  return cycle[phase];
}

function drawMalachiteCutFace(cx, cy, tilt) {
  const RX = 316, RY = 334;
  const NX = 148, NY = 148;
  const uMin = -1.12, uMax = 1.12;
  const vMin = -1.12, vMax = 1.12;

  // Precompute 2D scalar field grid
  const grid = [];
  for (let j = 0; j <= NY; j++) {
    let row = new Float32Array(NX + 1);
    let v = vMin + (j / NY) * (vMax - vMin);
    for (let i = 0; i <= NX; i++) {
      let u = uMin + (i / NX) * (uMax - uMin);
      row[i] = evalMalachiteCabbageField(u, v);
    }
    grid.push(row);
  }

  // Generate 58 concentric iso-contour thresholds from outer cut margin (0.98) to inner eye cores (0.04)
  const NUM_BANDS = 58;
  const allBandLoops = [];

  for (let b = 0; b < NUM_BANDS; b++) {
    let frac = b / (NUM_BANDS - 1);
    // Slightly tighter spacing near outer leaf layers and inner vortex hearts
    let thresh = 0.98 - Math.pow(frac, 0.94) * 0.935;
    let loops = extractIsoContours(grid, NX, NY, uMin, uMax, vMin, vMax, thresh, cx, cy, RX, RY, tilt);
    allBandLoops.push({
      bandIdx: b,
      thresh: thresh,
      loops: loops,
      style: getMalachiteBandStyle(b, NUM_BANDS)
    });
  }

  // Pass 1: Render crisp-edged watercolour & solid mineral wash bands from outermost to innermost
  brush.noStroke();
  for (let b = 0; b < allBandLoops.length; b++) {
    let item = allBandLoops[b];
    let st = item.style;

    for (let poly of item.loops) {
      // Base solid wash for crisp malachite opacity
      brush.wash(st.fill, st.op);
      drawPolyShape(poly, true);
      brush.noWash();

      // Selective watercolour bleed pass for authentic pigment granulation & crisp edge rings
      if (st.isWater && poly.length > 16) {
        brush.fill(st.fill, 115);
        brush.fillBleed(0.045, "in");
        brush.fillTexture(0.72, 0.82);
        drawPolyShape(poly, true);
        brush.noFill();
      }
    }
  }

  // Pass 2: Fine Pen Dividing Lines & Malachite Fibrous Cross-Striations
  for (let b = 0; b < allBandLoops.length; b++) {
    let item = allBandLoops[b];
    let st = item.style;

    for (let poly of item.loops) {
      // Main fine pen dividing line along every leaf/malachite layer boundary
      brush.set("rotring", st.pen, st.w);
      drawPolyShape(poly, true);

      // In pale mint midrib bands (phase 6), add delicate cellular cross-striations & vascular dots
      if (st.fill === PAL.mintIce || st.fill === PAL.mintPale) {
        brush.set("malachite_needle", PAL.whiteSpec, 0.45);
        for (let k = 0; k < poly.length; k += 5) {
          let p0 = poly[k];
          let p1 = poly[(k + 1) % poly.length];
          let dx = p1[0] - p0[0], dy = p1[1] - p0[1];
          let len = Math.sqrt(dx * dx + dy * dy) + 1e-5;
          // Tiny normal tick across the band (fibrous malachite / cabbage cell structure)
          let nx = -dy / len, ny = dx / len;
          brush.line(p0[0] - nx * 2.2, p0[1] - ny * 2.2, p0[0] + nx * 2.2, p0[1] + ny * 2.2);
        }
      }

      // In deep viridian bands, add subtle silky malachite acicular sheen
      if (st.fill === PAL.viridian && b % 2 === 0) {
        brush.set("2H", PAL.emeraldCool, 0.32);
        for (let k = 0; k < poly.length; k += 7) {
          let p0 = poly[k];
          let p1 = poly[(k + 2) % poly.length];
          brush.line(p0[0], p0[1], p1[0], p1[1]);
        }
      }
    }
  }
}

// ============================================================================
// 6. FIBROUS STALK CORE (HEART) & INTERNAL INTER-LEAF LACUNAE
// ============================================================================

function drawStalkCoreAndLacunae(cx, cy, tilt) {
  const RX = 316, RY = 334;

  function toCanvas(u, v) {
    return rotPt(cx + u * RX, cy + v * RY, cx, cy, tilt);
  }

  // A. Deep near-black inter-leaf shadow pockets (lacunae) where crinkled folds separate
  const lacunae = [
    // Left axillary cleft next to the stalk core
    [[-0.24, 0.48], [-0.36, 0.42], [-0.42, 0.24], [-0.32, 0.18], [-0.22, 0.34]],
    // Right axillary cleft next to the stalk core
    [[ 0.24, 0.48], [ 0.36, 0.40], [ 0.40, 0.22], [ 0.30, 0.18], [ 0.21, 0.34]],
    // Upper-left deep fold pocket
    [[-0.22, -0.22], [-0.34, -0.32], [-0.26, -0.44], [-0.14, -0.34]],
    // Upper-right deep fold pocket
    [[ 0.22, -0.20], [ 0.34, -0.30], [ 0.26, -0.42], [ 0.14, -0.32]],
    // Central heart cleft above the apex of the stalk core
    [[-0.12, -0.06], [ 0.00, -0.18], [ 0.12, -0.05], [ 0.00, -0.01]],
    // Outer-left deep crinkled pocket
    [[-0.68, 0.08], [-0.76, -0.08], [-0.66, -0.22], [-0.60, -0.04]],
    // Outer-right deep crinkled pocket
    [[ 0.68, 0.06], [ 0.75, -0.10], [ 0.66, -0.22], [ 0.60, -0.04]]
  ];

  for (let lac of lacunae) {
    let pts = chaikinSmooth(lac.map(p => toCanvas(p[0], p[1])), 2, true);

    // Outer mint leaf-edge rim around the cavity
    brush.set("rotring", PAL.mintPale, 0.65);
    brush.wash(PAL.blackGreen, 250);
    drawPolyShape(pts, true);
    brush.noWash();

    // Inner recessed blistered leaf fold glimpsed inside the dark cavity
    let inner = pts.map((p, i) => [
      p[0] * 0.7 + pts[0][0] * 0.3,
      p[1] * 0.7 + pts[0][1] * 0.3
    ]);
    brush.set("rotring", PAL.viridianDeep, 0.42);
    drawPolyShape(inner, false);

    brush.set("rotring", PAL.blackGreen, 0.55);
    drawPolyShape(pts, true);
  }

  // B. The Fibrous Stalk / Core Wedge at the base of the cabbage head
  const stalkOutlineUV = [
    [-0.24, 0.97],
    [-0.21, 0.72],
    [-0.18, 0.46],
    [-0.13, 0.22],
    [-0.06, 0.06],
    [ 0.00, 0.01], // Conical heart apex
    [ 0.06, 0.06],
    [ 0.13, 0.22],
    [ 0.18, 0.46],
    [ 0.21, 0.72],
    [ 0.24, 0.97],
    [ 0.00, 1.00]
  ];

  const stalkPts = chaikinSmooth(stalkOutlineUV.map(p => toCanvas(p[0], p[1])), 2, true);

  // Outer cambium shadow ring around the stalk wedge
  brush.noStroke();
  brush.wash(PAL.viridianDeep, 225);
  drawPolyShape(stalkPts, true);

  // Mid celadon-mint cortex of the stalk
  const stalkMidPts = stalkPts.map(p => {
    let c = toCanvas(0, 0.55);
    return [c[0] + (p[0] - c[0]) * 0.90, c[1] + (p[1] - c[1]) * 0.92];
  });
  brush.wash(PAL.mint, 235);
  drawPolyShape(stalkMidPts, true);

  // Dense icy-mint inner pith of the stalk
  const stalkInnerPts = stalkPts.map(p => {
    let c = toCanvas(0, 0.56);
    return [c[0] + (p[0] - c[0]) * 0.78, c[1] + (p[1] - c[1]) * 0.84];
  });
  brush.wash(PAL.mintPale, 245);
  drawPolyShape(stalkInnerPts, true);

  // Brightest ivory-celadon core heart center
  const stalkHeartPts = stalkPts.map(p => {
    let c = toCanvas(0, 0.52);
    return [c[0] + (p[0] - c[0]) * 0.54, c[1] + (p[1] - c[1]) * 0.65];
  });
  brush.wash(PAL.mintIce, 250);
  drawPolyShape(stalkHeartPts, true);
  brush.noWash();

  // Watercolor subtle shading at base of cut stalk
  brush.fill(PAL.emeraldCool, 75);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.6, 0.5);
  drawPolyShape(stalkMidPts, true);
  brush.noFill();

  // Leaf-attachment nodes & arching vascular fibers radiating from the stalk sides
  for (let k = 0; k < 7; k++) {
    let vNode = 0.14 + k * 0.11;
    let uWidth = 0.06 + k * 0.022;

    for (let side = -1; side <= 1; side += 2) {
      let n0 = toCanvas(side * uWidth * 0.4, vNode + 0.04);
      let n1 = toCanvas(side * uWidth * 0.95, vNode);
      let n2 = toCanvas(side * (uWidth + 0.09), vNode - 0.05);
      let n3 = toCanvas(side * (uWidth + 0.18), vNode - 0.14);

      brush.set("rotring", PAL.viridian, 0.42);
      brush.spline([n0, n1, n2, n3], 0.4);

      brush.set("rotring", PAL.whiteSpec, 0.38);
      brush.spline([
        [n0[0], n0[1] - 1.5],
        [n1[0], n1[1] - 1.5],
        [n2[0], n2[1] - 1.5]
      ], 0.4);
    }

    // Fine growth arches inside the pith of the stalk
    let archPts = [];
    for (let s = -1; s <= 1; s += 0.25) {
      let u = s * uWidth * 0.72;
      let v = vNode + 0.03 * (1 - s * s);
      archPts.push(toCanvas(u, v));
    }
    brush.set("2H", PAL.mintDeep, 0.35);
    brush.spline(archPts, 0.35);
  }

  // Vascular cambium dots along the border of the stalk pith
  for (let t = 0; t < stalkInnerPts.length; t += 2) {
    let p = stalkInnerPts[t];
    brush.set("rotring", PAL.viridianDeep, 0.42);
    brush.circle(p[0], p[1], 1.4, 0.15);
  }

  // Crisp dividing outline around the stalk
  brush.set("rotring", PAL.bottleDark, 0.48);
  drawPolyShape(stalkPts, true);
}

// ============================================================================
// 7. FRESHLY SLICED CABBAGE SHREDS ON THE LEFT SLATE BOARD
// ============================================================================

function drawSlicedShredsOnSlate() {
  // Three delicate curled Savoy ribbons lying on the left slate board
  // reinforcing the "just been cut and polished" composition
  const shreds = [
    {
      spine: [[165, 675], [225, 650], [295, 658], [355, 692], [395, 735]],
      width: 16
    },
    {
      spine: [[210, 775], [275, 798], [350, 788], [415, 755]],
      width: 13
    },
    {
      spine: [[115, 735], [155, 762], [195, 758]],
      width: 9
    }
  ];

  for (let sh of shreds) {
    let curve = chaikinSmooth(sh.spine, 2, false);
    let leftEdge = [], rightEdge = [], midEdge = [];

    for (let i = 0; i < curve.length; i++) {
      let p = curve[i];
      let pNext = curve[Math.min(curve.length - 1, i + 1)];
      let pPrev = curve[Math.max(0, i - 1)];
      let dx = pNext[0] - pPrev[0], dy = pNext[1] - pPrev[1];
      let len = Math.sqrt(dx * dx + dy * dy) + 1e-5;
      let nx = -dy / len, ny = dx / len;

      let f = Math.sin((i / (curve.length - 1)) * Math.PI);
      let crinkle = 1.0 + 0.25 * Math.sin(i * 1.6);
      let w = sh.width * f * crinkle;

      leftEdge.push([p[0] + nx * w, p[1] + ny * w]);
      rightEdge.unshift([p[0] - nx * w, p[1] - ny * w]);
      midEdge.push([p[0] + nx * w * 0.2, p[1] + ny * w * 0.2]);
    }

    let poly = [...leftEdge, ...rightEdge];
    let shadowPoly = poly.map(p => [p[0] - 5, p[1] + 8]);

    // Cast shadow on slate
    brush.noStroke();
    brush.wash(PAL.shadowDeep, 210);
    drawPolyShape(shadowPoly, true);

    // Viridian & bottle green outer edge of shred
    brush.wash(PAL.viridianDeep, 245);
    drawPolyShape(poly, true);

    // Pale mint inner cut face of shred
    let innerPoly = [...leftEdge, ...midEdge.slice().reverse()];
    brush.wash(PAL.mintPale, 240);
    drawPolyShape(innerPoly, true);
    brush.noWash();

    // Fine pen malachite dividing lines along the shred
    brush.set("rotring", PAL.blackGreen, 0.45);
    drawPolyShape(poly, true);
    brush.set("rotring", PAL.viridian, 0.38);
    drawPolyShape(midEdge, false);
    brush.set("rotring", PAL.whiteSpec, 0.35);
    drawPolyShape(leftEdge, false);
  }
}

// ============================================================================
// 8. HYPERREAL MOISTURE BEADS (SHARP WHITE HIGHLIGHTS)
// ============================================================================

function drawMoistureBead(x, y, r, isOnSlate = false) {
  brush.noField();

  // 1. Crisp drop shadow on the bottom-right (away from upper-left studio light)
  brush.noStroke();
  brush.wash(PAL.blackGreen, 225);
  let shPts = [];
  for (let a = 0; a < 360; a += 30) {
    let rad = a * Math.PI / 180;
    shPts.push([
      x + r * 0.42 + Math.cos(rad) * r * 0.95,
      y + r * 0.48 + Math.sin(rad) * r * 0.85
    ]);
  }
  drawPolyShape(shPts, true);

  // 2. Darkened refracted upper-left interior of the water droplet
  brush.wash(isOnSlate ? PAL.slateDark : PAL.bottleDark, 215);
  let bodyPts = [];
  for (let a = 0; a < 360; a += 24) {
    let rad = a * Math.PI / 180;
    bodyPts.push([x + Math.cos(rad) * r, y + Math.sin(rad) * r * 0.92]);
  }
  drawPolyShape(bodyPts, true);

  // 3. Refracted internal caustic glow at the lower-right interior
  brush.wash(isOnSlate ? PAL.slateQuartz : PAL.mint, 225);
  let causticPts = [];
  for (let a = 0; a < 360; a += 30) {
    let rad = a * Math.PI / 180;
    causticPts.push([
      x + r * 0.22 + Math.cos(rad) * r * 0.58,
      y + r * 0.24 + Math.sin(rad) * r * 0.52
    ]);
  }
  drawPolyShape(causticPts, true);

  // Brighter inner caustic crescent
  brush.wash(PAL.mintIce, 240);
  let innerCaustic = [];
  for (let a = 0; a < 360; a += 36) {
    let rad = a * Math.PI / 180;
    innerCaustic.push([
      x + r * 0.30 + Math.cos(rad) * r * 0.32,
      y + r * 0.32 + Math.sin(rad) * r * 0.28
    ]);
  }
  drawPolyShape(innerCaustic, true);

  // 4. Fine dark surface tension rim around droplet
  brush.noWash();
  brush.set("rotring", PAL.blackGreen, 0.38);
  drawPolyShape(bodyPts, true);

  // 5. Razor-sharp pure white primary specular highlight at upper-left
  let hx = x - r * 0.34;
  let hy = y - r * 0.34;
  let hr = Math.max(1.4, r * 0.36);

  brush.noStroke();
  brush.wash(PAL.pureWhite, 255);
  let specPts = [];
  for (let a = 0; a < 360; a += 36) {
    let rad = a * Math.PI / 180;
    specPts.push([
      hx + Math.cos(rad) * hr * 1.15,
      hy + Math.sin(rad) * hr * 0.85
    ]);
  }
  drawPolyShape(specPts, true);
  brush.noWash();

  // Crisp opaque marker pinpoint for maximum specular brilliance
  brush.set("specular_dot", PAL.pureWhite, Math.max(0.35, r * 0.14));
  brush.line(hx - hr * 0.3, hy - hr * 0.15, hx + hr * 0.3, hy + hr * 0.15);

  // Secondary tiny pinpoint reflection near bottom-right rim
  if (r >= 4.5) {
    brush.set("specular_dot", PAL.pureWhite, 0.28);
    brush.line(x + r * 0.35, y + r * 0.35, x + r * 0.42, y + r * 0.35);
  }
}

