  ];
  for (let b of outerLeafBeads) {
    drawMoistureBead(b[0], b[1], b[2], false);
  }

  // 5. Water droplets scattered across the cold slate board near the sliced shreds
  const slateBeads = [
    [255, 625, 6.5], [272, 634, 3.4], [190, 715, 7.8], [335, 735, 5.8],
    [435, 795, 8.2], [452, 808, 4.0], [310, 835, 6.2], [145, 645, 5.0],
    [485, 695, 5.5], [380, 635, 4.5], [535, 865, 6.8]
  ];
  for (let b of slateBeads) {
    drawMoistureBead(b[0], b[1], b[2], true);
  }
}

