// ============================================================================
// TOPOGRAPHY OF THE FOLDED & BUCKLED GOATSKIN VELLUM
// ============================================================================

function getVellumFoldX(y) {
  // Primary vertical fold running down near x = 568
  return 568 + 8 * sin((y - 160) * 0.18) + 4 * cos((y - 160) * 0.43);
}

function getVellumFoldY(x) {
  // Secondary horizontal fold running across near y = 632
  return 632 - 10 * sin((x - 160) * 0.15) + 5 * cos((x - 160) * 0.35);
}

function getVellumElevation(x, y) {
  // Returns height & slope illumination factor (-1 shadow trough to +1 lit ridge)
  let fx = getVellumFoldX(y);
  let fy = getVellumFoldY(x);
  let dx = x - fx;
  let dy = y - fy;

  // Sharp ridge just left of vertical fold, trough just right of it
  let vFold = 0;
  if (dx < 0 && dx > -90) {
    vFold = map(dx, -90, 0, 0, 0.65);
  } else if (dx >= 0 && dx < 75) {
    vFold = map(dx, 0, 22, -0.85, -0.45) * map(constrain(dx, 22, 75), 22, 75, 1, 0);
  }

  // Sharp ridge just above horizontal fold, trough just below it
  let hFold = 0;
  if (dy < 0 && dy > -80) {
    hFold = map(dy, -80, 0, 0, 0.55);
  } else if (dy >= 0 && dy < 68) {
    hFold = map(dy, 0, 18, -0.75, -0.35) * map(constrain(dy, 18, 68), 18, 68, 1, 0);
  }

  // Diagonal cockling (buckled skin waves radiating from corners and center)
  let cockle1 = 0.32 * sin((x * 0.65 + y * 0.75) * 0.95);
  let cockle2 = 0.22 * cos((x * 0.85 - y * 0.52) * 1.25);
  let edgeCockle = 0;
  if (y < 290) edgeCockle += 0.28 * sin((x - 160) * 1.6) * map(y, 168, 290, 1, 0);
  if (y > 900) edgeCockle += 0.30 * cos((x - 160) * 1.4) * map(y, 900, 1032, 0, 1);
  if (x < 290) edgeCockle += 0.25 * sin((y - 160) * 1.5) * map(x, 168, 290, 1, 0);

  return constrain(vFold + hFold + cockle1 + cockle2 + edgeCockle, -1, 1);
}

function getVellumBuckleDY(x, y) {
  // Subtle vertical displacement for script and shadow warping over buckles
  let fy = getVellumFoldY(x);
  let dy = y - fy;
  let foldWarp = exp(- (dy * dy) / 1800) * (dy < 0 ? -4.5 : 3.5);
  let waveWarp = 2.4 * sin((x * 0.65 + y * 0.75) * 0.95);
  return foldWarp + waveWarp;
}

// ============================================================================
// 1. OUTER MARGIN
// ============================================================================

function drawOuterMargin() {
  brush.noStroke();
  brush.wash(PAL.marginPaper, 255);
  brush.rect(0, 0, 1200, 1200, "corner");

  // Subtle aged paper grain around outer margin
  brush.set("2H", "#d6cbb8", 0.5);
  for (let i = 0; i < 180; i++) {
    let side = i % 4;
    let x1, y1;
    if (side === 0) { x1 = random(10, 1190); y1 = random(8, 55); }
    else if (side === 1) { x1 = random(10, 1190); y1 = random(1145, 1192); }
    else if (side === 2) { x1 = random(8, 55); y1 = random(10, 1190); }
    else { x1 = random(1145, 1192); y1 = random(10, 1190); }
    let ang = random(-15, 15) + (side >= 2 ? 90 : 0);
    brush.line(x1, y1, x1 + cos(ang) * random(15, 45), y1 + sin(ang) * random(15, 45));
  }
}

// ============================================================================
// 2. HYPERREAL FOLDED GOATSKIN VELLUM (BRANA)
// ============================================================================

function drawGoatskinVellum() {
  const vx1 = 166, vy1 = 166, vx2 = 1034, vy2 = 1034;
  const vw = vx2 - vx1, vh = vy2 - vy1;

  // Base goatskin wash
  brush.noStroke();
  brush.wash(PAL.vellumBase, 255);
  brush.rect(vx1, vy1, vw, vh, "corner");

  // Batch watercolor washes for buckled troughs and warm skin patches
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.25);

  // Batch 1: Mid warm vellum patches (cockling valleys & age patina)
  brush.fill(PAL.vellumMid, 95);
  let midPatches = [
    [170, 170, 395, 290],
    [570, 170, 460, 455],
    [170, 635, 400, 395],
    [570, 635, 460, 395],
    [320, 360, 360, 320]
  ];
  for (let p of midPatches) {
    drawSoftQuad(p[0], p[1], p[2], p[3], 14);
  }

  // Batch 2: Deeper shadow troughs along the vertical fold, horizontal fold, and diagonal buckles
  brush.fill(PAL.vellumShadow, 115);
  // Vertical fold shadow trough (right side of xFold)
  brush.beginShape(0.3);
  for (let y = vy1; y <= vy2; y += 70) brush.vertex(getVellumFoldX(y) + 2, y);
  for (let y = vy2; y >= vy1; y -= 70) brush.vertex(getVellumFoldX(y) + 52 + 12 * sin(y * 0.4), y);
  brush.endShape(true);

  // Horizontal fold shadow trough (bottom side of yFold)
  brush.beginShape(0.3);
  for (let x = vx1; x <= vx2; x += 70) brush.vertex(x, getVellumFoldY(x) + 2);
  for (let x = vx2; x >= vx1; x -= 70) brush.vertex(x, getVellumFoldY(x) + 46 + 10 * cos(x * 0.4));
  brush.endShape(true);

  // Diagonal buckle shadow bands
  let buckleBands = [
    [[180, 290], [380, 180], [435, 210], [210, 355]],
    [[180, 520], [490, 310], [540, 355], [220, 580]],
    [[610, 390], [920, 200], [980, 245], [655, 450]],
    [[210, 880], [530, 670], [565, 725], [260, 945]],
    [[620, 860], [980, 660], [1020, 725], [670, 930]]
  ];
  for (let b of buckleBands) {
    brush.beginShape(0.45);
    for (let pt of b) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
  }

  // Batch 3: Deepest fold core shadows
  brush.fill(PAL.vellumDeep, 105);
  brush.beginShape(0.25);
  for (let y = vy1; y <= vy2; y += 85) brush.vertex(getVellumFoldX(y), y);
  for (let y = vy2; y >= vy1; y -= 85) brush.vertex(getVellumFoldX(y) + 18, y);
  brush.endShape(true);

  brush.beginShape(0.25);
  for (let x = vx1; x <= vx2; x += 85) brush.vertex(x, getVellumFoldY(x));
  for (let x = vx2; x >= vx1; x -= 85) brush.vertex(x, getVellumFoldY(x) + 16);
  brush.endShape(true);

  // Batch 4: Luminous ridge highlights on the lit side of folds and buckles
  brush.fill(PAL.vellumLight, 130);
  brush.beginShape(0.25);
  for (let y = vy1; y <= vy2; y += 85) brush.vertex(getVellumFoldX(y) - 34, y);
  for (let y = vy2; y >= vy1; y -= 85) brush.vertex(getVellumFoldX(y) - 1, y);
  brush.endShape(true);

  brush.beginShape(0.25);
  for (let x = vx1; x <= vx2; x += 85) brush.vertex(x, getVellumFoldY(x) - 30);
  for (let x = vx2; x >= vx1; x -= 85) brush.vertex(x, getVellumFoldY(x) - 1);
  brush.endShape(true);

  brush.noFill();

  // Fine continuous dry-media shading to sculpt the 3D buckled surface smoothly
  for (let y = vy1 + 8; y < vy2 - 8; y += 5) {
    for (let x = vx1 + 8; x < vx2 - 8; x += 28) {
      let elev = getVellumElevation(x, y);
      let len = random(22, 38);
      // Follow subtle diagonal scraping direction or buckle contour
      let ang = -28 + 12 * noise(x * 0.005, y * 0.005);
      if (elev < -0.18) {
        let w = map(elev, -1, -0.18, 0.85, 0.25);
        brush.set("2H", elev < -0.5 ? PAL.vellumDeep : PAL.vellumShadow, w);
        brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
      } else if (elev > 0.22) {
        let w = map(elev, 0.22, 1, 0.3, 0.95);
        brush.set("cpencil", PAL.vellumLight, w);
        brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
      }
    }
  }

  // Pumice / knife preparation striae (characteristic of Ethiopian Brana vellum)
  brush.set("2H", "#d5c7ae", 0.28);
  for (let i = 0; i < 260; i++) {
    let sx = random(vx1 + 15, vx2 - 15);
    let sy = random(vy1 + 15, vy2 - 15);
    let sAng = random(-38, -22);
    let sLen = random(35, 110);
    brush.line(sx, sy, sx + cos(sAng) * sLen, sy + sin(sAng) * sLen);
  }

  // Faint subcutaneous translucent veins in the goatskin
  drawVellumVeins();

  // Sharp hyperreal crease ridges, micro-cracks, and stress wrinkles at fold intersections
  drawVellumCreaseDetails(vx1, vy1, vx2, vy2);

  // Obsessively observed goatskin hair follicles in sweeping natural hide grain tracts
  drawGoatskinFollicles(vx1, vy1, vx2, vy2);
}

function drawSoftQuad(x, y, w, h, jitter) {
  brush.beginShape(0.35);
  brush.vertex(x + random(-jitter, jitter), y + random(-jitter, jitter));
  brush.vertex(x + w + random(-jitter, jitter), y + random(-jitter, jitter));
  brush.vertex(x + w + random(-jitter, jitter), y + h + random(-jitter, jitter));
  brush.vertex(x + random(-jitter, jitter), y + h + random(-jitter, jitter));
  brush.endShape(true);
}

function drawVellumVeins() {
  let veins = [
    [[210, 240], [265, 290], [310, 355], [340, 420]],
    [[265, 290], [325, 305], [375, 330]],
    [[640, 740], [695, 790], [735, 860], [760, 940]],
    [[695, 790], [660, 845], [635, 905]],
    [[230, 720], [295, 760], [370, 780]]
  ];
  for (let v of veins) {
    brush.set("2H", "#d4c3a8", 0.45);
    brush.spline(v, 0.5);
    brush.set("cpencil", "#f7f1e3", 0.3);
    let vOff = v.map(pt => [pt[0] - 1.5, pt[1] - 1.5]);
    brush.spline(vOff, 0.5);
  }
}

function drawVellumCreaseDetails(vx1, vy1, vx2, vy2) {
  // 1. Primary Vertical Fold Crease
  for (let y = vy1 + 4; y < vy2 - 4; y += 6) {
    let fx = getVellumFoldX(y);
    let fxNext = getVellumFoldX(y + 6);
    // Crisp lit ridge lip on the left of the crease
    brush.set("cpencil", PAL.vellumLight, random(0.7, 1.2));
    brush.line(fx - 2.2, y, fxNext - 2.2, y + 6);
    brush.set("rotring", "#ffffff", 0.45);
    brush.line(fx - 1.0, y, fxNext - 1.0, y + 6);

    // Tight shadow pinch on the right of the crease
    brush.set("2B", PAL.vellumCreaseDark, random(0.45, 0.85));
    brush.line(fx + 1.2, y, fxNext + 1.2, y + 6);

    // Subtle short lateral stress-wrinkles fanning out from the fold
    if (random() < 0.35) {
      let dir = random() < 0.5 ? -1 : 1;
      let wLen = random(8, 24);
      let wAng = dir > 0 ? random(-25, 25) : random(155, 205);
      brush.set("2H", PAL.vellumDeep, 0.35);
      brush.line(fx, y, fx + cos(wAng) * wLen, y + sin(wAng) * wLen);
      brush.set("cpencil", PAL.vellumLight, 0.35);
      brush.line(fx, y - 1.2, fx + cos(wAng) * wLen, y - 1.2 + sin(wAng) * wLen);
    }
  }

  // 2. Secondary Horizontal Fold Crease
  for (let x = vx1 + 4; x < vx2 - 4; x += 6) {
    let fy = getVellumFoldY(x);
    let fyNext = getVellumFoldY(x + 6);
    // Lit upper lip
    brush.set("cpencil", PAL.vellumLight, random(0.65, 1.1));
    brush.line(x, fy - 2.0, x + 6, fyNext - 2.0);
    brush.set("rotring", "#ffffff", 0.4);
    brush.line(x, fy - 0.8, x + 6, fyNext - 0.8);

    // Shadow lower pinch
    brush.set("2B", PAL.vellumCreaseDark, random(0.4, 0.75));
    brush.line(x, fy + 1.4, x + 6, fyNext + 1.4);

    if (random() < 0.3) {
      let wLen = random(7, 20);
      let wAng = random(65, 115);
      brush.set("2H", PAL.vellumDeep, 0.32);
      brush.line(x, fy, x + cos(wAng) * wLen, fy + sin(wAng) * wLen);
    }
  }

  // 3. Central Fold Intersection Crow's-Foot Buckles around (570, 630)
  let ix = getVellumFoldX(630);
  let iy = getVellumFoldY(ix);
  for (let i = 0; i < 18; i++) {
    let ang = i * 20 + random(-6, 6);
    let r1 = random(3, 12);
    let r2 = random(22, 58);
    brush.set("2H", PAL.vellumCreaseDark, 0.45);
    brush.line(ix + cos(ang) * r1, iy + sin(ang) * r1, ix + cos(ang) * r2, iy + sin(ang) * r2);
    brush.set("cpencil", PAL.vellumLight, 0.5);
    brush.line(ix + cos(ang + 3) * r1, iy + sin(ang + 3) * r1 - 1.5, ix + cos(ang + 3) * r2, iy + sin(ang + 3) * r2 - 1.5);
  }
}

function drawGoatskinFollicles(vx1, vy1, vx2, vy2) {
  // Goatskin (unlike calfskin) has distinct grouped hair follicles arranged in curved grain waves.
  // They are especially crisp in raking light near the folds and slightly softer in flat areas.
  for (let gy = vy1 + 14; gy < vy2 - 14; gy += 11) {
    for (let gx = vx1 + 14; gx < vx2 - 14; gx += 11) {
      // Grain density modulated by organic hide regions
      let regionDensity = noise(gx * 0.006, gy * 0.006);
      let elev = getVellumElevation(gx, gy);
      // Raking light near slope transitions accentuates follicle pits
      let raking = 1.0 - abs(elev - 0.05);
      if (regionDensity + raking * 0.35 < 0.52) continue;

      // Local grain flow angle
      let flowAng = 35 * sin(gx * 0.008) + 25 * cos(gy * 0.009) - 20;
      let px = gx + random(-4.5, 4.5);
      let py = gy + random(-4.5, 4.5);

      // Primary guard-hair follicle pore
      let isDarker = regionDensity > 0.62 || abs(px - getVellumFoldX(py)) < 65;
      brush.set("rotring", isDarker ? PAL.follicle : PAL.follicleLight, random(0.32, 0.62));
      let tickLen = random(0.8, 2.1);
      brush.line(px, py, px + cos(flowAng) * tickLen, py + sin(flowAng) * tickLen);

      // Tiny companion wool-hair pores in a triad/arc (characteristic of goat hide)
      if (random() < 0.65) {
        let pAng = flowAng + 90;
        let p2x = px + cos(pAng) * random(1.8, 3.2);
        let p2y = py + sin(pAng) * random(1.8, 3.2);
        brush.set("2H", PAL.follicleLight, 0.35);
        brush.line(p2x, p2y, p2x + cos(flowAng) * 1.1, p2y + sin(flowAng) * 1.1);

        if (random() < 0.45) {
          let p3x = px - cos(pAng) * random(1.8, 3.2);
          let p3y = py - sin(pAng) * random(1.8, 3.2);
          brush.line(p3x, p3y, p3x + cos(flowAng) * 1.0, p3y + sin(flowAng) * 1.0);
        }
      }
    }
  }
}

// ============================================================================
// 3. COLUMN OF RHYTHMIC RED-AND-BLACK GE'EZ SCRIPT (FIDEL)
// ============================================================================

function drawGeezScriptColumn() {
  const colX1 = 748;
  const colX2 = 996;
  const colY1 = 212;
  const colY2 = 996;
  const numLines = 31;
  const lineSpacing = (colY2 - colY1) / numLines;

  // 1. Pricking holes along the right outer edge of the vellum (scribe's awl marks)
  for (let i = 0; i <= numLines; i++) {
    let py = colY1 + i * lineSpacing;
    let px = 1012 + random(-0.8, 0.8);
    let dy = getVellumBuckleDY(px, py);
    brush.set("rotring", PAL.vellumCreaseDark, 0.8);
    brush.line(px - 1, py + dy, px + 1.5, py + dy + 0.5);
    brush.set("cpencil", PAL.vellumLight, 0.55);
    brush.line(px - 1, py + dy - 1.2, px + 1.5, py + dy - 0.8);
  }

  // 2. Dry-point vertical bounding lines and horizontal ruling lines
  let vLines = [colX1 - 8, colX1 - 2, colX2 + 4, colX2 + 10];
  for (let vx of vLines) {
    for (let y = 185; y < 1012; y += 18) {
      let dy1 = getVellumBuckleDY(vx, y);
      let dy2 = getVellumBuckleDY(vx, y + 18);
      brush.set("2H", PAL.ruling, 0.35);
      brush.line(vx, y + dy1, vx, y + 18 + dy2);
      brush.set("cpencil", PAL.vellumLight, 0.28);
      brush.line(vx - 1, y + dy1, vx - 1, y + 18 + dy2);
    }
  }

  for (let i = 0; i <= numLines; i++) {
    let ry = colY1 + i * lineSpacing;
    for (let x = colX1 - 12; x < colX2 + 12; x += 20) {
      let dy1 = getVellumBuckleDY(x, ry);
      let dy2 = getVellumBuckleDY(x + 20, ry);
      brush.set("2H", PAL.ruling, 0.32);
      brush.line(x, ry + dy1, x + 20, ry + dy2);
    }
  }

  // 3. Decorative *Harag* headband at top of script column (y = 184..204)
  drawColumnHeadband(colX1 - 4, 184, colX2 - colX1 + 8, 18);

  // 4. Render 31 lines of rhythmic red-and-black Ge'ez calligraphy
  for (let row = 0; row < numLines; row++) {
    let baseY = colY1 + row * lineSpacing + 5;
    let cursorX = colX1 + 4;

    // Rhythmic rubrication state: alternates phrases of black carbon ink and red ochre ink
    let isRed = ((row * 3) % 7 === 0) || (row === 0) || (row === 14) || (row === 23);
    let charsInPhrase = int(random(3, 8));
    let charCount = 0;

    while (cursorX < colX2 - 14) {
      let dy = getVellumBuckleDY(cursorX, baseY);
      let gy = baseY + dy;
      let elev = getVellumElevation(cursorX, gy);

      // Slight ink darkening in vellum shadow troughs
      let inkCol = isRed
        ? (elev < -0.25 ? PAL.rubricDark : PAL.rubric)
        : (elev < -0.25 ? PAL.ink : PAL.inkSoft);

      let charW = random(14.5, 18.5);
      let charH = lineSpacing * 0.62;

      // Word separator (: two vertical dots with tiny horizontal serifs) or paragraph mark (፠)
      if (charCount >= charsInPhrase && cursorX < colX2 - 26) {
        if (random() < 0.22) {
          // 4-dot diamond paragraph mark (ነቁጥ / ፠) in red and black
          drawGeezParagraphMark(cursorX + 6, gy + charH * 0.5, inkCol);
          cursorX += 18;
        } else {
          // Standard 2-dot Ge'ez word divider (ሁለት ነጥብ)
          drawGeezWordDivider(cursorX + 4, gy + charH * 0.5, isRed ? PAL.ink : PAL.rubric);
          cursorX += 12;
        }
        // Switch rhythmically between black and red rubrication
        if (random() < 0.48) isRed = !isRed;
        charsInPhrase = isRed ? int(random(3, 7)) : int(random(5, 11));
        charCount = 0;
        continue;
      }

      let glyphId = int(random(16));
      drawFidelGlyph(cursorX, gy, charW * 0.78, charH, inkCol, glyphId);

      cursorX += charW;
      charCount++;
    }
  }
}

function drawColumnHeadband(x, y, w, h) {
  brush.noStroke();
  brush.wash(PAL.ochre, 210);
  brush.rect(x, y, w, h, "corner");

  // Interlaced zig-zag & lozenges inside headband
  let steps = 12;
  let sw = w / steps;
  for (let i = 0; i < steps; i++) {
    let sx = x + i * sw;
    brush.noStroke();
    brush.wash(i % 2 === 0 ? PAL.saffron : PAL.green, 220);
    brush.beginShape(0);
    brush.vertex(sx + sw * 0.5, y + 2);
    brush.vertex(sx + sw - 2, y + h * 0.5);
    brush.vertex(sx + sw * 0.5, y + h - 2);
    brush.vertex(sx + 2, y + h * 0.5);
    brush.endShape(true);
  }

  brush.set("pen", PAL.ink, 0.85);
  brush.noFill();
  brush.noWash();
  brush.rect(x, y, w, h, "corner");
  for (let i = 0; i < steps; i++) {
    let sx = x + i * sw;
    brush.line(sx, y + h * 0.5, sx + sw * 0.5, y + 1);
    brush.line(sx + sw * 0.5, y + 1, sx + sw, y + h * 0.5);
    brush.line(sx + sw, y + h * 0.5, sx + sw * 0.5, y + h - 1);
    brush.line(sx + sw * 0.5, y + h - 1, sx, y + h * 0.5);
  }
}

function drawGeezWordDivider(x, cy, col) {
  brush.set("pen", col, 1.15);
  brush.line(x - 1.8, cy - 3.5, x + 1.8, cy - 3.5);
  brush.line(x - 1.8, cy + 3.5, x + 1.8, cy + 3.5);
}

function drawGeezParagraphMark(x, cy, col) {
  brush.set("pen", PAL.ink, 1.1);
  brush.line(x - 1.5, cy - 5, x + 1.5, cy - 5);
  brush.line(x - 1.5, cy + 5, x + 1.5, cy + 5);
  brush.line(x - 5.5, cy, x - 3, cy);
  brush.line(x + 3, cy, x + 5.5, cy);
  brush.set("pen", PAL.rubric, 1.0);
  brush.line(x - 4, cy - 4, x + 4, cy + 4);
  brush.line(x + 4, cy - 4, x - 4, cy + 4);
}

function drawFidelGlyph(x, y, w, h, col, id) {
  // Authentic calligraphic Ge'ez Fidel structures: thick vertical stems,
  // rounded top/bottom loops, horizontal crossbars and diacritic vocalic rings
  let xL = x + 1.5;
  let xM = x + w * 0.5;
  let xR = x + w - 1.5;
  let yT = y + 1;
  let yM = y + h * 0.5;
  let yB = y + h - 1;

  // Main calligraphic nib downstrokes
  brush.set("pen", col, 0.95);

  switch (id % 16) {
    case 0: // ሀ (Ha) - U-shaped cup with top serifs
      brush.line(xL, yT, xL, yB);
      brush.line(xR, yT, xR, yB);
      brush.line(xL, yB, xR, yB);
      break;
    case 1: // ለ (Le) - Arch with peaked crown
      brush.line(xL, yB, xL + 1, yT + 2);
      brush.line(xL + 1, yT + 2, xM, yT - 1);
      brush.line(xM, yT - 1, xR - 1, yT + 2);
      brush.line(xR - 1, yT + 2, xR, yB);
      break;
    case 2: // ሐ (Hha) - Trident with central stem and crossbar
      brush.line(xM, yT, xM, yB);
      brush.line(xL, yM, xR, yM);
      brush.line(xL, yT + 2, xL, yM);
      brush.line(xR, yT + 2, xR, yM);
      break;
    case 3: // መ (Me) - Twin rounded chambers linked at top
      brush.line(xL, yT + 2, xL, yB - 1);
      brush.line(xM, yT + 1, xM, yB - 1);
      brush.line(xR, yT + 2, xR, yB - 1);
      brush.line(xL, yT + 1, xR, yT + 1);
      brush.line(xL, yB - 1, xM, yB - 1);
      brush.line(xM, yB - 1, xR, yB - 1);
      break;
    case 4: // ሰ (Se) - Three vertical stems joined at top bar
      brush.line(xL, yT, xR, yT);
      brush.line(xL, yT, xL, yB);
      brush.line(xM, yT, xM, yB - 2);
      brush.line(xR, yT, xR, yB);
      break;
    case 5: // ቀ (Qe) - Vertical stem with top loop and horizontal crossbar
      brush.line(xM, yT + 4, xM, yB);
      brush.line(xL, yM + 1, xR, yM + 1);
      brush.line(xL + 1, yT, xR - 1, yT);
      brush.line(xL + 1, yT, xL + 1, yT + 4);
      brush.line(xR - 1, yT, xR - 1, yT + 4);
      break;
    case 6: // በ (Be) - Tall two-legged arch with vocalic foot
      brush.line(xL, yT, xR, yT);
      brush.line(xL, yT, xL, yB);
      brush.line(xR, yT, xR, yB);
      brush.line(xR, yM + 2, xR + 2.5, yM + 2);
      break;
    case 7: // ተ (Te) - Cross form with top serif
      brush.line(xM, yT, xM, yB);
      brush.line(xL, yM - 1, xR, yM - 1);
      brush.line(xL + 1, yT, xR - 1, yT);
      break;
    case 8: // ነ (Ne) - Single stem with top left hook and bottom right foot
      brush.line(xM, yT, xM, yB);
      brush.line(xL, yT + 2, xM, yT);
      brush.line(xM, yB, xR + 1, yB);
      break;
    case 9: // አ (A) - Double-crowned stem with central notch
      brush.line(xL, yT, xR, yT);
      brush.line(xL, yT, xM, yM);
      brush.line(xM, yM, xL + 1, yB);
      brush.line(xR, yT, xR, yB);
      break;
    case 10: // ወ (We) - Rounded belly with central vertical divider
      brush.line(xL + 1, yT + 1, xR - 1, yT + 1);
      brush.line(xL, yT + 2, xL, yB - 2);
      brush.line(xR, yT + 2, xR, yB - 2);
      brush.line(xL + 1, yB - 1, xR - 1, yB - 1);
      brush.line(xM, yT + 1, xM, yB - 1);
      break;
    case 11: // ዐ (O) - Triangular/oval eye loop
      brush.line(xM, yT, xL, yB);
      brush.line(xM, yT, xR, yB);
      brush.line(xL, yB, xR, yB);
      break;
    case 12: // ዘ (Ze) - H-shaped frame with top ticks
      brush.line(xL, yT, xL, yB);
      brush.line(xR, yT, xR, yB);
      brush.line(xL, yM, xR, yM);
      break;
    case 13: // ገ (Ge) - Gamma-like stem with right shoulder
      brush.line(xL + 1, yT, xR, yT);
      brush.line(xR, yT, xR, yB);
      brush.line(xL, yB, xR, yB);
      break;
    case 14: // ጸ (Tse) - Crowned arch with internal hook
      brush.line(xL, yB, xL, yT + 2);
      brush.line(xR, yB, xR, yT + 2);
      brush.line(xL, yT + 2, xR, yT + 2);
      brush.line(xM, yT - 1, xM, yM + 2);
      break;
    case 15: // ፈ (Fe) - Spiraled top loop with sweeping base bar
      brush.line(xL + 1, yT, xR, yT);
      brush.line(xL + 1, yT, xL + 1, yM);
      brush.line(xL + 1, yM, xM + 2, yM);
      brush.line(xM, yM, xM, yB);
      brush.line(xL, yB, xR + 1, yB);
      break;
  }

  // Fine nib hairline serifs and vocalic rings (Ge'ez 2nd/4th/7th order markers)
  brush.set("rotring", col, 0.55);
  brush.line(xL - 1, yT, xL + 2, yT);
  if (id % 3 === 0) {
    // Small vocalic ring on right leg
    brush.circle(xR + 1.8, yM + 1, 1.8, 0.1);
  }
}

// ============================================================================
// COORDINATE HELPERS FOR THE TILTED ETHIOPIAN HAND CROSS
// ============================================================================

function crossPt(u, v, dx = 0, dy = 0) {
  let c = cos(CROSS_ANGLE);
  let s = sin(CROSS_ANGLE);
  return [
    CROSS_CX + u * c - v * s + dx,
    CROSS_CY + u * s + v * c + dy
  ];
}

// ============================================================================
// 4. CAST SHADOWS OF CROSS AND LEATHER THONG ON BUCKLED VELLUM
// ============================================================================

function drawCrossAndThongShadows() {
  // Light comes from top-left (-135 deg), so shadows cast down-right (+15, +19)
  const sdx = 15;
  const sdy = 19;

  // 1. Soft watercolor penumbra under the main cross head, shaft, and Tabot base
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.2);
  brush.fill(PAL.shadowPenumbra, 75);

  // Cross Head diamond-cruciform penumbra
  let headOutline = [
    [0, -210], [52, -165], [140, -140], [165, -52],
    [210, 0], [165, 52], [140, 140], [45, 175],
    [24, 200], [-24, 200], [-45, 175], [-140, 140],
    [-165, 52], [-210, 0], [-165, -52], [-140, -140], [-52, -165]
  ];
  brush.beginShape(0.35);
  for (let pt of headOutline) {
    let p = crossPt(pt[0], pt[1], sdx + 3, sdy + 3);
    brush.vertex(p[0], p[1] + getVellumBuckleDY(p[0], p[1]) * 0.5);
  }
  brush.endShape(true);

  // Shaft + Tabot Base penumbra
  let lowerOutline = [
    [-22, 195], [22, 195], [22, 375], [64, 375],
    [64, 490], [22, 505], [-22, 505], [-64, 490],
    [-64, 375], [-22, 375]
  ];
  brush.beginShape(0.2);
  for (let pt of lowerOutline) {
    let p = crossPt(pt[0], pt[1], sdx + 3, sdy + 3);
    brush.vertex(p[0], p[1] + getVellumBuckleDY(p[0], p[1]) * 0.5);
  }
  brush.endShape(true);
  brush.noFill();

  // 2. Crisp pierced filigree lattice shadow!
  // Every strut of the openwork cross casts its own dark umbra onto the vellum,
  // so through the holes of the silver cross we see the offset shadow of the lattice!
  let struts = getCrossFiligreeStruts();
  for (let st of struts) {
    let p1 = crossPt(st[0], st[1], sdx, sdy);
    let p2 = crossPt(st[2], st[3], sdx, sdy);
    let w = st[4];
    p1[1] += getVellumBuckleDY(p1[0], p1[1]) * 0.45;
    p2[1] += getVellumBuckleDY(p2[0], p2[1]) * 0.45;

    brush.set("marker", PAL.shadowUmbra, w * 0.24);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("charcoal", PAL.shadowContact, w * 0.14);
    brush.line(p1[0] - 2, p1[1] - 2, p2[0] - 2, p2[1] - 2);
  }

  // Finial buds cast shadows
  let finials = getCrossFinials();
  for (let fn of finials) {
    let pc = crossPt(fn[0], fn[1], sdx, sdy);
    let ang = fn[2] + CROSS_ANGLE;
    let sc = fn[3];
    brush.set("marker", PAL.shadowUmbra, 1.8 * sc);
    brush.line(pc[0], pc[1], pc[0] + cos(ang) * 26 * sc, pc[1] + sin(ang) * 26 * sc);
    brush.line(
      pc[0] + cos(ang) * 14 * sc + cos(ang - 90) * 11 * sc,
      pc[1] + sin(ang) * 14 * sc + sin(ang - 90) * 11 * sc,
      pc[0] + cos(ang) * 14 * sc + cos(ang + 90) * 11 * sc,
      pc[1] + sin(ang) * 14 * sc + sin(ang + 90) * 11 * sc
    );
  }

  // Solid umbra under the Neck Shaft and Tabot Base
  brush.noStroke();
  brush.wash(PAL.shadowUmbra, 135);
  let shaftBox = [[-19, 195], [19, 195], [19, 378], [-19, 378]];
  brush.beginShape(0);
  for (let pt of shaftBox) {
    let p = crossPt(pt[0], pt[1], sdx - 1, sdy - 1);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  let tabotBox = [[-58, 378], [58, 378], [58, 488], [-58, 488]];
  brush.beginShape(0);
  for (let pt of tabotBox) {
    let p = crossPt(pt[0], pt[1], sdx - 1, sdy - 1);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();
}

// ============================================================================
// 5. WORN LEATHER THONG
// ============================================================================

function getLeatherThongPaths() {
  // Eyelet ring center in world coordinates
  let ringPt = crossPt(0, 502);
  let rx = ringPt[0], ry = ringPt[1];

  // Left strap snakes down-left across the lower goatskin and turns gracefully
  let leftStrap = [
    [rx - 3, ry + 4],
    [rx - 42, ry + 34],
    [rx - 108, ry + 52],
    [rx - 185, ry + 38],
    [rx - 255, ry + 62],
    [rx - 295, ry + 102]
  ];

  // Right strap snakes down-right and curls inward near the bottom script margin
  let rightStrap = [
    [rx + 5, ry + 2],
    [rx + 58, ry + 28],
    [rx + 128, ry + 42],
    [rx + 188, ry + 78],
    [rx + 165, ry + 118],
    [rx + 108, ry + 125]
  ];

  return { ringPt, leftStrap, rightStrap };
}

function drawLeatherThong(frontPassOnly) {
  let { ringPt, leftStrap, rightStrap } = getLeatherThongPaths();
  let rx = ringPt[0], ry = ringPt[1];

  if (!frontPassOnly) {
    // Cast shadows of the two leather straps onto the vellum
    for (let strap of [leftStrap, rightStrap]) {
      let shadowPts = strap.map((pt, idx) => {
        // Variable lift height: higher near the ring knot, flatter near the tips
        let lift = map(idx, 0, strap.length - 1, 11, 4);
        return [pt[0] + lift, pt[1] + lift * 1.25];
      });
      brush.set("marker", PAL.shadowPenumbra, 3.8);
      brush.spline(shadowPts, 0.5);
      brush.set("charcoal", PAL.shadowUmbra, 2.1);
      let contactPts = strap.map((pt, idx) => {
        let lift = map(idx, 0, strap.length - 1, 6, 2);
        return [pt[0] + lift, pt[1] + lift * 1.2];
      });
      brush.spline(contactPts, 0.5);
    }

    // Render both leather straps in hyperreal detail
    renderDetailedLeatherStrap(leftStrap, 15);
    renderDetailedLeatherStrap(rightStrap, 14);
  } else {
    // Front Pass: The worn leather Lark's-head hitch knot wrapping OVER the silver eyelet ring
    // Left wrap lobe
    drawLeatherKnotLobe(rx - 9, ry - 6, rx - 4, ry + 14, 13);
    // Right wrap lobe
    drawLeatherKnotLobe(rx + 8, ry - 8, rx + 5, ry + 13, 13);
    // Horizontal collar cinch across the base of the ring
    drawLeatherKnotLobe(rx - 14, ry + 10, rx + 14, ry + 8, 12);
  }
}

function renderDetailedLeatherStrap(pts, baseWidth) {
  // Sample dense points along the spline curve for hyperreal transverse creases & suede fibers
  let dense = sampleCatmullRom(pts, 48);

  // 1. Dark shadow underside edge
  let underPts = dense.map(p => [p.x + p.nx * 3.5, p.y + p.ny * 3.5]);
  brush.set("marker", PAL.leatherAbyss, baseWidth * 0.24);
  brush.spline(underPts, 0.3);

  // 2. Core reddish-brown leather body
  let corePts = dense.map(p => [p.x, p.y]);
  brush.set("marker", PAL.leatherDark, baseWidth * 0.26);
  brush.spline(corePts, 0.3);

  // 3. Warm mid-tone leather grain
  let midPts = dense.map(p => [p.x - p.nx * 1.2, p.y - p.ny * 1.2]);
  brush.set("cpencil", PAL.leatherMid, baseWidth * 0.18);
  brush.spline(midPts, 0.3);

  // 4. Worn top bevel suede highlight (square-cut rawhide edge)
  let topBevelPts = dense.map(p => [p.x - p.nx * (baseWidth * 0.36), p.y - p.ny * (baseWidth * 0.36)]);
  brush.set("cpencil", PAL.leatherLight, 1.35);
  brush.spline(topBevelPts, 0.3);
  brush.set("rotring", PAL.leatherSuede, 0.55);
  brush.spline(topBevelPts, 0.3);

  // 5. Cut-side raw suede thickness band & transverse epidermis flex cracks
  for (let i = 1; i < dense.length - 1; i++) {
    let p = dense[i];
    let hw = baseWidth * 0.44;

    // Transverse flex creases where the strap bends
    if (i % 2 === 0) {
      let cCol = (i % 4 === 0) ? PAL.leatherAbyss : PAL.leatherWarm;
      brush.set("rotring", cCol, 0.45);
      brush.line(
        p.x - p.nx * hw * 0.85, p.y - p.ny * hw * 0.85,
        p.x + p.nx * hw * 0.85, p.y + p.ny * hw * 0.85
      );
      // Tiny bright crack highlight right next to dark crease
      if (i % 4 === 0) {
        brush.set("rotring", PAL.leatherSuede, 0.38);
        brush.line(
          p.x + p.tx * 1.2 - p.nx * hw * 0.6, p.y + p.ty * 1.2 - p.ny * hw * 0.6,
          p.x + p.tx * 1.2 + p.nx * hw * 0.4, p.y + p.ty * 1.2 + p.ny * hw * 0.4
        );
      }
    }

    // Frayed microscopic suede fibers sticking out along the worn edges
    if (random() < 0.75) {
      let side = random() < 0.5 ? -1 : 1;
      let ex = p.x + side * p.nx * hw;
      let ey = p.y + side * p.ny * hw;
      let fAng = atan2(p.ty, p.tx) + side * random(25, 68);
      let fLen = random(2.5, 6.5);
      brush.set("2H", side < 0 ? PAL.leatherLight : PAL.leatherDark, 0.35);
      brush.line(ex, ey, ex + cos(fAng) * fLen, ey + sin(fAng) * fLen);
    }
  }

  // Tapered cut tip at the end of the thong
  let last = dense[dense.length - 1];
  brush.set("pen", PAL.leatherAbyss, 0.8);
  brush.line(
    last.x - last.nx * baseWidth * 0.4, last.y - last.ny * baseWidth * 0.4,
    last.x + last.nx * baseWidth * 0.4, last.y + last.ny * baseWidth * 0.4
  );
}

function drawLeatherKnotLobe(x1, y1, x2, y2, w) {
  let dx = x2 - x1, dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy) || 1;
  let nx = -dy / len, ny = dx / len;

  // Shadow under knot fold
  brush.set("charcoal", PAL.shadowContact, w * 0.22);
  brush.line(x1 + 2.5, y1 + 3, x2 + 2.5, y2 + 3);

  // Dark leather body
  brush.set("marker", PAL.leatherAbyss, w * 0.25);
  brush.line(x1, y1, x2, y2);
  brush.set("marker", PAL.leatherDark, w * 0.2);
  brush.line(x1 - nx * 1.2, y1 - ny * 1.2, x2 - nx * 1.2, y2 - ny * 1.2);

  // Stretched leather highlight over the bend
  brush.set("cpencil", PAL.leatherWarm, w * 0.14);
  brush.line(x1 - nx * 2.2, y1 - ny * 2.2, x2 - nx * 2.2, y2 - ny * 2.2);
  brush.set("rotring", PAL.leatherSuede, 0.6);
  brush.line(x1 - nx * 3.2, y1 - ny * 3.2, x2 - nx * 3.2, y2 - ny * 3.2);

  // Stress creases across the knot
  for (let t = 0.2; t <= 0.8; t += 0.2) {
    let cx = lerp(x1, x2, t);
    let cy = lerp(y1, y2, t);
    brush.set("rotring", PAL.leatherAbyss, 0.45);
    brush.line(cx - nx * w * 0.38, cy - ny * w * 0.38, cx + nx * w * 0.38, cy + ny * w * 0.38);
  }
}

function sampleCatmullRom(pts, numSamples) {
  let out = [];
  let n = pts.length;
  for (let i = 0; i <= numSamples; i++) {
    let tGlobal = (i / numSamples) * (n - 1);
    let seg = constrain( floor(tGlobal), 0, n - 2);
    let t = tGlobal - seg;

    let p0 = pts[max(0, seg - 1)];
    let p1 = pts[seg];
    let p2 = pts[min(n - 1, seg + 1)];
    let p3 = pts[min(n - 1, seg + 2)];

    let t2 = t * t, t3 = t2 * t;
    let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
    let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
    out.push({ x, y, tx: 1, ty: 0, nx: 0, ny: 1 });
  }
  for (let i = 0; i < out.length; i++) {
    let prev = out[max(0, i - 1)];
    let next = out[min(out.length - 1, i + 1)];
    let dx = next.x - prev.x, dy = next.y - prev.y;
    let d = sqrt(dx * dx + dy * dy) || 1;
    out[i].tx = dx / d;
    out[i].ty = dy / d;
    out[i].nx = -dy / d;
    out[i].ny = dx / d;
  }
  return out;
}

// ============================================================================
// 6. HYPERREAL SILVER ETHIOPIAN HAND CROSS
// ============================================================================

function getCrossFiligreeStruts() {
  // Returns array of [u1, v1, u2, v2, width, isBeaded] in local cross coordinates
  let s = [];

  // 1. Central Sanctuary Square & Diamond Lattice (-46..46)
  let c = 46;
  s.push([-c, -c, c, -c, 11, true], [c, -c, c, c, 11, true], [c, c, -c, c, 11, true], [-c, c, -c, -c, 11, true]);
  let d = 64;
  s.push([0, -d, d, 0, 10, true], [d, 0, 0, d, 10, true], [0, d, -d, 0, 10, true], [-d, 0, 0, -d, 10, true]);
  // Central cruciform & X struts
  s.push([-c, 0, c, 0, 9, false], [0, -c, 0, c, 9, false]);
  s.push([-c, -c, c, c, 8, true], [-c, c, c, -c, 8, true]);

  // 2. Four Flaring Cruciform Arms (North, South, East, West)
  // Helper to add an ornate pierced lattice arm rotated by 0, 90, 180, 270 deg
  let armAngles = [0, 90, 180, 270];
  for (let a of armAngles) {
    let ca = cos(a), sa = sin(a);
    let rot = (u, v) => [u * ca - v * sa, u * sa + v * ca];
    let addArmStrut = (u1, v1, u2, v2, w, beaded) => {
      let p1 = rot(u1, v1), p2 = rot(u2, v2);
      s.push([p1[0], p1[1], p2[0], p2[1], w, beaded]);
    };

    // Arm extends from v = -46 out to v = -168, flaring in width from u = +-34 to +-62
    addArmStrut(-34, -46, -58, -158, 11, true);
    addArmStrut(34, -46, 58, -158, 11, true);
    addArmStrut(-58, -158, 0, -182, 11, true);
    addArmStrut(58, -158, 0, -182, 11, true);
    addArmStrut(-58, -158, 58, -158, 9.5, false);

    // Mid-transverse bars & internal diamond filigree inside each arm (creating pierced cross windows)
    addArmStrut(-42, -84, 42, -84, 8.5, true);
    addArmStrut(-50, -122, 50, -122, 8.5, true);
    addArmStrut(0, -46, 0, -182, 9.5, false);
    addArmStrut(-22, -46, -32, -158, 7.5, false);
    addArmStrut(22, -46, 32, -158, 7.5, false);

    // Diagonal interlace ribbons inside the arm lattice
    addArmStrut(-34, -46, 42, -84, 7, true);
    addArmStrut(34, -46, -42, -84, 7, true);
    addArmStrut(-42, -84, 50, -122, 7, true);
    addArmStrut(42, -84, -50, -122, 7, true);
    addArmStrut(-50, -122, 28, -158, 7, true);
    addArmStrut(50, -122, -28, -158, 7, true);
  }

  // 3. Four Quadrant Inter-Arm Filigree Webs (NE, SE, SW, NW)
  // Connects the flaring arms into the iconic Ethiopian diamond-quatrefoil silhouette
  let quadSigns = [[1, -1], [1, 1], [-1, 1], [-1, -1]];
  for (let qs of quadSigns) {
    let sx = qs[0], sy = qs[1];
    // Outer stepped diamond rim connecting arm corners
    s.push([sx * 58, sy * 158, sx * 112, sy * 112, 10.5, true]);
    s.push([sx * 158, sy * 58, sx * 112, sy * 112, 10.5, true]);
    // Inner concentric filigree web
    s.push([sx * 48, sy * 118, sx * 88, sy * 88, 8.5, true]);
    s.push([sx * 118, sy * 48, sx * 88, sy * 88, 8.5, true]);
    // Radial struts tying quadrant web to central sanctuary
    s.push([sx * 46, sy * 46, sx * 112, sy * 112, 9, true]);
    s.push([sx * 42, sy * 84, sx * 84, sy * 42, 7.5, false]);
    s.push([sx * 64, sy * 64, sx * 50, sy * 122, 7, true]);
    s.push([sx * 64, sy * 64, sx * 122, sy * 50, 7, true]);
  }

  return s;
}

function getCrossFinials() {
  // Returns [u, v, localAngle, scale] for the 11 ornate perimeter trefoil-cross finials
  // (North tip, East tip, West tip, and 4 quadrant pairs; South connects to the handle shaft)
  return [
    [0, -182, -90, 1.15],     // North crown finial
    [-58, -158, -118, 0.88],  // NNW
    [58, -158, -62, 0.88],    // NNE
    [182, 0, 0, 1.15],        // East crown finial
    [158, -58, -28, 0.88],    // ENE
    [158, 58, 28, 0.88],      // ESE
    [-182, 0, 180, 1.15],     // West crown finial
    [-158, -58, -152, 0.88],  // WNW
    [-158, 58, 152, 0.88],    // WSW
    [-112, -112, -135, 0.95], // NW quadrant finial
    [112, -112, -45, 0.95],   // NE quadrant finial
    [-112, 112, 135, 0.95],   // SW quadrant finial
    [112, 112, 45, 0.95]      // SE quadrant finial
  ];
}

function drawSilverHandCross() {
  // 1. Draw the Neck / Handle Shaft (*Gez*) and Lower *Tabot* Base first so the head overlaps cleanly
  drawSilverShaft();
  drawSilverTabotBase();

  // 2. Draw all the interlocking filigree struts of the Cross Head
  let struts = getCrossFiligreeStruts();
  // First pass: thinner internal struts
  for (let st of struts) {
    if (st[4] < 9.5) {
      let p1 = crossPt(st[0], st[1]);
      let p2 = crossPt(st[2], st[3]);
      drawMetallicStrut(p1[0], p1[1], p2[0], p2[1], st[4], st[5]);
    }
  }
  // Second pass: heavy primary structural frame struts on top
  for (let st of struts) {
    if (st[4] >= 9.5) {
      let p1 = crossPt(st[0], st[1]);
      let p2 = crossPt(st[2], st[3]);
      drawMetallicStrut(p1[0], p1[1], p2[0], p2[1], st[4], st[5]);
    }
  }

  // 3. Ornate silver rivets / bosses at the major lattice intersections
  let bossCoords = [
    [0, 0, 18], // Central crucifixion boss
    [0, -84, 8], [0, -122, 8], [0, -158, 8.5],
    [0, 84, 8], [0, 122, 8], [0, 158, 9],
    [-84, 0, 8], [-122, 0, 8], [-158, 0, 8.5],
    [84, 0, 8], [122, 0, 8], [158, 0, 8.5],
    [-46, -46, 9.5], [46, -46, 9.5], [46, 46, 9.5], [-46, 46, 9.5],
    [-88, -88, 7.5], [88, -88, 7.5], [88, 88, 7.5], [-88, 88, 7.5]
  ];
  for (let b of bossCoords) {
    let p = crossPt(b[0], b[1]);
    drawSilverBoss(p[0], p[1], b[2]);
  }

  // 4. Perimeter Trefoil-Cross Finials (symbolizing the Apostles)
  let finials = getCrossFinials();
  for (let fn of finials) {
    let p = crossPt(fn[0], fn[1]);
    drawSilverFinial(p[0], p[1], fn[2] + CROSS_ANGLE, fn[3]);
  }

  // 5. Micro-scratches, tarnish pits, and bright specular glints across the cross head
  drawCrossHeadScratches();
}

function drawMetallicStrut(x1, y1, x2, y2, w, isBeaded) {
  let dx = x2 - x1, dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len, ty = dy / len;
  let nx = -ty, ny = tx;

  // Determine which normal side faces the top-left light vector (-0.707, -0.707)
  let dotL = nx * (-0.707) + ny * (-0.707);
  let litSide = dotL >= 0 ? 1 : -1;
  let lnx = nx * litSide, lny = ny * litSide; // Points toward light
  let snx = -lnx, sny = -lny;                 // Points toward shadow/tarnish

  // 1. Deep oxidized silver-sulfide tarnish outer rim
  brush.set("pen", PAL.agAbyss, w * 0.25);
  brush.line(x1 + snx * w * 0.36, y1 + sny * w * 0.36, x2 + snx * w * 0.36, y2 + sny * w * 0.36);
  brush.set("pen", PAL.agTarnishWarm, w * 0.22);
  brush.line(x1 - lnx * w * 0.36, y1 - lny * w * 0.36, x2 - lnx * w * 0.36, y2 - lny * w * 0.36);

  // 2. Dark & Mid silver core body
  brush.set("marker", PAL.agDark, w * 0.22);
  brush.line(x1 + snx * w * 0.14, y1 + sny * w * 0.14, x2 + snx * w * 0.14, y2 + sny * w * 0.14);
  brush.set("marker", PAL.agMid, w * 0.20);
  brush.line(x1, y1, x2, y2);

  // 3. Warm vellum bounce-light reflection along the shadow edge
  brush.set("cpencil", PAL.agReflect, w * 0.11);
  brush.line(x1 + snx * w * 0.26, y1 + sny * w * 0.26, x2 + snx * w * 0.26, y2 + sny * w * 0.26);

  // 4. Bright lit silver bevel
  brush.set("cpencil", PAL.agLight, w * 0.15);
  brush.line(x1 + lnx * w * 0.18, y1 + lny * w * 0.18, x2 + lnx * w * 0.18, y2 + lny * w * 0.18);

  // 5. Razor-sharp specular highlight on the light-facing ridge
  brush.set("rotring", PAL.agSpec, 0.55);
  brush.line(x1 + lnx * w * 0.25, y1 + lny * w * 0.25, x2 + lnx * w * 0.25, y2 + lny * w * 0.25);

  // 6. Filigree twisted-wire / beaded engraving with dark sulfide tarnish in the notches
  if (isBeaded && len > 14) {
    let step = 5.5;
    let count = floor(len / step);
    for (let i = 1; i < count; i++) {
      let bx = x1 + tx * (i * step);
      let by = y1 + ty * (i * step);
      // Dark tarnished diagonal groove between silver rope twists
      brush.set("rotring", PAL.agAbyss, 0.55);
      brush.line(
        bx - lnx * w * 0.32 - tx * 1.4, by - lny * w * 0.32 - ty * 1.4,
        bx + lnx * w * 0.32 + tx * 1.4, by + lny * w * 0.32 + ty * 1.4
      );
      // Tiny bright specular bead glint on each rope twist
      brush.set("rotring", "#ffffff", 0.55);
      brush.line(
        bx + tx * 2.2 + lnx * w * 0.12, by + ty * 2.2 + lny * w * 0.12,
        bx + tx * 3.4 + lnx * w * 0.22, by + ty * 3.4 + lny * w * 0.22
      );
    }
  }
}

function drawSilverBoss(x, y, r) {
  // Tarnished recessed collar around the rivet/boss
  brush.noStroke();
  brush.wash(PAL.agAbyss, 230);
  brush.circle(x + 1, y + 1, r + 1.5, 0.08);

  // Metallic dome base
  brush.wash(PAL.agDark, 240);
  brush.circle(x, y, r, 0.06);
  brush.wash(PAL.agMid, 240);
  brush.circle(x - r * 0.12, y - r * 0.12, r * 0.78, 0.05);
  brush.wash(PAL.agLight, 240);
  brush.circle(x - r * 0.24, y - r * 0.24, r * 0.48, 0.05);
  brush.noWash();

  // Beaded filigree wire ring around the boss
  let beads = max(8, floor(r * 1.3));
  for (let i = 0; i < beads; i++) {
    let a = (i / beads) * 360;
    let bx = x + cos(a) * (r * 0.88);
    let by = y + sin(a) * (r * 0.88);
    brush.set("rotring", PAL.agAbyss, 0.6);
    brush.line(bx, by, bx + 1, by + 1);
    brush.set("rotring", PAL.agSpec, 0.55);
    brush.line(bx - 0.8, by - 0.8, bx, by);
  }

  // Crisp specular hot-spot on top-left of dome & warm bounce light on bottom-right
  brush.set("rotring", "#ffffff", 0.9);
  brush.line(x - r * 0.35, y - r * 0.35, x - r * 0.15, y - r * 0.42);
  brush.set("cpencil", PAL.agReflect, 0.65);
  brush.arc(x, y, r * 0.72, 15, 85);
}

function drawSilverFinial(x, y, ang, sc) {
  // Ornate Ethiopian trefoil-cross finial with silver granulation microbeads
  let tipX = x + cos(ang) * 28 * sc;
  let tipY = y + sin(ang) * 28 * sc;
  let crossX = x + cos(ang) * 14 * sc;
  let crossY = y + sin(ang) * 14 * sc;
  let armL = 12 * sc;
  let lx = crossX + cos(ang - 90) * armL;
  let ly = crossY + sin(ang - 90) * armL;
  let rx = crossX + cos(ang + 90) * armL;
  let ry = crossY + sin(ang + 90) * armL;

  drawMetallicStrut(x, y, tipX, tipY, 7.5 * sc, true);
  drawMetallicStrut(lx, ly, rx, ry, 6.8 * sc, false);

  // Three granulation silver beads at the trefoil tips
  drawSilverBoss(tipX, tipY, 3.8 * sc);
  drawSilverBoss(lx, ly, 3.2 * sc);
  drawSilverBoss(rx, ry, 3.2 * sc);
  drawSilverBoss(crossX, crossY, 4.0 * sc);
}

function drawSilverShaft() {
  // The Neck / Handle (*Gez*) from v = 175 to v = 378, u = -18..+18
  // Rendered as a hyperreal 3D cylindrical/faceted silver column worn smooth by centuries of hands
  const vTop = 175, vBot = 378;
  const hw = 17.5;

  // Longitudinal cylindrical shading bands across u from -hw to +hw
  let strips = [
    { u1: -17.5, u2: -13.5, col: PAL.agTarnishCool, brush: "pen" },
    { u1: -13.5, u2: -9.5,  col: PAL.agReflect,     brush: "cpencil" }, // Reflected warm vellum light
    { u1: -9.5,  u2: -3.5,  col: PAL.agLight,       brush: "marker" },  // Lit cylindrical face
    { u1: -3.5,  u2:  0.5,  col: PAL.agSpec,        brush: "cpencil" }, // Bright core specular band
    { u1:  0.5,  u2:  6.5,  col: PAL.agMid,         brush: "marker" },  // Mid metallic roll-off
    { u1:  6.5,  u2: 12.5,  col: PAL.agDark,        brush: "marker" },  // Core shadow
    { u1: 12.5,  u2: 15.5,  col: PAL.agTarnishWarm, brush: "pen" },     // Warm sulfide tarnish shadow
    { u1: 15.5,  u2: 17.5,  col: PAL.agSoft,        brush: "cpencil" }  // Right rim bounce light
  ];

  for (let st of strips) {
    let um = (st.u1 + st.u2) * 0.5;
    let sw = abs(st.u2 - st.u1);
    let p1 = crossPt(um, vTop);
    let p2 = crossPt(um, vBot);
    brush.set(st.brush, st.col, sw * 0.32);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Razor-sharp white specular highlight streak down the cylinder
  let sp1 = crossPt(-2.0, vTop + 10);
  let sp2 = crossPt(-2.0, vBot - 10);
  brush.set("rotring", "#ffffff", 0.85);
  brush.line(sp1[0], sp1[1], sp2[0], sp2[1]);

  // Crisp outer contours of the shaft
  let l1 = crossPt(-hw, vTop), l2 = crossPt(-hw, vBot);
  let r1 = crossPt(hw, vTop),  r2 = crossPt(hw, vBot);
  brush.set("pen", PAL.agAbyss, 0.9);
  brush.line(l1[0], l1[1], l2[0], l2[1]);
  brush.line(r1[0], r1[1], r2[0], r2[1]);

  // Engraved decorative bands & diamond knurling on the shaft
  for (let v = 220; v <= 335; v += 14) {
    let pl = crossPt(-hw + 2, v);
    let pr = crossPt(hw - 2, v + 10);
    let pl2 = crossPt(-hw + 2, v + 10);
    let pr2 = crossPt(hw - 2, v);
    brush.set("rotring", PAL.agAbyss, 0.45);
    brush.line(pl[0], pl[1], pr[0], pr[1]);
    brush.line(pl2[0], pl2[1], pr2[0], pr2[1]);
    // Tiny specular burr along engraving
    brush.set("rotring", PAL.agSpec, 0.35);
    brush.line(pl[0] - 0.8, pl[1] - 0.8, pr[0] - 0.8, pr[1] - 0.8);
  }

  // Raised torus collar moldings at top (v = 182..208) and bottom (v = 348..374) of the shaft
  let collarVs = [184, 193, 202, 278, 352, 361, 370];
  for (let cv of collarVs) {
    let cw = (cv === 193 || cv === 278 || cv === 361) ? hw + 5.5 : hw + 3.0;
    let cp1 = crossPt(-cw, cv);
    let cp2 = crossPt(cw, cv);
    drawMetallicStrut(cp1[0], cp1[1], cp2[0], cp2[1], 7.5, true);
  }

  // Fine hairline hand-wear scratches across the grip
  for (let i = 0; i < 45; i++) {
    let su = random(-hw + 3, hw - 3);
    let sv = random(208, 346);
    let p = crossPt(su, sv);
    let sAng = random(-180, 180);
    let sLen = random(4, 13);
    brush.set("rotring", random() < 0.5 ? PAL.agSpec : PAL.agTarnishCool, 0.32);
    brush.line(p[0], p[1], p[0] + cos(sAng) * sLen, p[1] + sin(sAng) * sLen);
  }
}

function drawSilverTabotBase() {
  // The square/rectangular flat plate (*Emnet* / *Tabot* box) at the bottom of the cross:
  // v = 376..488, u = -58..+58
  const uL = -58, uR = 58, vT = 376, vB = 488;

  // 1. Base metallic wash for the flat plate
  brush.noStroke();
  brush.wash(PAL.agMid, 255);
  brush.beginShape(0);
  for (let pt of [[uL, vT], [uR, vT], [uR, vB], [uL, vB]]) {
    let p = crossPt(pt[0], pt[1]);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // 2. Diagonal metallic sheen across the recessed inner panel (u: -44..44, v: 390..474)
  for (let v = 390; v <= 474; v += 2.5) {
    for (let u = -44; u <= 44; u += 18) {
      let uEnd = min(44, u + 18);
      let p1 = crossPt(u, v);
      let p2 = crossPt(uEnd, v);
      // Raking diagonal sheen: brightest along u + (v - 432) ~ -15
      let diag = (u + (v - 432)) / 88.0;
      let col = PAL.agMid;
      if (diag < -0.55) col = PAL.agTarnishCool;
      else if (diag < -0.25) col = PAL.agSoft;
      else if (diag < 0.08) col = PAL.agLight;
      else if (diag < 0.25) col = PAL.agSpec;
      else if (diag < 0.55) col = PAL.agMid;
      else col = PAL.agTarnishWarm;

      brush.set("cpencil", col, 0.95);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Deep silver-sulfide tarnish buildup in the recessed inner corners of the panel
  let innerCorners = [[-43, 391], [43, 391], [43, 473], [-43, 473]];
  for (let ic of innerCorners) {
    let p = crossPt(ic[0], ic[1]);
    brush.set("charcoal", PAL.agAbyss, 1.4);
    brush.line(p[0] - 2, p[1] - 2, p[0] + 2, p[1] + 2);
  }

  // 3. Traditional Ethiopian incised engraving on the Tabot panel
  // (Double diamond frame, central equal-armed cross, and corner solar rosettes)
  let engraveLines = [
    // Inner engraved frame
    [-42, 392, 42, 392], [42, 392, 42, 472], [42, 472, -42, 472], [-42, 472, -42, 392],
    // Inscribed diamond
    [0, 394, 40, 432], [40, 432, 0, 470], [0, 470, -40, 432], [-40, 432, 0, 394],
    [0, 402, 32, 432], [32, 432, 0, 462], [0, 462, -32, 432], [-32, 432, 0, 402],
    // Central Equal-Armed Cross with flared terminals
    [-20, 432, 20, 432], [0, 412, 0, 452],
    [-20, 426, -20, 438], [20, 426, 20, 438],
    [-6, 412, 6, 412], [-6, 452, 6, 452],
    // Corner diagonal rays
    [-38, 396, -22, 412], [38, 396, 22, 412],
    [-38, 468, -22, 452], [38, 468, 22, 452]
  ];
  for (let el of engraveLines) {
    let p1 = crossPt(el[0], el[1]);
    let p2 = crossPt(el[2], el[3]);
    // Dark incised groove (niello / sulfide tarnish)
    brush.set("rotring", PAL.agAbyss, 0.65);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    // Bright displaced metal burr highlight immediately adjacent
    brush.set("rotring", PAL.agSpec, 0.45);
    brush.line(p1[0] - 1.0, p1[1] - 1.0, p2[0] - 1.0, p2[1] - 1.0);
  }

  // 4. Heavy Raised Braided Silver Border around the Tabot Plate
  let borderStruts = [
    [uL, vT, uR, vT, 11, true],
    [uR, vT, uR, vB, 11, true],
    [uR, vB, uL, vB, 11, true],
    [uL, vB, uL, vT, 11, true],
    [-46, 388, 46, 388, 6.5, false],
    [46, 388, 46, 476, 6.5, false],
    [46, 476, -46, 476, 6.5, false],
    [-46, 476, -46, 388, 6.5, false]
  ];
  for (let bs of borderStruts) {
    let p1 = crossPt(bs[0], bs[1]);
    let p2 = crossPt(bs[2], bs[3]);
    drawMetallicStrut(p1[0], p1[1], p2[0], p2[1], bs[4], bs[5]);
  }

  // Corner bosses on the Tabot plate
  for (let cb of [[uL, vT], [uR, vT], [uR, vB], [uL, vB], [0, 432]]) {
    let p = crossPt(cb[0], cb[1]);
    drawSilverBoss(p[0], p[1], cb[0] === 0 ? 5.5 : 7.5);
  }

  // Two side finial buds on the Tabot box
  let pLeftFin = crossPt(uL, 432);
  let pRightFin = crossPt(uR, 432);
  drawSilverFinial(pLeftFin[0], pLeftFin[1], 180 + CROSS_ANGLE, 0.72);
  drawSilverFinial(pRightFin[0], pRightFin[1], 0 + CROSS_ANGLE, 0.72);

  // 5. Forged Silver Suspension Eyelet Ring at the bottom (u = 0, v = 502)
  let ringC = crossPt(0, 502);
  // Outer dark tarnish & shadow of the ring
  brush.set("pen", PAL.agAbyss, 4.2);
  brush.circle(ringC[0], ringC[1], 14, 0.06);
  // Mid silver torus
  brush.set("marker", PAL.agMid, 3.0);
  brush.circle(ringC[0], ringC[1], 14, 0.05);
  // Bright top-left specular arc on the ring
  brush.set("rotring", "#ffffff", 0.95);
  brush.arc(ringC[0], ringC[1], 14.5, 165, 315);

  // 6. Realistic surface scratches and age dings across the flat Tabot plate
  for (let i = 0; i < 65; i++) {
    let su = random(-50, 50);
    let sv = random(384, 480);
    let p1 = crossPt(su, sv);
    let sAng = random(-180, 180);
    let sLen = random(6, 26);
    let p2 = [p1[0] + cos(sAng) * sLen, p1[1] + sin(sAng) * sLen];
    // Dark scratch groove + bright edge glint
    brush.set("rotring", PAL.agTarnishCool, 0.35);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("rotring", "#ffffff", 0.32);
    brush.line(p1[0] - 0.7, p1[1] - 0.7, p2[0] - 0.7, p2[1] - 0.7);
  }
}

function drawCrossHeadScratches() {
  // Fine micro-scratches and bright specular glints across the flat junctions of the cross head
  let struts = getCrossFiligreeStruts();
  for (let st of struts) {
    let p1 = crossPt(st[0], st[1]);
    let p2 = crossPt(st[2], st[3]);
    for (let k = 0; k < 3; k++) {
      let t = random(0.15, 0.85);
      let sx = lerp(p1[0], p2[0], t);
      let sy = lerp(p1[1], p2[1], t);
      let ang = random(-180, 180);
      let len = random(4, 11);
      brush.set("rotring", random() < 0.6 ? "#ffffff" : PAL.agAbyss, 0.35);
      brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
    }
  }
}

// ============================================================================
// 8. BOLD MANUSCRIPT BORDERS (FLAT MARKER FILLS + CONFIDENT BLACK PEN CONTOURS)
// ============================================================================

function drawManuscriptBorders() {
  const bx1 = 58, by1 = 58, bx2 = 1142, by2 = 1142;
  const ix1 = 166, iy1 = 166, ix2 = 1034, iy2 = 1034;
  const bw = ix1 - bx1; // 108px total border width

  // 1. Mask/re-clean the 4 border strips so no vellum strokes bleed into the flat sacred frame
  brush.noStroke();
  brush.wash(PAL.interstice, 255);
  brush.rect(bx1, by1, bx2 - bx1, bw, "corner");        // Top
  brush.rect(bx1, iy2, bx2 - bx1, bw, "corner");        // Bottom
  brush.rect(bx1, iy1, bw, iy2 - iy1, "corner");        // Left
  brush.rect(ix2, iy1, bw, iy2 - iy1, "corner");        // Right

  // 2. Outer Guard Frame Band (Saffron flat marker wash) & Inner Guard Frame Band (Red Ochre)
  const gOut = 8, gIn = 8;
  brush.wash(PAL.saffron, 245);
  brush.rect(bx1, by1, bx2 - bx1, gOut, "corner");
  brush.rect(bx1, by2 - gOut, bx2 - bx1, gOut, "corner");
  brush.rect(bx1, by1 + gOut, gOut, by2 - by1 - 2 * gOut, "corner");
  brush.rect(bx2 - gOut, by1 + gOut, gOut, by2 - by1 - 2 * gOut, "corner");

  brush.wash(PAL.ochre, 245);
  brush.rect(ix1 - gIn, iy1 - gIn, ix2 - ix1 + 2 * gIn, gIn, "corner");
  brush.rect(ix1 - gIn, iy2, ix2 - ix1 + 2 * gIn, gIn, "corner");
  brush.rect(ix1 - gIn, iy1, gIn, iy2 - iy1, "corner");
  brush.rect(ix2, iy1, gIn, iy2 - iy1, "corner");

  // Dark charcoal-sepia background inside the main interlace channels
  brush.wash(PAL.borderBg, 250);
  brush.rect(ix1, by1 + gOut, ix2 - ix1, bw - gOut - gIn, "corner"); // Top channel
  brush.rect(ix1, iy2 + gIn, ix2 - ix1, bw - gOut - gIn, "corner");  // Bottom channel
  brush.rect(bx1 + gOut, iy1, bw - gOut - gIn, iy2 - iy1, "corner"); // Left channel
  brush.rect(ix2 + gIn, iy1, bw - gOut - gIn, iy2 - iy1, "corner");  // Right channel
  brush.noWash();

  // 3. Draw the 4 Interlaced Guilloche / Strapwork Bands (Top, Bottom, Left, Right)
  // Colors: Red Ochre, Leaf Green, Saffron
  const chThick = bw - gOut - gIn; // 92px
  drawInterlacedBand(ix1, by1 + gOut, ix2 - ix1, chThick, true);   // Top
  drawInterlacedBand(ix1, iy2 + gIn, ix2 - ix1, chThick, true);    // Bottom
  drawInterlacedBand(bx1 + gOut, iy1, chThick, iy2 - iy1, false);  // Left
  drawInterlacedBand(ix2 + gIn, iy1, chThick, iy2 - iy1, false);   // Right

  // 4. Draw the 4 Ornate Corner Knot Medallions (*Harag* Corner Squares)
  drawCornerKnotSquare(bx1 + gOut, by1 + gOut, chThick, -1, -1);
  drawCornerKnotSquare(ix2 + gIn, by1 + gOut, chThick, 1, -1);
  drawCornerKnotSquare(bx1 + gOut, iy2 + gIn, chThick, -1, 1);
  drawCornerKnotSquare(ix2 + gIn, iy2 + gIn, chThick, 1, 1);

  // 5. Confident Black Pen Contours framing the outer and inner guard bands
  brush.set("pen", PAL.ink, 1.45);
  brush.noFill();
  brush.noWash();
  brush.rect(bx1, by1, bx2 - bx1, by2 - by1, "corner");
  brush.rect(bx1 + gOut, by1 + gOut, bx2 - bx1 - 2 * gOut, by2 - by1 - 2 * gOut, "corner");
  brush.rect(ix1 - gIn, iy1 - gIn, ix2 - ix1 + 2 * gIn, iy2 - iy1 + 2 * gIn, "corner");
  brush.rect(ix1, iy1, ix2 - ix1, iy2 - iy1, "corner");

  // Traditional Ethiopian manuscript marginal dot-triplets around the outer perimeter
  drawMarginalDotTriplets(bx1, by1, bx2, by2);
}

function drawInterlacedBand(x, y, w, h, isHorizontal) {
  // True 3-strand over-under braided geometric strapwork in Red Ochre, Leaf Green, and Saffron
  const length = isHorizontal ? w : h;
  const thick = isHorizontal ? h : w;
  const numCells = 18;
  const cellLen = length / numCells; // 48px
  const pad = 7;
  const rW = 21; // Ribbon width

  const strandCols = [
    { main: PAL.ochre,   light: PAL.ochreLight },
    { main: PAL.green,   light: PAL.greenLight },
    { main: PAL.saffron, light: PAL.saffronLight }
  ];

  // Helper to convert local band coordinates (s along length, t across thickness) to canvas (x, y)
  let toXY = (s, t) => isHorizontal ? [x + s, y + t] : [x + t, y + s];

  let tTop = pad + rW * 0.5;
  let tMid = thick * 0.5;
  let tBot = thick - pad - rW * 0.5;

  // In a 3-strand braid, in cell i:
  // - One ribbon goes from tTop to tMid to tBot
  // - One ribbon goes from tBot to tMid to tTop
  // - Half-segments alternate UNDER and OVER at every crossing!
  let underSegs = [];
  let overSegs = [];

  for (let i = 0; i < numCells; i++) {
    let s0 = i * cellLen;
    let sM = (i + 0.5) * cellLen;
    let s1 = (i + 1.0) * cellLen;

    // 3 strands per cell i, cycling colors (i + k) % 3
    let cA = strandCols[i % 3];
    let cB = strandCols[(i + 1) % 3];
    let cC = strandCols[(i + 2) % 3];

    if (i % 2 === 0) {
      // First half-cell (s0 -> sM): top pair crosses; bottom strand runs along bottom edge
      underSegs.push({ p1: toXY(s0, tMid), p2: toXY(sM, tTop), col: cA });
      overSegs.push({  p1: toXY(s0, tTop), p2: toXY(sM, tMid), col: cB });
      overSegs.push({  p1: toXY(s0, tBot), p2: toXY(sM, tBot), col: cC });

      // Second half-cell (sM -> s1): bottom pair crosses; top strand runs along top edge
      overSegs.push({  p1: toXY(sM, tTop), p2: toXY(s1, tTop), col: cA });
      underSegs.push({ p1: toXY(sM, tMid), p2: toXY(s1, tBot), col: cB });
      overSegs.push({  p1: toXY(sM, tBot), p2: toXY(s1, tMid), col: cC });
    } else {
      // Symmetrical alternation for continuous 3-strand weave
      underSegs.push({ p1: toXY(s0, tBot), p2: toXY(sM, tMid), col: cA });
      overSegs.push({  p1: toXY(s0, tMid), p2: toXY(sM, tBot), col: cB });
      overSegs.push({  p1: toXY(s0, tTop), p2: toXY(sM, tTop), col: cC });

      overSegs.push({  p1: toXY(sM, tBot), p2: toXY(s1, tBot), col: cB });
      underSegs.push({ p1: toXY(sM, tTop), p2: toXY(s1, tMid), col: cC });
      overSegs.push({  p1: toXY(sM, tMid), p2: toXY(s1, tTop), col: cA });
    }
  }

  // Draw all UNDER ribbon segments first, then all OVER ribbon segments!
  for (let seg of underSegs) {
    drawMarkerRibbonSegment(seg.p1[0], seg.p1[1], seg.p2[0], seg.p2[1], rW, seg.col);
  }
  for (let seg of overSegs) {
    drawMarkerRibbonSegment(seg.p1[0], seg.p1[1], seg.p2[0], seg.p2[1], rW, seg.col);
  }

  // Small pastel diamond eyelets in the interstices of the braid
  for (let i = 0; i < numCells; i++) {
    let sc = (i + 0.5) * cellLen;
    let tc = (i % 2 === 0) ? lerp(tMid, tBot, 0.52) : lerp(tTop, tMid, 0.48);
    let ep = toXY(sc, tc);
    brush.set("pen", PAL.interstice, 0.9);
    brush.circle(ep[0], ep[1], 3.2, 0.05);
  }
}

function drawMarkerRibbonSegment(x1, y1, x2, y2, rw, colObj) {
  let dx = x2 - x1, dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len, ty = dy / len;
  let nx = -ty, ny = tx;
  let hw = rw * 0.5;

  // Slightly extend ends by 2px so adjacent segments join seamlessly before the over-crossing clips them
  let ex1 = x1 - tx * 2.5, ey1 = y1 - ty * 2.5;
  let ex2 = x2 + tx * 2.5, ey2 = y2 + ty * 2.5;

  // 1. Flat marker solid base fill
  brush.noStroke();
  brush.wash(colObj.main, 250);
  brush.beginShape(0);
  brush.vertex(ex1 - nx * hw, ey1 - ny * hw);
  brush.vertex(ex2 - nx * hw, ey2 - ny * hw);
  brush.vertex(ex2 + nx * hw, ey2 + ny * hw);
  brush.vertex(ex1 + nx * hw, ey1 + ny * hw);
  brush.endShape(true);
  brush.noWash();

  // 2. Layered marker stroke along the ribbon for authentic felt-tip marker pigment feel
  brush.set("marker", colObj.main, rw * 0.24);
  brush.line(x1, y1, x2, y2);
  brush.set("marker", colObj.light, rw * 0.12);
  brush.line(x1 - nx * hw * 0.2, y1 - ny * hw * 0.2, x2 - nx * hw * 0.2, y2 - ny * hw * 0.2);

  // 3. Central decorative pale thread line inside the strap
  brush.set("rotring", PAL.interstice, 0.55);
  brush.line(x1, y1, x2, y2);

  // 4. Confident black pen contours along both edges of the ribbon
  brush.set("pen", PAL.ink, 1.15);
  brush.line(ex1 - nx * hw, ey1 - ny * hw, ex2 - nx * hw, ey2 - ny * hw);
  brush.line(ex1 + nx * hw, ey1 + ny * hw, ex2 + nx * hw, ey2 + ny * hw);
}

function drawCornerKnotSquare(x, y, s, dirX, dirY) {
  // Ornate Ethiopian *Harag* corner medallion with interlaced square + diagonal diamond lozenge
  let cx = x + s * 0.5;
  let cy = y + s * 0.5;

  // Dark background square
  brush.noStroke();
  brush.wash(PAL.borderBg, 255);
  brush.rect(x, y, s, s, "corner");
  brush.noWash();

  let r1 = s * 0.36;
  let r2 = s * 0.42;
  let rw = 17;

  // 4 sides of the upright square (Red Ochre) and 4 sides of the tilted diamond (Leaf Green)
  // Interlaced over-under around the center!
  let sqPts = [
    [cx - r1, cy - r1], [cx + r1, cy - r1],
    [cx + r1, cy + r1], [cx - r1, cy + r1]
  ];
  let diaPts = [
    [cx, cy - r2], [cx + r2, cy],
    [cx, cy + r2], [cx - r2, cy]
  ];

  let cOchre = { main: PAL.ochre, light: PAL.ochreLight };
  let cGreen = { main: PAL.green, light: PAL.greenLight };
  let cSaff  = { main: PAL.saffron, light: PAL.saffronLight };

  // Draw full segments first, then re-draw the OVER half-segments to create a true Solomon's knot!
  for (let i = 0; i < 4; i++) {
    let p1 = sqPts[i], p2 = sqPts[(i + 1) % 4];
    drawMarkerRibbonSegment(p1[0], p1[1], p2[0], p2[1], rw, cOchre);
  }
  for (let i = 0; i < 4; i++) {
    let p1 = diaPts[i], p2 = diaPts[(i + 1) % 4];
    drawMarkerRibbonSegment(p1[0], p1[1], p2[0], p2[1], rw, cGreen);
  }
  // Over-crossings of the upright square
  for (let i = 0; i < 4; i++) {
    let p1 = sqPts[i], p2 = sqPts[(i + 1) % 4];
    let pm = [(p1[0] + p2[0]) * 0.5, (p1[1] + p2[1]) * 0.5];
    drawMarkerRibbonSegment(p1[0], p1[1], pm[0], pm[1], rw, cOchre);
  }

  // Central saffron cruciform rosette inside the knot
  drawMarkerRibbonSegment(cx - 14, cy, cx + 14, cy, 12, cSaff);
  drawMarkerRibbonSegment(cx, cy - 14, cx, cy + 14, 12, cSaff);

  brush.noStroke();
  brush.wash(PAL.interstice, 250);
  brush.circle(cx, cy, 5.5, 0.05);
  brush.noWash();
  brush.set("pen", PAL.ink, 1.1);
  brush.circle(cx, cy, 5.5, 0.05);

  // Confident black pen box framing the corner square
  brush.set("pen", PAL.ink, 1.35);
  brush.noFill();
  brush.rect(x, y, s, s, "corner");

  // Diagonal corner finial projecting into the outer parchment margin (classic Ethiopian Harag motif)
  let cornerX = dirX < 0 ? x - 8 : x + s + 8;
  let cornerY = dirY < 0 ? y - 8 : y + s + 8;
  let tipX = cornerX + dirX * 32;
  let tipY = cornerY + dirY * 32;

  drawMarkerRibbonSegment(cornerX, cornerY, tipX, tipY, 12, cOchre);
  drawMarkerRibbonSegment(
    cornerX + dirX * 16 - dirY * 12, cornerY + dirY * 16 + dirX * 12,
    cornerX + dirX * 16 + dirY * 12, cornerY + dirY * 16 - dirX * 12,
    10, cSaff
  );
  // Red & black terminal dots at finial tip
  brush.set("pen", PAL.ink, 1.2);
  brush.circle(tipX + dirX * 6, tipY + dirY * 6, 3.2, 0.05);
  brush.set("pen", PAL.rubric, 1.1);
  brush.circle(tipX + dirX * 12, tipY + dirY * 12, 2.2, 0.05);
}

function drawMarginalDotTriplets(bx1, by1, bx2, by2) {
  // Rhythmic black-and-red dot triplets along the outer manuscript border edge
  let step = 96;
  for (let d = bx1 + 115; d <= bx2 - 115; d += step) {
    drawDotTriplet(d, by1 - 8, 0, -1);
    drawDotTriplet(d, by2 + 8, 0, 1);
    drawDotTriplet(bx1 - 8, d, -1, 0);
    drawDotTriplet(bx2 + 8, d, 1, 0);
  }
}

function drawDotTriplet(x, y, nx, ny) {
  let tx = -ny, ty = nx;
  brush.set("pen", PAL.ink, 1.15);
  brush.circle(x - tx * 5, y - ty * 5, 2.2, 0.05);
  brush.circle(x + tx * 5, y + ty * 5, 2.2, 0.05);
  brush.set("pen", PAL.rubric, 1.25);
  brush.circle(x + nx * 5, y + ny * 5, 2.6, 0.05);
}

