function draw() {
  translate(-width / 2, -height / 2);
  randomSeed(4279);
  noiseSeed(8192);

  // Warm luminous paper ground (shines through pale citrine crown & caustic heart)
  background("#fff7db");

  // Core geometry of the domed resin paperweight
  const CX = 565;
  const CY = 535;
  const R = 355;
  const Y_BASE = 758; // Where spherical dome meets beveled base
  const RX_BASE = 276; // sqrt(355^2 - (758-535)^2) = 276.2
  const RY_BASE = 74;
  const Y_FOOT = 772; // Contact plane on the walnut desk

  // Dandelion seed head center inside the dome
  const DX = 552;
  const DY = 524;
  const D_RAD = 172;

  // =========================================================================
  // 1. DARK WALNUT DESK & ATMOSPHERIC BACKGROUND
  // =========================================================================
  drawWalnutDesk(CX, CY, R, RX_BASE, RY_BASE, Y_FOOT);

  // =========================================================================
  // 2. HEAVY REFRACTED SHADOW & GOLDEN CAUSTIC POOL
  // =========================================================================
  drawCausticShadowPool(CX, CY, R, RX_BASE, RY_BASE, Y_FOOT);

  // =========================================================================
  // 3. LAYERED WATERCOLOUR GLAZES OF THE RESIN DOME
  //    (Pale Citrine Crown -> Deep Honey & Cognac -> Treacly Burnt Sienna Base)
  // =========================================================================
  drawResinWatercolourGlazes(CX, CY, R, Y_BASE, RX_BASE, RY_BASE, Y_FOOT, DX, DY);

  // =========================================================================
  // 4. INTERNAL BASE MENISCUS & REFRACTED DESK RIM
  // =========================================================================
  drawInternalBaseRefraction(CX, CY, R, Y_BASE, RX_BASE, RY_BASE, Y_FOOT);

  // =========================================================================
  // 5. SUSPENDED DANDELION SEED HEAD (BACK HEMISPHERE, STEM, CORE, FRONT)
  // =========================================================================
  drawSuspendedDandelion(DX, DY, D_RAD, CX, CY, R, Y_BASE);

  // =========================================================================
  // 6. DRIFTING DETACHED SEEDS
  // =========================================================================
  drawDetachedSeeds(CX, CY, R);

  // =========================================================================
  // 7. HAIRLINE STRESS FRACTURES (INTERNAL CRAZING & LIFTED HIGHLIGHTS)
  // =========================================================================
  drawStressFractures(CX, CY, R, Y_BASE, RX_BASE, RY_BASE);

  // =========================================================================
  // 8. TRAPPED AIR BUBBLES (MACRO TO MICRO)
  // =========================================================================
  drawTrappedBubbles(CX, CY, R, DX, DY, D_RAD, Y_BASE);

  // =========================================================================
  // 9. SURFACE SPECULAR HIGHLIGHT, OPTICAL RIM & FINAL LUMINOUS GLAZES
  // =========================================================================
  drawDomeSpecularAndRim(CX, CY, R, Y_BASE, RX_BASE, RY_BASE, Y_FOOT);

  noLoop();
}

// ===========================================================================
// HELPER: Check if point lies inside the 2D silhouette of the resin paperweight
// ===========================================================================
function inDomeSilhouette(x, y, cx, cy, r, yBase, rxBase, ryBase, yFoot) {
  if (y < yBase) {
    let dx = x - cx;
    let dy = y - cy;
    return dx * dx + dy * dy <= r * r;
  } else {
    // Beveled base region between yBase and yFoot + ryBase
    let nx = (x - cx) / rxBase;
    let ny = (y - (yBase + (yFoot - yBase) * 0.5)) / (ryBase + (yFoot - yBase) * 0.5);
    return nx * nx + ny * ny <= 1.03;
  }
}

// ===========================================================================
//Helper: Polygon ring/crescent builder for watercolour washes
// ===========================================================================
function drawWashPolygon(pts, col, opacity, bleed = 0.2, tex = 0.55, border = 0.3) {
  brush.noStroke();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(0.35);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

// ===========================================================================
// 1. DARK WALNUT DESK & WOODGRAIN
// ===========================================================================
function drawWalnutDesk(cx, cy, r, rxBase, ryBase, yFoot) {
  // Deep warm background behind the top of the dome
  // Leave the dome interior untouched so the pale citrine crown stays pure
  let bgLeft = [
    [-40, -40], [cx + 80, -40],
    [cx - 80, cy - r + 15], [cx - r + 10, cy - 120],
    [cx - r - 5, cy + 120], [-40, cy + 180]
  ];
  drawWashPolygon(bgLeft, "#240d04", 190, 0.25, 0.6, 0.35);

  let bgRight = [
    [cx - 60, -40], [1240, -40],
    [1240, cy + 180], [cx + r + 5, cy + 120],
    [cx + r - 10, cy - 120], [cx + 60, cy - r + 15]
  ];
  drawWashPolygon(bgRight, "#1f0b03", 205, 0.25, 0.6, 0.35);

  // Lower walnut desk slabs around the paperweight and caustic zone
  // Left desk slab
  let deskLeft = [
    [-40, cy + 40], [cx - r + 25, cy + 40],
    [cx - rxBase + 10, yFoot], [cx + 40, yFoot + ryBase + 5],
    [cx + 120, 1240], [-40, 1240]
  ];
  drawWashPolygon(deskLeft, "#3d1b0a", 185, 0.22, 0.65, 0.4);
  drawWashPolygon(deskLeft, "#260f04", 130, 0.18, 0.5, 0.3);

  // Bottom & far-right desk slab (curving around the golden caustic pool at x:620..1040, y:730..940)
  let deskBottom = [
    [-40, yFoot + ryBase - 10], [cx + 140, yFoot + ryBase + 15],
    [760, 935], [1030, 920], [1240, 830],
    [1240, 1240], [-40, 1240]
  ];
  drawWashPolygon(deskBottom, "#331507", 195, 0.25, 0.65, 0.35);

  let deskUpperRight = [
    [cx + r - 20, cy + 20], [1240, cy + 20],
    [1240, 860], [1040, 810], [860, 725], [cx + rxBase - 10, yFoot - 20]
  ];
  drawWashPolygon(deskUpperRight, "#2e1306", 190, 0.22, 0.6, 0.35);

  // Warm illuminated walnut glow surrounding the dome base & caustic area
  let warmWalnutHalo = [
    [cx - rxBase - 120, yFoot - 60], [cx + rxBase + 380, yFoot - 90],
    [1150, 960], [cx - 100, 1020], [cx - rxBase - 160, yFoot + 120]
  ];
  drawWashPolygon(warmWalnutHalo, "#7a3b12", 95, 0.35, 0.55, 0.25);

  // Woodgrain cathedral arches & burled walnut fibers across the desk
  // Desk plane runs from y = 390 (horizon behind dome) down to 1200
  const tilt = -6.5;
  const cosT = cos(tilt);
  const sinT = sin(tilt);

  for (let row = 0; row < 210; row++) {
    let baseY = map(row, 0, 209, 380, 1210);
    // Perspective spacing: tighter near horizon, wider in foreground
    let perspY = 380 + pow((baseY - 380) / 830, 1.25) * 840;

    let grainPointsLeft = [];
    let grainPointsRight = [];

    for (let x = -30; x <= 1230; x += 22) {
      // Transform into wood plank coordinates for cathedral heartwood arches
      let wx = (x - 650) * cosT - (perspY - 880) * sinT;
      let wy = (x - 650) * sinT + (perspY - 880) * cosT;

      // Cathedral arch distortion
      let arch = sin(wx * 0.22 + noise(wx * 0.004, wy * 0.008) * 180) * 18;
      let knot = 26 * exp(- (pow(wx - 180, 2) / 18000 + pow(wy - 90, 2) / 4500)) * sin(wx * 0.5);
      let yPos = perspY + arch + knot + (x - 600) * tan(tilt);

      // Skip points inside the upper dome (above yBase - 40) so the pale crown stays clean
      let insideUpperDome = dist(x, yPos, cx, cy) < r - 8 && yPos < 710;
      if (!insideUpperDome) {
        grainPointsLeft.push([x, yPos]);
      } else {
        if (grainPointsLeft.length >= 3) {
          strokeWalnutGrainSegment(grainPointsLeft, row);
        }
        grainPointsLeft = [];
      }
    }
    if (grainPointsLeft.length >= 3) {
      strokeWalnutGrainSegment(grainPointsLeft, row);
    }
  }

  // Deep vignette toning in upper background corners using soft glaze & charcoal
  for (let i = 0; i < 45; i++) {
    let angle = random(-180, 15);
    let rad = random(r + 18, 860);
    let px = cx + cos(angle) * rad;
    let py = cy + sin(angle) * rad;
    if (py < 480 && dist(px, py, cx, cy) > r + 10) {
      let len = random(90, 220);
      let tang = angle + 90 + random(-12, 12);
      brush.set("glaze", random(["#140601", "#1f0a03", "#2b1005"]), random(1.2, 2.4));
      brush.line(
        px - cos(tang) * len * 0.5,
        py - sin(tang) * len * 0.5,
        px + cos(tang) * len * 0.5,
        py + sin(tang) * len * 0.5
      );
    }
  }
}

function strokeWalnutGrainSegment(pts, rowIdx) {
  let midPt = pts[floor(pts.length / 2)];
  let mx = midPt[0];
  let my = midPt[1];

  // Check proximity to golden caustic pool (centered around 835, 835)
  let dCaustic = dist(mx, my, 835, 835);
  let col;
  let w = random(0.6, 1.35);

  if (dCaustic < 220) {
    // Illuminated bronze/amber woodgrain inside the refracted light pool
    col = random(["#6e320c", "#8c4312", "#a85719", "#522207"]);
  } else if (my < 520) {
    col = random(["#170802", "#210c04", "#2e1206"]);
  } else {
    col = (rowIdx % 3 === 0)
      ? random(["#140702", "#1f0b03", "#2b1105"])
      : random(["#381808", "#4d230d", "#5e2c11", "#260f04"]);
  }

  brush.set("grain_pencil", col, w);
  brush.spline(pts, 0.4);

  // Occasional dark wood pores along the grain
  if (random() < 0.35 && pts.length > 4) {
    let p = random(pts);
    brush.set("rotring", "#120601", 0.35);
    brush.line(p[0], p[1], p[0] + random(8, 22), p[1] - random(1, 3));
  }
}

// ===========================================================================
// 2. HEAVY REFRACTED SHADOW & GOLDEN CAUSTIC POOL
// ===========================================================================
function drawCausticShadowPool(cx, cy, r, rxBase, ryBase, yFoot) {
  // Cast shadow stretches to the right / front-right from the paperweight base
  const shCx = 785;
  const shCy = 830;
  const shRx = 345;
  const shRy = 132;
  const shTilt = 11;

  // 2A. Heavy dark umbra outer ring (blocked peripheral rays)
  let outerShadowPts = [];
  for (let a = 0; a < 360; a += 10) {
    let lx = cos(a) * shRx;
    let ly = sin(a) * shRy;
    let rx = shCx + lx * cos(shTilt) - ly * sin(shTilt);
    let ry = shCy + lx * sin(shTilt) + ly * cos(shTilt);
    outerShadowPts.push([rx, ry]);
  }
  drawWashPolygon(outerShadowPts, "#210c03", 145, 0.25, 0.6, 0.35);

  // Darker shadow rim along the far right & bottom edge of the cast shadow
  let crescentShadowPts = [];
  for (let a = -65; a <= 135; a += 8) {
    let lx = cos(a) * shRx * 1.02;
    let ly = sin(a) * shRy * 1.02;
    crescentShadowPts.push([
      shCx + lx * cos(shTilt) - ly * sin(shTilt),
      shCy + lx * sin(shTilt) + ly * cos(shTilt)
    ]);
  }
  for (let a = 135; a >= -65; a -= 8) {
    let lx = cos(a) * shRx * 0.68;
    let ly = sin(a) * shRy * 0.68;
    crescentShadowPts.push([
      shCx + 30 + lx * cos(shTilt) - ly * sin(shTilt),
      shCy + 5 + lx * sin(shTilt) + ly * cos(shTilt)
    ]);
  }
  drawWashPolygon(crescentShadowPts, "#120601", 175, 0.2, 0.55, 0.4);

  // 2B. Refracted Golden Caustic Pool focused inside the shadow
  const cCx = 825;
  const cCy = 832;
  const causticLayers = [
    { rx: 235, ry: 95, offX: -15, col: "#b84a08", op: 115 },
    { rx: 195, ry: 80, offX: 0,   col: "#d96b0f", op: 125 },
    { rx: 155, ry: 64, offX: 14,  col: "#f2971b", op: 135 },
    { rx: 118, ry: 48, offX: 26,  col: "#fcbd35", op: 145 },
    { rx: 82,  ry: 34, offX: 36,  col: "#ffe36e", op: 155 },
    { rx: 46,  ry: 20, offX: 44,  col: "#fff8bf", op: 165 }
  ];

  for (let layer of causticLayers) {
    let pts = [];
    for (let a = 0; a < 360; a += 12) {
      let lx = cos(a) * layer.rx;
      let ly = sin(a) * layer.ry;
      pts.push([
        cCx + layer.offX + lx * cos(shTilt) - ly * sin(shTilt),
        cCy + lx * sin(shTilt) + ly * cos(shTilt)
      ]);
    }
    drawWashPolygon(pts, layer.col, layer.op, 0.22, 0.45, 0.2);
  }

  // 2C. Optical caustic arcs & refracted light striations inside the pool
  for (let i = 0; i < 65; i++) {
    let t = i / 64;
    let arcRx = lerp(30, 225, t);
    let arcRy = lerp(14, 90, t);
    let centerShift = lerp(48, -18, t);
    let span = lerp(55, 115, sin(t * 180));
    let startA = -span + random(-15, 15);
    let endA = span + random(-15, 15);

    let arcPts = [];
    for (let a = startA; a <= endA; a += 8) {
      let lx = cos(a) * arcRx;
      let ly = sin(a) * arcRy;
      // Slight cusp wave
      let wave = sin(a * 3 + i * 19) * 3.5;
      arcPts.push([
        cCx + centerShift + (lx + wave) * cos(shTilt) - ly * sin(shTilt),
        cCy + (lx + wave) * sin(shTilt) + ly * cos(shTilt)
      ]);
    }

    let cCol;
    if (t < 0.25) cCol = random(["#fffdf0", "#fff4ad", "#ffe473"]);
    else if (t < 0.6) cCol = random(["#ffd24c", "#f7a823", "#e68312"]);
    else cCol = random(["#cc5f0a", "#9e3f06", "#752803"]);

    brush.set(t < 0.35 ? "filament" : "cpencil", cCol, random(0.65, 1.35));
    brush.spline(arcPts, 0.45);
  }

  // Deep velvety contact shadow directly beneath the paperweight foot
  for (let i = 0; i < 38; i++) {
    let a1 = random(10, 195);
    let a2 = a1 + random(18, 45);
    let radScale = random(0.97, 1.07);
    let pts = [];
    for (let a = a1; a <= a2; a += 5) {
      pts.push([
        cx + cos(a) * rxBase * radScale,
        yFoot + sin(a) * ryBase * radScale + random(1, 9)
      ]);
    }
    brush.set("charcoal", random(["#0f0401", "#1a0802", "#290e04"]), random(0.7, 1.4));
    brush.spline(pts, 0.35);
  }
}

// ===========================================================================
// 3. LAYERED WATERCOLOUR GLAZES OF THE RESIN DOME
// ===========================================================================
function drawResinWatercolourGlazes(cx, cy, r, yBase, rxBase, ryBase, yFoot, dx, dy) {
  // Helper to clip a horizontal band [yMin, yMax] inside the dome contour
  function makeDomeBand(yMin, yMax, inset = 2, curveSag = 0) {
    let pts = [];
    let steps = 16;
    // Left edge from yMin to yMax
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = lerp(yMin, yMax, t);
      let halfW = getDomeHalfWidth(y, cx, cy, r, yBase, rxBase, ryBase, yFoot) - inset;
      if (halfW > 4) pts.push([cx - halfW, y]);
    }
    // Bottom curve from left to right (with optional meniscus sag)
    let botW = getDomeHalfWidth(yMax, cx, cy, r, yBase, rxBase, ryBase, yFoot) - inset;
    if (botW > 4) {
      for (let i = 1; i < 8; i++) {
        let u = map(i, 0, 8, -1, 1);
        pts.push([cx + u * botW, yMax + (1 - u * u) * curveSag]);
      }
    }
    // Right edge from yMax to yMin
    for (let i = steps; i >= 0; i--) {
      let t = i / steps;
      let y = lerp(yMin, yMax, t);
      let halfW = getDomeHalfWidth(y, cx, cy, r, yBase, rxBase, ryBase, yFoot) - inset;
      if (halfW > 4) pts.push([cx + halfW, y]);
    }
    // Top curve from right to left
    let topW = getDomeHalfWidth(yMin, cx, cy, r, yBase, rxBase, ryBase, yFoot) - inset;
    if (topW > 4) {
      for (let i = 7; i >= 1; i--) {
        let u = map(i, 0, 8, -1, 1);
        pts.push([cx + u * topW, yMin + (1 - u * u) * curveSag * 0.6]);
      }
    }
    return pts;
  }

  // 3A. Overall base wash of pale citrine across the entire dome
  let fullDomePts = makeDomeBand(cy - r + 3, yFoot + ryBase - 2, 2, 12);
  drawWashPolygon(fullDomePts, "#fae57a", 75, 0.14, 0.4, 0.2);

  // 3B. Crown glazes: Pale Citrine & Lemon Champagne (top of dome)
  let crownBand1 = makeDomeBand(cy - r + 4, cy - 150, 4, 28);
  drawWashPolygon(crownBand1, "#fff6b3", 95, 0.16, 0.35, 0.18);

  let crownBand2 = makeDomeBand(cy - 260, cy - 50, 4, 38);
  drawWashPolygon(crownBand2, "#f7d24c", 90, 0.18, 0.45, 0.22);

  // 3C. Mid-body glazes: Warm Golden Honey & Glowing Amber (behind the dandelion)
  let honeyBand1 = makeDomeBand(cy - 140, cy + 90, 3, 48);
  drawWashPolygon(honeyBand1, "#e8981c", 110, 0.2, 0.5, 0.25);

  let honeyBand2 = makeDomeBand(cy - 60, cy + 160, 3, 55);
  drawWashPolygon(honeyBand2, "#d47311", 120, 0.2, 0.55, 0.28);

  // Deep cognac flank crescents on left and right sides of the mid-dome (optical thickness)
  let leftCognacPts = [];
  for (let a = 115; a <= 235; a += 8) {
    leftCognacPts.push([cx + cos(a) * (r - 4), cy + sin(a) * (r - 4)]);
  }
  for (let a = 235; a >= 115; a -= 8) {
    leftCognacPts.push([cx + cos(a) * (r * 0.56), cy + sin(a) * (r * 0.64)]);
  }
  drawWashPolygon(leftCognacPts, "#b54b07", 110, 0.22, 0.55, 0.3);

  let rightCognacPts = [];
  for (let a = -55; a <= 65; a += 8) {
    rightCognacPts.push([cx + cos(a) * (r - 4), cy + sin(a) * (r - 4)]);
  }
  for (let a = 65; a >= -55; a -= 8) {
    rightCognacPts.push([cx + cos(a) * (r * 0.48), cy + sin(a) * (r * 0.62)]);
  }
  drawWashPolygon(rightCognacPts, "#a83e05", 130, 0.22, 0.55, 0.3);

  // 3D. Lower body & Base glazes: Deep Cognac to Treacly Burnt Sienna
  let siennaBand1 = makeDomeBand(cy + 50, yBase + 25, 3, 58);
  drawWashPolygon(siennaBand1, "#b84406", 130, 0.2, 0.58, 0.3);

  let siennaBand2 = makeDomeBand(cy + 130, yFoot + ryBase - 4, 3, 52);
  drawWashPolygon(siennaBand2, "#8f2903", 145, 0.18, 0.62, 0.35);

  let siennaBand3 = makeDomeBand(cy + 195, yFoot + ryBase - 2, 2, 42);
  drawWashPolygon(siennaBand3, "#5e1502", 160, 0.16, 0.65, 0.38);

  let baseTreacleBand = makeDomeBand(yBase - 10, yFoot + ryBase - 2, 2, 28);
  drawWashPolygon(baseTreacleBand, "#3b0a01", 165, 0.14, 0.6, 0.4);

  // 3E. Internal Golden Heart Glow around the Dandelion Seed Head
  for (let ring = 3; ring >= 1; ring--) {
    let rad = ring * 68;
    let glowPts = [];
    for (let a = 0; a < 360; a += 15) {
      glowPts.push([dx + cos(a) * rad, dy - 10 + sin(a) * rad * 0.92]);
    }
    let col = ring === 3 ? "#e88d17" : (ring === 2 ? "#f7b92e" : "#ffe26b");
    drawWashPolygon(glowPts, col, 65, 0.25, 0.4, 0.15);
  }

  // 3F. Smooth optical contour glazes using custom "glaze" marker brush
  // Following spherical latitudes from crown to base
  for (let i = 0; i < 95; i++) {
    let t = i / 94;
    let yCenter = lerp(cy - r + 28, yFoot + ryBase - 12, t);
    let sag = sin(t * 180) * 58 + (t > 0.7 ? 38 : 0);
    let halfW = getDomeHalfWidth(yCenter, cx, cy, r, yBase, rxBase, ryBase, yFoot) - 14;
    if (halfW < 25) continue;

    let pts = [];
    for (let s = -1; s <= 1; s += 0.2) {
      let px = cx + s * halfW;
      let py = yCenter + (1 - s * s) * sag;
      if (inDomeSilhouette(px, py, cx, cy, r - 4, yBase, rxBase, ryBase, yFoot)) {
        pts.push([px, py]);
      }
    }
    if (pts.length >= 3) {
      let gCol;
      if (t < 0.2) gCol = random(["#fff9c7", "#fae678", "#f5cf42"]);
      else if (t < 0.48) gCol = random(["#f0b126", "#e08716", "#cc670c"]);
      else if (t < 0.75) gCol = random(["#ba4c07", "#9e3604", "#822303"]);
      else gCol = random(["#661602", "#4a0d01", "#300600"]);

      brush.set("glaze", gCol, random(1.1, 2.1));
      brush.spline(pts, 0.45);
    }
  }
}

function getDomeHalfWidth(y, cx, cy, r, yBase, rxBase, ryBase, yFoot) {
  if (y < cy - r) return 0;
  if (y <= yBase) {
    let dy = y - cy;
    let sq = r * r - dy * dy;
    return sq > 0 ? sqrt(sq) : 0;
  }
  let midBaseY = yBase + (yFoot - yBase) * 0.5;
  let totalRy = ryBase + (yFoot - yBase) * 0.5;
  let ny = (y - midBaseY) / totalRy;
  if (abs(ny) > 1) return 0;
  return rxBase * sqrt(1 - ny * ny);
}

// ===========================================================================
// 4. INTERNAL BASE MENISCUS & REFRACTED DESK RIM
// ===========================================================================
function drawInternalBaseRefraction(cx, cy, r, yBase, rxBase, ryBase, yFoot) {
  // Through the lower dome, the back rim of the flat circular base is visible as a
  // glowing refracted meniscus arch around y = yBase - ryBase (curving from 684 to 758)
  for (let pass = 0; pass < 26; pass++) {
    let t = pass / 25;
    let rx = rxBase * lerp(0.92, 0.99, t);
    let ry = ryBase * lerp(0.85, 1.05, t);
    let pts = [];
    // Back half of base ellipse (-172 to -8 degrees)
    for (let a = -170; a <= -10; a += 8) {
      pts.push([cx + cos(a) * rx, yBase + sin(a) * ry]);
    }
    let col;
    if (t < 0.3) col = "#3d0d01";
    else if (t < 0.65) col = random(["#8f3004", "#b84a08", "#d96e11"]);
    else col = random(["#f29f24", "#ffca52", "#752003"]);

    brush.set(t > 0.6 ? "cpencil" : "grain_pencil", col, random(0.7, 1.5));
    brush.spline(pts, 0.4);
  }

  // Front beveled base rings (syrupy burnt sienna & internal gold reflections at yBase..yFoot+ryBase)
  for (let pass = 0; pass < 36; pass++) {
    let t = pass / 35;
    let yShift = lerp(yBase - 6, yFoot + 4, t);
    let rx = rxBase * lerp(0.995, 0.97, abs(t - 0.5));
    let ry = ryBase * lerp(0.96, 1.02, t);

    let aStart = random(5, 25);
    let aEnd = random(155, 175);
    let pts = [];
    for (let a = aStart; a <= aEnd; a += 7) {
      pts.push([cx + cos(a) * rx, yShift + sin(a) * ry]);
    }

    let col;
    if (t < 0.25) col = random(["#2e0801", "#4f1202", "#7a2404"]);
    else if (t < 0.55) col = random(["#d96c0f", "#f5a623", "#ffd666", "#993105"]);
    else if (t < 0.85) col = random(["#591402", "#380901", "#852704"]);
    else col = random(["#e6941c", "#ffcf59", "#240601"]);

    brush.set(random() < 0.5 ? "cpencil" : "needle", col, random(0.6, 1.3));
    brush.spline(pts, 0.4);
  }
}

// ===========================================================================
// 5. SUSPENDED DANDELION SEED HEAD (BOTANICAL HYPERREALISM)
// ===========================================================================
function drawSuspendedDandelion(dx, dy, dRad, cx, cy, r, yBase) {
  // Generate 168 seeds in a 3D Fibonacci sphere around (dx, dy, 0)
  const numSeeds = 168;
  const goldenRatio = (1 + sqrt(5)) / 2;
  let seeds = [];

  for (let i = 0; i < numSeeds; i++) {
    let theta = 360 * i / goldenRatio;
    let z = 1 - (2 * (i + 0.5)) / numSeeds; // +1 (front) to -1 (back)
    // Wait: let's make y3d be the vertical axis so the stem gap is at the bottom (y3d > 0.82)
    let y3d = 1 - (2 * (i + 0.5)) / numSeeds;
    let rSlice = sqrt(max(0, 1 - y3d * y3d));
    let x3d = cos(theta) * rSlice;
    let z3d = sin(theta) * rSlice;

    // Exclude small cone at bottom-left where stem enters (around (-0.2, 0.95, 0))
    let stemDot = x3d * (-0.18) + y3d * 0.96 + z3d * (-0.1);
    if (stemDot > 0.87) continue;

    // Slight organic botanical perturbation
    let nx = x3d + random(-0.05, 0.05);
    let ny = y3d + random(-0.05, 0.05);
    let nz = z3d + random(-0.05, 0.05);
    let mag = sqrt(nx * nx + ny * ny + nz * nz);
    nx /= mag;
    ny /= mag;
    nz /= mag;

    let seedRadius = dRad * random(0.92, 1.05);
    seeds.push({
      nx, ny, nz,
      radius: seedRadius,
      beakCurve: random(-7, 7),
      numHairs: floor(random(28, 36)),
      hairLen: random(38, 52),
      seedId: i
    });
  }

  // Sort seeds from deepest back (nz = -1) to closest front (nz = +1)
  seeds.sort((a, b) => a.nz - b.nz);

  // -------------------------------------------------------------------------
  // 5A. Draw BACK HEMISPHERE seeds (nz < -0.08)
  // -------------------------------------------------------------------------
  for (let s of seeds) {
    if (s.nz < -0.08) {
      drawSingleDandelionSeed(dx, dy, s);
    }
  }

  // Subtle internal amber resin veil over the back hemisphere to create depth
  for (let i = 0; i < 14; i++) {
    let a = random(0, 360);
    let rad = random(30, dRad * 0.85);
    let px = dx + cos(a) * rad;
    let py = dy + sin(a) * rad;
    let col = py < dy ? "#f2ad29" : "#b84c08";
    brush.set("glaze", col, random(1.0, 1.8));
    brush.line(px - 35, py - 10, px + 35, py + 10);
  }

  // -------------------------------------------------------------------------
  // 5B. Draw DANDELION STEM (PEDUNCLE), INVOLUCRAL BRACTS & RECEPTACLE CORE
  // -------------------------------------------------------------------------
  drawDandelionStemAndCore(dx, dy, yBase);

  // -------------------------------------------------------------------------
  // 5C. Draw MID-RIM & FRONT HEMISPHERE seeds (nz >= -0.08)
  // -------------------------------------------------------------------------
  for (let s of seeds) {
    if (s.nz >= -0.08) {
      drawSingleDandelionSeed(dx, dy, s);
    }
  }
}

function drawDandelionStemAndCore(dx, dy, yBase) {
  // Stem curves from bottom resin cut (516, 764) up to receptacle (dx, dy + 12)
  const stemStart = [516, 764];
  const stemMid1  = [526, 692];
  const stemMid2  = [541, 612];
  const stemEnd   = [dx, dy + 12];

  // Dark amber shadow aura along stem in resin
  brush.set("glaze", "#591802", 0.9);
  brush.spline([stemStart, stemMid1, stemMid2, stemEnd], 0.4);

  // Stem longitudinal vascular fibers from left (lit) to right (shaded)
  const numRibs = 15;
  for (let i = 0; i < numRibs; i++) {
    let u = map(i, 0, numRibs - 1, -1, 1); // -1 is left (sunlit), +1 is right (shadow)
    let wBot = 7.5;
    let wMid = 5.2;
    let wTop = 4.2;

    let pts = [
      [stemStart[0] + u * wBot, stemStart[1]],
      [stemMid1[0]  + u * wMid, stemMid1[1]],
      [stemMid2[0]  + u * wTop, stemMid2[1]],
      [stemEnd[0]   + u * (wTop * 1.25), stemEnd[1]]
    ];

    let col;
    if (u < -0.55) col = random(["#fff3b0", "#f7cf60", "#e3a130"]); // Lifted left rim highlight
    else if (u < 0.15) col = random(["#c77c20", "#a65b12", "#8c460b"]); // Translucent ochre core
    else col = random(["#5e2406", "#3d1403", "#260a01"]); // Shaded burnt umber right side

    brush.set(u < -0.55 ? "filament_fine" : "needle", col, random(0.65, 1.05));
    brush.spline(pts, 0.4);
  }

  // Cut base of stem sealed in the bottom resin (dark ellipse + tiny meniscus ring)
  brush.set("needle", "#240701", 0.9);
  brush.circle(stemStart[0], stemStart[1], 7.5, 0.15);
  brush.set("filament_fine", "#ffd970", 0.7);
  brush.arc(stemStart[0], stemStart[1], 8.2, 160, 340);

  // Reflexed involucral bracts (dried curled sepals hanging below the receptacle)
  for (let b = 0; b < 20; b++) {
    let t = map(b, 0, 19, -1, 1);
    let bx0 = dx + t * 15;
    let by0 = dy + 11 + abs(t) * 3;
    let spread = t * 34 + random(-6, 6);
    let len = random(28, 48) * (1 - abs(t) * 0.25);
    let curl = (t >= 0 ? 1 : -1) * random(8, 18);

    let bractPts = [
      [bx0, by0],
      [bx0 + spread * 0.45, by0 + len * 0.55],
      [bx0 + spread + curl, by0 + len]
    ];

    let bCol = t < -0.2
      ? random(["#e09c38", "#c4741a", "#783609"])
      : random(["#632707", "#421703", "#2b0c01", "#8f4410"]);

    brush.set("needle", bCol, random(0.75, 1.2));
    brush.spline(bractPts, 0.5);

    // Highlight edge on sun-facing bracts
    if (t < 0.1 && random() < 0.6) {
      brush.set("filament_fine", "#ffe58f", 0.55);
      brush.spline([
        [bx0 - 1, by0],
        [bx0 + spread * 0.42 - 1, by0 + len * 0.5]
      ], 0.4);
    }
  }

  // Receptacle (central honeycombed capitulum dome)
  for (let ring = 18; ring >= 2; ring -= 2.5) {
    let rCol = ring > 12 ? "#2e1002" : (ring > 6 ? "#5c2608" : "#964914");
    brush.set("grain_pencil", rCol, 1.1);
    brush.circle(dx, dy, ring, 0.2);
  }
  // Tiny alveolar pits and golden ridges on the receptacle
  for (let p = 0; p < 42; p++) {
    let a = random(0, 360);
    let rad = random(1, 16);
    let px = dx + cos(a) * rad;
    let py = dy + sin(a) * rad * 0.88;
    brush.set("needle", "#210801", 0.65);
    brush.line(px - 1.5, py, px + 1.5, py + 1);
    if (px < dx + 4 && py < dy + 4) {
      brush.set("filament_fine", "#f5be52", 0.55);
      brush.line(px - 1.5, py - 1, px + 1, py - 1);
    }
  }
}

function drawSingleDandelionSeed(dx, dy, s) {
  const { nx, ny, nz, radius, beakCurve, numHairs, hairLen } = s;

  // Orthonormal basis (U, V, N) around seed direction N = (nx, ny, nz)
  let upX = 0, upY = 1, upZ = 0;
  if (abs(ny) > 0.9) { upX = 1; upY = 0; }
  let ux = ny * upZ - nz * upY;
  let uy = nz * upX - nx * upZ;
  let uz = nx * upY - ny * upX;
  let uMag = sqrt(ux * ux + uy * uy + uz * uz);
  ux /= uMag; uy /= uMag; uz /= uMag;
  let vx = ny * uz - nz * uy;
  let vy = nz * ux - nx * uz;
  let vz = nx * uy - ny * ux;

  // 1. Achene (ribbed spindle seed body near receptacle, r = 16..34)
  let rAchStart = 16;
  let rAchEnd = 34;
  let ax0 = dx + nx * rAchStart;
  let ay0 = dy + ny * rAchStart;
  let ax1 = dx + nx * rAchEnd;
  let ay1 = dy + ny * rAchEnd;

  let achCol = nz < -0.2
    ? random(["#592306", "#73310a"])
    : random(["#2b0d02", "#451905", "#632809"]);
  brush.set("needle", achCol, 0.95);
  brush.line(ax0, ay0, ax1, ay1);

  // Achene width & tiny longitudinal ribs
  let perpX = -ny * 1.8;
  let perpY = nx * 1.8;
  brush.set("needle", "#381203", 0.7);
  brush.line(ax0 + perpX * 0.4, ay0 + perpY * 0.4, ax1 + perpX, ay1 + perpY);
  brush.line(ax0 - perpX * 0.4, ay0 - perpY * 0.4, ax1 - perpX, ay1 - perpY);

  // Golden highlight along sun-facing side of achene
  if (nz > -0.3 && nx + ny < 0.6) {
    brush.set("filament_fine", "#e8a843", 0.55);
    brush.line(ax0 - perpX * 0.5, ay0 - perpY * 0.5, ax1 - perpX * 0.8, ay1 - perpY * 0.8);
  }

  // 2. Slender Beak (rostrum stalk from rAchEnd out to pappus crown at radius)
  let bxMid = dx + nx * (radius * 0.55) + ux * beakCurve;
  let byMid = dy + ny * (radius * 0.55) + uy * beakCurve;
  let bxTip = dx + nx * radius;
  let byTip = dy + ny * radius;

  let beakCol;
  if (nz < -0.3) beakCol = random(["#8f4209", "#ab5610"]);
  else if (nz < 0.2) beakCol = random(["#6e3007", "#9e5012", "#c97a26"]);
  else beakCol = random(["#522105", "#85410e", "#deb059"]);

  brush.set("needle", beakCol, nz > 0.2 ? 0.65 : 0.55);
  brush.spline([[ax1, ay1], [bxMid, byMid], [bxTip, byTip]], 0.35);

  // Delicate lifted highlight along front/upper-left beaks
  if (nz > 0.0 && (nx < 0.35 || ny < 0.15)) {
    brush.set("filament_fine", "#fff2b3", 0.48);
    brush.spline([[ax1 - 0.6, ay1 - 0.6], [bxMid - 0.6, byMid - 0.6], [bxTip - 0.5, byTip - 0.5]], 0.35);
  }

  // 3. Parachute Filaments (Hyperreal White Pencil Threads)
  // Lighting factor based on 3D position (upper-left-front is brightest citrine/white,
  // lower-right-back is deepest warm honey/champagne)
  let sunDot = (-nx * 0.55 - ny * 0.65 + nz * 0.52); // [-1..+1]

  for (let h = 0; h < numHairs; h++) {
    let phi = h * (360 / numHairs) + random(-5, 5);
    // Two-tiered pappus umbrella angle (inner & outer ring of hairs)
    let alpha = (h % 2 === 0) ? random(54, 76) : random(30, 52);

    let cosA = cos(alpha);
    let sinA = sin(alpha);
    let cosP = cos(phi);
    let sinP = sin(phi);

    // 3D unit vector of this individual filament
    let fx = nx * cosA + (ux * cosP + vx * sinP) * sinA;
    let fy = ny * cosA + (uy * cosP + vy * sinP) * sinA;
    let fz = nz * cosA + (uz * cosP + vz * sinP) * sinA;

    let len = hairLen * random(0.84, 1.14);

    // Graceful outward & slightly buoyant curve in the viscous resin
    let midX = bxTip + fx * (len * 0.52) + nx * 3.2;
    let midY = byTip + fy * (len * 0.52) + ny * 3.2 - 1.5;
    let endX = bxTip + fx * len + nx * 4.5;
    let endY = byTip + fy * len + ny * 4.5 - 3.5;

    // Color & brush selection by depth (nz, fz) and light (sunDot)
    let hCol;
    let hBrush = "filament";
    let hWeight = 0.72;

    if (nz < -0.45) {
      // Deepest back hemisphere: submerged in warm honey/cognac resin
      hCol = random(["#c46e16", "#de8a24", "#edb045", "#f7cc6b"]);
      hWeight = 0.62;
    } else if (nz < -0.1) {
      // Mid-back hemisphere: glowing amber-cream & champagne threads
      hCol = sunDot > 0
        ? random(["#ffe694", "#fff2bd", "#f5c456"])
        : random(["#d98821", "#f0b243", "#fad678"]);
      hWeight = 0.68;
    } else if (nz < 0.35) {
      // Rim & mid-front halo: dense interlocking ivory & white pencil threads
      hCol = sunDot > -0.15
        ? random(["#ffffff", "#fffef5", "#fff9d6", "#ffefad"])
        : random(["#fff4c2", "#ffe28a", "#f5be52", "#fffdf0"]);
      hBrush = random() < 0.55 ? "filament_fine" : "filament";
      hWeight = random(0.65, 0.88);
    } else {
      // Closest front hemisphere: razor-sharp hyperreal white pencil starbursts
      hCol = random(["#ffffff", "#ffffff", "#fffef7", "#fff8d6"]);
      hBrush = "filament_fine";
      hWeight = random(0.68, 0.92);
    }

    brush.set(hBrush, hCol, hWeight);
    brush.spline([[bxTip, byTip], [midX, midY], [endX, endY]], 0.38);

    // Occasional crisp cpencil texture overlay on front/rim filaments
    if (nz > -0.05 && h % 5 === 0) {
      brush.set("cpencil", "#ffffff", 0.38);
      brush.line(bxTip, byTip, endX, endY);
    }
  }

  // Tiny callus ring at the center of the pappus crown where filaments join the beak
  let callusCol = nz > 0.15 ? "#592507" : "#8c4310";
  brush.set("needle", callusCol, 0.75);
  brush.circle(bxTip, byTip, 1.4, 0.1);
  if (nz > 0.0) {
    brush.set("filament_fine", "#fff8cc", 0.6);
    brush.line(bxTip - 1.2, byTip - 0.8, bxTip + 0.6, byTip - 0.8);
  }
}

// ===========================================================================
// 6. DRIFTING DETACHED SEEDS (DELICATE PEN & LIFTED HIGHLIGHTS)
// ===========================================================================
function drawDetachedSeeds(cx, cy, r) {
  const floatingSeeds = [
    // Drifting up & right toward the upper honey/citrine zone
    { x: 742, y: 392, angle: -42, scale: 1.02, depth: "front" },
    // High near the pale citrine crown
    { x: 648, y: 268, angle: -24, scale: 0.92, depth: "crown" },
    // Far right mid-depth in rich cognac
    { x: 812, y: 528, angle: -65, scale: 0.96, depth: "mid" },
    // Upper-left bright zone
    { x: 372, y: 376, angle: -115, scale: 0.9, depth: "front" },
    // Lower-left sinking gently toward the burnt sienna base
    { x: 408, y: 642, angle: -138, scale: 0.95, depth: "deep" }
  ];

  for (let fs of floatingSeeds) {
    const { x, y, angle, scale, depth } = fs;
    const cosA = cos(angle);
    const sinA = sin(angle);
    const perpX = -sinA;
    const perpY = cosA;

    // 1. Achene (spindle seed body at (x, y) of length 20 * scale)
    let achLen = 20 * scale;
    let ax1 = x + cosA * achLen;
    let ay1 = y + sinA * achLen;

    // Subtle amber wake/halo around the detached seed
    brush.set("glaze", depth === "deep" ? "#661a02" : "#e89a20", 0.65);
    brush.line(x, y, x + cosA * 85 * scale, y + sinA * 85 * scale);

    // Delicate dark pen contour & spiky apical barbules on achene
    let penCol = depth === "deep" ? "#260801" : "#381203";
    brush.set("needle", penCol, 0.88);
    brush.spline([
      [x, y],
      [x + cosA * achLen * 0.55 + perpX * 2.4 * scale, y + sinA * achLen * 0.55 + perpY * 2.4 * scale],
      [ax1, ay1]
    ], 0.4);
    brush.spline([
      [x, y],
      [x + cosA * achLen * 0.55 - perpX * 2.4 * scale, y + sinA * achLen * 0.55 - perpY * 2.4 * scale],
      [ax1, ay1]
    ], 0.4);
    brush.line(x, y, ax1, ay1);

    // Tiny barbules near tip of achene
    for (let b = 0.6; b <= 0.92; b += 0.15) {
      let bx = x + cosA * achLen * b;
      let by = y + sinA * achLen * b;
      brush.set("needle", penCol, 0.6);
      brush.line(bx + perpX * 2 * scale, by + perpY * 2 * scale, bx + (perpX * 3.8 - cosA * 2) * scale, by + (perpY * 3.8 - sinA * 2) * scale);
      brush.line(bx - perpX * 2 * scale, by - perpY * 2 * scale, bx - (perpX * 3.8 + cosA * 2) * scale, by - (perpY * 3.8 + sinA * 2) * scale);
    }

    // Lifted highlight along sunlit edge of achene
    brush.set("filament_fine", "#fff6bf", 0.72);
    brush.spline([
      [x + cosA * 2, y + sinA * 2],
      [x + cosA * achLen * 0.55 - perpX * 2.1 * scale, y + sinA * achLen * 0.55 - perpY * 2.1 * scale],
      [ax1, ay1]
    ], 0.4);

    // 2. Slender Beak (stalk from ax1, ay1 to pappus tip)
    let beakLen = 58 * scale;
    let bxMid = ax1 + cosA * beakLen * 0.5 + perpX * 3.5 * scale;
    let byMid = ay1 + sinA * beakLen * 0.5 + perpY * 3.5 * scale;
    let bxTip = ax1 + cosA * beakLen;
    let byTip = ay1 + sinA * beakLen;

    brush.set("needle", "#5c2406", 0.7);
    brush.spline([[ax1, ay1], [bxMid, byMid], [bxTip, byTip]], 0.4);

    // Lifted highlight along beak
    brush.set("filament_fine", "#fffbe0", 0.6);
    brush.spline([[ax1 - perpX * 0.8, ay1 - perpY * 0.8], [bxMid - perpX * 0.8, byMid - perpY * 0.8], [bxTip - perpX * 0.6, byTip - perpY * 0.6]], 0.4);

    // 3. Parachute Filaments (fanning cone of white pencil threads)
    let numF = 34;
    for (let f = 0; f < numF; f++) {
      let spread = map(f, 0, numF - 1, -68, 68) + random(-3, 3);
      let fAngle = angle + spread;
      let fLen = random(38, 54) * scale * (1 - abs(spread) * 0.0025);

      // Viscous drag curve on outer filaments
      let curveDrag = -spread * 0.16;
      let fxMid = bxTip + cos(fAngle + curveDrag * 0.5) * fLen * 0.52;
      let fyMid = byTip + sin(fAngle + curveDrag * 0.5) * fLen * 0.52;
      let fxEnd = bxTip + cos(fAngle + curveDrag) * fLen;
      let fyEnd = byTip + sin(fAngle + curveDrag) * fLen;

      // Delicate amber shadow thread behind a few filaments for contrast in pale zones
      if (depth === "crown" && f % 3 === 0) {
        brush.set("needle", "#b86b14", 0.45);
        brush.spline([[bxTip + 0.8, byTip + 0.8], [fxMid + 0.8, fyMid + 0.8], [fxEnd + 0.8, fyEnd + 0.8]], 0.35);
      }

      let fCol = depth === "deep"
        ? random(["#ffe699", "#fff4c7", "#ffffff"])
        : random(["#ffffff", "#ffffff", "#fffef5", "#fff6c4"]);

      brush.set("filament_fine", fCol, random(0.68, 0.92));
      brush.spline([[bxTip, byTip], [fxMid, fyMid], [fxEnd, fyEnd]], 0.38);
    }

    // Tiny dark pen callus dot + white pinpoint highlight at pappus junction
    brush.set("needle", "#361102", 0.8);
    brush.circle(bxTip, byTip, 1.5, 0.1);
    brush.set("filament_fine", "#ffffff", 0.7);
    brush.line(bxTip - 1, byTip - 1, bxTip + 0.5, byTip - 1);
  }
}

// ===========================================================================
// 7. HAIRLINE STRESS FRACTURES (INTERNAL CRAZING & LIFTED HIGHLIGHTS)
// ===========================================================================
function drawStressFractures(cx, cy, r, yBase, rxBase, ryBase) {
  // Helper to draw a branching internal stress fracture with pen + lifted highlight
  function drawFractureBranch(startPt, dirAngle, totalLen, generations, maxSteps = 14) {
    let pts = [startPt];
    let curX = startPt[0];
    let curY = startPt[1];
    let curA = dirAngle;
    let stepLen = totalLen / maxSteps;

    for (let i = 0; i < maxSteps; i++) {
      curA += random(-14, 14);
      curX += cos(curA) * stepLen;
      curY += sin(curA) * stepLen;
      pts.push([curX, curY]);

      // Recursive sub-branching
      if (generations > 0 && (i === floor(maxSteps * 0.4) || i === floor(maxSteps * 0.72))) {
        let branchSign = random() < 0.5 ? 1 : -1;
        drawFractureBranch(
          [curX, curY],
          curA + branchSign * random(22, 38),
          totalLen * random(0.45, 0.65),
          generations - 1,
          8
        );
      }
    }

    // 1. Subtle golden-citrine internal reflection veil along fracture cleavage plane
    for (let i = 0; i < pts.length - 1; i += 2) {
      let p1 = pts[i];
      let p2 = pts[min(pts.length - 1, i + 2)];
      let nx = -(p2[1] - p1[1]);
      let ny = (p2[0] - p1[0]);
      let mag = sqrt(nx * nx + ny * ny) || 1;
      nx = (nx / mag) * random(5, 14);
      ny = (ny / mag) * random(5, 14);

      brush.set("filament", "#ffdf78", 0.45);
      brush.line(p1[0], p1[1], p1[0] + nx, p1[1] + ny);
    }

    // 2. Fine plumose hackle marks (microscopic stress fringes perpendicular to crack)
    for (let i = 1; i < pts.length - 1; i++) {
      if (random() < 0.65) {
        let p = pts[i];
        let pNext = pts[i + 1];
        let ang = atan2(pNext[1] - p[1], pNext[0] - p[0]) + 75;
        let hLen = random(3, 8.5) * (1 - i / pts.length);
        brush.set("needle", "#521a03", 0.45);
        brush.line(p[0], p[1], p[0] + cos(ang) * hLen, p[1] + sin(ang) * hLen);
        brush.set("filament_fine", "#fff5b8", 0.42);
        brush.line(p[0] - 0.8, p[1] - 0.8, p[0] + cos(ang) * hLen - 0.8, p[1] + sin(ang) * hLen - 0.8);
      }
    }

    // 3. Delicate dark sienna pen hairline crack
    brush.set("needle", "#2e0b01", generations > 0 ? 0.78 : 0.55);
    brush.spline(pts, 0.25);

    // 4. Razor-sharp lifted white/citrine highlight immediately adjacent (1.3px toward light)
    let liftedPts = pts.map(p => [p[0] - 1.3, p[1] - 1.3]);
    brush.set("filament_fine", generations > 0 ? "#fffef2" : "#ffefa6", generations > 0 ? 0.72 : 0.5);
    brush.spline(liftedPts, 0.25);
  }

  // Fracture 1: Major stress fracture rising from lower-right base bevel into cognac resin
  drawFractureBranch([762, 724], -132, 118, 2, 16);
  drawFractureBranch([762, 724], -95, 74, 1, 10);

  // Fracture 2: Left flank conchoidal cleavage stress crack
  drawFractureBranch([258, 612], -28, 92, 2, 14);

  // Fracture 3: Delicate thermal curing hairline cracks radiating from the cut stem base
  drawFractureBranch([516, 764], -35, 58, 1, 10);
  drawFractureBranch([516, 764], -152, 48, 1, 9);
}

// ===========================================================================
// 8. TRAPPED AIR BUBBLES (DELICATE PEN & LIFTED HIGHLIGHTS)
// ===========================================================================
function drawTrappedBubbles(cx, cy, r, dx, dy, dRad, yBase) {
  let bubbles = [
    // Hero bubbles rising in a helical trail from the dandelion crown toward top of dome
    { x: 582, y: 332, rad: 12.5 },
    { x: 598, y: 294, rad: 8.5 },
    { x: 576, y: 262, rad: 6.2 },
    { x: 592, y: 232, rad: 4.5 },
    { x: 585, y: 208, rad: 2.8 },

    // Secondary bubble stream rising from right side of seed head
    { x: 718, y: 446, rad: 9.8 },
    { x: 734, y: 412, rad: 5.6 },
    { x: 726, y: 365, rad: 4.2 },

    // Bubbles trapped near the stem & lower cognac/sienna resin
    { x: 512, y: 698, rad: 7.4 },
    { x: 534, y: 648, rad: 4.8 },
    { x: 642, y: 712, rad: 8.2 },
    { x: 658, y: 685, rad: 4.1 },
    { x: 448, y: 706, rad: 6.0 },

    // Bubbles clinging among the dandelion filaments
    { x: 432, y: 468, rad: 6.5 },
    { x: 486, y: 382, rad: 5.2 },
    { x: 654, y: 396, rad: 5.8 },
    { x: 678, y: 558, rad: 6.8 },
    { x: 456, y: 584, rad: 4.6 },
    { x: 555, y: 422, rad: 3.9 }
  ];

  // Add 65 tiny micro-bubbles suspended throughout the dome & around the seed head
  for (let i = 0; i < 65; i++) {
    let a = random(0, 360);
    let distFromCenter = random(25, r - 32);
    let bx = cx + cos(a) * distFromCenter;
