  for (let b of bubbles) {
    drawSingleBubble(b.x, b.y, b.rad, cy);
  }
}

function drawSingleBubble(x, y, rad, cy) {
  let isDeep = y > cy + 90;

  if (rad >= 3.5) {
    // 1. Dark amber/sienna internal refractive shadow rim
    brush.set("needle", isDeep ? "#260701" : "#4f1a03", 0.78);
    brush.circle(x, y, rad, 0.08);

    // Thicker dark crescent on upper-left & lower-right rim (total internal reflection)
    brush.set("needle", "#2b0a01", 0.9);
    brush.arc(x, y, rad, 185, 275);
    brush.arc(x, y, rad, 10, 85);

    // 2. Warm golden-citrine internal bounce crescent at bottom-right
    brush.set("filament", isDeep ? "#f5a322" : "#ffe470", 0.85);
    brush.arc(x, y, rad * 0.78, 15, 115);

    // 3. Crisp lifted white highlight arc on upper-left inner dome
    brush.set("filament_fine", "#ffffff", 0.95);
    brush.arc(x, y, rad * 0.74, 195, 265);

    // 4. Razor-sharp pure white specular pinpoint
    let hx = x - rad * 0.42;
    let hy = y - rad * 0.42;
    brush.set("filament_fine", "#ffffff", 1.15);
    brush.line(hx - 1.2, hy + 0.8, hx + 1.2, hy - 0.8);
    brush.line(hx - 0.6, hy - 0.6, hx + 0.8, hy + 0.8);

    // Secondary tiny opposite pole reflection on larger bubbles
    if (rad > 6.5) {
      let bx2 = x + rad * 0.48;
      let by2 = y + rad * 0.48;
      brush.set("filament_fine", "#fff6bd", 0.75);
      brush.line(bx2 - 0.8, by2 + 0.5, bx2 + 0.8, by2 - 0.5);
    }
  } else {
    // Micro-bubble: crisp dark pen dot + bright lifted white pinpoint
    brush.set("needle", isDeep ? "#330b01" : "#5e2205", 0.65);
    brush.circle(x, y, rad, 0.05);
    brush.set("filament_fine", "#ffffff", 0.82);
    brush.line(x - rad * 0.5, y - rad * 0.4, x + 0.4, y - rad * 0.5);
  }
}

// ===========================================================================
// 9. SURFACE SPECULAR HIGHLIGHT, OPTICAL RIM & FINAL LUMINOUS GLAZES
// ===========================================================================
function drawDomeSpecularAndRim(cx, cy, r, yBase, rxBase, ryBase, yFoot) {
  // 9A. Internal Rim Glow (subsurface golden refraction along the right & upper dome edge)
  for (let pass = 0; pass < 18; pass++) {
    let inset = map(pass, 0, 17, 3, 22);
    let a1 = map(pass, 0, 17, -95, -70);
    let a2 = map(pass, 0, 17, 36, 25);
    let pts = [];
    for (let a = a1; a <= a2; a += 6) {
      pts.push([cx + cos(a) * (r - inset), cy + sin(a) * (r - inset)]);
    }
    let col = pass < 6
      ? random(["#471402", "#6e2204"]) // Outer dark refractive boundary ring
      : random(["#f5a422", "#ffd257", "#fff099"]); // Inner golden rim glow
    brush.set(pass < 6 ? "needle" : "cpencil", col, pass < 6 ? 0.85 : 0.95);
    brush.spline(pts, 0.4);
  }

  // Left and top outer boundary precision ring
  for (let pass = 0; pass < 10; pass++) {
    let inset = map(pass, 0, 9, 1.5, 9);
    let pts = [];
    for (let a = 142; a <= 275; a += 6) {
      pts.push([cx + cos(a) * (r - inset), cy + sin(a) * (r - inset)]);
    }
    let col = pass < 4 ? "#421503" : random(["#e89c20", "#fae075", "#fff8c2"]);
    brush.set(pass < 4 ? "needle" : "cpencil", col, 0.78);
    brush.spline(pts, 0.4);
  }

  // 9B. Curved Studio Window Specular Reflection on Upper-Left Crown of Dome
  // Follows spherical geometry from angle -158 to -102 degrees at r * 0.84 .. r * 0.93
  // Divided into two panes for hyperreal optical authenticity
  const panes = [
    { aStart: -158, aEnd: -129 },
    { aStart: -125, aEnd: -101 }
  ];

  for (let pane of panes) {
    // Soft luminous white/citrine glaze underneath
    for (let rFrac = 0.83; rFrac <= 0.93; rFrac += 0.02) {
      let pts = [];
      for (let a = pane.aStart; a <= pane.aEnd; a += 4) {
        pts.push([cx + cos(a) * (r * rFrac), cy + sin(a) * (r * rFrac)]);
      }
      brush.set("glaze", "#fffdf0", 0.85);
      brush.spline(pts, 0.4);
    }

    // Crisp hyperreal white pencil & filament highlight threads curving along the reflection
    let numStrokes = 26;
    for (let s = 0; s < numStrokes; s++) {
      let t = s / (numStrokes - 1);
      let curRad = r * lerp(0.835, 0.935, t);
      // Taper the arc slightly at inner and outer edges
      let taper = sin(t * 180) * 2.5;
      let pts = [];
      for (let a = pane.aStart - taper; a <= pane.aEnd + taper; a += 3.5) {
        pts.push([cx + cos(a) * curRad, cy + sin(a) * curRad]);
      }

      // Brightest along the upper-outer edge, softly feathered toward the interior
      let col = t > 0.35 ? "#ffffff" : random(["#fffef2", "#fff7c2"]);
      let w = map(sin(t * 180), 0, 1, 0.55, 1.05);
      brush.set(t > 0.4 ? "filament_fine" : "cpencil", col, w);
      brush.spline(pts, 0.4);
    }
  }

  // Secondary smaller curved specular streak near the top crown (-94 to -74 degrees)
  for (let s = 0; s < 10; s++) {
    let curRad = r * lerp(0.89, 0.94, s / 9);
    let pts = [];
    for (let a = -94; a <= -74; a += 4) {
      pts.push([cx + cos(a) * curRad, cy + sin(a) * curRad]);
    }
    brush.set("filament_fine", "#fffdf2", 0.72);
    brush.spline(pts, 0.4);
  }

  // 9C. Polished Base Bevel Specular Highlights (catching golden caustic bounce light)
  for (let s = 0; s < 14; s++) {
    let t = s / 13;
    let yOff = lerp(yBase + 1, yFoot - 2, t);
    let pts = [];
    for (let a = 18; a <= 78; a += 5) {
      pts.push([cx + cos(a) * (rxBase - 2), yOff + sin(a) * (ryBase - 1)]);
    }
    let col = (s > 4 && s < 10) ? "#fff9d2" : "#f7b529";
    brush.set("filament_fine", col, 0.78);
    brush.spline(pts, 0.4);
  }

  // Subtle left-front base rim highlight
  for (let s = 0; s < 8; s++) {
    let yOff = lerp(yBase + 2, yFoot - 3, s / 7);
    let pts = [];
    for (let a = 112; a <= 156; a += 5) {
      pts.push([cx + cos(a) * (rxBase - 2), yOff + sin(a) * (ryBase - 1)]);
    }
    brush.set("filament", "#e8921c", 0.65);
    brush.spline(pts, 0.4);
  }
}

// Hyperrealist Dark-Field Monotype: Crumpled Linen Napkin on Bare Oak Table
// Built subtractively from a dense lamp-black & brown-black charcoal/ink slab,
// with burnt umber ink blooms, rag-smears, fingertip lifts, uneven press offset edges,
// and hyperreal warp-and-weft linen weave on the sunlit crests.

const PAL = {
  paper: "#F3EDE1",
  paperWarm: "#EAE1D2",
  paperEdge: "#D6CBB8",
  boneBright: "#FFFDF8",
  boneHigh: "#FAF6EE",
  boneLight: "#EFE8DA",
  boneMid: "#DBD1C0",
  ragLight: "#C2B6A4",
  ragMid: "#9E907F",
  ragGhost: "#7A6C5D",
  ragDark: "#584B3E",
  smokyUmber: "#3D3127",
  oakLight: "#877460",
  oakMid: "#594838",
  oakDark: "#362A20",
  umberBloomBright: "#663A1B",
  umberBloom: "#4E2B14",
  umberDeep: "#361D0D",
  brownBlack: "#211914",
  lampBlack: "#130E0B",
  voidBlack: "#090705"
};

// Plate bounds on the 1200x1200 sheet
const PLATE = { x1: 58, y1: 54, x2: 1142, y2: 1146 };

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);

  randomSeed(7391);
  noiseSeed(7391);

  // Custom monotype & hyperreal texture brushes
  brush.add("charcoal_slab", {
    type: "default",
    weight: 16,
    scatter: 0.45,
    sharpness: 0.22,
    grain: 0.78,
    opacity: 95,
    spacing: 0.22,
    pressure: [0.7, 1.25, 0.65],
    rotate: "natural",
    noise: 0.65
  });

  brush.add("rag_broad", {
    type: "default",
    weight: 22,
    scatter: 0.35,
    sharpness: 0.14,
    grain: 0.62,
    opacity: 48,
    spacing: 0.18,
    pressure: [0.35, 1.3, 0.3],
    rotate: "natural",
    noise: 0.45
  });

  brush.add("tarlatan_streak", {
    type: "custom",
    weight: 8,
    scatter: 0.25,
    opacity: 32,
    spacing: 0.25,
    pressure: [0.4, 1.15, 0.35],
    tip: (_m) => {
      _m.rect(-3.2, -0.4, 6.4, 0.8);
      _m.rect(-2.4, 1.0, 4.8, 0.6);
      _m.rect(-2.8, -1.6, 5.6, 0.6);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.5
  });

  brush.add("fingertip_lift", {
    type: "default",
    weight: 14,
    scatter: 0.18,
    sharpness: 0.12,
    grain: 0.52,
    opacity: 65,
    spacing: 0.15,
    pressure: [0.5, 1.35, 0.4],
    rotate: "random",
    noise: 0.3
  });

  brush.add("press_edge", {
    type: "default",
    weight: 0.75,
    scatter: 0.12,
    sharpness: 0.72,
    grain: 0.68,
    opacity: 145,
    spacing: 0.14,
    pressure: [0.4, 1.1, 0.35],
    rotate: "natural",
    noise: 0.85
  });

  brush.add("linen_thread", {
    type: "default",
    weight: 0.32,
    scatter: 0.03,
    sharpness: 0.88,
    grain: 0.28,
    opacity: 175,
    spacing: 0.12,
    pressure: [0.65, 1.15, 0.65],
    rotate: "natural",
    noise: 0.25
  });

  // Custom vector fields for rag wiping & cloth contours
  brush.addField("rag_sweep", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let ang = -24 + 18 * sin(nx * 180 + ny * 90) + 12 * (noise(nx * 2.5, ny * 2.5) - 0.5);
        field[col][row] = ang;
      }
    }
    return field;
  });

  brush.addField("oak_grain", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        // Perspective fan + cathedral loop modulation
        let baseAng = 2.2 + (nx - 0.5) * 3.5;
        let arch = sin((nx - 0.42) * 320) * 4.2 * sin(ny * 260);
        field[col][row] = baseAng + arch + (noise(nx * 4, ny * 8) - 0.5) * 3.0;
      }
    }
    return field;
  });
}

function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawPoly(pts, curvature = 0.22, close = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
}

function offsetPts(pts, dx, dy, jitter = 0) {
  return pts.map((p, idx) => [
    p[0] + dx + (jitter ? (noise(idx * 1.7, p[0] * 0.02) - 0.5) * jitter : 0),
    p[1] + dy + (jitter ? (noise(idx * 2.3, p[1] * 0.02) - 0.5) * jitter : 0)
  ]);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);

  // 1. Paper deckle & recessed printmaking plate margin
  drawPaperAndPlateMargin();

  // Clip all monotype plate work inside the zinc plate bounds (with slight ink squash room)
  brush.clip([PLATE.x1 - 4, PLATE.y1 - 4, PLATE.x2 + 4, PLATE.y2 + 4]);

  // 2. Dense slab of lamp-black & brown-black charcoal mass + heavy upper plate tone
  drawMonotypeSlabAndPlateTone();

  // 3. Bare oak table pulled out of the dark + pooled burnt umber shadow
  drawBareOakTableAndShadow();

  // 4. First reductive rag-wipes: ghosted structural halo of the crumpled linen napkin
  drawNapkinReductiveUnderwipe();

  // 5. Sculptural facets of the napkin: rag-smears, mid-tone planes, and deep fold troughs
  drawNapkinSculpturalFacets();

  // 6. Pooled burnt umber & lamp-black ink in deep fold canyons and undercuts
  drawNapkinCreviceInkPools();

  // 7. Doubled, offset edges like an uneven press + stitched hem anatomy
  drawUnevenPressEdgesAndHem();

  // 8. Fingertip lifts & hyperreal warp-and-weft linen weave on the sunlit crests
  drawFingertipLiftsAndHyperrealWeave();

  // 9. Monotype plate surface incidents: lint resists, roller ghosts & plate rim ink squash
  drawMonotypeSurfaceIncidents();

  brush.noClip();
  drawPlateEmbossedBevel();

  noLoop();
}

// ============================================================================
// 1. PAPER & PLATE MARGIN
// ============================================================================
function drawPaperAndPlateMargin() {
  resetBrush();
  // Subtle warm rag paper mottling around the border
  brush.fill(PAL.paperWarm, 45);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.2);
  brush.rect(0, 0, 1200, 1200, "corner");
  resetBrush();

  // Fine paper fibers in the outer margin
  brush.set("2H", PAL.paperEdge, 0.35);
  for (let i = 0; i < 220; i++) {
    let side = i % 4;
    let x = side < 2 ? random(10, 1190) : (side === 2 ? random(8, 56) : random(1144, 1192));
    let y = side < 2 ? (side === 0 ? random(8, 52) : random(1148, 1192)) : random(10, 1190);
    let ang = random(360);
    let len = random(6, 22);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
  resetBrush();
}

// ============================================================================
// 2. DENSE SLAB OF LAMP-BLACK CHARCOAL MASS & HEAVY UPPER PLATE TONE
// ============================================================================
function drawMonotypeSlabAndPlateTone() {
  resetBrush();
  let pw = PLATE.x2 - PLATE.x1;
  let ph = PLATE.y2 - PLATE.y1;

  // Base opaque wash of deep brown-black & lamp-black across the entire plate
  brush.wash(PAL.lampBlack, 250);
  brush.rect(PLATE.x1, PLATE.y1, pw, ph, "corner");
  resetBrush();

  // Second velvety charcoal-black layer in the upper heavy plate margin and deep corners
  brush.wash(PAL.voidBlack, 215);
  brush.rect(PLATE.x1, PLATE.y1, pw, 620, "corner");
  resetBrush();

  // Burnt umber ink blooms where oil & pigment pooled in the dark slab
  const umberPools = [
    // Upper-left atmospheric plate bloom
    [[60, 60], [520, 60], [480, 390], [280, 470], [60, 410]],
    // Right-hand deep plate bloom above table
    [[680, 190], [1140, 160], [1140, 690], [820, 680], [640, 470]],
    // Deep pool surrounding the napkin's base & right shadow
    [[140, 740], [560, 690], [1060, 790], [1120, 1100], [120, 1120]],
    // Central fold reservoir
    [[310, 520], [720, 550], [760, 880], [250, 890]]
  ];

  brush.fill(PAL.umberDeep, 115);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.75, 0.35);
  for (let poly of umberPools) {
    drawPoly(poly, 0.35, true);
  }
  resetBrush();

  // Warmer burnt umber halo blooms where ink separated under roller pressure
  const warmUmberHalos = [
    [[220, 490], [490, 470], [560, 640], [210, 670]],
    [[540, 780], [980, 810], [1030, 1040], [490, 1050]],
    [[110, 880], [460, 920], [490, 1110], [105, 1095]]
  ];
  brush.fill(PAL.umberBloom, 88);
  brush.fillBleed(0.5, "out");
  brush.fillTexture(0.8, 0.4);
  for (let poly of warmUmberHalos) {
    drawPoly(poly, 0.4, true);
  }
  resetBrush();

  // Dense dry-media charcoal mass passes across the upper plate margin
  brush.mass("charcoal", PAL.voidBlack, { precision: 0.35, strength: 0.85, gradient: 0.25, outline: false });
  drawPoly([[58, 54], [1142, 54], [1142, 580], [840, 640], [58, 560]], 0.1, true);
  resetBrush();

  // Brayer / roller vertical & slight diagonal monotype slab streaks in the upper plate tone
  for (let i = 0; i < 190; i++) {
    let x = random(PLATE.x1 + 8, PLATE.x2 - 8);
    let y1 = random(PLATE.y1 + 5, 580);
    let len = random(90, 380);
    let y2 = min(720, y1 + len);
    let dx = random(-18, 18);
    let col = i % 3 === 0 ? PAL.brownBlack : (i % 3 === 1 ? PAL.voidBlack : PAL.umberDeep);
    brush.set("charcoal_slab", col, random(0.65, 1.45));
    brush.line(x, y1, x + dx, y2);
  }

  // Faint diagonal ghost wipes in the upper plate margin (where the printer's rag tested the tone)
  // This gives the "heavy margin of plate tone above it" authentic printmaking depth
  brush.field("rag_sweep");
  for (let i = 0; i < 65; i++) {
    let gx = random(130, 860);
    let gy = random(110, 540);
    // Concentrated slightly above-left of the napkin like rising warmth
    let dToCrown = dist(gx, gy, 420, 440);
    let col = dToCrown < 240 ? PAL.smokyUmber : PAL.brownBlack;
    brush.set("tarlatan_streak", col, random(0.7, 1.5));
    brush.flowLine(gx, gy, random(70, 220), random(-25, 15));
  }
  resetBrush();

  // Deep re-glaze at top corners so the plate margin feels heavy and enveloping
  for (let i = 0; i < 75; i++) {
    let x = random(PLATE.x1, PLATE.x2);
    let y = random(PLATE.y1, 280);
    brush.set("charcoal_slab", PAL.voidBlack, random(0.9, 1.6));
    brush.line(x, y, x + random(-60, 60), y + random(30, 120));
  }
  resetBrush();
}

// ============================================================================
// 3. BARE OAK TABLE & POOLED BURNT UMBER CAST SHADOW
// ============================================================================
function drawBareOakTableAndShadow() {
  resetBrush();

  // The bare oak table emerges from the dark slab below y ~ 645 (left) to 668 (right)
  // Pulled out by horizontal rag wipes that lift the ink slightly on the tabletop plane
  const tableGlowZones = [
    // Left table area catching raking light near the napkin's front-left apron
    { pts: [[58, 665], [340, 650], [320, 1080], [58, 1110]], col: PAL.oakMid, op: 62 },
    // Immediate foreground table shelf in front of the napkin
    { pts: [[60, 940], [580, 995], [960, 1015], [1140, 960], [1140, 1144], [60, 1144]], col: PAL.oakDark, op: 75 },
    // Right-hand distant table surface emerging dimly from plate tone
    { pts: [[640, 665], [1140, 672], [1140, 980], [680, 940]], col: PAL.oakDark, op: 54 }
  ];

  for (let z of tableGlowZones) {
    brush.fill(z.col, z.op);
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.65, 0.3);
    drawPoly(z.pts, 0.25, true);
  }
  resetBrush();

  // Horizontal rag-wipe passes across the oak table plane
  brush.field("oak_grain");
  for (let i = 0; i < 240; i++) {
    let y = random(652, 1140);
    let x = random(62, 1100);
    // Perspective foreshortening: strokes are tighter near y=655, broader near y=1140
    let t = map(y, 650, 1140, 0, 1);
    // Avoid lifting inside the deep cast shadow right of/under the napkin
    let inShadow = (x > 220 && x < 980 && y > 840 && y < 1065 && dist(x, y * 1.4, 580, 945 * 1.4) < 390);
    if (inShadow && random() < 0.82) continue;

    let dLight = dist(x, y, 240, 860);
    let col = dLight < 230 ? PAL.oakLight : (dLight < 440 ? PAL.oakMid : PAL.oakDark);
    if (random() < 0.35) col = PAL.smokyUmber;

    brush.set(i % 2 === 0 ? "tarlatan_streak" : "rag_broad", col, map(t, 0, 1, 0.35, 0.95));
    brush.flowLine(x, y, random(60, 210) * (0.6 + 0.6 * t), 2);
  }
  resetBrush();

  // Bare Oak Cathedral Grain Arches & Ring Pores (drawn by lifting & incising into the dark ink)
  const cathedrals = [
    { cx: 210, cy: 1035, rx: 240, ry: 42, rings: 11, dir: 1 },
    { cx: 830, cy: 1055, rx: 290, ry: 48, rings: 12, dir: -1 },
    { cx: 920, cy: 765, rx: 220, ry: 26, rings: 9, dir: 1 },
    { cx: 185, cy: 735, rx: 170, ry: 22, rings: 8, dir: -1 }
  ];

  for (let cat of cathedrals) {
    for (let r = 1; r <= cat.rings; r++) {
      let scaleF = r / cat.rings;
      let ptsLight = [];
      let ptsDark = [];
      for (let a = -155; a <= 155; a += 10) {
        let rad = a;
        let px = cat.cx + cos(rad) * cat.rx * scaleF * cat.dir + sin(rad * 2) * 14 * scaleF;
        let py = cat.cy + sin(rad) * cat.ry * Math.pow(scaleF, 0.88);
        px += (noise(px * 0.015, py * 0.04, r) - 0.5) * 16;
        py += (noise(px * 0.02, py * 0.05, r + 10) - 0.5) * 5;
        if (px > PLATE.x1 + 6 && px < PLATE.x2 - 6 && py > 655 && py < PLATE.y2 - 6) {
          ptsLight.push([px, py]);
          ptsDark.push([px + 1.5, py + 1.8]);
        }
      }
      if (ptsLight.length >= 4) {
        let dLight = dist(cat.cx, cat.cy, 250, 880);
        let lCol = dLight < 320 ? PAL.ragGhost : PAL.oakMid;
        brush.set("2B", lCol, random(0.45, 0.85));
        brush.spline(ptsLight, 0.35);

        brush.set("charcoal", PAL.lampBlack, random(0.4, 0.75));
        brush.spline(ptsDark, 0.35);
      }
    }
  }

  // Characteristic Oak Medullary Rays (short, crisp silver-bone & umber flecks angled slightly across the grain)
  for (let i = 0; i < 420; i++) {
    let rx = random(68, 1130);
    let ry = random(665, 1138);
    // Skip inside the napkin body
    if (rx > 145 && rx < 860 && ry > 555 && ry < 1015) continue;
    let t = map(ry, 665, 1138, 0.4, 1.15);
    let dToLight = dist(rx, ry, 230, 885);
    let rayCol = dToLight < 210 ? PAL.ragMid : (dToLight < 420 ? PAL.oakLight : PAL.oakMid);
    if (random() < 0.45) rayCol = PAL.lampBlack; // open oak ring pores filled with black ink

    brush.set("press_edge", rayCol, random(0.35, 0.75) * t);
    let len = random(7, 26) * t;
    let ang = random(-4, 7);
    brush.line(rx, ry, rx + cos(ang) * len, ry + sin(ang) * len);
  }

  // Oak Table Plank Joint Seam running across y ~ 915..955
  let seamPts = [];
  let seamHighlight = [];
  for (let sx = 60; sx <= 1140; sx += 35) {
    let sy = map(sx, 60, 1140, 912, 956) + (noise(sx * 0.01) - 0.5) * 4;
    seamPts.push([sx, sy]);
    seamHighlight.push([sx, sy + 2.4]);
  }
  brush.set("press_edge", PAL.voidBlack, 1.35);
  brush.spline(seamPts, 0.2);
  brush.set("press_edge", PAL.oakLight, 0.65);
  brush.spline(seamHighlight, 0.2);

  // Subtle back edge of the oak table meeting the vertical dark plate tone (~ y = 648..668)
  let horizonPts = [];
  let horizonGhost = [];
  for (let hx = 60; hx <= 1140; hx += 40) {
    let hy = map(hx, 60, 1140, 648, 668) + (noise(hx * 0.008, 9.1) - 0.5) * 6;
    horizonPts.push([hx, hy]);
    horizonGhost.push([hx + 5, hy - 3.5]); // uneven press offset on table edge
  }
  brush.set("charcoal", PAL.oakMid, 0.75);
  brush.spline(horizonPts, 0.25);
  brush.set("press_edge", PAL.umberBloom, 0.55);
  brush.spline(horizonGhost, 0.25);
  resetBrush();

  // POOLED BURNT UMBER & LAMP-BLACK CAST SHADOW UNDER & RIGHT OF THE NAPKIN
  // 1) Outer warm burnt umber bloom where ink pooled around the shadow perimeter
  const umberShadowBloom = [
    [132, 902], [275, 975], [435, 1058], [625, 1025],
    [825, 995], [1035, 935], [1055, 865], [885, 825],
    [715, 765], [420, 865]
  ];
  brush.fill(PAL.umberBloomBright, 110);
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.78, 0.45);
  drawPoly(umberShadowBloom, 0.35, true);
  resetBrush();

  // 2) Secondary deeper burnt umber pool
  const umberShadowCore = [
    [145, 900], [280, 970], [438, 1050], [610, 1005],
    [785, 965], [965, 905], [945, 855], [765, 825], [450, 880]
  ];
  brush.fill(PAL.umberDeep, 145);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.7, 0.4);
  drawPoly(umberShadowCore, 0.3, true);
  resetBrush();

  // 3) Dense lamp-black contact shadow directly beneath the crumpled cloth & trailing right
  const contactShadow = [
    [142, 896], [278, 968], [436, 1046], [602, 990],
    [755, 948], [910, 885], [868, 856], [710, 835], [380, 895]
  ];
  brush.mass("charcoal", PAL.voidBlack, { precision: 0.5, strength: 0.92, gradient: 0.15, outline: true });
  drawPoly(contactShadow, 0.25, true);
  resetBrush();

  // Doubled offset press edge along the cast shadow boundary
  let shadowEdge = [[275, 970], [436, 1048], [605, 992], [765, 952], [935, 895], [870, 858]];
  brush.set("press_edge", PAL.umberBloomBright, 0.95);
  brush.spline(offsetPts(shadowEdge, 6.5, -4.0, 1.5), 0.3);
  brush.set("press_edge", PAL.voidBlack, 1.15);
  brush.spline(shadowEdge, 0.3);
  resetBrush();
}

// ============================================================================
// 4. FIRST REDUCTIVE RAG-WIPES: GHOSTED HALOS OF THE NAPKIN
// ============================================================================
function drawNapkinReductiveUnderwipe() {
  resetBrush();

  // In a reductive monotype, the artist first wipes a broad ghost silhouette out of the dark ink,
  // leaving soft, feathered "ghosted borders" extending slightly beyond the crisp cloth folds.
  const ghostSilhouetteOuter = [
    [126, 895], [176, 745], [248, 615], [348, 526],
    [432, 540], [548, 562], [668, 612], [755, 705],
    [882, 858], [742, 952], [602, 992], [435, 1052], [268, 972]
  ];

  // Soft smoky ghost border where the rag first lifted the lamp-black
  brush.fill(PAL.ragDark, 92);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.72, 0.35);
  drawPoly(ghostSilhouetteOuter, 0.32, true);
  resetBrush();

  // Inner warmer rag lift establishing the overall bone-grey undertone of the cloth
  const ghostSilhouetteInner = [
    [142, 892], [192, 758], [262, 632], [356, 546],
    [425, 558], [542, 578], [650, 628], [732, 715],
    [862, 856], [730, 938], [595, 978], [435, 1038], [276, 962]
  ];
  brush.fill(PAL.ragGhost, 110);
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.65, 0.3);
  drawPoly(ghostSilhouetteInner, 0.28, true);
  resetBrush();

  // Broad directional rag-smear strokes that spill slightly across the perimeter (soft ghosted borders)
  const perimeterRagSmears = [
    { x1: 210, y1: 710, x2: 365, y2: 535, col: PAL.ragGhost, w: 1.3 },
    { x1: 350, y1: 538, x2: 455, y2: 565, col: PAL.ragMid, w: 1.15 },
