function drawNapkinSculpturalFacets() {
  resetBrush();
  const zones = getNapkinZones();

  // Pass 1: Soft watercolor-style bleed fills to simulate solvent/rag tone lifting
  for (let z of zones) {
    brush.fill(z.fillCol, z.fillOp);
    brush.fillBleed(0.24, "out");
    brush.fillTexture(0.68, 0.32);
    drawPoly(z.pts, 0.22, true);
  }
  resetBrush();

  // Pass 2: Dry-media pastel/crayon mass passes emulating hand pressure wiping across each facet
  for (let z of zones) {
    brush.mass("charcoal", z.massCol, {
      precision: 0.55,
      strength: z.massStr,
      gradient: 0.35,
      outline: false
    });
    drawPoly(z.pts, 0.2, true);
    resetBrush();
  }

  // Pass 3: Directional rag-smears & tarlatan wipe marks tailored to each facet's 3D orientation
  for (let z of zones) {
    // Compute bounding box & centroid of the facet
    let cx = 0, cy = 0;
    let minX = 9999, maxX = -9999, minY = 9999, maxY = -9999;
    for (let p of z.pts) {
      cx += p[0]; cy += p[1];
      minX = min(minX, p[0]); maxX = max(maxX, p[0]);
      minY = min(minY, p[1]); maxY = max(maxY, p[1]);
    }
    cx /= z.pts.length;
    cy /= z.pts.length;

    let polyObj = new brush.Polygon(z.pts);

    // Hatch with tarlatan/pencil along the cloth contour to build tactile fold grain
    brush.hatchStyle("2B", z.wipeCol, 0.65);
    brush.hatch(7.5, z.wipeAng, { rand: 0.12, continuous: false, gradient: 0.35 });
    polyObj.hatch(7.5, z.wipeAng, { rand: 0.12, continuous: false, gradient: 0.35 });
    resetBrush();

    // Directional rag smears across the belly of the fold with soft ghosted edges
    let numSmears = 14;
    for (let i = 0; i < numSmears; i++) {
      let sx = lerp(minX, maxX, random(0.15, 0.85));
      let sy = lerp(minY, maxY, random(0.15, 0.85));
      let ang = z.wipeAng + random(-14, 14);
      let len = random(28, 78);
      let hx = sx - cos(ang) * len * 0.5;
      let hy = sy - sin(ang) * len * 0.5;
      let tx = sx + cos(ang) * len * 0.5;
      let ty = sy + sin(ang) * len * 0.5;

      // Ghost border halo around the rag smear
      brush.set("rag_broad", PAL.ragMid, random(0.55, 1.05));
      brush.line(hx - 3, hy + 2, tx + 3, ty - 2);

      // Core rag smear
      brush.set(i % 2 === 0 ? "rag_broad" : "tarlatan_streak", z.wipeCol, random(0.45, 0.9));
      brush.line(hx, hy, tx, ty);
    }
  }
  resetBrush();
}

