      umber: PAL.umberDeep, dark: PAL.brownBlack
    },
    // Left shoulder pinch crease
    {
      pts: [[228, 775], [312, 695], [342, 610], [328, 715], [275, 815]],
      umber: PAL.umberBloom, dark: PAL.brownBlack
    },
    // Right wing lower trough
    {
      pts: [[635, 792], [752, 842], [848, 862], [742, 912], [648, 885]],
      umber: PAL.umberDeep, dark: PAL.lampBlack
    }
  ];

  // First bloom burnt umber out of the crevices into the adjacent pale cloth
  for (let c of crevices) {
    brush.fill(c.umber, 125);
    brush.fillBleed(0.38, "out");
    brush.fillTexture(0.75, 0.45);
    drawPoly(c.pts, 0.28, true);
  }
  resetBrush();

  // Then lay in the velvety lamp-black charcoal core inside the deepest pinch of each fold
  for (let c of crevices) {
    // Slightly contracted core polygon
    let cx = 0, cy = 0;
    for (let p of c.pts) { cx += p[0]; cy += p[1]; }
    cx /= c.pts.length; cy /= c.pts.length;
    let corePts = c.pts.map(p => [lerp(p[0], cx, 0.25), lerp(p[1], cy, 0.25)]);

    brush.fill(c.dark, 175);
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.65, 0.35);
    drawPoly(corePts, 0.25, true);
    resetBrush();

    // Charcoal shading strokes transitioning out of the crevice wall
    for (let i = 0; i < c.pts.length - 1; i++) {
      let p1 = c.pts[i];
