// ============================================================================
function drawUnevenPressEdgesAndHem() {
  resetBrush();

  // Key structural fold ridges, creases, and hem contours across the crumpled napkin
  const majorFoldContours = [
    // 1. Primary High Crown spine & left slope
    {
      pts: [[195, 765], [265, 635], [355, 550], [420, 560], [455, 665], [395, 780], [295, 835]],
