    },
    // 2. Central Canyon to Secondary Arch ridge
    {
      pts: [[420, 560], [485, 595], [545, 580], [595, 650], [575, 755], [530, 835]],
      mainCol: PAL.lampBlack, ghostCol: PAL.umberBloom, lightGhost: PAL.boneHigh, w: 0.9
    },
    // 3. Central Buckled S-Bridge overhanging lip
    {
      pts: [[235, 785], [295, 835], [395, 780], [475, 820], [530, 835], [465, 895], [345, 905]],
      mainCol: PAL.voidBlack, ghostCol: PAL.umberBloomBright, lightGhost: PAL.boneBright, w: 1.1
    },
    // 4. Left Apron & Mitered Corner A outer edge
    {
      pts: [[195, 765], [142, 895], [275, 965], [345, 905]],
      mainCol: PAL.voidBlack, ghostCol: PAL.umberBloom, lightGhost: PAL.boneMid, w: 1.05
    },
    // 5. Foreground Rolled Hem Crest & Mitered Corner B
    {
      pts: [[275, 965], [395, 945], [525, 945], [625, 915], [595, 985], [435, 1042], [275, 965]],
      mainCol: PAL.voidBlack, ghostCol: PAL.umberBloomBright, lightGhost: PAL.boneHigh, w: 1.1
    },
    // 6. Right Trailing Wing ridge & Corner C
    {
      pts: [[545, 580], [655, 625], [735, 715], [865, 860], [735, 945], [625, 915]],
      mainCol: PAL.lampBlack, ghostCol: PAL.umberBloom, lightGhost: PAL.ragLight, w: 0.9
    },
    // 7.Right-Center internal pipe fold
    {
      pts: [[615, 775], [705, 815], [745, 835], [865, 860]],
      mainCol: PAL.brownBlack, ghostCol: PAL.smokyUmber, lightGhost: PAL.boneMid, w: 0.85
    },
    // 8. Ironed press-crease memory line cutting across the left crown & apron
    {
      pts: [[168, 845], [258, 810], [348, 715], [412, 625], [445, 575]],
      mainCol: PAL.ragDark, ghostCol: PAL.umberBloom, lightGhost: PAL.boneBright, w: 0.7
    }
  ];

  // Draw the doubled, offset edges simulating paper slippage / uneven press registration:
  // Offset 1: (+5.5, -3.5) px warm umber/dark ghost impression
  // Offset 2: (-3.2, +2.2) px pale bone relief lip where ink was squeezed aside
  // Main: crisp broken monotype contour
  for (let fc of majorFoldContours) {
    let ghostDark = offsetPts(fc.pts, 5.8, -3.6, 1.2);
    let ghostLight = offsetPts(fc.pts, -3.2, 2.2, 0.8);

    // Pale lifted relief ghost
    brush.set("press_edge", fc.lightGhost, fc.w * 0.85);
    brush.spline(ghostLight, 0.28);

    // Offset dark/umber ghost edge from uneven press
    brush.set("press_edge", fc.ghostCol, fc.w * 0.9);
    brush.spline(ghostDark, 0.28);

    // Primary structural crease contour
    brush.set("press_edge", fc.mainCol, fc.w * 1.1);
    brush.spline(fc.pts, 0.28);
  }

  // HEMMED BORDER & DRAWN-THREAD HEMSTITCH ANATOMY
  // A linen table napkin has a ~20px folded hem with a delicate row of hemstitch pinholes
  // and mitered diagonal seams at the corners.
  const hemRuns = [
    // Left apron hem (Corner A)
    {
      outer: [[188, 780], [142, 895], [275, 965], [335, 912]],
      inner: [[206, 788], [164, 888], [272, 944], [322, 900]],
      miter: [[142, 895], [164, 888]],
      lightLevel: 0.85
    },
    // Foreground rolled hem & Corner B
    {
      outer: [[275, 965], [435, 1042], [595, 985], [622, 922]],
      inner: [[292, 952], [435, 1018], [582, 968], [606, 916]],
      miter: [[435, 1042], [435, 1018]],
      lightLevel: 0.9
    },
    // Right trailing wing hem & Corner C
    {
      outer: [[720, 702], [865, 860], [735, 945], [625, 915]],
      inner: [[706, 714], [840, 858], [726, 926], [628, 898]],
      miter: [[865, 860], [840, 858]],
      lightLevel: 0.55
    }
  ];

  for (let h of hemRuns) {
    // Raised double-thickness cloth ridge along the inner hem line
    brush.set("press_edge", h.lightLevel > 0.7 ? PAL.boneHigh : PAL.ragLight, 0.95);
    brush.spline(offsetPts(h.inner, -1.5, -1.5, 0.4), 0.25);

    // Hemstitch shadow groove & doubled press offset
    brush.set("press_edge", PAL.smokyUmber, 0.75);
    brush.spline(h.inner, 0.25);
    brush.set("press_edge", PAL.umberBloom, 0.55);
    brush.spline(offsetPts(h.inner, 4.5, -2.8, 0.6), 0.25);

    // Mitered corner diagonal seam where the folded hems meet at 45 degrees
    brush.set("press_edge", PAL.brownBlack, 0.85);
    brush.line(h.miter[0][0], h.miter[0][1], h.miter[1][0], h.miter[1][1]);
    brush.set("press_edge", PAL.boneHigh, 0.65);
    brush.line(h.miter[0][0] - 1.5, h.miter[0][1] - 1.5, h.miter[1][0] - 1.5, h.miter[1][1] - 1.5);

    // Drawn-thread hemstitch perforations (tiny rhythmic bundle pinpricks every ~6.5px)
    for (let s = 0; s < h.inner.length - 1; s++) {
      let p1 = h.inner[s];
      let p2 = h.inner[s + 1];
      let d = dist(p1[0], p1[1], p2[0], p2[1]);
      let steps = floor(d / 6.5);
      for (let k = 1; k < steps; k++) {
        let t = k / steps;
        let px = lerp(p1[0], p2[0], t);
        let py = lerp(p1[1], p2[1], t);
        // Tiny pinhole shadow
        brush.set("linen_thread", PAL.lampBlack, 0.95);
        brush.line(px, py, px + 1.4, py + 1.2);
        // Tiny bundled thread crown catching light
        brush.set("linen_thread", h.lightLevel > 0.7 ? PAL.boneBright : PAL.boneMid, 0.85);
        brush.line(px - 1.2, py - 1.2, px + 0.6, py - 2.4);
      }
    }
  }
  resetBrush();
}

