// 8. FINGERTIP LIFTS & HYPERREAL LINEN WEAVE ON SUNLIT CRESTS
// ============================================================================
function drawFingertipLiftsAndHyperrealWeave() {
  resetBrush();

  // Define the sunlit crests where fingertip lifts pull out luminous warm bone-white
  // and where light catches the hyperreal warp-and-weft linen weave.
  const sunlitCrests = [
    // Crest A: Primary High Crown (upper-left sunlit slope & ridge spine)
    {
      cx: 358, cy: 658, rx: 68, ry: 95, rot: -22,
      warpAng: -64, weftAng: 28, curvature: 0.24, spacing: 3.5, intensity: 1.0
    },
    // Crest B: High Crown Upper Peak Knuckle
    {
      cx: 382, cy: 578, rx: 42, ry: 36, rot: 12,
      warpAng: -48, weftAng: 44, curvature: 0.3, spacing: 3.4, intensity: 0.98
    },
    // Crest C: Secondary Diagonal Arch Spine
    {
      cx: 545, cy: 668, rx: 38, ry: 82, rot: -26,
      warpAng: -60, weftAng: 32, curvature: 0.28, spacing: 3.5, intensity: 0.94
    },
    // Crest D: Central Buckled S-Bridge Ridge
    {
      cx: 412, cy: 836, rx: 86, ry: 34, rot: -10,
      warpAng: -14, weftAng: 78, curvature: 0.22, spacing: 3.4, intensity: 0.96
    },
    // Crest E: Left Apron Sunlit Shelf
    {
      cx: 232, cy: 848, rx: 56, ry: 42, rot: -28,
      warpAng: -32, weftAng: 58, curvature: 0.18, spacing: 3.6, intensity: 0.88
    },
    // Crest F: Foreground Rolled Hem Crest
    {
      cx: 458, cy: 956, rx: 92, ry: 24, rot: -8,
      warpAng: -10, weftAng: 82, curvature: 0.25, spacing: 3.5, intensity: 0.92
    },
    // Crest G: Right-Center Knuckle Lift
    {
      cx: 626, cy: 806, rx: 38, ry: 28, rot: 18,
      warpAng: -38, weftAng: 52, curvature: 0.26, spacing: 3.6, intensity: 0.82
    },
    // Crest H: Right Trailing Wing Upper Spine
    {
      cx: 725, cy: 765, rx: 64, ry: 22, rot: 34,
      warpAng: 34, weftAng: -56, curvature: 0.18, spacing: 3.8, intensity: 0.74
    }
  ];

  // STEP 1: FINGERTIP LIFTS & RAG-SMEARS WITH SOFT GHOSTED BORDERS
  for (let c of sunlitCrests) {
    // 1a) Soft ghosted outer border left by the edge of the fingertip / wrapped rag
    let ghostPts = [];
    let corePts = [];
    for (let a = 0; a < 360; a += 24) {
      let lx = cos(a) * c.rx * 1.28;
      let ly = sin(a) * c.ry * 1.28;
      let rx = c.cx + lx * cos(c.rot) - ly * sin(c.rot) + (noise(c.cx, a * 0.1) - 0.5) * 14;
      let ry = c.cy + lx * sin(c.rot) + ly * cos(c.rot) + (noise(c.cy, a * 0.1) - 0.5) * 14;
      ghostPts.push([rx, ry]);

      let clx = cos(a) * c.rx * 0.88;
      let cly = sin(a) * c.ry * 0.88;
      let crx = c.cx + clx * cos(c.rot) - cly * sin(c.rot) + (noise(c.cx + 50, a * 0.1) - 0.5) * 8;
      let cry = c.cy + clx * sin(c.rot) + cly * cos(c.rot) + (noise(c.cy + 50, a * 0.1) - 0.5) * 8;
      corePts.push([crx, cry]);
    }

    // Ghosted halo border around the fingertip lift
    brush.set("rag_broad", PAL.ragLight, 0.75);
    brush.spline(offsetPts(ghostPts, 4, -2.5, 2), 0.35);

    // Luminous bone-white fingertip lift fill
    brush.fill(PAL.boneHigh, floor(170 * c.intensity));
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.45, 0.25);
    drawPoly(corePts, 0.35, true);
    resetBrush();

    // Fingertip dab & twist strokes pulling to pure warm bone-white at the crest apex
    for (let d = 0; d < 12; d++) {
      let ang = c.warpAng + random(-18, 18);
      let distR = random(0, 0.65);
      let lx = cos(d * 30) * c.rx * distR;
      let ly = sin(d * 30) * c.ry * distR;
      let sx = c.cx + lx * cos(c.rot) - ly * sin(c.rot);
      let sy = c.cy + lx * sin(c.rot) + ly * cos(c.rot);
      let strokeLen = random(18, 46);
      brush.set("fingertip_lift", d % 2 === 0 ? PAL.boneBright : PAL.boneHigh, random(0.55, 1.05));
      brush.line(
        sx - cos(ang) * strokeLen * 0.5,
        sy - sin(ang) * strokeLen * 0.5,
        sx + cos(ang) * strokeLen * 0.5,
        sy + sin(ang) * strokeLen * 0.5
      );
    }
  }
  resetBrush();

  // STEP 2: HYPERREAL LINEN WEAVE TEXTURE ONLY WHERE LIGHT CATCHES THE CRESTS
  // Renders individual curving warp and weft flax threads with natural slubs,
  // pinpoint interstice shadows, and bright bone-white thread crowns that fade smoothly into mid-tones.
  for (let c of sunlitCrests) {
    drawHyperrealCrestWeave(c);
  }
  resetBrush();
}

function drawHyperrealCrestWeave(c) {
  let step = c.spacing;
  let uCount = floor((c.rx * 2.1) / step);
  let vCount = floor((c.ry * 2.1) / step);

  // Local basis vectors aligned with the crest's warp and weft directions
  let ux = cos(c.warpAng + 90), uy = sin(c.warpAng + 90);
  let vx = cos(c.warpAng), vy = sin(c.warpAng);

  // Helper to map local grid (iu, iv) to 2D canvas coordinates with 3D fold cylinder curvature
  function gridToCanvas(iu, iv) {
    let nu = (iu / max(1, uCount) - 0.5) * 2; // -1 .. 1 across fold width
    let nv = (iv / max(1, vCount) - 0.5) * 2; // -1 .. 1 along fold spine

    // Foreshortening & cylindrical wrap over the fold crest:
    // Threads compress slightly as the surface curves away from the raking light
    let wrapU = sin(nu * 78) * c.rx;
    let archBow = (1 - nu * nu) * c.curvature * 24;
    let slubJitter = (noise(iu * 0.35, iv * 0.35, c.cx * 0.1) - 0.5) * 0.9;

    let px = c.cx + ux * wrapU + vx * (nv * c.ry + archBow) + slubJitter;
    let py = c.cy + uy * wrapU + vy * (nv * c.ry + archBow) + slubJitter;

    // Illumination falloff: highest along the sunlit crest ridge (nu ~ -0.18),
    // fading smoothly to 0 at the edges of the fingertip lift
    let radialDist = sqrt(sq((nu + 0.12) / 0.95) + sq(nv / 0.98));
    let lightVal = constrain(1.0 - Math.pow(radialDist, 1.65), 0, 1) * c.intensity;

    return { x: px, y: py, light: lightVal, nu, nv };
  }

  // 1) Draw Warp Threads (continuous slubbed linen fibers curving along the fold)
  for (let iu = 0; iu <= uCount; iu++) {
    // Natural flax slub variation: some threads are slightly thicker and more luminous
    let isSlubWarp = noise(iu * 0.7, c.cx) > 0.62;
    let warpPtsShadow = [];
    let warpPtsLight = [];

    for (let iv = 0; iv <= vCount; iv++) {
      let pt = gridToCanvas(iu, iv);
      if (pt.light > 0.16) {
        warpPtsLight.push([pt.x, pt.y]);
        warpPtsShadow.push([pt.x + 0.65, pt.y + 0.65]);
      } else {
        if (warpPtsLight.length >= 3) {
          brush.set("linen_thread", PAL.ragGhost, 0.42);
          brush.spline(warpPtsShadow, 0.25);
          brush.set("linen_thread", isSlubWarp ? PAL.boneBright : PAL.boneHigh, isSlubWarp ? 0.68 : 0.48);
          brush.spline(warpPtsLight, 0.25);
        }
        warpPtsLight = [];
        warpPtsShadow = [];
      }
    }
    if (warpPtsLight.length >= 3) {
      brush.set("linen_thread", PAL.ragGhost, 0.42);
      brush.spline(warpPtsShadow, 0.25);
      brush.set("linen_thread", isSlubWarp ? PAL.boneBright : PAL.boneHigh, isSlubWarp ? 0.68 : 0.48);
      brush.spline(warpPtsLight, 0.25);
    }
  }

  // 2) Draw Weft Threads (crossing perpendicular over the curved crest)
  for (let iv = 0; iv <= vCount; iv++) {
    let isSlubWeft = noise(iv * 0.7, c.cy) > 0.62;
    let weftPtsShadow = [];
    let weftPtsLight = [];

    for (let iu = 0; iu <= uCount; iu++) {
      let pt = gridToCanvas(iu, iv);
      if (pt.light > 0.18) {
        weftPtsLight.push([pt.x, pt.y]);
        weftPtsShadow.push([pt.x + 0.6, pt.y + 0.6]);
      } else {
        if (weftPtsLight.length >= 3) {
          brush.set("linen_thread", PAL.ragMid, 0.4);
          brush.spline(weftPtsShadow, 0.25);
          brush.set("linen_thread", isSlubWeft ? PAL.boneBright : PAL.boneLight, isSlubWeft ? 0.65 : 0.45);
          brush.spline(weftPtsLight, 0.25);
        }
        weftPtsLight = [];
        weftPtsShadow = [];
      }
    }
    if (weftPtsLight.length >= 3) {
      brush.set("linen_thread", PAL.ragMid, 0.4);
      brush.spline(weftPtsShadow, 0.25);
      brush.set("linen_thread", isSlubWeft ? PAL.boneBright : PAL.boneLight, isSlubWeft ? 0.65 : 0.45);
      brush.spline(weftPtsLight, 0.25);
    }
  }

  // 3) Micro-Interstices & Over-Under Thread Crowns at the brightest apex of the crest
  // Where light rakes across the very peak of the fold, each thread crossing creates a
  // tiny dark pore shadow next to a gleaming bone-white knuckle crown.
  for (let iu = 1; iu < uCount; iu++) {
    for (let iv = 1; iv < vCount; iv++) {
      let pt = gridToCanvas(iu, iv);
      if (pt.light < 0.42) continue;

      // Alternate 1-over-1 plain weave phase
      let phase = (iu + iv) % 2;
      let shadowCol = pt.light > 0.75 ? PAL.ragDark : PAL.ragGhost;

      // Pinpoint interstice shadow pore between crossing threads
      brush.set("linen_thread", shadowCol, map(pt.light, 0.42, 1.0, 0.35, 0.78));
      brush.line(pt.x + 0.8, pt.y + 0.8, pt.x + 1.8, pt.y + 1.5);

      // Gleaming pure bone-white crown on the top thread of the crossing
      if (pt.light > 0.58) {
        brush.set("linen_thread", PAL.boneBright, map(pt.light, 0.58, 1.0, 0.45, 0.95));
        if (phase === 0) {
          brush.line(pt.x - 1.1 * vx, pt.y - 1.1 * vy, pt.x + 1.1 * vx, pt.y + 1.1 * vy);
        } else {
          brush.line(pt.x - 1.1 * ux, pt.y - 1.1 * uy, pt.x + 1.1 * ux, pt.y + 1.1 * uy);
        }
      }
    }
  }
}

// ============================================================================
// 9. MONOTYPE PLATE INCIDENTS & EMBOSSED PLATE BEVEL
// ============================================================================
function drawMonotypeSurfaceIncidents() {
  resetBrush();

  // 1) Delicate loose flax lint fibers catching light along the sunlit napkin ridges
  const sunlitEdges = [
    [[235, 785], [325, 695], [355, 550], [420, 560]],
    [[485, 595], [545, 580], [595, 650]],
    [[295, 835], [395, 780], [475, 820]],
    [[275, 965], [395, 945], [525, 945]]
  ];

  for (let chain of sunlitEdges) {
    for (let s = 0; s < chain.length - 1; s++) {
      let p1 = chain[s];
      let p2 = chain[s + 1];
      for (let i = 0; i < 16; i++) {
        let t = random();
        let px = lerp(p1[0], p2[0], t) + random(-3, 3);
        let py = lerp(p1[1], p2[1], t) + random(-3, 3);
        let ang = random(-150, -20);
        let len = random(3, 8.5);
        brush.set("linen_thread", PAL.boneBright, random(0.3, 0.55));
        brush.line(px, py, px + cos(ang) * len, py + sin(ang) * len);
      }
    }
  }

  // 2) Authentic monotype dust/fiber resists in the dark plate tone
  // (tiny bone-white specs and hairlines where a speck of paper lint blocked the black ink)
  for (let i = 0; i < 68; i++) {
    let rx = random(PLATE.x1 + 20, PLATE.x2 - 20);
    let ry = random(PLATE.y1 + 20, PLATE.y2 - 20);
    // Mostly in the dark upper margin and shadow zones
    if (rx > 180 && rx < 780 && ry > 560 && ry < 980 && random() < 0.75) continue;
    let col = random() < 0.6 ? PAL.boneMid : PAL.ragLight;
    brush.set("linen_thread", col, random(0.3, 0.65));
    let len = random(1.5, 5.5);
    let ang = random(360);
    brush.line(rx, ry, rx + cos(ang) * len, ry + sin(ang) * len);
  }

  // 3) Fine charcoal spatter / plate grain around the transition zones
  for (let i = 0; i < 180; i++) {
    let sx = random(110, 960);
    let sy = random(480, 1080);
    let col = i % 3 === 0 ? PAL.umberBloom : (i % 3 === 1 ? PAL.lampBlack : PAL.ragDark);
    brush.set("spray", col, random(0.35, 0.8));
    brush.line(sx, sy, sx + random(-12, 12), sy + random(-12, 12));
  }
  resetBrush();
}

function drawPlateEmbossedBevel() {
  resetBrush();
  let x1 = PLATE.x1, y1 = PLATE.y1, x2 = PLATE.x2, y2 = PLATE.y2;

  // Irregular ink squash along the zinc plate edge (burnt umber + lamp-black bead)
  let topEdge = [], botEdge = [], leftEdge = [], rightEdge = [];
  for (let x = x1; x <= x2; x += 30) {
    topEdge.push([x, y1 + (noise(x * 0.02, 1) - 0.5) * 3.5]);
    botEdge.push([x, y2 + (noise(x * 0.02, 2) - 0.5) * 3.5]);
  }
  for (let y = y1; y <= y2; y += 30) {
    leftEdge.push([x1 + (noise(y * 0.02, 3) - 0.5) * 3.5, y]);
    rightEdge.push([x2 + (noise(y * 0.02, 4) - 0.5) * 3.5, y]);
  }

  for (let edge of [topEdge, botEdge, leftEdge, rightEdge]) {
    brush.set("press_edge", PAL.umberBloom, 1.15);
    brush.spline(offsetPts(edge, 1.8, 1.5, 1.0), 0.15);
    brush.set("press_edge", PAL.voidBlack, 1.35);
    brush.spline(edge, 0.15);
  }

  // Embossed paper plate-mark (debossed outer rim 6px outside the inked plate)
  let m = 7;
  brush.set("2H", PAL.paperEdge, 0.85);
  brush.line(x1 - m, y1 - m, x2 + m, y1 - m);
  brush.line(x1 - m, y1 - m, x1 - m, y2 + m);

  brush.set("2H", PAL.boneBright, 0.95);
  brush.line(x1 - m, y2 + m, x2 + m, y2 + m);
  brush.line(x2 + m, y1 - m, x2 + m, y2 + m);

  // Subtle printer's thumb smudge in the lower-left paper margin
  brush.fill(PAL.ragMid, 22);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.7, 0.3);
  drawPoly([[18, 1020], [46, 1012], [50, 1068], [20, 1075]], 0.4, true);
  resetBrush();
}

// Hyperreal Jungle Crow on Utility Wire against Crushed Azurite & Tarnished Gold Mist
// p5.js 2.x + p5.brush

function wireY(x) {
  const x0 = -30, y0 = 690;
  const x1 = 1125, y1 = 224;
  const t = constrain((x - x0) / (x1 - x0), 0, 1);
  const lin = lerp(y0, y1, t);
  const sag = 112 * 4 * t * (1 - t) + 7 * Math.exp(-Math.pow((x - 830) / 110, 2));
  return lin + sag;
}

function wireSlopeAngle(x) {
  const dx = 2;
  const dy = wireY(x + dx) - wireY(x - dx);
  return atan2(dy, 2 * dx);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(8831);

  // Custom mineral crystal brush for crushed azurite granulation
  brush.add("azurite_grit", {
    type: "custom",
    weight: 1.4,
    scatter: 2.8,
    opacity: 65,
    spacing: 0.9,
    pressure: [0.4, 1.3, 0.3],
    tip: (_m) => {
      _m.rotate(25);
      _m.rect(-0.9, -0.6, 1.8, 1.2);
      _m.rect(0.4, 0.3, 0.8, 0.8);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.9
  });

  // Custom sheared metallic flake brush for tarnished gold leaf
  brush.add("gold_flake", {
    type: "custom",
    weight: 2.2,
    scatter: 0.65,
    opacity: 48,
    spacing: 0.45,
    pressure: [0.8, 1.1, 0.7],
    tip: (_m) => {
      _m.rect(-2.2, -0.7, 4.4, 1.4);
    },
    rotate: "none",
    markerTip: false,
    noise: 0.4
  });

  // Custom hyper-fine tapered barb brush for iridescent plumage
  brush.add("feather_barb", {
    type: "default",
    weight: 0.32,
    scatter: 0.04,
    sharpness: 0.92,
    grain: 0.25,
    opacity: 165,
    spacing: 0.12,
    pressure: [0.9, 1.25, 0.15],
    noise: 0.25
  });

  // Custom sediment vector field for watercolor mineral settling & drifting mist
  brush.addField("mineral_drift", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        const nx = col * 0.09;
        const ny = row * 0.09;
        const angle = (noise(nx, ny, t * 0.1) - 0.5) * 38 + sin(row * 0.35) * 8;
        field[col][row] = angle;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Deep dusky twilight mineral ground
  background("#07101f");

  // 2. Crushed Azurite Watercolor Sky & Granular Mineral Texture
  drawAzuriteSky();

  // 3. Tarnished Gold-Leaf Mist Band drifting behind the bird
  drawTarnishedGoldMist();

  // 4. Industrial Insulator, Steel Bracket & Sagging Stranded Utility Wire (Back pass)
  drawInsulatorAndBracket();
  drawUtilityWire();

  // 5. Hyperreal Jungle Crow (Corvus macrorhynchos)
  drawJungleCrow();

  // 6. Foreground Foot Claws wrapping over the wire & final atmospheric glints
  drawForegroundTalons();
  drawFinalSparkles();

  noLoop();
}

// ============================================================================
// 1. CRUSHED AZURITE SKY & GRANULAR MINERAL TEXTURE
// ============================================================================
function drawAzuriteSky() {
  brush.noStroke();

  // Batch 1: Deep Prussian & Twilight Indigo base washes
  const deepWashes = [
    { x: -60, y: -60, w: 1320, h: 480, col: "#0a1931", op: 115, bleed: 0.42 },
    { x: -60, y: 720, w: 1320, h: 540, col: "#091326", op: 130, bleed: 0.38 },
    { x: -40, y: 380, w: 780, h: 520, col: "#0d2140", op: 95, bleed: 0.45 },
    { x: 420, y: 580, w: 820, h: 640, col: "#111b36", op: 110, bleed: 0.40 }
  ];
  for (const w of deepWashes) {
    brush.fill(w.col, w.op);
    brush.fillBleed(w.bleed, "out");
    brush.fillTexture(0.88, 0.45);
    drawOrganicBand(w.x, w.y, w.w, w.h, 14);
  }

  // Batch 2: Rich Crushed Azurite Midtone blooms
  const azuriteWashes = [
    { x: -50, y: 20, w: 980, h: 380, col: "#133561", op: 95, bleed: 0.45 },
    { x: 280, y: -30, w: 960, h: 440, col: "#184378", op: 105, bleed: 0.48 },
    { x: -40, y: 260, w: 1280, h: 420, col: "#1c4e8a", op: 88, bleed: 0.44 },
    { x: 80, y: 460, w: 920, h: 420, col: "#153b6e", op: 92, bleed: 0.42 },
    { x: 480, y: 80, w: 720, h: 460, col: "#215a9c", op: 85, bleed: 0.50 }
  ];
  for (const w of azuriteWashes) {
    brush.fill(w.col, w.op);
    brush.fillBleed(w.bleed, "out");
    brush.fillTexture(0.92, 0.55);
    drawOrganicBand(w.x, w.y, w.w, w.h, 16);
  }

  // Batch 3: Luminous Lapis-Azurite highlights & Dusky Violet-Blue troughs
  const accentWashes = [
    { x: 520, y: 110, w: 640, h: 320, col: "#286bb5", op: 72, bleed: 0.46 },
    { x: 60, y: 140, w: 620, h: 290, col: "#245ea1", op: 68, bleed: 0.44 },
    { x: -30, y: 580, w: 760, h: 360, col: "#1a284d", op: 85, bleed: 0.38 },
    { x: 340, y: 780, w: 880, h: 420, col: "#141d3b", op: 95, bleed: 0.35 }
  ];
  for (const w of accentWashes) {
    brush.fill(w.col, w.op);
    brush.fillBleed(w.bleed, "in");
    brush.fillTexture(0.95, 0.62);
    drawOrganicBand(w.x, w.y, w.w, w.h, 14);
  }
  brush.noFill();

  // Sedimentary mineral granulation bands following vector field
  brush.field("mineral_drift");
  const gritColors = ["#060e1c", "#0c203d", "#173d6e", "#2560a3", "#367bc4", "#1b2847"];
  for (let c = 0; c < gritColors.length; c++) {
    brush.set("azurite_grit", gritColors[c], random(0.8, 1.45));
    const count = c < 3 ? 260 : 190;
    for (let i = 0; i < count; i++) {
      const gx = random(-20, 1220);
      // Concentrate mineral settling in horizontal watermark troughs
      const bandBias = floor(random(7)) * 175 + random(-65, 65);
      const gy = constrain(bandBias + (noise(gx * 0.004, i * 0.1) - 0.5) * 180, -10, 1210);
      const len = random(18, 75);
      brush.flowLine(gx, gy, len, random(-12, 12));
    }
  }

  // Fine charcoal & spray mineral settling texture (gritty watercolor edge pools)
  const sprayPalette = ["#081326", "#10294d", "#1f508c", "#3b7ec4", "#589ce0"];
  for (let s = 0; s < sprayPalette.length; s++) {
    brush.set("spray", sprayPalette[s], random(0.7, 1.3));
    const nStrokes = s === 4 ? 85 : 140;
    for (let i = 0; i < nStrokes; i++) {
      const sx = random(0, 1200);
      const sy = random(0, 1200);
      // Prefer pooling along organic noise contours
      if (noise(sx * 0.005, sy * 0.008) > 0.36) {
        brush.flowLine(sx, sy, random(25, 95), random(-18, 18));
      }
    }
  }
  brush.noField();

  // Sparkling crushed azurite crystal glints settled into the paper grain
  const glintColors = ["#498cd1", "#6eb1f5", "#99ccff", "#c7e4ff", "#2c6ba8", "#050b14"];
  for (let g = 0; g < glintColors.length; g++) {
    const isBright = g === 2 || g === 3;
    brush.set("2H", glintColors[g], isBright ? 0.55 : 0.75);
    const numGlints = isBright ? 240 : 380;
    for (let i = 0; i < numGlints; i++) {
      const x = random(10, 1190);
      const y = random(10, 1190);
      const n = noise(x * 0.006, y * 0.009);
      if (n > 0.44) {
        const l = random(1.2, 3.8);
        const a = random(360);
        brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
      }
    }
  }
}

function drawOrganicBand(x, y, w, h, steps) {
  brush.beginShape(0.45);
  for (let i = 0; i <= steps; i++) {
    const px = x + (w * i) / steps;
    const py = y + (noise(px * 0.004, y * 0.004) - 0.5) * 90;
    brush.vertex(px, py);
  }
  for (let i = steps; i >= 0; i--) {
    const px = x + (w * i) / steps;
    const py = y + h + (noise(px * 0.004, (y + h) * 0.004 + 10) - 0.5) * 90;
    brush.vertex(px, py);
  }
  brush.endShape(true);
}

// ============================================================================
// 2. TARNISHED GOLD-LEAF MIST BAND
// ============================================================================
function drawTarnishedGoldMist() {
  // Soft patinated bronze/ochre watercolor under-glow behind the bird
  brush.noStroke();
  const mistWashes = [
    { x: 140, y: 205, w: 1080, h: 155, col: "#3d311b", op: 85, bleed: 0.35 },
    { x: 260, y: 175, w: 940, h: 185, col: "#574523", op: 80, bleed: 0.38 },
    { x: 460, y: 155, w: 720, h: 195, col: "#755c2e", op: 75, bleed: 0.32 },
    { x: 560, y: 180, w: 540, h: 145, col: "#96783c", op: 65, bleed: 0.28 }
  ];
  for (const m of mistWashes) {
    brush.fill(m.col, m.op);
    brush.fillBleed(m.bleed, "out");
    brush.fillTexture(0.85, 0.5);
    drawMistRibbon(m.x, m.y, m.w, m.h, 18);
  }
  brush.noFill();

  // Layered sheared gold-leaf squares & tarnished metallic leaf fragments
  // Gold leaf is laid in rectangular leaf sheets ("haku") that fracture and drift at the edges
  const leafColors = [
    { col: "#453820", w: 1.3, count: 220 }, // dark bronze tarnish
    { col: "#665229", w: 1.2, count: 260 }, // antique umber gold
    { col: "#8a6f36", w: 1.15, count: 310 }, // tarnished brass-gold
    { col: "#ab8b46", w: 1.05, count: 290 }, // warm old gold leaf
    { col: "#cba85a", w: 0.95, count: 210 }, // bright gold leaf glint
    { col: "#e3c578", w: 0.80, count: 110 }, // pale champagne gold highlight
    { col: "#2c4742", w: 0.90, count: 95 }   // subtle verdigris oxidation on tarnished leaf
  ];

  for (const layer of leafColors) {
    brush.set("gold_flake", layer.col, layer.w);
    for (let i = 0; i < layer.count; i++) {
      // Concentrated around x: 220..1190, y: 165..385, richest behind the crow (x: 580..1080)
      const t = pow(random(), 0.78);
      const lx = lerp(1185, 90, t) + random(-35, 35);
      const centerCurveY = 265 + sin(lx * 0.32) * 28 + (noise(lx * 0.005, 4.2) - 0.5) * 75;
      const spreadY = map(lx, 100, 1150, 42, 92);
      const ly = centerCurveY + randomGaussian(0, spreadY * 0.46);

      // Quantize some coordinates slightly to evoke overlapping squares of real gold leaf
      const sheetQuantX = floor(lx / 48) * 48 + random(-18, 18);
      const px = lerp(lx, sheetQuantX, 0.35);
      const len = random(8, 34) * (1 - t * 0.35);
      const driftAngle = (noise(px * 0.008, ly * 0.015) - 0.5) * 14;
      brush.line(px, ly, px + cos(driftAngle) * len, ly + sin(driftAngle) * len);
    }
  }

  // Delicate dark azurite & tarnish cracks (craquelure) cutting through the gold-leaf mist
  brush.set("2H", "#112847", 0.55);
  for (let i = 0; i < 95; i++) {
    const cx = random(280, 1160);
    const cy = 265 + random(-75, 75);
    const angle = random(-25, 25);
    const len = random(12, 42);
    brush.line(cx, cy, cx + cos(angle) * len, cy + sin(angle) * len);
  }

  // Fine gold-leaf dust specs drifting off into the left azurite expanse
  const dustCols = ["#9c7e3e", "#c9a659", "#e8cb82"];
  for (let d = 0; d < dustCols.length; d++) {
    brush.set("cpencil", dustCols[d], 0.65);
    for (let i = 0; i < 160; i++) {
      const dx = random(40, 1180);
      const dy = 265 + sin(dx * 0.32) * 28 + randomGaussian(0, 58);
      const l = random(1.5, 5.5);
      brush.line(dx, dy, dx + l, dy + random(-1, 1));
    }
  }
}

function drawMistRibbon(x, y, w, h, steps) {
  brush.beginShape(0.5);
  for (let i = 0; i <= steps; i++) {
    const px = x + (w * i) / steps;
    const wave = sin(px * 0.32) * 24 + (noise(px * 0.006, 1.1) - 0.5) * 55;
    brush.vertex(px, y + wave);
  }
  for (let i = steps; i >= 0; i--) {
    const px = x + (w * i) / steps;
    const taper = sin((i / steps) * 180);
    const wave = sin(px * 0.32 + 20) * 24 + (noise(px * 0.006, 3.7) - 0.5) * 55;
    brush.vertex(px, y + wave + h * (0.25 + 0.75 * taper));
  }
  brush.endShape(true);
}

// ============================================================================
// 3. INDUSTRIAL INSULATOR, BRACKET & SAGGING STRANDED UTILITY WIRE
// ============================================================================
function drawInsulatorAndBracket() {
  push();
  // Heavy galvanized steel cross-arm bracket extending from right edge (x = 1200)
  // Supporting the vertical insulator pin at (1125, 224..315)
  const brkPts = [
    [1205, 295],
    [1116, 282],
    [1114, 298],
    [1205, 326]
  ];
  const strutPts = [
    [1205, 368],
    [1126, 296],
    [1136, 290],
    [1205, 350]
  ];

  brush.noStroke();
  brush.wash("#1b242e", 240);
  drawPoly(brkPts);
  drawPoly(strutPts);

  // Steel pin shaft holding insulator
  drawPoly([
    [1121, 248],
    [1133, 250],
    [1130, 305],
    [1118, 303]
  ]);
  brush.noWash();

  // Bracket metallic shading, bevels, hex bolts, and weathering rust
  brush.set("cpencil", "#4b5c6e", 0.9);
  for (let i = 0; i < 18; i++) {
    const ty = lerp(283, 296, i / 18);
    brush.line(1116, ty, 1202, ty + 14);
  }
  brush.set("2H", "#89a4bf", 0.75);
  brush.line(1116, 282, 1202, 295);
  brush.line(1134, 291, 1202, 352);

  // Rust streaks around bolt & pin nut
  brush.set("cpencil", "#6e3b26", 0.75);
  for (let i = 0; i < 14; i++) {
    const rx = random(1120, 1185);
    brush.line(rx, 286, rx + random(-2, 2), 286 + random(6, 15));
  }

  // Hex nut & washer under the bracket
  brush.noStroke();
  brush.wash("#11171f", 245);
  brush.rect(1124, 304, 20, 10, "center");
  brush.noWash();
  brush.set("rotring", "#7b93ab", 0.65);
  brush.line(1115, 300, 1133, 301);
  brush.line(1116, 308, 1132, 309);

  // High-Voltage Multi-Skirted Porcelain Pin Insulator
  // Tilted slightly left (-11 deg) into the wire tension
  push();
  translate(1125, 224);
  rotate(-11);

  // Draw from bottom skirt up to top dome for accurate occlusion
  // 1) Lower porcelain skirt (Bottom bell)
  drawPorcelainSkirt(0, 38, 56, 22, "#0c1520", "#1c3147", "#6ea4d8", "#b59a58");

  // 2) Middle wide drip-skirt (Main umbrella bell)
  drawPorcelainSkirt(0, 18, 74, 26, "#09111a", "#182c42", "#7eb5eb", "#c9ab63");

  // 3) Shadowed neck groove where tie-wire binds
  brush.noStroke();
  brush.wash("#080d14", 250);
  drawEllipsePoly(0, 2, 42, 14, 20);
  brush.noWash();

  // 4) Upper porcelain crown / dome
  drawPorcelainSkirt(0, -8, 52, 20, "#0b141f", "#1f3854", "#96c8f7", "#d9bc75");

  // Top saddle groove
  brush.set("rotring", "#060a0f", 0.85);
  brush.arc(0, -16, 16, 15, 165);
  brush.set("2H", "#b8dcff", 0.7);
  brush.arc(0, -15, 15, 25, 145);

  // Aluminum tie-wire ring & lashing collar around the insulator neck (y ~ 2)
  for (let r = -3; r <= 3; r += 1.5) {
    brush.set("rotring", r < 0 ? "#18222e" : "#89a6c2", 0.75);
    brush.line(-21, 2 + r, 21, 2 + r);
  }
  brush.set("2H", "#d4e9ff", 0.6);
  brush.line(-19, -1, 14, -1);

  pop();
  pop();
}

function drawPorcelainSkirt(cx, cy, w, h, darkCol, midCol, skySpecCol, goldReflCol) {
  // Base dark glazed porcelain silhouette
  brush.noStroke();
  brush.wash(darkCol, 250);
  brush.beginShape(0.35);
  brush.vertex(cx - w * 0.5, cy + h * 0.25);
  brush.vertex(cx - w * 0.38, cy - h * 0.45);
  brush.vertex(cx, cy - h * 0.55);
  brush.vertex(cx + w * 0.38, cy - h * 0.45);
  brush.vertex(cx + w * 0.5, cy + h * 0.25);
  brush.vertex(cx + w * 0.28, cy + h * 0.52);
  brush.vertex(cx, cy + h * 0.58);
  brush.vertex(cx - w * 0.28, cy + h * 0.52);
  brush.endShape(true);
  brush.noWash();

  // Midtone ceramic glaze curvature
  brush.set("cpencil", midCol, 1.1);
  for (let a = 195; a <= 345; a += 6) {
    const rx = (w * 0.44) * cos(a);
    const ry = (h * 0.42) * sin(a);
    brush.line(cx + rx * 0.5, cy + ry * 0.5, cx + rx, cy + ry + 3);
  }

  // Deep shadow under the bell rim
  brush.set("rotring", "#04070b", 0.95);
  brush.spline([
    [cx - w * 0.48, cy + h * 0.26, 0.7],
    [cx, cy + h * 0.54, 1.2],
    [cx + w * 0.48, cy + h * 0.26, 0.7]
  ], 0.4);

  // Warm gold-leaf mist reflection on the right/lower glaze curve
  brush.set("cpencil", goldReflCol, 0.75);
  brush.spline([
    [cx + w * 0.08, cy + h * 0.32, 0.5],
    [cx + w * 0.28, cy + h * 0.18, 1.1],
    [cx + w * 0.42, cy + h * 0.05, 0.5]
  ], 0.35);

  // Crisp glossy sky reflection across the upper-left porcelain dome
  brush.set("2H", skySpecCol, 0.85);
  brush.spline([
    [cx - w * 0.40, cy + h * 0.08, 0.5],
    [cx - w * 0.22, cy - h * 0.28, 1.2],
    [cx + w * 0.06, cy - h * 0.34, 0.6]
  ], 0.4);

  brush.set("rotring", "#e6f3ff", 0.5);
  brush.line(cx - w * 0.28, cy - h * 0.16, cx - w * 0.10, cy - h * 0.26);
}

function drawUtilityWire() {
  // 1) Slack jumper loop dropping from insulator to right edge
  const jumperPts = [
    [1125, 224],
    [1146, 295],
    [1178, 322],
    [1210, 304]
  ];
  brush.set("rotring", "#0b1118", 1.35);
  brush.spline(jumperPts, 0.5);
  brush.set("2H", "#6c8fad", 0.65);
  brush.spline(jumperPts.map(p => [p[0], p[1] - 1.5]), 0.5);

  // 2) Secondary distant parallel wire (faint, higher/behind to right edge)
  // Kept strictly confined near the insulator so the vast expanse remains pure
  brush.set("2H", "#1a314d", 0.6);
  brush.spline([
    [1127, 226],
    [1168, 208],
    [1210, 192]
  ], 0.3);

  // 3) Main Sagging Braided Steel/Aluminum Utility Cable
  const steps = 90;
  const xStart = -30;
  const xEnd = 1125;

  // Core dark shadow under-cable
  const shadowPts = [];
  const corePts = [];
  const midPts = [];
  const specPts = [];

  for (let i = 0; i <= steps; i++) {
    const x = lerp(xStart, xEnd, i / steps);
    const y = wireY(x);
    shadowPts.push([x, y + 2.4, 1.0]);
    corePts.push([x, y + 0.8, 1.1]);
    midPts.push([x, y - 0.6, 0.9]);
    specPts.push([x, y - 1.9, 0.8]);
  }

  brush.set("rotring", "#05080d", 1.5);
  brush.spline(shadowPts, 0.35);

  brush.set("HB", "#172230", 1.35);
  brush.spline(corePts, 0.35);

  brush.set("2H", "#465d75", 1.0);
  brush.spline(midPts, 0.35);

  // Sky-facing metallic specular rim
  brush.set("rotring", "#92bce3", 0.65);
  brush.spline(specPts, 0.35);

  // Individual helical wire strand notches along the entire cable for industrial precision
  for (let x = -20; x < 1122; x += 6.5) {
    const y = wireY(x);
    const ang = wireSlopeAngle(x);
    // Helical strand lay angle (~26 deg relative to wire axis)
    const strandAng = ang + 26;
    const dx = cos(strandAng) * 3.4;
    const dy = sin(strandAng) * 3.4;

    brush.set("rotring", "#070b12", 0.45);
    brush.line(x - dx, y - dy + 0.5, x + dx, y + dy + 0.5);

    // Bright specular glint on each twisted strand crown
    if (x > 520 && x < 1100 && random() < 0.55) {
      brush.set("2H", "#cce6ff", 0.4);
      brush.line(x - dx * 0.5, y - 1.8, x + dx * 0.5, y - 1.2);
    }
  }

  // Helical Armor-Rod / Tie-Wire wrapping near the insulator (x: 1035..1125)
  for (let x = 1040; x <= 1122; x += 4.2) {
    const y = wireY(x);
    const wrapH = map(x, 1040, 1122, 2.5, 5.2);
    brush.set("rotring", "#0b121c", 0.65);
    brush.line(x - 1.5, y - wrapH, x + 1.5, y + wrapH);
    brush.set("2H", "#9ec5eb", 0.55);
    brush.line(x - 0.5, y - wrapH, x + 1.2, y);
  }
}

// ============================================================================
// 4. HYPERREAL JUNGLE CROW (Corvus macrorhynchos)
// ============================================================================
function drawJungleCrow() {
  // Step A: Tarsi & Rear Toes (behind wire/body)
  drawCrowLegsBase();

  // Step B: Dense Ink-Black Base Silhouette & Charcoal Massing
  drawCrowInkMass();

  // Step C: Graduated Tail Rectrices with Malachite/Violet Edge Sheen
  drawCrowTail();

  // Step D: Breast, Belly, Flanks & Undertail Plumage
  drawCrowUnderparts();

  // Step E: Mantle, Scapulars, Wing Coverts, Secondaries & Crossed Primaries
  drawCrowWingAndBack();

  // Step F: Head, Crown, Nape & Lanceolate Throat Hackles
  drawCrowHeadAndHackles();

  // Step G: Heavy Arched Beak with Scuffs, Keratin Wear & Nasal Bristles
  drawCrowBeak();

  // Step H: Eye with Scaly Orbital Ring & Wet Corneal Highlights
  drawCrowEye();
}

function drawCrowLegsBase() {
  // Right Leg (Upper/Back foot along wire at x=854, y=wireY(854)=418.2)
  const rx = 854, ry = wireY(854);
  // Left Leg (Lower/Foreground foot along wire at x=812, y=wireY(812)=442.8)
  const lx = 812, ly = wireY(812);

  // Feathered tibial cuffs ("trousers") emerging from belly
  drawTibialCuff(862, 382, 856, 405, 16);
  drawTibialCuff(834, 392, 820, 422, 19);

  // Scaly Tarsometatarsus shafts
  drawScaledTarsus(857, 398, rx, ry - 2, 7.5);
  drawScaledTarsus(823, 415, lx, ly - 2, 8.5);

  // Hallux (rear toe) wrapping underneath the wire + curved black claw
  drawRearTalon(rx, ry);
  drawRearTalon(lx, ly);
}

function drawTibialCuff(x1, y1, x2, y2, w) {
  brush.noStroke();
  brush.wash("#06080e", 250);
  drawPoly([
    [x1 - w * 0.6, y1],
    [x1 + w * 0.6, y1],
    [x2 + w * 0.35, y2],
    [x2 - w * 0.35, y2]
  ]);
  brush.noWash();

  for (let i = 0; i < 28; i++) {
    const t = i / 28;
    const px = lerp(x1, x2, t) + random(-w * 0.45, w * 0.45) * (1 - t * 0.4);
    const py = lerp(y1, y2, t);
    const col = random() < 0.35 ? "#1f1836" : "#080b12";
    brush.set("feather_barb", col, 0.7);
    brush.line(px, py, px - 3, py + 9);
  }
}

function drawScaledTarsus(x1, y1, x2, y2, thickness) {
  const ang = atan2(y2 - y1, x2 - x1);
  const nx = cos(ang + 90) * (thickness * 0.5);
  const ny = sin(ang + 90) * (thickness * 0.5);

  brush.noStroke();
  brush.wash("#080b10", 252);
  drawPoly([
    [x1 - nx, y1 - ny],
    [x1 + nx, y1 + ny],
    [x2 + nx * 0.85, y2 + ny * 0.85],
    [x2 - nx * 0.85, y2 - ny * 0.85]
  ]);
  brush.noWash();

  // Overlapping keratin scutes (scales) down the front of the tarsus
  const nScutes = 9;
  for (let i = 0; i <= nScutes; i++) {
    const t = i / nScutes;
    const sx = lerp(x1, x2, t);
    const sy = lerp(y1, y2, t);
    brush.set("rotring", "#040609", 0.6);
    brush.line(sx - nx * 0.9, sy - ny * 0.9, sx + nx * 0.8, sy + ny * 0.8);
    // Specular ridge on each scale plate
    brush.set("2H", "#6f88a3", 0.55);
    brush.line(sx - nx * 0.75, sy - ny * 0.75 - 1, sx + nx * 0.2, sy + ny * 0.2 - 1);
  }
}

function drawRearTalon(fx, fy) {
  // Rear toe (hallux) gripping under wire toward the right-down
  brush.set("rotring", "#070a0f", 1.8);
  brush.spline([
    [fx + 1, fy + 2, 1.1],
    [fx + 10, fy + 7, 1.0],
    [fx + 16, fy + 5, 0.8]
  ], 0.4);
  // Scales on hallux
  brush.set("2H", "#5c728a", 0.5);
  brush.line(fx + 3, fy + 4, fx + 12, fy + 7);
  // Sharp curved black claw
  brush.set("rotring", "#040609", 1.1);
  brush.spline([
    [fx + 15, fy + 5, 1.0],
    [fx + 21, fy + 1, 0.7],
    [fx + 23, fy - 4, 0.3]
  ], 0.5);
  brush.set("2H", "#89a7c4", 0.4);
  brush.line(fx + 16, fy + 5, fx + 21, fy + 1);
}

function drawForegroundTalons() {
  // Drawn AFTER wire and body so the 3 anterior toes wrap convincingly over the cable
  const feet = [
    { x: 854, y: wireY(854), scale: 0.92 },
    { x: 812, y: wireY(812), scale: 1.02 }
  ];

  for (const f of feet) {
    const s = f.scale;
    // Three anterior toes (inner, middle, outer) arching over the wire
    const toeOffsets = [-5.5 * s, -0.5 * s, 4.8 * s];
    for (let tIdx = 0; tIdx < 3; tIdx++) {
      const ox = toeOffsets[tIdx];
      const tx = f.x + ox;
      const ty = f.y + ox * -0.38;

      // Dark toe pad arching over wire
      brush.noStroke();
      brush.wash("#06090e", 255);
      drawPoly([
        [tx - 3 * s, ty - 5 * s],
        [tx + 2.5 * s, ty - 5.5 * s],
        [tx - 1.5 * s, ty + 6.5 * s],
        [tx - 5.5 * s, ty + 5.5 * s]
      ]);
      brush.noWash();

      // Phalangeal scute lines & sky specular highlights on knuckles
      for (let k = 0; k < 4; k++) {
        const ky = lerp(ty - 4.5 * s, ty + 4.5 * s, k / 3.5);
        const kx = tx - k * 0.8 * s;
        brush.set("rotring", "#030508", 0.55);
        brush.line(kx - 2.6 * s, ky, kx + 2.0 * s, ky + 0.6);
        brush.set("2H", "#8ab0d6", 0.55);
        brush.line(kx - 2.2 * s, ky - 0.8, kx + 1.0 * s, ky - 0.4);
      }

      // Hooked keratin claw curving down and under the wire
      const cx = tx - 3.5 * s;
      const cy = ty + 5.5 * s;
      brush.set("rotring", "#04060a", 1.15 * s);
      brush.spline([
        [cx, cy, 1.1],
        [cx - 1.5 * s, cy + 7.5 * s, 0.8],
        [cx + 3.0 * s, cy + 12.5 * s, 0.25]
      ], 0.45);
      // Specular gleam along the dorsal curve of the claw
      brush.set("2H", "#9ec2e6", 0.45);
      brush.spline([
        [cx - 0.8 * s, cy + 0.5, 0.8],
        [cx - 2.0 * s, cy + 6.8 * s, 0.6],
        [cx + 1.5 * s, cy + 11.2 * s, 0.2]
      ], 0.45);
    }
  }
}

function drawCrowInkMass() {
  // Main anatomical silhouette of the Jungle Crow in dense ink-black wash + charcoal mass
  const bodyPoly = [
    [740, 188], // forehead base
    [762, 171], // steep forehead
    [786, 165], // crown peak
    [814, 174], // rear crown
    [836, 202], // nape
    [860, 238], // upper mantle
    [896, 294], // scapulars
    [926, 366], // wing edge
    [958, 486], // primary tips
    [932, 488], // primary inner web
    [992, 614], // outer right tail tip
    [942, 628], // lower left tail tip
    [872, 430], // undertail base
    [840, 412], // vent
    [792, 398], // belly
    [754, 368], // lower breast
    [732, 314], // full chest
    [734, 258], // shaggy throat hackles
    [742, 227]  // chin
  ];

  // Pass 1: Solid opaque ink-black wash
  brush.noStroke();
  brush.wash("#05070c", 255);
  drawPoly(bodyPoly);
  brush.noWash();

  // Pass 2: Dense dry-pigment charcoal massing for velvet light-absorbing depth
  brush.mass("charcoal", "#070a12", {
    precision: 0.82,
    strength: 0.85,
    gradient: 0.25,
    outline: false
  });
  drawPoly([
    [748, 176],
    [825, 192],
    [892, 292],
    [928, 425],
    [855, 415],
    [762, 375],
    [736, 295],
    [742, 225]
  ]);
  brush.noMass();
}

function drawCrowTail() {
  // Graduated tail rectrices extending from (870, 418)..(914, 408) down to (942, 628)..(992, 614)
  const numRectrices = 7;
  for (let i = 0; i < numRectrices; i++) {
    const t = i / (numRectrices - 1);
    const xBase = lerp(872, 910, t);
    const yBase = lerp(424, 406, t);
    // Graduated lengths: central feathers longest, outer slightly shorter
    const lenFactor = 1.0 - abs(t - 0.45) * 0.16;
    const xTip = lerp(942, 990, t) - (1 - lenFactor) * 18;
    const yTip = lerp(626, 610, t) - (1 - lenFactor) * 32;

    drawFlightFeather(xBase, yBase, xTip, yTip, 16, t > 0.5 ? "malachite" : "violet", t === numRectrices - 1);
  }
}

function drawCrowUnderparts() {
  // Breast, Belly, Flanks & Undertail Coverts
  // Sculpted as a 3D rounded volume facing left-up toward the azurite sky
  const rows = 22;
  for (let r = rows - 1; r >= 0; r--) {
    const ty = r / (rows - 1); // 0 = upper breast (y=258), 1 = vent/undertail (y=420)
    const yCenter = lerp(258, 418, ty);

    // Left contour (chest curve) & Right boundary (under wing)
    const xLeft = chestLeftContour(ty);
    const xRight = lerp(795, 875, ty);
    const cols = floor(map(xRight - xLeft, 50, 120, 9, 17));

    for (let c = 0; c < cols; c++) {
      const tx = c / max(1, cols - 1);
      const fx = lerp(xLeft, xRight, tx) + random(-2.5, 2.5);
      const fy = yCenter + sin(tx * 180) * 6 + random(-2.5, 2.5);

      // Feather direction follows body flow down-right
      const flowAngle = lerp(88, 52, tx) + (ty - 0.4) * 18;
      const fLen = lerp(18, 28, ty) * (0.85 + 0.3 * sin(tx * 180));
      const fWid = lerp(9, 14, ty);

      // Compute iridescent sheen based on 3D cylinder normal
      // Left edge (tx < 0.22): sky rim light; Upper-mid (tx 0.2..0.65, ty < 0.65): Oil-slick Violet & Malachite; Lower belly: Ink black
      let sheenType = "ink";
      let sheenIntensity = 0.2;
      if (tx < 0.16) {
        sheenType = "sky_rim";
        sheenIntensity = map(tx, 0, 0.16, 0.95, 0.35);
      } else if (ty < 0.72 && tx < 0.78) {
        const nVal = noise(fx * 0.025, fy * 0.025);
        sheenType = nVal > 0.46 ? "violet" : "malachite";
        sheenIntensity = sin(tx * 180) * (1 - ty * 0.65) * 0.92;
      }

      drawContourFeather(fx, fy, fLen, fWid, flowAngle, sheenType, sheenIntensity);
    }
  }
}

function chestLeftContour(ty) {
  // Smooth anatomical curve from throat (734, 258) -> chest (731, 315) -> belly (790, 398) -> vent (855, 420)
  if (ty < 0.35) {
    return lerp(735, 730, sin((ty / 0.35) * 90));
  } else {
    const u = (ty - 0.35) / 0.65;
    return lerp(730, 852, pow(u, 1.55));
  }
}

function drawCrowWingAndBack() {
  // 1) Upper Mantle & Scapulars (flowing down the back from nape to upper wing)
  // Rich Malachite Green & Emerald-Teal iridescence + Gold-Leaf mist reflection on back edge
  const mantleRows = 16;
  for (let r = mantleRows - 1; r >= 0; r--) {
    const ty = r / (mantleRows - 1);
    const y = lerp(205, 335, ty);
    const xStart = lerp(802, 825, ty);
    const xEnd = lerp(838, 906, ty);
    const cols = 10;

    for (let c = 0; c < cols; c++) {
      const tx = c / (cols - 1);
      const fx = lerp(xStart, xEnd, tx) + random(-2, 2);
      const fy = y + tx * 12 + random(-2, 2);
      const ang = lerp(62, 54, tx);
      const fLen = lerp(19, 32, ty);
      const fWid = lerp(10, 15, ty);

      let sheen = "malachite";
      let inten = sin(tx * 165) * 0.95;
      if (tx > 0.84) {
        sheen = "gold_rim";
        inten = 0.78;
      } else if (tx > 0.35 && tx < 0.7 && ty > 0.45 && noise(fx * 0.03, fy * 0.03) > 0.52) {
        sheen = "violet";
      }
      drawContourFeather(fx, fy, fLen, fWid, ang, sheen, inten);
    }
  }

  // 2) Wing Bow & Lesser Coverts (x: 785..855, y: 255..315)
  for (let r = 8; r >= 0; r--) {
    const ty = r / 8;
    for (let c = 0; c < 9; c++) {
      const tx = c / 8;
      const fx = lerp(786, 852, tx) + ty * 14 + random(-1.8, 1.8);
      const fy = lerp(252, 305, ty) + tx * 16 + random(-1.8, 1.8);
      const ang = lerp(68, 56, tx);
      const sheen = (tx + ty * 0.5 < 0.65) ? "malachite" : "violet";
      const inten = 0.45 + 0.5 * sin(tx * 180);
      drawContourFeather(fx, fy, 20, 11, ang, sheen, inten);
    }
  }

  // 3) Median Coverts (Distinct imbricated tier with bold Violet & Malachite oil-slick bands)
  const numMedian = 11;
  for (let i = 0; i < numMedian; i++) {
    const t = i / (numMedian - 1);
    const fx = lerp(796, 876, t);
    const fy = lerp(302, 336, t);
    const ang = lerp(65, 55, t);
    const sheen = t < 0.45 ? "violet" : "malachite";
    drawCovertFeather(fx, fy, 34, 15, ang, sheen, 0.92);
  }

  // 4) Greater Coverts (Long structured feathers with sharp dark overlap & intense Violet/Green sheen)
  const numGreater = 12;
  for (let i = 0; i < numGreater; i++) {
    const t = i / (numGreater - 1);
    const fx = lerp(808, 896, t);
    const fy = lerp(332, 368, t);
    const ang = lerp(62, 53, t);
    const sheen = (i % 3 === 0) ? "malachite" : "violet";
    drawCovertFeather(fx, fy, 44, 16, ang, sheen, 0.95);
  }

  // 5) Primary Remiges (Long stiff flight feathers tapering down to crossed tips at 958, 488)
  const numPrimaries = 8;
  for (let i = 0; i < numPrimaries; i++) {
    const t = i / (numPrimaries - 1);
    const xBase = lerp(848, 898, t);
    const yBase = lerp(375, 392, t);
    const xTip = lerp(918, 958, t);
    const yTip = lerp(452, 488, t);
    drawFlightFeather(xBase, yBase, xTip, yTip, 13, t > 0.4 ? "malachite" : "violet", i === numPrimaries - 1);
  }

  // 6) Tertials & Secondaries overlapping the upper primaries (rich royal violet & emerald gloss)
  const numSecondaries = 7;
  for (let i = 0; i < numSecondaries; i++) {
    const t = i / (numSecondaries - 1);
    const xBase = lerp(820, 882, t);
    const yBase = lerp(358, 376, t);
    const xTip = lerp(872, 932, t);
    const yTip = lerp(418, 442, t);
    drawFlightFeather(xBase, yBase, xTip, yTip, 16, t < 0.55 ? "violet" : "malachite", i === numSecondaries - 1);
  }
}

function drawCrowHeadAndHackles() {
  // 1) Shaggy Lanceolate Throat Hackles (signature feature of the Jungle Crow!)
  // Pointed, individually separated lance-shaped feathers on throat & upper neck (x: 734..805, y: 222..276)
  for (let r = 7; r >= 0; r--) {
    const ty = r / 7;
    const y = lerp(224, 272, ty);
    const xLeft = lerp(742, 734, sin(ty * 150));
    const xRight = lerp(788, 808, ty);
    const cols = 8;

    for (let c = 0; c < cols; c++) {
      const tx = c / (cols - 1);
      const hx = lerp(xLeft, xRight, tx) + random(-1.5, 1.5);
      const hy = y + tx * 8 + random(-1.5, 1.5);
      const ang = lerp(102, 66, tx);
      const len = lerp(15, 24, ty);
      const sheen = (tx < 0.2) ? "sky_rim" : ((c + r) % 2 === 0 ? "violet" : "malachite");
      const inten = tx < 0.2 ? 0.85 : (0.5 + 0.48 * sin(tx * 180));
      drawHackleFeather(hx, hy, len, 7.5, ang, sheen, inten);
    }
  }

  // 2) Crown, Steep Forehead, Ear Coverts (Auriculars) & Nape
  // Fine, dense, velvety micro-feathers radiating backward over the skull dome
  const headLayers = 24;
  for (let r = headLayers - 1; r >= 0; r--) {
    const ty = r / (headLayers - 1); // 0 = crown top (y=166), 1 = lower cheek/nape (y=224)
    const y = lerp(166, 224, ty);

    // Forehead/lore left edge vs rear crown/nape right edge
    const xLeft = ty < 0.38
      ? lerp(780, 740, pow(ty / 0.38, 0.75))
      : lerp(740, 744, (ty - 0.38) / 0.62);
    const xRight = lerp(796, 838, pow(ty, 0.8));

    const cols = floor(map(xRight - xLeft, 16, 94, 6, 16));
    for (let c = 0; c < cols; c++) {
      const tx = c / max(1, cols - 1);
      const fx = lerp(xLeft, xRight, tx) + random(-1.2, 1.2);
      const fy = y + sin(tx * 180) * -4 + random(-1.2, 1.2);

      // Skip the immediate eye socket so we don't overwrite the orbital ring later
      if (dist(fx, fy, 764, 198) < 9.5) continue;

      // Feather angle sweeps from forehead over crown down the nape
      const crownArch = map(ty, 0, 1, 8, 52) + map(tx, 0, 1, -18, 28);
      const fLen = lerp(10, 16, ty);
      const fWid = lerp(5.5, 8.5, ty);

      // Crown & Nape have intense Malachite Green & Cyan-Emerald sheen; Cheek has deep Violet sheen
      let sheen = "malachite";
      let inten = 0.75;
      if (ty < 0.22 || (tx < 0.22 && ty < 0.45)) {
        sheen = "sky_rim";
        inten = 0.92;
      } else if (tx > 0.85) {
        sheen = "gold_rim";
        inten = 0.72;
      } else if (ty > 0.48 && tx < 0.65) {
        sheen = "violet";
        inten = 0.78;
      } else {
        sheen = "malachite";
        inten = 0.65 + 0.35 * sin(tx * 180);
      }

      drawContourFeather(fx, fy, fLen, fWid, crownArch, sheen, inten);
    }
  }

  // Auricular (ear covert) fine hair-like barb sweep behind & below the eye
  for (let i = 0; i < 65; i++) {
    const ax = random(768, 804);
    const ay = random(198, 222);
    const ang = random(18, 36);
    const col = random() < 0.45 ? "#4a2878" : (random() < 0.5 ? "#165947" : "#070a10");
    brush.set("feather_barb", col, 0.55);
    brush.line(ax, ay, ax + cos(ang) * 11, ay + sin(ang) * 11);
  }
}

// ============================================================================
// FEATHER RENDERING PRIMITIVES (Layered Pencil over Dense Ink-Black Mass)
// ============================================================================
function getIridescentPalette(sheenType) {
  if (sheenType === "malachite") {
    return {
      shadow: "#04080a",
      dark: "#0a241e",
      mid: "#134d3c",
      bright: "#228264",
      spec: "#4ec99e",
      glint: "#8ef2cc"
    };
  } else if (sheenType === "violet") {
    return {
      shadow: "#06050c",
      dark: "#1b1030",
      mid: "#381f63",
      bright: "#6136a3",
      spec: "#9362db",
      glint: "#c49eff"
    };
  } else if (sheenType === "sky_rim") {
    return {
      shadow: "#050912",
      dark: "#0f223d",
      mid: "#1e4778",
      bright: "#4482c4",
      spec: "#82bcf5",
      glint: "#cce6ff"
    };
  } else if (sheenType === "gold_rim") {
    return {
      shadow: "#08080a",
      dark: "#211c12",
      mid: "#4a3d22",
      bright: "#826b39",
      spec: "#ba9b54",
      glint: "#e3c77d"
    };
  } else {
    // Deep ink-black shadow plumage
    return {
      shadow: "#030408",
      dark: "#070a12",
      mid: "#0e1524",
      bright: "#182338",
      spec: "#273854",
      glint: "#3d5478"
    };
  }
}

function drawContourFeather(x, y, len, wid, angle, sheenType, intensity) {
  const pal = getIridescentPalette(sheenType);
  const ca = cos(angle);
  const sa = sin(angle);
  const nx = -sa;
  const ny = ca;

  // 1) Dark base separation stroke so overlapping feather tips read crisply
  brush.set("HB", pal.shadow, 0.95);
  brush.line(
    x + ca * len * 0.2 - nx * wid * 0.45,
    y + sa * len * 0.2 - ny * wid * 0.45,
    x + ca * len * 0.95,
    y + sa * len * 0.95
  );

  // 2) Fine radiating barbs from central rachis
  const nBarbs = 7;
  for (let i = 0; i < nBarbs; i++) {
    const t = i / (nBarbs - 1); // 0 = base, 1 = tip
    const rx = x + ca * (len * t * 0.82);
    const ry = y + sa * (len * t * 0.82);
    const spread = sin(t * 165) * wid * 0.52;
    const barbReach = len * (0.28 + 0.14 * (1 - t));

    // Upper/outer vane barb
    const ux = rx + ca * barbReach - nx * spread;
    const uy = ry + sa * barbReach - ny * spread;
    // Lower/inner vane barb
    const lx = rx + ca * barbReach + nx * spread;
    const ly = ry + sa * barbReach + ny * spread;

    // Choose tone based on position along feather (iridescence concentrates on outer/distal third)
    let colU = pal.dark;
    let colL = pal.shadow;
    if (t > 0.35 && intensity > 0.25) {
      colU = t > 0.68 ? (intensity > 0.72 ? pal.spec : pal.bright) : pal.mid;
      colL = t > 0.72 ? pal.mid : pal.dark;
    }

    brush.set("feather_barb", colL, 0.55);
    brush.line(rx, ry, lx, ly);

    brush.set("feather_barb", colU, 0.62);
    brush.line(rx, ry, ux, uy);
  }

  // 3) High-key oil-slick specular glint on distal barb tips
  if (intensity > 0.58) {
    brush.set("2H", intensity > 0.84 ? pal.glint : pal.spec, 0.48);
    const tx = x + ca * (len * 0.72);
    const ty = y + sa * (len * 0.72);
    brush.line(tx - nx * wid * 0.28, ty - ny * wid * 0.28, x + ca * len, y + sa * len - ny * wid * 0.12);
  }
}

function drawHackleFeather(x, y, len, wid, angle, sheenType, intensity) {
  // Pointed lance-shaped throat hackle with glossy central ridge
  const pal = getIridescentPalette(sheenType);
  const ca = cos(angle);
  const sa = sin(angle);
  const nx = -sa;
  const ny = ca;

  // Deep shadow notch around the pointed tip
  brush.set("rotring", "#030509", 0.75);
  brush.line(x + ca * len * 0.4 - nx * wid * 0.5, y + sa * len * 0.4 - ny * wid * 0.5, x + ca * len * 1.05, y + sa * len * 1.05);
  brush.line(x + ca * len * 0.4 + nx * wid * 0.5, y + sa * len * 0.4 + ny * wid * 0.5, x + ca * len * 1.05, y + sa * len * 1.05);

  // Tightly appressed lanceolate barbs
  for (let i = -3; i <= 3; i++) {
    const frac = i / 3;
    const col = abs(frac) < 0.45
      ? (intensity > 0.65 ? pal.spec : pal.bright)
      : (frac < 0 ? pal.mid : pal.dark);
    brush.set("feather_barb", col, 0.58);
    brush.line(
      x + nx * frac * wid * 0.35,
      y + ny * frac * wid * 0.35,
      x + ca * len + nx * frac * wid * 0.08,
      y + sa * len + ny * frac * wid * 0.08
    );
  }

  if (intensity > 0.6) {
    brush.set("2H", pal.glint, 0.45);
    brush.line(x + ca * len * 0.45, y + sa * len * 0.45, x + ca * len * 0.95, y + sa * len * 0.95);
  }
}

function drawCovertFeather(x, y, len, wid, angle, sheenType, intensity) {
  const pal = getIridescentPalette(sheenType);
  const ca = cos(angle);
  const sa = sin(angle);
  const nx = -sa;
  const ny = ca;

  const tipX = x + ca * len;
  const tipY = y + sa * len;

  // Opaque ink-black covert base pad
  brush.noStroke();
  brush.wash("#05070d", 245);
  drawPoly([
    [x - nx * wid * 0.45, y - ny * wid * 0.45],
    [x + nx * wid * 0.45, y + ny * wid * 0.45],
    [tipX + nx * wid * 0.32, tipY + ny * wid * 0.32],
    [tipX, tipY + sa * 4],
    [tipX - nx * wid * 0.32, tipY - ny * wid * 0.32]
  ]);
  brush.noWash();

  // Dense parallel barbules in layered colored pencil & custom barb brush
  const steps = 14;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const rx = lerp(x, tipX, t * 0.88);
    const ry = lerp(y, tipY, t * 0.88);
    const wLocal = wid * (0.48 - 0.14 * t);

    // Inner/lower web (darker, violet-indigo shadow)
    brush.set("feather_barb", t > 0.6 ? pal.mid : pal.dark, 0.62);
    brush.line(rx, ry, rx + ca * 10 + nx * wLocal, ry + sa * 10 + ny * wLocal);

    // Outer/upper web (intense iridescent oil-slick sheen)
    const outerCol = t < 0.3 ? pal.dark : (t < 0.65 ? pal.mid : (t < 0.88 ? pal.bright : pal.spec));
    brush.set("feather_barb", outerCol, 0.68);
    brush.line(rx, ry, rx + ca * 10 - nx * wLocal, ry + sa * 10 - ny * wLocal);
  }

  // Shimmering iridescent sub-terminal band & crisp dark margin
  brush.set("cpencil", pal.spec, 0.72 * intensity);
  brush.line(
    tipX - ca * 7 - nx * wid * 0.36,
    tipY - sa * 7 - ny * wid * 0.36,
    tipX - ca * 2 + nx * wid * 0.15,
    tipY - sa * 2 + ny * wid * 0.15
  );

  brush.set("2H", pal.glint, 0.48);
  brush.line(
    tipX - ca * 5 - nx * wid * 0.25,
    tipY - sa * 5 - ny * wid * 0.25,
    tipX - ca * 2,
    tipY - sa * 2
  );

  // Central rachis shaft
  brush.set("rotring", "#04060a", 0.55);
  brush.line(x, y, tipX, tipY);
}

function drawFlightFeather(x1, y1, x2, y2, wid, sheenType, isOuterEdge) {
  const pal = getIridescentPalette(sheenType);
  const ang = atan2(y2 - y1, x2 - x1);
  const len = dist(x1, y1, x2, y2);
  const ca = cos(ang);
  const sa = sin(ang);
  const nx = -sa;
  const ny = ca;

  // Opaque ink-black vane silhouette
  brush.noStroke();
  brush.wash("#04060b", 252);
  drawPoly([
    [x1 - nx * wid * 0.35, y1 - ny * wid * 0.35],
    [x1 + nx * wid * 0.55, y1 + ny * wid * 0.55],
    [x2 + nx * wid * 0.28 - ca * 8, y2 + ny * wid * 0.28 - sa * 8],
    [x2, y2],
    [x2 - nx * wid * 0.22 - ca * 6, y2 - ny * wid * 0.22 - sa * 6]
  ]);
  brush.noWash();

  // Barb striations along the entire flight feather
  const nBarbs = floor(len / 3.2);
  for (let i = 0; i <= nBarbs; i++) {
    const t = i / nBarbs;
    const rx = lerp(x1, x2, t * 0.95);
    const ry = lerp(y1, y2, t * 0.95);
    const taper = sin(pow(t, 0.65) * 172);
    const wOut = wid * 0.38 * taper;
    const wIn = wid * 0.58 * taper;

    // Inner web (left/lower side): velvet coal black with subtle violet-blue cast
    brush.set("feather_barb", t > 0.7 ? pal.dark : "#070a12", 0.58);
    brush.line(rx, ry, rx + ca * 8 + nx * wIn, ry + sa * 8 + ny * wIn);

    // Outer web (right/upper side): metallic malachite/violet oil-slick gloss
    const outerCol = t < 0.25 ? pal.dark : (t < 0.68 ? pal.mid : pal.bright);
    brush.set("feather_barb", outerCol, 0.62);
    brush.line(rx, ry, rx + ca * 9 - nx * wOut, ry + sa * 9 - ny * wOut);

    if (t > 0.35 && t < 0.9 && i % 2 === 0) {
      brush.set("2H", pal.spec, 0.45);
      brush.line(rx - nx * wOut * 0.4, ry - ny * wOut * 0.4, rx + ca * 7 - nx * wOut * 0.9, ry + sa * 7 - ny * wOut * 0.9);
    }
  }

  // If outer edge facing the tarnished gold mist, add warm gold-leaf rim reflection
  if (isOuterEdge) {
    brush.set("2H", "#c4a456", 0.55);
    brush.line(
      lerp(x1, x2, 0.25) - nx * wid * 0.34,
      lerp(y1, y2, 0.25) - ny * wid * 0.34,
      lerp(x1, x2, 0.88) - nx * wid * 0.22,
      lerp(y1, y2, 0.88) - ny * wid * 0.22
    );
  }

  // Stiff dark glossy rachis shaft with fine specular highlight line
  brush.set("rotring", "#020306", 0.75);
  brush.line(x1, y1, x2, y2);
  brush.set("2H", "#465c75", 0.4);
  brush.line(x1 + 0.6, y1, x2 + 0.4, y2);
}

// ============================================================================
// 5. HEAVY ARCHED BEAK WITH SCUFFS & NASAL BRISTLES
// ============================================================================
function drawCrowBeak() {
  // Upper Mandible (Culmen arches boldly from forehead 740,188 to hooked tip 650,217)
  const upperBeak = [
    [740, 188],
    [714, 187],
    [688, 193],
    [666, 203],
    [650, 217], // sharp hooked tip
    [662, 216],
    [696, 216], // tomium (cutting edge)
    [744, 218]  // gape
  ];

  // Lower Mandible (from tip 653,217 along sturdy gonys 688,229 to chin 742,227)
  const lowerBeak = [
    [653, 217],
    [696, 216],
    [744, 218],
    [742, 227],
    [710, 229],
    [684, 228],
    [664, 223]
  ];

  // 1) Opaque horn-black base washes
  brush.noStroke();
  brush.wash("#080b11", 255);
  drawPoly(upperBeak);
  brush.wash("#05070b", 255);
  drawPoly(lowerBeak);
  brush.noWash();

  // 2) Longitudinal keratin shading & twilight sky reflection along the arched culmen
  for (let i = 0; i < 24; i++) {
    const t = i / 23; // 0 = top ridge, 1 = tomium
    const p1 = [lerp(740, 742, t), lerp(188, 217, t), 0.7];
    const p2 = [lerp(696, 696, t), lerp(191, 216, t), 1.1];
    const p3 = [lerp(650, 653, t), lerp(217, 217, t), 0.5];

    let col = "#101722";
    if (t < 0.14) col = "#8ab8e6";       // crisp top culmen sky highlight
    else if (t < 0.32) col = "#43658a";  // upper keratin sheen
    else if (t < 0.55) col = "#1d2a3b";  // mid lateral horn
    else if (t > 0.86) col = "#4c5b6e";  // worn cutting edge (tomium)

    brush.set(t < 0.25 ? "2H" : "cpencil", col, 0.65);
    brush.spline([p1, p2, p3], 0.45);
  }

  // Lower mandible shading & warm reflected gold-mist glint along the gonys ridge
  for (let i = 0; i < 12; i++) {
    const t = i / 11;
    const p1 = [742, lerp(218, 227, t), 0.7];
    const p2 = [692, lerp(217, 228, t), 1.0];
    const p3 = [654, lerp(217, 220, t), 0.5];
    const col = t > 0.75 ? "#5c5749" : (t < 0.25 ? "#2e3d4f" : "#0b0f17");
    brush.set("cpencil", col, 0.6);
    brush.spline([p1, p2, p3], 0.4);
  }

  // 3) Commissure (mouth line) deep shadow & pale tomium rim
  brush.set("rotring", "#020305", 1.15);
  brush.spline([
    [651, 217, 0.8],
    [696, 216, 1.2],
    [745, 218, 0.9]
  ], 0.35);

  brush.set("2H", "#778da6", 0.5);
  brush.spline([
    [653, 216, 0.7],
    [696, 215, 1.0],
    [734, 217, 0.6]
  ], 0.35);

  // 4) HYPERREAL BEAK SCUFFS, FORAGING SCRATCHES & KERATIN FLAKING
  // Fine diagonal scratches, nicks near the tip, and worn keratin layers
  const scuffData = [
    [666, 207, 675, 213, "#9bb4cc", 0.55],
    [672, 203, 683, 211, "#7b93ab", 0.50],
    [681, 198, 694, 205, "#8da8c4", 0.45],
    [689, 206, 698, 214, "#a9c2db", 0.52],
    [702, 199, 712, 208, "#6b8299", 0.48],
    [676, 211, 691, 213, "#8aa2ba", 0.45],
    [660, 212, 671, 215, "#b5cee6", 0.55],
    [678, 220, 690, 225, "#74889e", 0.48],
    [694, 221, 706, 226, "#627487", 0.45],
    [668, 205, 674, 214, "#06090e", 0.50], // dark gouge next to bright scratch
    [688, 205, 697, 213, "#06090e", 0.50]
  ];
  for (const s of scuffData) {
    brush.set("2H", s[4], s[5]);
    brush.line(s[0], s[1], s[2], s[3]);
  }

  // Flaky keratin growth lines near the tip & nostril
  brush.set("2H", "#637a91", 0.42);
  for (let i = 0; i < 9; i++) {
    const kx = 658 + i * 4.2;
    const ky = lerp(212, 196, i / 9);
    brush.line(kx, ky, kx - 3.5, ky + 6.5);
  }

  // 5) Stiff Forward-Directed Nasal & Rictal Bristles covering the base of the bill
  // Sweeping from forehead/lore (736..745, 190..216) forward over the nostril to (704, 205)
  for (let i = 0; i < 52; i++) {
    const t = i / 51;
    const bx = lerp(738, 744, t) + random(-2, 2);
    const by = lerp(189, 217, t) + random(-1, 1);
    const bLen = lerp(28, 36, sin(t * 165)) + random(-4, 4);
    const bAng = lerp(196, 174, t) + random(-4, 4);

    const isHighlight = i % 4 === 0;
    brush.set(
      isHighlight ? "2H" : "feather_barb",
      isHighlight ? "#4d6782" : "#04060a",
      isHighlight ? 0.45 : 0.72
    );
    brush.line(bx, by, bx + cos(bAng) * bLen, by + sin(bAng) * bLen);
  }
}

// ============================================================================
// 6. HYPERREAL EYE WITH SCALY ORBITAL RING & WET HIGHLIGHT
// ============================================================================
function drawCrowEye() {
  const ex = 764, ey = 198, r = 8.4;

  // 1) Recessed dark eye socket shadow
  brush.noStroke();
  brush.wash("#020305", 255);
  drawEllipsePoly(ex, ey, (r + 3.2) * 2, (r + 2.6) * 2, 20);

  // 2) Scaly grey-black orbital skin ring (eyelid papillae)
  const nPapillae = 26;
  for (let i = 0; i < nPapillae; i++) {
    const a = (i / nPapillae) * 360;
    const px = ex + cos(a) * (r + 1.5);
    const py = ey + sin(a) * (r + 1.1);
    const isLit = a > 190 && a < 330;
    brush.set("rotring", "#06080d", 0.85);
    brush.circle(px, py, 1.3, 0.1);
    if (isLit || (a > 20 && a < 150)) {
      brush.set("2H", isLit ? "#6d849e" : "#4b5a6b", 0.48);
      brush.line(px - 0.6, py - 0.4, px + 0.6, py - 0.2);
    }
  }

  // 3) Deep dark brown-black iris & jet-black pupil
  brush.noStroke();
  brush.wash("#1c120d", 255);
  drawEllipsePoly(ex, ey, r * 1.9, r * 1.82, 20);

  // Warm coffee-umber iris fibers on the lower-right side opposite the light
  brush.set("2H", "#3b261b", 0.5);
  for (let a = -25; a <= 135; a += 14) {
    brush.line(
      ex + cos(a) * (r * 0.45),
      ey + sin(a) * (r * 0.45),
      ex + cos(a) * (r * 0.86),
      ey + sin(a) * (r * 0.82)
    );
  }

  // Central dilated pupil
  brush.noStroke();
  brush.wash("#030406", 255);
  drawEllipsePoly(ex - 0.4, ey - 0.2, r * 1.15, r * 1.12, 16);
  brush.noWash();

  // 4) WET CORNEAL HIGHLIGHTS
