function drawPoly(pts) {
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawEllipsePoly(cx, cy, w, h, steps) {
  brush.beginShape(0.2);
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * 360;
    brush.vertex(cx + cos(a) * (w * 0.5), cy + sin(a) * (h * 0.5));
  }
  brush.endShape(true);
}

