function smin(a, b, k) {
  let h = Math.max(k - Math.abs(a - b), 0.0) / k;
  return Math.min(a, b) - h * h * k * 0.25;
}

function smax(a, b, k) {
  return -smin(-a, -b, k);
}

function distToSegment(px, py, x1, y1, x2, y2) {
  let vx = x2 - x1;
  let vy = y2 - y1;
  let l2 = vx * vx + vy * vy;
  let t = l2 > 0 ? ((px - x1) * vx + (py - y1) * vy) / l2 : 0;
  t = Math.max(0, Math.min(1, t));
  let projX = x1 + t * vx;
  let projY = y1 + t * vy;
  let d = Math.hypot(px - projX, py - projY);
  return { d, t, projX, projY };
}

function evalEllipticalDome(px, py, cx, cy, rx, ry, angleDeg, amp) {
  let rad = angleDeg * Math.PI / 180;
  let cosA = Math.cos(rad);
  let sinA = Math.sin(rad);
  let dx = px - cx;
  let dy = py - cy;
  let lx = dx * cosA + dy * sinA;
  let ly = -dx * sinA + dy * cosA;
  let u2 = (lx * lx) / (rx * rx) + (ly * ly) / (ry * ry);
  if (u2 >= 1.0) return 0.0;
  let falloff = 1.0 - u2;
  return amp * falloff * falloff;
}

function evalPolylineCrease(px, py, pts, depth, wNarrow, wWide) {
  let minD = 1e9;
  let bestT = 0;
  let nSegs = pts.length - 1;
  for (let i = 0; i < nSegs; i++) {
    let res = distToSegment(px, py, pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    if (res.d < minD) {
      minD = res.d;
      bestT = (i + res.t) / nSegs;
    }
  }
  if (minD > wWide * 2.6) return 0.0;
  // Taper cleanly at crease tips
  let taper = Math.sin(Math.PI * Math.max(0.02, Math.min(0.98, bestT)));
  taper = Math.pow(taper, 0.55);
  let cNarrow = Math.exp(-(minD * minD) / (wNarrow * wNarrow));
  let cWide = Math.exp(-(minD * minD) / (wWide * wWide));
  return depth * taper * (0.72 * cNarrow + 0.28 * cWide);
}

function evalHandPoint(px, py) {
  // 1. Evaluate Palm Base Volume (smooth union of metacarpal & wrist capsules)
  let palmH = -0.2;
  for (let i = 0; i < PALM_CAPSULES.length; i++) {
    let c = PALM_CAPSULES[i];
    let res = distToSegment(px, py, c.x1, c.y1, c.x2, c.y2);
    let r = c.r1 + (c.r2 - c.r1) * res.t;
    let hPeak = c.h1 + (c.h2 - c.h1) * res.t;
    let u = res.d / r;
    let val = u < 1.15 ? hPeak * (1.0 - Math.pow(u, 1.85)) : -0.2;
    palmH = smax(palmH, val, 0.14);
  }

  // 2. Evaluate 5 Digits (each digit is an independent chain so fingers stay separated)
  let bestDigitH = -0.2;
  for (let d = 0; d < DIGITS.length; d++) {
    let dig = DIGITS[d];
    let digH = -0.2;
    for (let s = 0; s < 3; s++) {
      let p1 = dig.pts[s];
      let p2 = dig.pts[s + 1];
      let r1 = dig.rads[s];
      let r2 = dig.rads[s + 1];
      let h1 = dig.heights[s];
      let h2 = dig.heights[s + 1];
      let res = distToSegment(px, py, p1[0], p1[1], p2[0], p2[1]);
      // Subtle phalanx belly swell in middle of segment
      let bellyR = 1.0 + 0.055 * Math.sin(Math.PI * res.t);
      let r = (r1 + (r2 - r1) * res.t) * bellyR;
      let hPeak = h1 + (h2 - h1) * res.t + 0.045 * Math.sin(Math.PI * res.t);
      let u = res.d / r;
      let val = u < 1.12 ? hPeak * (1.0 - Math.pow(u, 1.82)) : -0.2;
      digH = smax(digH, val, 0.07);
    }
    // Add apical fingertip pad dome
    let pad = dig.pad;
    let padBoost = evalEllipticalDome(px, py, pad.x, pad.y, pad.rx, pad.ry, pad.angle, pad.amp);
    if (digH > 0.01) {
      digH += padBoost * Math.min(1.0, digH * 3.5);
    }
    if (digH > bestDigitH) bestDigitH = digH;
  }

  // Smooth union of digits with palm at MCP knuckles
  let baseH = smax(palmH, bestDigitH, 0.085);
  if (baseH <= 0.0) {
    return { h: 0.0, crease: 0.0 };
  }

  // Smooth boundary envelope so interior mounds fade cleanly to 0 at silhouette edge
  let edgeMask = Math.min(1.0, baseH / 0.22);
  edgeMask = edgeMask * edgeMask * (3.0 - 2.0 * edgeMask);

  let h = baseH;

  // 3. Sculpt Palmar Mounds & Central Hollow
  // Thenar Eminence (prominent thumb mound)
  h += edgeMask * evalEllipticalDome(px, py, 456, 808, 102, 158, -32, 0.36);
  h += edgeMask * evalEllipticalDome(px, py, 434, 774, 58, 86, -28, 0.11);

  // Hypothenar Eminence (ulnar mound)
  h += edgeMask * evalEllipticalDome(px, py, 734, 838, 72, 148, 16, 0.25);
  h += edgeMask * evalEllipticalDome(px, py, 766, 702, 62, 108, 10, 0.18);

  // Central Palmar Hollow (cup of the palm)
  h -= edgeMask * evalEllipticalDome(px, py, 582, 726, 114, 102, -8, 0.19);

  // Four Distal Metacarpal Mounts
  h += edgeMask * evalEllipticalDome(px, py, 464, 566, 52, 46, -15, 0.16);
  h += edgeMask * evalEllipticalDome(px, py, 568, 542, 54, 46, -2, 0.15);
  h += edgeMask * evalEllipticalDome(px, py, 672, 564, 52, 46, 12, 0.17);
  h += edgeMask * evalEllipticalDome(px, py, 770, 622, 48, 42, 24, 0.15);

  // Interdigital valleys between mounts
  h -= edgeMask * evalEllipticalDome(px, py, 514, 535, 22, 48, -8, 0.07);
  h -= edgeMask * evalEllipticalDome(px, py, 622, 532, 22, 48, 4, 0.07);
  h -= edgeMask * evalEllipticalDome(px, py, 726, 574, 22, 46, 16, 0.07);

  // Wrist Tendons (palmaris longus & flexor carpi radialis)
  let t1 = distToSegment(px, py, 642, 1190, 610, 995);
  if (t1.d < 28) h += edgeMask * 0.055 * Math.pow(1.0 - t1.d / 28, 2);
  let t2 = distToSegment(px, py, 604, 1190, 578, 995);
  if (t2.d < 26) h += edgeMask * 0.050 * Math.pow(1.0 - t2.d / 26, 2);

  // 4. Hyperreal Callus on Ring Finger Mount (steep-rimmed plaque with dimpled center)
  let calDome = evalEllipticalDome(px, py, CALLUS.x, CALLUS.y, CALLUS.rx, CALLUS.ry, CALLUS.angle, 0.105);
  let calCore = evalEllipticalDome(px, py, CALLUS.x, CALLUS.y, CALLUS.rx * 0.45, CALLUS.ry * 0.45, CALLUS.angle, 0.048);
  h += edgeMask * (calDome - calCore);

  // 5. Hyperreal Splinter Swelling on Upper Thenar Mound
  let splWelt = evalEllipticalDome(px, py, SPLINTER.x, SPLINTER.y, 24, 15, SPLINTER.angle, 0.075);
  let splShaft = distToSegment(px, py, SPLINTER.x1, SPLINTER.y1, SPLINTER.x2, SPLINTER.y2);
  let splRidge = splShaft.d < 6.0 ? 0.028 * Math.exp(-(splShaft.d * splShaft.d) / 9.0) : 0.0;
  h += edgeMask * (splWelt + splRidge);

  // 6. Carve Palmar & Digital Creases
  let totalCrease = 0.0;
  for (let i = 0; i < CREASES.length; i++) {
    let cr = CREASES[i];
    let cVal = evalPolylineCrease(px, py, cr.pts, cr.depth, cr.wNarrow, cr.wWide);
    if (cVal > 0) {
      totalCrease += cVal;
    }
  }
  // Soft saturation so intersecting creases stay dramatic without punching below 0
  let creaseDrop = Math.min(h * 0.72, totalCrease * edgeMask);
  h -= creaseDrop;

  // Fine organic skin micro-undulation
  let micro = (noise(px * 0.025, py * 0.025) - 0.5) * 0.012 * edgeMask;
  h = Math.max(0.0, h + micro);

  return { h, crease: totalCrease * edgeMask };
}

function computeElevationField() {
  for (let iy = 0; iy <= NY; iy++) {
    let py = iy * STEP_Y;
    for (let ix = 0; ix <= NX; ix++) {
      let px = ix * STEP_X;
      let idx = iy * (NX + 1) + ix;
      let res = evalHandPoint(px, py);
      heightGrid[idx] = res.h;
      creaseGrid[idx] = res.crease;
    }
  }

  // Compute central-difference surface gradients for top-lit shading & ridge flow
  for (let iy = 1; iy < NY; iy++) {
    for (let ix = 1; ix < NX; ix++) {
      let idx = iy * (NX + 1) + ix;
      let dhdx = (heightGrid[idx + 1] - heightGrid[idx - 1]) / (2 * STEP_X);
      let dhdy = (heightGrid[idx + (NX + 1)] - heightGrid[idx - (NX + 1)]) / (2 * STEP_Y);
      gradXGrid[idx] = dhdx;
      gradYGrid[idx] = dhdy;
    }
  }
}

function sampleField(px, py) {
  let gx = Math.max(0, Math.min(NX - 1, Math.floor(px / STEP_X)));
  let gy = Math.max(0, Math.min(NY - 1, Math.floor(py / STEP_Y)));
  let idx = gy * (NX + 1) + gx;
  return {
    h: heightGrid[idx],
    gx: gradXGrid[idx],
    gy: gradYGrid[idx],
    crease: creaseGrid[idx]
  };
}

