  background("#e6dfd1");

  brush.noStroke();

  // Large subtle parchment & cool stone washes across the sheet
  brush.fill("#ddd6c7", 28);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.2);
  brush.rect(600, 600, 1140, 1140, "center");

  // Cool slate atmospheric shadow behind lower palm & wrist
  brush.fill("#98a4b0", 16);
  brush.fillBleed(0.45, "out");
  brush.circle(610, 820, 320, 0.25);
  brush.circle(645, 1020, 220, 0.25);

  // Cool porcelain-ivory highlight wash on top-lit mounds & fingertip pads
  brush.fill("#f3f1ea", 34);
  brush.fillBleed(0.28, "out");
  brush.circle(445, 755, 115, 0.2); // Upper thenar dome
  brush.circle(565, 535, 140, 0.2); // Distal metacarpal mounts
  for (let d = 0; d < DIGITS.length; d++) {
    let pad = DIGITS[d].pad;
    brush.circle(pad.x, pad.y - 10, pad.rx * 1.1, 0.18);
  }

  // Deep cool slate-blue glazes in the palmar hollow and beneath the thenar overhang
  brush.fill("#6c7b8b", 18);
  brush.fillBleed(0.35, "out");
  brush.circle(575, 725, 105, 0.3); // Central hollow
  brush.circle(520, 910, 95, 0.3);  // Lower thenar shadow
  brush.circle(755, 865, 85, 0.3);  // Lower hypothenar shadow

  brush.noFill();

  // Subtle buff paper fiber & graphite dust grain
  brush.set("spray", "#b8b2a6", 0.35);
  for (let i = 0; i < 65; i++) {
    let x = random(40, 1160);
    let y = random(40, 1160);
    brush.line(x, y, x + random(-45, 45), y + random(-45, 45));
  }
}

// ============================================================================
// LAYER 2: TOP-LIT TONAL UNDER-SHADING
// ============================================================================

function drawTopLitUnderShading() {
  // Light from top-slightly-left: downward-facing slopes (gy > 0) receive cool graphite shading
  brush.set("2H", "#63707e", 0.22);

  for (let y = 90; y < 1165; y += 9) {
    for (let x = 120; x < 980; x += 9) {
      let jx = x + random(-3.5, 3.5);
      let jy = y + random(-3.5, 3.5);
      let f = sampleField(jx, jy);
      if (f.h <= 0.03) continue;

      // Top-lit shadow term: positive when slope faces downward (away from top light)
      let shadow = f.gy * 32.0 + f.gx * 8.0 + f.crease * 2.2;
      if (shadow > 0.12) {
        let len = map(constrain(shadow, 0.12, 0.85), 0.12, 0.85, 6, 16);
        // Stroke along contour tangent
        let ang = atan2(f.gx, -f.gy);
        let dx = cos(ang) * len * 0.5;
        let dy = sin(ang) * len * 0.5;
        if (shadow > 0.38) {
          brush.set("HB", "#3e4a57", 0.25);
        } else {
          brush.set("2H", "#6a7786", 0.20);
        }
        brush.line(jx - dx, jy - dy, jx + dx, jy + dy);
      }
    }
  }
}

// ============================================================================
// LAYER 3: MARCHING SQUARES & CONTINUOUS GRAPHITE ELEVATION CONTOURS
// ============================================================================

function extractIsoContours(iso) {
  // Edge index helper so adjacent cells share exact integer edge keys
  const hEdgeBase = 0;
  const vEdgeBase = (NX + 1) * (NY + 1) + 10;

  function getEdgeKey(ix, iy, edgeType) {
    // edgeType: 0=top, 1=right, 2=bottom, 3=left
    if (edgeType === 0) return hEdgeBase + iy * (NX + 1) + ix;
    if (edgeType === 2) return hEdgeBase + (iy + 1) * (NX + 1) + ix;
    if (edgeType === 3) return vEdgeBase + iy * (NX + 1) + ix;
    return vEdgeBase + iy * (NX + 1) + (ix + 1);
  }

  function interpEdge(ix, iy, edgeType, v00, v10, v11, v01) {
    let x0 = ix * STEP_X;
    let y0 = iy * STEP_Y;
    let x1 = (ix + 1) * STEP_X;
    let y1 = (iy + 1) * STEP_Y;
    if (edgeType === 0) {
      let t = (iso - v00) / ((v10 - v00) || 1e-6);
      return [x0 + constrain(t, 0, 1) * STEP_X, y0];
    }
    if (edgeType === 1) {
      let t = (iso - v10) / ((v11 - v10) || 1e-6);
      return [x1, y0 + constrain(t, 0, 1) * STEP_Y];
    }
    if (edgeType === 2) {
      let t = (iso - v01) / ((v11 - v01) || 1e-6);
      return [x0 + constrain(t, 0, 1) * STEP_X, y1];
    }
    let t = (iso - v00) / ((v01 - v00) || 1e-6);
    return [x0, y0 + constrain(t, 0, 1) * STEP_Y];
  }

  const MS_TABLE = [
    [],
    [[3, 2]],
    [[2, 1]],
    [[3, 1]],
    [[0, 1]],
    [[0, 3], [1, 2]],
    [[0, 2]],
    [[3, 0]],
    [[0, 3]],
    [[0, 2]],
    [[0, 1], [2, 3]],
    [[0, 1]],
    [[3, 1]],
    [[2, 1]],
    [[3, 2]],
    []
  ];

  let nodeCoords = new Map();
  let adj = new Map();

  function addSegment(kA, ptA, kB, ptB) {
    nodeCoords.set(kA, ptA);
    nodeCoords.set(kB, ptB);
    if (!adj.has(kA)) adj.set(kA, []);
    if (!adj.has(kB)) adj.set(kB, []);
    adj.get(kA).push(kB);
    adj.get(kB).push(kA);
  }

  // Crop at the wrist around y = 1172 so contours open naturally at the wrist cut
  const MAX_IY = Math.floor(1172 / STEP_Y);

  for (let iy = 1; iy < MAX_IY; iy++) {
    for (let ix = 1; ix < NX - 1; ix++) {
      let i00 = iy * (NX + 1) + ix;
      let v00 = heightGrid[i00];
      let v10 = heightGrid[i00 + 1];
      let v01 = heightGrid[i00 + (NX + 1)];
      let v11 = heightGrid[i00 + (NX + 1) + 1];

      let mask = 0;
      if (v00 >= iso) mask |= 8;
      if (v10 >= iso) mask |= 4;
      if (v11 >= iso) mask |= 2;
      if (v01 >= iso) mask |= 1;

      if (mask === 0 || mask === 15) continue;

      let pairs = MS_TABLE[mask];
      for (let p = 0; p < pairs.length; p++) {
        let eA = pairs[p][0];
        let eB = pairs[p][1];
        let kA = getEdgeKey(ix, iy, eA);
        let kB = getEdgeKey(ix, iy, eB);
        let ptA = interpEdge(ix, iy, eA, v00, v10, v11, v01);
        let ptB = interpEdge(ix, iy, eB, v00, v10, v11, v01);
        addSegment(kA, ptA, kB, ptB);
      }
    }
  }

  // Link segments into continuous polylines
  let visitedEdges = new Set();
  let polylines = [];

  function edgeId(a, b) {
    return a < b ? a + "_" + b : b + "_" + a;
  }

  function traceFrom(startKey) {
    let chain = [nodeCoords.get(startKey)];
    let curr = startKey;
    while (true) {
      let neighbors = adj.get(curr) || [];
      let nextKey = null;
      for (let n of neighbors) {
        let eid = edgeId(curr, n);
        if (!visitedEdges.has(eid)) {
          visitedEdges.add(eid);
          nextKey = n;
          break;
        }
      }
      if (nextKey === null) break;
      chain.push(nodeCoords.get(nextKey));
      curr = nextKey;
    }
    return chain;
  }

  // 1. Trace open chains starting at degree-1 endpoints (e.g. wrist crop boundary)
  for (let [k, neighbors] of adj.entries()) {
    if (neighbors.length === 1) {
      let eid = edgeId(k, neighbors[0]);
      if (!visitedEdges.has(eid)) {
        polylines.push(traceFrom(k));
      }
    }
  }

  // 2. Trace closed elevation rings
  for (let [k, neighbors] of adj.entries()) {
    for (let n of neighbors) {
      let eid = edgeId(k, n);
      if (!visitedEdges.has(eid)) {
        polylines.push(traceFrom(k));
      }
    }
  }

  return polylines;
}

function smoothPolyline(pts, iterations) {
  if (pts.length < 4) return pts;
  let isClosed = Math.hypot(pts[0][0] - pts[pts.length - 1][0], pts[0][1] - pts[pts.length - 1][1]) < 6.0;
  let curr = pts.map(p => [p[0], p[1]]);
  for (let it = 0; it < iterations; it++) {
    let next = [];
    let n = curr.length;
    for (let i = 0; i < n; i++) {
      if (!isClosed && (i === 0 || i === n - 1)) {
        next.push([curr[i][0], curr[i][1]]);
      } else {
        let pPrev = curr[(i - 1 + n) % n];
        let pCurr = curr[i];
        let pNext = curr[(i + 1) % n];
        next.push([
          0.25 * pPrev[0] + 0.5 * pCurr[0] + 0.25 * pNext[0],
          0.25 * pPrev[1] + 0.5 * pCurr[1] + 0.25 * pNext[1]
        ]);
      }
    }
    curr = next;
  }
  return curr;
}

function drawElevationContours() {
  const NUM_LEVELS = 58;
  const MIN_ISO = 0.038;
  const MAX_ISO = 0.965;

  for (let lvl = 0; lvl < NUM_LEVELS; lvl++) {
    let iso = map(lvl, 0, NUM_LEVELS - 1, MIN_ISO, MAX_ISO);
    // Every 5th contour ring is a heavier index line
    let isIndex = (lvl % 5 === 0);

    let rawChains = extractIsoContours(iso);

    for (let c = 0; c < rawChains.length; c++) {
      let chain = rawChains[c];
      if (chain.length < 4) continue;

      let smoothed = smoothPolyline(chain, 2);

      // Subsample every 2nd vertex (~5-6px spacing) for crisp spline rendering
      let pts = [];
      for (let i = 0; i < smoothed.length; i += 2) {
        pts.push(smoothed[i]);
      }
      if (pts.length < 3) continue;
      // Ensure last point is preserved
      let lastOrig = smoothed[smoothed.length - 1];
      let lastPt = pts[pts.length - 1];
      if (Math.hypot(lastOrig[0] - lastPt[0], lastOrig[1] - lastPt[1]) > 1.5) {
        pts.push(lastOrig);
      }

      // Draw in overlapping continuous sub-strokes of 14 vertices so graphite tone
      // and weight respond dynamically to top-lighting and deep crease crowding
      const CHUNK = 14;
      for (let start = 0; start < pts.length - 1; start += CHUNK - 1) {
        let end = Math.min(pts.length, start + CHUNK);
        let sub = pts.slice(start, end);
        if (sub.length < 2) continue;

        let mid = sub[Math.floor(sub.length / 2)];
        let f = sampleField(mid[0], mid[1]);

        // Top-lit illumination: light comes from top-slightly-left (0, -1)
        // Downward-facing slopes (gy > 0) and deep creases receive darker, richer graphite
        let shade = constrain(0.46 + f.gy * 18.0 + f.gx * 4.5 + f.crease * 2.4, 0.0, 1.0);

        if (isIndex) {
          // Heavier Index Contour Line (every 5th ring)
          let col = shade > 0.62 ? "#141b23" : (shade > 0.36 ? "#27323f" : "#424f5e");
          let w = map(shade, 0, 1, 0.44, 0.72);
          brush.set("HB", col, w);
        } else {
          // Standard Contour Ring
          let col, bName, w;
          if (shade > 0.68) {
            bName = "HB";
            col = "#222b35";
            w = map(shade, 0.68, 1.0, 0.30, 0.42);
          } else if (shade > 0.36) {
            bName = "2H";
            col = "#465362";
            w = map(shade, 0.36, 0.68, 0.24, 0.32);
          } else {
            bName = "2H";
            col = "#6d7b8b";
            w = map(shade, 0.0, 0.36, 0.18, 0.25);
          }
          brush.set(bName, col, w);
        }

        if (sub.length >= 3) {
          brush.spline(sub, 0.45);
        } else {
          brush.line(sub[0][0], sub[0][1], sub[1][0], sub[1][1]);
        }
      }
    }
  }
}

// ============================================================================
// LAYER 4A: HYPERREAL DERMAL FRICTION RIDGES (FINGERTIP WHORLS & PALM CREASES)
// ============================================================================

function drawDermalRidges() {
  // 1. Dermatoglyphic Whorl & Loop Patterns on all 5 Fingertip Pads
  for (let d = 0; d < DIGITS.length; d++) {
    let dig = DIGITS[d];
    let pad = dig.pad;
    let rad = pad.angle * Math.PI / 180;
    let cosA = Math.cos(rad);
    let sinA = Math.sin(rad);

    // Draw concentric / spiraling dermal friction ridges with sweat-pore interruptions
    let numRings = 24;
    for (let rIdx = 2; rIdx <= numRings; rIdx++) {
      let normR = rIdx / numRings;
      let rx = normR * pad.rx * 1.18;
      let ry = normR * pad.ry * 1.18;

      // Break each dermal loop into pore-interrupted micro-arcs
      let steps = Math.floor(22 + normR * 36);
      let arcPts = [];
      for (let s = 0; s <= steps; s++) {
        let theta = (s / steps) * Math.PI * 2;
        // Authentic dermatoglyphic arch/whorl distortion
        let pinch = 1.0 + 0.18 * Math.sin(theta) - 0.10 * Math.cos(2 * theta);
        let swirl = 0.12 * (1.0 - normR) * Math.sin(theta * 2 + d);
        let lx = Math.cos(theta + swirl) * rx * pinch;
        let ly = Math.sin(theta + swirl) * ry;

        let wx = pad.x + lx * cosA - ly * sinA;
        let wy = pad.y + lx * sinA + ly * cosA;

        let f = sampleField(wx, wy);
        if (f.h > 0.34) {
          arcPts.push([wx, wy]);
        }

        // Sweat pore gap or end of arc
        if ((s % 7 === 0 && arcPts.length >= 3) || s === steps || f.h <= 0.34) {
          if (arcPts.length >= 3) {
            let mid = arcPts[Math.floor(arcPts.length / 2)];
            let fm = sampleField(mid[0], mid[1]);
            let shade = constrain(0.45 + fm.gy * 16.0, 0.1, 1.0);
            let col = shade > 0.55 ? "#26303c" : "#4e5c6b";
            brush.set("dermal", col, map(shade, 0.1, 1.0, 0.55, 0.90));
            brush.spline(arcPts, 0.4);
          }
          arcPts = [];
        }
      }
    }
  }

  // 2. Dense Palmar Friction Ridges emerging where contour lines crowd tightly
  //    (along the major creases, interdigital mounts, and upper thenar dome)
  for (let y = 180; y < 1060; y += 3.2) {
    for (let x = 160; x < 920; x += 3.2) {
      let jx = x + random(-1.1, 1.1);
      let jy = y + random(-1.1, 1.1);
      let f = sampleField(jx, jy);
      if (f.h < 0.18) continue;

      let gradMag = Math.hypot(f.gx, f.gy);
      // Density metric: high where slope is steep or inside deep creases
      let density = gradMag * 52.0 + f.crease * 3.8;
      if (density < 0.42) continue;
      if (random() > constrain((density - 0.35) * 0.95, 0.15, 0.82)) continue;

      // Avoid drawing generic ridges right over the splinter shaft core
      if (Math.hypot(jx - SPLINTER.x, jy - SPLINTER.y) < 16) continue;

      // Trace a short dermal ridge stream across the local palmar flow field
      let rPts = [[jx, jy]];
      let cx = jx;
      let cy = jy;
      let stepLen = 2.8;
      let nSteps = Math.floor(random(4, 8));

      for (let k = 0; k < nSteps; k++) {
        // Palmar dermal ridges sweep obliquely across the palm and curve into creases
        let baseAng = -25 + 38 * noise(cx * 0.0045, cy * 0.0045);
        let fCurr = sampleField(cx, cy);
        let contourAng = atan2(fCurr.gx, -fCurr.gy);
        let mixAng = lerp(baseAng, contourAng, constrain(fCurr.crease * 2.5, 0.25, 0.85));

        // Deflect ridges around the callus rim
        let dCal = Math.hypot(cx - CALLUS.x, cy - CALLUS.y);
        if (dCal < 36 && dCal > 10) {
          let tangCal = atan2(cy - CALLUS.y, cx - CALLUS.x) + 90;
          mixAng = lerp(mixAng, tangCal, 0.55);
        }

        cx += cos(mixAng) * stepLen;
        cy += sin(mixAng) * stepLen;
        if (sampleField(cx, cy).h < 0.12) break;
        rPts.push([cx, cy]);
      }

      if (rPts.length >= 3) {
        let shade = constrain(0.45 + f.gy * 16.0 + f.crease * 2.2, 0.15, 1.0);
        let col = shade > 0.62 ? "#1e2731" : (shade > 0.38 ? "#3a4654" : "#5c6a79");
        brush.set("dermal", col, map(shade, 0.15, 1.0, 0.50, 0.88));
        brush.spline(rPts, 0.35);
      }
    }
  }
}

// ============================================================================
// LAYER 4B: HYPERREAL CALLUS (RING FINGER METACARPAL MOUNT)
// ============================================================================

function drawHyperrealCallus() {
  let cx = CALLUS.x;
  let cy = CALLUS.y;
  let rx = CALLUS.rx;
  let ry = CALLUS.ry;
  let rad = CALLUS.angle * Math.PI / 180;
  let cosA = Math.cos(rad);
  let sinA = Math.sin(rad);

  // 1. Subtle thickened horn (stratum corneum) cool-ochre & slate wash
  brush.noStroke();
  brush.fill("#cfc6b2", 42);
  brush.fillBleed(0.18, "out");
  brush.circle(cx, cy, rx * 0.95, 0.22);

  brush.fill("#586472", 24);
  brush.fillBleed(0.15, "in");
  brush.circle(cx + 2, cy + 4, rx * 0.55, 0.25);
  brush.noFill();

  // 2. Concentric flaky hyperkeratotic skin rings & peeling epidermal scales
  for (let ring = 0; ring < 16; ring++) {
    let norm = map(ring, 0, 15, 0.22, 1.22);
    let nSegs = 8;
    for (let s = 0; s < nSegs; s++) {
      if (random() < 0.22) continue;
      let aStart = (s / nSegs) * 360 + random(-8, 8);
      let aEnd = aStart + (360 / nSegs) * random(0.65, 0.92);
      let pts = [];
      for (let a = aStart; a <= aEnd; a += 8) {
        let ar = a * Math.PI / 180;
        let jag = 1.0 + 0.08 * (noise(ring * 2.1, a * 0.08) - 0.5);
        let lx = Math.cos(ar) * rx * norm * jag;
        let ly = Math.sin(ar) * ry * norm * jag;
        pts.push([
          cx + lx * cosA - ly * sinA,
          cy + lx * sinA + ly * cosA
        ]);
      }
      if (pts.length >= 3) {
        let isShadow = sin((aStart + aEnd) * 0.5) > 0;
        let col = isShadow ? "#1d252f" : (norm > 0.85 ? "#384452" : "#525f6e");
        let w = isShadow ? 0.85 : 0.62;
        brush.set("dermal", col, w);
        brush.spline(pts, 0.35);
      }
    }
  }

  // 3. Radial stress micro-fissures around the thickened peripheral rim
  for (let i = 0; i < 22; i++) {
    let ang = i * (360 / 22) + random(-6, 6);
    let ar = ang * Math.PI / 180;
    let rIn = random(0.58, 0.78);
    let rOut = random(1.02, 1.28);
    let lx1 = Math.cos(ar) * rx * rIn;
    let ly1 = Math.sin(ar) * ry * rIn;
    let lx2 = Math.cos(ar + random(-0.08, 0.08)) * rx * rOut;
    let ly2 = Math.sin(ar + random(-0.08, 0.08)) * ry * rOut;

    let x1 = cx + lx1 * cosA - ly1 * sinA;
    let y1 = cy + lx1 * sinA + ly1 * cosA;
    let x2 = cx + lx2 * cosA - ly2 * sinA;
    let y2 = cy + lx2 * sinA + ly2 * cosA;

    brush.set("dermal", "#232c37", random(0.55, 0.85));
    brush.line(x1, y1, x2, y2);
  }

  // 4. Translucent dry-skin highlight flecks on the top-lit callus ridge
  brush.set("2H", "#f2eee4", 0.28);
  for (let i = 0; i < 14; i++) {
    let a = random(-155, -25) * Math.PI / 180;
    let rr = random(0.45, 0.92);
    let lx = Math.cos(a) * rx * rr;
    let ly = Math.sin(a) * ry * rr;
    let px = cx + lx * cosA - ly * sinA;
    let py = cy + lx * sinA + ly * cosA;
    brush.line(px - 2.5, py - 1, px + 2.5, py + 1);
  }
}

// ============================================================================
// LAYER 4C: HYPERREAL SPLINTER (EMBEDDED ON UPPER THENAR MOUND)
// ============================================================================

function drawHyperrealSplinter() {
  let x1 = SPLINTER.x1;
  let y1 = SPLINTER.y1;
  let x2 = SPLINTER.x2;
  let y2 = SPLINTER.y2;
  let vx = x2 - x1;
  let vy = y2 - y1;
  let len = Math.hypot(vx, vy);
  let ux = vx / len;
  let uy = vy / len;
  let nx = -uy;
  let ny = ux;

  // 1. Subcutaneous inflammatory halo (cool rose-violet erythema beneath the skin)
  brush.noStroke();
  brush.fill("#8e454d", 24);
  brush.fillBleed(0.32, "out");
  brush.circle(SPLINTER.x, SPLINTER.y, 18, 0.25);

  brush.fill("#68242d", 32);
  brush.fillBleed(0.20, "out");
  brush.circle(x1 + ux * 4, y1 + uy * 4, 8, 0.2);
  brush.noFill();

  // 2. Submerged distal shaft of the splinter (muted cool brown-slate under translucent skin)
  for (let s = -1.2; s <= 1.2; s += 0.6) {
    let wFactor = 1.0 - Math.abs(s) * 0.45;
    let sx1 = x1 + ux * 7 + nx * s * 0.9;
    let sy1 = y1 + uy * 7 + ny * s * 0.9;
    let sx2 = x2 + nx * s * 0.15;
    let sy2 = y2 + ny * s * 0.15;
    brush.set("dermal", "#494144", 0.78 * wFactor);
    brush.line(sx1, sy1, sx2, sy2);
  }

  // 3. Exposed / Entry point of the wood sliver + pinpoint of dark dried blood
  for (let s = -1.4; s <= 1.4; s += 0.45) {
    let sx0 = x1 - ux * 3.5 + nx * s * 0.55;
    let sy0 = y1 - uy * 3.5 + ny * s * 0.55;
    let sx1 = x1 + ux * 8.5 + nx * s * 1.05;
    let sy1 = y1 + uy * 8.5 + ny * s * 1.05;
    brush.set("dermal", "#181212", 0.95);
    brush.line(sx0, sy0, sx1, sy1);
  }

  // Coagulated dark crimson-violet blood speck at puncture site
  brush.set("rotring", "#48121a", 0.55);
  for (let i = 0; i < 8; i++) {
    let bx = x1 + ux * random(-1, 4) + nx * random(-2.5, 2.5);
    let by = y1 + uy * random(-1, 4) + ny * random(-2.5, 2.5);
    brush.line(bx, by, bx + ux * 2.2, by + uy * 2.2);
  }

  // 4. Torn translucent epidermal V-flap & intact dermal ridges arching OVER the submerged shaft
  //    (This creates the hyperreal illusion that the splinter is truly *under* the skin!)
  brush.set("2H", "#f0ebe0", 0.34);
  let collarPts1 = [
    [x1 + ux * 2 - nx * 5.5, y1 + uy * 2 - ny * 5.5],
    [x1 - ux * 1.5 - nx * 2.0, y1 - uy * 1.5 - ny * 2.0],
    [x1 + ux * 2 + nx * 5.5, y1 + uy * 2 + ny * 5.5]
  ];
  brush.spline(collarPts1, 0.4);

  // Intact dermal friction ridges crossing over the submerged portion of the splinter
  for (let t = 5.5; t <= len + 3.0; t += 2.6) {
    let cx = x1 + ux * t;
    let cy = y1 + uy * t;
    let bulge = t < len ? 2.4 * Math.sin((t / len) * Math.PI) : 0.4;
    let ridgePts = [];
    for (let s = -14; s <= 14; s += 3.5) {
      let lift = Math.exp(-(s * s) / 28.0) * bulge;
      ridgePts.push([
        cx + nx * s - ux * lift,
        cy + ny * s - uy * lift
      ]);
    }
    // Dark ridge shadow line
    brush.set("dermal", "#26303c", 0.72);
    brush.spline(ridgePts, 0.45);

    // Subtle top-lit epidermal ridge highlight right over the shaft
    if (t > 7 && t < len - 1) {
      brush.set("2H", "#ebe6da", 0.22);
      brush.line(
        cx - nx * 3.5 - ux * (bulge + 0.6),
        cy - ny * 3.5 - uy * (bulge + 0.6),
        cx + nx * 3.5 - ux * (bulge + 0.6),
        cy + ny * 3.5 - uy * (bulge + 0.6)
      );
    }
  }
}

// ============================================================================
// LAYER 5: FAINT RED PENCIL SURVEY TICKS & NON-LEGIBLE ELEVATION NUMERALS
// ============================================================================

function drawAbstractGlyph(x, y, scaleVal, col) {
  // Draws fragmented, non-legible cartographic elevation numerals & survey shorthand
  // using delicate red pencil strokes so no literal readable digits form
  brush.set("survey_red", col, random(0.55, 0.85));
  let type = Math.floor(random(5));
  let s = scaleVal;

  if (type === 0) {
    // Broken loop + oblique tick (evokes partial '6' or '0' with datum slash)
    brush.arc(x, y, s * 0.55, 40, 295);
    brush.line(x - s * 0.4, y + s * 0.6, x + s * 0.5, y - s * 0.7);
  } else if (type === 1) {
    // Open angular surveyor's hook (evokes partial '4' or '7' without closing)
    brush.spline([
      [x + s * 0.3, y - s * 0.6],
      [x - s * 0.5, y + s * 0.1],
      [x + s * 0.4, y + s * 0.05]
    ], 0.2);
    brush.line(x + s * 0.1, y - s * 0.3, x + s * 0.05, y + s * 0.65);
  } else if (type === 2) {
    // Double incomplete inflection curve (evokes faded '3' or '8' fragment)
    brush.spline([
      [x - s * 0.3, y - s * 0.55],
      [x + s * 0.35, y - s * 0.25],
      [x - s * 0.15, y + s * 0.05],
      [x + s * 0.4, y + s * 0.45],
      [x - s * 0.25, y + s * 0.6]
    ], 0.55);
  } else if (type === 3) {
    // Survey prime / decimal / overbar notation
    brush.line(x - s * 0.5, y - s * 0.5, x + s * 0.5, y - s * 0.5);
    brush.arc(x + s * 0.1, y + s * 0.15, s * 0.4, -30, 190);
    brush.line(x - s * 0.45, y + s * 0.5, x - s * 0.35, y + s * 0.35);
  } else {
    // Stadia stem with dual hash ticks
    brush.line(x, y - s * 0.65, x - s * 0.15, y + s * 0.65);
    brush.line(x - s * 0.4, y - s * 0.15, x + s * 0.35, y - s * 0.25);
    brush.line(x + s * 0.45, y + s * 0.35, x + s * 0.6, y + s * 0.15);
  }
}

function drawSurveyNumeralCluster(x, y, col) {
  let count = Math.floor(random(2, 5));
  let spacing = random(8.5, 11.0);
  for (let i = 0; i < count; i++) {
    drawAbstractGlyph(x + i * spacing, y + random(-1.5, 1.5), random(6.5, 8.5), col);
  }
  // Faint strike-through or baseline whisper
  if (random() < 0.65) {
    brush.set("cpencil", col, 0.18);
    brush.line(x - 4, y + 6, x + count * spacing + 3, y + 5.5);
  }
}

function drawSurveyCrosshair(x, y, sz, col) {
  brush.set("cpencil", col, 0.22);
  brush.line(x - sz, y, x + sz, y);
  brush.line(x, y - sz, x, y + sz);
  if (random() < 0.5) {
    brush.circle(x, y, sz * 0.42, 0.15);
  }
}

function drawSurveyMarginalia() {
  const RED_MAIN = "#a6423e";
  const RED_FAINT = "#b95c58";
  const RED_DEEP = "#8c3330";

  // 1. Left Margin Survey Axis & Graduated Stadia Ticks
  let leftX = 78;
  brush.set("cpencil", RED_FAINT, 0.18);
  brush.line(leftX, 110, leftX, 460);
  brush.line(leftX, 680, leftX, 1080);

  for (let y = 120; y <= 1080; y += 24) {
    if (y > 470 && y < 670) continue; // Break gracefully near thumb tip
    let isMajor = (y % 120 === 0);
    let tickW = isMajor ? 11 : 5;
    brush.set("cpencil", isMajor ? RED_MAIN : RED_FAINT, isMajor ? 0.26 : 0.18);
    brush.line(leftX - tickW * 0.4, y, leftX + tickW * 0.6, y);
    if (isMajor) {
      drawSurveyNumeralCluster(leftX + 14, y - 2, RED_MAIN);
    }
  }

  // 2. Right Margin Survey Axis & Graduated Ticks
  let rightX = 1112;
  brush.set("cpencil", RED_FAINT, 0.18);
  brush.line(rightX, 130, rightX, 1060);

  for (let y = 140; y <= 1060; y += 24) {
    let isMajor = (y % 120 === 20);
    let tickW = isMajor ? 11 : 5;
    brush.set("cpencil", isMajor ? RED_MAIN : RED_FAINT, isMajor ? 0.26 : 0.18);
    brush.line(rightX - tickW * 0.6, y, rightX + tickW * 0.4, y);
    if (isMajor) {
      drawSurveyNumeralCluster(rightX - 52, y - 2, RED_MAIN);
    }
  }

  // 3. Top Margin Horizontal Datum Bar & Ticks
  let topY = 58;
  brush.set("cpencil", RED_FAINT, 0.18);
  brush.line(140, topY, 470, topY);
  brush.line(630, topY, 1050, topY);

  for (let x = 160; x <= 1040; x += 30) {
    if (x > 475 && x < 625) continue; // Break near middle fingertip
    let isMajor = (x % 150 === 10);
    let tickH = isMajor ? 10 : 4.5;
    brush.set("cpencil", isMajor ? RED_MAIN : RED_FAINT, isMajor ? 0.25 : 0.17);
    brush.line(x, topY - tickH * 0.4, x, topY + tickH * 0.6);
    if (isMajor) {
      drawSurveyNumeralCluster(x + 5, topY + 12, RED_FAINT);
    }
  }

  // 4. Bottom Margin Datum Ticks Flanking the Cropped Wrist
  let botY = 1142;
  brush.set("cpencil", RED_FAINT, 0.18);
  brush.line(150, botY, 465, botY);
  brush.line(795, botY, 1060, botY);

  for (let x = 160; x <= 1050; x += 30) {
    if (x > 465 && x < 795) continue;
    let isMajor = (x % 120 === 40);
    let tickH = isMajor ? 10 : 4.5;
    brush.set("cpencil", isMajor ? RED_MAIN : RED_FAINT, isMajor ? 0.25 : 0.17);
    brush.line(x, botY - tickH * 0.6, x, botY + tickH * 0.4);
    if (isMajor) {
      drawSurveyNumeralCluster(x - 12, botY - 16, RED_MAIN);
    }
  }

  // 5. Peripheral Survey Bench-Marks, Crosshairs & Index Leader Ticks near the Hand
  const STATIONS = [
    // Near thumb tip & outer radial margin
    { x: 118, y: 518, tx: 158, ty: 522 },
    // Near index fingertip
    { x: 262, y: 146, tx: 332, ty: 152 },
    // Near ring/pinky upper margin
    { x: 848, y: 175, tx: 758, ty: 162 },
    // Near pinky tip
    { x: 1005, y: 282, tx: 928, ty: 284 },
    // Near outer hypothenar slope
    { x: 912, y: 785, tx: 812, ty: 785 },
    // Near lower radial wrist cut
    { x: 432, y: 1038, tx: 515, ty: 1018 },
    // Near lower ulnar wrist cut
    { x: 825, y: 1022, tx: 728, ty: 1005 },
    // Near thumb web / index mount
    { x: 258, y: 412, tx: 378, ty: 418 }
  ];

  for (let i = 0; i < STATIONS.length; i++) {
    let st = STATIONS[i];
    drawSurveyCrosshair(st.x, st.y, 7.5, RED_MAIN);

    // Faint leader line with tick toward the hand contour
    brush.set("cpencil", RED_FAINT, 0.17);
    brush.line(st.x, st.y, st.tx, st.ty);
    // Tiny perpendicular tick at the contour end
    let dx = st.tx - st.x;
    let dy = st.ty - st.y;
    let l = Math.hypot(dx, dy) || 1;
    let nx = -dy / l * 4.5;
    let ny = dx / l * 4.5;
    brush.set("cpencil", RED_DEEP, 0.24);
    brush.line(st.tx - nx, st.ty - ny, st.tx + nx, st.ty + ny);

    // Abstracted elevation numeral cluster beside station
    let offX = st.x < 500 ? -42 : 12;
    drawSurveyNumeralCluster(st.x + offX, st.y - 10, RED_MAIN);
  }

  // 6. Subtle Triangular Bench-Mark Symbols in the Negative Space Corners
  const BENCHMARKS = [
    [185, 245],
    [965, 495],
    [235, 885],
    [955, 915]
  ];
  for (let b = 0; b < BENCHMARKS.length; b++) {
    let bx = BENCHMARKS[b][0];
    let by = BENCHMARKS[b][1];
    let r = 6.5;
    brush.set("cpencil", RED_MAIN, 0.24);
    brush.line(bx, by - r, bx - r * 0.86, by + r * 0.6);
    brush.line(bx - r * 0.86, by + r * 0.6, bx + r * 0.86, by + r * 0.6);
    brush.line(bx + r * 0.86, by + r * 0.6, bx, by - r);
    drawSurveyNumeralCluster(bx + 11, by + 2, RED_FAINT);
  }
}
